/* works-v2.js — 自動生成: build_data.py（正本= data-work/final-*.json）。直接編集禁止 */
const WORKDATA_V2={"version":"2026-10-13","categories":[{"id":"feeding","name":"飼養管理"},{"id":"hygiene","name":"衛生管理"},{"id":"breeding","name":"繁殖管理"},{"id":"farrowing","name":"分娩管理"},{"id":"facility","name":"施設管理"},{"id":"record","name":"記録管理"},{"id":"shipping","name":"出荷管理"}],"works":[{"id":"feeding-daily","category":"feeding","no":"No.11","name":"給餌","purposeShort":"豚の発育と体調を安定させ、全頭がムラなく食べ、ムダな飼料を出さない","gyomu":"11","aspects":[{"id":"amount","name":"給与量の管理と個体・季節調整","kanten":"決められた給与量（不断給餌ではエサ箱の出量）を守りつつ、豚の状態や季節に応じて過不足なく調整できるか。","levels":["決められた量を守らず目分量で与え、豚の状態や季節の違いを考えずに一律に給餌する。","指示があれば決められた量を与えられるが、季節や個体差に応じた調整は他者まかせで、過不足が出やすい。","指示があれば決められた量を守り、暑い時期や豚の状態に応じてある程度の増減ができる。","指示がなくても食い込みや季節を見て量を細かく加減し、食下量の低下があれば原因を探って対応する。","給与量が発育・体調に与える影響を理解し、食い込み・季節・ステージに合わせて最適化し、調整の考え方を新人に指導できる。"],"name_en":"Feed amount control with individual and seasonal adjustment","name_vi":"Quản lý lượng thức ăn và điều chỉnh theo từng con, theo mùa","name_id":"Pengelolaan jumlah pakan dan penyesuaian per individu dan musim","kanten_en":"Can they follow the prescribed feed amounts (or, with ad-lib feeding, the feeder output) while adjusting appropriately for pig condition and season, without excess or shortage?","kanten_vi":"Có giữ đúng lượng thức ăn quy định (với cho ăn tự do thì là lượng thức ăn ra ở máng), đồng thời điều chỉnh vừa đủ theo tình trạng lợn và theo mùa không.","kanten_id":"Apakah bisa mengikuti jumlah pakan yang ditentukan (pada pemberian ad libitum, jumlah pakan yang keluar di palung), dan menyesuaikannya dengan tepat sesuai kondisi babi dan musim.","levels_en":["Ignores the prescribed amounts and feeds by eye, giving the same amount to all pigs regardless of condition or season.","With guidance, can give the prescribed amount, but leaves seasonal and individual adjustments to others, often causing excess or shortage.","With guidance, follows the prescribed amounts and can make some increases or decreases according to hot weather or pig condition.","Independently fine-tunes amounts based on feed intake and season, and investigates the cause when feed intake drops.","Understands how feed amounts affect growth and condition, optimizes them by intake, season, and stage, and can teach new staff the principles of adjustment."],"levels_vi":["Không giữ lượng quy định, cho ăn theo ước lượng bằng mắt, cho ăn giống nhau mà không nghĩ đến tình trạng lợn hay mùa.","Nếu có chỉ dẫn thì cho ăn đúng lượng quy định, nhưng việc điều chỉnh theo mùa hay từng con thì phó mặc cho người khác, dễ bị thừa hoặc thiếu.","Nếu có chỉ dẫn thì giữ đúng lượng quy định, và có thể tăng giảm phần nào theo mùa nóng hoặc tình trạng lợn.","Không cần chỉ dẫn cũng nhìn mức ăn và mùa để điều chỉnh lượng một cách tỉ mỉ; nếu lợn ăn ít đi thì tìm nguyên nhân và xử lý.","Hiểu lượng thức ăn ảnh hưởng đến sự phát triển và thể lực của lợn, tối ưu theo mức ăn, mùa và giai đoạn, và có thể hướng dẫn người mới cách điều chỉnh."],"levels_id":["Tidak mengikuti jumlah yang ditentukan, memberi pakan dengan kira-kira saja, dan memberi jumlah yang sama tanpa melihat kondisi babi atau musim.","Jika ada instruksi bisa memberi jumlah yang ditentukan, tetapi penyesuaian menurut musim atau perbedaan individu diserahkan ke orang lain, sehingga sering kelebihan atau kekurangan.","Jika ada instruksi, bisa mengikuti jumlah yang ditentukan dan bisa menambah atau mengurangi sedikit sesuai musim panas atau kondisi babi.","Tanpa instruksi pun, bisa mengatur jumlah pakan dengan teliti sambil melihat nafsu makan dan musim, dan jika konsumsi pakan turun, mencari penyebabnya lalu menanganinya.","Memahami pengaruh jumlah pakan terhadap pertumbuhan dan kondisi babi, mengoptimalkannya sesuai nafsu makan, musim, dan tahap produksi, serta bisa mengajari karyawan baru cara berpikir penyesuaiannya."]},{"id":"residue-water","name":"残餌と給水の確認","kanten":"残餌の有無・変質と、給水器の流量を毎回確認し、飲水不足や飼料ロスを防げるか。","levels":["残餌や給水器の不具合を確認せず、飼料ロスや飲水不足を放置する。高温期の変質・カビにも気づかない。","指示があれば残餌を片づけるが、給水器の流量確認や槽内飼料の傷みの点検に漏れが多い。","指示があれば残餌を確認して片づけ、給水器から水が出ているかを確かめられる。","指示がなくても毎回残餌の量と傷みを確かめ、給水器の流量を点検し、飲水不足による食い込み低下を防ぐ。","残餌量・飲水量を給餌量の見直しに結びつけ、高温期の変質対策まで判断し、確認の要点を新人に指導できる。"],"name_en":"Checking leftover feed and water supply","name_vi":"Kiểm tra thức ăn thừa và nước uống","name_id":"Pemeriksaan sisa pakan dan air minum","kanten_en":"Can they check for leftover feed, spoilage, and drinker flow rate at every feeding to prevent water shortage and feed loss?","kanten_vi":"Mỗi lần có kiểm tra thức ăn thừa, thức ăn bị hỏng và lưu lượng núm uống nước, để tránh lợn thiếu nước và lãng phí thức ăn không.","kanten_id":"Apakah setiap kali memeriksa ada tidaknya sisa pakan dan kerusakannya serta aliran air di nipple, sehingga bisa mencegah kekurangan air minum dan pemborosan pakan.","levels_en":["Does not check leftover feed or drinker problems, leaving feed loss and water shortage unaddressed; fails to notice spoilage or mold in hot weather.","With guidance, clears leftover feed, but often misses checking drinker flow rates and spoiled feed in the trough.","With guidance, checks and clears leftover feed and can confirm that water comes out of the drinkers.","Independently checks the amount and condition of leftover feed at every feeding, inspects drinker flow rates, and prevents reduced feed intake caused by water shortage.","Links leftover feed and water intake to feed amount reviews, makes decisions on spoilage countermeasures in hot weather, and can teach new staff the key checkpoints."],"levels_vi":["Không kiểm tra thức ăn thừa hay núm uống nước hỏng, bỏ mặc lãng phí thức ăn và thiếu nước. Mùa nóng thức ăn hỏng, mốc cũng không nhận ra.","Nếu có chỉ dẫn thì dọn thức ăn thừa, nhưng hay bỏ sót việc kiểm tra lưu lượng nước và thức ăn hỏng trong máng.","Nếu có chỉ dẫn thì kiểm tra và dọn thức ăn thừa, xác nhận được nước có chảy ra từ núm uống không.","Không cần chỉ dẫn cũng kiểm tra lượng và độ hỏng của thức ăn thừa mỗi lần, kiểm tra lưu lượng núm uống, phòng lợn ăn ít do thiếu nước.","Biết dùng lượng thức ăn thừa và lượng nước uống để xem lại lượng cho ăn, biết cách chống thức ăn hỏng mùa nóng, và có thể hướng dẫn người mới các điểm cần kiểm tra."],"levels_id":["Tidak memeriksa sisa pakan atau kerusakan nipple air minum, membiarkan pakan terbuang dan babi kekurangan air. Tidak sadar pakan rusak atau berjamur di musim panas.","Jika ada instruksi bisa membereskan sisa pakan, tetapi sering lupa memeriksa aliran air nipple dan kerusakan pakan di dalam tempat pakan.","Jika ada instruksi, bisa memeriksa dan membereskan sisa pakan, serta memastikan air keluar dari nipple air minum.","Tanpa instruksi pun, setiap kali memeriksa jumlah dan kerusakan sisa pakan, memeriksa aliran air nipple, dan mencegah turunnya nafsu makan karena kekurangan air minum.","Menghubungkan jumlah sisa pakan dan konsumsi air dengan peninjauan jumlah pakan, bisa memutuskan langkah pencegahan pakan rusak di musim panas, dan bisa mengajari karyawan baru poin-poin pemeriksaannya."]},{"id":"feed-label","name":"飼料の種類・状態の確認と報告","kanten":"袋やタンクのラベルで飼料の種類を毎回確かめ、カビ・固まり・変なにおいと残量を点検して報告できるか。","levels":["ラベルを見ずに給餌し、カビや変なにおいのする飼料にも気づかず与えてしまう。","指示があればラベルを見るが、タンク内の変質や残量の点検に漏れが多い。","指示があればラベルで種類を確かめ、カビ・固まり・においの異常を見つけたら使わずにおける。","指示がなくても毎回ラベルと飼料の状態・タンク残量を確かめ、異常や残量不足をすぐ上司に報告する。","飼料の間違い・変質が発育不良や下痢につながることを理解し、確認の要点を新人に指導できる。"],"name_en":"Checking and reporting feed type and condition","name_vi":"Kiểm tra và báo cáo loại và tình trạng thức ăn","name_id":"Memeriksa dan melaporkan jenis dan kondisi pakan","kanten_en":"Can they check the feed type on the bag or tank label every time, inspect for mold, clumps, and odd smells as well as the remaining amount, and report?","kanten_vi":"Có kiểm tra loại thức ăn bằng nhãn trên bao hoặc bồn chứa mỗi lần, kiểm tra nấm mốc, vón cục, mùi lạ và lượng còn lại, rồi báo cáo không.","kanten_id":"Apakah setiap kali memastikan jenis pakan dari label karung atau tangki, memeriksa jamur, gumpalan, bau aneh, dan sisa jumlahnya, lalu melaporkannya.","levels_en":["Feeds without looking at the label, and gives moldy or odd-smelling feed without noticing.","Looks at the label when instructed, but often misses spoilage inside the tank and remaining-amount checks.","With guidance, checks the feed type on the label, and can set aside feed with mold, clumps, or odd smells instead of using it.","Independently checks the label, feed condition, and tank level every time, and immediately reports abnormalities or low stock to the supervisor.","Understands that wrong or spoiled feed leads to poor growth and diarrhea, and can teach new staff the key checkpoints."],"levels_vi":["Cho ăn mà không nhìn nhãn, không nhận ra cả thức ăn bị mốc hay có mùi lạ mà vẫn cho ăn.","Nếu có chỉ dẫn thì nhìn nhãn, nhưng thường bỏ sót việc kiểm tra thức ăn hỏng trong bồn và lượng còn lại.","Nếu có chỉ dẫn thì kiểm tra loại thức ăn bằng nhãn, và nếu thấy bất thường như nấm mốc, vón cục, mùi lạ thì để riêng không dùng.","Không cần chỉ dẫn cũng kiểm tra nhãn, tình trạng thức ăn và lượng còn lại trong bồn mỗi lần, báo ngay cho cấp trên khi có bất thường hoặc sắp hết.","Hiểu việc nhầm thức ăn hay thức ăn hỏng dẫn đến chậm lớn và tiêu chảy, và có thể hướng dẫn người mới các điểm cần kiểm tra."],"levels_id":["Memberi pakan tanpa melihat label, dan tidak sadar memberi pakan yang berjamur atau berbau aneh.","Jika ada instruksi melihat label, tetapi sering melewatkan pemeriksaan pakan rusak di dalam tangki dan sisa jumlahnya.","Jika ada instruksi, bisa memastikan jenis pakan dari label, dan jika menemukan jamur, gumpalan, atau bau aneh, bisa menyisihkannya tanpa memakainya.","Tanpa instruksi pun, setiap kali memeriksa label, kondisi pakan, dan sisa isi tangki, lalu segera melaporkan kelainan atau kekurangan stok ke atasan.","Memahami bahwa pakan yang salah atau rusak menyebabkan pertumbuhan buruk dan diare, dan bisa mengajari karyawan baru poin-poin pemeriksaannya."]},{"id":"intake-watch","name":"給餌後の食い込み観察","kanten":"配り終えた後5〜10分は食い込みを観察し、食べに来ない豚を耳標番号または豚房番号・マーキングで特定して報告できるか。","levels":["配り終えるとすぐ立ち去り、食べに来ない豚や動きのおかしい豚がいても気づかない。","指示されれば観察するが、時間が短く、個体の特定やメモをしないことが多い。","指示があれば給餌後5〜10分観察し、食べに来ない豚・元気のない豚に気づける。","指示がなくても毎回観察し、異常な個体を耳標番号または豚房番号・マーキングで特定してメモし、上司に報告する。","給餌が豚の体調を見る一番良い機会であることを理解し、観察の着眼点を新人に指導できる。"],"name_en":"Observing feed intake after feeding","name_vi":"Quan sát lợn ăn sau khi cho ăn","name_id":"Mengamati babi makan setelah pemberian pakan","kanten_en":"Can they observe feed intake for 5-10 minutes after distributing, identify pigs that do not come to eat by ear tag number, or by pen number and marking, and report?","kanten_vi":"Sau khi chia xong có quan sát lợn ăn trong 5–10 phút, xác định lợn không đến ăn bằng số thẻ tai, hoặc số ô chuồng và dấu đánh dấu và báo cáo không.","kanten_id":"Apakah setelah selesai membagikan pakan mengamati babi makan selama 5–10 menit, mengenali babi yang tidak datang makan dengan nomor eartag, atau nomor petak kandang dan tanda semprot, dan melaporkannya.","levels_en":["Leaves right after distributing, and does not notice pigs that do not come to eat or that move strangely.","Observes when instructed, but for too short a time, and often fails to identify individuals or take notes.","With guidance, observes for 5-10 minutes after feeding and can notice pigs that do not come to eat or lack energy.","Independently observes every time, identifies abnormal individuals by ear tag number, or by pen number and marking, notes them, and reports to the supervisor.","Understands that feeding time is the best opportunity to check pig condition, and can teach new staff the key observation points."],"levels_vi":["Chia xong là bỏ đi ngay, không nhận ra cả lợn không đến ăn hay lợn cử động bất thường.","Nếu được chỉ dẫn thì quan sát, nhưng thời gian quá ngắn, thường không xác định từng con và không ghi chú.","Nếu có chỉ dẫn thì quan sát 5–10 phút sau khi cho ăn, và nhận ra được lợn không đến ăn hay lợn không khỏe.","Không cần chỉ dẫn cũng quan sát mỗi lần, xác định con bất thường bằng số thẻ tai, hoặc số ô chuồng và dấu đánh dấu, ghi chú lại và báo cáo cấp trên.","Hiểu lúc cho ăn là cơ hội tốt nhất để xem sức khỏe của lợn, và có thể hướng dẫn người mới các điểm cần chú ý khi quan sát."],"levels_id":["Langsung pergi setelah selesai membagikan, dan tidak sadar walau ada babi yang tidak datang makan atau bergerak aneh.","Jika disuruh mengamati, tetapi waktunya terlalu singkat, dan sering tidak mengenali individu atau tidak mencatat.","Jika ada instruksi, mengamati 5–10 menit setelah memberi pakan, dan bisa menyadari babi yang tidak datang makan atau tampak lesu.","Tanpa instruksi pun, mengamati setiap kali, mengenali individu yang tidak normal dengan nomor eartag, atau nomor petak kandang dan tanda semprot, mencatatnya, dan melaporkan ke atasan.","Memahami bahwa waktu pemberian pakan adalah kesempatan terbaik untuk melihat kondisi babi, dan bisa mengajari karyawan baru titik-titik pengamatannya."]},{"id":"record-biosec","name":"日報記入と豚舎間の防疫","kanten":"与えた量・残餌・異常を日報に記入し、豚舎を移る時は踏込消毒槽で長靴を消毒できるか。","levels":["日報を書かず、踏込消毒もせずに豚舎間を行き来する。","指示されれば記入・消毒するが、書き漏れや消毒の飛ばしが多い。","指示があれば与えた量・残餌・異常を日報に記入し、豚舎の出入りで踏込消毒ができる。","指示がなくても毎回もれなく記録し、こぼれた飼料の掃除と豚舎ごとの消毒・履き替えルールを守る。","エサ運びの移動が病気を運ぶ経路になることを理解し、記録と防疫の習慣を新人に指導できる。"],"name_en":"Daily report entry and biosecurity between barns","name_vi":"Ghi nhật ký và phòng dịch giữa các chuồng","name_id":"Mengisi laporan harian dan biosekuriti antar kandang","kanten_en":"Can they record the amount fed, leftover feed, and abnormalities in the daily report, and disinfect their boots in the footbath when moving between barns?","kanten_vi":"Có ghi vào nhật ký lượng đã cho ăn, thức ăn thừa và bất thường, và khi chuyển sang chuồng khác có khử trùng ủng ở bể nhúng ủng khử trùng không.","kanten_id":"Apakah menulis jumlah yang diberikan, sisa pakan, dan kelainan di laporan harian, serta mendisinfeksi sepatu bot di bak celup disinfeksi saat berpindah kandang.","levels_en":["Does not write the daily report and moves between barns without footbath disinfection.","Records and disinfects when instructed, but often skips entries or footbath steps.","With guidance, records the amount fed, leftover feed, and abnormalities in the daily report, and can disinfect in the footbath when entering and leaving barns.","Independently records everything without omission every time, cleans up spilled feed, and follows the per-barn disinfection and boot-change rules.","Understands that moving feed between barns can become a route that carries disease, and can teach new staff the habits of recording and biosecurity."],"levels_vi":["Không ghi nhật ký, đi lại giữa các chuồng mà không nhúng ủng khử trùng.","Nếu được chỉ dẫn thì ghi và khử trùng, nhưng hay bỏ sót mục ghi và bỏ qua bước khử trùng.","Nếu có chỉ dẫn thì ghi vào nhật ký lượng đã cho ăn, thức ăn thừa và bất thường, và khử trùng ủng ở bể nhúng khi ra vào chuồng.","Không cần chỉ dẫn cũng ghi chép đầy đủ mỗi lần, quét dọn thức ăn rơi vãi, và tuân thủ quy tắc khử trùng và thay ủng theo từng chuồng.","Hiểu việc di chuyển khi vận chuyển thức ăn có thể trở thành đường lây bệnh, và có thể hướng dẫn người mới thói quen ghi chép và phòng dịch."],"levels_id":["Tidak menulis laporan harian, dan berpindah-pindah antar kandang tanpa mencelupkan sepatu bot ke bak disinfeksi.","Jika disuruh, menulis dan mendisinfeksi, tetapi banyak catatan yang terlewat dan langkah disinfeksi yang dilompati.","Jika ada instruksi, bisa menulis jumlah yang diberikan, sisa pakan, dan kelainan di laporan harian, serta mendisinfeksi sepatu bot di bak celup saat keluar-masuk kandang.","Tanpa instruksi pun, mencatat lengkap setiap kali, membersihkan pakan yang tumpah, dan mematuhi aturan disinfeksi dan ganti sepatu bot per kandang.","Memahami bahwa perpindahan saat mengangkut pakan bisa menjadi jalur pembawa penyakit, dan bisa mengajari karyawan baru kebiasaan mencatat dan biosekuriti."]}],"name_en":"Feeding","name_vi":"Cho ăn","name_id":"Pemberian pakan","purposeShort_en":"Stabilize pigs' growth and condition, ensure all pigs eat evenly, and avoid feed waste","purposeShort_vi":"Giúp lợn phát triển và giữ thể lực ổn định, cả đàn ăn đều nhau, không lãng phí thức ăn","purposeShort_id":"Menstabilkan pertumbuhan dan kondisi babi, semua babi makan merata, tidak ada pakan terbuang"},{"id":"feed-adjust","category":"feeding","no":"No.02","name":"エサ調整","purposeShort":"BCS・生理ステージに応じて栄養過不足を防ぎ、繁殖成績を高める","gyomu":"02","aspects":[{"id":"stage-timing","name":"ステージ・時期に合わせた調整","kanten":"妊娠・泌乳などの生理ステージと正しい時期を見て、適切な段階で給与を変えられるか。","levels":["ステージや時期を考えず、いつも同じ与え方をする。切り替えの時期を外しても気にしない。","指示があれば切り替えられるが、ステージ移行の時期が遅れがちで、判断は他者まかせ。","指示があれば生理ステージに応じた時期にエサ量を切り替えられる。","指示がなくてもステージの移行を見越して適切な時期に調整し、増量中は餌残しに注意する。","不適切な時期の調整が逆効果になることを理解し、ステージごとに最適な時期と量を判断し、新人に指導できる。"],"name_en":"Adjustment by stage and timing","name_vi":"Điều chỉnh theo giai đoạn và thời điểm","name_id":"Penyesuaian sesuai tahap dan waktu","kanten_en":"Can they observe physiological stages such as gestation and lactation and change feeding at the appropriate step and correct timing?","kanten_vi":"Có nhìn giai đoạn sinh lý như mang thai, nuôi con và đúng thời điểm, để thay đổi lượng cho ăn ở bước phù hợp không.","kanten_id":"Apakah bisa mengubah pemberian pakan pada tahap yang tepat, dengan melihat tahap fisiologis seperti bunting dan menyusui serta waktu yang benar.","levels_en":["Feeds the same way at all times without considering stage or timing, and does not care about missing the switch-over timing.","With guidance, can switch feed, but stage transitions tend to be late and judgment is left to others.","With guidance, can switch feed amounts at the timing appropriate to the physiological stage.","Independently anticipates stage transitions, adjusts at the appropriate timing, and watches for feed refusals during increases.","Understands that adjustment at the wrong timing can backfire, judges the optimal timing and amount for each stage, and can teach new staff."],"levels_vi":["Không nghĩ đến giai đoạn hay thời điểm, lúc nào cũng cho ăn giống nhau. Lỡ thời điểm chuyển đổi cũng không quan tâm.","Nếu có chỉ dẫn thì chuyển đổi được, nhưng hay bị trễ thời điểm chuyển giai đoạn, việc phán đoán phó mặc cho người khác.","Nếu có chỉ dẫn thì chuyển đổi lượng thức ăn đúng thời điểm theo giai đoạn sinh lý.","Không cần chỉ dẫn cũng nhìn trước việc chuyển giai đoạn để điều chỉnh đúng lúc, khi tăng lượng thì chú ý thức ăn bị bỏ thừa.","Hiểu rằng điều chỉnh sai thời điểm sẽ phản tác dụng, biết phán đoán thời điểm và lượng tốt nhất cho từng giai đoạn, và có thể hướng dẫn người mới."],"levels_id":["Selalu memberi pakan dengan cara yang sama tanpa memikirkan tahap atau waktu. Tidak peduli walau melewatkan waktu penggantian pakan.","Jika ada instruksi bisa mengganti pakan, tetapi waktu perpindahan tahap sering terlambat dan keputusan diserahkan ke orang lain.","Jika ada instruksi, bisa mengganti jumlah pakan pada waktu yang sesuai dengan tahap fisiologis.","Tanpa instruksi pun, bisa mengantisipasi perpindahan tahap dan menyesuaikan pada waktu yang tepat, serta memperhatikan sisa pakan saat jumlah pakan sedang dinaikkan.","Memahami bahwa penyesuaian pada waktu yang salah bisa berakibat sebaliknya, bisa menentukan waktu dan jumlah terbaik untuk tiap tahap, dan bisa mengajari karyawan baru."]},{"id":"individual","name":"個体ごとの採食・残飼の確認","kanten":"給餌後に個体ごとの食べ方と残飼を確かめ、群飼で食べ負ける個体や量の過不足に気づけるか。","levels":["給餌後の食べ方を見ず、残飼があっても放置し、群飼で食べられていない母豚に気づかない。","指示があれば残飼を見るが、残飼をすぐ捨てず、群飼の順位の低い母豚の採食確認に漏れが多い。","指示があれば給餌後に食べ方を見回り、残飼を確認してすぐ捨てられる。","指示がなくても個体ごとの採食を確かめ、残す個体は体調不良・発情・量過多を疑い、すぐ完食して隣のエサを狙う個体は量不足を疑って報告する。","残飼が示すサインと群飼で食べ負ける母豚のリスクを理解し、採食確認の要点を新人に指導できる。"],"name_en":"Checking each sow's eating and leftover feed","name_vi":"Kiểm tra việc ăn và thức ăn thừa của từng con","name_id":"Memeriksa cara makan dan sisa pakan tiap individu","kanten_en":"Can they check how each animal eats and its leftover feed after feeding, and notice individuals losing out in group housing or feed amounts that are too much or too little?","kanten_vi":"Sau khi cho ăn có kiểm tra cách ăn và thức ăn thừa của từng con, nhận ra con bị tranh mất phần khi nuôi nhóm hay lượng thừa thiếu không.","kanten_id":"Apakah setelah memberi pakan memeriksa cara makan dan sisa pakan tiap individu, dan menyadari individu yang kalah makan di kandang kelompok atau jumlah yang berlebih atau kurang.","levels_en":["Does not watch how the pigs eat after feeding, leaves leftover feed as is, and does not notice sows failing to eat in group housing.","Looks at leftover feed when instructed, but does not discard it promptly and often misses checking whether low-ranking sows in group housing are eating.","With guidance, walks around after feeding to watch how the pigs eat, and can check and promptly discard leftover feed.","Independently checks each individual's eating; for sows that leave feed, suspects poor condition, heat, or excess amount, and for those that finish immediately and go for the neighbor's feed, suspects a shortage, and reports.","Understands the signs leftover feed indicates and the risk to sows losing out in group housing, and can teach new staff the key points of eating checks."],"levels_vi":["Không xem cách ăn sau khi cho ăn, có thức ăn thừa cũng bỏ mặc, không nhận ra lợn nái không được ăn khi nuôi nhóm.","Nếu có chỉ dẫn thì xem thức ăn thừa, nhưng không đổ bỏ ngay, và thường bỏ sót việc kiểm tra ăn uống của lợn nái thứ hạng thấp trong nhóm.","Nếu có chỉ dẫn thì đi xem cách ăn sau khi cho ăn, kiểm tra thức ăn thừa và đổ bỏ ngay được.","Không cần chỉ dẫn cũng kiểm tra việc ăn của từng con; con để thừa thì nghi ngờ không khỏe, lên giống hoặc lượng quá nhiều, con ăn hết ngay rồi nhắm sang phần bên cạnh thì nghi ngờ thiếu lượng, và báo cáo.","Hiểu tín hiệu mà thức ăn thừa cho thấy và rủi ro của lợn nái bị tranh mất phần khi nuôi nhóm, và có thể hướng dẫn người mới các điểm chính khi kiểm tra việc ăn."],"levels_id":["Tidak melihat cara makan setelah memberi pakan, membiarkan sisa pakan begitu saja, dan tidak menyadari induk babi yang tidak kebagian makan di kandang kelompok.","Jika ada instruksi melihat sisa pakan, tetapi tidak segera membuangnya, dan sering melewatkan pemeriksaan makan induk babi yang berperingkat rendah di kelompok.","Jika ada instruksi, berkeliling melihat cara makan setelah memberi pakan, dan bisa memeriksa sisa pakan lalu segera membuangnya.","Tanpa instruksi pun, memeriksa makan tiap individu; yang menyisakan pakan dicurigai kurang sehat, birahi, atau jumlahnya berlebih, yang langsung menghabiskan lalu mengincar pakan sebelah dicurigai kekurangan jumlah, lalu melaporkannya.","Memahami tanda yang ditunjukkan sisa pakan dan risiko induk babi yang kalah makan di kandang kelompok, dan bisa mengajari karyawan baru poin-poin pemeriksaan makan."]},{"id":"gradual","name":"段階的な増減","kanten":"エサ量を急に変えず少しずつ増減し、急な変化による食欲低下を防げるか。","levels":["エサ量を一気に増減し、食欲低下を招いても気にしない。","指示があれば増減するが、変化幅が大きく食欲を落とすことがある。","指示があればエサ量を少しずつ増減できる。","指示がなくても食い込みを見ながら段階的に増減し、急な変化を避ける。","急な増減が消化器や食欲に与える影響を理解し、段階的な調整幅を判断して新人に指導できる。"],"name_en":"Gradual increases and decreases","name_vi":"Tăng giảm theo từng bước","name_id":"Menambah dan mengurangi secara bertahap","kanten_en":"Can they change feed amounts little by little instead of suddenly, and prevent loss of appetite caused by abrupt changes?","kanten_vi":"Có tăng giảm lượng thức ăn từng chút một, không thay đổi đột ngột, để tránh giảm ăn do thay đổi quá nhanh không.","kanten_id":"Apakah bisa menambah atau mengurangi jumlah pakan sedikit demi sedikit tanpa perubahan mendadak, sehingga mencegah turunnya nafsu makan.","levels_en":["Increases or decreases feed amounts all at once, and does not care even when this causes loss of appetite.","Adjusts when instructed, but the change is too large and sometimes reduces appetite.","With guidance, can increase or decrease feed amounts little by little.","Independently adjusts in stages while watching feed intake, avoiding abrupt changes.","Understands how abrupt changes affect the digestive system and appetite, can judge appropriate step sizes, and can teach them to new staff."],"levels_vi":["Tăng giảm lượng thức ăn một lúc quá nhiều, gây giảm ăn cũng không quan tâm.","Nếu có chỉ dẫn thì tăng giảm, nhưng mức thay đổi quá lớn, đôi khi làm lợn giảm ăn.","Nếu có chỉ dẫn thì có thể tăng giảm lượng thức ăn từng chút một.","Không cần chỉ dẫn cũng vừa nhìn mức ăn vừa tăng giảm theo từng bước, tránh thay đổi đột ngột.","Hiểu ảnh hưởng của tăng giảm đột ngột đến tiêu hóa và sự thèm ăn, biết quyết định mức điều chỉnh từng bước và có thể hướng dẫn người mới."],"levels_id":["Menambah atau mengurangi jumlah pakan sekaligus, dan tidak peduli walau menyebabkan nafsu makan turun.","Jika ada instruksi bisa menambah atau mengurangi, tetapi perubahannya terlalu besar sehingga kadang menurunkan nafsu makan.","Jika ada instruksi, bisa menambah atau mengurangi jumlah pakan sedikit demi sedikit.","Tanpa instruksi pun, menyesuaikan secara bertahap sambil melihat nafsu makan, dan menghindari perubahan mendadak.","Memahami pengaruh perubahan mendadak terhadap pencernaan dan nafsu makan, bisa menentukan besaran penyesuaian bertahap, dan bisa mengajari karyawan baru."]},{"id":"parity-season","name":"産次・季節への配慮","kanten":"産次の違いや夏季の食い込み低下を考え、量だけでなく回数や時間帯でも対応できるか。","levels":["産次の違いや季節を無視して与え、夏季の食い込み低下を量の増加だけで対応し残餌を増やす。","指示があれば産次や季節をある程度考えるが、多産系母豚の泌乳量増大への対応に漏れが多い。","指示があれば産次や季節を考えて量を調整できる。","指示がなくても産次差・多産系の泌乳量を考え、夏季は給与時間や回数を工夫して食下量を確保する。","産次・泌乳量・季節を総合して給与設計を最適化し、残餌を抑える工夫を新人に指導できる。"],"name_en":"Consideration of parity and season","name_vi":"Chú ý đến lứa đẻ và mùa","name_id":"Memperhatikan paritas dan musim","kanten_en":"Can they account for parity differences and the summer drop in feed intake, responding not only with amounts but also with feeding frequency and timing?","kanten_vi":"Có nghĩ đến sự khác nhau về lứa đẻ và việc giảm ăn mùa hè, ứng phó không chỉ bằng lượng mà cả số bữa và khung giờ cho ăn không.","kanten_id":"Apakah mempertimbangkan perbedaan paritas dan turunnya nafsu makan di musim panas, dan menanganinya bukan hanya dengan jumlah tetapi juga frekuensi dan waktu pemberian.","levels_en":["Feeds while ignoring parity differences and season, handles the summer intake drop only by increasing amounts, and increases leftover feed.","Considers parity and season to some extent when instructed, but often fails to respond to the increased milk production of hyperprolific sows.","With guidance, can adjust amounts considering parity and season.","Independently considers parity differences and hyperprolific sows' milk production, and in summer secures feed intake by adjusting feeding times and frequency.","Optimizes the feeding plan by integrating parity, milk production, and season, and can teach new staff techniques to keep leftover feed down."],"levels_vi":["Cho ăn mà bỏ qua lứa đẻ và mùa, mùa hè lợn giảm ăn chỉ ứng phó bằng cách tăng lượng làm thức ăn thừa tăng lên.","Nếu có chỉ dẫn thì có nghĩ phần nào đến lứa đẻ và mùa, nhưng thường bỏ sót việc ứng phó với lượng sữa tăng của lợn nái dòng mắn đẻ.","Nếu có chỉ dẫn thì có thể điều chỉnh lượng theo lứa đẻ và mùa.","Không cần chỉ dẫn cũng nghĩ đến khác biệt lứa đẻ và lượng sữa của dòng mắn đẻ, mùa hè thì thay đổi giờ và số bữa cho ăn để bảo đảm mức ăn.","Tối ưu thiết kế cho ăn dựa trên tổng hợp lứa đẻ, lượng sữa và mùa, và có thể hướng dẫn người mới cách giảm thức ăn thừa."],"levels_id":["Memberi pakan tanpa memedulikan paritas dan musim, mengatasi turunnya nafsu makan musim panas hanya dengan menambah jumlah sehingga sisa pakan bertambah.","Jika ada instruksi sedikit banyak mempertimbangkan paritas dan musim, tetapi sering lalai menangani meningkatnya produksi susu induk babi tipe beranak banyak.","Jika ada instruksi, bisa menyesuaikan jumlah dengan mempertimbangkan paritas dan musim.","Tanpa instruksi pun, mempertimbangkan perbedaan paritas dan produksi susu tipe beranak banyak, dan di musim panas mengatur waktu serta frekuensi pemberian untuk menjaga konsumsi pakan.","Mengoptimalkan rancangan pemberian pakan dengan memadukan paritas, produksi susu, dan musim, serta bisa mengajari karyawan baru cara menekan sisa pakan."]},{"id":"bcs-palpation","name":"BCS触診と即時記録","kanten":"背骨に手を当てて押しBCSを触って判定し、結果と変更した量をその場で記録できるか。","levels":["目で見ただけで判断し、判定結果も給餌量の変更も記録に残さない。","指示があれば触って判定するが、採点にばらつきがあり、記録を後回しにして忘れる。","指示があれば背骨に沿って触ってBCSを1〜5で判定し、その場で記録できる。","指示がなくても触診で判定してBCS1などの深刻な個体をすぐ報告し、次にエサをやる人が同じ量を与えられる形で記録する。","被毛の厚い冬でも触診が必要な理由を理解し、判定の基準と記録の残し方を新人に指導できる。"],"name_en":"BCS palpation and immediate recording","name_vi":"Sờ nắn chấm điểm BCS và ghi chép ngay tại chỗ","name_id":"Palpasi BCS dan pencatatan langsung","kanten_en":"Can they press a hand along the backbone to judge BCS by touch, and record the result and the changed amount on the spot?","kanten_vi":"Có đặt tay ấn dọc xương sống để sờ nắn chấm điểm BCS, và ghi ngay tại chỗ kết quả cùng lượng đã thay đổi không.","kanten_id":"Apakah bisa menekan dengan tangan di tulang punggung untuk menilai BCS dengan perabaan, dan langsung mencatat hasilnya beserta jumlah yang diubah.","levels_en":["Judges by sight alone, and records neither the score nor the change in feed amount.","Palpates and judges when instructed, but scoring is inconsistent and recording is postponed and forgotten.","With guidance, can judge BCS 1-5 by feeling along the backbone and record it on the spot.","Independently judges by palpation, immediately reports serious individuals such as BCS 1, and records in a form that lets the next feeder give the same amount.","Understands why palpation is still needed in winter when the hair coat is thick, and can teach new staff the scoring criteria and how to keep records."],"levels_vi":["Chỉ nhìn bằng mắt để đánh giá, không ghi lại cả kết quả chấm điểm lẫn thay đổi lượng cho ăn.","Nếu có chỉ dẫn thì sờ nắn để chấm điểm, nhưng điểm số không đều, để việc ghi chép lại sau rồi quên.","Nếu có chỉ dẫn thì sờ dọc xương sống để chấm BCS từ 1〜5 và ghi ngay tại chỗ được.","Không cần chỉ dẫn cũng sờ nắn để chấm điểm, báo ngay con nghiêm trọng như BCS 1, và ghi theo cách để người cho ăn lần sau cho đúng lượng như vậy.","Hiểu vì sao mùa đông lông dày vẫn cần sờ nắn, và có thể hướng dẫn người mới tiêu chuẩn chấm điểm và cách ghi chép."],"levels_id":["Menilai hanya dengan melihat, dan tidak mencatat hasil penilaian maupun perubahan jumlah pakan.","Jika ada instruksi menilai dengan meraba, tetapi skornya tidak konsisten, dan menunda pencatatan sampai lupa.","Jika ada instruksi, bisa meraba sepanjang tulang punggung untuk menilai BCS 1〜5 dan mencatatnya di tempat.","Tanpa instruksi pun, menilai dengan palpasi, segera melaporkan individu serius seperti BCS 1, dan mencatat dalam bentuk yang memungkinkan pemberi pakan berikutnya memberi jumlah yang sama.","Memahami mengapa palpasi tetap perlu di musim dingin saat bulu tebal, dan bisa mengajari karyawan baru kriteria penilaian dan cara menyimpan catatan."]}],"name_en":"Feed adjustment","name_vi":"Điều chỉnh lượng thức ăn","name_id":"Penyesuaian Jumlah Pakan","purposeShort_en":"Prevent nutritional excess or deficiency according to BCS and physiological stage, and improve reproductive performance","purposeShort_vi":"Tránh thừa hoặc thiếu dinh dưỡng theo BCS (điểm thể trạng) và giai đoạn sinh lý, nâng cao thành tích sinh sản","purposeShort_id":"Mencegah kelebihan atau kekurangan gizi sesuai BCS dan tahap fisiologis, meningkatkan hasil reproduksi"},{"id":"feed-recovery","category":"feeding","no":"No.16","name":"エサ回収","purposeShort":"病気・腐敗リスクを減らし飼料コストを削減し、給餌量見直しに役立てる","gyomu":"16","aspects":[{"id":"spoilage","name":"変質餌の見分けと短時間回収","kanten":"カビ・腐敗した残餌を再利用せず、回収・保管を短時間で行い変質を防げるか。","levels":["カビや腐敗した残餌を再利用し、回収後も常温で長時間放置して変質させる。","指示があれば回収するが、変質の見分けが甘く、放置時間が長くなりがち。","指示があればカビ・腐敗した残餌を見分けて分け、短時間で回収できる。","指示がなくても変質を見分けて再利用せず、回収・保管を短時間で済ませる。","変質が病気・腐敗リスクにつながることを理解し、回収の手順を最適化して新人に指導できる。"],"name_en":"Identifying spoiled feed and quick recovery","name_vi":"Phân biệt thức ăn hỏng và thu gom nhanh","name_id":"Mengenali pakan rusak dan pengumpulan cepat","kanten_en":"Can they avoid reusing moldy or rotten leftover feed and complete recovery and storage quickly to prevent spoilage?","kanten_vi":"Có tránh dùng lại thức ăn thừa bị mốc, thối, và thu gom, cất giữ trong thời gian ngắn để tránh hỏng thêm không.","kanten_id":"Apakah tidak memakai ulang sisa pakan yang berjamur atau busuk, dan bisa mengumpulkan serta menyimpannya dalam waktu singkat agar tidak rusak.","levels_en":["Reuses moldy or rotten leftover feed and leaves recovered feed at room temperature for long periods, letting it spoil.","With guidance, recovers feed, but is poor at identifying spoilage and tends to leave feed standing too long.","With guidance, can identify and separate moldy or rotten leftover feed and recover it quickly.","Independently identifies spoiled feed, avoids reusing it, and completes recovery and storage in a short time.","Understands that spoilage leads to disease and decay risk, optimizes the recovery procedure, and can teach new staff."],"levels_vi":["Dùng lại thức ăn thừa bị mốc hoặc thối; sau khi thu gom lại để lâu ở nhiệt độ thường làm hỏng thêm.","Nếu có chỉ dẫn thì thu gom, nhưng phân biệt thức ăn hỏng còn kém, hay để lâu.","Nếu có chỉ dẫn thì phân biệt và tách được thức ăn thừa bị mốc, thối, thu gom trong thời gian ngắn.","Không cần chỉ dẫn cũng phân biệt thức ăn hỏng và không dùng lại, thu gom và cất giữ nhanh gọn.","Hiểu thức ăn hỏng dẫn đến nguy cơ bệnh và thối rữa, biết tối ưu quy trình thu gom và có thể hướng dẫn người mới."],"levels_id":["Memakai ulang sisa pakan yang berjamur atau busuk, dan setelah dikumpulkan dibiarkan lama di suhu ruang sampai rusak.","Jika ada instruksi bisa mengumpulkan, tetapi kurang teliti mengenali pakan rusak dan cenderung membiarkannya terlalu lama.","Jika ada instruksi, bisa mengenali dan memisahkan sisa pakan yang berjamur atau busuk, serta mengumpulkannya dalam waktu singkat.","Tanpa instruksi pun, mengenali pakan rusak dan tidak memakainya ulang, serta menyelesaikan pengumpulan dan penyimpanan dalam waktu singkat.","Memahami bahwa pakan rusak berhubungan dengan risiko penyakit dan pembusukan, bisa mengoptimalkan urutan pengumpulan, dan bisa mengajari karyawan baru."]},{"id":"dedicated-tools","name":"専用容器・器具の管理","kanten":"回収用の容器・器具を専用にして洗い、他用途転用や豚房間共用による交差汚染を防げるか。","levels":["他用途のバケツを転用し、器具を豚房間で使い回して交差汚染・病原伝播を招く。","指示があれば専用容器を使うが、洗浄や豚房ごとの使い分けに漏れがある。","指示があれば回収用の専用容器・器具を使い、使用後に洗える。","指示がなくても専用容器を清潔に保ち、豚房間の共用を避けて交差汚染を防ぐ。","交差汚染・病原伝播の仕組みを理解し、容器・器具の管理ルールを新人に指導できる。"],"name_en":"Management of dedicated containers and tools","name_vi":"Quản lý thùng và dụng cụ chuyên dùng","name_id":"Pengelolaan wadah dan alat khusus","kanten_en":"Can they keep recovery containers and tools dedicated and washed, preventing cross-contamination from repurposing or sharing between pens?","kanten_vi":"Có dùng thùng và dụng cụ chuyên cho việc thu gom, rửa sạch sau khi dùng, tránh lây nhiễm chéo do dùng chung giữa các ô chuồng hoặc dùng sang việc khác không.","kanten_id":"Apakah memakai wadah dan alat khusus untuk pengumpulan lalu mencucinya, sehingga mencegah kontaminasi silang karena dipakai untuk keperluan lain atau dipakai bergantian antar petak kandang.","levels_en":["Repurposes buckets from other uses and shares tools between pens, causing cross-contamination and pathogen spread.","With guidance, uses dedicated containers, but is inconsistent about washing and keeping tools separate per pen.","With guidance, uses dedicated recovery containers and tools and can wash them after use.","Independently keeps dedicated containers clean and avoids sharing between pens, preventing cross-contamination.","Understands the mechanisms of cross-contamination and pathogen spread, and can teach new staff the rules for managing containers and tools."],"levels_vi":["Lấy xô của việc khác sang dùng, dùng chung dụng cụ giữa các ô chuồng lợn, gây lây nhiễm chéo và lan truyền mầm bệnh.","Nếu có chỉ dẫn thì dùng thùng chuyên dùng, nhưng có bỏ sót việc rửa và việc dùng riêng theo từng ô chuồng.","Nếu có chỉ dẫn thì dùng thùng và dụng cụ chuyên cho thu gom, rửa được sau khi dùng.","Không cần chỉ dẫn cũng giữ thùng chuyên dùng sạch sẽ, tránh dùng chung giữa các ô chuồng để phòng lây nhiễm chéo.","Hiểu cơ chế lây nhiễm chéo và lan truyền mầm bệnh, và có thể hướng dẫn người mới quy tắc quản lý thùng, dụng cụ."],"levels_id":["Memakai ember bekas keperluan lain, dan memakai alat bergantian antar petak kandang sehingga menyebabkan kontaminasi silang dan penyebaran bibit penyakit.","Jika ada instruksi bisa memakai wadah khusus, tetapi sering lalai mencuci atau memisahkan pemakaian per petak kandang.","Jika ada instruksi, bisa memakai wadah dan alat khusus untuk pengumpulan, serta mencucinya setelah dipakai.","Tanpa instruksi pun, menjaga wadah khusus tetap bersih dan menghindari pemakaian bergantian antar petak kandang sehingga mencegah kontaminasi silang.","Memahami mekanisme kontaminasi silang dan penyebaran bibit penyakit, dan bisa mengajari karyawan baru aturan pengelolaan wadah dan alat."]},{"id":"trough-clean","name":"エサ箱の点検と毎日の清掃","kanten":"エサ箱の底が見えるかで残餌を判断し、すみに固まったエサをかき出して毎日きれいにできるか。","levels":["エサ箱の中を見ず、すみに固まったエサを残したまま放置する。","指示があれば清掃するが、すみや角の固まりのかき出しに取り残しが多い。","指示があれば底が見えるかで残餌の有無を判断し、固まりをブラシでかき出して清掃できる。","指示がなくても毎日エサ箱を点検・清掃し、水がかかって濡れ固まったエサを見つけたら取り除いて報告する。","取り残しがカビ・細菌のもとになり豚が食べなくなることを理解し、清掃の要点を新人に指導できる。"],"name_en":"Feed trough inspection and daily cleaning","name_vi":"Kiểm tra máng ăn và vệ sinh hằng ngày","name_id":"Pemeriksaan tempat pakan dan pembersihan harian","kanten_en":"Can they judge leftover feed by whether the trough bottom is visible, scrape out feed caked in the corners, and clean it every day?","kanten_vi":"Có nhìn thấy đáy máng hay không để đánh giá thức ăn thừa, cạo sạch thức ăn đóng cứng ở góc và làm sạch máng mỗi ngày không.","kanten_id":"Apakah bisa menilai sisa pakan dari terlihat tidaknya dasar tempat pakan, mengerok pakan yang mengeras di sudut, dan membersihkannya setiap hari.","levels_en":["Does not look inside the trough and leaves feed caked in the corners as it is.","Cleans when instructed, but leaves much of the caked feed in corners and edges unscraped.","With guidance, can judge leftover feed by whether the bottom is visible, and scrape out caked feed with a brush.","Independently inspects and cleans the trough every day, and if wet, caked feed from water splashes is found, removes it and reports.","Understands that leftover residue breeds mold and bacteria and stops pigs from eating, and can teach new staff the key cleaning points."],"levels_vi":["Không nhìn vào trong máng ăn, để mặc thức ăn đóng cứng ở góc máng.","Nếu được chỉ dẫn thì vệ sinh, nhưng cạo sót nhiều chỗ đóng cứng ở góc và cạnh máng.","Nếu có chỉ dẫn thì nhìn thấy đáy máng hay không để đánh giá thức ăn thừa, và dùng bàn chải cạo sạch chỗ đóng cứng được.","Không cần chỉ dẫn cũng kiểm tra và vệ sinh máng mỗi ngày, nếu thấy thức ăn bị nước bắn vào ướt và đóng cứng thì lấy ra và báo cáo.","Hiểu chỗ cạo sót là nguồn nấm mốc và vi khuẩn làm lợn bỏ ăn, và có thể hướng dẫn người mới các điểm chính khi vệ sinh."],"levels_id":["Tidak melihat ke dalam tempat pakan, dan membiarkan pakan yang mengeras di sudut.","Jika disuruh membersihkan, tetapi banyak gumpalan di sudut dan pojok yang tertinggal tidak dikerok.","Jika ada instruksi, bisa menilai ada tidaknya sisa pakan dari terlihatnya dasar tempat pakan, dan mengerok gumpalan dengan sikat.","Tanpa instruksi pun, memeriksa dan membersihkan tempat pakan setiap hari, dan jika menemukan pakan yang basah terkena air lalu mengeras, mengambilnya dan melaporkannya.","Memahami bahwa sisa yang tertinggal menjadi sumber jamur dan bakteri sehingga babi berhenti makan, dan bisa mengajari karyawan baru poin-poin pembersihannya."]},{"id":"residue-report","name":"残餌量の記録と給餌量への反映","kanten":"房番号と残餌量を記録して給餌担当に伝え、次回の給餌量見直しにつなげられるか。","levels":["残餌の量を記録せずただ捨てるだけで、給餌担当にも伝えない。","指示されれば記録するが、房番号や量があいまいで給餌量の見直しに使えない。","指示があれば房番号とおおよその量を記録し、給餌担当に伝えられる。","指示がなくても記録・報告し、残る房は次回10〜20%減の目安を踏まえて「残餌ゼロ」に近づける。","残餌が飼料コストと給餌設計を見直す情報であることを理解し、記録と伝え方を新人に指導できる。"],"name_en":"Recording leftover feed and feeding it back into feed amounts","name_vi":"Ghi lượng thức ăn thừa và phản ánh vào lượng cho ăn","name_id":"Mencatat jumlah sisa pakan dan memakainya untuk meninjau jumlah pakan","kanten_en":"Can they record the pen number and leftover amount, pass it to the person in charge of feeding, and link it to the next feed amount review?","kanten_vi":"Có ghi số ô chuồng và lượng thức ăn thừa, báo cho người phụ trách cho ăn, và kết nối vào việc xem lại lượng cho ăn lần sau không.","kanten_id":"Apakah bisa mencatat nomor petak dan jumlah sisa pakan, menyampaikannya ke petugas pemberi pakan, dan menghubungkannya dengan peninjauan jumlah pakan berikutnya.","levels_en":["Just throws leftover feed away without recording the amount, and does not tell the person in charge of feeding.","Records when instructed, but the pen number and amount are vague and cannot be used for feed amount reviews.","With guidance, can record the pen number and approximate amount and pass them to the person in charge of feeding.","Independently records and reports, and for pens with leftovers, works toward \"zero leftover feed\" using the guideline of a 10-20% reduction next time.","Understands that leftover feed is information for reviewing feed costs and feeding plans, and can teach new staff how to record and communicate it."],"levels_vi":["Không ghi lượng thức ăn thừa, chỉ đổ bỏ, cũng không báo cho người phụ trách cho ăn.","Nếu được chỉ dẫn thì ghi, nhưng số ô chuồng và lượng mơ hồ, không dùng được để xem lại lượng cho ăn.","Nếu có chỉ dẫn thì ghi số ô chuồng và lượng ước chừng, và báo cho người phụ trách cho ăn được.","Không cần chỉ dẫn cũng ghi chép và báo cáo; ô còn thừa thì dựa vào mốc giảm 10〜20% lần sau để tiến gần đến \"không còn thức ăn thừa\".","Hiểu thức ăn thừa là thông tin để xem lại chi phí thức ăn và thiết kế cho ăn, và có thể hướng dẫn người mới cách ghi và cách truyền đạt."],"levels_id":["Hanya membuang sisa pakan tanpa mencatat jumlahnya, dan tidak memberi tahu petugas pemberi pakan.","Jika disuruh mencatat, tetapi nomor petak dan jumlahnya tidak jelas sehingga tidak bisa dipakai untuk meninjau jumlah pakan.","Jika ada instruksi, bisa mencatat nomor petak dan perkiraan jumlahnya, lalu menyampaikannya ke petugas pemberi pakan.","Tanpa instruksi pun, mencatat dan melaporkan; untuk petak yang menyisakan pakan, mendekati \"sisa pakan nol\" dengan patokan pengurangan 10〜20% pada pemberian berikutnya.","Memahami bahwa sisa pakan adalah informasi untuk meninjau biaya pakan dan rancangan pemberian pakan, dan bisa mengajari karyawan baru cara mencatat dan menyampaikannya."]},{"id":"pig-sign","name":"残餌からの体調サイン察知","kanten":"残餌のある房の豚のようすを合わせて見て、体調不良やエサ不足のサインに気づけるか。","levels":["残餌を片づけるだけで、その房の豚のようすをまったく見ない。","指示されれば豚を見るが、体調不良とエサ不足の見分けは他者まかせ。","指示があれば残餌のある房の豚のようすを確かめ、気づいたことを伝えられる。","指示がなくても残る房は体調不良を、すぐ完食して隣のエサを狙う豚はエサ不足を疑って報告する。","「残餌は情報」という考え方を理解し、体調サインの読み方を新人に指導できる。"],"name_en":"Reading condition signs from leftover feed","name_vi":"Nhận ra dấu hiệu sức khỏe từ thức ăn thừa","name_id":"Membaca tanda kondisi babi dari sisa pakan","kanten_en":"Can they also look at the pigs in pens with leftover feed, and notice signs of poor condition or feed shortage?","kanten_vi":"Có xem thêm tình trạng lợn ở ô chuồng còn thức ăn thừa, và nhận ra dấu hiệu không khỏe hay thiếu thức ăn không.","kanten_id":"Apakah juga melihat keadaan babi di petak yang ada sisa pakannya, dan menyadari tanda kondisi buruk atau kekurangan pakan.","levels_en":["Only clears away leftover feed and never looks at the pigs in that pen.","Looks at the pigs when instructed, but leaves distinguishing poor condition from feed shortage to others.","With guidance, can check the pigs in pens with leftover feed and pass on what they noticed.","Independently suspects poor condition in pens that leave feed, and feed shortage in pigs that finish immediately and go for the neighbor's feed, and reports.","Understands the idea that \"leftover feed is information\", and can teach new staff how to read condition signs."],"levels_vi":["Chỉ dọn thức ăn thừa, hoàn toàn không xem tình trạng lợn trong ô chuồng đó.","Nếu được chỉ dẫn thì xem lợn, nhưng việc phân biệt không khỏe hay thiếu thức ăn thì phó mặc cho người khác.","Nếu có chỉ dẫn thì xem tình trạng lợn ở ô còn thức ăn thừa, và truyền đạt điều nhận thấy được.","Không cần chỉ dẫn cũng nghi ngờ ô còn thừa là lợn không khỏe, con ăn hết ngay rồi nhắm sang phần bên cạnh là thiếu thức ăn, và báo cáo.","Hiểu cách nghĩ \"thức ăn thừa là thông tin\", và có thể hướng dẫn người mới cách đọc dấu hiệu sức khỏe."],"levels_id":["Hanya membereskan sisa pakan, dan sama sekali tidak melihat keadaan babi di petak itu.","Jika disuruh melihat babi, tetapi membedakan kondisi buruk dan kekurangan pakan diserahkan ke orang lain.","Jika ada instruksi, bisa memeriksa keadaan babi di petak yang ada sisa pakannya dan menyampaikan apa yang disadarinya.","Tanpa instruksi pun, mencurigai kondisi buruk pada petak yang menyisakan pakan, dan kekurangan pakan pada babi yang langsung menghabiskan lalu mengincar pakan sebelah, lalu melaporkannya.","Memahami cara pikir bahwa \"sisa pakan adalah informasi\", dan bisa mengajari karyawan baru cara membaca tanda kondisi babi."]}],"name_en":"Feed recovery","name_vi":"Thu gom thức ăn thừa","name_id":"Mengumpulkan sisa pakan","purposeShort_en":"Reduce disease and spoilage risk, cut feed costs, and inform feed amount reviews","purposeShort_vi":"Giảm nguy cơ bệnh và thức ăn thối hỏng, giảm chi phí thức ăn, giúp xem lại lượng cho ăn","purposeShort_id":"Mengurangi risiko penyakit dan pembusukan, menekan biaya pakan, dan membantu peninjauan jumlah pakan"},{"id":"nursing-feed","category":"feeding","no":"No.43","name":"えつけ（哺乳期給餌）","purposeShort":"泌乳量を確保し、子豚の離乳頭数・体重を高め、母豚の削痩を防ぐ","gyomu":"43","aspects":[{"id":"gradual-lactation","name":"分娩後の段階的増給と暑熱対応","kanten":"分娩後は少量から段階的に増やし、暑熱時は回数を増やして食下量を確保できるか。","levels":["分娩後にいきなり多く与える、または暑熱時に回数を増やさず食下量を落とす。","指示があれば段階的に増やすが、暑熱時の回数調整や水の確保に漏れがある。","指示があれば分娩後は少量から段階的に増やし、水が飲める状態を保てる。","指示がなくても食い込みを見て段階的に増やし、暑熱時は回数を増やして食下量を確保する。","泌乳量と母豚の削痩・次回繁殖の関係を理解し、給餌設計を最適化して新人に指導できる。"],"name_en":"Gradual increase after farrowing and heat stress response","name_vi":"Tăng dần thức ăn sau đẻ và ứng phó nắng nóng","name_id":"Penambahan bertahap setelah melahirkan dan penanganan cuaca panas","kanten_en":"Can they increase feed gradually from small amounts after farrowing, and increase feeding frequency in hot weather to maintain feed intake?","kanten_vi":"Sau khi đẻ có cho ăn từ ít rồi tăng dần từng bước, khi nắng nóng có tăng số bữa để lợn ăn đủ không.","kanten_id":"Apakah setelah melahirkan menambah pakan bertahap mulai dari sedikit, dan saat cuaca panas menambah frekuensi pemberian agar konsumsi pakan terjaga.","levels_en":["Gives large amounts right after farrowing, or fails to increase feeding frequency in hot weather, reducing feed intake.","With guidance, increases feed gradually, but is inconsistent about adjusting frequency in hot weather and securing water.","With guidance, increases feed gradually from small amounts after farrowing and keeps water available.","Independently increases feed step by step while watching intake, and raises feeding frequency in hot weather to maintain feed intake.","Understands the relationship between milk production, sow body condition loss, and the next breeding cycle, optimizes the feeding plan, and can teach new staff."],"levels_vi":["Sau khi đẻ cho ăn nhiều ngay một lúc, hoặc khi nắng nóng không tăng số bữa làm lợn ăn ít đi.","Nếu có chỉ dẫn thì tăng dần được, nhưng có bỏ sót việc điều chỉnh số bữa khi nắng nóng và việc bảo đảm nước uống.","Nếu có chỉ dẫn thì sau khi đẻ cho ăn từ ít rồi tăng dần, giữ được trạng thái lợn luôn uống được nước.","Không cần chỉ dẫn cũng nhìn mức ăn để tăng dần từng bước, khi nắng nóng thì tăng số bữa để lợn ăn đủ.","Hiểu quan hệ giữa lượng sữa với việc nái gầy sút và lứa sinh sản tiếp theo, biết tối ưu cách cho ăn và có thể hướng dẫn người mới."],"levels_id":["Langsung memberi banyak pakan setelah melahirkan, atau saat cuaca panas tidak menambah frekuensi sehingga konsumsi pakan turun.","Jika ada instruksi bisa menambah bertahap, tetapi sering lalai mengatur frekuensi saat cuaca panas dan memastikan air minum.","Jika ada instruksi, bisa menambah pakan bertahap mulai dari sedikit setelah melahirkan, dan menjaga agar induk selalu bisa minum air.","Tanpa instruksi pun, menambah pakan bertahap sambil melihat nafsu makan, dan saat cuaca panas menambah frekuensi pemberian agar konsumsi pakan terjaga.","Memahami hubungan produksi susu dengan menurunnya kondisi tubuh induk dan reproduksi berikutnya, bisa mengoptimalkan rancangan pemberian pakan, dan bisa mengajari karyawan baru."]},{"id":"colostrum-balance","name":"産子数と乳頭数のバランス管理","kanten":"産子数と乳頭数の差を確認し、初乳未摂取子豚や泌乳不全乳頭を見落とさず対応できるか。","levels":["産子数と乳頭数の差を確認せず、初乳を飲めない子豚や泌乳不全の乳頭を放置する。","指示があれば確認するが、分割授乳や弱い子豚の固定に漏れが多い。","指示があれば産子数と乳頭数の差を確かめ、初乳を飲めていない子豚に気づける。","指示がなくても分割授乳を行い、泌乳不全乳頭や発育格差に気づいて弱い子豚を手当てする。","初乳・泌乳と発育格差の関係を理解し、里子や分割授乳の判断を最適化して新人に指導できる。"],"name_en":"Balancing litter size and functional teats","name_vi":"Quản lý cân bằng số con đẻ ra và số vú","name_id":"Pengelolaan keseimbangan jumlah anak dan jumlah puting","kanten_en":"Can they check the gap between litter size and teat count, and respond without overlooking piglets that missed colostrum or non-functional teats?","kanten_vi":"Có kiểm tra chênh lệch giữa số con đẻ ra và số vú, không bỏ sót lợn con chưa bú sữa đầu và vú không tiết sữa, và xử lý được không.","kanten_id":"Apakah memeriksa selisih jumlah anak yang lahir dengan jumlah puting, dan tidak melewatkan anak babi yang belum minum kolostrum atau puting yang tidak mengeluarkan susu.","levels_en":["Does not check the gap between litter size and teat count, leaving piglets without colostrum and non-lactating teats unattended.","With guidance, checks, but often fails to carry out split suckling or place weak piglets on teats.","With guidance, checks the gap between litter size and teat count and can notice piglets that are not getting colostrum.","Independently performs split suckling, notices non-functional teats and growth disparities, and cares for weak piglets.","Understands the relationship between colostrum, lactation, and growth disparity, optimizes decisions on cross-fostering and split suckling, and can teach new staff."],"levels_vi":["Không kiểm tra chênh lệch giữa số con đẻ ra và số vú, bỏ mặc lợn con không bú được sữa đầu và vú không tiết sữa.","Nếu có chỉ dẫn thì kiểm tra, nhưng hay bỏ sót việc cho bú theo nhóm chia lượt và việc giữ chỗ bú cho con yếu.","Nếu có chỉ dẫn thì kiểm tra chênh lệch giữa số con đẻ ra và số vú, nhận ra được lợn con chưa bú được sữa đầu.","Không cần chỉ dẫn cũng cho bú theo nhóm chia lượt, nhận ra vú không tiết sữa và sự chênh lệch phát triển, chăm sóc con yếu.","Hiểu quan hệ giữa sữa đầu, tiết sữa và chênh lệch phát triển, biết tối ưu việc ghép bầy và cho bú chia lượt, và có thể hướng dẫn người mới."],"levels_id":["Tidak memeriksa selisih jumlah anak dan jumlah puting, membiarkan anak babi yang tidak bisa minum kolostrum atau puting yang tidak mengeluarkan susu.","Jika ada instruksi bisa memeriksa, tetapi sering lalai melakukan menyusui bergantian (split suckling) atau memegangi anak yang lemah ke puting.","Jika ada instruksi, bisa memeriksa selisih jumlah anak dan jumlah puting, serta menyadari anak babi yang belum minum kolostrum.","Tanpa instruksi pun, melakukan menyusui bergantian, menyadari puting yang tidak mengeluarkan susu dan perbedaan pertumbuhan, serta menolong anak babi yang lemah.","Memahami hubungan kolostrum dan produksi susu dengan perbedaan pertumbuhan, bisa mengoptimalkan keputusan titip anak ke induk lain dan menyusui bergantian, dan bisa mengajari karyawan baru."]},{"id":"water-first","name":"「エサの前に水」の飲水確認","kanten":"給餌前に必ずニップルを押して水を確かめ、週1回はカップで流量テストができるか。","levels":["飲水を確認せずにエサだけ与え、水が出ていなくても気づかない。","指示があれば確認するが、目視だけで済ませ、流量テストはしない。","指示があれば給餌前にニップルを指で押して水が出るか確かめられる。","指示がなくても「エサの前に水」を守り、週1回カップで流量（2L/分以上）を測って不足があれば報告する。","泌乳中の母豚は1日25〜30L飲み、水不足が泌乳量激減につながることを理解し、確認の習慣を新人に指導できる。"],"name_en":"\"Water before feed\" drinking-water check","name_vi":"Kiểm tra nước uống theo nguyên tắc \"nước trước, thức ăn sau\"","name_id":"Pemeriksaan air minum \"air dulu sebelum pakan\"","kanten_en":"Can they always press the nipple to check the water before feeding, and run a flow test with a cup once a week?","kanten_vi":"Trước khi cho ăn có luôn ấn núm uống để kiểm tra nước, và mỗi tuần 1 lần đo lưu lượng bằng cốc không.","kanten_id":"Apakah selalu menekan nipple untuk memeriksa air sebelum memberi pakan, dan seminggu sekali melakukan tes aliran dengan cangkir.","levels_en":["Gives only feed without checking the water, and does not notice even when no water comes out.","Checks when instructed, but only by sight, and does not run flow tests.","With guidance, can press the nipple with a finger before feeding to check that water comes out.","Independently follows \"water before feed\", measures the flow with a cup once a week (2 L/min or more), and reports any shortfall.","Understands that a lactating sow drinks 25-30 L a day and that water shortage sharply reduces milk production, and can teach new staff the checking habit."],"levels_vi":["Không kiểm tra nước uống mà chỉ cho ăn, nước không chảy ra cũng không nhận ra.","Nếu có chỉ dẫn thì kiểm tra, nhưng chỉ nhìn bằng mắt, không đo lưu lượng.","Nếu có chỉ dẫn thì trước khi cho ăn dùng ngón tay ấn núm uống để kiểm tra nước có chảy ra không.","Không cần chỉ dẫn cũng giữ nguyên tắc \"nước trước, thức ăn sau\", mỗi tuần 1 lần đo lưu lượng bằng cốc (từ 2L/phút trở lên), thiếu thì báo cáo.","Hiểu lợn nái đang cho con bú uống 25〜30L mỗi ngày và thiếu nước làm lượng sữa giảm mạnh, và có thể hướng dẫn người mới thói quen kiểm tra."],"levels_id":["Hanya memberi pakan tanpa memeriksa air minum, dan tidak sadar walau air tidak keluar.","Jika ada instruksi memeriksa, tetapi hanya dengan melihat, dan tidak melakukan tes aliran.","Jika ada instruksi, bisa menekan nipple dengan jari sebelum memberi pakan untuk memastikan air keluar.","Tanpa instruksi pun, menjaga prinsip \"air dulu sebelum pakan\", seminggu sekali mengukur aliran dengan cangkir (2L/menit atau lebih), dan melaporkan jika kurang.","Memahami bahwa induk babi menyusui minum 25〜30L per hari dan kekurangan air membuat produksi susu turun drastis, dan bisa mengajari karyawan baru kebiasaan memeriksanya."]},{"id":"residue-decide","name":"残飯チェックと給餌量の決定","kanten":"残飯を見てから今日の量を決める順番を守り、全く食べない母豚は検温して報告できるか。","levels":["残飯を見ずに惰性で同じ量を入れ、食べない母豚がいても放置する。","指示があれば残飯を見るが、古い残飯の上に新しいエサを足してしまうことがある。","指示があれば古い残飯を取り除いてから量を決め、給餌量と残飯を記録用紙に記入できる。","指示がなくても完食・残飯あり・食欲廃絶を見分けて量を加減し、食べない母豚は体温を測って39.5℃以上ならすぐ報告する。","「残飯チェック→給餌量決定」の順番の意味を理解し、量の決め方と報告の判断を新人に指導できる。"],"name_en":"Leftover check and deciding the feed amount","name_vi":"Kiểm tra thức ăn thừa rồi mới quyết định lượng cho ăn","name_id":"Memeriksa sisa pakan lalu menentukan jumlah pakan","kanten_en":"Can they keep the order of checking leftovers before deciding today's amount, and take the temperature of sows that eat nothing and report?","kanten_vi":"Có giữ đúng trình tự xem thức ăn thừa trước rồi mới quyết định lượng hôm nay, và đo nhiệt độ lợn nái hoàn toàn không ăn để báo cáo không.","kanten_id":"Apakah menjaga urutan melihat sisa pakan dulu baru menentukan jumlah hari ini, dan mengukur suhu induk babi yang sama sekali tidak makan lalu melaporkannya.","levels_en":["Puts in the same amount out of habit without looking at leftovers, and leaves sows that do not eat unattended.","Looks at leftovers when instructed, but sometimes adds new feed on top of old leftovers.","With guidance, removes old leftovers before deciding the amount, and can record the feed amount and leftovers on the record sheet.","Independently distinguishes finished, leftovers present, and complete loss of appetite to adjust the amount, and for sows that do not eat, takes the temperature and reports immediately if it is 39.5°C or higher.","Understands the meaning of the order \"leftover check, then decide the feed amount\", and can teach new staff how to decide amounts and when to report."],"levels_vi":["Không xem thức ăn thừa mà cứ theo quán tính đổ cùng một lượng, có lợn nái không ăn cũng bỏ mặc.","Nếu có chỉ dẫn thì xem thức ăn thừa, nhưng đôi khi đổ thức ăn mới đè lên thức ăn thừa cũ.","Nếu có chỉ dẫn thì lấy thức ăn thừa cũ ra rồi mới quyết định lượng, và ghi lượng cho ăn cùng thức ăn thừa vào phiếu ghi chép được.","Không cần chỉ dẫn cũng phân biệt ăn hết, còn thừa, bỏ ăn hoàn toàn để tăng giảm lượng; lợn nái không ăn thì đo thân nhiệt, từ 39,5℃ trở lên là báo ngay.","Hiểu ý nghĩa của trình tự \"kiểm tra thức ăn thừa → quyết định lượng cho ăn\", và có thể hướng dẫn người mới cách quyết định lượng và cách phán đoán khi báo cáo."],"levels_id":["Menuang jumlah yang sama karena kebiasaan tanpa melihat sisa pakan, dan membiarkan induk babi yang tidak makan.","Jika ada instruksi melihat sisa pakan, tetapi kadang menambahkan pakan baru di atas sisa pakan lama.","Jika ada instruksi, bisa membuang sisa pakan lama dulu baru menentukan jumlah, dan menulis jumlah pakan serta sisa pakan di lembar catatan.","Tanpa instruksi pun, membedakan habis, ada sisa, dan sama sekali tidak makan untuk mengatur jumlah; induk babi yang tidak makan diukur suhunya, dan jika 39,5℃ atau lebih segera dilaporkan.","Memahami makna urutan \"periksa sisa pakan → tentukan jumlah pakan\", dan bisa mengajari karyawan baru cara menentukan jumlah dan pertimbangan pelaporannya."]},{"id":"creep-feed","name":"クリープフィードの管理","kanten":"生後5〜7日からひとつまみを与え、毎日全て交換して子豚の興味のようすを確かめられるか。","levels":["フィーダーに大量に入れっぱなしにし、カビたエサも交換しない。","指示があれば入れ替えるが、量が多すぎたり毎日の交換を忘れたりする。","指示があれば古いエサを全部出してフィーダーをきれいにし、新しいクリープフィードをひとつまみ入れられる。","指示がなくても毎日交換し、子豚が鼻でつつくかなど興味のようすを確かめて次の対応につなげる。","ひとつまみが「固形のエサも食べ物」と教えるための量だと理解し、えつけの進め方を新人に指導できる。"],"name_en":"Creep feed management","name_vi":"Quản lý creep feed (thức ăn tập ăn)","name_id":"Pengelolaan creep feed","kanten_en":"Can they give a pinch from 5-7 days of age, replace all of it every day, and check the piglets' interest?","kanten_vi":"Có cho một nhúm nhỏ từ 5〜7 ngày tuổi, mỗi ngày thay toàn bộ, và kiểm tra biểu hiện lợn con có quan tâm không.","kanten_id":"Apakah memberi sejumput mulai umur 5〜7 hari, menggantinya seluruhnya setiap hari, dan memeriksa tanda ketertarikan anak babi.","levels_en":["Leaves large amounts sitting in the feeder and does not replace even moldy feed.","Replaces it when instructed, but gives too much or forgets the daily replacement.","With guidance, can empty out all the old feed, clean the feeder, and put in a pinch of fresh creep feed.","Independently replaces it every day, checks the piglets' interest such as nosing at it, and links this to the next step.","Understands that the pinch is the amount used to teach that \"solid feed is also food\", and can teach new staff how to advance creep feeding."],"levels_vi":["Đổ nhiều vào máng rồi để nguyên, thức ăn mốc cũng không thay.","Nếu có chỉ dẫn thì thay, nhưng lúc thì cho quá nhiều, lúc thì quên thay hằng ngày.","Nếu có chỉ dẫn thì lấy hết thức ăn cũ ra, làm sạch máng, và cho một nhúm nhỏ creep feed mới vào được.","Không cần chỉ dẫn cũng thay mỗi ngày, kiểm tra biểu hiện quan tâm của lợn con như dùng mũi hích thử, và kết nối vào bước tiếp theo.","Hiểu một nhúm nhỏ là lượng để dạy lợn con rằng \"thức ăn rắn cũng là đồ ăn\", và có thể hướng dẫn người mới cách tiến hành tập ăn."],"levels_id":["Membiarkan pakan dalam jumlah banyak menumpuk di feeder, dan pakan berjamur pun tidak diganti.","Jika ada instruksi menggantinya, tetapi kadang memberi terlalu banyak atau lupa mengganti setiap hari.","Jika ada instruksi, bisa mengeluarkan semua pakan lama, membersihkan feeder, dan mengisi sejumput creep feed baru.","Tanpa instruksi pun, mengganti setiap hari, memeriksa tanda ketertarikan anak babi seperti menyodok dengan hidung, dan menghubungkannya ke langkah berikutnya.","Memahami bahwa sejumput adalah jumlah untuk mengajarkan bahwa \"pakan padat juga makanan\", dan bisa mengajari karyawan baru cara melatih makan."]}],"name_en":"Lactation feeding","name_vi":"Tập cho ăn (cho ăn thời kỳ nuôi con bú sữa)","name_id":"Melatih makan (pemberian pakan masa menyusui)","purposeShort_en":"Secure milk production, increase the number and weight of weaned piglets, and prevent sow body condition loss","purposeShort_vi":"Bảo đảm lượng sữa, tăng số con và cân nặng lúc cai sữa, tránh lợn nái bị gầy sút","purposeShort_id":"Menjaga produksi susu, meningkatkan jumlah dan berat anak babi saat sapih, dan mencegah induk babi menjadi kurus"},{"id":"grow-handover","category":"feeding","no":"No.27","name":"育成受け","purposeShort":"育成管理への引き継ぎを確実に行う","gyomu":"27","aspects":[{"id":"info-handover","name":"個体情報の引き継ぎ","kanten":"離乳日齢・頭数・処置やワクチンの記録・注意個体を、引き継ぎシートの書面で残して伝えられるか。","levels":["口頭だけで済ませて書面に残さず、注意個体の伝達漏れがあっても気にしない。","指示されれば伝えるが、処置記録や注意個体の項目が抜け、その場の読み合わせをしない。","指示があれば離乳日齢・頭数・処置やワクチンの記録・注意個体を引き継ぎシートに書いて伝えられる。","指示がなくても書面で引き継いでその場で読み合わせ、小さい子・下痢をしていた子・足を引きずる子を必ず書面に残す。","引き継ぎで漏れやすい情報を把握し、書面と読み合わせによる確実な引き継ぎの方法を新人に指導できる。"],"name_en":"Handover of individual animal information","name_vi":"Bàn giao thông tin từng con","name_id":"Serah terima informasi individu","kanten_en":"Can they leave the weaning age, head count, treatment and vaccine records, and animals needing attention in writing on the handover sheet and pass them on?","kanten_vi":"Có ghi lại bằng văn bản trên phiếu bàn giao ngày tuổi cai sữa, số con, hồ sơ điều trị và vắc-xin, con cần chú ý, rồi truyền đạt không.","kanten_id":"Apakah bisa meninggalkan umur sapih, jumlah ekor, catatan pengobatan dan vaksin, serta individu yang perlu diperhatikan secara tertulis di lembar serah terima dan menyampaikannya.","levels_en":["Finishes with word of mouth only, leaves nothing in writing, and does not care even if animals needing attention are missed.","Passes information when instructed, but items such as treatment records and animals needing attention are missing, and does not read it through together on the spot.","With guidance, can write the weaning age, head count, treatment and vaccine records, and animals needing attention on the handover sheet and pass them on.","Independently hands over in writing and reads it through together on the spot, always noting in writing the small ones, those that had diarrhea, and those dragging a leg.","Knows which information is easily missed in handovers, and can teach new staff reliable handover methods using written sheets and read-throughs."],"levels_vi":["Chỉ nói miệng cho xong, không để lại văn bản, con cần chú ý bị bỏ sót cũng không quan tâm.","Nếu được chỉ dẫn thì truyền đạt, nhưng thiếu mục hồ sơ điều trị và con cần chú ý, không cùng đọc lại xác nhận tại chỗ.","Nếu có chỉ dẫn thì ghi ngày tuổi cai sữa, số con, hồ sơ điều trị và vắc-xin, con cần chú ý vào phiếu bàn giao và truyền đạt được.","Không cần chỉ dẫn cũng bàn giao bằng văn bản và cùng đọc lại xác nhận tại chỗ; con nhỏ, con từng tiêu chảy, con đi khập khiễng nhất định ghi vào văn bản.","Nắm được những thông tin dễ bị bỏ sót khi bàn giao, và có thể hướng dẫn người mới cách bàn giao chắc chắn bằng văn bản và đọc lại xác nhận."],"levels_id":["Menyelesaikan hanya dengan lisan tanpa meninggalkan tulisan, dan tidak peduli walau individu yang perlu diperhatikan terlewat.","Jika disuruh menyampaikan, tetapi butir seperti catatan pengobatan dan individu yang perlu diperhatikan hilang, dan tidak membacakannya bersama di tempat.","Jika ada instruksi, bisa menulis umur sapih, jumlah ekor, catatan pengobatan dan vaksin, serta individu yang perlu diperhatikan di lembar serah terima dan menyampaikannya.","Tanpa instruksi pun, menyerahterimakan secara tertulis dan membacakannya bersama di tempat; yang kecil, yang pernah diare, dan yang kakinya diseret selalu dicatat tertulis.","Mengetahui informasi yang mudah terlewat saat serah terima, dan bisa mengajari karyawan baru cara serah terima yang pasti dengan tulisan dan pembacaan bersama."]},{"id":"receiving-env","name":"受入れ環境の事前確認と初期観察","kanten":"受入れ先の水・エサ・温度・群密度を事前に整え、受入後数日の採食・飲水を確認できるか。","levels":["洗浄・消毒や空舎期間を省き、前ロットのままの温度・換気で受け入れ、群密度過多も見落とす。","指示があれば環境を確認するが、受入後の採食・飲水の確認に漏れが多い。","指示があれば受入れ先の水・エサ・温度を事前に確かめられる。","指示がなくても洗浄・消毒・空舎期間をとり、群密度と受入後3日間の採食・飲水を確認する。","病原体持ち越しや群密度過多のリスクを理解し、受入れ環境づくりを最適化して新人に指導できる。"],"name_en":"Pre-checking the receiving environment and initial observation","name_vi":"Kiểm tra trước môi trường nhận lợn và quan sát ban đầu","name_id":"Pemeriksaan awal lingkungan penerima dan pengamatan awal","kanten_en":"Can they prepare water, feed, temperature, and group density at the receiving site in advance, and check eating and drinking for the first days after arrival?","kanten_vi":"Có chuẩn bị trước nước, thức ăn, nhiệt độ, mật độ đàn ở nơi nhận lợn, và kiểm tra việc ăn, uống trong vài ngày sau khi nhận không.","kanten_id":"Apakah menyiapkan air, pakan, suhu, dan kepadatan kelompok di tempat penerima sebelumnya, dan memeriksa makan serta minum selama beberapa hari setelah diterima.","levels_en":["Skips washing, disinfection, and downtime, receives pigs with the previous lot's temperature and ventilation settings, and overlooks overcrowding.","With guidance, checks the environment, but often fails to confirm eating and drinking after arrival.","With guidance, can check water, feed, and temperature at the receiving site in advance.","Independently carries out washing, disinfection, and downtime, and checks group density plus eating and drinking for the first 3 days after arrival.","Understands the risks of pathogen carryover and overcrowding, optimizes preparation of the receiving environment, and can teach new staff."],"levels_vi":["Bỏ qua việc rửa, khử trùng và thời gian để trống chuồng, nhận lợn với nhiệt độ, thông gió còn nguyên như lứa trước, mật độ đàn quá đông cũng bỏ sót.","Nếu có chỉ dẫn thì kiểm tra môi trường, nhưng hay bỏ sót việc kiểm tra ăn, uống sau khi nhận lợn.","Nếu có chỉ dẫn thì kiểm tra trước được nước, thức ăn, nhiệt độ ở nơi nhận lợn.","Không cần chỉ dẫn cũng thực hiện rửa, khử trùng, để trống chuồng, kiểm tra mật độ đàn và việc ăn, uống trong 3 ngày sau khi nhận.","Hiểu nguy cơ mầm bệnh còn sót lại và mật độ đàn quá đông, biết tối ưu việc chuẩn bị môi trường nhận lợn và có thể hướng dẫn người mới."],"levels_id":["Melewatkan pencucian, disinfeksi, dan masa kosong kandang, menerima babi dengan suhu dan ventilasi bekas kelompok sebelumnya, dan tidak sadar kepadatan kelompok berlebih.","Jika ada instruksi bisa memeriksa lingkungan, tetapi sering lalai memeriksa makan dan minum setelah babi diterima.","Jika ada instruksi, bisa memeriksa air, pakan, dan suhu di tempat penerima sebelum babi datang.","Tanpa instruksi pun, melakukan pencucian, disinfeksi, dan masa kosong kandang, serta memeriksa kepadatan kelompok dan makan-minum selama 3 hari setelah diterima.","Memahami risiko bibit penyakit yang terbawa dan kepadatan kelompok berlebih, bisa mengoptimalkan penyiapan lingkungan penerima, dan bisa mengajari karyawan baru."]},{"id":"grouping","name":"体重別グルーピングと弱小豚の別管理","kanten":"子豚を大・中・小に分け、群平均の70%以下の極端に小さい子豚を別管理にできるか。","levels":["体重差を見ずに全頭を同じ房に入れ、小さい子豚が衰弱しても気づかない。","指示があれば分けるが、基準があいまいで極端に小さい子豚を普通の群に入れてしまう。","指示があれば体重や目視で大・中・小に分け、極端に小さい子豚を見分けられる。","指示がなくてもグルーピングを行い、群平均の70%以下の子豚は別管理にして衰弱を防ぐ。","弱い子豚が普通の群ではエサにありつけない仕組みを理解し、分け方の基準を新人に指導できる。"],"name_en":"Grouping by weight and separate care for weak piglets","name_vi":"Chia nhóm theo cân nặng và quản lý riêng lợn con yếu","name_id":"Pengelompokan menurut berat dan perawatan terpisah anak babi lemah","kanten_en":"Can they sort piglets into large, medium, and small, and put extremely small piglets at 70% or less of the group average under separate management?","kanten_vi":"Có chia lợn con thành lớn, vừa, nhỏ, và quản lý riêng con quá nhỏ chỉ bằng 70% trở xuống so với trung bình đàn không.","kanten_id":"Apakah bisa memilah anak babi menjadi besar, sedang, kecil, dan mengelola terpisah anak babi yang sangat kecil, 70% atau kurang dari rata-rata kelompok.","levels_en":["Puts all piglets in the same pen without looking at weight differences, and does not notice even when small piglets weaken.","Sorts when instructed, but the criteria are vague and extremely small piglets end up in the normal group.","With guidance, can sort into large, medium, and small by weight or by eye, and pick out extremely small piglets.","Independently does the grouping, and puts piglets at 70% or less of the group average under separate management to prevent weakening.","Understands why weak piglets cannot get to the feed in a normal group, and can teach new staff the sorting criteria."],"levels_vi":["Không nhìn chênh lệch cân nặng, cho tất cả vào cùng một ô, lợn con nhỏ suy yếu cũng không nhận ra.","Nếu có chỉ dẫn thì chia, nhưng tiêu chuẩn mơ hồ, con quá nhỏ vẫn bị cho vào nhóm bình thường.","Nếu có chỉ dẫn thì dựa vào cân nặng hoặc nhìn bằng mắt để chia lớn, vừa, nhỏ, và nhận ra được con quá nhỏ.","Không cần chỉ dẫn cũng chia nhóm, con chỉ bằng 70% trở xuống so với trung bình đàn thì quản lý riêng để tránh suy yếu.","Hiểu cơ chế con yếu không giành được thức ăn trong nhóm bình thường, và có thể hướng dẫn người mới tiêu chuẩn chia nhóm."],"levels_id":["Memasukkan semua anak babi ke petak yang sama tanpa melihat perbedaan berat, dan tidak sadar walau anak babi kecil melemah.","Jika ada instruksi memilah, tetapi kriterianya kabur sehingga anak babi yang sangat kecil masuk ke kelompok biasa.","Jika ada instruksi, bisa memilah besar, sedang, kecil berdasarkan berat atau pengamatan, dan mengenali anak babi yang sangat kecil.","Tanpa instruksi pun, melakukan pengelompokan, dan anak babi yang 70% atau kurang dari rata-rata kelompok dikelola terpisah untuk mencegah pelemahan.","Memahami mekanisme anak babi lemah tidak kebagian pakan di kelompok biasa, dan bisa mengajari karyawan baru kriteria pemilahannya."]},{"id":"move-count","name":"安全な移動と頭数照合","kanten":"カートで無理のない頭数を安全に運び、入舎後に頭数を数えて引き継ぎ情報と照合できるか。","levels":["一度に大量に運んで落とす・挟むの危険を招き、入舎後の頭数も数えない。","指示があれば運べるが、頭数の照合やプレートへの記入に漏れが多い。","指示があれば無理のない頭数で運び、入舎後に頭数を数えてプレートに記入できる。","指示がなくても季節に応じた時間帯・経路で安全に移動し、数が合わなければその場で分娩舎に確認する。","移動時の事故と頭数の食い違いが後の管理を狂わせることを理解し、移動と照合の段取りを新人に指導できる。"],"name_en":"Safe transport and head count verification","name_vi":"Vận chuyển an toàn và đối chiếu số con","name_id":"Pemindahan yang aman dan pencocokan jumlah ekor","kanten_en":"Can they carry a reasonable number safely by cart, count the pigs after housing, and verify against the handover information?","kanten_vi":"Có dùng xe đẩy chở số con vừa sức một cách an toàn, sau khi vào chuồng đếm số con và đối chiếu với thông tin bàn giao không.","kanten_id":"Apakah bisa mengangkut jumlah yang wajar dengan aman memakai kereta dorong, menghitung jumlah ekor setelah masuk kandang, dan mencocokkannya dengan informasi serah terima.","levels_en":["Carries too many at once, risking drops and pinching, and does not count the pigs after housing.","Can carry when instructed, but often fails to verify the head count or write it on the plate.","With guidance, carries a reasonable number, and can count the pigs after housing and write it on the plate.","Independently moves them safely at times and routes suited to the season, and if the numbers do not match, checks with the farrowing house on the spot.","Understands that transport accidents and head count discrepancies disrupt later management, and can teach new staff how to organize transport and verification."],"levels_vi":["Một lần chở quá nhiều gây nguy cơ rơi, kẹp, sau khi vào chuồng cũng không đếm số con.","Nếu có chỉ dẫn thì chở được, nhưng hay bỏ sót việc đối chiếu số con và ghi vào bảng.","Nếu có chỉ dẫn thì chở số con vừa sức, sau khi vào chuồng đếm số con và ghi vào bảng được.","Không cần chỉ dẫn cũng chọn khung giờ và lối đi theo mùa để di chuyển an toàn, số không khớp thì xác nhận ngay tại chỗ với chuồng đẻ.","Hiểu tai nạn khi di chuyển và số con không khớp sẽ làm rối việc quản lý sau này, và có thể hướng dẫn người mới cách sắp xếp di chuyển và đối chiếu."],"levels_id":["Mengangkut terlalu banyak sekaligus sehingga berisiko jatuh atau terjepit, dan tidak menghitung jumlah ekor setelah masuk kandang.","Jika ada instruksi bisa mengangkut, tetapi sering lalai mencocokkan jumlah ekor dan menulisnya di papan.","Jika ada instruksi, mengangkut dalam jumlah wajar, dan bisa menghitung jumlah ekor setelah masuk kandang lalu menulisnya di papan.","Tanpa instruksi pun, memindahkan dengan aman pada waktu dan rute yang sesuai musim, dan jika jumlah tidak cocok, langsung mengonfirmasi ke kandang beranak di tempat.","Memahami bahwa kecelakaan saat pemindahan dan selisih jumlah ekor mengacaukan pengelolaan selanjutnya, dan bisa mengajari karyawan baru pengaturan pemindahan dan pencocokannya."]},{"id":"teach-water-feed","name":"飲水・エサの教え込み","kanten":"全頭が水を飲めるか1頭ずつ確かめ、少量のスターターでエサの場所を教えられるか。","levels":["水を飲めない子豚を放置し、エサを一度に大量に入れて腐らせる。","指示があれば確認するが、1頭ずつの飲水確認や食べやすくする工夫に漏れがある。","指示があれば1頭ずつ飲水を確かめ、エサ箱に少量のスターターを入れて場所を教えられる。","指示がなくても飲めない子豚にはニップルを押して水を出して見せ、初日はおかゆ状にするなど食べやすく整える。","入舎直後の脱水と食べ残しの腐敗が下痢につながることを理解し、教え込みのコツを新人に指導できる。"],"name_en":"Teaching piglets to drink and eat","name_vi":"Tập cho lợn con uống nước và ăn","name_id":"Mengajari anak babi minum dan makan","kanten_en":"Can they check one by one that every piglet can drink water, and teach them where the feed is with a small amount of starter?","kanten_vi":"Có kiểm tra từng con xem cả đàn có uống được nước không, và dùng một lượng nhỏ thức ăn starter để chỉ chỗ ăn không.","kanten_id":"Apakah bisa memeriksa satu per satu apakah semua anak babi bisa minum air, dan mengajari lokasi pakan dengan sedikit pakan starter.","levels_en":["Leaves piglets that cannot drink unattended, and puts in large amounts of feed at once, letting it rot.","Checks when instructed, but often misses the one-by-one drinking check and ways to make feed easier to eat.","With guidance, can check drinking one by one, and put a small amount of starter in the trough to teach where the feed is.","Independently presses the nipple to show water to piglets that cannot drink, and makes feed easier to eat, such as making it porridge-like on the first day.","Understands that dehydration right after housing and rotting leftovers lead to diarrhea, and can teach new staff the tricks of teaching piglets."],"levels_vi":["Bỏ mặc lợn con không uống được nước, đổ một lúc quá nhiều thức ăn làm thức ăn bị thối.","Nếu có chỉ dẫn thì kiểm tra, nhưng hay bỏ sót việc kiểm tra uống nước từng con và cách làm cho dễ ăn.","Nếu có chỉ dẫn thì kiểm tra uống nước từng con, cho một lượng nhỏ thức ăn starter vào máng để chỉ chỗ ăn được.","Không cần chỉ dẫn cũng ấn núm uống cho nước chảy ra để chỉ cho con không uống được, ngày đầu làm thức ăn dạng cháo cho dễ ăn.","Hiểu mất nước ngay sau khi vào chuồng và thức ăn thừa bị thối dẫn đến tiêu chảy, và có thể hướng dẫn người mới mẹo tập cho lợn con."],"levels_id":["Membiarkan anak babi yang tidak bisa minum, dan memasukkan pakan dalam jumlah besar sekaligus sampai membusuk.","Jika ada instruksi memeriksa, tetapi sering melewatkan pemeriksaan minum satu per satu dan cara membuat pakan mudah dimakan.","Jika ada instruksi, bisa memeriksa minum satu per satu, dan menaruh sedikit pakan starter di tempat pakan untuk mengajari lokasinya.","Tanpa instruksi pun, menekan nipple untuk memperlihatkan air keluar kepada anak babi yang tidak bisa minum, dan di hari pertama membuat pakan seperti bubur agar mudah dimakan.","Memahami bahwa dehidrasi tepat setelah masuk kandang dan sisa pakan yang membusuk menyebabkan diare, dan bisa mengajari karyawan baru kiat-kiat melatihnya."]}],"name_en":"Nursery intake (weaned pigs)","name_vi":"Nhận lợn cai sữa vào chuồng cai sữa (bàn giao nuôi dưỡng)","name_id":"Penerimaan babi sapih ke kandang sapih (serah terima pemeliharaan)","purposeShort_en":"Ensure a reliable handover to grower management","purposeShort_vi":"Bàn giao chắc chắn sang khâu quản lý lợn choai","purposeShort_id":"Memastikan serah terima ke pengelolaan pembesaran berjalan dengan pasti"},{"id":"castration","category":"feeding","no":"No.34","name":"去勢","purposeShort":"雄臭のない豚肉を生産し、ケンカ・乗駕を減らし、群管理を安全にする","gyomu":"34","aspects":[{"id":"age-method","name":"日齢・方法の遵守と短時間実施","kanten":"決められた日齢・方法で、子豚に無理をさせず短時間で去勢できるか。","levels":["日齢や方法を守らず、生後7日を過ぎてから雑に行い、子豚に長く無理をさせる。","指示があれば実施できるが、日齢の判断や手早さに欠け、ストレスをかけがち。","指示があれば決められた日齢・方法でひと通り去勢できる。","指示がなくても適期を見て短時間で行い、子豚への負担を抑える。","日齢超過がストレス・出血を増やすことを理解し、適期と手技を新人に指導できる。"],"name_en":"Following age and method with quick execution","name_vi":"Giữ đúng tuổi ngày, cách làm và thực hiện nhanh gọn","name_id":"Mematuhi umur dan metode serta pelaksanaan cepat","kanten_en":"Can they castrate at the prescribed age in days and by the prescribed method, quickly and without straining the piglets?","kanten_vi":"Có thiến đúng tuổi ngày và cách làm quy định, thao tác nhanh, không làm lợn con quá sức không.","kanten_id":"Apakah bisa melakukan kastrasi dengan umur (hari) dan metode yang ditentukan, dalam waktu singkat tanpa memaksa anak babi.","levels_en":["Ignores age and method, performs the procedure roughly after 7 days of age, and puts prolonged strain on the piglets.","With guidance, can perform the procedure, but lacks judgment on age and speed, tending to stress the piglets.","With guidance, can castrate adequately at the prescribed age and by the prescribed method.","Independently judges the right timing, works quickly, and keeps the burden on piglets low.","Understands that exceeding the proper age increases stress and bleeding, and can teach new staff the right timing and technique."],"levels_vi":["Không giữ tuổi ngày và cách làm, làm ẩu sau khi lợn quá 7 ngày tuổi, bắt lợn con chịu đựng lâu.","Nếu có chỉ dẫn thì làm được, nhưng phán đoán tuổi ngày và độ nhanh tay còn kém, dễ gây stress cho lợn.","Nếu có chỉ dẫn thì thiến được các bước cơ bản theo đúng tuổi ngày và cách làm quy định.","Không cần chỉ dẫn cũng nhìn đúng thời kỳ thích hợp, làm nhanh gọn, giảm gánh nặng cho lợn con.","Hiểu việc quá tuổi ngày làm tăng stress và chảy máu, và có thể hướng dẫn người mới thời kỳ thích hợp và kỹ thuật thao tác."],"levels_id":["Tidak mematuhi umur atau metode, melakukannya dengan kasar setelah lewat umur 7 hari, dan membuat anak babi tersiksa lama.","Jika ada instruksi bisa melaksanakan, tetapi kurang bisa menilai umur dan kurang cekatan sehingga cenderung membuat stres.","Jika ada instruksi, bisa melakukan kastrasi secara garis besar dengan umur dan metode yang ditentukan.","Tanpa instruksi pun, melakukannya pada waktu yang tepat dalam waktu singkat, dan menekan beban pada anak babi.","Memahami bahwa melewati umur yang tepat menambah stres dan pendarahan, dan bisa mengajari karyawan baru waktu yang tepat dan teknik pelaksanaannya."]},{"id":"asepsis-aftercare","name":"清潔な器具と術後の確認","kanten":"器具を1頭ごとに消毒し、術後の切り口の処置と出血・腫れ・元気の確認ができるか。","levels":["器具を1頭ごとに消毒せず使い回し、術後の切り口処置や観察を怠り腹膜炎・感染を招く。","指示があれば消毒するが、術後の消毒薬塗布や観察に漏れが多い。","指示があれば清潔な器具を使い、術後の出血・腫れ・元気をひと通り確認できる。","指示がなくても1頭ごとに器具を消毒し、切り口を処置して術後の観察頻度を増やす。","感染・合併症の仕組みを理解し、無菌操作と術後管理を新人に指導できる。"],"name_en":"Clean instruments and post-operative checks","name_vi":"Dụng cụ sạch và kiểm tra sau thiến","name_id":"Alat yang bersih dan pemeriksaan pascaoperasi","kanten_en":"Can they disinfect instruments for each animal, treat the incision, and check for bleeding, swelling, and vitality after the procedure?","kanten_vi":"Có khử trùng dụng cụ theo từng con, xử lý vết cắt sau thiến và kiểm tra chảy máu, sưng, độ khỏe không.","kanten_id":"Apakah mendisinfeksi alat setiap satu ekor, merawat luka sayatan setelah operasi, dan memeriksa pendarahan, bengkak, serta keaktifan anak babi.","levels_en":["Reuses instruments without disinfecting between animals and neglects incision care and observation, causing peritonitis and infection.","With guidance, disinfects, but often fails to apply antiseptic to the incision or observe afterward.","With guidance, uses clean instruments and can adequately check bleeding, swelling, and vitality after the procedure.","Independently disinfects instruments between each animal, treats the incision, and increases the frequency of post-operative observation.","Understands the mechanisms of infection and complications, and can teach new staff aseptic technique and post-operative management."],"levels_vi":["Không khử trùng dụng cụ theo từng con mà dùng đi dùng lại, bỏ qua xử lý vết cắt và quan sát sau thiến, gây viêm phúc mạc và nhiễm trùng.","Nếu có chỉ dẫn thì khử trùng, nhưng hay bỏ sót việc bôi thuốc sát trùng và quan sát sau thiến.","Nếu có chỉ dẫn thì dùng dụng cụ sạch, kiểm tra được cơ bản chảy máu, sưng và độ khỏe sau thiến.","Không cần chỉ dẫn cũng khử trùng dụng cụ theo từng con, xử lý vết cắt và tăng số lần quan sát sau thiến.","Hiểu cơ chế nhiễm trùng và biến chứng, và có thể hướng dẫn người mới thao tác vô trùng và quản lý sau thiến."],"levels_id":["Memakai alat bergantian tanpa disinfeksi per ekor, lalai merawat luka dan mengamati setelah operasi sehingga menyebabkan peritonitis (radang selaput perut) dan infeksi.","Jika ada instruksi bisa mendisinfeksi, tetapi sering lalai mengoleskan obat disinfektan pada luka dan mengamati setelah operasi.","Jika ada instruksi, bisa memakai alat yang bersih dan memeriksa pendarahan, bengkak, serta keaktifan secara garis besar setelah operasi.","Tanpa instruksi pun, mendisinfeksi alat setiap satu ekor, merawat luka sayatan, dan menambah frekuensi pengamatan setelah operasi.","Memahami mekanisme infeksi dan komplikasi, dan bisa mengajari karyawan baru cara kerja bersih (aseptik) dan pengelolaan pascaoperasi."]},{"id":"restraint-safety","name":"保定と刃物の安全","kanten":"子豚を仰向けにしっかり保定し、刃を人に向けず、暴れたら保定し直してから切れるか。","levels":["保定が不十分なまま切ろうとし、刃の向きや使い終わった刃の処理も気にしない。","指示があれば保定できるが、固定が甘く、子豚が暴れても無理に続けることがある。","指示があれば仰向けにしっかり保定し、暴れたら切らずに保定し直せる。","指示がなくても刃を自分や補助者に向けない・使い終わった刃は医療ゴミへ、などの安全を守って補助者と連携する。","保定のコツと刃物事故の防ぎ方を理解し、見学・保定係から段階を踏ませて新人に指導できる。"],"name_en":"Restraint and blade safety","name_vi":"Giữ lợn con và an toàn dao kéo","name_id":"Penahanan anak babi dan keamanan pisau","kanten_en":"Can they firmly restrain the piglet on its back, keep the blade pointed away from people, and re-restrain before cutting if it struggles?","kanten_vi":"Có giữ chắc lợn con nằm ngửa, không hướng lưỡi dao về phía người, lợn giãy thì giữ lại cho chắc rồi mới cắt không.","kanten_id":"Apakah bisa menahan anak babi telentang dengan kuat, tidak mengarahkan mata pisau ke orang, dan jika meronta menahan ulang dulu sebelum memotong.","levels_en":["Tries to cut with insufficient restraint, and pays no attention to the blade's direction or the disposal of used blades.","Can restrain when instructed, but the hold is loose and sometimes forces on even when the piglet struggles.","With guidance, can restrain the piglet firmly on its back, and if it struggles, stops cutting and re-restrains.","Independently follows safety rules such as never pointing the blade at themselves or the assistant and putting used blades into medical waste, and coordinates with the assistant.","Understands the tricks of restraint and how to prevent blade accidents, and can teach new staff step by step, starting from observing and holding."],"levels_vi":["Giữ chưa chắc đã định cắt, cũng không để ý hướng lưỡi dao hay cách xử lý lưỡi dao đã dùng.","Nếu có chỉ dẫn thì giữ được, nhưng cố định lỏng lẻo, lợn con giãy vẫn có khi cố làm tiếp.","Nếu có chỉ dẫn thì giữ chắc lợn con nằm ngửa, lợn giãy thì không cắt mà giữ lại cho chắc được.","Không cần chỉ dẫn cũng tuân thủ an toàn như không hướng lưỡi dao về mình hay người phụ, lưỡi dao đã dùng bỏ vào rác y tế, và phối hợp với người phụ.","Hiểu mẹo giữ lợn và cách phòng tai nạn dao kéo, và có thể hướng dẫn người mới theo từng bước từ quan sát, làm người giữ trở đi."],"levels_id":["Mencoba memotong dengan penahanan yang belum kuat, dan tidak memedulikan arah mata pisau maupun pembuangan pisau bekas.","Jika ada instruksi bisa menahan, tetapi pegangannya longgar, dan kadang tetap melanjutkan walau anak babi meronta.","Jika ada instruksi, bisa menahan anak babi telentang dengan kuat, dan jika meronta, tidak memotong melainkan menahan ulang.","Tanpa instruksi pun, menjaga keselamatan seperti tidak mengarahkan pisau ke diri sendiri atau pembantu dan membuang pisau bekas ke limbah medis, serta bekerja sama dengan pembantu.","Memahami kiat penahanan dan cara mencegah kecelakaan pisau, dan bisa mengajari karyawan baru secara bertahap mulai dari mengamati dan menjadi pemegang."]},{"id":"complete-check","name":"左右摘出の確認とヘルニア対応","kanten":"左右2つの精巣を取り出せたか必ず確かめ、陰嚢がふくらんだ子豚は切らずに報告できるか。","levels":["摘出の確認をせず、陰嚢が大きくふくらんだ子豚もそのまま切ってしまう。","指示があれば確認するが、取り残しやヘルニア疑いの見分けが不確実。","指示があれば左右2つとも取り出せたことを確認し、陰嚢のふくらみに気づける。","指示がなくても毎頭確認し、ヘルニア疑いの子豚は自分で切らず必ず指導係に報告する。","取り残しが腫れ・雄臭の原因になることを理解し、確認とヘルニアの見分け方を新人に指導できる。"],"name_en":"Checking removal of both testicles and handling hernias","name_vi":"Kiểm tra đã lấy đủ hai tinh hoàn và xử lý thoát vị","name_id":"Memastikan kedua testis terangkat dan penanganan hernia","kanten_en":"Can they always confirm that both left and right testicles were removed, and report piglets with a swollen scrotum without cutting them?","kanten_vi":"Có luôn kiểm tra đã lấy ra đủ hai tinh hoàn trái phải chưa, con có bìu phồng to thì không cắt mà báo cáo không.","kanten_id":"Apakah selalu memastikan kedua testis kiri dan kanan sudah dikeluarkan, dan melaporkan anak babi dengan skrotum membengkak tanpa memotongnya.","levels_en":["Does not confirm removal, and cuts even piglets with a greatly swollen scrotum.","Confirms when instructed, but is unreliable at spotting retained testicles and suspected hernias.","With guidance, confirms that both testicles were removed, and can notice a swollen scrotum.","Independently confirms every piglet, and for suspected hernias, never cuts by themselves and always reports to the trainer.","Understands that retained testicles cause swelling and boar taint, and can teach new staff the confirmation and how to spot hernias."],"levels_vi":["Không kiểm tra việc lấy tinh hoàn, con có bìu phồng to cũng cứ thế cắt.","Nếu có chỉ dẫn thì kiểm tra, nhưng phân biệt sót tinh hoàn và nghi thoát vị chưa chắc chắn.","Nếu có chỉ dẫn thì kiểm tra đã lấy ra đủ hai bên, và nhận ra được bìu bị phồng.","Không cần chỉ dẫn cũng kiểm tra từng con, con nghi thoát vị thì không tự cắt mà nhất định báo cho người hướng dẫn.","Hiểu việc sót tinh hoàn gây sưng và mùi hôi đực, và có thể hướng dẫn người mới cách kiểm tra và cách nhận biết thoát vị."],"levels_id":["Tidak memastikan pengangkatan, dan tetap memotong anak babi yang skrotumnya membengkak besar.","Jika ada instruksi memastikan, tetapi belum andal membedakan testis tertinggal dan dugaan hernia.","Jika ada instruksi, memastikan kedua testis sudah dikeluarkan, dan bisa menyadari skrotum yang membengkak.","Tanpa instruksi pun, memastikan setiap ekor, dan untuk dugaan hernia tidak memotong sendiri melainkan selalu melapor ke pembimbing.","Memahami bahwa testis yang tertinggal menyebabkan pembengkakan dan bau pejantan, dan bisa mengajari karyawan baru cara memastikan dan mengenali hernia."]},{"id":"season-record","name":"季節への配慮と処置記録","kanten":"夏は早朝に行いハエに注意し、冬は処置後すぐ保温灯へ戻し、処置の記録と片づけができるか。","levels":["暑い時間帯に行って子豚に負担をかけ、処置の記録も片づけもしない。","指示があれば対応するが、保温灯へ戻すのが遅れたり記録に漏れが多い。","指示があれば季節の注意を守って実施し、処置の記録と医療ゴミの片づけができる。","指示がなくても夏は早朝の段取りを組み、冬は道具を先にそろえて保温灯から離す時間を最短にし、記録を残す。","季節ごとのリスク（ハエ・ウジ・凍傷）を理解し、段取りと記録の残し方を新人に指導できる。"],"name_en":"Seasonal consideration and treatment records","name_vi":"Chú ý theo mùa và ghi chép xử lý","name_id":"Perhatian musiman dan pencatatan tindakan","kanten_en":"Can they work early in the morning in summer watching for flies, return piglets to the heat lamp right after treatment in winter, and record the treatment and clean up?","kanten_vi":"Mùa hè có làm vào sáng sớm và chú ý ruồi, mùa đông xử lý xong đưa ngay về đèn sưởi, ghi chép việc xử lý và dọn dẹp không.","kanten_id":"Apakah di musim panas bekerja pagi-pagi sambil mewaspadai lalat, di musim dingin segera mengembalikan ke lampu penghangat setelah tindakan, serta mencatat tindakan dan membereskannya.","levels_en":["Works in hot hours, straining the piglets, and neither records the treatment nor cleans up.","Responds when instructed, but is slow to return piglets to the heat lamp and often misses records.","With guidance, follows the seasonal precautions, and can record the treatment and clean up the medical waste.","Independently plans early-morning work in summer, and in winter prepares the tools first to minimize time away from the heat lamp, and keeps records.","Understands the seasonal risks (flies, maggots, frostbite), and can teach new staff the preparation and how to keep records."],"levels_vi":["Làm vào giờ nắng nóng gây gánh nặng cho lợn con, không ghi chép việc xử lý cũng không dọn dẹp.","Nếu có chỉ dẫn thì làm theo, nhưng đưa về đèn sưởi bị chậm, hay bỏ sót ghi chép.","Nếu có chỉ dẫn thì giữ các chú ý theo mùa để thực hiện, ghi chép việc xử lý và dọn rác y tế được.","Không cần chỉ dẫn cũng mùa hè sắp xếp làm sáng sớm, mùa đông chuẩn bị dụng cụ trước để rút ngắn tối đa thời gian xa đèn sưởi, và ghi chép lại.","Hiểu rủi ro theo mùa (ruồi, giòi, tê cóng), và có thể hướng dẫn người mới cách sắp xếp và cách ghi chép."],"levels_id":["Bekerja di jam panas sehingga membebani anak babi, dan tidak mencatat tindakan maupun membereskannya.","Jika ada instruksi menangani, tetapi terlambat mengembalikan ke lampu penghangat dan banyak catatan yang terlewat.","Jika ada instruksi, melaksanakan dengan mematuhi perhatian musiman, dan bisa mencatat tindakan serta membereskan limbah medis.","Tanpa instruksi pun, di musim panas mengatur kerja pagi-pagi, di musim dingin menyiapkan alat lebih dulu agar waktu jauh dari lampu penghangat sesingkat mungkin, dan meninggalkan catatan.","Memahami risiko tiap musim (lalat, belatung, radang dingin), dan bisa mengajari karyawan baru pengaturannya dan cara menyimpan catatan."]}],"name_en":"Castration","name_vi":"Thiến lợn con","name_id":"Kastrasi anak babi","purposeShort_en":"Produce pork free of boar taint, reduce fighting and mounting, and make group management safer","purposeShort_vi":"Sản xuất thịt lợn không có mùi hôi đực, giảm đánh nhau và nhảy lên nhau, quản lý đàn an toàn hơn","purposeShort_id":"Menghasilkan daging babi tanpa bau pejantan, mengurangi perkelahian dan menunggangi, membuat pengelolaan kelompok lebih aman"},{"id":"additive","category":"feeding","no":"No.18","name":"添加剤準備","purposeShort":"添加剤の効果をムラなく出し、豚の健康・成績を安定させる","gyomu":"18","aspects":[{"id":"dosage-mix","name":"正確な計量と混合","kanten":"ラベルの対象・添加量を守り、正確に計量してムラなく混合できるか。","levels":["計量器を確かめず目分量で入れ、混合手順を省いてムラを出す。","指示があれば計量するが、秤のゼロ調整（風袋引き）や量った数値の声出し確認に漏れがある。","指示があればラベルの添加量に従って計量し、ひと通り混合できる。","指示がなくても計量器を確かめて正確に計り、指示された方法でムラなく混合し、計量後すぐ容器にラベルを貼る。","計量誤差・混合ムラが成績に与える影響を理解し、正確な準備手順を新人に指導できる。"],"name_en":"Accurate measurement and mixing","name_vi":"Cân đo chính xác và trộn đều","name_id":"Penakaran akurat dan pencampuran","kanten_en":"Can they follow the label's target animals and inclusion rate, measure accurately, and mix evenly?","kanten_vi":"Có giữ đúng đối tượng và lượng bổ sung ghi trên nhãn, cân đo chính xác và trộn đều không.","kanten_id":"Apakah mematuhi sasaran dan dosis pada label, menakar dengan akurat, dan mencampur secara merata.","levels_en":["Adds by eye without checking the scale and skips mixing steps, causing uneven distribution.","With guidance, measures, but often misses zeroing the scale (tare) or calling out the measured value.","With guidance, measures according to the label's inclusion rate and can mix adequately.","Independently verifies the scale, measures accurately, mixes evenly by the instructed method, and labels the container right after weighing.","Understands how measurement errors and uneven mixing affect performance, and can teach new staff accurate preparation procedures."],"levels_vi":["Không kiểm tra dụng cụ cân, đổ theo ước lượng bằng mắt, bỏ bước trộn làm trộn không đều.","Nếu có chỉ dẫn thì cân đo, nhưng hay bỏ sót việc chỉnh cân về 0 (trừ bì) và đọc to số đã cân để xác nhận.","Nếu có chỉ dẫn thì cân đo theo lượng bổ sung trên nhãn, trộn được các bước cơ bản.","Không cần chỉ dẫn cũng kiểm tra dụng cụ cân, cân chính xác, trộn đều theo cách được chỉ định và dán nhãn lên hộp ngay sau khi cân.","Hiểu sai số cân đo và trộn không đều ảnh hưởng đến thành tích, và có thể hướng dẫn người mới quy trình chuẩn bị chính xác."],"levels_id":["Memasukkan dengan kira-kira tanpa memeriksa alat takar, dan melewatkan langkah pencampuran sehingga tidak merata.","Jika ada instruksi bisa menakar, tetapi sering lalai menolkan timbangan (tara) dan menyebutkan angka takaran dengan suara keras.","Jika ada instruksi, bisa menakar sesuai dosis pada label dan mencampur secara garis besar.","Tanpa instruksi pun, memeriksa alat takar dan menakar dengan akurat, mencampur merata sesuai cara yang diinstruksikan, dan menempel label pada wadah segera setelah menakar.","Memahami pengaruh kesalahan takaran dan campuran tidak merata terhadap performa, dan bisa mengajari karyawan baru urutan persiapan yang akurat."]},{"id":"antibacterial","name":"抗菌性添加物の休薬管理","kanten":"休薬期間のある添加剤について、投与開始日・終了日を記録し、出荷予定日と照らして休薬を管理できるか。","levels":["休薬期間のある添加剤の投与開始日・終了日を記録せず、出荷予定日とも照らさず、残留リスクを招く。","指示があれば注意するが、投与開始日・終了日の記録や出荷予定日との照合に漏れが多い。","指示があれば休薬期間のある添加剤の投与開始日・終了日を記録できる。","指示がなくても投与開始日・終了日を記録し、出荷予定日と照らして休薬を管理する。","残留リスクと休薬の意味を理解し、抗菌性添加物の管理ルールを新人に指導できる。"],"name_en":"Managing withdrawal of antibacterial additives","name_vi":"Quản lý thời gian ngừng thuốc của chất bổ sung kháng khuẩn","name_id":"Pengelolaan masa henti obat imbuhan antibakteri","kanten_en":"For additives with a withdrawal period, can they record the start and end dates and manage withdrawal against the planned shipping date?","kanten_vi":"Với chất bổ sung có thời gian ngừng thuốc, có ghi ngày bắt đầu, ngày kết thúc và đối chiếu với ngày dự kiến xuất chuồng để quản lý ngừng thuốc không.","kanten_id":"Untuk imbuhan bermasa henti obat, apakah mencatat tanggal mulai dan selesai serta mengelola masa henti obat dengan mencocokkan rencana tanggal kirim.","levels_en":["Does not record the start and end dates of additives with a withdrawal period or check them against the planned shipping date, creating residue risk.","With guidance, pays attention, but often misses recording start and end dates or checking against the planned shipping date.","With guidance, can record the start and end dates of additives with a withdrawal period.","Independently records start and end dates and manages withdrawal against the planned shipping date.","Understands residue risk and the meaning of withdrawal periods, and can teach new staff the rules for managing antibacterial additives."],"levels_vi":["Không ghi ngày bắt đầu và ngày kết thúc của chất bổ sung có thời gian ngừng thuốc, không đối chiếu với ngày dự kiến xuất chuồng, gây nguy cơ tồn dư thuốc.","Nếu có chỉ dẫn thì chú ý, nhưng hay bỏ sót việc ghi ngày bắt đầu, ngày kết thúc và đối chiếu với ngày dự kiến xuất chuồng.","Nếu có chỉ dẫn thì ghi được ngày bắt đầu và ngày kết thúc của chất bổ sung có thời gian ngừng thuốc.","Không cần chỉ dẫn cũng ghi ngày bắt đầu, ngày kết thúc và đối chiếu với ngày dự kiến xuất chuồng để quản lý ngừng thuốc.","Hiểu nguy cơ tồn dư và ý nghĩa của việc ngừng thuốc, và có thể hướng dẫn người mới quy tắc quản lý chất bổ sung kháng khuẩn."],"levels_id":["Tidak mencatat tanggal mulai dan selesai imbuhan bermasa henti obat dan tidak mencocokkannya dengan rencana tanggal kirim, sehingga menimbulkan risiko residu obat.","Jika ada instruksi bisa berhati-hati, tetapi sering lalai mencatat tanggal mulai dan selesai serta mencocokkan dengan rencana tanggal kirim.","Jika ada instruksi, bisa mencatat tanggal mulai dan selesai imbuhan bermasa henti obat.","Tanpa instruksi pun, mencatat tanggal mulai dan selesai serta mengelola masa henti obat dengan mencocokkan rencana tanggal kirim.","Memahami risiko residu dan arti masa henti obat, dan bisa mengajari karyawan baru aturan pengelolaan imbuhan antibakteri."]},{"id":"instruction-verify","name":"指示・ラベル・状態の照合","kanten":"「どの豚群に・何を・どれだけ」の3点と対象家畜・有効期限・中身の状態を確かめてから始められるか。","levels":["指示書やラベルを確かめずに始め、期限切れや固まった添加剤も使ってしまう。","指示があれば確認するが、対象ステージや有効期限の見落としが多い。","指示があれば3点とラベルの対象家畜・添加量を照合し、異常品を使わずにおける。","指示がなくても毎回照合し、1つでも分からなければ始めずに責任者に聞き、異常品は分けて報告する。","対象家畜違い・変質品を使うリスクを理解し、作業前の照合手順を新人に指導できる。"],"name_en":"Verifying instructions, labels, and condition","name_vi":"Đối chiếu chỉ thị, nhãn và tình trạng","name_id":"Mencocokkan instruksi, label, dan kondisi","kanten_en":"Can they confirm the three points \"which pig group, what, and how much\" plus the target animal species, expiry date, and the contents' condition before starting?","kanten_vi":"Có kiểm tra 3 điểm \"cho nhóm lợn nào, thứ gì, bao nhiêu\" cùng loài vật nuôi đối tượng, hạn sử dụng và tình trạng bên trong rồi mới bắt đầu không.","kanten_id":"Apakah memastikan 3 hal \"untuk kelompok babi mana, apa, berapa banyak\" beserta hewan sasaran, tanggal kedaluwarsa, dan kondisi isinya sebelum mulai.","levels_en":["Starts without checking the instruction sheet or label, and even uses expired or caked additives.","Confirms when instructed, but often overlooks the target stage and the expiry date.","With guidance, can verify the three points against the label's target species and inclusion rate, and set aside abnormal products without using them.","Independently verifies every time; if even one point is unclear, does not start and asks the person in charge, and separates and reports abnormal products.","Understands the risks of using products for the wrong species or spoiled products, and can teach new staff the pre-work verification steps."],"levels_vi":["Không xem phiếu chỉ thị hay nhãn mà đã bắt đầu, dùng cả chất bổ sung hết hạn hay bị vón cục.","Nếu có chỉ dẫn thì kiểm tra, nhưng hay bỏ sót giai đoạn đối tượng và hạn sử dụng.","Nếu có chỉ dẫn thì đối chiếu 3 điểm với loài vật nuôi đối tượng và lượng trộn trên nhãn, hàng bất thường để riêng không dùng được.","Không cần chỉ dẫn cũng đối chiếu mỗi lần; chỉ cần 1 điểm không rõ thì không bắt đầu mà hỏi người phụ trách, hàng bất thường để riêng và báo cáo.","Hiểu rủi ro dùng nhầm loài vật nuôi hay dùng hàng biến chất, và có thể hướng dẫn người mới trình tự đối chiếu trước khi làm."],"levels_id":["Mulai tanpa memeriksa lembar instruksi atau label, dan bahkan memakai imbuhan yang kedaluwarsa atau menggumpal.","Jika ada instruksi memastikan, tetapi sering melewatkan tahap sasaran dan tanggal kedaluwarsa.","Jika ada instruksi, bisa mencocokkan 3 hal itu dengan hewan sasaran dan takaran di label, dan menyisihkan produk yang tidak normal tanpa memakainya.","Tanpa instruksi pun, mencocokkan setiap kali; jika ada satu saja yang tidak jelas, tidak memulai melainkan bertanya ke penanggung jawab, dan memisahkan serta melaporkan produk yang tidak normal.","Memahami risiko salah hewan sasaran atau memakai produk rusak, dan bisa mengajari karyawan baru langkah pencocokan sebelum bekerja."]},{"id":"ppe-dust","name":"防護具と粉のあつかい","kanten":"マスク・手袋（必要なら防護メガネ）を着け、こぼした粉をすぐ片づけ、作業後に手を洗えるか。","levels":["防護具を着けずに粉を吸い込み、こぼした粉も放置する。","指示があれば着けるが、防護メガネの使い分けや作業後の手洗いを忘れがち。","指示があればマスク・手袋を着けて作業し、こぼした粉を片づけられる。","指示がなくても薬剤に応じて防護具を選び、粉を舞わせない扱いと石けんでの手洗いを徹底する。","粉じんの吸入や薬剤付着のリスクを理解し、防護のルールを新人に指導できる。"],"name_en":"Protective gear and handling powder","name_vi":"Đồ bảo hộ và cách xử lý bột","name_id":"Alat pelindung dan penanganan serbuk","kanten_en":"Can they wear a mask and gloves (and goggles when needed), promptly clean up spilled powder, and wash their hands after the work?","kanten_vi":"Có đeo khẩu trang, găng tay (khi cần thì kính bảo hộ), bột đổ ra dọn ngay, và rửa tay sau khi làm không.","kanten_id":"Apakah memakai masker dan sarung tangan (kacamata pelindung jika perlu), segera membereskan serbuk yang tumpah, dan mencuci tangan setelah bekerja.","levels_en":["Inhales powder without wearing protective gear, and leaves spilled powder as it is.","Wears them when instructed, but tends to forget when goggles are needed and to skip washing hands afterward.","With guidance, works wearing a mask and gloves, and can clean up spilled powder.","Independently chooses protective gear according to the product, handles powder without raising dust, and always washes hands with soap.","Understands the risks of inhaling dust and skin contact with the products, and can teach new staff the protection rules."],"levels_vi":["Không đeo đồ bảo hộ nên hít phải bột, bột đổ ra cũng bỏ mặc.","Nếu có chỉ dẫn thì đeo, nhưng hay quên khi nào cần kính bảo hộ và quên rửa tay sau khi làm.","Nếu có chỉ dẫn thì đeo khẩu trang, găng tay khi làm, và dọn được bột đổ ra.","Không cần chỉ dẫn cũng chọn đồ bảo hộ theo loại thuốc, thao tác không làm bột bay lên, và luôn rửa tay bằng xà phòng.","Hiểu rủi ro hít phải bụi bột và thuốc dính vào người, và có thể hướng dẫn người mới quy tắc bảo hộ."],"levels_id":["Menghirup serbuk karena tidak memakai alat pelindung, dan membiarkan serbuk yang tumpah.","Jika ada instruksi memakainya, tetapi sering lupa kapan perlu kacamata pelindung dan lupa mencuci tangan sesudahnya.","Jika ada instruksi, bekerja dengan masker dan sarung tangan, dan bisa membereskan serbuk yang tumpah.","Tanpa instruksi pun, memilih alat pelindung sesuai bahannya, menangani serbuk tanpa membuatnya beterbangan, dan selalu mencuci tangan dengan sabun.","Memahami risiko menghirup debu dan terkena bahan di kulit, dan bisa mengajari karyawan baru aturan perlindungannya."]},{"id":"mixup-storage","name":"取り違え防止と保管・器具清掃","kanten":"計量した容器に豚群名・剤名・量のメモをはり、計量後すぐラベルを貼って保管し、器具に粉を残さないか。","levels":["表示のない粉を平気で使い、袋を開けっぱなしにし、器具に粉が残ったまま次に使う。","指示があればメモをはるが、ラベル貼りや保管場所への戻しに漏れが多い。","指示があればメモをはって管理し、袋の口を閉じて決められた場所に戻し、器具を掃除できる。","指示がなくても書いていない粉は使わず、直射日光と湿気を避けて保管し、器具の粉残りをゼロにする。","白い粉の取り違えと前の添加剤の混入リスクを理解し、表示・保管・清掃のルールを新人に指導できる。"],"name_en":"Preventing mix-ups, storage, and tool cleaning","name_vi":"Chống nhầm lẫn, bảo quản và vệ sinh dụng cụ","name_id":"Mencegah tertukar, penyimpanan, dan pembersihan alat","kanten_en":"Do they stick a memo with the pig group, product name, and amount on the measured container, label it right after weighing for storage, and leave no powder on the tools?","kanten_vi":"Có dán ghi chú tên nhóm lợn, tên thuốc, lượng lên hộp đã cân, dán nhãn ngay sau khi cân để bảo quản, và không để bột sót lại trên dụng cụ không.","kanten_id":"Apakah menempelkan memo nama kelompok babi, nama produk, dan jumlah pada wadah yang sudah ditakar, menempel label segera setelah menakar untuk penyimpanan, dan tidak meninggalkan serbuk di alat.","levels_en":["Casually uses unlabeled powder, leaves bags open, and uses tools next time with powder still on them.","Sticks memos when instructed, but often fails to label right after weighing or return items to the storage place.","With guidance, can manage with memos, close the bag opening, return items to the designated place, and clean the tools.","Independently never uses unlabeled powder, stores away from direct sunlight and humidity, and leaves zero powder residue on the tools.","Understands the risks of mixing up white powders and contamination from previous additives, and can teach new staff the labeling, storage, and cleaning rules."],"levels_vi":["Bột không ghi gì vẫn thản nhiên dùng, mở bao để nguyên, dụng cụ còn dính bột vẫn dùng cho lần sau.","Nếu có chỉ dẫn thì dán ghi chú, nhưng hay bỏ sót việc dán nhãn ngay sau khi cân và cất về chỗ bảo quản.","Nếu có chỉ dẫn thì dán ghi chú để quản lý, đóng miệng bao, cất về chỗ quy định và vệ sinh dụng cụ được.","Không cần chỉ dẫn cũng không dùng bột không ghi gì, bảo quản tránh nắng trực tiếp và ẩm, dụng cụ không còn sót chút bột nào.","Hiểu rủi ro nhầm các loại bột trắng và lẫn chất bổ sung lần trước, và có thể hướng dẫn người mới quy tắc ghi nhãn, bảo quản, vệ sinh."],"levels_id":["Dengan santai memakai serbuk tanpa label, membiarkan karung terbuka, dan memakai alat yang masih ada serbuknya untuk pekerjaan berikutnya.","Jika ada instruksi menempel memo, tetapi sering lalai menempel label segera setelah menakar dan mengembalikan ke tempat penyimpanan.","Jika ada instruksi, bisa mengelola dengan memo, menutup mulut karung, mengembalikan ke tempat yang ditentukan, dan membersihkan alat.","Tanpa instruksi pun, tidak memakai serbuk tanpa tulisan, menyimpan terhindar dari sinar matahari langsung dan lembap, dan memastikan tidak ada serbuk tersisa di alat.","Memahami risiko tertukarnya serbuk putih dan tercampurnya imbuhan sebelumnya, dan bisa mengajari karyawan baru aturan pelabelan, penyimpanan, dan pembersihan."]}],"name_en":"Additive preparation","name_vi":"Chuẩn bị chất bổ sung (trộn vào thức ăn)","name_id":"Persiapan imbuhan pakan (dicampur ke pakan)","purposeShort_en":"Deliver the effects of additives evenly and stabilize pig health and performance","purposeShort_vi":"Giúp chất bổ sung phát huy hiệu quả đều, giữ sức khỏe và thành tích của lợn ổn định","purposeShort_id":"Mengeluarkan efek imbuhan pakan secara merata, menstabilkan kesehatan dan performa babi"},{"id":"feed-adjust-fin","category":"feeding","no":"","name":"エサ調整（肥育）","purposeShort":"肥育豚の飼料の出量と切り替えを調整し、こぼれやムダを防いで増体と飼料効率を保つ","gyomu":"","aspects":[{"id":"feeder-spill","name":"エサ箱の出量調整とこぼれの確認","kanten":"エサ箱の飼料の出量を見て、床へのこぼれや詰まりがないように、多すぎず少なすぎない量へ調整できるか。","levels":["エサ箱を見ず、飼料が床にこぼれていても、詰まっていても放置する。","指示があればエサ箱を見るが、こぼれや詰まりに気づくのが遅く、調整は他者まかせ。","指示があればエサ箱の出量を調整し、床へのこぼれや詰まりがないか確認できる。","指示がなくても毎回の給餌でこぼれ・詰まり・出量不足（空腹）を見つけ、その場で出量を調整する。","こぼれが飼料のムダと飼料効率の悪化につながることを理解し、エサ箱の調整の要点を新人に指導できる。"],"name_en":"Adjusting the feeder output and checking for spillage","name_vi":"Điều chỉnh lượng thức ăn ra ở máng và kiểm tra thức ăn rơi vãi","name_id":"Penyesuaian keluaran pakan di tempat pakan dan pemeriksaan pakan tercecer","kanten_en":"Can they look at how much feed comes out of the feeder and adjust it to neither too much nor too little, so that feed does not spill on the floor or clog?","kanten_vi":"Có xem lượng thức ăn ra ở máng và điều chỉnh sao cho không nhiều quá, không ít quá, để thức ăn không rơi vãi xuống sàn hay bị tắc không.","kanten_id":"Apakah bisa melihat jumlah pakan yang keluar dari tempat pakan dan menyesuaikannya agar tidak terlalu banyak atau terlalu sedikit, sehingga pakan tidak tercecer ke lantai atau tersumbat.","levels_en":["Does not look at the feeders and leaves feed spilled on the floor or clogged.","Looks at the feeders when instructed, but is slow to notice spillage or clogging and leaves the adjustment to others.","With guidance, can adjust the feeder output and check for spillage on the floor and clogging.","Independently finds spillage, clogging, or too little output (hungry pigs) at every feeding and adjusts the output on the spot.","Understands that spillage means wasted feed and worse feed efficiency, and can teach new staff the key points of feeder adjustment."],"levels_vi":["Không xem máng ăn, thức ăn rơi vãi xuống sàn hay bị tắc cũng bỏ mặc.","Nếu có chỉ dẫn thì xem máng ăn, nhưng chậm nhận ra thức ăn rơi vãi hay bị tắc, việc điều chỉnh phó mặc cho người khác.","Nếu có chỉ dẫn thì điều chỉnh được lượng thức ăn ra ở máng và kiểm tra thức ăn rơi xuống sàn và tình trạng tắc.","Không cần chỉ dẫn, mỗi lần cho ăn cũng tìm ra thức ăn rơi vãi, bị tắc hoặc ra quá ít (lợn đói) và điều chỉnh lượng ra ngay tại chỗ.","Hiểu rằng thức ăn rơi vãi là lãng phí và làm xấu hiệu quả sử dụng thức ăn, và có thể hướng dẫn người mới các điểm chính khi điều chỉnh máng ăn."],"levels_id":["Tidak melihat tempat pakan, pakan tercecer di lantai atau tersumbat pun dibiarkan.","Jika ada instruksi melihat tempat pakan, tetapi lambat menyadari pakan tercecer atau tersumbat dan penyesuaian diserahkan ke orang lain.","Jika ada instruksi, bisa menyesuaikan keluaran pakan di tempat pakan dan memeriksa pakan tercecer di lantai serta sumbatan.","Tanpa instruksi pun, di setiap pemberian pakan menemukan pakan tercecer, sumbatan, atau keluaran terlalu sedikit (babi lapar) dan langsung menyesuaikan keluarannya.","Memahami bahwa pakan tercecer berarti pakan terbuang dan efisiensi pakan memburuk, dan bisa mengajari karyawan baru poin penting penyesuaian tempat pakan."]},{"id":"feed-switch","name":"飼料の切り替えと段階的な混合","kanten":"体重帯に合った飼料を間違えずに使い、切り替えを5〜7日かけて旧飼料と新飼料を混ぜて進め、その間の糞を確かめられるか。","levels":["飼料の種類や体重帯を確かめず、急に切り替えて、糞の状態も見ない。","指示があれば飼料を切り替えるが、混ぜる割合や日数を守れず、糞の確認も漏れる。","指示があれば飼料を間違えずに使い、5〜7日かけて旧飼料の割合を減らしながら切り替えられる。","指示がなくても体重帯に合った飼料かを確かめ、段階的に混ぜて切り替え、下痢が出たら切り替えを遅くして報告する。","急な切り替えが消化不良と下痢につながることを理解し、体重帯ごとの飼料と混合の手順を新人に指導できる。"],"name_en":"Switching feed and mixing it in steps","name_vi":"Chuyển đổi thức ăn và trộn dần từng bước","name_id":"Penggantian pakan dan pencampuran bertahap","kanten_en":"Can they use the right feed for the weight range without mistakes, switch over in 5 to 7 days by mixing old and new feed, and check the dung during the switch?","kanten_vi":"Có dùng đúng loại thức ăn theo khoảng cân nặng không nhầm, chuyển đổi trong 5 đến 7 ngày bằng cách trộn thức ăn cũ và mới, và kiểm tra phân trong thời gian đó không.","kanten_id":"Apakah bisa memakai pakan yang sesuai dengan kisaran berat badan tanpa keliru, mengganti pakan selama 5 sampai 7 hari dengan mencampur pakan lama dan baru, dan memeriksa kotoran selama itu.","levels_en":["Does not check the feed type or weight range, switches suddenly, and does not look at the dung.","Switches feed when instructed, but does not keep to the mixing ratio or the number of days and misses checking the dung.","With guidance, uses the right feed without mistakes and switches over in 5 to 7 days while reducing the share of the old feed.","Independently checks that the feed suits the weight range, switches by mixing in steps, and slows the switch and reports if diarrhea appears.","Understands that a sudden switch leads to poor digestion and diarrhea, and can teach new staff the feed for each weight range and the mixing steps."],"levels_vi":["Không kiểm tra loại thức ăn hay khoảng cân nặng, chuyển đột ngột và cũng không xem phân.","Nếu có chỉ dẫn thì chuyển đổi thức ăn, nhưng không giữ đúng tỷ lệ trộn và số ngày, bỏ sót việc kiểm tra phân.","Nếu có chỉ dẫn thì dùng đúng thức ăn không nhầm, và chuyển đổi trong 5 đến 7 ngày trong khi giảm dần tỷ lệ thức ăn cũ.","Không cần chỉ dẫn cũng kiểm tra thức ăn có hợp khoảng cân nặng không, trộn dần để chuyển đổi, nếu bị tiêu chảy thì chuyển chậm lại và báo cáo.","Hiểu rằng chuyển đột ngột dẫn đến khó tiêu và tiêu chảy, và có thể hướng dẫn người mới thức ăn theo từng khoảng cân nặng và các bước trộn."],"levels_id":["Tidak memeriksa jenis pakan atau kisaran berat badan, mengganti mendadak, dan tidak melihat kotoran.","Jika ada instruksi bisa mengganti pakan, tetapi tidak menaati rasio campuran dan jumlah hari, serta terlewat memeriksa kotoran.","Jika ada instruksi, bisa memakai pakan yang benar tanpa keliru dan mengganti selama 5 sampai 7 hari sambil mengurangi porsi pakan lama.","Tanpa instruksi pun, memeriksa apakah pakan sesuai kisaran berat badan, mengganti dengan pencampuran bertahap, dan jika muncul diare, memperlambat penggantian dan melapor.","Memahami bahwa penggantian mendadak menyebabkan gangguan pencernaan dan diare, dan bisa mengajari karyawan baru pakan tiap kisaran berat badan dan langkah pencampurannya."]},{"id":"feeder-line","name":"自動給餌器・配管・飼料タンクの点検","kanten":"自動給餌器の出量とセンサー、配管の詰まり、飼料タンクの残量とブリッジ、飼料の変色・カビ・異臭を確かめられるか。","levels":["自動給餌器・配管・タンクを見ず、詰まりや飼料切れ、カビが出ても気づかない。","指示があれば点検するが、タンクの残量確認やブリッジの見落としが多く、異常は他者に見つけてもらう。","指示があれば自動給餌器の出量とセンサー、配管の詰まり、タンクの残量を確認できる。","指示がなくても毎日、出量・センサー・配管・タンク残量を確かめ、飼料が出ない時はブリッジを疑い、変色・カビ・異臭を見つけて報告する。","飼料切れが成長停止や尾かじりにつながることを理解し、残量が農場で決めた発注点になったら発注するなど、点検の要点を新人に指導できる。"],"name_en":"Checking the automatic feeder, piping, and feed tank","name_vi":"Kiểm tra máy cho ăn tự động, đường ống và silo thức ăn","name_id":"Pemeriksaan pemberi pakan otomatis, pipa, dan tangki pakan","kanten_en":"Can they check the automatic feeder output and sensors, clogging in the piping, the feed tank level and bridging, and discoloration, mold, or odor in the feed?","kanten_vi":"Có kiểm tra lượng ra và cảm biến của máy cho ăn tự động, đường ống có bị tắc không, lượng còn lại và hiện tượng vón cục (bridge) trong silo, cùng thức ăn có đổi màu, mốc, có mùi lạ không.","kanten_id":"Apakah bisa memeriksa keluaran dan sensor pemberi pakan otomatis, sumbatan pipa, sisa dan pakan menggumpal (bridge) di tangki pakan, serta perubahan warna, jamur, atau bau pada pakan.","levels_en":["Does not look at the automatic feeder, piping, or tank, and does not notice clogging, running out of feed, or mold.","Checks when instructed, but often misses the tank level and bridging, and relies on others to find problems.","With guidance, can check the automatic feeder output and sensors, clogging in the piping, and the tank level.","Independently checks output, sensors, piping, and tank level every day, suspects bridging when feed does not come out, and finds and reports discoloration, mold, or odor.","Understands that running out of feed leads to stopped growth and tail biting, and can teach new staff the key points of checking, such as ordering when the stock reaches the reorder point set by the farm."],"levels_vi":["Không xem máy cho ăn tự động, đường ống hay silo, bị tắc, hết thức ăn hay bị mốc cũng không nhận ra.","Nếu có chỉ dẫn thì kiểm tra, nhưng hay bỏ sót việc xem lượng còn lại trong silo và hiện tượng vón cục, phải nhờ người khác phát hiện bất thường.","Nếu có chỉ dẫn thì kiểm tra được lượng ra và cảm biến của máy cho ăn tự động, đường ống có tắc không và lượng còn lại trong silo.","Không cần chỉ dẫn, mỗi ngày cũng kiểm tra lượng ra, cảm biến, đường ống, lượng còn lại trong silo, khi thức ăn không ra thì nghi vón cục, và phát hiện thức ăn đổi màu, mốc, có mùi lạ rồi báo cáo.","Hiểu rằng hết thức ăn dẫn đến ngừng tăng trưởng và cắn đuôi, và có thể hướng dẫn người mới các điểm chính khi kiểm tra, như đặt hàng khi lượng còn lại chạm mức đặt hàng mà trại đã quy định."],"levels_id":["Tidak melihat pemberi pakan otomatis, pipa, atau tangki, dan tidak menyadari sumbatan, pakan habis, atau jamur.","Jika ada instruksi memeriksa, tetapi sering terlewat memeriksa sisa tangki dan pakan menggumpal, dan masalah ditemukan oleh orang lain.","Jika ada instruksi, bisa memeriksa keluaran dan sensor pemberi pakan otomatis, sumbatan pipa, dan sisa pakan di tangki.","Tanpa instruksi pun, setiap hari memeriksa keluaran, sensor, pipa, dan sisa tangki, mencurigai pakan menggumpal saat pakan tidak keluar, serta menemukan dan melaporkan perubahan warna, jamur, atau bau.","Memahami bahwa pakan habis menyebabkan pertumbuhan berhenti dan menggigit ekor, dan bisa mengajari karyawan baru poin penting pemeriksaan, misalnya memesan saat sisa pakan mencapai batas pemesanan yang ditetapkan peternakan."]},{"id":"eating-observe","name":"食い込みの観察と環境要因の確認","kanten":"給餌のたびに豚の集まりとエサ箱の食べ残しを見て、特定の豚房だけ食い込みが悪い時に温度・飲水・密度を確かめられるか。","levels":["給餌しても豚の集まりや食べ残しを見ず、食い込みが悪い豚房があっても気づかない。","指示があれば食べ残しを見るが、豚房ごとの違いに気づくのが遅く、原因の確認は他者まかせ。","指示があれば豚がエサ箱に集まるか、底が見えるまで食べているかを確認できる。","指示がなくても豚房ごとの食い込みを見分け、悪い豚房では温度・飲水・密度を確かめて、気づいたことを報告する。","暑さや水不足、過密が食欲を落とすことを理解し、食い込みから群の異常を早く見つける見方を新人に指導できる。"],"name_en":"Observing how well the pigs eat and checking environmental factors","name_vi":"Quan sát việc ăn và kiểm tra các yếu tố môi trường","name_id":"Pengamatan nafsu makan dan pemeriksaan faktor lingkungan","kanten_en":"Can they watch the pigs gathering and the leftover feed in the feeders at every feeding, and check temperature, drinking water, and density when only certain pens eat poorly?","kanten_vi":"Mỗi lần cho ăn có xem lợn tụ tập và thức ăn thừa trong máng, và khi chỉ một số ô ăn kém thì kiểm tra nhiệt độ, nước uống, mật độ không.","kanten_id":"Apakah setiap pemberian pakan melihat babi yang berkumpul dan sisa pakan di tempat pakan, dan jika hanya kandang tertentu yang makan buruk, memeriksa suhu, air minum, dan kepadatan.","levels_en":["Does not watch the pigs gathering or the leftover feed at feeding, and does not notice pens that eat poorly.","Looks at the leftover feed when instructed, but is slow to notice differences between pens and leaves checking the cause to others.","With guidance, can check whether the pigs gather at the feeder and eat until the bottom of the feeder is visible.","Independently tells how well each pen eats, checks temperature, drinking water, and density in pens that eat poorly, and reports what they noticed.","Understands that heat, lack of water, and overcrowding reduce appetite, and can teach new staff how to spot problems in the group early from how well they eat."],"levels_vi":["Cho ăn mà không xem lợn tụ tập hay thức ăn thừa, ô ăn kém cũng không nhận ra.","Nếu có chỉ dẫn thì xem thức ăn thừa, nhưng chậm nhận ra sự khác nhau giữa các ô, việc kiểm tra nguyên nhân phó mặc cho người khác.","Nếu có chỉ dẫn thì kiểm tra được lợn có tụ tập ở máng không, và có ăn đến khi thấy đáy máng không.","Không cần chỉ dẫn cũng phân biệt được việc ăn của từng ô, ô ăn kém thì kiểm tra nhiệt độ, nước uống, mật độ, và báo cáo điều nhận thấy.","Hiểu rằng nóng, thiếu nước và nuôi quá chật làm giảm ngon miệng, và có thể hướng dẫn người mới cách sớm phát hiện bất thường của đàn từ việc ăn."],"levels_id":["Tidak melihat babi berkumpul atau sisa pakan saat memberi pakan, dan tidak menyadari kandang yang makannya buruk.","Jika ada instruksi melihat sisa pakan, tetapi lambat menyadari perbedaan antar kandang dan pemeriksaan penyebab diserahkan ke orang lain.","Jika ada instruksi, bisa memeriksa apakah babi berkumpul di tempat pakan dan makan sampai dasar tempat pakan terlihat.","Tanpa instruksi pun, membedakan cara makan tiap kandang, memeriksa suhu, air minum, dan kepadatan di kandang yang makannya buruk, serta melaporkan yang disadari.","Memahami bahwa panas, kekurangan air, dan kepadatan berlebih menurunkan nafsu makan, dan bisa mengajari karyawan baru cara menemukan kelainan kelompok lebih awal dari cara makan."]},{"id":"adjust-record","name":"調整の記録と休薬期間の確認・報告","kanten":"飼料の切り替えや出量の調整を記録し、休薬期間のある飼料は分からない時に確認して、異常を上長に報告できるか。","levels":["調整や切り替えを記録せず、休薬期間が分からなくても確認しないまま与える。","指示があれば記録するが、記録が抜けやすく、休薬期間の確認や異常の報告は他者まかせ。","指示があれば切り替えと出量の調整を記録し、休薬期間は飼料のラベルや添付文書で確認できる。","指示がなくても切り替え日・飼料の種類・タンク在庫を記録し、休薬期間が不明な時は必ず確認してから与え、異常はすぐ報告する。","休薬期間を守ることが法的義務であり、出荷停止につながることを理解し、記録と確認の手順を新人に指導できる。"],"name_en":"Recording adjustments, checking the withdrawal period, and reporting","name_vi":"Ghi chép điều chỉnh, kiểm tra thời gian ngừng thuốc và báo cáo","name_id":"Pencatatan penyesuaian, pemeriksaan masa henti obat, dan pelaporan","kanten_en":"Can they record feed switches and output adjustments, check the withdrawal period of feed that has one when they are unsure, and report problems to the supervisor?","kanten_vi":"Có ghi chép việc chuyển đổi thức ăn và điều chỉnh lượng ra, kiểm tra thời gian ngừng thuốc của thức ăn có thuốc khi chưa rõ, và báo cáo bất thường cho cấp trên không.","kanten_id":"Apakah bisa mencatat penggantian pakan dan penyesuaian keluaran, memeriksa masa henti obat pada pakan yang memilikinya saat tidak yakin, dan melaporkan kelainan kepada atasan.","levels_en":["Does not record adjustments or switches, and feeds without checking even when the withdrawal period is unknown.","Records when instructed, but records are often missing, and leaves checking the withdrawal period and reporting problems to others.","With guidance, records the switches and output adjustments and can check the withdrawal period on the feed label or package insert.","Independently records the switch date, feed type, and tank stock, always checks before feeding when the withdrawal period is unknown, and reports problems promptly.","Understands that keeping the withdrawal period is a legal duty and that violations can lead to a shipping ban, and can teach new staff the steps for recording and checking."],"levels_vi":["Không ghi chép việc điều chỉnh hay chuyển đổi, và dù không biết thời gian ngừng thuốc cũng cho ăn mà không kiểm tra.","Nếu có chỉ dẫn thì ghi chép, nhưng hay thiếu, việc kiểm tra thời gian ngừng thuốc và báo cáo bất thường phó mặc cho người khác.","Nếu có chỉ dẫn thì ghi chép việc chuyển đổi và điều chỉnh lượng ra, và kiểm tra được thời gian ngừng thuốc trên nhãn thức ăn hoặc tờ hướng dẫn kèm theo.","Không cần chỉ dẫn cũng ghi ngày chuyển đổi, loại thức ăn và tồn kho silo, khi chưa rõ thời gian ngừng thuốc thì nhất định kiểm tra rồi mới cho ăn, và báo cáo bất thường ngay.","Hiểu rằng giữ đúng thời gian ngừng thuốc là nghĩa vụ pháp lý và vi phạm có thể dẫn đến bị cấm xuất chuồng, và có thể hướng dẫn người mới các bước ghi chép và kiểm tra."],"levels_id":["Tidak mencatat penyesuaian atau penggantian, dan memberi pakan tanpa memeriksa walau masa henti obat tidak diketahui.","Jika ada instruksi mencatat, tetapi catatan sering terlewat, dan pemeriksaan masa henti obat serta pelaporan kelainan diserahkan ke orang lain.","Jika ada instruksi, mencatat penggantian dan penyesuaian keluaran, dan bisa memeriksa masa henti obat pada label pakan atau lembar petunjuk.","Tanpa instruksi pun, mencatat tanggal penggantian, jenis pakan, dan stok tangki, selalu memeriksa sebelum memberi pakan saat masa henti obat tidak jelas, dan segera melaporkan kelainan.","Memahami bahwa menaati masa henti obat adalah kewajiban hukum dan pelanggaran bisa berujung larangan pengiriman, dan bisa mengajari karyawan baru langkah pencatatan dan pemeriksaan."]}],"name_en":"Feed Adjustment (Finishing)","purposeShort_en":"Adjust the feed output and feed switches for finishing pigs, preventing spillage and waste to keep growth and feed efficiency","name_vi":"Điều chỉnh thức ăn (lợn thịt)","purposeShort_vi":"Điều chỉnh lượng thức ăn ra và việc chuyển đổi thức ăn cho lợn thịt, tránh rơi vãi và lãng phí để giữ tăng trọng và hiệu quả sử dụng thức ăn","name_id":"Penyesuaian pakan (penggemukan)","purposeShort_id":"Menyesuaikan keluaran dan penggantian pakan babi penggemukan, mencegah pakan tercecer dan terbuang untuk menjaga pertambahan berat dan efisiensi pakan"},{"id":"dung-removal","category":"hygiene","no":"No.12","name":"除フン","purposeShort":"病気・有害ガスを減らし豚の健康を守り、糞から異常を早期発見する","gyomu":"12","aspects":[{"id":"order","name":"除糞→洗浄→消毒の順序","kanten":"先に糞を取り除いてから洗浄・消毒する順序を守り、汚れの上から消毒しないか。","levels":["汚れが残ったまま消毒し、順序を守らず効果を半減させても気にしない。","指示があれば糞を取るが、洗浄・消毒の順序や仕上がりの確認に漏れが多い。","指示があれば先に糞を取り、その後に洗浄・消毒する順序をひと通り守れる。","指示がなくても順序を守り、汚れが残ると消毒が効かないことを踏まえて確実に除糞する。","汚れと消毒効果の関係を理解し、決められた頻度・タイミングと順序を新人に指導できる。"],"name_en":"Order of manure removal, washing, then disinfection","name_vi":"Thứ tự dọn phân → rửa → khử trùng","name_id":"Urutan bersihkan kotoran → cuci → disinfeksi","kanten_en":"Do they follow the order of removing manure first, then washing and disinfecting, and avoid disinfecting over dirt?","kanten_vi":"Có giữ thứ tự lấy phân đi trước rồi mới rửa và khử trùng, không khử trùng đè lên chỗ bẩn không.","kanten_id":"Apakah mematuhi urutan membersihkan kotoran dulu baru mencuci dan mendisinfeksi, dan tidak mendisinfeksi di atas kotoran.","levels_en":["Disinfects over remaining dirt, ignoring the correct order and not caring that this halves the effect.","With guidance, removes manure, but often skips steps in the washing and disinfection order and fails to check the result.","With guidance, can adequately follow the order of removing manure first, then washing and disinfecting.","Independently follows the order and removes manure thoroughly, knowing that disinfection does not work over remaining dirt.","Understands the relationship between dirt and disinfection efficacy, and can teach new staff the prescribed frequency, timing, and order."],"levels_vi":["Khử trùng khi chỗ bẩn còn nguyên, không giữ thứ tự làm hiệu quả giảm một nửa cũng không quan tâm.","Nếu có chỉ dẫn thì lấy phân, nhưng hay bỏ sót thứ tự rửa, khử trùng và việc kiểm tra kết quả.","Nếu có chỉ dẫn thì giữ được cơ bản thứ tự lấy phân trước, sau đó rửa và khử trùng.","Không cần chỉ dẫn cũng giữ thứ tự, dọn phân kỹ vì biết rằng còn bẩn thì khử trùng không có tác dụng.","Hiểu quan hệ giữa chỗ bẩn và hiệu quả khử trùng, và có thể hướng dẫn người mới tần suất, thời điểm quy định và thứ tự làm."],"levels_id":["Mendisinfeksi dengan kotoran masih menempel, tidak peduli walau urutan dilanggar dan efeknya berkurang setengah.","Jika ada instruksi bisa membersihkan kotoran, tetapi sering lalai soal urutan cuci-disinfeksi dan memeriksa hasil akhirnya.","Jika ada instruksi, bisa mematuhi urutan secara garis besar: bersihkan kotoran dulu, lalu cuci dan disinfeksi.","Tanpa instruksi pun, mematuhi urutan dan membersihkan kotoran dengan pasti, karena tahu disinfeksi tidak bekerja jika kotoran masih tersisa.","Memahami hubungan kotoran dengan efek disinfeksi, dan bisa mengajari karyawan baru frekuensi, waktu, dan urutan yang ditentukan."]},{"id":"underfloor","name":"床下・ピット・残渣の確認","kanten":"床下やピットまで定期的に確認し、スクレーパー動作後の残渣を目視で確かめられるか。","levels":["床下・ピットを確認せず、スクレーパー後の残渣も見ずに次工程へ進む。","指示があれば見えるところは確認するが、床下・ピットの点検に漏れが多い。","指示があれば床下やピットをひと通り確認できる。","指示がなくても床下・ピットを定期的に確認し、スクレーパー後の残渣を目視で確かめる。","残渣滞留のリスクを理解し、見落としやすい箇所の点検を新人に指導できる。"],"name_en":"Checking underfloor areas, pits, and residue","name_vi":"Kiểm tra dưới sàn, hố chứa phân và phân sót lại","name_id":"Pemeriksaan bawah lantai, pit, dan sisa kotoran","kanten_en":"Can they regularly check underfloor areas and pits, and visually confirm residue after the scraper has run?","kanten_vi":"Có kiểm tra định kỳ cả dưới sàn và hố chứa phân, nhìn tận mắt phân còn sót sau khi máy cào phân chạy không.","kanten_id":"Apakah memeriksa sampai bawah lantai dan pit secara berkala, dan memeriksa dengan mata sisa kotoran setelah alat pengeruk kotoran bekerja.","levels_en":["Does not check underfloor areas or pits, and moves to the next task without looking at residue after the scraper.","With guidance, checks visible areas, but often misses underfloor and pit inspections.","With guidance, can adequately check underfloor areas and pits.","Independently checks underfloor areas and pits regularly and visually confirms residue after the scraper.","Understands the risks of residue accumulation and can teach new staff how to inspect easily overlooked spots."],"levels_vi":["Không kiểm tra dưới sàn và hố chứa phân, cũng không nhìn phân sót sau khi máy cào phân chạy mà chuyển sang việc tiếp theo.","Nếu có chỉ dẫn thì kiểm tra chỗ nhìn thấy được, nhưng hay bỏ sót việc kiểm tra dưới sàn và hố chứa phân.","Nếu có chỉ dẫn thì kiểm tra được cơ bản dưới sàn và hố chứa phân.","Không cần chỉ dẫn cũng kiểm tra định kỳ dưới sàn và hố chứa phân, nhìn tận mắt phân còn sót sau khi máy cào phân chạy.","Hiểu nguy cơ khi phân ứ đọng, và có thể hướng dẫn người mới cách kiểm tra những chỗ dễ bỏ sót."],"levels_id":["Tidak memeriksa bawah lantai dan pit, dan lanjut ke pekerjaan berikutnya tanpa melihat sisa kotoran setelah alat pengeruk bekerja.","Jika ada instruksi bisa memeriksa bagian yang terlihat, tetapi sering lalai memeriksa bawah lantai dan pit.","Jika ada instruksi, bisa memeriksa bawah lantai dan pit secara garis besar.","Tanpa instruksi pun, memeriksa bawah lantai dan pit secara berkala, dan memeriksa dengan mata sisa kotoran setelah alat pengeruk bekerja.","Memahami risiko kotoran yang menumpuk, dan bisa mengajari karyawan baru pemeriksaan tempat-tempat yang mudah terlewat."]},{"id":"dung-observation","name":"糞の観察と異常便の即報告","kanten":"糞の色・かたさを見て、血便・水様下痢・黒色便などを豚房番号つきですぐ報告できるか。","levels":["糞を見ずに掃除だけで終わらせ、血便や下痢があっても気づかず放置する。","指示されれば糞を見るが、異常便の見分けや豚房番号の記録に漏れが多い。","指示があれば糞の色・かたさを確認し、異常便を見つけたら豚房番号を控えて報告できる。","指示がなくても除フンを健康チェックととらえ、血便・水様下痢・黒色便を早期に見つけて即報告する。","正常便と異常便の見分けと報告の優先度を理解し、「迷ったら報告」の姿勢を新人に指導できる。"],"name_en":"Observing manure and immediately reporting abnormal feces","name_vi":"Quan sát phân và báo cáo ngay phân bất thường","name_id":"Pengamatan kotoran dan segera melaporkan kotoran abnormal","kanten_en":"Can they look at the color and firmness of the manure and immediately report bloody stool, watery diarrhea, black stool, and the like with the pen number?","kanten_vi":"Có nhìn màu và độ cứng của phân, báo cáo ngay phân có máu, tiêu chảy nước, phân màu đen... kèm số ô chuồng không.","kanten_id":"Apakah melihat warna dan kekerasan kotoran, dan segera melaporkan kotoran berdarah, diare cair, kotoran berwarna hitam, dll. beserta nomor petak kandang.","levels_en":["Finishes with just cleaning without looking at the manure, and leaves bloody stool or diarrhea unnoticed.","Looks at the manure when instructed, but often fails to distinguish abnormal feces and record the pen number.","With guidance, checks the color and firmness of the manure, and can note the pen number and report when abnormal feces are found.","Independently treats manure removal as a health check, finding bloody stool, watery diarrhea, and black stool early and reporting immediately.","Understands how to distinguish normal from abnormal feces and the priority of reporting, and can teach new staff the attitude of \"when in doubt, report\"."],"levels_vi":["Chỉ dọn dẹp cho xong mà không nhìn phân, có phân có máu hay tiêu chảy cũng không nhận ra mà bỏ mặc.","Nếu được chỉ dẫn thì nhìn phân, nhưng hay bỏ sót việc phân biệt phân bất thường và ghi số ô chuồng.","Nếu có chỉ dẫn thì kiểm tra màu và độ cứng của phân, khi thấy phân bất thường thì ghi số ô chuồng và báo cáo được.","Không cần chỉ dẫn cũng coi việc dọn phân là kiểm tra sức khỏe, phát hiện sớm phân có máu, tiêu chảy nước, phân màu đen và báo cáo ngay.","Hiểu cách phân biệt phân bình thường và phân bất thường cùng mức ưu tiên báo cáo, và có thể hướng dẫn người mới thái độ \"phân vân thì báo cáo\"."],"levels_id":["Hanya menyelesaikan bersih-bersih tanpa melihat kotoran, dan membiarkan kotoran berdarah atau diare tanpa menyadarinya.","Jika disuruh bisa melihat kotoran, tetapi sering lalai membedakan kotoran abnormal dan mencatat nomor petak kandang.","Jika ada instruksi, bisa memeriksa warna dan kekerasan kotoran, dan jika menemukan kotoran abnormal bisa mencatat nomor petak kandang lalu melaporkannya.","Tanpa instruksi pun, menganggap pembersihan kotoran sebagai pemeriksaan kesehatan, menemukan lebih awal kotoran berdarah, diare cair, dan kotoran hitam lalu segera melaporkannya.","Memahami cara membedakan kotoran normal dan abnormal serta prioritas pelaporan, dan bisa mengajari karyawan baru sikap \"jika ragu, laporkan\"."]},{"id":"pit-scraper-safety","name":"ピット・除糞機の安全確保","kanten":"ピットをのぞきこまず、自動スクレーパーには電源を切り周囲へ声かけしてから近づけるか。","levels":["動いているスクレーパーに近づき、ピットの中をのぞきこむなど危険な行動を平気でする。","指示があれば注意するが、電源の切り忘れや周囲への声かけを忘れることが多い。","指示があれば電源を切ってから点検し、ピットに入らない決まりをひと通り守れる。","指示がなくても電源を切って周囲に声をかけ、ピットの有害ガスを踏まえて絶対に立ち入らない。","巻き込まれ事故と有害ガス・救助の二次被害の危険を理解し、安全手順を新人に指導できる。"],"name_en":"Safety around pits and manure removal equipment","name_vi":"Bảo đảm an toàn với hố chứa phân và máy dọn phân","name_id":"Menjaga keselamatan di sekitar pit dan alat pembersih kotoran","kanten_en":"Can they avoid peering into the pit, and approach the automatic scraper only after switching off the power and calling out to those around?","kanten_vi":"Có tránh cúi nhìn vào hố chứa phân, và chỉ lại gần máy cào phân tự động sau khi tắt nguồn điện và lên tiếng báo cho người xung quanh không.","kanten_id":"Apakah tidak menjenguk ke dalam pit, dan hanya mendekati alat pengeruk otomatis setelah mematikan listrik dan memberi tahu orang di sekitar.","levels_en":["Approaches the scraper while it is running and casually does dangerous things such as peering into the pit.","With guidance, takes care, but often forgets to switch off the power or call out to those around.","With guidance, switches off the power before inspecting and can adequately follow the rule of not entering the pit.","Independently switches off the power, calls out to those around, and never enters the pit, mindful of its harmful gases.","Understands the dangers of entanglement accidents, harmful gases, and secondary harm during rescue, and can teach new staff the safety procedures."],"levels_vi":["Lại gần máy cào phân đang chạy, thản nhiên làm những hành động nguy hiểm như cúi nhìn vào trong hố chứa phân.","Nếu có chỉ dẫn thì chú ý, nhưng thường quên tắt nguồn điện và quên lên tiếng báo cho người xung quanh.","Nếu có chỉ dẫn thì tắt nguồn điện rồi mới kiểm tra, giữ được cơ bản quy định không vào hố chứa phân.","Không cần chỉ dẫn cũng tắt nguồn điện và lên tiếng báo cho người xung quanh, tuyệt đối không vào hố chứa phân vì biết có khí độc hại.","Hiểu nguy cơ tai nạn bị cuốn vào máy, khí độc hại và tai nạn thứ cấp khi cứu hộ, và có thể hướng dẫn người mới quy trình an toàn."],"levels_id":["Mendekati alat pengeruk yang sedang berjalan, dan dengan santai melakukan tindakan berbahaya seperti menjenguk ke dalam pit.","Jika ada instruksi bisa berhati-hati, tetapi sering lupa mematikan listrik dan memberi tahu orang di sekitar.","Jika ada instruksi, bisa mematikan listrik dulu baru memeriksa, dan mematuhi secara garis besar aturan tidak masuk ke pit.","Tanpa instruksi pun, mematikan listrik dan memberi tahu orang di sekitar, serta sama sekali tidak masuk ke pit karena sadar akan gas berbahayanya.","Memahami bahaya kecelakaan terseret mesin, gas berbahaya, dan korban kedua saat penyelamatan, dan bisa mengajari karyawan baru prosedur keselamatan."]},{"id":"tool-dedicated","name":"豚舎専用道具の管理","kanten":"道具をその豚舎専用で使い、作業後に洗って同じ豚舎の置き場へ戻し、持ち出さないか。","levels":["道具を洗わず放置し、他の豚舎へ平気で持ち出して病原体を運ぶ危険を作る。","指示があれば片づけるが、道具の洗浄や専用ルールの徹底に漏れが多い。","指示があれば道具を洗い、同じ豚舎の置き場にひと通り戻せる。","指示がなくても専用道具のルールを守り、洗浄して定位置に戻し、破損に気づけば報告する。","道具の共用が病原体を運ぶ仕組みを理解し、豚舎専用管理の徹底を新人に指導できる。"],"name_en":"Managing barn-dedicated tools","name_vi":"Quản lý dụng cụ chuyên dùng của từng chuồng","name_id":"Pengelolaan alat khusus per kandang","kanten_en":"Do they use tools only in their dedicated barn, wash them after work, return them to that barn's storage place, and never take them out?","kanten_vi":"Có dùng dụng cụ chuyên cho chuồng đó, sau khi làm xong rửa sạch và trả về chỗ để của cùng chuồng, không mang ra ngoài không.","kanten_id":"Apakah memakai alat khusus untuk kandang itu saja, mencucinya setelah bekerja, mengembalikannya ke tempat penyimpanan kandang yang sama, dan tidak membawanya keluar.","levels_en":["Leaves tools unwashed and casually takes them to other barns, creating the risk of carrying pathogens.","With guidance, tidies up, but often fails to wash tools and observe the dedicated-use rules.","With guidance, washes tools and can adequately return them to the same barn's storage place.","Independently follows the dedicated-tool rules, washes and returns tools to their fixed places, and reports any damage noticed.","Understands how sharing tools carries pathogens, and can teach new staff thorough barn-dedicated management."],"levels_vi":["Bỏ mặc dụng cụ không rửa, thản nhiên mang sang chuồng khác, tạo nguy cơ mang mầm bệnh đi.","Nếu có chỉ dẫn thì dọn dẹp, nhưng hay bỏ sót việc rửa dụng cụ và giữ nghiêm quy tắc chuyên dùng.","Nếu có chỉ dẫn thì rửa dụng cụ, trả được cơ bản về chỗ để của cùng chuồng.","Không cần chỉ dẫn cũng giữ quy tắc dụng cụ chuyên dùng, rửa sạch và trả về đúng vị trí, nếu thấy hỏng hóc thì báo cáo.","Hiểu cơ chế dùng chung dụng cụ làm mang mầm bệnh đi, và có thể hướng dẫn người mới việc quản lý chuyên dùng theo chuồng."],"levels_id":["Membiarkan alat tanpa dicuci, dengan santai membawanya ke kandang lain, dan menciptakan bahaya membawa bibit penyakit.","Jika ada instruksi bisa membereskan, tetapi sering lalai mencuci alat dan mematuhi aturan alat khusus.","Jika ada instruksi, bisa mencuci alat dan mengembalikannya secara garis besar ke tempat penyimpanan kandang yang sama.","Tanpa instruksi pun, mematuhi aturan alat khusus, mencuci dan mengembalikannya ke tempat tetap, dan melaporkan jika menyadari ada kerusakan.","Memahami mekanisme pemakaian alat bersama yang membawa bibit penyakit, dan bisa mengajari karyawan baru pengelolaan alat khusus per kandang."]}],"name_en":"Manure removal","name_vi":"Dọn phân","name_id":"Membersihkan kotoran","purposeShort_en":"Reduce disease and harmful gases to protect pig health, and detect abnormalities early from the manure","purposeShort_vi":"Giảm bệnh và khí độc hại, bảo vệ sức khỏe lợn, phát hiện sớm bất thường qua phân","purposeShort_id":"Mengurangi penyakit dan gas berbahaya untuk menjaga kesehatan babi, dan menemukan kelainan lebih awal dari kotoran"},{"id":"five-s","category":"hygiene","no":"No.31","name":"5S清掃","purposeShort":"衛生レベルを底上げし、作業をやりやすくし、設備トラブルを早く見つける","gyomu":"31","aspects":[{"id":"fixed-place","name":"定位置管理の徹底","kanten":"物の置き場所を決めて守り、使った物を元の場所に戻せるか。","levels":["置き場所を決めず、使った物を元に戻さないまま放置する。","指示があれば片づけるが、元の場所に戻さないことが多い。","指示があれば決められた置き場所に物を戻せる。","指示がなくても定位置を守り、乱れがあれば自分で整える。","定位置管理がミス削減につながることを理解し、置き場所のルールづくりを新人に指導できる。"],"name_en":"Thorough fixed-location management","name_vi":"Giữ nghiêm việc để đồ đúng vị trí quy định","name_id":"Menjalankan pengaturan tempat tetap","kanten_en":"Can they set and observe fixed storage locations, returning items to their place after use?","kanten_vi":"Có quy định chỗ để đồ và giữ đúng, dùng xong trả đồ về chỗ cũ không.","kanten_id":"Apakah menentukan dan mematuhi tempat menyimpan barang, dan mengembalikan barang yang dipakai ke tempat semula.","levels_en":["Does not set storage locations and leaves used items lying around without returning them.","With guidance, tidies up, but often fails to return items to their original place.","With guidance, can return items to their designated locations.","Independently keeps to the fixed locations and straightens things up on their own when they are out of order.","Understands that fixed-location management reduces mistakes, and can teach new staff how to establish storage rules."],"levels_vi":["Không quy định chỗ để đồ, dùng xong không trả về chỗ cũ mà bỏ mặc.","Nếu có chỉ dẫn thì dọn dẹp, nhưng thường không trả đồ về chỗ cũ.","Nếu có chỉ dẫn thì trả được đồ về chỗ để quy định.","Không cần chỉ dẫn cũng giữ đúng vị trí quy định, nếu có xáo trộn thì tự mình sắp xếp lại.","Hiểu việc quản lý vị trí cố định giúp giảm sai sót, và có thể hướng dẫn người mới cách đặt quy tắc chỗ để đồ."],"levels_id":["Tidak menentukan tempat penyimpanan, dan membiarkan barang yang dipakai tanpa dikembalikan ke tempatnya.","Jika ada instruksi bisa membereskan, tetapi sering tidak mengembalikan barang ke tempat semula.","Jika ada instruksi, bisa mengembalikan barang ke tempat penyimpanan yang ditentukan.","Tanpa instruksi pun, mematuhi tempat tetap, dan jika ada yang berantakan merapikannya sendiri.","Memahami bahwa pengaturan tempat tetap mengurangi kesalahan, dan bisa mengajari karyawan baru cara membuat aturan tempat penyimpanan."]},{"id":"standard-abnormal","name":"きれいさの基準共有と異常発見","kanten":"「基準のきれいさ」を共有し、清掃を形式で終わらせず設備の異常発見につなげられるか。","levels":["基準があいまいで人により差が出て、チェックリストを形式的に埋めるだけで異常に気づかない。","指示があれば清掃するが、基準の共有や異常発見への意識が薄い。","指示があれば仕上がりを基準の写真と見比べ、決めた基準に沿ってひと通り清掃できる。","指示がなくても基準のきれいさを意識し、清掃しながら設備トラブルの兆候に気づく。","5Sを異常の早期発見に結びつけ、基準の共有と継続の仕組みを新人に指導できる。"],"name_en":"Sharing cleanliness standards and finding abnormalities","name_vi":"Chia sẻ tiêu chuẩn sạch sẽ và phát hiện bất thường","name_id":"Berbagi standar kebersihan dan menemukan kelainan","kanten_en":"Can they share a common cleanliness standard and use cleaning to detect equipment abnormalities rather than treating it as a formality?","kanten_vi":"Có chia sẻ \"tiêu chuẩn sạch sẽ\" chung, không làm vệ sinh cho có hình thức mà gắn với việc phát hiện bất thường của thiết bị không.","kanten_id":"Apakah berbagi \"standar kebersihan\" bersama, dan tidak menjadikan bersih-bersih sekadar formalitas tetapi menghubungkannya dengan penemuan kelainan peralatan.","levels_en":["Standards are vague and vary by person; fills in checklists as a formality and misses abnormalities.","With guidance, cleans, but has little awareness of shared standards or abnormality detection.","With guidance, compares the finish with the standard photo and can clean adequately according to the agreed standard.","Independently keeps the cleanliness standard in mind and notices early signs of equipment trouble while cleaning.","Connects 5S to early detection of abnormalities, and can teach new staff how to share standards and keep the practice going."],"levels_vi":["Tiêu chuẩn mơ hồ nên mỗi người làm một kiểu, chỉ điền bảng kiểm cho có hình thức mà không nhận ra bất thường.","Nếu có chỉ dẫn thì làm vệ sinh, nhưng ý thức về chia sẻ tiêu chuẩn và phát hiện bất thường còn yếu.","Nếu có chỉ dẫn thì so sánh kết quả với ảnh tiêu chuẩn, làm vệ sinh được cơ bản theo tiêu chuẩn đã định.","Không cần chỉ dẫn cũng ý thức về tiêu chuẩn sạch sẽ, vừa làm vệ sinh vừa nhận ra dấu hiệu sự cố của thiết bị.","Gắn 5S với việc phát hiện sớm bất thường, và có thể hướng dẫn người mới cách chia sẻ tiêu chuẩn và duy trì lâu dài."],"levels_id":["Standarnya tidak jelas sehingga hasil tiap orang berbeda, hanya mengisi daftar periksa sebagai formalitas dan tidak menyadari kelainan.","Jika ada instruksi bisa bersih-bersih, tetapi kesadaran akan berbagi standar dan menemukan kelainan masih lemah.","Jika ada instruksi, bisa membandingkan hasil akhir dengan foto standar dan bersih-bersih secara garis besar sesuai standar yang ditetapkan.","Tanpa instruksi pun, sadar akan standar kebersihan, dan sambil bersih-bersih menyadari tanda-tanda masalah peralatan.","Bisa menghubungkan 5S dengan penemuan kelainan lebih awal, dan bisa mengajari karyawan baru cara berbagi standar dan menjaga kelangsungannya."]},{"id":"sort-discard","name":"整理（不要物の処分判断）","kanten":"不要物を見つけて処分し、捨てていいか迷う物は自己判断せず先輩に確認できるか。","levels":["不要物が放置されていても気にせず、必要な物を自己判断で勝手に捨てることもある。","指示があれば不要物を捨てるが、見て回りに漏れが多く、迷う物の確認をしない。","指示があれば通路や豚舎を見て回って不要物を処分し、迷う物は先輩に確認できる。","指示がなくても不要物に気づいて処分し、判断に迷う物は必ず確認してから捨てる。","整理が作業性と衛生の土台になることを理解し、要・不要の判断基準を新人に指導できる。"],"name_en":"Sorting (deciding what to discard)","name_vi":"Sàng lọc (phán đoán xử lý đồ không cần)","name_id":"Ringkas (menilai pembuangan barang tak perlu)","kanten_en":"Can they find and dispose of unneeded items, and check with a senior instead of self-judging when unsure whether something may be discarded?","kanten_vi":"Có tìm và xử lý đồ không cần, với đồ phân vân không biết bỏ được không thì không tự quyết mà hỏi người đi trước không.","kanten_id":"Apakah menemukan dan membuang barang yang tidak perlu, dan untuk barang yang diragukan boleh dibuang atau tidak, bertanya kepada senior alih-alih memutuskan sendiri.","levels_en":["Does not care that unneeded items are left lying around, and sometimes discards needed items on their own judgment.","With guidance, discards unneeded items, but often misses areas when looking around and does not check on doubtful items.","With guidance, walks around the aisles and barns to dispose of unneeded items, and can check doubtful items with a senior.","Independently notices and disposes of unneeded items, and always checks before discarding anything they are unsure about.","Understands that sorting underpins workability and hygiene, and can teach new staff the criteria for judging what is needed and what is not."],"levels_vi":["Đồ không cần bị bỏ mặc cũng không quan tâm, có khi còn tự ý vứt cả đồ cần dùng.","Nếu có chỉ dẫn thì vứt đồ không cần, nhưng hay bỏ sót khi đi xem quanh và không hỏi về đồ còn phân vân.","Nếu có chỉ dẫn thì đi xem quanh lối đi và chuồng để xử lý đồ không cần, đồ phân vân thì hỏi được người đi trước.","Không cần chỉ dẫn cũng nhận ra đồ không cần và xử lý, đồ khó phán đoán thì nhất định hỏi rồi mới vứt.","Hiểu việc sàng lọc là nền tảng cho hiệu quả làm việc và vệ sinh, và có thể hướng dẫn người mới tiêu chí phán đoán cần hay không cần."],"levels_id":["Tidak peduli walau barang tak perlu dibiarkan berserakan, dan kadang membuang barang yang diperlukan atas keputusan sendiri.","Jika ada instruksi bisa membuang barang tak perlu, tetapi sering ada yang terlewat saat berkeliling dan tidak menanyakan barang yang diragukan.","Jika ada instruksi, bisa berkeliling lorong dan kandang untuk membuang barang tak perlu, dan menanyakan barang yang diragukan kepada senior.","Tanpa instruksi pun, menyadari dan membuang barang tak perlu, dan untuk barang yang meragukan selalu bertanya dulu sebelum membuang.","Memahami bahwa ringkas menjadi dasar kelancaran kerja dan kebersihan, dan bisa mengajari karyawan baru kriteria menilai perlu atau tidaknya barang."]},{"id":"priority-spots","name":"汚れやすい場所の重点清掃","kanten":"排水口・餌箱の裏・飲水器の下を重点的に清掃し、排水口の詰まりを取り除けるか。","levels":["見えやすい所だけ掃き、排水口や餌箱の裏の飼料カス・糞を残したまま終える。","指示があれば掃除するが、餌箱の裏側や排水口の詰まり確認に漏れが多い。","指示があれば排水口・餌箱まわり・飲水器の下をひと通り重点清掃できる。","指示がなくても汚れやすい場所を重点的に清掃し、排水口の詰まりを見つけて取り除く。","飼料カスがハエの発生源、詰まりが病原体の温床になることを理解し、重点箇所を新人に指導できる。"],"name_en":"Focused cleaning of spots that get dirty easily","name_vi":"Vệ sinh trọng điểm những chỗ dễ bẩn","name_id":"Pembersihan intensif tempat yang mudah kotor","kanten_en":"Can they focus their cleaning on drains, the backs of feed boxes, and under drinkers, and clear blockages in the drains?","kanten_vi":"Có vệ sinh kỹ miệng cống thoát nước, mặt sau máng ăn, dưới vòi uống nước, và lấy được rác làm tắc cống không.","kanten_id":"Apakah membersihkan secara khusus saluran pembuangan, bagian belakang kotak pakan, dan bawah tempat minum, serta bisa menyingkirkan sumbatan di saluran pembuangan.","levels_en":["Sweeps only the visible areas and finishes leaving feed residue and manure in the drains and behind the feed boxes.","With guidance, cleans, but often misses the backs of feed boxes and checking drains for blockages.","With guidance, can adequately give focused cleaning to drains, around the feed boxes, and under the drinkers.","Independently focuses cleaning on spots that get dirty easily, and finds and clears blockages in the drains.","Understands that feed residue breeds flies and blockages become hotbeds for pathogens, and can teach new staff the priority spots."],"levels_vi":["Chỉ quét chỗ dễ nhìn thấy, kết thúc mà vẫn để sót cặn thức ăn và phân ở cống thoát nước và mặt sau máng ăn.","Nếu có chỉ dẫn thì lau dọn, nhưng hay bỏ sót mặt sau máng ăn và việc kiểm tra cống có tắc không.","Nếu có chỉ dẫn thì vệ sinh trọng điểm được cơ bản miệng cống, xung quanh máng ăn và dưới vòi uống nước.","Không cần chỉ dẫn cũng vệ sinh kỹ những chỗ dễ bẩn, phát hiện và lấy rác làm tắc cống thoát nước.","Hiểu cặn thức ăn là nguồn phát sinh ruồi và chỗ tắc là ổ mầm bệnh, và có thể hướng dẫn người mới những chỗ trọng điểm."],"levels_id":["Hanya menyapu bagian yang mudah terlihat, dan selesai dengan meninggalkan sisa pakan dan kotoran di saluran pembuangan dan belakang kotak pakan.","Jika ada instruksi bisa membersihkan, tetapi sering lalai memeriksa bagian belakang kotak pakan dan sumbatan saluran pembuangan.","Jika ada instruksi, bisa membersihkan secara garis besar saluran pembuangan, sekitar kotak pakan, dan bawah tempat minum.","Tanpa instruksi pun, membersihkan secara intensif tempat yang mudah kotor, serta menemukan dan menyingkirkan sumbatan saluran pembuangan.","Memahami bahwa sisa pakan menjadi sumber lalat dan sumbatan menjadi sarang bibit penyakit, dan bisa mengajari karyawan baru titik-titik prioritas."]},{"id":"honest-checklist","name":"チェックリストの正直な記録","kanten":"実際に清掃した場所だけをチェックリストに記録し、やっていない所にチェックを入れないか。","levels":["やっていない場所にもチェックを入れ、記録上「完了」でも実態が伴わない。","指示されれば記録するが、記入漏れや実施とのずれが多い。","指示があれば実際にやった場所だけをチェックリストにひと通り記録できる。","指示がなくても実施内容を正確に記録し、できなかった場所は理由とあわせて引き継ぐ。","形式的なチェックが問題の見逃しを生むことを理解し、正直な記録の意味を新人に指導できる。"],"name_en":"Honest checklist records","name_vi":"Ghi chép trung thực bảng kiểm tra","name_id":"Pencatatan daftar periksa secara jujur","kanten_en":"Do they record on the checklist only the places actually cleaned, without checking off places they have not done?","kanten_vi":"Có chỉ ghi vào bảng kiểm tra những chỗ đã thực sự vệ sinh, không đánh dấu vào chỗ chưa làm không.","kanten_id":"Apakah mencatat di daftar periksa hanya tempat yang benar-benar dibersihkan, dan tidak mencentang tempat yang belum dikerjakan.","levels_en":["Checks off even places not done, so the record says \"completed\" while reality does not match.","Records when instructed, but with many omissions and gaps from what was actually done.","With guidance, can adequately record on the checklist only the places actually done.","Independently records what was done accurately, and hands over any places not done together with the reason.","Understands that box-ticking leads to problems being overlooked, and can teach new staff the meaning of honest records."],"levels_vi":["Đánh dấu cả vào chỗ chưa làm, trên giấy tờ là \"hoàn thành\" nhưng thực tế không đúng như vậy.","Nếu được chỉ dẫn thì ghi chép, nhưng hay bỏ sót và lệch với việc đã thực hiện.","Nếu có chỉ dẫn thì ghi được cơ bản vào bảng kiểm tra chỉ những chỗ đã thực sự làm.","Không cần chỉ dẫn cũng ghi chính xác nội dung đã làm, chỗ chưa làm được thì bàn giao kèm lý do.","Hiểu việc đánh dấu hình thức làm bỏ sót vấn đề, và có thể hướng dẫn người mới ý nghĩa của ghi chép trung thực."],"levels_id":["Mencentang juga tempat yang belum dikerjakan, sehingga catatan tertulis \"selesai\" padahal kenyataannya tidak.","Jika disuruh bisa mencatat, tetapi banyak yang terlewat dan tidak sesuai dengan yang dikerjakan.","Jika ada instruksi, bisa mencatat secara garis besar di daftar periksa hanya tempat yang benar-benar dikerjakan.","Tanpa instruksi pun, mencatat isi pekerjaan dengan akurat, dan menyerahterimakan tempat yang belum bisa dikerjakan beserta alasannya.","Memahami bahwa pencentangan sekadar formalitas membuat masalah terlewat, dan bisa mengajari karyawan baru arti pencatatan yang jujur."]}],"name_en":"5S cleaning","name_vi":"Vệ sinh 5S (Sàng lọc - Sắp xếp - Sạch sẽ - Săn sóc - Sẵn sàng)","name_id":"Kebersihan 5S (Ringkas - Rapi - Resik - Rawat - Rajin)","purposeShort_en":"Raise the overall hygiene level, make work easier, and detect equipment trouble early","purposeShort_vi":"Nâng cao mức vệ sinh, làm việc dễ hơn, phát hiện sớm sự cố thiết bị","purposeShort_id":"Menaikkan tingkat kebersihan, membuat pekerjaan lebih mudah, dan menemukan masalah peralatan lebih cepat"},{"id":"treatment","category":"hygiene","no":"No.04","name":"治療","purposeShort":"体調の悪い豚を早く回復させ、悪化と感染拡大を防ぐ","gyomu":"04","aspects":[{"id":"withdrawal","name":"休薬期間の確認と治療豚の識別","kanten":"使用薬剤の休薬期間を確認し、治療豚を確実に識別して出荷から除外できるか。","levels":["休薬期間を確認せず、治療豚の識別もあいまいで、休薬中の豚を誤って出荷する危険がある。","指示があれば休薬を確認するが、治療豚の識別や記録に漏れが多い。","指示があれば休薬期間を確認し、治療豚を識別してひと通り管理できる。","指示がなくても休薬期間を必ず確認し、治療豚を明確に識別して出荷から除外する。","残留違反の重大さを理解し、休薬管理と個体識別の仕組みを新人に指導できる。"],"name_en":"Checking withdrawal periods and identifying treated pigs","name_vi":"Kiểm tra thời gian ngừng thuốc và nhận biết lợn đang điều trị","name_id":"Pemeriksaan masa henti obat dan penandaan babi yang diobati","kanten_en":"Can they check the withdrawal period of each drug used, reliably identify treated pigs, and exclude them from shipment?","kanten_vi":"Có kiểm tra thời gian ngừng thuốc của thuốc đang dùng, đánh dấu rõ lợn đang điều trị và loại khỏi danh sách xuất chuồng không.","kanten_id":"Apakah memeriksa masa henti obat dari obat yang dipakai, menandai babi yang diobati dengan pasti, dan mengeluarkannya dari pengiriman.","levels_en":["Does not check withdrawal periods; identification of treated pigs is vague, risking mistaken shipment of pigs still in withdrawal.","With guidance, checks withdrawal periods, but often fails to identify or record treated pigs.","With guidance, checks withdrawal periods and can adequately identify and manage treated pigs.","Independently always checks withdrawal periods, clearly identifies treated pigs, and excludes them from shipment.","Understands the seriousness of residue violations, and can teach new staff systems for withdrawal management and individual identification."],"levels_vi":["Không kiểm tra thời gian ngừng thuốc, đánh dấu lợn đang điều trị cũng mơ hồ, có nguy cơ xuất chuồng nhầm lợn đang trong thời gian ngừng thuốc.","Nếu có chỉ dẫn thì kiểm tra việc ngừng thuốc, nhưng hay bỏ sót việc đánh dấu và ghi chép lợn đang điều trị.","Nếu có chỉ dẫn thì kiểm tra thời gian ngừng thuốc, đánh dấu lợn đang điều trị và quản lý được cơ bản.","Không cần chỉ dẫn cũng luôn kiểm tra thời gian ngừng thuốc, đánh dấu rõ lợn đang điều trị và loại khỏi việc xuất chuồng.","Hiểu mức độ nghiêm trọng của vi phạm tồn dư thuốc, và có thể hướng dẫn người mới cách quản lý ngừng thuốc và nhận dạng từng con."],"levels_id":["Tidak memeriksa masa henti obat, penandaan babi yang diobati juga tidak jelas, sehingga ada bahaya mengirim babi yang masih dalam masa henti obat.","Jika ada instruksi bisa memeriksa masa henti obat, tetapi sering lalai menandai dan mencatat babi yang diobati.","Jika ada instruksi, bisa memeriksa masa henti obat, menandai babi yang diobati, dan mengelolanya secara garis besar.","Tanpa instruksi pun, selalu memeriksa masa henti obat, menandai babi yang diobati dengan jelas, dan mengeluarkannya dari pengiriman.","Memahami seriusnya pelanggaran residu obat, dan bisa mengajari karyawan baru sistem pengelolaan masa henti obat dan identifikasi individu."]},{"id":"protocol","name":"指示・用法の遵守と針の本数管理","kanten":"決められたやり方・指示を守り、注射針の本数を管理して紛失・混入を防げるか。","levels":["自己判断でやり方を変え、注射針の本数管理もせず紛失・混入の危険を放置する。","指示があれば従うが、用法の徹底や針の本数確認に漏れがある。","指示があれば決められたやり方・指示に従い、針の本数をひと通り確認できる。","指示がなくても用法を守り、注射針の本数管理を徹底して紛失・混入を防ぐ。","自己判断で薬ややり方を変える危険と針混入の重大さを理解し、正しい治療手順を新人に指導できる。"],"name_en":"Following instructions and dosage, and needle count management","name_vi":"Tuân thủ chỉ dẫn, cách dùng thuốc và quản lý số kim tiêm","name_id":"Mematuhi instruksi dan aturan pakai serta pengelolaan jumlah jarum","kanten_en":"Can they follow prescribed methods and instructions, and manage the number of needles to prevent loss and contamination?","kanten_vi":"Có giữ đúng cách làm và chỉ dẫn quy định, quản lý số lượng kim tiêm để tránh mất kim và kim lẫn vào thịt không.","kanten_id":"Apakah mematuhi cara dan instruksi yang ditentukan, dan mengelola jumlah jarum suntik untuk mencegah hilang atau masuk ke tubuh babi.","levels_en":["Changes methods on their own judgment and does not manage needle counts, leaving the risk of loss and contamination unaddressed.","With guidance, complies, but is inconsistent about following dosage instructions and checking needle counts.","With guidance, follows the prescribed methods and instructions and can adequately check needle counts.","Independently follows the dosage instructions and rigorously manages needle counts to prevent loss and contamination.","Understands the danger of changing drugs or methods on one's own judgment and the seriousness of needle contamination, and can teach new staff correct treatment procedures."],"levels_vi":["Tự ý thay đổi cách làm, không quản lý số kim tiêm, bỏ mặc nguy cơ mất kim và kim lẫn vào thịt.","Nếu có chỉ dẫn thì làm theo, nhưng có bỏ sót việc giữ đúng cách dùng thuốc và kiểm số kim.","Nếu có chỉ dẫn thì làm theo đúng cách và chỉ dẫn quy định, kiểm được cơ bản số kim tiêm.","Không cần chỉ dẫn cũng giữ đúng cách dùng thuốc, quản lý chặt số kim tiêm để tránh mất và lẫn kim.","Hiểu nguy cơ khi tự ý thay đổi thuốc hay cách làm và mức nghiêm trọng của việc kim lẫn vào thịt, và có thể hướng dẫn người mới quy trình điều trị đúng."],"levels_id":["Mengubah cara sesuka hati, tidak mengelola jumlah jarum suntik, dan membiarkan bahaya jarum hilang atau masuk ke tubuh babi.","Jika ada instruksi bisa mengikuti, tetapi sering lalai mematuhi aturan pakai dan memeriksa jumlah jarum.","Jika ada instruksi, bisa mengikuti cara dan instruksi yang ditentukan, serta memeriksa jumlah jarum secara garis besar.","Tanpa instruksi pun, mematuhi aturan pakai dan mengelola jumlah jarum suntik dengan ketat untuk mencegah hilang atau masuk ke tubuh babi.","Memahami bahaya mengubah obat atau cara atas keputusan sendiri dan seriusnya jarum yang masuk ke tubuh babi, dan bisa mengajari karyawan baru urutan pengobatan yang benar."]},{"id":"identify-track","name":"治療記録のその場記入","kanten":"「いつ・どの豚に・何の薬を・どれだけ・誰が」を後回しにせず、その場で記録簿に書けるか。","levels":["治療しても記録を書かず、後から投薬経過を追えない状態にする。","指示されれば記録するが、後回しにして薬剤名・投与量・日付の記入漏れが多い。","指示があれば「いつ・どの豚に・何の薬を・どれだけ・誰が」をひと通り記録できる。","指示がなくても治療したその場で漏れなく記録し、記入漏れに気づけば自分で確かめて直す。","後書きが記入漏れを生み休薬管理・治療評価を狂わせることを理解し、その場記録を新人に指導できる。"],"name_en":"On-the-spot treatment records","name_vi":"Ghi sổ điều trị ngay tại chỗ","name_id":"Pencatatan pengobatan langsung di tempat","kanten_en":"Can they write \"when, which pig, what drug, how much, by whom\" in the record book on the spot, without putting it off?","kanten_vi":"Có ghi ngay tại chỗ vào sổ ghi chép \"khi nào, con lợn nào, thuốc gì, bao nhiêu, ai làm\" mà không để sau không.","kanten_id":"Apakah bisa menulis di buku catatan langsung di tempat \"kapan, babi yang mana, obat apa, berapa banyak, oleh siapa\" tanpa menundanya.","levels_en":["Treats pigs without writing records, leaving the medication course untraceable later.","Records when instructed, but puts it off and often omits the drug name, dose, and date.","With guidance, can adequately record \"when, which pig, what drug, how much, by whom\".","Independently records completely on the spot right after treating, and when noticing an omission, verifies and corrects it themselves.","Understands that writing records later creates omissions and disrupts withdrawal management and treatment evaluation, and can teach new staff on-the-spot recording."],"levels_vi":["Điều trị xong không ghi chép, làm cho sau này không theo dõi lại được quá trình dùng thuốc.","Nếu được chỉ dẫn thì ghi chép, nhưng để sau nên hay bỏ sót tên thuốc, liều lượng, ngày tháng.","Nếu có chỉ dẫn thì ghi được cơ bản \"khi nào, con lợn nào, thuốc gì, bao nhiêu, ai làm\".","Không cần chỉ dẫn cũng ghi đầy đủ ngay tại chỗ sau khi điều trị, nếu thấy ghi sót thì tự kiểm tra và sửa lại.","Hiểu việc ghi sau sinh ra bỏ sót và làm sai lệch quản lý ngừng thuốc, đánh giá điều trị, và có thể hướng dẫn người mới việc ghi ngay tại chỗ."],"levels_id":["Mengobati tanpa menulis catatan, sehingga perjalanan pengobatan tidak bisa ditelusuri kemudian.","Jika disuruh bisa mencatat, tetapi menundanya sehingga sering lupa mengisi nama obat, dosis, dan tanggal.","Jika ada instruksi, bisa mencatat secara garis besar \"kapan, babi yang mana, obat apa, berapa banyak, oleh siapa\".","Tanpa instruksi pun, mencatat lengkap langsung di tempat setelah mengobati, dan jika menyadari ada yang terlewat, memeriksanya sendiri lalu memperbaikinya.","Memahami bahwa mencatat belakangan menimbulkan kelalaian dan mengacaukan pengelolaan masa henti obat serta evaluasi pengobatan, dan bisa mengajari karyawan baru pencatatan langsung di tempat."]},{"id":"early-detect","name":"体調不良豚の発見と報告","kanten":"食欲・耳の垂れ・動き・呼吸・糞のサインで不調豚を見つけ、耳標番号を控えて報告できるか。","levels":["体調不良のサインに気づかず見過ごし、見つけても報告せず自分の判断で薬を使おうとする。","指示されれば豚を見るが、サインの見落としが多く、耳標番号の控えや報告が不確実。","指示があれば不調のサインを確認し、迷ったら体温を測って耳標番号とともに報告できる。","指示がなくても見回りで不調豚を早期に見つけ、耳標番号・症状を控えて報告し治療指示を受ける。","早期発見が治療成績を左右することを理解し、体調不良のサインの見方を新人に指導できる。"],"name_en":"Finding and reporting unwell pigs","name_vi":"Phát hiện và báo cáo lợn có sức khỏe kém","name_id":"Menemukan dan melaporkan babi yang tidak sehat","kanten_en":"Can they spot unwell pigs from signs in appetite, drooping ears, movement, breathing, and manure, and note the ear tag number and report?","kanten_vi":"Có phát hiện lợn không khỏe qua dấu hiệu ăn uống, tai cụp, cử động, hô hấp, phân, ghi lại số thẻ tai và báo cáo không.","kanten_id":"Apakah bisa menemukan babi yang tidak sehat dari tanda nafsu makan, telinga terkulai, gerakan, napas, dan kotoran, lalu mencatat nomor tanda telinga dan melaporkannya.","levels_en":["Overlooks signs of poor condition, and even when finding one, does not report and tries to use drugs on their own judgment.","Looks at the pigs when instructed, but misses many signs, and noting the ear tag number and reporting are unreliable.","With guidance, checks for signs of illness, and when unsure, can take the temperature and report together with the ear tag number.","Independently finds unwell pigs early during rounds, notes the ear tag number and symptoms, reports, and receives treatment instructions.","Understands that early detection determines treatment outcomes, and can teach new staff how to read the signs of poor condition."],"levels_vi":["Không nhận ra dấu hiệu sức khỏe kém mà bỏ qua, có thấy cũng không báo cáo mà định tự ý dùng thuốc.","Nếu được chỉ dẫn thì nhìn lợn, nhưng hay bỏ sót dấu hiệu, việc ghi số thẻ tai và báo cáo không chắc chắn.","Nếu có chỉ dẫn thì kiểm tra dấu hiệu không khỏe, khi phân vân thì đo thân nhiệt và báo cáo kèm số thẻ tai.","Không cần chỉ dẫn cũng phát hiện sớm lợn không khỏe khi đi kiểm tra, ghi số thẻ tai và triệu chứng, báo cáo và nhận chỉ thị điều trị.","Hiểu việc phát hiện sớm quyết định kết quả điều trị, và có thể hướng dẫn người mới cách nhìn dấu hiệu sức khỏe kém."],"levels_id":["Melewatkan tanda-tanda kondisi buruk tanpa menyadarinya, dan walau menemukannya tidak melapor melainkan mencoba memakai obat atas keputusan sendiri.","Jika disuruh bisa melihat babi, tetapi banyak tanda yang terlewat, dan pencatatan nomor tanda telinga serta pelaporannya tidak pasti.","Jika ada instruksi, bisa memeriksa tanda-tanda tidak sehat, dan jika ragu mengukur suhu tubuh lalu melaporkannya beserta nomor tanda telinga.","Tanpa instruksi pun, menemukan babi yang tidak sehat lebih awal saat berkeliling, mencatat nomor tanda telinga dan gejalanya, melapor, dan menerima instruksi pengobatan.","Memahami bahwa penemuan dini menentukan hasil pengobatan, dan bisa mengajari karyawan baru cara melihat tanda-tanda kondisi yang buruk."]},{"id":"isolation-order","name":"隔離と感染拡大防止の作業順","kanten":"重症・下痢の豚を隔離し、世話は健康豚の後に回し、病豚に触れた後は手指消毒できるか。","levels":["病豚と健康豚を区別せずに触り、隔離もせず感染を広げる危険を放置する。","指示があれば隔離するが、作業順や手指消毒の徹底に漏れが多い。","指示があれば病豚を隔離ペンに移し、健康豚の後に世話をする順序をひと通り守れる。","指示がなくても隔離と作業順を守り、病豚に触れた後は手指消毒してから健康豚に触る。","作業順と手指消毒が感染拡大を防ぐ理由を理解し、病豚の扱い方を新人に指導できる。"],"name_en":"Isolation and work order to prevent infection spread","name_vi":"Cách ly và thứ tự làm việc để chống lây lan","name_id":"Isolasi dan urutan kerja untuk mencegah penyebaran infeksi","kanten_en":"Can they isolate severely ill or diarrheic pigs, care for them after the healthy pigs, and disinfect their hands after touching sick pigs?","kanten_vi":"Có cách ly lợn bệnh nặng, lợn tiêu chảy, chăm sóc chúng sau lợn khỏe, và khử trùng tay sau khi chạm vào lợn bệnh không.","kanten_id":"Apakah mengisolasi babi yang sakit parah atau diare, mengurusnya setelah babi sehat, dan mendisinfeksi tangan setelah menyentuh babi sakit.","levels_en":["Touches sick and healthy pigs without distinction, does not isolate, and leaves the risk of spreading infection unaddressed.","With guidance, isolates, but often fails to keep the work order and hand disinfection.","With guidance, moves sick pigs to the isolation pen and can adequately keep the order of caring for them after the healthy pigs.","Independently keeps the isolation and work order, and disinfects their hands after touching sick pigs before touching healthy ones.","Understands why work order and hand disinfection prevent infection spread, and can teach new staff how to handle sick pigs."],"levels_vi":["Chạm vào lợn bệnh và lợn khỏe không phân biệt, cũng không cách ly, bỏ mặc nguy cơ làm lây lan bệnh.","Nếu có chỉ dẫn thì cách ly, nhưng hay bỏ sót việc giữ thứ tự làm việc và khử trùng tay.","Nếu có chỉ dẫn thì chuyển lợn bệnh sang ô cách ly, giữ được cơ bản thứ tự chăm sóc sau lợn khỏe.","Không cần chỉ dẫn cũng giữ việc cách ly và thứ tự làm việc, sau khi chạm lợn bệnh thì khử trùng tay rồi mới chạm lợn khỏe.","Hiểu lý do thứ tự làm việc và khử trùng tay ngăn được lây lan, và có thể hướng dẫn người mới cách xử lý lợn bệnh."],"levels_id":["Menyentuh babi sakit dan sehat tanpa membedakan, tidak mengisolasi, dan membiarkan bahaya penyebaran infeksi.","Jika ada instruksi bisa mengisolasi, tetapi sering lalai menjaga urutan kerja dan disinfeksi tangan.","Jika ada instruksi, bisa memindahkan babi sakit ke petak isolasi dan mematuhi secara garis besar urutan mengurusnya setelah babi sehat.","Tanpa instruksi pun, menjaga isolasi dan urutan kerja, dan setelah menyentuh babi sakit mendisinfeksi tangan dulu sebelum menyentuh babi sehat.","Memahami alasan urutan kerja dan disinfeksi tangan mencegah penyebaran infeksi, dan bisa mengajari karyawan baru cara menangani babi sakit."]}],"name_en":"Treatment","name_vi":"Điều trị","name_id":"Pengobatan","purposeShort_en":"Help sick pigs recover quickly and prevent deterioration and spread of infection","purposeShort_vi":"Giúp lợn ốm hồi phục nhanh, ngăn bệnh nặng thêm và lây lan","purposeShort_id":"Memulihkan babi yang sakit dengan cepat, mencegah kondisi memburuk dan penyebaran infeksi"},{"id":"sow-vaccine","category":"hygiene","no":"No.06","name":"母豚ワクチン接種","purposeShort":"母豚と子豚を守る免疫をつけ、農場の免疫レベルをそろえる","gyomu":"06","aspects":[{"id":"schedule","name":"日齢・スケジュールの遵守","kanten":"決められた日齢・スケジュールで確実に接種し、打ち漏れを作らないか。","levels":["スケジュールを守らず、自分の判断で接種日を前後させて免疫を不十分にする。","指示があれば接種するが、対象や時期の確認に漏れがある。","指示があれば決められた日齢・スケジュールでひと通り接種できる。","指示がなくてもスケジュール表で対象と時期を確認して接種し、打ち漏れを防ぐ。","早すぎても遅すぎても効かないことを理解し、スケジュール管理を新人に指導できる。"],"name_en":"Following age and vaccination schedule","name_vi":"Giữ đúng tuổi ngày và lịch tiêm","name_id":"Mematuhi umur dan jadwal","kanten_en":"Can they vaccinate reliably at the prescribed age and schedule without missing any animals?","kanten_vi":"Có tiêm chắc chắn theo đúng tuổi ngày và lịch quy định, không để sót con chưa tiêm không.","kanten_id":"Apakah menyuntik vaksin dengan pasti sesuai umur dan jadwal yang ditentukan, tanpa ada yang terlewat.","levels_en":["Ignores the schedule and shifts vaccination dates on their own judgment, resulting in insufficient immunity.","With guidance, vaccinates, but is inconsistent about confirming target animals and timing.","With guidance, can adequately vaccinate at the prescribed age and schedule.","Independently confirms the target animals and timing on the schedule sheet before vaccinating, preventing missed injections.","Understands that vaccinating too early or too late does not work, and can teach new staff schedule management."],"levels_vi":["Không giữ lịch tiêm, tự ý xê dịch ngày tiêm làm miễn dịch không đủ.","Nếu có chỉ dẫn thì tiêm, nhưng có bỏ sót việc kiểm tra đối tượng và thời điểm.","Nếu có chỉ dẫn thì tiêm được cơ bản theo đúng tuổi ngày và lịch quy định.","Không cần chỉ dẫn cũng xem bảng lịch để kiểm tra đối tượng và thời điểm rồi tiêm, phòng sót con chưa tiêm.","Hiểu tiêm quá sớm hay quá muộn đều không có tác dụng, và có thể hướng dẫn người mới cách quản lý lịch tiêm."],"levels_id":["Tidak mematuhi jadwal, menggeser tanggal penyuntikan atas keputusan sendiri sehingga kekebalan tidak cukup.","Jika ada instruksi bisa menyuntik, tetapi sering lalai memeriksa sasaran dan waktunya.","Jika ada instruksi, bisa menyuntik secara garis besar sesuai umur dan jadwal yang ditentukan.","Tanpa instruksi pun, memeriksa sasaran dan waktunya di tabel jadwal sebelum menyuntik, dan mencegah ada yang terlewat.","Memahami bahwa menyuntik terlalu cepat atau terlalu lambat tidak akan bekerja, dan bisa mengajari karyawan baru pengelolaan jadwal."]},{"id":"vaccine-handling","name":"ワクチンの取り扱いと針交換","kanten":"生ワクチンは溶解後すぐ使い切り、不活化は当日中に使い、針を頭ごとに交換できるか。","levels":["溶解後の保管時間を超過し、注射針を使い回して感染リスクを高める。","指示があれば取り扱うが、使い切りの時間管理や針交換に漏れがある。","指示があれば生ワクチンを溶解後すぐ使い、針をひと通り交換できる。","指示がなくても溶解後の時間を守って使い切り、針を頭ごとに交換する。","ワクチンの失活や針使い回しのリスクを理解し、正しい取り扱いを新人に指導できる。"],"name_en":"Vaccine handling and needle changes","name_vi":"Cách xử lý vắc-xin và thay kim tiêm","name_id":"Penanganan vaksin dan penggantian jarum","kanten_en":"Can they use live vaccines immediately after reconstitution, use inactivated vaccines within the day, and change needles for each animal?","kanten_vi":"Vắc-xin sống có dùng hết ngay sau khi pha, vắc-xin bất hoạt dùng trong ngày, và thay kim theo từng con không.","kanten_id":"Apakah vaksin hidup dihabiskan segera setelah dilarutkan, vaksin inaktif dipakai pada hari yang sama, dan jarum diganti setiap ekor.","levels_en":["Exceeds the storage time after reconstitution and reuses needles, raising infection risk.","With guidance, handles vaccines, but is inconsistent about use-by time management and needle changes.","With guidance, uses live vaccines promptly after reconstitution and can adequately change needles.","Independently observes the time limit after reconstitution, uses vaccines up, and changes the needle for each animal.","Understands the risks of vaccine inactivation and needle reuse, and can teach new staff correct handling."],"levels_vi":["Để quá thời gian bảo quản sau khi pha, dùng lại kim tiêm làm tăng nguy cơ lây nhiễm.","Nếu có chỉ dẫn thì xử lý được, nhưng có bỏ sót việc quản lý thời gian dùng hết và thay kim.","Nếu có chỉ dẫn thì dùng vắc-xin sống ngay sau khi pha, thay kim được cơ bản.","Không cần chỉ dẫn cũng giữ đúng thời gian sau khi pha và dùng hết, thay kim theo từng con.","Hiểu nguy cơ vắc-xin mất hiệu lực và dùng lại kim, và có thể hướng dẫn người mới cách xử lý đúng."],"levels_id":["Melewati batas waktu penyimpanan setelah vaksin dilarutkan, dan memakai jarum suntik bergantian sehingga menaikkan risiko infeksi.","Jika ada instruksi bisa menangani, tetapi sering lalai mengelola batas waktu pemakaian dan mengganti jarum.","Jika ada instruksi, bisa memakai vaksin hidup segera setelah dilarutkan dan mengganti jarum secara garis besar.","Tanpa instruksi pun, mematuhi batas waktu setelah pelarutan dan menghabiskannya, serta mengganti jarum setiap ekor.","Memahami risiko vaksin kehilangan daya dan pemakaian jarum bergantian, dan bisa mengajari karyawan baru penanganan yang benar."]},{"id":"condition-check","name":"対象母豚の体調確認と接種可否","kanten":"接種前に1頭ずつ体調を見て、発熱・食欲不振・下痢の母豚はリストから外して報告できるか。","levels":["体調を見ずに全頭へ打ち、明らかに具合の悪い母豚にも接種してしまう。","指示があれば体調を見るが、確認が形式的でリストから外す判断や報告を他者まかせにする。","指示があれば対象を1頭ずつ確認し、体調不良の母豚を外して上長に報告できる。","指示がなくても接種前の体調確認を欠かさず、外した母豚の回復後の接種まで気を配る。","体調不良時の接種が免疫と母豚に及ぼす影響を理解し、接種可否の見極めを新人に指導できる。"],"name_en":"Checking each sow's condition and fitness for vaccination","name_vi":"Kiểm tra sức khỏe lợn nái và quyết định tiêm hay không","name_id":"Pemeriksaan kondisi induk babi sasaran dan boleh-tidaknya divaksin","kanten_en":"Can they check each sow's condition before vaccinating, and remove sows with fever, poor appetite, or diarrhea from the list and report them?","kanten_vi":"Trước khi tiêm có xem sức khỏe từng con, đưa lợn nái bị sốt, kém ăn, tiêu chảy ra khỏi danh sách và báo cáo không.","kanten_id":"Apakah memeriksa kondisi tiap ekor sebelum menyuntik, dan mengeluarkan induk babi yang demam, kurang nafsu makan, atau diare dari daftar lalu melaporkannya.","levels_en":["Vaccinates every animal without checking condition, injecting even sows that are clearly unwell.","With guidance, looks at their condition, but the check is a formality and leaves the removal decision and reporting to others.","With guidance, checks the target sows one by one, and can remove unwell sows and report to the supervisor.","Independently never skips the pre-vaccination condition check, and follows up so removed sows are vaccinated after recovery.","Understands how vaccinating unwell sows affects immunity and the sows themselves, and can teach new staff how to judge fitness for vaccination."],"levels_vi":["Không xem sức khỏe mà tiêm hết cả đàn, tiêm cả cho lợn nái rõ ràng đang ốm.","Nếu có chỉ dẫn thì xem sức khỏe, nhưng kiểm tra cho có hình thức, việc quyết định loại khỏi danh sách và báo cáo thì phó mặc người khác.","Nếu có chỉ dẫn thì kiểm tra từng con đối tượng, loại lợn nái sức khỏe kém ra và báo cáo được cấp trên.","Không cần chỉ dẫn cũng không bỏ qua việc kiểm tra sức khỏe trước khi tiêm, còn để tâm đến việc tiêm lại cho lợn nái bị loại sau khi hồi phục.","Hiểu ảnh hưởng của việc tiêm khi sức khỏe kém đến miễn dịch và lợn nái, và có thể hướng dẫn người mới cách nhận định tiêm được hay không."],"levels_id":["Menyuntik semua ekor tanpa melihat kondisinya, bahkan menyuntik induk babi yang jelas-jelas sedang sakit.","Jika ada instruksi bisa melihat kondisinya, tetapi pemeriksaannya sekadar formalitas dan menyerahkan keputusan mengeluarkan dari daftar serta pelaporannya kepada orang lain.","Jika ada instruksi, bisa memeriksa sasaran satu per satu, mengeluarkan induk babi yang tidak sehat, dan melaporkannya ke atasan.","Tanpa instruksi pun, tidak pernah melewatkan pemeriksaan kondisi sebelum penyuntikan, dan memperhatikan sampai penyuntikan ulang induk babi yang dikeluarkan setelah pulih.","Memahami pengaruh penyuntikan saat kondisi buruk terhadap kekebalan dan induk babi, dan bisa mengajari karyawan baru cara menilai boleh-tidaknya divaksin."]},{"id":"injection-site","name":"接種部位と保定・注入手技","kanten":"耳の付け根の後ろの首の筋肉へ90度で素早く刺してゆっくり注入し、無理な保定をしないか。","levels":["腰やお尻に打つ・浅く刺すなど部位と手技が不正確で、動く母豚に無理をして危険を作る。","指示があれば打てるが、刺す角度や部位が安定せず、母豚が動いた時の対応が不確実。","指示があれば首の筋肉に90度で刺してゆっくり注入し、落ち着いた時をねらってひと通り接種できる。","指示がなくても正しい部位・角度を守り、母豚が動いたら手を止め、危ない時は2人や保定具で安全に行う。","浅打ちで効果が落ちる理由と針刺し事故の危険を理解し、部位と保定のコツを新人に指導できる。"],"name_en":"Injection site, restraint, and injection technique","name_vi":"Vị trí tiêm, cách giữ lợn và thao tác tiêm","name_id":"Lokasi suntik, cara memegang, dan teknik penyuntikan","kanten_en":"Do they insert the needle quickly at 90 degrees into the neck muscle behind the base of the ear, inject slowly, and avoid forcing the restraint?","kanten_vi":"Có đâm kim nhanh, góc 90 độ vào cơ cổ phía sau gốc tai, bơm thuốc từ từ, và không cố giữ lợn một cách gượng ép không.","kanten_id":"Apakah menusukkan jarum dengan cepat pada sudut 90 derajat ke otot leher di belakang pangkal telinga, menyuntikkan perlahan, dan tidak memaksakan pemegangannya.","levels_en":["Injects in the wrong place such as the back or rump, inserts shallowly, and forces things with a moving sow, creating danger.","With guidance, can inject, but the angle and site are inconsistent, and their response when the sow moves is unreliable.","With guidance, inserts at 90 degrees into the neck muscle, injects slowly, and can adequately vaccinate by aiming for calm moments.","Independently keeps the correct site and angle, stops when the sow moves, and when it is dangerous, works safely in pairs or with restraint equipment.","Understands why shallow injections reduce effectiveness and the danger of needlestick accidents, and can teach new staff the knack of site and restraint."],"levels_vi":["Tiêm vào lưng hay mông, đâm nông... vị trí và thao tác không chính xác, cố làm với lợn nái đang cựa quậy nên tạo ra nguy hiểm.","Nếu có chỉ dẫn thì tiêm được, nhưng góc đâm và vị trí không ổn định, cách xử lý khi lợn nái cựa quậy không chắc chắn.","Nếu có chỉ dẫn thì đâm 90 độ vào cơ cổ, bơm thuốc từ từ, chọn lúc lợn bình tĩnh và tiêm được cơ bản.","Không cần chỉ dẫn cũng giữ đúng vị trí và góc tiêm, lợn nái cựa quậy thì dừng tay, khi nguy hiểm thì làm 2 người hoặc dùng dụng cụ giữ lợn để an toàn.","Hiểu lý do tiêm nông làm giảm hiệu quả và nguy cơ tai nạn kim đâm vào người, và có thể hướng dẫn người mới bí quyết về vị trí tiêm và cách giữ lợn."],"levels_id":["Menyuntik di pinggang atau pantat, menusuk dangkal — lokasi dan tekniknya tidak tepat, dan memaksakan diri pada induk babi yang bergerak sehingga menimbulkan bahaya.","Jika ada instruksi bisa menyuntik, tetapi sudut dan lokasi tusukan tidak stabil, dan penanganan saat induk babi bergerak tidak pasti.","Jika ada instruksi, bisa menusuk 90 derajat ke otot leher, menyuntikkan perlahan, dan menyuntik secara garis besar dengan memilih saat babi tenang.","Tanpa instruksi pun, menjaga lokasi dan sudut yang benar, berhenti saat induk babi bergerak, dan jika berbahaya bekerja berdua atau memakai alat fiksasi agar aman.","Memahami alasan suntikan dangkal menurunkan efek dan bahaya kecelakaan tertusuk jarum, dan bisa mengajari karyawan baru kiat lokasi suntik dan cara memegang."]},{"id":"record-observe","name":"その場での記録と接種後の観察","kanten":"個体番号・ワクチン名・ロット・量をその場で記録し、接種後30分〜1時間の異常を観察できるか。","levels":["記録を後回しにして漏らし、接種後の豚も見ずに立ち去る。","指示されれば記録するが、ロット番号などの記入漏れが多く、接種後の観察も不十分。","指示があれば打ったその場で記録し、接種後のぐったり・呼吸困難がないかひと通り観察できる。","指示がなくてもその場で漏れなく記録し、アナフィラキシーの兆候や40℃以上の高熱を見つけたらすぐ連絡する。","後書きが二重接種・打ち漏れを生むことと副反応の見分けを理解し、記録と観察を新人に指導できる。"],"name_en":"On-the-spot records and post-vaccination observation","name_vi":"Ghi chép ngay tại chỗ và quan sát sau tiêm","name_id":"Pencatatan langsung di tempat dan pengamatan setelah penyuntikan","kanten_en":"Can they record the animal number, vaccine name, lot, and dose on the spot, and observe for abnormalities for 30 minutes to 1 hour after vaccination?","kanten_vi":"Có ghi ngay tại chỗ số hiệu con, tên vắc-xin, số lô, liều lượng, và quan sát bất thường trong 30 phút〜1 tiếng sau tiêm không.","kanten_id":"Apakah mencatat langsung di tempat nomor individu, nama vaksin, lot, dan dosis, serta mengamati kelainan selama 30 menit〜1 jam setelah penyuntikan.","levels_en":["Puts off recording and misses entries, and walks away without watching the pigs after vaccination.","Records when instructed, but often omits the lot number and other entries, and post-vaccination observation is insufficient.","With guidance, records on the spot right after injecting, and can adequately observe for limpness or breathing difficulty afterward.","Independently records completely on the spot, and contacts someone immediately upon finding signs of anaphylaxis or a fever of 40°C or higher.","Understands that writing records later causes double or missed injections and how to recognize adverse reactions, and can teach new staff recording and observation."],"levels_vi":["Để việc ghi chép lại sau nên bỏ sót, tiêm xong cũng không nhìn lợn mà bỏ đi.","Nếu được chỉ dẫn thì ghi chép, nhưng hay bỏ sót số lô..., việc quan sát sau tiêm cũng chưa đủ.","Nếu có chỉ dẫn thì ghi ngay tại chỗ sau khi tiêm, quan sát được cơ bản xem có con nào lả đi, khó thở không.","Không cần chỉ dẫn cũng ghi đầy đủ ngay tại chỗ, thấy dấu hiệu sốc phản vệ hay sốt cao trên 40℃ thì liên lạc ngay.","Hiểu việc ghi sau sinh ra tiêm trùng, sót tiêm và cách nhận biết phản ứng phụ, và có thể hướng dẫn người mới việc ghi chép và quan sát."],"levels_id":["Menunda pencatatan sehingga ada yang terlewat, dan pergi begitu saja tanpa melihat babi setelah disuntik.","Jika disuruh bisa mencatat, tetapi sering lupa mengisi nomor lot dan lainnya, dan pengamatan setelah penyuntikan juga kurang.","Jika ada instruksi, bisa mencatat langsung di tempat setelah menyuntik, dan mengamati secara garis besar apakah ada yang lemas atau sesak napas.","Tanpa instruksi pun, mencatat lengkap langsung di tempat, dan segera menghubungi jika menemukan tanda anafilaksis atau demam tinggi 40℃ ke atas.","Memahami bahwa mencatat belakangan menimbulkan suntikan ganda atau terlewat serta cara mengenali reaksi samping, dan bisa mengajari karyawan baru pencatatan dan pengamatan."]}],"name_en":"Sow vaccination","name_vi":"Tiêm vắc-xin cho lợn nái","name_id":"Vaksinasi induk babi","purposeShort_en":"Build immunity that protects sows and piglets, and even out the farm's immunity level","purposeShort_vi":"Tạo miễn dịch bảo vệ lợn nái và lợn con, làm đồng đều mức miễn dịch của trại","purposeShort_id":"Membangun kekebalan yang melindungi induk babi dan anak babi, dan menyeragamkan tingkat kekebalan peternakan"},{"id":"csf-vaccine","category":"hygiene","no":"No.41","name":"CSF（豚熱）子ワクチン接種","purposeShort":"子豚の免疫を立ち上げ、豚熱の発生・死亡と経済被害を防ぐ","gyomu":"41","aspects":[{"id":"maternal-antibody","name":"移行抗体を考えた接種日齢","kanten":"移行抗体を考慮し、決められた日齢で接種して免疫獲得の失敗を防げるか。","levels":["移行抗体を考えず、抗体の高い時期に接種して免疫獲得を失敗させる。","指示があれば接種するが、対象の日齢確認に漏れがあり、日をずらすことの影響を知らない。","指示があれば決められた日齢でひと通り接種できる。","指示がなくても移行抗体を考えた日齢で接種し、確実な免疫獲得を意識する。","移行抗体が残るうちに打つと効かないことを理解し、決められた日齢を守る理由を新人に指導できる。"],"name_en":"Vaccination age accounting for maternal antibodies","name_vi":"Tuổi ngày tiêm có tính đến kháng thể mẹ truyền","name_id":"Umur penyuntikan yang mempertimbangkan antibodi dari induk","kanten_en":"Can they take maternal antibodies into account and vaccinate at the prescribed age to prevent immunization failure?","kanten_vi":"Có tính đến kháng thể mẹ truyền, tiêm đúng tuổi ngày quy định để tránh thất bại trong việc tạo miễn dịch không.","kanten_id":"Apakah mempertimbangkan antibodi dari induk (antibodi maternal) dan menyuntik pada umur yang ditentukan, sehingga mencegah gagalnya pembentukan kekebalan.","levels_en":["Ignores maternal antibodies and vaccinates while antibody levels are high, causing immunization failure.","With guidance, vaccinates, but is inconsistent about confirming the target age in days and does not know the effect of shifting the date.","With guidance, can adequately vaccinate at the prescribed age.","Independently vaccinates at an age that accounts for maternal antibodies, keeping reliable immunization in mind.","Understands that vaccinating while maternal antibodies remain does not work, and can teach new staff the reason for keeping to the prescribed age."],"levels_vi":["Không nghĩ đến kháng thể mẹ truyền, tiêm vào thời kỳ kháng thể còn cao làm việc tạo miễn dịch thất bại.","Nếu có chỉ dẫn thì tiêm, nhưng có bỏ sót việc kiểm tra tuổi ngày của đối tượng, không biết ảnh hưởng của việc xê dịch ngày tiêm.","Nếu có chỉ dẫn thì tiêm được cơ bản theo đúng tuổi ngày quy định.","Không cần chỉ dẫn cũng tiêm ở tuổi ngày có tính đến kháng thể mẹ truyền, ý thức việc tạo miễn dịch chắc chắn.","Hiểu tiêm khi kháng thể mẹ truyền còn lại sẽ không có tác dụng, và có thể hướng dẫn người mới lý do phải giữ đúng tuổi ngày quy định."],"levels_id":["Tidak memikirkan antibodi dari induk, menyuntik saat antibodi masih tinggi sehingga pembentukan kekebalan gagal.","Jika ada instruksi bisa menyuntik, tetapi sering lalai memeriksa umur hari sasaran dan tidak tahu pengaruh menggeser tanggalnya.","Jika ada instruksi, bisa menyuntik secara garis besar pada umur yang ditentukan.","Tanpa instruksi pun, menyuntik pada umur yang mempertimbangkan antibodi dari induk, dan sadar akan pembentukan kekebalan yang pasti.","Memahami bahwa menyuntik selagi antibodi dari induk masih tersisa tidak akan bekerja, dan bisa mengajari karyawan baru alasan mematuhi umur hari yang ditentukan."]},{"id":"no-miss","name":"全頭接種と記録","kanten":"「寄せる→打つ→印→反対側→頭数照合」を守り、打ち漏れなく全頭接種して記録を残せるか。","levels":["子豚を寄せずに打ち始め、マーキングも頭数照合もせず「たぶん打った」で先に進む。","指示があれば接種するが、マーキングや豚房ごとの頭数照合に漏れが多い。","指示があれば寄せる→打つ→印→反対側→照合の流れをひと通り守り、記録できる。","指示がなくても毎豚房で流れを徹底し、数が合わなければ全頭を見直して印のない豚を探して打つ。","打ち漏れが防疫上の穴になることを理解し、全頭接種の流れと記録の徹底を新人に指導できる。"],"name_en":"Whole-herd vaccination and records","name_vi":"Tiêm đủ cả đàn và ghi chép","name_id":"Penyuntikan semua ekor dan pencatatan","kanten_en":"Can they follow \"gather, inject, mark, other side, count check\", vaccinate every animal without misses, and keep records?","kanten_vi":"Có giữ trình tự \"dồn lợn → tiêm → đánh dấu → phía đối diện → đối chiếu số con\", tiêm đủ cả đàn không sót và để lại ghi chép không.","kanten_id":"Apakah mematuhi alur \"kumpulkan → suntik → tandai → sisi seberang → cocokkan jumlah ekor\", menyuntik semua ekor tanpa terlewat, dan meninggalkan catatan.","levels_en":["Starts injecting without gathering the piglets, does no marking or count checking, and moves on with \"probably injected\".","With guidance, vaccinates, but often fails at marking and per-pen count checks.","With guidance, can adequately follow the flow of gather, inject, mark, other side, check, and keep records.","Independently keeps the flow in every pen, and if the numbers do not match, rechecks all pigs to find and inject the unmarked ones.","Understands that missed injections become holes in biosecurity, and can teach new staff the whole-herd vaccination flow and thorough record-keeping."],"levels_vi":["Không dồn lợn con lại mà bắt đầu tiêm, không đánh dấu cũng không đối chiếu số con, cứ \"chắc là tiêm rồi\" mà làm tiếp.","Nếu có chỉ dẫn thì tiêm, nhưng hay bỏ sót việc đánh dấu và đối chiếu số con theo từng ô chuồng.","Nếu có chỉ dẫn thì giữ được cơ bản trình tự dồn → tiêm → đánh dấu → phía đối diện → đối chiếu, và ghi chép được.","Không cần chỉ dẫn cũng giữ nghiêm trình tự ở từng ô chuồng, nếu số không khớp thì xem lại cả đàn, tìm con chưa có dấu để tiêm.","Hiểu con sót tiêm là lỗ hổng trong phòng dịch, và có thể hướng dẫn người mới trình tự tiêm đủ cả đàn và việc ghi chép nghiêm túc."],"levels_id":["Mulai menyuntik tanpa mengumpulkan anak babi, tidak menandai dan tidak mencocokkan jumlah ekor, lalu lanjut dengan \"mungkin sudah disuntik\".","Jika ada instruksi bisa menyuntik, tetapi sering lalai menandai dan mencocokkan jumlah ekor per petak kandang.","Jika ada instruksi, bisa mematuhi secara garis besar alur kumpulkan → suntik → tandai → sisi seberang → cocokkan, dan mencatatnya.","Tanpa instruksi pun, menjalankan alur itu di setiap petak kandang, dan jika jumlahnya tidak cocok memeriksa ulang semua babi untuk mencari yang belum bertanda dan menyuntiknya.","Memahami bahwa penyuntikan yang terlewat menjadi lubang biosekuriti, dan bisa mengajari karyawan baru alur penyuntikan semua ekor dan pencatatan yang menyeluruh."]},{"id":"restraint-team","name":"保定・連携と確実な筋注","kanten":"両後脚で保定し、2人1組の声かけで連携して、首の筋肉へ90度で確実に接種できるか。","levels":["片脚で持ち上げる・無理に押さえて暴れさせるなど危険な保定をし、浅く刺して筋肉に届かない。","指示があれば保定・接種するが、声かけや役割分担が不十分で、部位や角度が安定しない。","指示があれば両後脚で頭を下に保定し、耳の付け根の後ろの首の筋肉へ90度でひと通り接種できる。","指示がなくても保定係・接種係で声をかけ合い、豚が暴れたら仕切り直して安全・確実に筋注する。","片脚保定が関節を痛めることと浅打ちのリスクを理解し、保定と連携のコツを新人に指導できる。"],"name_en":"Restraint, teamwork, and reliable intramuscular injection","name_vi":"Giữ lợn, phối hợp và tiêm bắp chắc chắn","name_id":"Pemegangan, kerja sama, dan suntikan intramuskular yang pasti","kanten_en":"Can they restrain by both hind legs, coordinate in pairs by calling out, and inject reliably at 90 degrees into the neck muscle?","kanten_vi":"Có giữ lợn bằng cả hai chân sau, phối hợp theo cặp 2 người bằng cách lên tiếng gọi nhau, và tiêm chắc chắn góc 90 độ vào cơ cổ không.","kanten_id":"Apakah memegang dengan kedua kaki belakang, bekerja sama berpasangan sambil saling memberi aba-aba, dan menyuntik dengan pasti pada sudut 90 derajat ke otot leher.","levels_en":["Restrains dangerously — lifting by one leg or forcing pigs down until they struggle — and inserts shallowly so the needle does not reach the muscle.","With guidance, restrains and injects, but calling out and role-sharing are insufficient, and the site and angle are inconsistent.","With guidance, restrains by both hind legs with the head down, and can adequately inject at 90 degrees into the neck muscle behind the base of the ear.","Independently calls back and forth between the restrainer and injector, and when a pig struggles, resets and gives the intramuscular injection safely and reliably.","Understands that one-leg restraint damages the joints and the risks of shallow injection, and can teach new staff the knack of restraint and teamwork."],"levels_vi":["Giữ lợn nguy hiểm như nhấc bằng một chân, đè ép làm lợn giãy giụa, đâm nông nên kim không tới cơ.","Nếu có chỉ dẫn thì giữ và tiêm được, nhưng việc lên tiếng gọi nhau và phân vai chưa đủ, vị trí và góc tiêm không ổn định.","Nếu có chỉ dẫn thì giữ bằng cả hai chân sau cho đầu hướng xuống, tiêm được cơ bản góc 90 độ vào cơ cổ phía sau gốc tai.","Không cần chỉ dẫn cũng gọi nhau giữa người giữ và người tiêm, lợn giãy thì làm lại từ đầu, tiêm bắp an toàn và chắc chắn.","Hiểu giữ bằng một chân sẽ làm hỏng khớp và nguy cơ của tiêm nông, và có thể hướng dẫn người mới bí quyết giữ lợn và phối hợp."],"levels_id":["Memegang dengan cara berbahaya seperti mengangkat dengan satu kaki atau menekan paksa sampai meronta, dan menusuk dangkal sehingga tidak sampai ke otot.","Jika ada instruksi bisa memegang dan menyuntik, tetapi aba-aba dan pembagian peran kurang, sehingga lokasi dan sudutnya tidak stabil.","Jika ada instruksi, bisa memegang dengan kedua kaki belakang dengan kepala di bawah, dan menyuntik secara garis besar pada sudut 90 derajat ke otot leher di belakang pangkal telinga.","Tanpa instruksi pun, saling memberi aba-aba antara pemegang dan penyuntik, dan jika babi meronta, mengulang dari awal lalu menyuntik intramuskular dengan aman dan pasti.","Memahami bahwa memegang dengan satu kaki merusak sendi dan risiko suntikan dangkal, dan bisa mengajari karyawan baru kiat memegang dan bekerja sama."]},{"id":"needle-mgmt","name":"針の本数照合・交換・針刺し対応","kanten":"針の本数を作業前後で照合し、1腹ごとに交換し、針折れ・針刺し時に正しく対応できるか。","levels":["本数を数えず古い針を使い続け、リキャップするなど針折れ・針刺しの危険を放置する。","指示があれば数えるが、照合や1腹ごとの交換、シャープスコンテナへの廃棄に漏れがある。","指示があれば本数を記録・照合し、1腹ごとに交換してシャープスコンテナにひと通り廃棄できる。","指示がなくても本数管理を徹底し、針折れ疑いはその豚に印をつけて即報告、針刺し時は流水で洗って報告する。","針残留が食肉混入の重大事故になることを理解し、本数管理と事故対応を新人に指導できる。"],"name_en":"Needle count checks, changes, and needlestick response","name_vi":"Đối chiếu số kim, thay kim và xử lý khi bị kim đâm","name_id":"Pencocokan jumlah jarum, penggantian, dan penanganan tertusuk jarum","kanten_en":"Can they check needle counts before and after work, change needles for each litter, and respond correctly to needle breakage or needlestick?","kanten_vi":"Có đối chiếu số kim trước và sau khi làm, thay kim theo từng ổ lợn con, và xử lý đúng khi kim gãy hoặc bị kim đâm không.","kanten_id":"Apakah mencocokkan jumlah jarum sebelum dan sesudah bekerja, mengganti jarum setiap kelompok anak babi seinduk, dan menangani dengan benar saat jarum patah atau tertusuk jarum.","levels_en":["Does not count needles, keeps using old ones, and recaps them, leaving the dangers of breakage and needlestick unaddressed.","With guidance, counts, but is inconsistent about checking, changing needles per litter, and disposal into the sharps container.","With guidance, records and checks the counts, changes needles per litter, and can adequately dispose of them into the sharps container.","Independently manages the counts rigorously; on suspected needle breakage, marks that pig and reports immediately, and on needlestick, washes under running water and reports.","Understands that a retained needle becomes a serious meat-contamination accident, and can teach new staff count management and accident response."],"levels_vi":["Không đếm số kim, dùng mãi kim cũ, còn đậy lại nắp kim..., bỏ mặc nguy cơ gãy kim và bị kim đâm.","Nếu có chỉ dẫn thì đếm, nhưng có bỏ sót việc đối chiếu, thay kim theo từng ổ và bỏ kim vào hộp đựng kim (sharps container).","Nếu có chỉ dẫn thì ghi và đối chiếu số kim, thay theo từng ổ và bỏ được cơ bản vào hộp đựng kim.","Không cần chỉ dẫn cũng quản lý chặt số kim, nghi gãy kim thì đánh dấu con lợn đó và báo ngay, bị kim đâm thì rửa dưới vòi nước chảy rồi báo cáo.","Hiểu kim sót lại trong cơ thể là sự cố nghiêm trọng lẫn vào thịt, và có thể hướng dẫn người mới cách quản lý số kim và xử lý sự cố."],"levels_id":["Tidak menghitung jumlah jarum, terus memakai jarum lama, dan memasang kembali tutup jarum, membiarkan bahaya jarum patah dan tertusuk jarum.","Jika ada instruksi bisa menghitung, tetapi sering lalai mencocokkan, mengganti jarum per kelompok seinduk, dan membuangnya ke wadah jarum bekas (sharps container).","Jika ada instruksi, bisa mencatat dan mencocokkan jumlah, mengganti per kelompok seinduk, dan membuangnya secara garis besar ke wadah jarum bekas.","Tanpa instruksi pun, mengelola jumlah jarum dengan ketat; jika dicurigai jarum patah, menandai babi itu dan segera melapor, dan jika tertusuk jarum, mencucinya di air mengalir lalu melapor.","Memahami bahwa jarum yang tertinggal menjadi kecelakaan serius berupa masuknya jarum ke daging, dan bisa mengajari karyawan baru pengelolaan jumlah jarum dan penanganan kecelakaan."]},{"id":"cold-chain","name":"ワクチンの冷蔵管理と品質確認","kanten":"2〜8℃の冷蔵保管を守り、期限切れ・変色・沈殿のあるワクチンは使わず報告できるか。","levels":["常温に放置したり期限や外観を見ずに使い、効かないワクチンを打つ危険を作る。","指示があれば冷蔵庫から出し入れするが、期限・変色・沈殿の確認に漏れが多い。","指示があれば使用直前に取り出し、薬品名・期限・外観をひと通り確認して使える。","指示がなくても冷蔵管理を守り、異常のあるワクチンは使わずに報告して交換する。","温度逸脱で失活する仕組みを理解し、冷蔵管理と品質確認の要点を新人に指導できる。"],"name_en":"Vaccine refrigeration and quality checks","name_vi":"Bảo quản lạnh vắc-xin và kiểm tra chất lượng","name_id":"Penyimpanan dingin vaksin dan pemeriksaan mutu","kanten_en":"Do they keep refrigerated storage at 2-8°C, and not use but report vaccines that are expired, discolored, or have sediment?","kanten_vi":"Có giữ bảo quản lạnh 2〜8℃, không dùng vắc-xin hết hạn, đổi màu, có cặn mà báo cáo không.","kanten_id":"Apakah menjaga penyimpanan dingin 2〜8℃, dan tidak memakai vaksin yang kedaluwarsa, berubah warna, atau berendapan melainkan melaporkannya.","levels_en":["Leaves vaccines at room temperature or uses them without checking the expiry date and appearance, creating the risk of injecting ineffective vaccines.","With guidance, takes vaccines in and out of the refrigerator, but often fails to check expiry, discoloration, and sediment.","With guidance, takes vaccines out just before use and can adequately check the product name, expiry date, and appearance before using.","Independently keeps the refrigeration rules, and does not use abnormal vaccines but reports and replaces them.","Understands how temperature deviations inactivate vaccines, and can teach new staff the key points of refrigeration and quality checks."],"levels_vi":["Để vắc-xin ở nhiệt độ thường, dùng mà không xem hạn và bề ngoài, tạo nguy cơ tiêm vắc-xin không còn tác dụng.","Nếu có chỉ dẫn thì lấy ra cất vào tủ lạnh, nhưng hay bỏ sót việc kiểm tra hạn, đổi màu, cặn.","Nếu có chỉ dẫn thì lấy ra ngay trước khi dùng, kiểm tra được cơ bản tên thuốc, hạn dùng, bề ngoài rồi mới dùng.","Không cần chỉ dẫn cũng giữ việc bảo quản lạnh, vắc-xin có bất thường thì không dùng mà báo cáo để đổi.","Hiểu cơ chế vắc-xin mất hiệu lực khi nhiệt độ lệch chuẩn, và có thể hướng dẫn người mới các điểm chính của bảo quản lạnh và kiểm tra chất lượng."],"levels_id":["Membiarkan vaksin di suhu ruang atau memakainya tanpa melihat tanggal kedaluwarsa dan penampilannya, menciptakan bahaya menyuntikkan vaksin yang tidak bekerja.","Jika ada instruksi bisa mengeluarkan dan memasukkan ke kulkas, tetapi sering lalai memeriksa kedaluwarsa, perubahan warna, dan endapan.","Jika ada instruksi, bisa mengeluarkannya tepat sebelum dipakai dan memeriksa secara garis besar nama obat, kedaluwarsa, dan penampilannya sebelum dipakai.","Tanpa instruksi pun, menjaga penyimpanan dingin, dan tidak memakai vaksin yang abnormal melainkan melaporkannya untuk diganti.","Memahami mekanisme vaksin kehilangan daya karena penyimpangan suhu, dan bisa mengajari karyawan baru poin penting penyimpanan dingin dan pemeriksaan mutu."]}],"name_en":"CSF (classical swine fever) piglet vaccination","name_vi":"Tiêm vắc-xin CSF (dịch tả lợn cổ điển) cho lợn con","name_id":"Vaksinasi CSF (demam babi klasik) untuk anak babi","purposeShort_en":"Establish piglet immunity and prevent CSF outbreaks, deaths, and economic damage","purposeShort_vi":"Tạo miễn dịch cho lợn con, phòng bệnh dịch tả lợn phát sinh, chết và thiệt hại kinh tế","purposeShort_id":"Membangun kekebalan anak babi, mencegah kejadian dan kematian demam babi klasik serta kerugian ekonomi"},{"id":"washing","category":"hygiene","no":"No.40","name":"洗浄（離乳後）","purposeShort":"汚れと病原体を物理的に落とし、消毒が効く状態を作り舎内をリセットする","gyomu":"40","aspects":[{"id":"wash-order","name":"除糞→洗浄→乾燥→消毒の順序","kanten":"除糞→洗浄→乾燥→消毒の決められた順序を守り、有機物を残したまま消毒しないか。","levels":["有機物が残った状態で消毒薬を散布し、乾燥不十分のまま次ロットを入れる。","指示があれば洗浄するが、順序や乾燥の徹底に漏れが多い。","指示があれば除糞→洗浄→乾燥→消毒の順序をひと通り守れる。","指示がなくても順序を守り、有機物を落としてから消毒し、十分に乾燥させる。","有機物残存が消毒を無効化することを理解し、洗浄・乾燥の徹底を新人に指導できる。"],"name_en":"Order of manure removal, washing, drying, then disinfection","name_vi":"Thứ tự dọn phân → rửa → làm khô → khử trùng","name_id":"Urutan bersihkan kotoran → cuci → keringkan → disinfeksi","kanten_en":"Do they follow the prescribed order of manure removal, washing, drying, then disinfection, and avoid disinfecting over remaining organic matter?","kanten_vi":"Có giữ đúng thứ tự quy định dọn phân → rửa → làm khô → khử trùng, không khử trùng khi chất hữu cơ còn sót không.","kanten_id":"Apakah mematuhi urutan yang ditentukan bersihkan kotoran → cuci → keringkan → disinfeksi, dan tidak mendisinfeksi selagi bahan organik masih tersisa.","levels_en":["Sprays disinfectant over remaining organic matter and brings in the next lot without sufficient drying.","With guidance, washes, but often skips steps in the order and fails to dry thoroughly.","With guidance, can adequately follow the order of manure removal, washing, drying, then disinfection.","Independently follows the order, removes organic matter before disinfecting, and dries thoroughly.","Understands that remaining organic matter neutralizes disinfection, and can teach new staff thorough washing and drying."],"levels_vi":["Phun thuốc khử trùng khi chất hữu cơ còn sót, đưa lứa lợn mới vào khi chuồng chưa khô đủ.","Nếu có chỉ dẫn thì rửa, nhưng hay bỏ sót thứ tự và việc làm khô kỹ.","Nếu có chỉ dẫn thì giữ được cơ bản thứ tự dọn phân → rửa → làm khô → khử trùng.","Không cần chỉ dẫn cũng giữ đúng thứ tự, loại bỏ chất hữu cơ trước rồi mới khử trùng, làm khô đầy đủ.","Hiểu chất hữu cơ còn sót làm khử trùng mất tác dụng, và có thể hướng dẫn người mới việc rửa và làm khô kỹ."],"levels_id":["Menyemprotkan disinfektan dalam keadaan bahan organik masih tersisa, dan memasukkan kelompok berikutnya selagi belum kering.","Jika ada instruksi bisa mencuci, tetapi sering lalai mematuhi urutan dan pengeringan menyeluruh.","Jika ada instruksi, bisa mematuhi urutan secara garis besar: bersihkan kotoran → cuci → keringkan → disinfeksi.","Tanpa instruksi pun, mematuhi urutan, menghilangkan bahan organik dulu baru mendisinfeksi, dan mengeringkan dengan cukup.","Memahami bahwa bahan organik yang tersisa membuat disinfeksi tidak berguna, dan bisa mengajari karyawan baru pentingnya pencucian dan pengeringan menyeluruh."]},{"id":"hidden-spots","name":"隅・溝・裏側の重点洗浄","kanten":"隅・溝・エサ箱・スノコ裏など汚れが溜まりやすい見えにくい場所を重点的に洗えるか。","levels":["見えやすい所だけ洗い、隅・溝・スノコ裏などの汚れを残す。","指示があれば洗うが、見えにくい場所の洗浄に漏れが多い。","指示があれば汚れが溜まりやすい場所をひと通り洗える。","指示がなくても隅・溝・スノコ裏まで重点的に洗い、汚れを残さない。","見えにくい場所の病原残存リスクを理解し、重点洗浄の着眼点を新人に指導できる。"],"name_en":"Focused washing of corners, grooves, and undersides","name_vi":"Rửa kỹ góc, rãnh và mặt sau","name_id":"Pencucian intensif sudut, parit, dan bagian belakang","kanten_en":"Can they focus on hard-to-see spots where dirt accumulates — corners, grooves, feed boxes, and the undersides of slats?","kanten_vi":"Có rửa kỹ những chỗ khó nhìn thấy, dễ đọng bẩn như góc, rãnh, máng ăn, mặt sau sàn khe không.","kanten_id":"Apakah bisa mencuci secara intensif tempat-tempat tersembunyi yang mudah menumpuk kotoran seperti sudut, parit, kotak pakan, dan bagian bawah lantai slat.","levels_en":["Washes only visible areas, leaving dirt in corners, grooves, and under the slats.","With guidance, washes, but often misses hard-to-see spots.","With guidance, can adequately wash the spots where dirt accumulates.","Independently focuses on corners, grooves, and slat undersides, leaving no dirt behind.","Understands the risk of pathogens surviving in hard-to-see spots, and can teach new staff where to focus the washing."],"levels_vi":["Chỉ rửa chỗ dễ nhìn thấy, để sót bẩn ở góc, rãnh, mặt sau sàn khe.","Nếu có chỉ dẫn thì rửa, nhưng hay bỏ sót việc rửa những chỗ khó nhìn thấy.","Nếu có chỉ dẫn thì rửa được cơ bản những chỗ dễ đọng bẩn.","Không cần chỉ dẫn cũng rửa kỹ đến tận góc, rãnh, mặt sau sàn khe, không để sót bẩn.","Hiểu nguy cơ mầm bệnh còn sót ở những chỗ khó nhìn thấy, và có thể hướng dẫn người mới các điểm cần chú ý khi rửa kỹ."],"levels_id":["Hanya mencuci bagian yang mudah terlihat, meninggalkan kotoran di sudut, parit, dan bawah lantai slat.","Jika ada instruksi bisa mencuci, tetapi sering lalai mencuci tempat yang sulit terlihat.","Jika ada instruksi, bisa mencuci secara garis besar tempat-tempat yang mudah menumpuk kotoran.","Tanpa instruksi pun, mencuci intensif sampai sudut, parit, dan bawah lantai slat tanpa meninggalkan kotoran.","Memahami risiko bibit penyakit yang tersisa di tempat yang sulit terlihat, dan bisa mengajari karyawan baru titik fokus pencucian intensif."]},{"id":"allout-safety","name":"オールアウト確認と洗浄時の安全","kanten":"豚が1頭も残っていないことを記録と突き合わせ、電源を切りノズルを人に向けず作業できるか。","levels":["豚の残留を確かめずに洗い始め、回っているファンに水をかけたりノズルを人に向けたりする。","指示があれば確認するが、記録との突き合わせや電源の切り忘れが多い。","指示があれば全豚房を歩いて残留ゼロを確かめ、電源を切り防護具を着けてひと通り作業できる。","指示がなくてもオールアウトを記録と照合してから始め、感電・高圧水の危険を避けて安全に洗う。","高圧水が皮膚を切る力を持つことと感電の危険を理解し、洗浄の安全手順を新人に指導できる。"],"name_en":"All-out confirmation and safety during washing","name_vi":"Xác nhận đã chuyển hết lợn (all-out) và an toàn khi rửa","name_id":"Konfirmasi kandang kosong (all-out) dan keselamatan saat mencuci","kanten_en":"Can they verify against the records that not a single pig remains, switch off the power, and work without pointing the nozzle at people?","kanten_vi":"Có đối chiếu với ghi chép để chắc chắn không còn con lợn nào, tắt nguồn điện, và làm việc không chĩa vòi phun vào người không.","kanten_id":"Apakah mencocokkan dengan catatan bahwa tidak ada satu ekor babi pun yang tersisa, mematikan listrik, dan bekerja tanpa mengarahkan nozel ke orang.","levels_en":["Starts washing without checking for remaining pigs, sprays water on running fans, and points the nozzle at people.","With guidance, checks, but often skips verifying against records and forgets to switch off the power.","With guidance, walks all pens to confirm zero pigs remain, switches off the power, and can adequately work in protective gear.","Independently verifies the all-out against records before starting, and washes safely, avoiding the dangers of electric shock and high-pressure water.","Understands that high-pressure water can cut skin and the danger of electric shock, and can teach new staff the safety procedures for washing."],"levels_vi":["Không kiểm tra còn lợn sót hay không đã bắt đầu rửa, xịt nước vào quạt đang quay, chĩa vòi phun vào người.","Nếu có chỉ dẫn thì kiểm tra, nhưng hay bỏ sót việc đối chiếu với ghi chép và quên tắt nguồn điện.","Nếu có chỉ dẫn thì đi hết các ô chuồng để chắc chắn không còn con nào, tắt nguồn điện, đeo đồ bảo hộ và làm được cơ bản.","Không cần chỉ dẫn cũng đối chiếu việc chuyển hết lợn với ghi chép rồi mới bắt đầu, tránh nguy cơ điện giật và nước áp lực cao để rửa an toàn.","Hiểu nước áp lực cao đủ mạnh để cắt da và nguy cơ điện giật, và có thể hướng dẫn người mới quy trình an toàn khi rửa."],"levels_id":["Mulai mencuci tanpa memastikan tidak ada babi tersisa, menyiram kipas yang sedang berputar, dan mengarahkan nozel ke orang.","Jika ada instruksi bisa memeriksa, tetapi sering lupa mencocokkan dengan catatan dan mematikan listrik.","Jika ada instruksi, bisa berjalan memeriksa semua petak kandang untuk memastikan nol babi tersisa, mematikan listrik, dan bekerja secara garis besar dengan alat pelindung.","Tanpa instruksi pun, mencocokkan kandang kosong dengan catatan sebelum mulai, dan mencuci dengan aman menghindari bahaya sengatan listrik dan air bertekanan tinggi.","Memahami bahwa air bertekanan tinggi bisa melukai kulit dan bahaya sengatan listrik, dan bisa mengajari karyawan baru prosedur keselamatan pencucian."]},{"id":"soak-rinse","name":"洗浄剤の浸漬と完全すすぎ","kanten":"洗浄剤を規定濃度で20〜30分浸漬させ、すすぎ後に白い紙で汚れ残りを確認できるか。","levels":["浸漬を待たずに洗い始め、すすぎも不十分で洗剤や汚れを残したまま終える。","指示があれば洗浄剤を使うが、浸漬時間の確保やすすぎの徹底に漏れが多い。","指示があれば規定濃度で浸漬させ、すすいだ後に白い紙でひと通り確認できる。","指示がなくても浸漬時間を確保して効率よく洗い、紙に汚れが付けばもう一度洗い直す。","浸漬が汚れを浮かせる仕組みと残留洗剤が子豚に害になることを理解し、確認法を新人に指導できる。"],"name_en":"Detergent soaking and complete rinsing","name_vi":"Ngâm chất tẩy rửa và xối sạch hoàn toàn","name_id":"Perendaman deterjen dan pembilasan tuntas","kanten_en":"Can they soak with detergent at the prescribed concentration for 20-30 minutes, and after rinsing, check for remaining dirt with white paper?","kanten_vi":"Có ngâm chất tẩy rửa theo nồng độ quy định 20〜30 phút, sau khi xối dùng giấy trắng kiểm tra bẩn còn sót không.","kanten_id":"Apakah merendam dengan deterjen pada konsentrasi yang ditentukan selama 20〜30 menit, dan setelah membilas memeriksa sisa kotoran dengan kertas putih.","levels_en":["Starts washing without waiting for the soak, rinses insufficiently, and finishes leaving detergent and dirt behind.","With guidance, uses detergent, but often fails to secure the soaking time and rinse thoroughly.","With guidance, soaks at the prescribed concentration and can adequately check with white paper after rinsing.","Independently secures the soaking time to wash efficiently, and rewashes if dirt sticks to the paper.","Understands how soaking lifts dirt and that residual detergent harms piglets, and can teach new staff the checking method."],"levels_vi":["Không chờ ngâm đã bắt đầu rửa, xối cũng không đủ, kết thúc mà còn sót chất tẩy và bẩn.","Nếu có chỉ dẫn thì dùng chất tẩy rửa, nhưng hay bỏ sót việc bảo đảm thời gian ngâm và xối kỹ.","Nếu có chỉ dẫn thì ngâm theo nồng độ quy định, sau khi xối kiểm tra được cơ bản bằng giấy trắng.","Không cần chỉ dẫn cũng bảo đảm thời gian ngâm để rửa hiệu quả, giấy còn dính bẩn thì rửa lại lần nữa.","Hiểu cơ chế ngâm làm chất bẩn nổi lên và chất tẩy còn sót gây hại cho lợn con, và có thể hướng dẫn người mới cách kiểm tra."],"levels_id":["Mulai mencuci tanpa menunggu perendaman, membilas tidak cukup, dan selesai dengan meninggalkan deterjen dan kotoran.","Jika ada instruksi bisa memakai deterjen, tetapi sering lalai memastikan waktu perendaman dan membilas dengan tuntas.","Jika ada instruksi, bisa merendam pada konsentrasi yang ditentukan dan memeriksa secara garis besar dengan kertas putih setelah membilas.","Tanpa instruksi pun, memastikan waktu perendaman agar mencuci dengan efisien, dan mencuci ulang jika kotoran menempel di kertas.","Memahami mekanisme perendaman mengangkat kotoran dan bahwa sisa deterjen berbahaya bagi anak babi, dan bisa mengajari karyawan baru cara memeriksanya."]},{"id":"dry-next-lot","name":"乾燥時間の確保と次ロット準備","kanten":"洗浄後・消毒後の乾燥時間を確保し、温度設定・飲水器・保温灯を確認して受け入れ準備できるか。","levels":["乾燥を待たずに次工程へ進み、次ロットの準備もせずに子豚を迎えさせる。","指示があれば乾燥させるが、時間の確保や飲水器・保温灯の確認に漏れが多い。","指示があれば決められた乾燥時間を確保し、温度・飲水・保温灯をひと通り確認できる。","指示がなくても季節に応じて乾燥時間を延ばし、換気で乾燥を早め、受け入れ準備の不備を直す。","湿ったままの消毒が効かない理由と空舎期間の意味を理解し、乾燥と準備の要点を新人に指導できる。"],"name_en":"Securing drying time and preparing for the next lot","name_vi":"Bảo đảm thời gian làm khô và chuẩn bị cho lứa tiếp theo","name_id":"Memastikan waktu pengeringan dan persiapan kelompok berikutnya","kanten_en":"Can they secure drying time after washing and after disinfection, and prepare for intake by checking the temperature setting, drinkers, and heat lamps?","kanten_vi":"Có bảo đảm thời gian làm khô sau khi rửa và sau khi khử trùng, kiểm tra cài đặt nhiệt độ, vòi uống nước, đèn sưởi để chuẩn bị đón lợn không.","kanten_id":"Apakah memastikan waktu pengeringan setelah mencuci dan setelah disinfeksi, serta menyiapkan penerimaan dengan memeriksa pengaturan suhu, alat minum, dan lampu penghangat.","levels_en":["Moves to the next step without waiting for drying, and lets piglets come in without preparing for the next lot.","With guidance, dries, but often fails to secure the time and check the drinkers and heat lamps.","With guidance, secures the prescribed drying time and can adequately check the temperature, water, and heat lamps.","Independently extends drying time according to the season, speeds up drying with ventilation, and fixes any gaps in the intake preparation.","Understands why disinfection does not work while wet and the meaning of the empty-barn period, and can teach new staff the key points of drying and preparation."],"levels_vi":["Không chờ khô đã chuyển sang bước tiếp theo, cũng không chuẩn bị cho lứa mới mà để đón lợn con vào.","Nếu có chỉ dẫn thì làm khô, nhưng hay bỏ sót việc bảo đảm thời gian và kiểm tra vòi uống nước, đèn sưởi.","Nếu có chỉ dẫn thì bảo đảm thời gian làm khô quy định, kiểm tra được cơ bản nhiệt độ, nước uống, đèn sưởi.","Không cần chỉ dẫn cũng kéo dài thời gian làm khô theo mùa, thông gió để khô nhanh hơn, và sửa những thiếu sót trong chuẩn bị đón lợn.","Hiểu lý do khử trùng không có tác dụng khi còn ướt và ý nghĩa của thời gian để trống chuồng, và có thể hướng dẫn người mới các điểm chính của làm khô và chuẩn bị."],"levels_id":["Lanjut ke langkah berikutnya tanpa menunggu kering, dan membiarkan anak babi masuk tanpa persiapan kelompok berikutnya.","Jika ada instruksi bisa mengeringkan, tetapi sering lalai memastikan waktunya dan memeriksa alat minum serta lampu penghangat.","Jika ada instruksi, bisa memastikan waktu pengeringan yang ditentukan dan memeriksa secara garis besar suhu, air minum, dan lampu penghangat.","Tanpa instruksi pun, memperpanjang waktu pengeringan sesuai musim, mempercepat pengeringan dengan ventilasi, dan memperbaiki kekurangan persiapan penerimaan.","Memahami alasan disinfeksi tidak bekerja selagi basah dan arti masa kandang kosong, dan bisa mengajari karyawan baru poin penting pengeringan dan persiapan."]}],"name_en":"Washing (post-weaning)","name_vi":"Rửa chuồng (sau cai sữa)","name_id":"Mencuci kandang (setelah sapih)","purposeShort_en":"Physically remove dirt and pathogens, create conditions where disinfection works, and reset the barn","purposeShort_vi":"Loại bỏ chất bẩn và mầm bệnh bằng cách rửa, tạo trạng thái để khử trùng có tác dụng, làm mới lại chuồng","purposeShort_id":"Menghilangkan kotoran dan bibit penyakit secara fisik, membuat kondisi agar disinfeksi bekerja, dan mereset bagian dalam kandang"},{"id":"disinfect","category":"hygiene","no":"No.15","name":"消毒","purposeShort":"病原体を入れない・広げない・持ち出さず、農場の防疫レベルを保つ","gyomu":"15","aspects":[{"id":"concentration","name":"濃度・量・接触時間の遵守","kanten":"決められた濃度・量・接触時間を守り、目分量の希釈をしないか。","levels":["希釈濃度を目分量で調整し、接触時間も守らず規定を外す。","指示があれば希釈するが、濃度や接触時間の管理に漏れが多い。","指示があれば決められた濃度・量・接触時間をひと通り守れる。","指示がなくても正確に希釈し、接触時間を確保してから乾燥させる。","薬剤ごとの特性と濃度・接触時間の意味を理解し、正しい消毒を新人に指導できる。"],"name_en":"Following concentration, volume, and contact time","name_vi":"Giữ đúng nồng độ, lượng và thời gian tiếp xúc","name_id":"Mematuhi konsentrasi, jumlah, dan waktu kontak","kanten_en":"Do they follow the prescribed concentration, volume, and contact time, without diluting by eye?","kanten_vi":"Có giữ đúng nồng độ, lượng và thời gian tiếp xúc quy định, không pha loãng theo ước lượng bằng mắt không.","kanten_id":"Apakah mematuhi konsentrasi, jumlah, dan waktu kontak yang ditentukan, dan tidak mengencerkan dengan kira-kira.","levels_en":["Adjusts dilution by eye and ignores contact times, deviating from the standards.","With guidance, dilutes, but often fails to manage concentration and contact time.","With guidance, can adequately follow the prescribed concentration, volume, and contact time.","Independently dilutes accurately and secures the contact time before allowing surfaces to dry.","Understands each chemical's characteristics and the meaning of concentration and contact time, and can teach new staff correct disinfection."],"levels_vi":["Pha loãng theo ước lượng bằng mắt, không giữ thời gian tiếp xúc, làm sai quy định.","Nếu có chỉ dẫn thì pha loãng, nhưng hay bỏ sót việc quản lý nồng độ và thời gian tiếp xúc.","Nếu có chỉ dẫn thì giữ được cơ bản nồng độ, lượng và thời gian tiếp xúc quy định.","Không cần chỉ dẫn cũng pha loãng chính xác, bảo đảm thời gian tiếp xúc rồi mới làm khô.","Hiểu đặc tính từng loại thuốc và ý nghĩa của nồng độ, thời gian tiếp xúc, và có thể hướng dẫn người mới cách khử trùng đúng."],"levels_id":["Mengatur konsentrasi pengenceran dengan kira-kira, tidak mematuhi waktu kontak, dan keluar dari ketentuan.","Jika ada instruksi bisa mengencerkan, tetapi sering lalai mengelola konsentrasi dan waktu kontak.","Jika ada instruksi, bisa mematuhi secara garis besar konsentrasi, jumlah, dan waktu kontak yang ditentukan.","Tanpa instruksi pun, mengencerkan dengan akurat, memastikan waktu kontak tercapai, lalu membiarkannya kering.","Memahami sifat tiap bahan disinfektan serta arti konsentrasi dan waktu kontak, dan bisa mengajari karyawan baru cara disinfeksi yang benar."]},{"id":"clean-first-ppe","name":"汚れ除去の徹底と防護具着用","kanten":"汚れを先に落としてから消毒し、防護マスク・ゴーグルを着けて曝露を防げるか。","levels":["有機物が残った面に散布して消毒剤を不活化させ、防護具も着けず薬剤に曝露する。","指示があれば汚れを落とすが、防護具の着用や汚れ除去の徹底に漏れがある。","指示があれば汚れを落としてから消毒し、防護具をひと通り着用できる。","指示がなくても汚れを確実に落としてから消毒し、防護具を着けて安全に作業する。","有機物による不活化と薬剤曝露の危険を理解し、汚れ除去と防護の徹底を新人に指導できる。"],"name_en":"Thorough dirt removal first and wearing protective gear","name_vi":"Loại bỏ bẩn kỹ trước và đeo đồ bảo hộ","name_id":"Menghilangkan kotoran dengan tuntas dan memakai alat pelindung","kanten_en":"Can they remove dirt before disinfecting, and wear a protective mask and goggles to prevent chemical exposure?","kanten_vi":"Có loại bỏ chất bẩn trước rồi mới khử trùng, đeo khẩu trang và kính bảo hộ để tránh phơi nhiễm thuốc không.","kanten_id":"Apakah menghilangkan kotoran dulu baru mendisinfeksi, dan memakai masker pelindung serta kacamata pelindung agar tidak terpapar bahan kimia.","levels_en":["Sprays onto surfaces with organic matter, inactivating the disinfectant, and works without protective gear, exposing themselves to chemicals.","With guidance, removes dirt, but is inconsistent about wearing protective gear and removing dirt thoroughly.","With guidance, removes dirt before disinfecting and can adequately wear protective gear.","Independently removes dirt thoroughly before disinfecting and works safely in protective gear.","Understands inactivation by organic matter and the dangers of chemical exposure, and can teach new staff thorough dirt removal and protection."],"levels_vi":["Phun lên bề mặt còn chất hữu cơ làm thuốc khử trùng mất tác dụng, không đeo đồ bảo hộ nên bị phơi nhiễm thuốc.","Nếu có chỉ dẫn thì loại bỏ bẩn, nhưng có bỏ sót việc đeo đồ bảo hộ và việc làm sạch kỹ.","Nếu có chỉ dẫn thì loại bỏ bẩn trước rồi mới khử trùng, đeo được cơ bản đồ bảo hộ.","Không cần chỉ dẫn cũng loại bỏ bẩn chắc chắn trước khi khử trùng, đeo đồ bảo hộ và làm việc an toàn.","Hiểu chất hữu cơ làm thuốc mất tác dụng và nguy hiểm khi phơi nhiễm thuốc, và có thể hướng dẫn người mới việc làm sạch và bảo hộ kỹ."],"levels_id":["Menyemprot ke permukaan yang masih ada bahan organik sehingga disinfektan tidak bekerja, dan terpapar bahan kimia karena tidak memakai alat pelindung.","Jika ada instruksi bisa menghilangkan kotoran, tetapi sering lalai memakai alat pelindung dan menghilangkan kotoran dengan tuntas.","Jika ada instruksi, bisa menghilangkan kotoran dulu baru mendisinfeksi, dan memakai alat pelindung secara garis besar.","Tanpa instruksi pun, menghilangkan kotoran dengan pasti sebelum mendisinfeksi, dan bekerja dengan aman memakai alat pelindung.","Memahami disinfektan yang tidak bekerja karena bahan organik dan bahaya paparan bahan kimia, dan bisa mengajari karyawan baru pentingnya menghilangkan kotoran dan perlindungan diri."]},{"id":"dry-both","name":"洗浄後・消毒後の乾燥徹底","kanten":"ぬれた面に消毒せず洗浄後にしっかり乾かし、消毒後も乾いてから豚を入れられるか。","levels":["ぬれたままの面に消毒液をまき、湿ったままの豚房に豚を入れても気にしない。","指示があれば乾かすが、乾燥時間の確保や乾き具合の確認に漏れが多い。","指示があれば洗浄後・消毒後それぞれの乾燥をひと通り確保できる。","指示がなくても換気扇を使って乾燥を早め、完全に乾いたのを確かめてから豚を入れる。","ぬれた面では薬剤が薄まり湿気で病原体が増えることを理解し、乾燥の要点を新人に指導できる。"],"name_en":"Thorough drying after washing and after disinfection","name_vi":"Làm khô kỹ sau khi rửa và sau khi khử trùng","name_id":"Pengeringan menyeluruh setelah mencuci dan setelah disinfeksi","kanten_en":"Do they avoid disinfecting wet surfaces by drying well after washing, and put pigs in only after it has dried following disinfection?","kanten_vi":"Có không khử trùng lên bề mặt còn ướt mà làm khô kỹ sau khi rửa, và sau khi khử trùng cũng chờ khô rồi mới cho lợn vào không.","kanten_id":"Apakah tidak mendisinfeksi permukaan yang basah melainkan mengeringkannya dengan baik setelah mencuci, dan memasukkan babi hanya setelah kering sesudah disinfeksi.","levels_en":["Sprays disinfectant on still-wet surfaces, and does not care about putting pigs into a still-damp pen.","With guidance, dries, but often fails to secure drying time and check how dry it is.","With guidance, can adequately secure drying both after washing and after disinfection.","Independently speeds up drying with the ventilation fans and puts pigs in only after confirming everything is completely dry.","Understands that wet surfaces dilute the chemical and dampness lets pathogens multiply, and can teach new staff the key points of drying."],"levels_vi":["Phun thuốc khử trùng lên bề mặt còn ướt, cho lợn vào ô chuồng còn ẩm cũng không quan tâm.","Nếu có chỉ dẫn thì làm khô, nhưng hay bỏ sót việc bảo đảm thời gian khô và kiểm tra độ khô.","Nếu có chỉ dẫn thì bảo đảm được cơ bản việc làm khô sau khi rửa và sau khi khử trùng.","Không cần chỉ dẫn cũng dùng quạt thông gió để khô nhanh hơn, chắc chắn đã khô hoàn toàn rồi mới cho lợn vào.","Hiểu bề mặt ướt làm thuốc bị loãng và ẩm ướt làm mầm bệnh sinh sôi, và có thể hướng dẫn người mới các điểm chính của việc làm khô."],"levels_id":["Menyemprotkan cairan disinfektan ke permukaan yang masih basah, dan tidak peduli memasukkan babi ke petak kandang yang masih lembap.","Jika ada instruksi bisa mengeringkan, tetapi sering lalai memastikan waktu pengeringan dan memeriksa tingkat keringnya.","Jika ada instruksi, bisa memastikan secara garis besar pengeringan setelah mencuci maupun setelah disinfeksi.","Tanpa instruksi pun, mempercepat pengeringan dengan kipas ventilasi, dan memasukkan babi hanya setelah memastikan benar-benar kering.","Memahami bahwa permukaan basah mengencerkan bahan kimia dan kelembapan membuat bibit penyakit berkembang biak, dan bisa mengajari karyawan baru poin penting pengeringan."]},{"id":"no-mix-accident","name":"消毒剤の混合禁止と事故時対応","kanten":"消毒剤を絶対に混ぜず1種類ずつ使い、目に入ったら流水15分以上洗って報告できるか。","levels":["消毒剤を混ぜたり、薬液が目や皮膚についても洗わず放置したりする。","指示があれば守るが、混合禁止の理由を知らず、事故時の対応も不確実。","指示があれば1種類ずつ使い、目に入った時は流水で15分以上洗って報告する対応をひと通りできる。","指示がなくても混合禁止を徹底し、はね防止に水を先に入れるなど安全に扱い、事故時は即対応・報告する。","混合で危険なガスが出る仕組みを理解し、薬剤の安全な扱いと事故対応を新人に指導できる。"],"name_en":"No mixing of disinfectants and accident response","name_vi":"Cấm pha trộn thuốc khử trùng và xử lý khi có sự cố","name_id":"Larangan mencampur disinfektan dan penanganan kecelakaan","kanten_en":"Do they never mix disinfectants, using one type at a time, and if any gets in the eyes, rinse under running water for at least 15 minutes and report?","kanten_vi":"Có tuyệt đối không pha trộn thuốc khử trùng, dùng từng loại một, nếu vào mắt thì rửa dưới vòi nước chảy trên 15 phút và báo cáo không.","kanten_id":"Apakah sama sekali tidak mencampur disinfektan, memakainya satu jenis demi satu jenis, dan jika masuk ke mata mencucinya di air mengalir minimal 15 menit lalu melapor.","levels_en":["Mixes disinfectants, and leaves chemical solution on the eyes or skin without washing it off.","With guidance, complies, but does not know why mixing is forbidden, and their accident response is unreliable.","With guidance, uses one type at a time, and can adequately respond by rinsing under running water for at least 15 minutes and reporting when it gets in the eyes.","Independently enforces the no-mixing rule, handles chemicals safely such as putting water in first to prevent splashing, and responds and reports immediately in an accident.","Understands how mixing produces dangerous gases, and can teach new staff safe chemical handling and accident response."],"levels_vi":["Pha trộn thuốc khử trùng, thuốc dính vào mắt hay da cũng không rửa mà bỏ mặc.","Nếu có chỉ dẫn thì tuân theo, nhưng không biết lý do cấm pha trộn, cách xử lý khi có sự cố cũng không chắc chắn.","Nếu có chỉ dẫn thì dùng từng loại một, khi vào mắt thì làm được cơ bản việc rửa dưới vòi nước chảy trên 15 phút và báo cáo.","Không cần chỉ dẫn cũng giữ nghiêm việc cấm pha trộn, thao tác an toàn như cho nước vào trước để tránh bắn thuốc, khi có sự cố thì xử lý và báo cáo ngay.","Hiểu cơ chế sinh ra khí nguy hiểm khi pha trộn, và có thể hướng dẫn người mới cách dùng thuốc an toàn và xử lý sự cố."],"levels_id":["Mencampur disinfektan, dan membiarkan cairan kimia yang mengenai mata atau kulit tanpa mencucinya.","Jika ada instruksi bisa mematuhi, tetapi tidak tahu alasan larangan mencampur, dan penanganan saat kecelakaan juga tidak pasti.","Jika ada instruksi, bisa memakai satu jenis demi satu jenis, dan saat masuk ke mata bisa melakukan secara garis besar penanganan mencuci di air mengalir minimal 15 menit lalu melapor.","Tanpa instruksi pun, menjalankan larangan mencampur dengan ketat, menangani dengan aman seperti memasukkan air dulu untuk mencegah percikan, dan saat kecelakaan segera menangani dan melapor.","Memahami mekanisme munculnya gas berbahaya karena pencampuran, dan bisa mengajari karyawan baru penanganan bahan kimia yang aman dan penanganan kecelakaan."]},{"id":"footbath-record","name":"踏み込み消毒槽の管理と実施記録","kanten":"出入口の消毒槽の薬液を確認して汚れ・不足なら交換・補充し、実施場所と薬剤を記録できるか。","levels":["消毒槽が汚れていても放置し、どこに何をまいたかの記録も残さない。","指示されれば交換・記録するが、確認の頻度や記入内容に漏れが多い。","指示があれば消毒槽の薬液をひと通り確認・交換し、実施場所と消毒剤を記録できる。","指示がなくても消毒槽を日常的に点検して汚れたら交換し、実施内容を漏れなく記録する。","汚れた薬液は効果が落ちることを理解し、消毒槽の管理と記録の習慣を新人に指導できる。"],"name_en":"Footbath management and implementation records","name_vi":"Quản lý hố khử trùng chân và ghi chép thực hiện","name_id":"Pengelolaan bak celup disinfektan kaki dan pencatatan pelaksanaan","kanten_en":"Can they check the solution in the entrance footbaths, replace or refill it when dirty or low, and record the places treated and the chemicals used?","kanten_vi":"Có kiểm tra dung dịch trong hố khử trùng ở cửa ra vào, bẩn hay thiếu thì thay mới, bổ sung, và ghi lại nơi đã khử trùng và thuốc đã dùng không.","kanten_id":"Apakah memeriksa cairan di bak celup disinfektan pintu masuk, menggantinya atau menambahkannya jika kotor atau kurang, dan mencatat tempat pelaksanaan serta disinfektan yang dipakai.","levels_en":["Leaves the footbath dirty, and keeps no record of where and what was applied.","Replaces and records when instructed, but the checking frequency and entries are often lacking.","With guidance, can adequately check and replace the footbath solution, and record the places treated and the disinfectant.","Independently inspects the footbaths daily, replaces the solution when dirty, and records everything done without omission.","Understands that dirty solution loses its effect, and can teach new staff the habit of footbath management and record-keeping."],"levels_vi":["Hố khử trùng bẩn cũng bỏ mặc, cũng không ghi lại đã phun gì ở đâu.","Nếu được chỉ dẫn thì thay và ghi chép, nhưng hay bỏ sót tần suất kiểm tra và nội dung ghi.","Nếu có chỉ dẫn thì kiểm tra, thay được cơ bản dung dịch trong hố khử trùng, và ghi lại nơi thực hiện và thuốc khử trùng.","Không cần chỉ dẫn cũng kiểm tra hố khử trùng hằng ngày, bẩn thì thay, và ghi chép đầy đủ nội dung đã làm.","Hiểu dung dịch bẩn sẽ giảm tác dụng, và có thể hướng dẫn người mới thói quen quản lý hố khử trùng và ghi chép."],"levels_id":["Membiarkan bak celup yang kotor, dan tidak meninggalkan catatan di mana dan apa yang disemprotkan.","Jika disuruh bisa mengganti dan mencatat, tetapi frekuensi pemeriksaan dan isi catatannya sering kurang.","Jika ada instruksi, bisa memeriksa dan mengganti cairan bak celup secara garis besar, serta mencatat tempat pelaksanaan dan disinfektannya.","Tanpa instruksi pun, memeriksa bak celup setiap hari, menggantinya jika kotor, dan mencatat lengkap semua yang dilakukan.","Memahami bahwa cairan yang kotor kehilangan efeknya, dan bisa mengajari karyawan baru kebiasaan mengelola bak celup dan mencatat."]}],"name_en":"Disinfection","name_vi":"Khử trùng","name_id":"Disinfeksi","purposeShort_en":"Keep pathogens out, contained, and off the farm, maintaining the farm's biosecurity level","purposeShort_vi":"Không cho mầm bệnh vào, không làm lan rộng, không mang ra ngoài, giữ mức phòng dịch của trại","purposeShort_id":"Tidak memasukkan, tidak menyebarkan, dan tidak membawa keluar bibit penyakit, menjaga tingkat biosekuriti peternakan"},{"id":"lime","category":"hygiene","no":"No.44","name":"石灰散布","purposeShort":"農場出入口に防疫バリアを作り、病原体の侵入・拡散を抑える","gyomu":"44","aspects":[{"id":"moisture","name":"水分と散布量の管理","kanten":"地面が白く見える量を目安に、乾いた地面には先に水をまいてから散布できるか。","levels":["乾いた地面にそのまま散布し、量の目安も守らず消毒効果を出せない。","指示があれば散布するが、地面を湿らせることや量の管理に漏れがある。","指示があれば地面が白く見える量を目安にひと通り散布できる。","指示がなくても乾いた地面には先に水をまいてから散布し、白さの劣化を見て定期的に補充する。","石灰は水分がないと効かないことを理解し、散布量と補充の管理を新人に指導できる。"],"name_en":"Managing moisture and application amount","name_vi":"Quản lý nước và lượng rắc","name_id":"Pengelolaan air dan jumlah taburan","kanten_en":"Can they use visible whitening of the ground as the amount guide, and on dry ground, sprinkle water first before spreading?","kanten_vi":"Có lấy lượng đủ để mặt đất nhìn thấy trắng làm chuẩn, và với mặt đất khô thì tưới nước trước rồi mới rắc không.","kanten_id":"Apakah memakai patokan tanah terlihat putih, dan pada tanah yang kering menyiramkan air dulu sebelum menabur.","levels_en":["Spreads lime on dry ground as-is and ignores the amount guideline, achieving no disinfectant effect.","With guidance, spreads lime, but is inconsistent about wetting the ground and managing the amount.","With guidance, can adequately spread lime using visible whitening of the ground as the amount guide.","Independently sprinkles water first on dry ground before spreading, and replenishes regularly by watching the whiteness fade.","Understands that lime does not work without moisture, and can teach new staff how to manage application amounts and replenishment."],"levels_vi":["Rắc thẳng lên mặt đất khô, cũng không giữ lượng chuẩn nên không có tác dụng khử trùng.","Nếu có chỉ dẫn thì rắc, nhưng có bỏ sót việc làm ẩm mặt đất và quản lý lượng rắc.","Nếu có chỉ dẫn thì rắc được cơ bản với lượng đủ để mặt đất nhìn thấy trắng.","Không cần chỉ dẫn cũng tưới nước trước lên mặt đất khô rồi mới rắc, nhìn độ trắng phai đi để bổ sung định kỳ.","Hiểu vôi không có nước thì không có tác dụng, và có thể hướng dẫn người mới cách quản lý lượng rắc và bổ sung."],"levels_id":["Menabur begitu saja di tanah kering, tidak mematuhi patokan jumlah, sehingga efek disinfeksi tidak keluar.","Jika ada instruksi bisa menabur, tetapi sering lalai membasahi tanah dan mengelola jumlahnya.","Jika ada instruksi, bisa menabur secara garis besar dengan patokan tanah terlihat putih.","Tanpa instruksi pun, menyiramkan air dulu ke tanah kering sebelum menabur, dan menambah taburan secara berkala dengan melihat pudarnya warna putih.","Memahami bahwa kapur tidak bekerja tanpa air, dan bisa mengajari karyawan baru pengelolaan jumlah taburan dan penambahannya."]},{"id":"wind-safety","name":"風向き確認と防護","kanten":"風向きを確認して粉末飛散を防ぎ、人・豚にかからないよう防護具を着けて散布できるか。","levels":["風向きを確認せず粉末を飛散させ、防護具も着けず呼吸器障害や周辺苦情を招く。","指示があれば注意するが、風向き確認や防護具着用に漏れがある。","指示があれば人・豚に直接かからないようひと通り注意して散布できる。","指示がなくても風向きを確認して飛散を防ぎ、防護具を着けて安全に散布する。","飛散による健康被害・苦情のリスクを理解し、安全な散布方法を新人に指導できる。"],"name_en":"Checking wind direction and protection","name_vi":"Kiểm tra hướng gió và bảo hộ","name_id":"Pemeriksaan arah angin dan perlindungan diri","kanten_en":"Can they check the wind direction to prevent powder drift, and wear protective gear so the lime does not land on people or pigs?","kanten_vi":"Có kiểm tra hướng gió để tránh bột bay tán, đeo đồ bảo hộ và rắc sao cho không dính vào người và lợn không.","kanten_id":"Apakah memeriksa arah angin untuk mencegah bubuk beterbangan, dan bisa menabur dengan memakai alat pelindung agar tidak mengenai orang dan babi.","levels_en":["Scatters powder without checking wind direction and works without protective gear, causing respiratory harm and neighborhood complaints.","With guidance, takes care, but is inconsistent about checking wind direction and wearing protective gear.","With guidance, can spread lime with adequate care to keep it off people and pigs.","Independently checks wind direction to prevent drift and spreads lime safely in protective gear.","Understands the health and complaint risks of powder drift, and can teach new staff safe spreading methods."],"levels_vi":["Không kiểm tra hướng gió làm bột bay tán, không đeo đồ bảo hộ, gây hại đường hô hấp và khiếu nại từ xung quanh.","Nếu có chỉ dẫn thì chú ý, nhưng có bỏ sót việc kiểm tra hướng gió và đeo đồ bảo hộ.","Nếu có chỉ dẫn thì rắc được với sự chú ý cơ bản để không dính trực tiếp vào người và lợn.","Không cần chỉ dẫn cũng kiểm tra hướng gió để tránh bay tán, đeo đồ bảo hộ và rắc an toàn.","Hiểu nguy cơ hại sức khỏe và khiếu nại do bột bay tán, và có thể hướng dẫn người mới cách rắc an toàn."],"levels_id":["Menabur tanpa memeriksa arah angin sehingga bubuk beterbangan, tidak memakai alat pelindung sehingga menyebabkan gangguan pernapasan dan keluhan warga sekitar.","Jika ada instruksi bisa berhati-hati, tetapi sering lalai memeriksa arah angin dan memakai alat pelindung.","Jika ada instruksi, bisa menabur dengan cukup hati-hati agar tidak langsung mengenai orang dan babi.","Tanpa instruksi pun, memeriksa arah angin untuk mencegah bubuk beterbangan, dan menabur dengan aman memakai alat pelindung.","Memahami risiko gangguan kesehatan dan keluhan akibat bubuk beterbangan, dan bisa mengajari karyawan baru cara menabur yang aman."]},{"id":"weather-stock","name":"天候と在庫の事前確認","kanten":"天気予報を見て雨の近い時間帯を避け、袋の残量を確認して不足を事前に報告できるか。","levels":["天気も在庫も確認せず、雨の直前にまいて流したり、石灰切れで作業を止めたりする。","指示があれば確認するが、天候の判断や残量の見方が不確実で報告も遅れがち。","指示があれば天気予報と袋の残量をひと通り確認してから作業に入れる。","指示がなくても雨の近い散布を避けて時間帯を選び、在庫不足に気づいたら作業前に報告する。","雨で流れると効果が薄れることを理解し、天候判断と在庫管理の段取りを新人に指導できる。"],"name_en":"Checking the weather and stock in advance","name_vi":"Kiểm tra trước thời tiết và tồn kho","name_id":"Pemeriksaan cuaca dan stok sebelumnya","kanten_en":"Can they check the weather forecast to avoid times when rain is near, check the amount left in the bags, and report shortages in advance?","kanten_vi":"Có xem dự báo thời tiết để tránh khung giờ sắp mưa, xem lượng còn lại trong bao và báo trước khi thiếu không.","kanten_id":"Apakah melihat prakiraan cuaca untuk menghindari jam yang hampir hujan, memeriksa sisa di karung, dan melaporkan kekurangan sebelumnya.","levels_en":["Checks neither the weather nor the stock, spreading lime just before rain washes it away, or halting work by running out of lime.","With guidance, checks, but their weather judgment and reading of the remaining amount are unreliable, and reporting tends to be late.","With guidance, can adequately check the weather forecast and the amount left in the bags before starting work.","Independently avoids spreading when rain is near by choosing the time, and reports before work upon noticing a stock shortage.","Understands that rain washing the lime away weakens its effect, and can teach new staff the routine of weather judgment and stock management."],"levels_vi":["Không kiểm tra cả thời tiết lẫn tồn kho, rắc ngay trước mưa làm vôi trôi mất, hoặc hết vôi phải dừng việc.","Nếu có chỉ dẫn thì kiểm tra, nhưng phán đoán thời tiết và cách xem lượng còn lại không chắc chắn, báo cáo cũng hay chậm.","Nếu có chỉ dẫn thì kiểm tra được cơ bản dự báo thời tiết và lượng còn lại trong bao rồi mới vào việc.","Không cần chỉ dẫn cũng tránh rắc khi sắp mưa bằng cách chọn khung giờ, thấy thiếu tồn kho thì báo trước khi làm.","Hiểu vôi bị mưa trôi sẽ giảm tác dụng, và có thể hướng dẫn người mới cách sắp xếp việc phán đoán thời tiết và quản lý tồn kho."],"levels_id":["Tidak memeriksa cuaca maupun stok, menabur tepat sebelum hujan sehingga hanyut, atau menghentikan pekerjaan karena kapur habis.","Jika ada instruksi bisa memeriksa, tetapi penilaian cuaca dan cara melihat sisa stok tidak pasti, dan pelaporannya cenderung terlambat.","Jika ada instruksi, bisa memeriksa secara garis besar prakiraan cuaca dan sisa di karung sebelum mulai bekerja.","Tanpa instruksi pun, memilih waktu untuk menghindari menabur saat hampir hujan, dan melapor sebelum bekerja jika menyadari stok kurang.","Memahami bahwa kapur yang hanyut oleh hujan berkurang efeknya, dan bisa mengajari karyawan baru pengaturan penilaian cuaca dan pengelolaan stok."]},{"id":"even-spread","name":"均一散布と仕上がり確認","kanten":"山にせずうすく広くまき、散布後に見回って白く均一か・通行の支障がないか確認できるか。","levels":["一か所に山盛りにするなどムラだらけにまき、仕上がりを見ずに終える。","指示があればまくが、まきムラが多く、散布後の見回りをしない。","指示があればうすく広くまき、散布後に全体をひと通り見回って確認できる。","指示がなくても均一に散布し、まきムラを見つけてまき足し、石灰乳はよくかくはんして詰まりを防ぐ。","白さが効果の目安になることを理解し、均一にまくコツと確認の仕方を新人に指導できる。"],"name_en":"Even spreading and finish checks","name_vi":"Rắc đều và kiểm tra kết quả","name_id":"Penaburan merata dan pemeriksaan hasil akhir","kanten_en":"Can they spread thinly and widely without making piles, and after spreading, walk around to check it is evenly white and does not obstruct passage?","kanten_vi":"Có rắc mỏng và rộng, không vun thành đống, sau khi rắc đi kiểm tra xem đã trắng đều chưa, có cản trở đi lại không.","kanten_id":"Apakah menabur tipis dan lebar tanpa menumpuknya, dan setelah menabur berkeliling memeriksa apakah putih merata dan tidak mengganggu lalu lintas.","levels_en":["Spreads unevenly, such as piling it up in one spot, and finishes without looking at the result.","With guidance, spreads, but with much unevenness, and does not walk around afterward.","With guidance, spreads thinly and widely, and can adequately walk around the whole area to check afterward.","Independently spreads evenly, finds and tops up uneven spots, and stirs lime milk well to prevent clogging.","Understands that whiteness is the guide to effectiveness, and can teach new staff the knack of spreading evenly and how to check."],"levels_vi":["Rắc loang lổ như vun thành đống một chỗ, kết thúc mà không nhìn kết quả.","Nếu có chỉ dẫn thì rắc, nhưng rắc không đều nhiều chỗ, không đi kiểm tra sau khi rắc.","Nếu có chỉ dẫn thì rắc mỏng và rộng, sau khi rắc đi kiểm tra được cơ bản toàn bộ.","Không cần chỉ dẫn cũng rắc đều, phát hiện chỗ chưa đều để rắc bổ sung, sữa vôi thì khuấy kỹ để tránh tắc.","Hiểu độ trắng là thước đo hiệu quả, và có thể hướng dẫn người mới bí quyết rắc đều và cách kiểm tra."],"levels_id":["Menabur tidak merata seperti menumpuknya di satu tempat, dan selesai tanpa melihat hasilnya.","Jika ada instruksi bisa menabur, tetapi banyak yang tidak merata dan tidak berkeliling setelah menabur.","Jika ada instruksi, bisa menabur tipis dan lebar, dan setelahnya berkeliling memeriksa keseluruhan secara garis besar.","Tanpa instruksi pun, menabur merata, menemukan bagian yang belum rata dan menaburinya lagi, serta mengaduk rata susu kapur untuk mencegah tersumbat.","Memahami bahwa warna putih menjadi patokan efektivitas, dan bisa mengajari karyawan baru kiat menabur merata dan cara memeriksanya."]},{"id":"skin-storage","name":"皮膚付着時の対応と石灰の保管","kanten":"皮膚についたらすぐ大量の水で洗い流し、残った石灰は袋を閉じて湿気を避けて保管できるか。","levels":["皮膚についても洗わず放置し、袋を開けたまま雨ざらしにして石灰を劣化させる。","指示があれば対応するが、洗い流しが不十分で、袋の閉め忘れや保管場所のミスが多い。","指示があれば付着時に大量の水で洗い、袋の口を閉じて湿気のない場所にひと通り保管できる。","指示がなくても付着時は即座に洗って赤み・痛みがあれば報告し、保管状態まで自分で確かめる。","消石灰の強アルカリ性による化学熱傷の危険を理解し、応急対応と保管を新人に指導できる。"],"name_en":"Response to skin contact and lime storage","name_vi":"Xử lý khi vôi dính da và bảo quản vôi","name_id":"Penanganan saat kapur mengenai kulit dan penyimpanan kapur","kanten_en":"Can they immediately rinse with plenty of water when lime gets on the skin, and store leftover lime with the bag closed, away from moisture?","kanten_vi":"Vôi dính da có rửa trôi ngay bằng nhiều nước, vôi còn thừa có đóng miệng bao và bảo quản tránh ẩm không.","kanten_id":"Apakah segera membilas dengan banyak air jika kapur mengenai kulit, dan menyimpan sisa kapur dengan karung tertutup jauh dari lembap.","levels_en":["Leaves lime on the skin without washing, and leaves bags open in the rain, letting the lime degrade.","With guidance, responds, but rinsing is insufficient, and often forgets to close the bags or stores them in the wrong place.","With guidance, washes with plenty of water when lime gets on the skin, and can adequately store the bags closed in a dry place.","Independently washes immediately on contact, reports any redness or pain, and checks the storage condition themselves.","Understands the danger of chemical burns from the strong alkalinity of slaked lime, and can teach new staff first-aid response and storage."],"levels_vi":["Vôi dính da cũng không rửa mà bỏ mặc, để bao mở phơi mưa làm vôi xuống cấp.","Nếu có chỉ dẫn thì xử lý, nhưng rửa chưa đủ, hay quên đóng miệng bao và để sai chỗ bảo quản.","Nếu có chỉ dẫn thì khi dính vôi rửa bằng nhiều nước, đóng miệng bao và bảo quản được cơ bản ở nơi không ẩm.","Không cần chỉ dẫn cũng rửa ngay khi dính vôi, có đỏ hay đau thì báo cáo, tự mình kiểm tra cả tình trạng bảo quản.","Hiểu nguy cơ bỏng hóa chất do tính kiềm mạnh của vôi bột, và có thể hướng dẫn người mới cách sơ cứu và bảo quản."],"levels_id":["Membiarkan kapur di kulit tanpa mencucinya, dan membiarkan karung terbuka kena hujan sehingga kapur rusak.","Jika ada instruksi bisa menangani, tetapi pembilasannya kurang, dan sering lupa menutup karung atau salah tempat penyimpanan.","Jika ada instruksi, bisa mencuci dengan banyak air saat terkena, menutup mulut karung, dan menyimpannya secara garis besar di tempat yang tidak lembap.","Tanpa instruksi pun, langsung mencuci saat terkena, melapor jika ada kemerahan atau nyeri, dan memeriksa sendiri sampai kondisi penyimpanannya.","Memahami bahaya luka bakar kimia karena sifat basa kuat kapur, dan bisa mengajari karyawan baru penanganan darurat dan penyimpanannya."]}],"name_en":"Lime spreading","name_vi":"Rắc vôi bột (khử trùng bằng vôi)","name_id":"Menaburkan kapur (disinfeksi dengan kapur)","purposeShort_en":"Create a biosecurity barrier at farm entrances and suppress pathogen entry and spread","purposeShort_vi":"Tạo hàng rào phòng dịch ở lối ra vào trại, ngăn mầm bệnh xâm nhập và lan rộng","purposeShort_id":"Membuat penghalang biosekuriti di pintu masuk-keluar peternakan, menekan masuk dan menyebarnya bibit penyakit"},{"id":"carcass","category":"hygiene","no":"No.37","name":"死獣回収","purposeShort":"病原体の拡散と悪臭・害獣被害を防ぎ、法令を守る","gyomu":"37","aspects":[{"id":"prompt-storage","name":"速やかな回収と専用保管","kanten":"死亡確認後すぐに回収し、豚房内に放置せず専用の保管場所へ入れられるか。","levels":["死体を豚房内に放置し、他の豚が接触して感染源になっても気にしない。","指示があれば回収するが、回収の遅れや保管場所の管理に漏れがある。","指示があれば死亡確認後にひと通り回収し、専用保管場所へ入れられる。","指示がなくても速やかに回収して専用場所へ入れ、感染源化を防ぐ。","死体放置の感染リスクを理解し、速やかな回収・保管の手順を新人に指導できる。"],"name_en":"Prompt collection and dedicated storage","name_vi":"Thu gom nhanh và cất giữ ở nơi chuyên dùng","name_id":"Pengumpulan segera dan penyimpanan khusus","kanten_en":"Can they collect carcasses immediately after confirming death, without leaving them in the pen, and place them in dedicated storage?","kanten_vi":"Sau khi xác nhận lợn chết có thu gom ngay, không để trong ô chuồng mà đưa vào nơi cất giữ chuyên dùng không.","kanten_id":"Apakah segera mengumpulkan setelah kematian dipastikan, tidak membiarkannya di dalam petak kandang, dan memasukkannya ke tempat penyimpanan khusus.","levels_en":["Leaves carcasses in the pen and does not care that other pigs touch them and they become an infection source.","With guidance, collects carcasses, but collection is delayed and storage management is inconsistent.","With guidance, can adequately collect carcasses after confirming death and place them in dedicated storage.","Independently collects carcasses promptly and moves them to the dedicated area, preventing them from becoming an infection source.","Understands the infection risk of leaving carcasses, and can teach new staff the procedures for prompt collection and storage."],"levels_vi":["Để xác lợn trong ô chuồng, lợn khác chạm vào thành nguồn lây nhiễm cũng không quan tâm.","Nếu có chỉ dẫn thì thu gom, nhưng có chậm trễ và bỏ sót việc quản lý nơi cất giữ.","Nếu có chỉ dẫn thì thu gom được cơ bản sau khi xác nhận lợn chết, đưa vào nơi cất giữ chuyên dùng.","Không cần chỉ dẫn cũng thu gom nhanh và đưa vào nơi chuyên dùng, ngăn xác trở thành nguồn lây nhiễm.","Hiểu nguy cơ lây nhiễm khi để xác lợn, và có thể hướng dẫn người mới quy trình thu gom, cất giữ nhanh chóng."],"levels_id":["Membiarkan bangkai di dalam petak kandang, dan tidak peduli walau babi lain menyentuhnya dan menjadi sumber infeksi.","Jika ada instruksi bisa mengumpulkan, tetapi sering terlambat mengumpulkan dan lalai mengelola tempat penyimpanan.","Jika ada instruksi, bisa mengumpulkan secara garis besar setelah kematian dipastikan, dan memasukkannya ke tempat penyimpanan khusus.","Tanpa instruksi pun, segera mengumpulkan dan memasukkannya ke tempat khusus, sehingga mencegahnya menjadi sumber infeksi.","Memahami risiko infeksi dari bangkai yang dibiarkan, dan bisa mengajari karyawan baru urutan pengumpulan dan penyimpanan yang cepat."]},{"id":"law-record","name":"法令遵守と死亡記録","kanten":"堆肥混入などの違法処理を避け、感染症疑いは自己判断せず、死亡状況を記録できるか。","levels":["死亡子豚を堆肥に混入するなど違法な処理をし、記録も残さない。","指示されれば記録するが、法令の理解が浅く記録に漏れが多い。","指示があれば専用処理へ回し、死亡状況をひと通り記録できる。","指示がなくても法令に沿って処理し、感染症疑いは自己判断せず、死亡日・頭数・原因を記録する。","化製場法・廃棄物処理法の要点を理解し、正しい処理と記録を新人に指導できる。"],"name_en":"Legal compliance and mortality records","name_vi":"Tuân thủ pháp luật và ghi chép lợn chết","name_id":"Kepatuhan peraturan dan pencatatan kematian","kanten_en":"Can they avoid illegal disposal such as mixing into compost, not self-judge suspected infectious diseases, and record the circumstances of death?","kanten_vi":"Có tránh xử lý trái pháp luật như trộn vào phân ủ, không tự phán đoán khi nghi bệnh truyền nhiễm, và ghi chép được tình trạng chết không.","kanten_id":"Apakah menghindari pemrosesan ilegal seperti mencampur ke kompos, tidak memutuskan sendiri jika dicurigai penyakit menular, dan bisa mencatat keadaan kematian.","levels_en":["Disposes of carcasses illegally, such as mixing dead piglets into compost, and keeps no records.","Records when instructed, but has a shallow understanding of the law and many recording omissions.","With guidance, sends carcasses to dedicated disposal and can adequately record the circumstances of death.","Independently disposes of carcasses in accordance with the law, never self-judges suspected infectious diseases, and records the date, number, and cause of death.","Understands the key points of the rendering plant and waste disposal laws, and can teach new staff correct disposal and record-keeping."],"levels_vi":["Xử lý trái pháp luật như trộn lợn con chết vào phân ủ, cũng không để lại ghi chép.","Nếu được chỉ dẫn thì ghi chép, nhưng hiểu biết pháp luật còn nông, hay bỏ sót ghi chép.","Nếu có chỉ dẫn thì chuyển sang xử lý chuyên dùng, ghi chép được cơ bản tình trạng chết.","Không cần chỉ dẫn cũng xử lý theo pháp luật, nghi bệnh truyền nhiễm thì không tự phán đoán, ghi chép ngày chết, số con, nguyên nhân.","Hiểu các điểm chính của luật về cơ sở xử lý xác động vật và luật xử lý chất thải (quy định của Nhật Bản), và có thể hướng dẫn người mới cách xử lý và ghi chép đúng."],"levels_id":["Melakukan pemrosesan ilegal seperti mencampur anak babi yang mati ke kompos, dan tidak meninggalkan catatan.","Jika disuruh bisa mencatat, tetapi pemahaman peraturannya dangkal dan catatannya banyak yang terlewat.","Jika ada instruksi, bisa menyerahkan ke pemrosesan khusus dan mencatat keadaan kematian secara garis besar.","Tanpa instruksi pun, memproses sesuai peraturan, tidak memutuskan sendiri jika dicurigai penyakit menular, dan mencatat tanggal kematian, jumlah ekor, dan penyebabnya.","Memahami poin-poin undang-undang pengolahan bangkai dan pengelolaan limbah (peraturan Jepang), dan bisa mengajari karyawan baru pemrosesan dan pencatatan yang benar."]},{"id":"infect-signs","name":"感染症サインの察知と作業停止","kanten":"短期間の複数死・紫黒斑・血便・血泡を見たら死体を動かさず作業を止めて即報告できるか。","levels":["感染症のサインを見ずに死体を動かし、疑わしい状況でも自己判断で処理を進める。","指示があればサインを見るが、見分けが不確実で報告の判断を他者まかせにする。","指示があれば感染症のサインをひと通り確認し、見つけたら動かさず上司と獣医に報告できる。","指示がなくても回収前に必ずサインを確認し、疑いがあれば作業を止めて即報告し指示を待つ。","法定伝染病疑い時の届出や剖検の必要性を理解し、止めるべき状況の見極めを新人に指導できる。"],"name_en":"Detecting infectious disease signs and stopping work","name_vi":"Nhận biết dấu hiệu bệnh truyền nhiễm và dừng công việc","name_id":"Mengenali tanda penyakit menular dan menghentikan pekerjaan","kanten_en":"Can they stop work without moving the carcass and report immediately upon seeing multiple deaths in a short period, purple-black patches, bloody stool, or bloody foam?","kanten_vi":"Khi thấy nhiều con chết trong thời gian ngắn, vết tím đen, phân có máu, bọt máu, có dừng công việc mà không di chuyển xác và báo cáo ngay không.","kanten_id":"Apakah saat melihat beberapa kematian dalam waktu singkat, bercak ungu kehitaman, kotoran berdarah, atau busa berdarah, bisa menghentikan pekerjaan tanpa memindahkan bangkai dan segera melapor.","levels_en":["Moves carcasses without looking for infectious disease signs, and proceeds with disposal on their own judgment even in suspicious situations.","With guidance, looks at the signs, but cannot distinguish them reliably and leaves the reporting decision to others.","With guidance, can adequately check for infectious disease signs, and upon finding them, report to the supervisor and veterinarian without moving the carcass.","Independently always checks for the signs before collection, and when there is suspicion, stops work, reports immediately, and waits for instructions.","Understands the need for notification and necropsy when a notifiable disease is suspected, and can teach new staff how to recognize situations where work must stop."],"levels_vi":["Không nhìn dấu hiệu bệnh truyền nhiễm mà di chuyển xác, tình huống đáng ngờ cũng tự ý tiến hành xử lý.","Nếu có chỉ dẫn thì nhìn dấu hiệu, nhưng phân biệt không chắc chắn, việc quyết định báo cáo thì phó mặc người khác.","Nếu có chỉ dẫn thì kiểm tra được cơ bản dấu hiệu bệnh truyền nhiễm, thấy thì không di chuyển mà báo cáo cấp trên và bác sĩ thú y.","Không cần chỉ dẫn cũng nhất định kiểm tra dấu hiệu trước khi thu gom, có nghi ngờ thì dừng việc, báo ngay và chờ chỉ thị.","Hiểu sự cần thiết của việc khai báo và mổ khám khi nghi bệnh truyền nhiễm theo luật định, và có thể hướng dẫn người mới cách nhận định tình huống phải dừng lại."],"levels_id":["Memindahkan bangkai tanpa melihat tanda penyakit menular, dan tetap memprosesnya atas keputusan sendiri walau situasinya mencurigakan.","Jika ada instruksi bisa melihat tandanya, tetapi tidak bisa membedakannya dengan pasti dan menyerahkan keputusan pelaporan kepada orang lain.","Jika ada instruksi, bisa memeriksa secara garis besar tanda penyakit menular, dan jika menemukannya, melapor ke atasan dan dokter hewan tanpa memindahkan bangkai.","Tanpa instruksi pun, selalu memeriksa tandanya sebelum mengumpulkan, dan jika ada kecurigaan, menghentikan pekerjaan, segera melapor, dan menunggu instruksi.","Memahami perlunya pelaporan resmi dan bedah bangkai saat dicurigai penyakit menular yang wajib dilaporkan, dan bisa mengajari karyawan baru cara menilai situasi yang harus dihentikan."]},{"id":"ppe-disinfect","name":"防護具着用と回収後の消毒","kanten":"厚手手袋・マスクを着け素手で触らず、死体のあった場所・道具を消毒し手洗いできるか。","levels":["素手で死体にさわり、跡地や道具も消毒せずそのまま他の豚の作業に移る。","指示があれば手袋を着けるが、跡地の消毒や道具の洗浄・手指消毒に漏れが多い。","指示があれば防護具を着けて回収し、跡地・道具の消毒と手洗い・手指消毒をひと通りできる。","指示がなくても防護具と消毒を徹底し、手指消毒を終えてから他の豚にさわる。","豚丹毒など人にうつる病気の危険を理解し、防護と消毒の手順を新人に指導できる。"],"name_en":"Wearing protective gear and disinfection after collection","name_vi":"Đeo đồ bảo hộ và khử trùng sau khi thu gom","name_id":"Memakai alat pelindung dan disinfeksi setelah pengumpulan","kanten_en":"Can they wear thick gloves and a mask, never touch with bare hands, disinfect the spot where the carcass was and the tools, and wash their hands?","kanten_vi":"Có đeo găng tay dày, khẩu trang, không chạm bằng tay trần, khử trùng chỗ có xác và dụng cụ, rồi rửa tay không.","kanten_id":"Apakah memakai sarung tangan tebal dan masker, tidak menyentuh dengan tangan kosong, mendisinfeksi tempat bekas bangkai dan alatnya, lalu mencuci tangan.","levels_en":["Touches carcasses with bare hands, and moves on to work with other pigs without disinfecting the spot or the tools.","With guidance, wears gloves, but often fails to disinfect the spot, wash the tools, and disinfect their hands.","With guidance, collects in protective gear, and can adequately disinfect the spot and tools and wash and disinfect their hands.","Independently keeps protective gear and disinfection thorough, and touches other pigs only after finishing hand disinfection.","Understands the danger of diseases transmissible to humans such as erysipelas, and can teach new staff the protection and disinfection procedures."],"levels_vi":["Chạm vào xác bằng tay trần, chỗ cũ và dụng cụ cũng không khử trùng mà chuyển luôn sang việc với lợn khác.","Nếu có chỉ dẫn thì đeo găng tay, nhưng hay bỏ sót việc khử trùng chỗ cũ, rửa dụng cụ và khử trùng tay.","Nếu có chỉ dẫn thì đeo đồ bảo hộ để thu gom, làm được cơ bản việc khử trùng chỗ cũ, dụng cụ và rửa tay, khử trùng tay.","Không cần chỉ dẫn cũng giữ nghiêm đồ bảo hộ và khử trùng, khử trùng tay xong mới chạm vào lợn khác.","Hiểu nguy cơ những bệnh lây sang người như bệnh đóng dấu lợn, và có thể hướng dẫn người mới quy trình bảo hộ và khử trùng."],"levels_id":["Menyentuh bangkai dengan tangan kosong, dan langsung pindah mengurus babi lain tanpa mendisinfeksi bekas tempatnya dan alatnya.","Jika ada instruksi bisa memakai sarung tangan, tetapi sering lalai mendisinfeksi bekas tempatnya, mencuci alat, dan mendisinfeksi tangan.","Jika ada instruksi, bisa mengumpulkan dengan alat pelindung, dan melakukan secara garis besar disinfeksi bekas tempat dan alat serta cuci tangan dan disinfeksi tangan.","Tanpa instruksi pun, menjalankan alat pelindung dan disinfeksi dengan menyeluruh, dan menyentuh babi lain hanya setelah selesai disinfeksi tangan.","Memahami bahaya penyakit yang menular ke manusia seperti erisipelas babi, dan bisa mengajari karyawan baru prosedur perlindungan dan disinfeksi."]},{"id":"confirm-herdwatch","name":"死亡確認と同居豚の観察","kanten":"呼吸・反応を見て死亡を確かめ、同じ豚房の豚の元気・食欲・呼吸・皮膚色を観察できるか。","levels":["動かない＝死亡と決めつけて弱った豚を運ぼうとし、同居豚の様子も見ない。","指示があれば確認するが、死亡確認が不確実で、同居豚の観察も形だけになる。","指示があれば呼吸と反応で死亡をひと通り確かめ、同居豚の様子を見て回れる。","指示がなくても死亡を慎重に確かめ、同居豚の異常の兆候を早期に見つけて報告する。","突然死の病気が群れに広がりやすいことを理解し、確認と観察の着眼点を新人に指導できる。"],"name_en":"Confirming death and observing pen mates","name_vi":"Xác nhận lợn chết và quan sát lợn cùng ô chuồng","name_id":"Memastikan kematian dan mengamati babi sekandang","kanten_en":"Can they confirm death by checking breathing and responses, and observe the liveliness, appetite, breathing, and skin color of the pigs in the same pen?","kanten_vi":"Có nhìn hô hấp và phản ứng để chắc chắn lợn đã chết, quan sát độ khỏe, ăn uống, hô hấp, màu da của lợn cùng ô chuồng không.","kanten_id":"Apakah memastikan kematian dengan melihat napas dan reaksinya, dan mengamati kelincahan, nafsu makan, napas, serta warna kulit babi di petak kandang yang sama.","levels_en":["Assumes not moving means dead and tries to carry off weakened pigs, and does not look at the pen mates.","With guidance, checks, but the death confirmation is unreliable and the observation of pen mates is only a formality.","With guidance, can adequately confirm death by breathing and responses, and go around observing the pen mates.","Independently confirms death carefully, and finds and reports early signs of abnormality in the pen mates.","Understands that diseases causing sudden death spread easily through the herd, and can teach new staff the key points of confirmation and observation."],"levels_vi":["Cho rằng không cử động = đã chết nên định mang cả lợn đang yếu đi, cũng không nhìn lợn cùng ô.","Nếu có chỉ dẫn thì kiểm tra, nhưng việc xác nhận chết không chắc chắn, quan sát lợn cùng ô cũng chỉ cho có hình thức.","Nếu có chỉ dẫn thì xác nhận được cơ bản lợn chết qua hô hấp và phản ứng, đi xem được tình trạng lợn cùng ô.","Không cần chỉ dẫn cũng xác nhận lợn chết một cách thận trọng, phát hiện sớm dấu hiệu bất thường của lợn cùng ô và báo cáo.","Hiểu những bệnh gây chết đột ngột dễ lan trong đàn, và có thể hướng dẫn người mới các điểm cần chú ý khi xác nhận và quan sát."],"levels_id":["Menganggap tidak bergerak = mati dan mencoba mengangkut babi yang lemah, dan tidak melihat keadaan babi sekandang.","Jika ada instruksi bisa memeriksa, tetapi pemastian kematiannya tidak pasti dan pengamatan babi sekandang hanya formalitas.","Jika ada instruksi, bisa memastikan kematian secara garis besar dari napas dan reaksi, dan berkeliling melihat keadaan babi sekandang.","Tanpa instruksi pun, memastikan kematian dengan hati-hati, dan menemukan lebih awal tanda kelainan pada babi sekandang lalu melaporkannya.","Memahami bahwa penyakit penyebab kematian mendadak mudah menyebar di kawanan, dan bisa mengajari karyawan baru titik perhatian dalam pemastian dan pengamatan."]}],"name_en":"Dead pig collection","name_vi":"Thu gom lợn chết","name_id":"Pengumpulan babi mati","purposeShort_en":"Prevent pathogen spread, odor, and pest damage, and comply with the law","purposeShort_vi":"Ngăn mầm bệnh lan rộng, mùi hôi và thú hại, tuân thủ pháp luật","purposeShort_id":"Mencegah penyebaran bibit penyakit, bau busuk, dan kerusakan oleh hewan liar, serta mematuhi peraturan"},{"id":"patrol-check","category":"hygiene","no":"","name":"見回り・健康チェック","purposeShort":"毎日の巡回で不調の豚を早く見つけ、迷わず報告して病気の広がりと出荷ロスを防ぐ","purposeShort_en":"Find unwell pigs early on daily rounds and report without hesitation to prevent disease spread and shipping losses","purposeShort_vi":"Đi kiểm tra hằng ngày để phát hiện sớm lợn không khỏe, báo cáo không do dự, phòng bệnh lây lan và thiệt hại khi xuất bán","purposeShort_id":"Menemukan babi yang tidak sehat lebih awal lewat keliling harian dan melapor tanpa ragu, agar penyakit tidak menyebar dan kerugian penjualan dicegah","gyomu":"","name_en":"Rounds and Health Check","name_vi":"Đi kiểm tra và xem sức khỏe lợn","name_id":"Keliling dan pemeriksaan kesehatan","aspects":[{"id":"route-cover","name":"豚房の巡回手順","kanten":"全豚房の中まで入り、入口で全体を見てから、立つ豚・寝ている豚・エサ箱・飲水器・排泄エリア・奥の順に見て回れるか。","levels":["遠くから見ただけで大丈夫と済ませ、豚房の中に入らず、寝ている豚が起き上がるかも確かめない。","指示があれば豚房に入るが、エサ箱や排泄エリアの確認が抜け、寝ている豚の確認は他者まかせ。","指示があれば入口で全体を見て、立つ豚・寝ている豚・エサ箱・飲水器・排泄エリア・奥の順に確認できる。","指示がなくても全豚房を漏れなく回り、寝ている豚に起き上がらない豚がいないか確かめ、ルートも時々変えて手薄な豚房を作らない。","遠くから見て済ませる危うさと、異常をひとつ見つけて安心し他が雑になる危うさを理解し、巡回の順番を新人に指導できる。"],"name_en":"Pen-by-Pen Rounds Procedure","name_vi":"Trình tự đi kiểm tra từng ô chuồng","name_id":"Prosedur keliling tiap petak kandang","kanten_en":"Can they go inside every pen, view the whole pen from the entrance, then check standing pigs, resting pigs, feeder, drinker, dunging area, and the far end in order?","kanten_vi":"Có vào tận trong mọi ô chuồng, nhìn tổng thể từ cửa vào rồi lần lượt xem lợn đứng, lợn nằm, máng ăn, núm uống, khu thải phân và phía trong cùng không.","kanten_id":"Apakah masuk ke dalam semua petak kandang, melihat keseluruhan dari pintu, lalu memeriksa babi berdiri, babi berbaring, tempat pakan, tempat minum, area kotoran, dan bagian dalam secara berurutan?","levels_en":["Glances from a distance and calls it fine, does not enter the pen, and does not check whether resting pigs get up.","With guidance enters the pen, but skips steps such as the feeder or dunging area, and leaves checking resting pigs to others.","With guidance can view the pen from the entrance, then check standing pigs, resting pigs, feeder, drinker, dunging area, and the far end in order.","Independently covers every pen without gaps, checks whether any resting pig fails to get up, and varies the route now and then so no pen gets less attention.","Understands the danger of judging from a distance and of relaxing on other pens after finding one problem, and can teach new staff the rounds order."],"levels_vi":["Chỉ nhìn từ xa rồi cho là ổn, không vào trong ô chuồng, cũng không kiểm tra xem lợn đang nằm có đứng dậy không.","Nếu có chỉ dẫn thì vào ô chuồng, nhưng bỏ sót bước như máng ăn hay khu thải phân, việc xem lợn đang nằm phó mặc cho người khác.","Nếu có chỉ dẫn thì nhìn tổng thể từ cửa vào, rồi lần lượt xem lợn đứng, lợn nằm, máng ăn, núm uống, khu thải phân và phía trong cùng được.","Không cần chỉ dẫn cũng đi hết mọi ô chuồng không sót, kiểm tra xem có con lợn nằm nào không đứng dậy không, thỉnh thoảng đổi lộ trình để không có ô nào bị xem sơ sài.","Hiểu sự nguy hiểm của việc nhìn từ xa và của việc thấy một con bất thường rồi yên tâm làm ẩu các ô khác, và có thể hướng dẫn người mới trình tự đi kiểm tra."],"levels_id":["Hanya melihat dari jauh lalu menganggap aman, tidak masuk ke petak kandang, dan tidak memeriksa apakah babi yang berbaring bangun.","Jika ada instruksi, masuk ke petak kandang, tetapi ada langkah yang terlewat seperti tempat pakan atau area kotoran, dan pemeriksaan babi berbaring diserahkan kepada orang lain.","Jika ada instruksi, dapat melihat keseluruhan dari pintu, lalu memeriksa babi berdiri, babi berbaring, tempat pakan, tempat minum, area kotoran, dan bagian dalam secara berurutan.","Tanpa instruksi pun, mengelilingi semua petak kandang tanpa terlewat, memeriksa apakah ada babi berbaring yang tidak bangun, dan sesekali mengubah rute agar tidak ada petak yang kurang diperhatikan.","Memahami bahaya menilai dari jauh dan bahaya menjadi lengah pada petak lain setelah menemukan satu masalah, dan bisa mengajari karyawan baru urutan keliling."]},{"id":"urgency-judge","name":"異常サインの緊急度判定","kanten":"開口呼吸や突然死は緊急、血便（黒いタール便）・水様や粘液の下痢・起立不能は高、跛行・乾いた咳・食欲低下は中と見分け、迷ったら即報告すると口頭で説明できるか。","levels":["異常に気づいても緊急かどうか分けず、様子を見ようと報告を後回しにして悪化させる。","指示があれば報告するが、緊急の異常も他と同じ速さで報告するなど、急ぐ異常の区別があいまいで場当たり的。","指示があれば、開口呼吸・突然死は緊急、血便・水様や粘液の下痢・起立不能は高、跛行・乾いた咳・食欲低下は中と口頭で分けて説明し、報告できる。","指示がなくても緊急度を判断して緊急と高はすぐ報告し、迷う時も即報告し、起立不能や突然死の豚は動かさずに報告する。","報告を後回しにすると治療が間に合わなくなる理由を口頭で説明し、緊急度の見分け方を新人に指導できる。"],"name_en":"Judging Urgency of Abnormal Signs","name_vi":"Phán đoán mức khẩn cấp của dấu hiệu bất thường","name_id":"Menilai tingkat kedaruratan tanda abnormal","kanten_en":"Can they explain aloud how to tell urgent (open-mouth breathing, sudden death) from high (bloody or black tarry stool, watery or mucous diarrhoea, unable to stand) and medium (lameness, dry cough, reduced appetite), and that they report at once when unsure?","kanten_vi":"Có nói được bằng miệng cách phân biệt khẩn cấp (thở há miệng, chết đột ngột), mức cao (phân có máu hoặc phân đen như hắc ín, tiêu chảy phân nước hoặc có nhầy, không đứng dậy được) và mức trung bình (đi khập khiễng, ho khan, giảm ăn), và khi phân vân thì báo cáo ngay không.","kanten_id":"Apakah dapat menjelaskan secara lisan cara membedakan darurat (napas dengan mulut terbuka, mati mendadak), tinggi (feses berdarah atau hitam seperti ter, diare encer atau berlendir, tidak bisa berdiri), dan sedang (pincang, batuk kering, nafsu makan turun), serta melapor segera bila ragu?","levels_en":["Even when noticing an abnormality, does not sort out its urgency, puts off reporting to see how it goes, and lets it get worse.","With guidance reports, but the line between abnormalities to rush is vague, such as reporting urgent cases at the same pace as others, so it is haphazard.","With guidance can explain aloud and report: open-mouth breathing and sudden death as urgent; bloody or black tarry stool, watery or mucous diarrhoea, and unable to stand as high; lameness, dry cough, and reduced appetite as medium.","Independently judges urgency, reports urgent and high cases at once, reports at once even when unsure, and reports a pig that cannot stand or died suddenly without moving it.","Can explain aloud why putting off a report makes treatment too late, and can teach new staff how to tell the urgency levels."],"levels_vi":["Dù nhận ra bất thường cũng không phân mức khẩn cấp, để lại báo cáo sau vì nghĩ cứ theo dõi thêm, khiến tình trạng nặng hơn.","Nếu có chỉ dẫn thì báo cáo, nhưng ranh giới các bất thường cần gấp còn mơ hồ, chẳng hạn báo cáo ca khẩn cấp cũng chậm như các ca khác, nên tùy hứng.","Nếu có chỉ dẫn thì nói bằng miệng và báo cáo được: thở há miệng, chết đột ngột là khẩn cấp; phân có máu hoặc phân đen như hắc ín, tiêu chảy phân nước hoặc có nhầy, không đứng dậy được là mức cao; đi khập khiễng, ho khan, giảm ăn là mức trung bình.","Không cần chỉ dẫn cũng tự phán đoán mức khẩn cấp, báo cáo ngay các ca khẩn cấp và mức cao, khi phân vân cũng báo ngay, và báo cáo lợn không đứng dậy được hoặc chết đột ngột mà không di chuyển nó.","Giải thích được bằng miệng vì sao để báo cáo chậm thì điều trị không kịp, và có thể hướng dẫn người mới cách phân biệt các mức khẩn cấp."],"levels_id":["Meski menyadari ada yang abnormal, tidak memilah tingkat kedaruratannya, menunda laporan dengan alasan melihat perkembangan, hingga kondisinya memburuk.","Jika ada instruksi, melapor, tetapi batas kelainan yang harus cepat masih samar, misalnya kasus darurat dilaporkan sama lambatnya dengan yang lain, sehingga tidak menentu.","Jika ada instruksi, dapat menjelaskan secara lisan dan melapor: napas dengan mulut terbuka dan mati mendadak sebagai darurat; feses berdarah atau hitam seperti ter, diare encer atau berlendir, dan tidak bisa berdiri sebagai tinggi; pincang, batuk kering, dan nafsu makan turun sebagai sedang.","Tanpa instruksi pun, menilai tingkat kedaruratan, segera melapor kasus darurat dan tinggi, segera melapor juga saat ragu, dan melaporkan babi yang tidak bisa berdiri atau mati mendadak tanpa memindahkannya.","Dapat menjelaskan secara lisan mengapa menunda laporan membuat pengobatan terlambat, dan bisa mengajari karyawan baru cara membedakan tingkat kedaruratan."]},{"id":"report-template","name":"異常報告の中身","kanten":"異常を見つけたら、日時・棟/列/豚房番号・対象の豚（マーキング色など）・症状・いつから・同房の状況を整理して第一報として伝えられるか。","levels":["口頭で「なんか変です」と伝えるだけで、場所も個体も症状もわからず、聞き返されて初めて答える。","指示があれば報告するが、豚房番号やどの豚か、症状の具体性、いつからかが抜け、同房の状況は伝えない。","指示があれば、日時・棟/列/豚房番号・対象の豚（マーキング色など）・症状・いつから・同房の状況を整理して第一報を伝えられる。","指示がなくても項目をそろえて第一報を伝え、症状を見たまま具体的に述べ、獣医師への連絡が要るかを自分で判断して伝える。","報告の項目が獣医師の判断を助ける理由を理解し、報告の組み立て方を新人に指導できる。"],"name_en":"Contents of an Abnormality Report","name_vi":"Nội dung báo cáo bất thường","name_id":"Isi laporan kelainan","kanten_en":"When they find an abnormality, can they organize and give a first report with the date and time, building/row/pen number, the pig (marking colour, etc.), symptoms, since when, and the situation in the same pen?","kanten_vi":"Khi phát hiện bất thường, có sắp xếp và báo cáo lần đầu đủ ngày giờ, số nhà chuồng/hàng/ô chuồng, con lợn nào (màu đánh dấu…), triệu chứng, bắt đầu từ khi nào và tình trạng các con lợn khác cùng ô không.","kanten_id":"Apakah saat menemukan kelainan, dapat menyusun dan menyampaikan laporan awal berisi tanggal dan jam, nomor gedung/baris/petak kandang, babi yang mana (warna tanda, dll.), gejala, sejak kapan, dan kondisi babi lain di petak yang sama?","levels_en":["Only says \"something is off\" verbally, so the place, the pig, and the symptoms are unclear, and answers only when asked again.","With guidance reports, but leaves out the pen number, which pig, concrete symptoms, or since when, and does not tell the situation in the same pen.","With guidance can organize and give a first report with the date and time, building/row/pen number, the pig (marking colour, etc.), symptoms, since when, and the situation in the same pen.","Independently gives a first report with all items in place, describes symptoms concretely as seen, and states on their own whether the veterinarian needs to be contacted.","Understands why these items help the veterinarian's judgment, and can teach new staff how to put a report together."],"levels_vi":["Chỉ nói miệng là \"có gì đó lạ\", nên không rõ vị trí, con lợn nào, triệu chứng gì, bị hỏi lại mới trả lời.","Nếu có chỉ dẫn thì báo cáo, nhưng thiếu số ô chuồng, con lợn nào, triệu chứng cụ thể hoặc bắt đầu từ khi nào, và không nói tình trạng các con lợn khác cùng ô.","Nếu có chỉ dẫn thì sắp xếp và báo cáo lần đầu được ngày giờ, số nhà chuồng/hàng/ô chuồng, con lợn nào (màu đánh dấu…), triệu chứng, bắt đầu từ khi nào và tình trạng các con lợn khác cùng ô.","Không cần chỉ dẫn cũng báo cáo lần đầu đủ các mục, nói cụ thể triệu chứng đúng như thấy, và tự nêu có cần liên lạc với bác sĩ thú y hay không.","Hiểu vì sao các mục này giúp bác sĩ thú y phán đoán, và có thể hướng dẫn người mới cách soạn báo cáo."],"levels_id":["Hanya mengatakan secara lisan \"ada yang aneh\", sehingga tempat, babi yang mana, dan gejalanya tidak jelas, dan baru menjawab setelah ditanya lagi.","Jika ada instruksi, melapor, tetapi nomor petak kandang, babi yang mana, kejelasan gejala, atau sejak kapan terlewat, dan kondisi babi lain di petak yang sama tidak disampaikan.","Jika ada instruksi, dapat menyusun dan menyampaikan laporan awal berisi tanggal dan jam, nomor gedung/baris/petak kandang, babi yang mana (warna tanda, dll.), gejala, sejak kapan, dan kondisi babi lain di petak yang sama.","Tanpa instruksi pun, menyampaikan laporan awal dengan butir yang lengkap, menyampaikan gejala secara konkret sesuai yang terlihat, dan menyatakan sendiri apakah dokter hewan perlu dihubungi.","Memahami mengapa butir-butir ini membantu penilaian dokter hewan, dan bisa mengajari karyawan baru cara menyusun laporan."]},{"id":"mark-followup","name":"マーキングと翌日の追跡","kanten":"異常な豚にスプレーでマーキングし、翌日同じ豚を確かめて変化を報告できるか。","levels":["マーキングスプレーを持たず、異常な豚に印を付けないため、翌日に同じ豚を見つけられない。","指示があれば印を付けるが、翌日の確認があいまいで忘れがち、変化の報告も他者まかせ。","指示があれば異常な豚に印を付け、翌日同じ豚を確かめると口頭で答え、変化があれば伝えられる。","指示がなくてもスプレーを常に携帯して印を付け、前日に印を付けた豚を翌日確かめて報告した記録（日報・連絡）を示せる。","印がないと翌日に同じ豚を見つけられない理由と、変化を追う意味を理解し、新人に指導できる。"],"name_en":"Marking and Next-Day Follow-up","name_vi":"Đánh dấu và theo dõi ngày hôm sau","name_id":"Penandaan dan tindak lanjut esok hari","kanten_en":"Can they spray-mark abnormal pigs, check the same pig the next day, and report any change?","kanten_vi":"Có phun đánh dấu lợn bất thường, hôm sau kiểm tra lại đúng con đó và báo cáo thay đổi không.","kanten_id":"Apakah menandai babi yang abnormal dengan semprotan, memeriksa babi yang sama keesokan harinya, dan melaporkan perubahannya?","levels_en":["Does not carry the marking spray and does not mark abnormal pigs, so cannot find the same pig the next day.","With guidance marks, but the next-day check is vague and easily forgotten, and leaves reporting changes to others.","With guidance can mark abnormal pigs, say aloud that they will check the same pig the next day, and tell any change.","Independently always carries the spray and marks pigs, and can show a record (daily report or message) of having checked the previously marked pig the next day and reported on it.","Understands why the same pig cannot be found the next day without a mark and what following changes is for, and can teach new staff."],"levels_vi":["Không mang bình xịt đánh dấu, không đánh dấu lợn bất thường nên hôm sau không tìm lại được đúng con đó.","Nếu có chỉ dẫn thì đánh dấu, nhưng việc kiểm tra hôm sau còn mơ hồ và hay quên, việc báo cáo thay đổi phó mặc cho người khác.","Nếu có chỉ dẫn thì đánh dấu lợn bất thường, nói được bằng miệng rằng hôm sau sẽ kiểm tra lại đúng con đó, và báo được thay đổi nếu có.","Không cần chỉ dẫn cũng luôn mang bình xịt để đánh dấu, và xuất trình được bản ghi (nhật báo, tin nhắn liên lạc) cho thấy đã kiểm tra con lợn đánh dấu hôm trước vào hôm sau và đã báo cáo.","Hiểu vì sao không đánh dấu thì hôm sau không tìm lại được đúng con đó, hiểu ý nghĩa của việc theo dõi thay đổi, và có thể hướng dẫn người mới."],"levels_id":["Tidak membawa semprotan penanda dan tidak menandai babi yang abnormal, sehingga esoknya tidak dapat menemukan babi yang sama.","Jika ada instruksi, menandai, tetapi pemeriksaan esok hari samar dan mudah terlupa, dan pelaporan perubahan diserahkan kepada orang lain.","Jika ada instruksi, dapat menandai babi yang abnormal, menyebutkan secara lisan bahwa babi yang sama akan diperiksa esok hari, dan menyampaikan perubahan bila ada.","Tanpa instruksi pun, selalu membawa semprotan dan menandai, serta dapat menunjukkan catatan (laporan harian atau pesan laporan) bahwa babi yang ditandai sehari sebelumnya diperiksa keesokan harinya dan dilaporkan.","Memahami mengapa tanpa tanda babi yang sama tidak bisa ditemukan esoknya dan arti memantau perubahan, serta bisa mengajari karyawan baru."]},{"id":"safe-quiet","name":"静かな巡回と人の安全","kanten":"声をかけながら静かに近づき、視界の外から急に近づかず、逃げ道を確保して壁際に追い込まれない位置で見回れるか。","levels":["急ぎ足で視界の外から近づいて豚を驚かせ、声もかけず、逃げ道も考えず、壁際で観察する。","指示があれば静かに歩くが、背後から近づいたり壁際で観察したりして、逃げ道の確保が抜ける。","指示があれば、声をかけながらゆっくり近づき、豚の視界に入る位置から、逃げ道を確保して観察できる。","指示がなくても静かに声をかけて近づき、壁際に追い込まれない位置を選び、豚房内でも通路でも常に逃げ道を確保して見回る。","驚かせると突進される理由と、静かな巡回が正常な状態を見るために必要な理由を理解し、新人に指導できる。"],"name_en":"Quiet Rounds and Personal Safety","name_vi":"Đi kiểm tra yên lặng và an toàn cho người","name_id":"Keliling tenang dan keselamatan diri","kanten_en":"Can they approach quietly while speaking to the pigs, avoid approaching suddenly from outside their view, and observe from a position that keeps an escape route and does not get them cornered against a wall?","kanten_vi":"Có đến gần nhẹ nhàng vừa lên tiếng gọi lợn, không bất ngờ tiến lại từ ngoài tầm nhìn của lợn, và đứng ở vị trí có đường thoát, không bị dồn vào sát tường khi quan sát không.","kanten_id":"Apakah mendekat dengan tenang sambil menyapa babi, tidak mendadak mendekat dari luar pandangan babi, dan mengamati dari posisi yang menyisakan jalan keluar serta tidak terpojok di dinding?","levels_en":["Hurries and approaches from outside the pigs' view and startles them, does not speak to them, does not think of an escape route, and observes against a wall.","With guidance walks quietly, but approaches from behind or observes against a wall, and leaves out securing an escape route.","With guidance can approach slowly while speaking, from a position within the pigs' view, and observe with an escape route secured.","Independently approaches quietly while speaking, chooses a position where they will not be cornered against a wall, and keeps an escape route open at all times in the pen and the aisle.","Understands why startling pigs can lead to a charge and why quiet rounds are needed to see the normal state, and can teach new staff."],"levels_vi":["Đi vội, tiến lại từ ngoài tầm nhìn khiến lợn giật mình, không lên tiếng gọi, không nghĩ đến đường thoát và đứng sát tường để quan sát.","Nếu có chỉ dẫn thì đi nhẹ nhàng, nhưng đến từ phía sau hoặc đứng sát tường để quan sát, bỏ sót việc giữ đường thoát.","Nếu có chỉ dẫn thì vừa lên tiếng vừa từ từ đến gần, từ vị trí nằm trong tầm nhìn của lợn, và quan sát với đường thoát được đảm bảo.","Không cần chỉ dẫn cũng nhẹ nhàng lên tiếng rồi đến gần, chọn vị trí không bị dồn vào sát tường, và luôn giữ đường thoát cả trong ô chuồng lẫn ngoài lối đi.","Hiểu vì sao làm lợn giật mình thì có thể bị lao vào húc, vì sao đi kiểm tra yên lặng mới thấy được trạng thái bình thường, và có thể hướng dẫn người mới."],"levels_id":["Terburu-buru dan mendekat dari luar pandangan babi hingga mengagetkan, tidak menyapa, tidak memikirkan jalan keluar, dan mengamati di dekat dinding.","Jika ada instruksi, berjalan dengan tenang, tetapi mendekat dari belakang atau mengamati di dekat dinding, dan lupa menyiapkan jalan keluar.","Jika ada instruksi, dapat mendekat pelan-pelan sambil menyapa, dari posisi yang terlihat oleh babi, dan mengamati dengan jalan keluar yang terjamin.","Tanpa instruksi pun, mendekat dengan tenang sambil menyapa, memilih posisi agar tidak terpojok di dinding, dan selalu menjaga jalan keluar baik di dalam petak kandang maupun di lorong.","Memahami mengapa mengagetkan babi bisa berujung diseruduk dan mengapa keliling yang tenang diperlukan untuk melihat kondisi normal, dan bisa mengajari karyawan baru."]}]},{"id":"ai-insem","category":"breeding","no":"No.14","name":"AI（人工授精）注入作業","purposeShort":"受胎数・産子数を高く保ち、精液を無駄なく計画的に使う","gyomu":"14","aspects":[{"id":"prep-activity","name":"事前準備と精子活性の確認","kanten":"産歴・AI回数・本数を確認して器具をそろえ、注入前に顕微鏡で精子の活性を確認できるか。","levels":["母豚や本数を確かめず器具も不足したまま始め、活性確認を省いて悪い精液を使う。","指示があれば準備するが、本数の確認や活性チェックに抜けが多い。","指示があれば産歴・回数・本数を確認し、顕微鏡で活性を見てから注入に入れる。","指示がなくても対象母豚と必要本数を自分で確かめ、活性確認と保冷まで整えてから始める。","準備不足が受胎率と精液のムダに直結することを理解し、準備と活性確認の手順を新人に指導できる。"],"name_en":"Advance preparation and checking sperm activity","kanten_en":"Can they check parity, AI count, and the number of doses, prepare the equipment, and check sperm activity under a microscope before insemination?","levels_en":["Starts without confirming the sows or the number of doses and with equipment missing, skips the activity check, and uses bad semen.","With guidance, prepares, but often misses checking the number of doses and the activity check.","With guidance, checks parity, AI count, and the number of doses, and can check activity under the microscope before starting insemination.","Independently confirms the target sows and the required number of doses, and gets everything ready including the activity check and cold storage before starting.","Understands that poor preparation directly lowers conception rates and wastes semen, and can teach new staff the preparation and activity-check procedure."],"name_vi":"Chuẩn bị trước và kiểm tra hoạt lực tinh trùng","kanten_vi":"Có kiểm tra lứa đẻ, số lần AI, số liều để chuẩn bị dụng cụ, và kiểm tra hoạt lực tinh trùng bằng kính hiển vi trước khi bơm không.","levels_vi":["Bắt đầu mà không kiểm tra lợn nái và số liều, dụng cụ còn thiếu, bỏ qua kiểm tra hoạt lực nên dùng cả tinh dịch kém.","Nếu có chỉ dẫn thì chuẩn bị, nhưng hay bỏ sót việc kiểm tra số liều và hoạt lực.","Nếu có chỉ dẫn thì kiểm tra lứa đẻ, số lần, số liều, xem hoạt lực bằng kính hiển vi rồi mới vào bơm tinh.","Không cần chỉ dẫn cũng tự kiểm tra lợn nái đối tượng và số liều cần thiết, chuẩn bị xong cả kiểm tra hoạt lực và giữ lạnh rồi mới bắt đầu.","Hiểu việc chuẩn bị thiếu ảnh hưởng trực tiếp đến tỷ lệ thụ thai và lãng phí tinh dịch, và có thể hướng dẫn người mới trình tự chuẩn bị và kiểm tra hoạt lực."],"name_id":"Persiapan awal dan pemeriksaan daya gerak sperma","kanten_id":"Apakah memeriksa paritas, jumlah AI, dan jumlah dosis untuk menyiapkan alat, serta memeriksa daya gerak sperma dengan mikroskop sebelum inseminasi.","levels_id":["Mulai tanpa memeriksa induk dan jumlah dosis, alat pun kurang, melewatkan pemeriksaan daya gerak sehingga memakai semen yang jelek.","Jika ada instruksi bisa menyiapkan, tetapi sering lalai memeriksa jumlah dosis dan daya gerak.","Jika ada instruksi, bisa memeriksa paritas, jumlah AI, dan jumlah dosis, lalu melihat daya gerak dengan mikroskop sebelum mulai inseminasi.","Tanpa instruksi pun, memastikan sendiri induk babi sasaran dan jumlah dosis yang diperlukan, serta menyiapkan semuanya termasuk pemeriksaan daya gerak dan penyimpanan dingin sebelum mulai.","Memahami bahwa persiapan yang kurang langsung menurunkan angka kebuntingan dan memboroskan semen, dan bisa mengajari karyawan baru urutan persiapan dan pemeriksaan daya gerak."]},{"id":"acceptance","name":"許容確認と挿入の判断","kanten":"許容を確認してから無理なく挿入し、排卵タイミングに合った適期に注入できるか。","levels":["許容を確かめず無理に挿入し、排卵タイミングを無視して受胎率を落とす。","指示があれば実施するが、許容確認が不十分で適期を外すことが多い。","指示があれば許容を確認し、指示された適期にひと通り注入できる。","指示がなくても許容を確かめてから適期に注入し、無理な挿入を避ける。","許容開始からの排卵時間を理解し、適期の判断と丁寧な注入を新人に指導できる。"],"name_en":"Confirming standing heat and judging insertion","kanten_en":"Can they confirm standing heat before inserting gently, and inseminate at the right time matched to ovulation?","levels_en":["Inserts forcibly without confirming standing heat and ignores ovulation timing, lowering the conception rate.","With guidance, performs the procedure, but standing heat checks are insufficient and the optimal window is often missed.","With guidance, confirms standing heat and can adequately inseminate at the instructed timing.","Independently confirms standing heat before inseminating at the right time, avoiding forced insertion.","Understands the time from onset of standing heat to ovulation, and can teach new staff timing judgment and careful insemination."],"name_vi":"Kiểm tra phản xạ đứng yên và phán đoán đưa ống vào","kanten_vi":"Có kiểm tra phản xạ đứng yên rồi mới đưa ống vào nhẹ nhàng, bơm tinh đúng thời kỳ phù hợp với thời điểm rụng trứng không.","levels_vi":["Không kiểm tra phản xạ đứng yên mà đưa ống vào cưỡng ép, bỏ qua thời điểm rụng trứng làm giảm tỷ lệ thụ thai.","Nếu có chỉ dẫn thì làm được, nhưng kiểm tra phản xạ đứng yên chưa đủ, thường lỡ thời kỳ thích hợp.","Nếu có chỉ dẫn thì kiểm tra phản xạ đứng yên, bơm tinh được cơ bản vào thời kỳ được chỉ định.","Không cần chỉ dẫn cũng kiểm tra phản xạ đứng yên rồi bơm tinh đúng thời kỳ, tránh đưa ống vào cưỡng ép.","Hiểu thời gian rụng trứng tính từ khi bắt đầu chịu đực, và có thể hướng dẫn người mới cách phán đoán thời kỳ và bơm tinh nhẹ nhàng."],"name_id":"Pemeriksaan refleks diam dan keputusan memasukkan kateter","kanten_id":"Apakah memeriksa refleks diam dulu baru memasukkan kateter tanpa paksaan, dan bisa memasukkan semen pada waktu yang tepat sesuai saat ovulasi.","levels_id":["Memasukkan kateter dengan paksa tanpa memeriksa refleks diam, mengabaikan saat ovulasi sehingga menurunkan angka kebuntingan.","Jika ada instruksi bisa melaksanakan, tetapi pemeriksaan refleks diam kurang sehingga sering meleset dari waktu yang tepat.","Jika ada instruksi, bisa memeriksa refleks diam dan memasukkan semen secara garis besar pada waktu yang diinstruksikan.","Tanpa instruksi pun, memeriksa refleks diam dulu baru memasukkan semen pada waktu yang tepat, dan menghindari pemasukan kateter secara paksa.","Memahami waktu ovulasi dihitung dari mulainya refleks diam, dan bisa mengajari karyawan baru cara menilai waktu yang tepat dan memasukkan semen dengan hati-hati."]},{"id":"hygiene-temp","name":"器具・外陰部の清潔と精液の温度管理","kanten":"器具・外陰部を清潔に保ち、精液をゆっくり入れ、急激な加温を避けて温度管理できるか。","levels":["器具・外陰部を清潔にせず、精液を急激に加温してカテーテル汚染や高温障害を招く。","指示があれば清潔にするが、温度管理や注入速度に漏れがある。","指示があれば器具・外陰部を清潔に保ち、精液をひと通りゆっくり入れられる。","指示がなくても清潔を徹底し、精液を急激に加温せずゆっくり注入する。","子宮炎・高温障害の仕組みを理解し、清潔操作と温度管理を新人に指導できる。"],"name_en":"Cleanliness of equipment and vulva, and semen temperature control","kanten_en":"Can they keep the equipment and vulva clean, introduce semen slowly, and control temperature while avoiding rapid warming?","levels_en":["Does not clean the equipment or vulva and warms semen rapidly, causing catheter contamination and heat damage.","With guidance, keeps things clean, but is inconsistent about temperature control and insemination speed.","With guidance, keeps the equipment and vulva clean and can adequately introduce the semen slowly.","Independently maintains strict cleanliness and inseminates slowly without rapidly warming the semen.","Understands the mechanisms of metritis and heat damage, and can teach new staff clean technique and temperature control."],"name_vi":"Giữ sạch dụng cụ, bộ phận sinh dục ngoài và quản lý nhiệt độ tinh dịch","kanten_vi":"Có giữ sạch dụng cụ và bộ phận sinh dục ngoài, bơm tinh chậm rãi, tránh làm ấm đột ngột và quản lý được nhiệt độ không.","levels_vi":["Không làm sạch dụng cụ và bộ phận sinh dục ngoài, làm ấm tinh dịch đột ngột, gây bẩn catheter và hỏng do nhiệt độ cao.","Nếu có chỉ dẫn thì làm sạch, nhưng có bỏ sót việc quản lý nhiệt độ và tốc độ bơm.","Nếu có chỉ dẫn thì giữ sạch dụng cụ và bộ phận sinh dục ngoài, bơm tinh được cơ bản một cách chậm rãi.","Không cần chỉ dẫn cũng giữ sạch kỹ, không làm ấm tinh dịch đột ngột mà bơm chậm rãi.","Hiểu cơ chế viêm tử cung và hỏng do nhiệt độ cao, và có thể hướng dẫn người mới thao tác sạch và quản lý nhiệt độ."],"name_id":"Kebersihan alat dan vulva serta pengelolaan suhu semen","kanten_id":"Apakah menjaga alat dan vulva tetap bersih, memasukkan semen perlahan, dan mengelola suhu dengan menghindari pemanasan mendadak.","levels_id":["Tidak membersihkan alat dan vulva, memanaskan semen secara mendadak sehingga menyebabkan kontaminasi kateter dan kerusakan karena suhu tinggi.","Jika ada instruksi bisa menjaga kebersihan, tetapi sering lalai mengelola suhu dan kecepatan memasukkan semen.","Jika ada instruksi, bisa menjaga alat dan vulva tetap bersih, dan memasukkan semen secara garis besar dengan perlahan.","Tanpa instruksi pun, menjaga kebersihan dengan ketat, dan memasukkan semen perlahan tanpa memanaskannya mendadak.","Memahami mekanisme radang rahim dan kerusakan karena suhu tinggi, dan bisa mengajari karyawan baru kerja bersih dan pengelolaan suhu."]},{"id":"natural-inflow","name":"自然流入での注入とカテーテル対応","kanten":"精液を無理に押し込まず自然に流し、注入後2〜3分さわらず、排尿・汚染時にカテーテルを正しく対応できるか。","levels":["精液を無理に押し込み、注入直後にカテーテルをさわり、汚れたカテーテルもそのまま使う。","指示があれば注入できるが、押し込みや注入後の放置時間にムラがあり、排尿時の対応は他者まかせ。","指示があれば自然流入で注入し、注入後2〜3分さわらずに待てる。","指示がなくても排尿時はカテーテルを上げ、汚れたら新品に交換し、自然流入を守って抜去まで丁寧に行う。","母豚が吸い込む仕組みと逆流・汚染の原因を理解し、注入とカテーテル対応のコツを新人に指導できる。"],"name_en":"Insemination by natural inflow and catheter handling","kanten_en":"Can they let the semen flow in naturally without forcing it, leave the catheter untouched for 2-3 minutes after insemination, and handle the catheter correctly when the sow urinates or it gets contaminated?","levels_en":["Forces the semen in, touches the catheter right after insemination, and keeps using contaminated catheters.","With guidance, can inseminate, but tends to push the semen in, is inconsistent about the waiting time afterward, and leaves urination handling to others.","With guidance, inseminates by natural inflow and can wait 2-3 minutes without touching the catheter.","Independently raises the catheter when the sow urinates, replaces contaminated catheters with new ones, keeps to natural inflow, and removes the catheter carefully.","Understands how the sow draws the semen in and what causes backflow and contamination, and can teach new staff the knack of insemination and catheter handling."],"name_vi":"Bơm tinh bằng cách để tự chảy và xử lý catheter","kanten_vi":"Có để tinh dịch tự chảy vào không ép mạnh, sau khi bơm 2〜3 phút không chạm vào, và xử lý đúng catheter khi lợn đi tiểu hoặc catheter bị bẩn không.","levels_vi":["Ép mạnh tinh dịch vào, vừa bơm xong đã chạm vào catheter, catheter bẩn vẫn dùng tiếp.","Nếu có chỉ dẫn thì bơm được, nhưng hay ép tinh vào, thời gian chờ sau khi bơm không đều, việc xử lý khi lợn đi tiểu thì phó mặc cho người khác.","Nếu có chỉ dẫn thì bơm bằng cách để tự chảy, và chờ được 2〜3 phút sau khi bơm mà không chạm vào.","Không cần chỉ dẫn cũng nâng catheter lên khi lợn đi tiểu, thay catheter mới khi bị bẩn, giữ cách để tự chảy và rút ra nhẹ nhàng.","Hiểu cơ chế lợn nái tự hút tinh vào và nguyên nhân trào ngược, nhiễm bẩn, và có thể hướng dẫn người mới mẹo bơm tinh và xử lý catheter."],"name_id":"Inseminasi dengan aliran alami dan penanganan kateter","kanten_id":"Apakah membiarkan semen mengalir masuk secara alami tanpa didorong paksa, tidak menyentuh kateter selama 2〜3 menit setelah inseminasi, dan menangani kateter dengan benar saat babi kencing atau kateter kotor.","levels_id":["Mendorong semen dengan paksa, langsung menyentuh kateter begitu selesai, dan tetap memakai kateter yang kotor.","Jika ada instruksi bisa inseminasi, tetapi cenderung mendorong semen, waktu tunggu setelahnya tidak tetap, dan penanganan saat babi kencing diserahkan ke orang lain.","Jika ada instruksi, bisa inseminasi dengan aliran alami dan menunggu 2〜3 menit tanpa menyentuh kateter.","Tanpa instruksi pun, mengangkat kateter saat babi kencing, mengganti dengan yang baru jika kotor, menjaga aliran alami, dan mencabut kateter dengan hati-hati.","Memahami mekanisme induk babi menghisap semen serta penyebab aliran balik dan kontaminasi, dan bisa mengajari karyawan baru trik inseminasi dan penanganan kateter."]},{"id":"record-restock","name":"記録・医療ゴミ処理と資材補充","kanten":"母豚カード・野帳をその場で記入し、医療ゴミを片付け、アル綿・ペーパー等を補充できるか。","levels":["記録をせず、医療ゴミや余ったカテーテルも放置し、資材が切れても補充しない。","指示されれば記入・片付けするが、記載漏れや補充忘れが多い。","指示があれば母豚カード・野帳を記入し、ゴミの片付けと補充までひと通りできる。","指示がなくても作業後すぐ記録し、医療ゴミを正しく処理して次回分の資材を補充しておく。","記録と資材管理が交配計画の土台であることを理解し、記入と片付けの型を新人に指導できる。"],"name_en":"Records, medical waste disposal, and restocking supplies","kanten_en":"Can they fill in the sow card and field notebook on the spot, clear away medical waste, and restock alcohol cotton, paper, and other supplies?","levels_en":["Does not record, leaves medical waste and leftover catheters lying around, and does not restock supplies even when they run out.","With guidance, records and tidies up, but often leaves entries incomplete and forgets to restock.","With guidance, fills in the sow card and field notebook and can adequately tidy up the waste and restock.","Independently records right after the work, disposes of medical waste correctly, and restocks supplies for the next time.","Understands that records and supply management underpin the breeding plan, and can teach new staff the routine of recording and tidying up."],"name_vi":"Ghi chép, xử lý rác y tế và bổ sung vật tư","kanten_vi":"Có ghi thẻ nái và sổ ghi chép ngay tại chỗ, dọn rác y tế, và bổ sung bông cồn, giấy v.v. không.","levels_vi":["Không ghi chép, bỏ mặc rác y tế và catheter còn thừa, vật tư hết cũng không bổ sung.","Nếu có chỉ dẫn thì ghi và dọn dẹp, nhưng hay ghi sót và quên bổ sung.","Nếu có chỉ dẫn thì ghi thẻ nái, sổ ghi chép, dọn rác và bổ sung được cơ bản.","Không cần chỉ dẫn cũng ghi chép ngay sau khi làm, xử lý đúng rác y tế và bổ sung sẵn vật tư cho lần sau.","Hiểu ghi chép và quản lý vật tư là nền tảng của kế hoạch phối giống, và có thể hướng dẫn người mới nề nếp ghi chép và dọn dẹp."],"name_id":"Pencatatan, pembuangan sampah medis, dan pengisian ulang perlengkapan","kanten_id":"Apakah mengisi kartu induk dan buku catatan di tempat, membereskan sampah medis, dan mengisi ulang kapas alkohol, kertas, dan lainnya.","levels_id":["Tidak mencatat, membiarkan sampah medis dan kateter sisa, dan tidak mengisi ulang walau perlengkapan habis.","Jika ada instruksi bisa mencatat dan membereskan, tetapi catatan sering kurang dan lupa mengisi ulang.","Jika ada instruksi, bisa mengisi kartu induk dan buku catatan, membereskan sampah, dan mengisi ulang secara garis besar.","Tanpa instruksi pun, langsung mencatat setelah bekerja, membuang sampah medis dengan benar, dan menyiapkan perlengkapan untuk kali berikutnya.","Memahami bahwa pencatatan dan pengelolaan perlengkapan adalah dasar rencana perkawinan, dan bisa mengajari karyawan baru pola pencatatan dan beres-beres."]}],"name_en":"AI (artificial insemination)","purposeShort_en":"Keep conception and litter size high, and use semen efficiently and according to plan","name_vi":"Công việc bơm tinh AI (thụ tinh nhân tạo)","purposeShort_vi":"Giữ số con thụ thai và số con đẻ ra ở mức cao, dùng tinh dịch có kế hoạch, không lãng phí","name_id":"Pekerjaan inseminasi AI (inseminasi buatan)","purposeShort_id":"Menjaga angka kebuntingan dan jumlah anak tetap tinggi, dan memakai semen secara terencana tanpa pemborosan"},{"id":"standing-check","category":"breeding","no":"No.33","name":"許容確認","purposeShort":"交配に入れる最適なタイミングを見極め、受胎率と産子数を上げる","gyomu":"33","aspects":[{"id":"target-list","name":"対象母豚の絞り込み","kanten":"前日の記録から離乳後3〜7日と交配後約21日の母豚を抜き出し、重点的に確認できるか。","levels":["記録を見ずに手当たり次第に見て、発情の来やすい母豚を確認し忘れる。","指示があれば対象を見るが、離乳日・前回交配日の確認に抜けが多い。","指示があれば前日の記録から対象母豚をひと通り抜き出して確認できる。","指示がなくても離乳後3〜7日・交配後約21日の母豚を自分でリストアップし、重点的に見る。","発情周期と発情が来やすい時期の理由を理解し、対象の絞り込み方を新人に指導できる。"],"name_en":"Narrowing down the target sows","kanten_en":"Can they pick out sows at 3-7 days after weaning and around 21 days after mating from the previous day's records and check them with priority?","levels_en":["Looks at sows at random without checking the records, and forgets to check the sows most likely to come into heat.","With guidance, looks at the targets, but often misses checking weaning dates and previous mating dates.","With guidance, can adequately pick out the target sows from the previous day's records and check them.","Independently lists up sows at 3-7 days after weaning and around 21 days after mating, and checks them with priority.","Understands the estrous cycle and why heat tends to come at those times, and can teach new staff how to narrow down the targets."],"name_vi":"Chọn lọc lợn nái đối tượng","kanten_vi":"Có xem ghi chép ngày hôm trước để lọc ra nái 3〜7 ngày sau cai sữa và nái khoảng 21 ngày sau phối, rồi kiểm tra trọng điểm không.","levels_vi":["Không xem ghi chép mà xem tùy tiện, quên kiểm tra những nái dễ động dục.","Nếu có chỉ dẫn thì xem nái đối tượng, nhưng hay bỏ sót việc kiểm tra ngày cai sữa và ngày phối lần trước.","Nếu có chỉ dẫn thì lọc ra được cơ bản nái đối tượng từ ghi chép ngày hôm trước để kiểm tra.","Không cần chỉ dẫn cũng tự lập danh sách nái 3〜7 ngày sau cai sữa và khoảng 21 ngày sau phối, kiểm tra trọng điểm.","Hiểu chu kỳ động dục và lý do động dục dễ đến vào các thời điểm đó, và có thể hướng dẫn người mới cách chọn lọc đối tượng."],"name_id":"Menyaring induk babi sasaran","kanten_id":"Apakah dari catatan hari sebelumnya bisa memilih induk 3〜7 hari setelah sapih dan induk sekitar 21 hari setelah kawin, lalu memeriksanya secara khusus.","levels_id":["Melihat sembarangan tanpa membaca catatan, dan lupa memeriksa induk yang mudah birahi.","Jika ada instruksi bisa melihat sasaran, tetapi sering lalai memeriksa tanggal sapih dan tanggal kawin sebelumnya.","Jika ada instruksi, bisa memilih induk sasaran dari catatan hari sebelumnya dan memeriksanya secara garis besar.","Tanpa instruksi pun, membuat sendiri daftar induk 3〜7 hari setelah sapih dan sekitar 21 hari setelah kawin, lalu memeriksanya secara khusus.","Memahami siklus birahi dan alasan birahi mudah datang pada waktu-waktu itu, dan bisa mengajari karyawan baru cara menyaring sasaran."]},{"id":"boar-backpressure","name":"雄豚接触＋背圧での確認","kanten":"雄豚を接触させ、背圧をかけて強く押しても動かず立つかを確かめられるか。","levels":["雄豚を近づけず外陰部の腫れだけで判断し、偽陰性・適期外授精を招く。","指示があれば背圧を確かめるが、雄豚接触が不十分で判断が甘い。","指示があれば雄豚接触＋背圧で許容をひと通り確認できる。","指示がなくても雄豚を接触させて背圧をかけ、静止するかを確実に確かめる。","許容反応の仕組みを理解し、確実な確認方法と適期の見極めを新人に指導できる。"],"name_en":"Checking with boar contact plus back pressure","kanten_en":"Can they bring a boar into contact and apply back pressure to verify that the sow stands firm even when pushed hard?","levels_en":["Judges only by vulvar swelling without bringing a boar close, causing false negatives and mistimed insemination.","With guidance, checks back pressure, but boar contact is insufficient and judgment is unreliable.","With guidance, can adequately confirm standing heat with boar contact plus back pressure.","Independently brings the boar into contact, applies back pressure, and reliably verifies that the sow stands still.","Understands the mechanism of the standing reflex, and can teach new staff reliable checking methods and how to judge the optimal timing."],"name_vi":"Kiểm tra bằng tiếp xúc lợn đực và ấn lưng","kanten_vi":"Có cho tiếp xúc lợn đực, ấn lưng mạnh để kiểm tra lợn có đứng yên không nhúc nhích không.","levels_vi":["Không cho lợn đực lại gần, chỉ phán đoán bằng độ sưng của bộ phận sinh dục ngoài, gây âm tính giả và phối sai thời kỳ.","Nếu có chỉ dẫn thì kiểm tra bằng ấn lưng, nhưng việc tiếp xúc lợn đực chưa đủ nên phán đoán còn non.","Nếu có chỉ dẫn thì kiểm tra được cơ bản phản xạ đứng yên bằng tiếp xúc lợn đực và ấn lưng.","Không cần chỉ dẫn cũng cho tiếp xúc lợn đực và ấn lưng, kiểm tra chắc chắn lợn có đứng yên không.","Hiểu cơ chế của phản xạ đứng yên, và có thể hướng dẫn người mới cách kiểm tra chắc chắn và nhìn ra thời kỳ thích hợp."],"name_id":"Pemeriksaan dengan kontak babi jantan + tekanan punggung","kanten_id":"Apakah bisa mendekatkan babi jantan, memberi tekanan pada punggung, dan memastikan babi tetap berdiri diam walau ditekan kuat.","levels_id":["Tidak mendekatkan babi jantan dan hanya menilai dari bengkaknya vulva, sehingga terjadi negatif palsu dan inseminasi di luar waktu yang tepat.","Jika ada instruksi bisa memeriksa tekanan punggung, tetapi kontak dengan babi jantan kurang sehingga penilaiannya lemah.","Jika ada instruksi, bisa memeriksa refleks diam secara garis besar dengan kontak babi jantan + tekanan punggung.","Tanpa instruksi pun, mendekatkan babi jantan, memberi tekanan punggung, dan memastikan dengan pasti apakah babi berdiri diam.","Memahami mekanisme refleks diam saat birahi, dan bisa mengajari karyawan baru cara pemeriksaan yang pasti dan penentuan waktu yang tepat."]},{"id":"sign-composite","name":"外陰部・粘液・行動の複合判断","kanten":"外陰部の色・腫れ、粘液の状態、行動の変化を合わせて見て、発情の時期を総合判断できるか。","levels":["外陰部の見た目だけで授精を決め、粘液や行動のサインを見ない。","指示があればサインを見るが、透明で糸を引く粘液と白くにごった粘液の区別など判断が曖昧。","指示があれば外陰部・粘液・行動をひと通り観察して判断材料にできる。","指示がなくても複数のサインを合わせて時期を判断し、見た目だけで早すぎる授精をしない。","各サインが発情のどの段階を示すかを理解し、複合判断の見方を新人に指導できる。"],"name_en":"Combined judgment from vulva, mucus, and behavior","kanten_en":"Can they look at vulvar color and swelling, the state of the mucus, and behavioral changes together, and judge the stage of heat comprehensively?","levels_en":["Decides to inseminate from the look of the vulva alone, without looking at mucus or behavioral signs.","With guidance, looks at the signs, but judgment is vague, such as distinguishing clear stringy mucus from cloudy white mucus.","With guidance, can adequately observe the vulva, mucus, and behavior and use them as judgment material.","Independently combines multiple signs to judge the stage, and does not inseminate too early on looks alone.","Understands which stage of heat each sign indicates, and can teach new staff how to make the combined judgment."],"name_vi":"Phán đoán tổng hợp từ âm hộ, dịch nhầy và hành vi","kanten_vi":"Có nhìn kết hợp màu và độ sưng của âm hộ, trạng thái dịch nhầy, thay đổi hành vi để phán đoán tổng hợp thời kỳ động dục không.","levels_vi":["Chỉ nhìn bề ngoài âm hộ đã quyết định phối, không xem dấu hiệu dịch nhầy và hành vi.","Nếu có chỉ dẫn thì xem các dấu hiệu, nhưng phán đoán còn mơ hồ như phân biệt dịch nhầy trong kéo sợi với dịch nhầy trắng đục.","Nếu có chỉ dẫn thì quan sát được cơ bản âm hộ, dịch nhầy, hành vi để làm căn cứ phán đoán.","Không cần chỉ dẫn cũng kết hợp nhiều dấu hiệu để phán đoán thời kỳ, không phối quá sớm chỉ dựa vào bề ngoài.","Hiểu mỗi dấu hiệu thể hiện giai đoạn nào của động dục, và có thể hướng dẫn người mới cách nhìn phán đoán tổng hợp."],"name_id":"Penilaian gabungan dari vulva, lendir, dan perilaku","kanten_id":"Apakah melihat bersama warna dan bengkak vulva, keadaan lendir, serta perubahan perilaku untuk menilai masa birahi secara menyeluruh.","levels_id":["Memutuskan inseminasi hanya dari penampilan vulva, tanpa melihat tanda lendir dan perilaku.","Jika ada instruksi bisa melihat tanda-tandanya, tetapi penilaiannya samar, misalnya membedakan lendir bening yang menarik benang dengan lendir putih keruh.","Jika ada instruksi, bisa mengamati vulva, lendir, dan perilaku secara garis besar sebagai bahan penilaian.","Tanpa instruksi pun, menggabungkan beberapa tanda untuk menilai waktunya, dan tidak inseminasi terlalu awal hanya dari penampilan.","Memahami tiap tanda menunjukkan tahap birahi yang mana, dan bisa mengajari karyawan baru cara penilaian gabungan."]},{"id":"quiet-timing","name":"静かな母豚・夜間発情の見落とし防止","kanten":"静かな母豚は外見・行動も合わせて見て、夜間・早朝発情を見落とさず確認できるか。","levels":["1日1回の確認だけで、夜間・早朝発情や静かな母豚の発情を見落とす。","指示があれば確認するが、静かな母豚や時間帯による見落としが多い。","指示があれば静かな母豚も外見・行動を合わせてひと通り確認できる。","指示がなくても確認回数を工夫し、静かな母豚も排尿等の行動から発情を捉える。","夜間発情や微弱発情の見落としリスクを理解し、確認のタイミングを新人に指導できる。"],"name_en":"Avoiding missed quiet sows and night-time heats","kanten_en":"Can they assess quiet sows by appearance and behavior as well, and check without missing night-time or early-morning heats?","levels_en":["Checks only once a day and misses night or early-morning heats and the heats of quiet sows.","With guidance, checks, but often misses quiet sows and heats at certain times of day.","With guidance, can adequately check quiet sows using appearance and behavior together.","Independently varies the number and timing of checks, and detects heat in quiet sows from behaviors such as urination.","Understands the risk of missing night-time and weak heats, and can teach new staff the timing of checks."],"name_vi":"Phòng bỏ sót lợn nái động dục thầm lặng và động dục ban đêm","kanten_vi":"Với lợn nái động dục thầm lặng có nhìn thêm cả bề ngoài và hành vi, không bỏ sót động dục ban đêm và sáng sớm không.","levels_vi":["Chỉ kiểm tra 1 lần mỗi ngày, bỏ sót động dục ban đêm, sáng sớm và động dục của lợn nái thầm lặng.","Nếu có chỉ dẫn thì kiểm tra, nhưng hay bỏ sót lợn nái thầm lặng và tùy theo giờ giấc.","Nếu có chỉ dẫn thì kiểm tra được cơ bản cả lợn nái thầm lặng bằng cách nhìn thêm bề ngoài và hành vi.","Không cần chỉ dẫn cũng thay đổi số lần kiểm tra, nhận ra động dục của lợn nái thầm lặng qua hành vi như đi tiểu.","Hiểu nguy cơ bỏ sót động dục ban đêm và động dục yếu, và có thể hướng dẫn người mới thời điểm kiểm tra."],"name_id":"Mencegah terlewatnya induk pendiam dan birahi malam hari","kanten_id":"Apakah induk babi yang pendiam diperiksa juga dari penampilan dan perilakunya, dan birahi malam serta pagi buta tidak terlewat.","levels_id":["Hanya memeriksa sekali sehari, sehingga melewatkan birahi malam dan pagi buta serta birahi induk babi yang pendiam.","Jika ada instruksi bisa memeriksa, tetapi sering melewatkan induk yang pendiam atau karena jam pemeriksaan.","Jika ada instruksi, bisa memeriksa induk yang pendiam juga secara garis besar dengan melihat penampilan dan perilakunya.","Tanpa instruksi pun, mengatur frekuensi pemeriksaan, dan menangkap birahi induk yang pendiam dari perilaku seperti buang air kecil.","Memahami risiko terlewatnya birahi malam hari dan birahi yang lemah, dan bisa mengajari karyawan baru waktu-waktu pemeriksaan."]},{"id":"time-record-report","name":"時刻の即時記録と未発情の報告","kanten":"許容確認した時刻をその場で記録・マーキングし、判定に迷う母豚と離乳後8日以上未発情の母豚を報告できるか。","levels":["時刻を記録せずマーキングもせず、発情が来ない母豚も報告せず放置する。","指示されれば記録するが、あとでまとめて書いて時刻が曖昧になり、報告漏れも多い。","指示があればその場で個体番号・日付・時刻を記録し、迷った母豚を報告できる。","指示がなくても許容ごとに即時記録・マーキングし、8日以上未発情の母豚をリスト化して報告する。","時刻がAIタイミングの基準になることを理解し、記録と報告の型を新人に指導できる。"],"name_en":"Immediate time recording and reporting sows not in heat","kanten_en":"Can they record and mark the time of the standing heat check on the spot, and report sows they are unsure about and sows not in heat 8 or more days after weaning?","levels_en":["Records no times, does no marking, and leaves sows that do not come into heat unreported.","With guidance, records, but writes it all up later so times become vague, and often fails to report.","With guidance, records the ID number, date, and time on the spot and can report sows they were unsure about.","Independently records and marks each standing heat immediately, and lists and reports sows not in heat for 8 or more days.","Understands that the time becomes the basis for AI timing, and can teach new staff the routine of recording and reporting."],"name_vi":"Ghi giờ ngay tại chỗ và báo cáo nái chưa động dục","kanten_vi":"Có ghi và đánh dấu ngay tại chỗ giờ kiểm tra phản xạ đứng yên, báo cáo nái khó phán đoán và nái quá 8 ngày sau cai sữa chưa động dục không.","levels_vi":["Không ghi giờ, không đánh dấu, nái không động dục cũng không báo cáo mà bỏ mặc.","Nếu có chỉ dẫn thì ghi, nhưng để sau mới ghi gộp nên giờ giấc mơ hồ, cũng hay quên báo cáo.","Nếu có chỉ dẫn thì ghi ngay tại chỗ số hiệu cá thể, ngày, giờ và báo cáo được nái khó phán đoán.","Không cần chỉ dẫn cũng ghi và đánh dấu ngay từng lần chịu đực, lập danh sách nái quá 8 ngày chưa động dục để báo cáo.","Hiểu giờ ghi được là căn cứ cho thời điểm AI, và có thể hướng dẫn người mới nề nếp ghi chép và báo cáo."],"name_id":"Mencatat waktu langsung di tempat dan melaporkan induk yang belum birahi","kanten_id":"Apakah mencatat dan menandai langsung di tempat waktu pemeriksaan refleks diam, serta melaporkan induk yang sulit dinilai dan induk yang belum birahi lebih dari 8 hari setelah sapih.","levels_id":["Tidak mencatat waktu, tidak menandai, dan induk yang tidak birahi pun dibiarkan tanpa dilaporkan.","Jika ada instruksi bisa mencatat, tetapi menulisnya belakangan sekaligus sehingga waktunya samar, dan sering lupa melapor.","Jika ada instruksi, bisa mencatat nomor individu, tanggal, dan waktu langsung di tempat, serta melaporkan induk yang sulit dinilai.","Tanpa instruksi pun, mencatat dan menandai langsung setiap refleks diam, dan membuat daftar induk yang belum birahi lebih dari 8 hari untuk dilaporkan.","Memahami bahwa waktu itu menjadi patokan saat AI, dan bisa mengajari karyawan baru pola pencatatan dan pelaporan."]}],"name_en":"Standing heat check","purposeShort_en":"Identify the optimal timing for breeding and raise conception rate and litter size","name_vi":"Kiểm tra phản xạ đứng yên khi động dục","purposeShort_vi":"Nhìn ra thời điểm tốt nhất để phối giống, nâng tỷ lệ thụ thai và số con đẻ ra","name_id":"Pemeriksaan refleks diam saat birahi","purposeShort_id":"Menentukan waktu terbaik untuk perkawinan, menaikkan angka kebuntingan dan jumlah anak"},{"id":"semen-check","category":"breeding","no":"No.03","name":"精液検査・反転","purposeShort":"問題のある精液を使用前に除外し、繁殖成績の低下を防ぐ","gyomu":"03","aspects":[{"id":"temp-control","name":"17℃保管と温度変化の抑制","kanten":"精液を17℃前後で保管し、検査前の温度を均一にして温度変化を最小限にできるか。","levels":["保管温度を気にせず、検査前の温度も不均一なまま評価して誤判定する。","指示があれば温度を確認するが、変化の抑制や均一化に漏れがある。","指示があれば17℃前後で保管し、ひと通り温度に配慮できる。","指示がなくても温度変化を最小限に抑え、検査前に温度を均一にする。","温度が精子品質に与える影響を理解し、保管・検査時の温度管理を新人に指導できる。"],"name_en":"Storage at 17°C and minimizing temperature changes","kanten_en":"Can they store semen at around 17°C and equalize its temperature before testing, keeping temperature changes to a minimum?","levels_en":["Pays no attention to storage temperature and evaluates semen at uneven temperatures, causing misjudgment.","With guidance, checks the temperature, but is inconsistent about limiting changes and equalizing it.","With guidance, stores semen at around 17°C and can pay adequate attention to temperature.","Independently keeps temperature changes to a minimum and equalizes the temperature before testing.","Understands how temperature affects sperm quality, and can teach new staff temperature control during storage and testing."],"name_vi":"Bảo quản 17℃ và hạn chế thay đổi nhiệt độ","kanten_vi":"Có bảo quản tinh dịch quanh 17℃, làm đều nhiệt độ trước khi kiểm tra và giữ thay đổi nhiệt độ ở mức nhỏ nhất không.","levels_vi":["Không quan tâm nhiệt độ bảo quản, đánh giá khi nhiệt độ trước kiểm tra chưa đều nên phán đoán sai.","Nếu có chỉ dẫn thì kiểm tra nhiệt độ, nhưng có bỏ sót việc hạn chế thay đổi và làm đều nhiệt độ.","Nếu có chỉ dẫn thì bảo quản quanh 17℃, chú ý được cơ bản đến nhiệt độ.","Không cần chỉ dẫn cũng giữ thay đổi nhiệt độ ở mức nhỏ nhất, làm đều nhiệt độ trước khi kiểm tra.","Hiểu nhiệt độ ảnh hưởng đến chất lượng tinh trùng, và có thể hướng dẫn người mới cách quản lý nhiệt độ khi bảo quản và kiểm tra."],"name_id":"Penyimpanan 17°C dan menekan perubahan suhu","kanten_id":"Apakah menyimpan semen sekitar 17°C, menyeragamkan suhu sebelum pemeriksaan, dan menekan perubahan suhu seminimal mungkin.","levels_id":["Tidak peduli suhu penyimpanan, mengevaluasi dengan suhu sebelum pemeriksaan yang tidak seragam sehingga salah menilai.","Jika ada instruksi bisa memeriksa suhu, tetapi sering lalai menekan perubahan dan menyeragamkan suhu.","Jika ada instruksi, bisa menyimpan sekitar 17°C dan cukup memperhatikan suhu.","Tanpa instruksi pun, menekan perubahan suhu seminimal mungkin, dan menyeragamkan suhu sebelum pemeriksaan.","Memahami pengaruh suhu terhadap kualitas sperma, dan bisa mengajari karyawan baru pengelolaan suhu saat penyimpanan dan pemeriksaan."]},{"id":"activity-mix","name":"精子活力確認と穏やかな反転","kanten":"顕微鏡で精子活力を確認し、反転を穏やかに行って精子へのダメージを防げるか。","levels":["活力確認を省き、新鮮精液を激しく振盪して精子を傷める。","指示があれば確認するが、反転の強さやタイミングに漏れがある。","指示があれば顕微鏡で活力を確認し、ひと通り穏やかに反転できる。","指示がなくても活力を確認し、反転を穏やかに行ってダメージを防ぐ。","精子活力と反転操作の関係を理解し、検査と反転の手技を新人に指導できる。"],"name_en":"Checking sperm motility and gentle inversion","kanten_en":"Can they check sperm motility under a microscope and invert the container gently to prevent sperm damage?","levels_en":["Skips the motility check and shakes fresh semen violently, damaging the sperm.","With guidance, checks motility, but is inconsistent about the force and timing of inversion.","With guidance, checks motility under the microscope and can adequately invert the container gently.","Independently checks motility and inverts gently to prevent damage.","Understands the relationship between sperm motility and the inversion procedure, and can teach new staff the testing and inversion techniques."],"name_vi":"Kiểm tra hoạt lực tinh trùng và đảo chai nhẹ nhàng","kanten_vi":"Có kiểm tra hoạt lực tinh trùng bằng kính hiển vi, đảo chai nhẹ nhàng để tránh làm tổn thương tinh trùng không.","levels_vi":["Bỏ qua kiểm tra hoạt lực, lắc mạnh tinh dịch tươi làm tổn thương tinh trùng.","Nếu có chỉ dẫn thì kiểm tra, nhưng có bỏ sót về độ mạnh và thời điểm đảo chai.","Nếu có chỉ dẫn thì kiểm tra hoạt lực bằng kính hiển vi, đảo chai được cơ bản một cách nhẹ nhàng.","Không cần chỉ dẫn cũng kiểm tra hoạt lực, đảo chai nhẹ nhàng để tránh tổn thương.","Hiểu quan hệ giữa hoạt lực tinh trùng và thao tác đảo chai, và có thể hướng dẫn người mới kỹ thuật kiểm tra và đảo chai."],"name_id":"Pemeriksaan motilitas sperma dan membalik botol dengan lembut","kanten_id":"Apakah memeriksa motilitas (gerak) sperma dengan mikroskop, dan membalik botol dengan lembut untuk mencegah kerusakan sperma.","levels_id":["Melewatkan pemeriksaan motilitas, dan mengguncang semen segar dengan keras sehingga merusak sperma.","Jika ada instruksi bisa memeriksa, tetapi sering lalai soal kekuatan dan waktu membalik botol.","Jika ada instruksi, bisa memeriksa motilitas dengan mikroskop dan membalik botol secara garis besar dengan lembut.","Tanpa instruksi pun, memeriksa motilitas dan membalik botol dengan lembut sehingga mencegah kerusakan.","Memahami hubungan motilitas sperma dengan cara membalik botol, dan bisa mengajari karyawan baru teknik pemeriksaan dan pembalikan."]},{"id":"reject-report","name":"不良精液の除外と報告","kanten":"運動率・凝集・色の異常から使えない精液を見分け、戻さず分けて上長へ報告できるか。","levels":["動きの悪い精液や色のおかしい精液も「もったいない」とそのまま使う。","指示があれば見るが、振動運動や凝集の見分けが曖昧で、報告は他者まかせ。","指示があれば運動率の基準に沿って判定し、問題のあるロットを分けて報告できる。","指示がなくても不良精液をインキュベーターに戻さず分け、すぐ上長に報告して使用を止める。","受胎しない損が精液1本より大きいことを理解し、判定基準と除外・報告の判断を新人に指導できる。"],"name_en":"Excluding bad semen and reporting","kanten_en":"Can they identify unusable semen from motility rate, clumping, and abnormal color, set it aside without returning it, and report to the supervisor?","levels_en":["Uses semen with poor movement or odd color anyway, thinking it a waste to discard.","With guidance, looks, but is vague about telling vibrating-in-place movement and clumping apart, and leaves reporting to others.","With guidance, judges by the motility standard and can separate problem lots and report them.","Independently keeps bad semen out of the incubator, sets it aside, and reports to the supervisor immediately to stop its use.","Understands that a failed conception costs more than one dose of semen, and can teach new staff the judgment standards and the decisions to exclude and report."],"name_vi":"Loại bỏ tinh dịch kém và báo cáo","kanten_vi":"Có phân biệt tinh dịch không dùng được qua tỷ lệ vận động, vón cục, màu bất thường, tách riêng không cho lại vào và báo cáo cấp trên không.","levels_vi":["Tinh dịch vận động kém hay màu lạ vẫn dùng vì thấy tiếc.","Nếu có chỉ dẫn thì xem, nhưng phân biệt vận động rung tại chỗ và vón cục còn mơ hồ, việc báo cáo thì phó mặc người khác.","Nếu có chỉ dẫn thì phán định theo tiêu chuẩn tỷ lệ vận động, tách riêng lô có vấn đề và báo cáo được.","Không cần chỉ dẫn cũng không cho tinh dịch kém lại vào incubator, tách riêng và báo ngay cấp trên để ngừng sử dụng.","Hiểu thiệt hại khi không thụ thai lớn hơn một liều tinh, và có thể hướng dẫn người mới tiêu chuẩn phán định và cách quyết định loại bỏ, báo cáo."],"name_id":"Menyingkirkan semen jelek dan melapor","kanten_id":"Apakah bisa membedakan semen yang tidak bisa dipakai dari daya gerak, gumpalan, dan warna yang tidak normal, memisahkannya tanpa mengembalikan, dan melapor ke atasan.","levels_id":["Semen yang geraknya jelek atau warnanya aneh tetap dipakai karena merasa sayang.","Jika ada instruksi bisa melihat, tetapi samar membedakan gerak bergetar di tempat dan gumpalan, dan pelaporan diserahkan ke orang lain.","Jika ada instruksi, bisa menilai sesuai standar daya gerak, memisahkan lot yang bermasalah, dan melaporkannya.","Tanpa instruksi pun, tidak mengembalikan semen jelek ke inkubator, memisahkannya, dan segera melapor ke atasan untuk menghentikan pemakaiannya.","Memahami bahwa kerugian gagal bunting lebih besar daripada satu dosis semen, dan bisa mengajari karyawan baru standar penilaian serta keputusan menyingkirkan dan melapor."]},{"id":"expiry-fifo","name":"使用期限の管理（先入れ先出し）","kanten":"ラベルの使用期限を確認して期限が近いものを手前に置き、期限切れを絶対に使わず廃棄・記録できるか。","levels":["期限を見ずに使い、期限切れの精液も気づかずに使う。","指示があれば期限を見るが、置き直しや廃棄の記録に抜けが多い。","指示があれば期限を確認し、先入れ先出しでひと通り並べ替えられる。","指示がなくても期限の近いものを手前に置き、期限切れは廃棄して記録に残す。","使用期限と精子品質の関係を理解し、先入れ先出しの管理を新人に指導できる。"],"name_en":"Managing expiration dates (first-in, first-out)","kanten_en":"Can they check the expiration date on the label, place those expiring soon at the front, never use expired semen, and discard and record it?","levels_en":["Uses semen without looking at the dates, and uses expired semen without noticing.","With guidance, looks at the dates, but often misses rearranging and recording disposals.","With guidance, checks the dates and can adequately rearrange on a first-in, first-out basis.","Independently places semen expiring soon at the front, and discards expired semen and leaves a record.","Understands the relationship between expiration dates and sperm quality, and can teach new staff first-in, first-out management."],"name_vi":"Quản lý hạn sử dụng (nhập trước xuất trước)","kanten_vi":"Có kiểm tra hạn sử dụng trên nhãn, đặt loại gần hết hạn ra phía trước, tuyệt đối không dùng loại hết hạn mà hủy bỏ và ghi lại không.","levels_vi":["Không xem hạn mà dùng, loại hết hạn cũng dùng mà không nhận ra.","Nếu có chỉ dẫn thì xem hạn, nhưng hay bỏ sót việc xếp lại và ghi chép hủy bỏ.","Nếu có chỉ dẫn thì kiểm tra hạn, xếp lại được cơ bản theo nhập trước xuất trước.","Không cần chỉ dẫn cũng đặt loại gần hết hạn ra phía trước, hủy bỏ loại hết hạn và ghi lại.","Hiểu quan hệ giữa hạn sử dụng và chất lượng tinh trùng, và có thể hướng dẫn người mới cách quản lý nhập trước xuất trước."],"name_id":"Pengelolaan tanggal kedaluwarsa (masuk dulu keluar dulu)","kanten_id":"Apakah memeriksa tanggal kedaluwarsa pada label, meletakkan yang hampir habis masa pakainya di depan, sama sekali tidak memakai yang kedaluwarsa, serta membuang dan mencatatnya.","levels_id":["Memakai tanpa melihat tanggal, dan memakai semen kedaluwarsa tanpa sadar.","Jika ada instruksi bisa melihat tanggal, tetapi sering lalai menata ulang dan mencatat pembuangan.","Jika ada instruksi, bisa memeriksa tanggal dan menata ulang secara garis besar dengan cara masuk dulu keluar dulu.","Tanpa instruksi pun, meletakkan yang hampir kedaluwarsa di depan, membuang yang kedaluwarsa, dan meninggalkan catatan.","Memahami hubungan tanggal kedaluwarsa dengan kualitas sperma, dan bisa mengajari karyawan baru pengelolaan masuk dulu keluar dulu."]},{"id":"record-equip","name":"検査記録と機器の点検","kanten":"温度・ロット別の検査結果を毎回記録し、レンズ清掃・扉閉め・電源プラグの確認まで行えるか。","levels":["温度も検査結果も記録せず、扉の閉め忘れやプラグ抜けにも気づかない。","指示されれば記録するが、ロット番号や判定の記載漏れが多く、片付けも不十分。","指示があれば温度と検査結果をロットごとに記録し、レンズ清掃・扉・プラグの確認までできる。","指示がなくても毎朝の温度記録と検査記録を続け、「昨日より悪い」変化に気づいて相談する。","プラグ抜け等が精液全損につながることを理解し、記録と機器点検の習慣を新人に指導できる。"],"name_en":"Test records and equipment checks","kanten_en":"Can they record the temperature and per-lot test results every time, and go as far as cleaning the lens, closing the door, and checking the power plug?","levels_en":["Records neither temperature nor test results, and does not notice the door left open or the plug pulled out.","With guidance, records, but often omits lot numbers and judgments, and tidying up is incomplete.","With guidance, records temperature and test results per lot, and can check the lens cleaning, the door, and the plug.","Independently keeps up the daily morning temperature and test records, notices changes such as 'worse than yesterday', and consults.","Understands that a pulled plug can mean total loss of the semen, and can teach new staff the habit of recording and equipment checks."],"name_vi":"Ghi chép kiểm tra và kiểm tra máy móc","kanten_vi":"Có ghi mỗi lần kết quả kiểm tra theo nhiệt độ và từng lô, làm đến cả vệ sinh ống kính, đóng cửa, kiểm tra phích cắm điện không.","levels_vi":["Không ghi nhiệt độ lẫn kết quả kiểm tra, cửa quên đóng hay phích cắm tuột cũng không nhận ra.","Nếu có chỉ dẫn thì ghi, nhưng hay ghi sót số lô và kết luận, dọn dẹp cũng chưa đủ.","Nếu có chỉ dẫn thì ghi nhiệt độ và kết quả theo từng lô, làm được đến vệ sinh ống kính, kiểm tra cửa và phích cắm.","Không cần chỉ dẫn cũng duy trì ghi nhiệt độ mỗi sáng và ghi kết quả kiểm tra, nhận ra thay đổi như 'kém hơn hôm qua' và trao đổi.","Hiểu tuột phích cắm v.v. có thể làm hỏng toàn bộ tinh dịch, và có thể hướng dẫn người mới thói quen ghi chép và kiểm tra máy móc."],"name_id":"Catatan pemeriksaan dan pengecekan alat","kanten_id":"Apakah setiap kali mencatat suhu dan hasil pemeriksaan per lot, serta sampai membersihkan lensa, menutup pintu, dan memeriksa steker listrik.","levels_id":["Tidak mencatat suhu maupun hasil pemeriksaan, dan tidak sadar pintu lupa ditutup atau steker terlepas.","Jika ada instruksi bisa mencatat, tetapi nomor lot dan keputusan sering tidak ditulis, dan beres-beresnya kurang.","Jika ada instruksi, bisa mencatat suhu dan hasil pemeriksaan per lot, serta memeriksa sampai kebersihan lensa, pintu, dan steker.","Tanpa instruksi pun, terus mencatat suhu tiap pagi dan hasil pemeriksaan, menyadari perubahan seperti 'lebih jelek dari kemarin' dan berkonsultasi.","Memahami bahwa steker terlepas dan sejenisnya bisa merusak seluruh semen, dan bisa mengajari karyawan baru kebiasaan mencatat dan mengecek alat."]}],"name_en":"Semen check and inversion","purposeShort_en":"Exclude problem semen before use and prevent declines in reproductive performance","name_vi":"Kiểm tra tinh dịch và đảo chai tinh","purposeShort_vi":"Loại bỏ tinh dịch có vấn đề trước khi dùng, ngăn thành tích sinh sản giảm sút","name_id":"Pemeriksaan semen dan membalik botol semen","purposeShort_id":"Menyingkirkan semen yang bermasalah sebelum dipakai, mencegah turunnya hasil reproduksi"},{"id":"semen-mix","category":"breeding","no":"No.17","name":"精液攪拌","purposeShort":"精子濃度を均一化する","gyomu":"17","aspects":[{"id":"temp-check","name":"保管温度の確認と逸脱時の対応","kanten":"攪拌前にインキュベーターが17℃前後にあるか確認・記録し、範囲を外れていたら使う前に上長へ報告できるか。","levels":["温度計を見ずに攪拌を始め、温度が外れていても気にせず使わせてしまう。","指示があれば温度を見るが、記録や逸脱時の報告に抜けがある。","指示があれば温度を確認・記録し、範囲外のときは報告してから進められる。","指示がなくても毎回温度を確かめ、逸脱時は精液を使う前に必ず報告して対応につなげる。","温度逸脱が精子に与えるダメージを理解し、確認と報告の判断基準を新人に指導できる。"],"name_en":"Checking storage temperature and responding to deviations","kanten_en":"Can they check and record that the incubator is at around 17°C before mixing, and report to the supervisor before use if it is out of range?","levels_en":["Starts mixing without looking at the thermometer, and lets the semen be used even when the temperature is off.","With guidance, looks at the temperature, but misses recording it and reporting deviations.","With guidance, checks and records the temperature, and can report before proceeding when it is out of range.","Independently checks the temperature every time, and always reports deviations before the semen is used so action can be taken.","Understands the damage temperature deviations do to sperm, and can teach new staff the criteria for checking and reporting."],"name_vi":"Kiểm tra nhiệt độ bảo quản và xử lý khi lệch chuẩn","kanten_vi":"Trước khi lắc có kiểm tra, ghi lại incubator có ở quanh 17℃ không, nếu ra ngoài phạm vi thì báo cấp trên trước khi dùng không.","levels_vi":["Không nhìn nhiệt kế đã bắt đầu lắc, nhiệt độ lệch cũng mặc kệ để dùng.","Nếu có chỉ dẫn thì xem nhiệt độ, nhưng có bỏ sót việc ghi lại và báo cáo khi lệch.","Nếu có chỉ dẫn thì kiểm tra, ghi nhiệt độ, khi ra ngoài phạm vi thì báo cáo rồi mới tiến hành.","Không cần chỉ dẫn cũng kiểm tra nhiệt độ mỗi lần, khi lệch chuẩn nhất định báo cáo trước khi dùng tinh để kịp xử lý.","Hiểu nhiệt độ lệch chuẩn gây hại cho tinh trùng thế nào, và có thể hướng dẫn người mới tiêu chí kiểm tra và báo cáo."],"name_id":"Memeriksa suhu penyimpanan dan menangani penyimpangan","kanten_id":"Apakah sebelum mengaduk memeriksa dan mencatat inkubator berada sekitar 17°C, dan jika keluar dari rentang, melapor ke atasan sebelum dipakai.","levels_id":["Mulai mengaduk tanpa melihat termometer, dan walau suhunya melenceng tetap membiarkannya dipakai.","Jika ada instruksi bisa melihat suhu, tetapi sering lalai mencatat dan melapor saat menyimpang.","Jika ada instruksi, bisa memeriksa dan mencatat suhu, dan saat di luar rentang melapor dulu sebelum melanjutkan.","Tanpa instruksi pun, memeriksa suhu setiap kali, dan saat menyimpang selalu melapor sebelum semen dipakai agar bisa ditangani.","Memahami kerusakan yang ditimbulkan penyimpangan suhu pada sperma, dan bisa mengajari karyawan baru patokan pemeriksaan dan pelaporan."]},{"id":"gentle-mix","name":"穏やかな攪拌と温度・浸透圧の配慮","kanten":"強く振らず穏やかに攪拌し、希釈液との温度差や気泡混入を避けられるか。","levels":["強く振って気泡を混入させ、希釈液との温度差で浸透圧ショックを招く。","指示があれば攪拌するが、強さや温度差への配慮に漏れがある。","指示があれば穏やかにひと通り攪拌できる。","指示がなくても温度差を抑えて穏やかに攪拌し、気泡混入を避ける。","浸透圧ショックや酸化ストレスの仕組みを理解し、攪拌のコツを新人に指導できる。"],"name_en":"Gentle mixing with attention to temperature and osmotic pressure","kanten_en":"Can they mix gently without shaking hard, avoiding temperature differences with the extender and air bubble entrainment?","levels_en":["Shakes hard, entraining air bubbles, and causes osmotic shock through temperature differences with the extender.","With guidance, mixes, but is inconsistent about force and attention to temperature differences.","With guidance, can adequately mix gently.","Independently limits temperature differences, mixes gently, and avoids entraining air bubbles.","Understands the mechanisms of osmotic shock and oxidative stress, and can teach new staff the knack of mixing."],"name_vi":"Lắc nhẹ nhàng và chú ý nhiệt độ, áp suất thẩm thấu","kanten_vi":"Có lắc nhẹ nhàng, không lắc mạnh, tránh chênh lệch nhiệt độ với dung dịch pha loãng và tránh lẫn bọt khí không.","levels_vi":["Lắc mạnh làm lẫn bọt khí, chênh lệch nhiệt độ với dung dịch pha loãng gây sốc thẩm thấu.","Nếu có chỉ dẫn thì lắc, nhưng có bỏ sót về độ mạnh và chú ý đến chênh lệch nhiệt độ.","Nếu có chỉ dẫn thì lắc được cơ bản một cách nhẹ nhàng.","Không cần chỉ dẫn cũng giữ chênh lệch nhiệt độ nhỏ, lắc nhẹ nhàng và tránh lẫn bọt khí.","Hiểu cơ chế sốc thẩm thấu và stress oxy hóa, và có thể hướng dẫn người mới mẹo lắc đều."],"name_id":"Pengadukan lembut dan perhatian pada suhu serta tekanan osmotik","kanten_id":"Apakah mengaduk dengan lembut tanpa mengocok keras, dan menghindari perbedaan suhu dengan cairan pengencer serta masuknya gelembung udara.","levels_id":["Mengocok keras sehingga gelembung udara masuk, dan perbedaan suhu dengan cairan pengencer menyebabkan syok tekanan osmotik.","Jika ada instruksi bisa mengaduk, tetapi sering lalai memperhatikan kekuatan dan perbedaan suhu.","Jika ada instruksi, bisa mengaduk secara garis besar dengan lembut.","Tanpa instruksi pun, menekan perbedaan suhu, mengaduk dengan lembut, dan menghindari masuknya gelembung udara.","Memahami mekanisme syok tekanan osmotik dan stres oksidatif, dan bisa mengajari karyawan baru trik pengadukan."]},{"id":"visual-inspect","name":"沈殿・結露・色の点検","kanten":"攪拌時に底の沈み・固まりが消えたか、結露や色の変化がないかを目で確かめ、異常ロットを報告できるか。","levels":["ひっくり返すだけで底や色を見ず、大きな固まりのあるロットも気づかず戻す。","指示があれば見るが、結露や色の変化の意味が分からず見過ごしが多い。","指示があれば沈殿・結露・色をひと通り点検し、気づいたことを伝えられる。","指示がなくても毎回点検し、大きな固まりや色の変化があるロットは使わずに報告する。","結露＝温度差・色の変化＝品質低下のサインであることを理解し、点検の着眼点を新人に指導できる。"],"name_en":"Inspecting sediment, condensation, and color","kanten_en":"Can they visually confirm during mixing that the sediment and clumps at the bottom have disappeared and that there is no condensation or color change, and report abnormal lots?","levels_en":["Just turns the bottle over without looking at the bottom or the color, and returns lots with large clumps without noticing.","With guidance, looks, but does not understand what condensation and color changes mean and often overlooks them.","With guidance, can adequately inspect sediment, condensation, and color, and pass on what they notice.","Independently inspects every time, and does not use lots with large clumps or color changes but reports them.","Understands that condensation signals a temperature difference and color change signals quality loss, and can teach new staff the inspection points."],"name_vi":"Kiểm tra cặn lắng, đọng sương và màu sắc","kanten_vi":"Khi lắc có nhìn xem cặn, cục ở đáy đã tan chưa, có đọng sương hay đổi màu không, và báo cáo lô bất thường không.","levels_vi":["Chỉ lật chai mà không nhìn đáy và màu, lô có cục lớn cũng không nhận ra mà cho lại vào.","Nếu có chỉ dẫn thì nhìn, nhưng không hiểu ý nghĩa của đọng sương và đổi màu nên hay bỏ qua.","Nếu có chỉ dẫn thì kiểm tra được cơ bản cặn lắng, đọng sương, màu sắc và truyền đạt điều nhận thấy.","Không cần chỉ dẫn cũng kiểm tra mỗi lần, lô có cục lớn hay đổi màu thì không dùng mà báo cáo.","Hiểu đọng sương = chênh lệch nhiệt độ, đổi màu = dấu hiệu giảm chất lượng, và có thể hướng dẫn người mới điểm cần nhìn khi kiểm tra."],"name_id":"Memeriksa endapan, embun, dan warna","kanten_id":"Apakah saat mengaduk melihat dengan mata bahwa endapan dan gumpalan di dasar sudah hilang, tidak ada embun atau perubahan warna, dan melaporkan lot yang tidak normal.","levels_id":["Hanya membalik botol tanpa melihat dasar dan warna, lot dengan gumpalan besar pun dikembalikan tanpa disadari.","Jika ada instruksi bisa melihat, tetapi tidak paham arti embun dan perubahan warna sehingga sering terlewat.","Jika ada instruksi, bisa memeriksa endapan, embun, dan warna secara garis besar, serta menyampaikan yang disadari.","Tanpa instruksi pun, memeriksa setiap kali, dan lot dengan gumpalan besar atau perubahan warna tidak dipakai melainkan dilaporkan.","Memahami embun = tanda beda suhu dan perubahan warna = tanda penurunan kualitas, dan bisa mengajari karyawan baru titik perhatian pemeriksaan."]},{"id":"light-shield","name":"遮光の徹底","kanten":"インキュベーターを直射日光の当たる場所に置かず、攪拌のときも精液を強い光に当てないようにできるか。","levels":["直射日光の当たる場所で作業し、精液を光にさらしたまま精子を傷める。","指示があれば光を避けるが、置き場所や扱いの徹底に漏れがある。","指示があれば直射日光を避け、ひと通り光に当てずに扱える。","指示がなくても置き場所と扱いの両方で強い光を避け、光線ダメージを防ぐ。","強い光が精子を弱らせることを理解し、遮光管理を新人に指導できる。"],"name_en":"Thorough light shielding","kanten_en":"Can they keep the incubator out of direct sunlight, and avoid exposing the semen to strong light during mixing as well?","levels_en":["Works in direct sunlight and leaves the semen exposed to light, damaging the sperm.","With guidance, avoids light, but is not thorough about placement and handling.","With guidance, avoids direct sunlight and can adequately handle the semen without exposing it to light.","Independently avoids strong light in both placement and handling, preventing light damage.","Understands that strong light weakens sperm, and can teach new staff light-shielding management."],"name_vi":"Che sáng kỹ càng","kanten_vi":"Có không đặt incubator ở nơi có nắng chiếu trực tiếp, khi lắc cũng không để tinh dịch tiếp xúc ánh sáng mạnh không.","levels_vi":["Làm việc ở nơi nắng chiếu trực tiếp, để tinh dịch phơi ra ánh sáng làm tổn thương tinh trùng.","Nếu có chỉ dẫn thì tránh ánh sáng, nhưng chưa triệt để về chỗ đặt và cách xử lý.","Nếu có chỉ dẫn thì tránh nắng trực tiếp, xử lý được cơ bản mà không để tinh dịch ra ánh sáng.","Không cần chỉ dẫn cũng tránh ánh sáng mạnh cả về chỗ đặt lẫn cách xử lý, phòng tổn thương do ánh sáng.","Hiểu ánh sáng mạnh làm tinh trùng yếu đi, và có thể hướng dẫn người mới cách quản lý che sáng."],"name_id":"Menjalankan pelindungan dari cahaya","kanten_id":"Apakah tidak meletakkan inkubator di tempat yang terkena sinar matahari langsung, dan saat mengaduk pun tidak membiarkan semen terkena cahaya kuat.","levels_id":["Bekerja di tempat yang terkena sinar matahari langsung dan membiarkan semen terpapar cahaya sehingga sperma rusak.","Jika ada instruksi bisa menghindari cahaya, tetapi belum menyeluruh soal tempat meletakkan dan cara menangani.","Jika ada instruksi, bisa menghindari sinar matahari langsung dan menangani semen secara garis besar tanpa terkena cahaya.","Tanpa instruksi pun, menghindari cahaya kuat baik dalam penempatan maupun penanganan, sehingga mencegah kerusakan karena cahaya.","Memahami bahwa cahaya kuat melemahkan sperma, dan bisa mengajari karyawan baru pengelolaan pelindungan dari cahaya."]},{"id":"fifo-record","name":"短時間の取り扱いと先入れ先出し・記録","kanten":"外に出す時間を1〜2分以内にし、期限の近いものを手前に置き直し、攪拌と温度を記録できるか。","levels":["外に出したまま長く握り、期限も並び順も気にせず、記録も残さない。","指示があれば戻すが、出す時間が長引きがちで、置き直しや記録に抜けが多い。","指示があれば1〜2分以内に戻し、先入れ先出しの置き直しと記録までできる。","指示がなくても素手で長く握らず短時間で戻し、期限順に整えて攪拌・温度を毎回記録する。","手の体温と時間経過が精子を弱らせることを理解し、扱いの型と記録を新人に指導できる。"],"name_en":"Short handling time, first-in first-out, and records","kanten_en":"Can they keep the time out of the incubator to 1-2 minutes, put those expiring soon back at the front, and record the mixing and temperature?","levels_en":["Holds the bottle outside for a long time, ignores dates and order, and leaves no records.","With guidance, puts it back, but tends to keep it out too long and often misses rearranging and recording.","With guidance, returns it within 1-2 minutes and can do the first-in, first-out rearranging and the records.","Independently avoids holding it long with bare hands, returns it quickly, arranges by date order, and records mixing and temperature every time.","Understands that hand warmth and elapsed time weaken sperm, and can teach new staff the handling routine and records."],"name_vi":"Thao tác trong thời gian ngắn, nhập trước xuất trước và ghi chép","kanten_vi":"Có giữ thời gian để bên ngoài trong vòng 1〜2 phút, xếp lại loại gần hết hạn ra phía trước, ghi lại việc lắc và nhiệt độ không.","levels_vi":["Cầm bên ngoài lâu, không quan tâm hạn và thứ tự, cũng không ghi chép.","Nếu có chỉ dẫn thì cho lại vào, nhưng hay để bên ngoài lâu, hay bỏ sót việc xếp lại và ghi chép.","Nếu có chỉ dẫn thì cho lại vào trong vòng 1〜2 phút, làm được cả xếp lại nhập trước xuất trước và ghi chép.","Không cần chỉ dẫn cũng không cầm lâu bằng tay trần, trả lại nhanh, xếp theo thứ tự hạn và ghi việc lắc, nhiệt độ mỗi lần.","Hiểu thân nhiệt bàn tay và thời gian trôi qua làm tinh trùng yếu đi, và có thể hướng dẫn người mới nề nếp thao tác và ghi chép."],"name_id":"Penanganan singkat, masuk dulu keluar dulu, dan pencatatan","kanten_id":"Apakah menjaga waktu di luar dalam 1〜2 menit, menata kembali yang hampir kedaluwarsa ke depan, dan mencatat pengadukan serta suhu.","levels_id":["Menggenggam di luar lama, tidak peduli tanggal dan urutan, dan tidak meninggalkan catatan.","Jika ada instruksi bisa mengembalikan, tetapi cenderung terlalu lama di luar, dan sering lalai menata ulang dan mencatat.","Jika ada instruksi, bisa mengembalikan dalam 1〜2 menit, serta melakukan penataan masuk dulu keluar dulu dan pencatatan.","Tanpa instruksi pun, tidak menggenggam lama dengan tangan kosong, cepat mengembalikan, menata sesuai urutan tanggal, dan mencatat pengadukan serta suhu setiap kali.","Memahami bahwa panas tangan dan berjalannya waktu melemahkan sperma, dan bisa mengajari karyawan baru pola penanganan dan pencatatan."]}],"name_en":"Semen mixing","purposeShort_en":"Even out the sperm concentration","name_vi":"Lắc đều tinh dịch (lắc nhẹ)","purposeShort_vi":"Làm đều nồng độ tinh trùng","name_id":"Mengaduk semen (kocok pelan)","purposeShort_id":"Menyeragamkan konsentrasi sperma"},{"id":"preg-check","category":"breeding","no":"No.09","name":"妊娠鑑定","purposeShort":"分娩・離乳頭数を計画通り確保し、空胎母豚を早く見つけて対応する","gyomu":"09","aspects":[{"id":"timing-recheck","name":"鑑定時期の厳守と再確認","kanten":"交配後21〜28日に鑑定し、1回で判断せず35日頃の第2回エコーで必ず再確認できるか。","levels":["1回の確認だけで妊娠を確定し、胚が吸収されて消えた空胎を見落とす。","指示があれば鑑定するが、時期の厳守や再確認に漏れが多い。","指示があれば決められた時期に鑑定し、ひと通り実施できる。","指示がなくても21〜28日に鑑定し、35日頃の再確認を省略しない。","早すぎると妊娠嚢が見えないことや陽性後の胚吸収を理解し、鑑定時期と再確認の重要性を新人に指導できる。"],"name_en":"Strict Timing and Recheck","kanten_en":"Can they check at 21-28 days after mating, and always reconfirm with a second ultrasound around day 35 instead of deciding from a single check?","levels_en":["Confirms pregnancy from a single check and misses open sows whose embryos were resorbed and disappeared.","With guidance can perform checks, but often misses the required timing or the recheck.","With guidance can check at the designated timing and complete the basic procedure.","Independently checks at 21-28 days and never skips the reconfirmation around day 35.","Understands that gestational sacs are not visible too early and that embryos can be resorbed after a positive result, and can teach new staff the importance of check timing and rechecking."],"name_vi":"Tuân thủ thời điểm chẩn đoán và kiểm tra lại","kanten_vi":"Có chẩn đoán vào ngày 21-28 sau giao phối, không kết luận chỉ sau 1 lần mà luôn kiểm tra lại bằng siêu âm lần 2 khoảng ngày 35 không.","levels_vi":["Chỉ kiểm tra 1 lần đã kết luận mang thai, bỏ sót nái không mang thai do phôi bị tiêu biến.","Nếu được chỉ thị thì chẩn đoán, nhưng hay thiếu sót về tuân thủ thời điểm và kiểm tra lại.","Nếu được chỉ thị thì chẩn đoán đúng thời điểm quy định và thực hiện được cơ bản.","Dù không có chỉ thị vẫn chẩn đoán vào ngày 21-28 và không bỏ qua việc kiểm tra lại khoảng ngày 35.","Hiểu việc siêu âm quá sớm sẽ không thấy túi thai và phôi có thể tiêu biến sau khi dương tính, và có thể hướng dẫn người mới về tầm quan trọng của thời điểm chẩn đoán và kiểm tra lại."],"name_id":"Menepati waktu pemeriksaan dan pemeriksaan ulang","kanten_id":"Apakah dapat memeriksa pada hari ke-21-28 setelah perkawinan, tidak memutuskan hanya dengan satu kali pemeriksaan, dan selalu memeriksa ulang dengan USG kedua sekitar hari ke-35?","levels_id":["Memastikan kebuntingan hanya dengan satu kali pemeriksaan, sehingga melewatkan induk yang tidak bunting karena embrionya diserap kembali dan hilang.","Memeriksa jika diperintah, tetapi sering lalai menepati waktu dan melakukan pemeriksaan ulang.","Jika diperintah, dapat memeriksa pada waktu yang ditentukan dan melakukannya secara lengkap.","Tanpa diperintah pun, memeriksa pada hari ke-21-28 dan tidak melewatkan pemeriksaan ulang sekitar hari ke-35.","Memahami bahwa kantung janin tidak terlihat jika terlalu awal dan embrio bisa diserap kembali setelah hasil positif, dan dapat mengajarkan pentingnya waktu pemeriksaan dan pemeriksaan ulang kepada karyawan baru."]},{"id":"echo-reading","name":"エコー画像の正しい読み取り","kanten":"膀胱・腸内容物と胎胞を混同せず、エコー画像を正しく読み取れるか。","levels":["膀胱や腸内容物を妊娠と誤読し、判定を誤る。","指示があれば当てるが、画像の読み取りに誤りが多い。","指示があればひと通りエコーを当てて胎胞を確認できる。","指示がなくても膀胱・腸内容物と胎胞を見分けて正しく判定する。","エコー画像の見分け方を理解し、誤読を避ける読み取りを新人に指導できる。"],"name_en":"Correct Reading of Ultrasound Images","kanten_en":"Can they read ultrasound images correctly without confusing the bladder or intestinal contents with gestational sacs?","levels_en":["Misreads the bladder or intestinal contents as pregnancy and makes wrong judgments.","With guidance can apply the probe, but makes frequent errors in reading the images.","With guidance can apply the ultrasound probe and confirm gestational sacs through the basic procedure.","Independently distinguishes the bladder and intestinal contents from gestational sacs and judges correctly.","Understands how to distinguish ultrasound images and can teach new staff how to read them without misinterpretation."],"name_vi":"Đọc đúng hình ảnh siêu âm","kanten_vi":"Có đọc đúng hình ảnh siêu âm, không nhầm bàng quang hoặc chất chứa trong ruột với túi thai không.","levels_vi":["Đọc nhầm bàng quang hoặc chất chứa trong ruột thành mang thai, dẫn đến kết luận sai.","Nếu được chỉ thị thì áp đầu dò siêu âm, nhưng hay đọc sai hình ảnh.","Nếu được chỉ thị thì có thể siêu âm và xác nhận túi thai một cách cơ bản.","Dù không có chỉ thị vẫn phân biệt được bàng quang, chất chứa trong ruột với túi thai và kết luận đúng.","Hiểu cách phân biệt hình ảnh siêu âm, và có thể hướng dẫn người mới cách đọc để tránh đọc sai."],"name_id":"Membaca gambar USG dengan benar","kanten_id":"Apakah dapat membaca gambar USG dengan benar, tanpa mengira kandung kemih atau isi usus sebagai kantung janin?","levels_id":["Salah membaca kandung kemih atau isi usus sebagai kebuntingan, sehingga hasil penilaian keliru.","Menempelkan alat USG jika diperintah, tetapi sering salah membaca gambar.","Jika diperintah, dapat menempelkan alat USG dan memeriksa kantung janin secara lengkap.","Tanpa diperintah pun, dapat membedakan kandung kemih dan isi usus dari kantung janin, lalu menilai dengan benar.","Memahami cara membedakan gambar USG dan dapat mengajarkan cara membaca yang menghindari salah baca kepada karyawan baru."]},{"id":"hold-judgment","name":"迷ったときの保留判断と再検査設定","kanten":"判定に迷ったら無理に決めず保留とし、排尿後の再確認や5〜7日後の再検査日を決めて対応できるか。","levels":["あいまいな画像でも陽性・陰性を確定してしまい、誤判定を招く。","指示があれば保留にするが、排尿させての再確認や再検査日の設定に漏れがある。","指示があれば迷った個体を保留にし、5〜7日後の再検査日を決めて記録できる。","指示がなくても排尿させて当て直し、それでも不明なら保留として再検査日を設定し、2回目も不明なら獣医師に相談する。","保留を恥ずかしがらない判断の価値を理解し、迷ったときの決め方を新人に指導できる。"],"name_en":"Holding Judgment When Unsure and Scheduling Retests","kanten_en":"Can they mark unclear cases as pending instead of forcing a decision, and handle them by rechecking after urination or setting a retest date 5-7 days later?","levels_en":["Declares even ambiguous images positive or negative, causing misdiagnosis.","With guidance can mark cases pending, but misses rechecking after having the sow urinate or setting the retest date.","With guidance can mark unclear animals as pending, and set and record a retest date 5-7 days later.","Independently has the sow urinate and scans again; if still unclear, marks it pending with a retest date, and consults the veterinarian if the second check is also unclear.","Understands the value of not being ashamed to mark a case pending, and can teach new staff how to decide when unsure."],"name_vi":"Tạm hoãn kết luận khi phân vân và đặt lịch kiểm tra lại","kanten_vi":"Khi phân vân có không cố kết luận mà để tạm hoãn, xử lý bằng cách kiểm tra lại sau khi lợn đi tiểu hoặc định ngày kiểm tra lại sau 5-7 ngày không.","levels_vi":["Hình ảnh mơ hồ vẫn kết luận dương tính hay âm tính, gây chẩn đoán sai.","Nếu được chỉ thị thì để tạm hoãn, nhưng còn thiếu sót về việc cho lợn đi tiểu rồi kiểm tra lại và đặt ngày kiểm tra lại.","Nếu được chỉ thị thì để tạm hoãn con phân vân, định ngày kiểm tra lại sau 5-7 ngày và ghi lại.","Dù không có chỉ thị vẫn cho lợn đi tiểu rồi siêu âm lại, nếu vẫn không rõ thì để tạm hoãn và đặt ngày kiểm tra lại, lần 2 vẫn không rõ thì hỏi bác sĩ thú y.","Hiểu giá trị của việc không ngại để tạm hoãn, và có thể hướng dẫn người mới cách quyết định khi phân vân."],"name_id":"Menunda keputusan saat ragu dan menjadwalkan pemeriksaan ulang","kanten_id":"Apakah saat ragu tidak memaksakan keputusan melainkan menandai tunda, lalu menanganinya dengan memeriksa ulang setelah babi kencing atau menetapkan tanggal periksa ulang 5-7 hari kemudian?","levels_id":["Gambar yang samar pun tetap diputuskan positif atau negatif, sehingga terjadi salah diagnosa.","Jika diperintah bisa menandai tunda, tetapi sering lalai memeriksa ulang setelah babi dibuat kencing dan menetapkan tanggal periksa ulang.","Jika diperintah, dapat menandai tunda pada individu yang meragukan, serta menetapkan dan mencatat tanggal periksa ulang 5-7 hari kemudian.","Tanpa diperintah pun, membuat babi kencing lalu memeriksa lagi; jika masih tidak jelas menandai tunda dan menetapkan tanggal periksa ulang, dan jika kali kedua pun tidak jelas berkonsultasi dengan dokter hewan.","Memahami nilai dari tidak malu menandai tunda, dan dapat mengajarkan cara memutuskan saat ragu kepada karyawan baru."]},{"id":"recheck-return","name":"鑑定後の再発情チェック","kanten":"鑑定後も再発情チェックを続け、空胎の長期化を防げるか。","levels":["鑑定後の再発情チェックを中断し、空胎を長期化させる。","指示があれば確認するが、継続に漏れが多い。","指示があれば鑑定後の再発情をひと通り確認できる。","指示がなくても再発情チェックを続け、空胎の母豚を早く見つける。","再発情チェックの意義を理解し、空胎長期化を防ぐ管理を新人に指導できる。"],"name_en":"Return-to-Estrus Checks After Diagnosis","kanten_en":"Can they continue return-to-estrus checks after diagnosis and prevent prolonged open days?","levels_en":["Stops return-to-estrus checks after diagnosis and lets open days drag on.","With guidance can check, but often fails to keep it up.","With guidance can carry out the basic return-to-estrus checks after diagnosis.","Independently continues return-to-estrus checks and finds open sows early.","Understands the purpose of return-to-estrus checks and can teach new staff how to prevent prolonged open days."],"name_vi":"Kiểm tra động dục trở lại sau chẩn đoán","kanten_vi":"Sau khi chẩn đoán có tiếp tục kiểm tra động dục trở lại, tránh để tình trạng không mang thai kéo dài không.","levels_vi":["Ngừng kiểm tra động dục trở lại sau chẩn đoán, để tình trạng không mang thai kéo dài.","Nếu được chỉ thị thì kiểm tra, nhưng hay không duy trì liên tục.","Nếu được chỉ thị thì có thể kiểm tra động dục trở lại sau chẩn đoán một cách cơ bản.","Dù không có chỉ thị vẫn tiếp tục kiểm tra động dục trở lại, phát hiện sớm lợn nái không mang thai.","Hiểu ý nghĩa của việc kiểm tra động dục trở lại, và có thể hướng dẫn người mới cách quản lý để tránh tình trạng không mang thai kéo dài."],"name_id":"Memeriksa birahi kembali setelah diagnosa","kanten_id":"Apakah tetap memeriksa birahi kembali setelah diagnosa, sehingga masa tidak bunting tidak berkepanjangan?","levels_id":["Berhenti memeriksa birahi kembali setelah diagnosa, sehingga masa tidak bunting menjadi berkepanjangan.","Memeriksa jika diperintah, tetapi sering tidak melanjutkannya.","Jika diperintah, dapat memeriksa birahi kembali setelah diagnosa secara lengkap.","Tanpa diperintah pun, terus memeriksa birahi kembali dan cepat menemukan induk babi yang tidak bunting.","Memahami pentingnya pemeriksaan birahi kembali dan dapat mengajarkan cara mencegah masa tidak bunting berkepanjangan kepada karyawan baru."]},{"id":"onsite-record-probe","name":"その場での記録とプローブ消毒","kanten":"結果を1頭ごとにその場でプレート・記録用紙に記入し、プローブを毎回清拭・消毒して片付けられるか。","levels":["「覚えているから後で」と記録を後回しにし、プローブも汚れたまま次に使う。","指示されれば記入・消毒するが、まとめ書きによる間違いや消毒忘れが多い。","指示があれば1頭ごとに結果をその場で記入し、使用後のプローブ清拭・消毒までできる。","指示がなくても即時記入を徹底して陰性・保留には次回検査日を書き、プローブ消毒と機器の片付けを毎回行う。","伝達漏れ・重複検査・病気の持ち運びを防ぐ意味を理解し、即時記録と消毒の型を新人に指導できる。"],"name_en":"On-the-Spot Recording and Probe Disinfection","kanten_en":"Can they write the result for each sow on the plate and record sheet on the spot, and wipe, disinfect, and put away the probe every time?","levels_en":["Puts off recording, thinking they will remember, and uses the probe on the next sow while still dirty.","With guidance can record and disinfect, but batch writing causes mistakes and disinfection is often forgotten.","With guidance can write each sow's result on the spot, and wipe and disinfect the probe after use.","Independently records immediately, writes the next test date for negatives and pending cases, and disinfects the probe and puts the equipment away every time.","Understands that this prevents missed communication, duplicate testing, and carrying disease, and can teach new staff the routine of immediate recording and disinfection."],"name_vi":"Ghi ngay tại chỗ và khử trùng đầu dò","kanten_vi":"Có ghi kết quả từng con ngay tại chỗ vào bảng và giấy ghi chép, mỗi lần đều lau sạch, khử trùng đầu dò rồi dọn dẹp không.","levels_vi":["Nghĩ nhớ được nên để sau mà hoãn ghi chép, đầu dò còn bẩn vẫn dùng cho con tiếp theo.","Nếu được chỉ thị thì ghi và khử trùng, nhưng hay sai do ghi gộp và hay quên khử trùng.","Nếu được chỉ thị thì ghi kết quả từng con ngay tại chỗ, lau sạch và khử trùng đầu dò sau khi dùng.","Dù không có chỉ thị vẫn triệt để ghi ngay, ghi ngày kiểm tra lần sau cho con âm tính và tạm hoãn, mỗi lần đều khử trùng đầu dò và dọn máy.","Hiểu ý nghĩa phòng sót thông tin, kiểm tra trùng lặp và mang mầm bệnh đi, và có thể hướng dẫn người mới nề nếp ghi ngay và khử trùng."],"name_id":"Pencatatan di tempat dan disinfeksi probe","kanten_id":"Apakah menulis hasil setiap ekor langsung di tempat pada papan dan lembar catatan, serta setiap kali mengelap, mendisinfeksi probe dan membereskannya?","levels_id":["Menunda pencatatan dengan alasan masih ingat nanti saja, dan memakai probe yang masih kotor untuk babi berikutnya.","Jika diperintah bisa mencatat dan mendisinfeksi, tetapi sering salah karena menulis sekaligus dan lupa disinfeksi.","Jika diperintah, dapat menulis hasil setiap ekor langsung di tempat, serta mengelap dan mendisinfeksi probe setelah dipakai.","Tanpa diperintah pun, mencatat langsung dengan tertib, menulis tanggal periksa berikutnya untuk yang negatif dan tunda, serta setiap kali mendisinfeksi probe dan membereskan alat.","Memahami arti mencegah informasi terlewat, pemeriksaan ganda, dan terbawanya penyakit, dan dapat mengajarkan pola catat langsung dan disinfeksi kepada karyawan baru."]}],"name_en":"Pregnancy Check","purposeShort_en":"Secure planned farrowing and weaning numbers, and find open sows early to take action","name_vi":"Chẩn đoán mang thai","purposeShort_vi":"Đảm bảo số con đẻ ra và số con cai sữa theo kế hoạch, phát hiện sớm lợn nái không mang thai để xử lý","name_id":"Diagnosa kebuntingan","purposeShort_id":"Memastikan jumlah kelahiran dan penyapihan sesuai rencana, serta cepat menemukan induk babi yang tidak bunting untuk ditangani"},{"id":"pms","category":"breeding","no":"No.08","name":"PMS投与","purposeShort":"発情が弱い・来ない母豚に発情を誘起し、タイミングをそろえる","gyomu":"08","aspects":[{"id":"timing-judge","name":"投与時期と黄体確認","kanten":"基本は離乳翌日に指示された量を投与し、黄体遺残をエコー確認せずに重複投与しないか。","levels":["黄体遺残を確認せず重複投与し、投与時期も守らない。","指示があれば投与するが、時期や黄体確認に漏れがある。","指示があれば決められた時期に用量を守ってひと通り投与できる。","指示がなくても離乳翌日のタイミングを守って投与し、再投与は獣医師の判断を仰いで重複を避ける。","黄体とホルモン誘起の関係を理解し、投与時期と適応の判断を新人に指導できる。"],"name_en":"Administration Timing and Corpus Luteum Check","kanten_en":"Can they administer the instructed dose on the day after weaning as a rule, and never give a duplicate dose without checking for retained corpora lutea by ultrasound?","levels_en":["Doses repeatedly without checking for retained corpora lutea, and ignores the administration timing.","With guidance can administer, but misses the timing or the corpus luteum check.","With guidance can administer the correct dose at the designated timing through the basic procedure.","Independently keeps to the day-after-weaning timing, and asks the veterinarian's judgment for any repeat dose to avoid duplication.","Understands the relationship between corpora lutea and hormonal induction, and can teach new staff how to judge timing and indications."],"name_vi":"Thời điểm tiêm và kiểm tra thể vàng","kanten_vi":"Về cơ bản có tiêm liều được chỉ thị vào ngày hôm sau cai sữa, và không tiêm trùng lặp khi chưa siêu âm kiểm tra thể vàng tồn lưu không.","levels_vi":["Không kiểm tra thể vàng tồn lưu mà tiêm trùng lặp, cũng không giữ đúng thời điểm tiêm.","Nếu được chỉ thị thì tiêm, nhưng còn thiếu sót về thời điểm và kiểm tra thể vàng.","Nếu được chỉ thị thì tiêm đúng thời điểm, đúng liều lượng quy định một cách cơ bản.","Dù không có chỉ thị vẫn giữ đúng thời điểm ngày hôm sau cai sữa để tiêm, việc tiêm lại thì xin ý kiến bác sĩ thú y để tránh trùng lặp.","Hiểu quan hệ giữa thể vàng và kích thích bằng hormone, và có thể hướng dẫn người mới cách phán đoán thời điểm tiêm và đối tượng phù hợp."],"name_id":"Waktu penyuntikan dan pemeriksaan korpus luteum","kanten_id":"Apakah pada dasarnya menyuntikkan dosis yang diinstruksikan pada hari setelah sapih, dan tidak menyuntik ganda tanpa memeriksa sisa korpus luteum dengan USG?","levels_id":["Menyuntik ganda tanpa memeriksa sisa korpus luteum, dan tidak menepati waktu penyuntikan.","Menyuntik jika diperintah, tetapi sering lalai soal waktu dan pemeriksaan korpus luteum.","Jika diperintah, dapat menyuntik pada waktu yang ditentukan dengan dosis yang benar secara lengkap.","Tanpa diperintah pun, menepati waktu penyuntikan pada hari setelah sapih, dan untuk penyuntikan ulang meminta penilaian dokter hewan agar tidak ganda.","Memahami hubungan korpus luteum dengan induksi hormon, dan dapat mengajarkan penilaian waktu dan sasaran penyuntikan kepada karyawan baru."]},{"id":"no-self-judge","name":"自己判断の回避と対象母豚の確認","kanten":"使いすぎず上長・獣医師と相談し、未経産・経産の量の違いに注意し、妊娠の可能性がある母豚を対象から外せるか。","levels":["自己判断で使い、妊娠しているかもしれない母豚にも打って流産の危険を招く。","指示があれば投与するが、相談や対象母豚の確認に漏れがある。","指示があれば上長・獣医師と相談し、対象リストの母豚だけにひと通り投与できる。","指示がなくても使いすぎを避けて相談し、妊娠の可能性がある母豚は対象から外して確かめる。","ホルモン剤の使いすぎが卵巣の機能低下を招くことを理解し、相談と対象確認の要点を新人に指導できる。"],"name_en":"Avoiding Self-Judgment and Confirming Target Sows","kanten_en":"Can they avoid overuse by consulting supervisors and the veterinarian, watch the dose difference between gilts and parous sows, and exclude possibly pregnant sows from the targets?","levels_en":["Uses the drug on their own judgment and injects even possibly pregnant sows, risking abortion.","With guidance can administer, but misses consultations and the target-sow check.","With guidance can consult supervisors and the veterinarian and administer only to the sows on the target list.","Independently avoids overuse by consulting others, and excludes possibly pregnant sows from the targets and verifies them.","Understands that hormone overuse degrades ovarian function, and can teach new staff the key points of consultation and target confirmation."],"name_vi":"Tránh tự ý quyết định và xác nhận lợn nái đối tượng","kanten_vi":"Có tránh lạm dụng, trao đổi với cấp trên và bác sĩ thú y, chú ý sự khác nhau về liều giữa nái chưa đẻ và nái đã đẻ, loại nái có khả năng mang thai khỏi đối tượng không.","levels_vi":["Tự ý sử dụng, tiêm cả nái có thể đang mang thai, gây nguy cơ sảy thai.","Nếu được chỉ thị thì tiêm, nhưng còn thiếu sót về trao đổi và xác nhận nái đối tượng.","Nếu được chỉ thị thì trao đổi với cấp trên, bác sĩ thú y và chỉ tiêm được cơ bản cho nái trong danh sách đối tượng.","Dù không có chỉ thị vẫn tránh lạm dụng, có trao đổi, loại nái có khả năng mang thai khỏi đối tượng và kiểm tra lại.","Hiểu lạm dụng hormone làm suy giảm chức năng buồng trứng, và có thể hướng dẫn người mới các điểm chính về trao đổi và xác nhận đối tượng."],"name_id":"Tidak memutuskan sendiri dan memastikan induk babi sasaran","kanten_id":"Apakah tidak memakai obat berlebihan, berkonsultasi dengan atasan dan dokter hewan, memperhatikan perbedaan dosis babi dara dan induk beranak, serta mengeluarkan induk yang mungkin bunting dari sasaran?","levels_id":["Memakai obat atas keputusan sendiri, menyuntik juga induk yang mungkin sedang bunting, sehingga menimbulkan bahaya keguguran.","Menyuntik jika diperintah, tetapi sering lalai berkonsultasi dan memastikan induk sasaran.","Jika diperintah, dapat berkonsultasi dengan atasan dan dokter hewan, dan menyuntik secara lengkap hanya pada induk dalam daftar sasaran.","Tanpa diperintah pun, menghindari pemakaian berlebihan, berkonsultasi, mengeluarkan induk yang mungkin bunting dari sasaran dan memastikannya.","Memahami bahwa pemakaian hormon berlebihan menurunkan fungsi indung telur, dan dapat mengajarkan pokok konsultasi dan pemastian sasaran kepada karyawan baru."]},{"id":"drug-label-check","name":"薬剤のラベル確認と温度管理","kanten":"冷蔵2〜8℃保管の薬剤を出してラベルの名前・量・期限・保管状態・変色沈殿を確認し、少し室温に戻して使えるか。","levels":["ラベルを見ずに吸い、期限切れや変色した薬でも気づかず使う。","指示があれば確認するが、5つの確認項目に抜けがあり、冷たいまま打って母豚を暴れさせる。","指示があればラベルの確認項目をひと通りチェックし、室温に戻してから使える。","指示がなくても毎回声に出して確認し、異常のある薬は使わずに報告する。","保管温度と薬効の関係を理解し、ラベル確認と温度管理の手順を新人に指導できる。"],"name_en":"Checking the Drug Label and Temperature Control","kanten_en":"Can they take out the drug stored refrigerated at 2-8°C, check the label for name, dose, expiration, storage condition, and discoloration or sediment, and let it warm slightly to room temperature before use?","levels_en":["Draws up the drug without reading the label, and uses expired or discolored drug without noticing.","With guidance can check, but misses some of the five check items and injects the drug cold, making the sow struggle.","With guidance, can check all the label items and warm the drug toward room temperature before use.","Independently reads out the checks aloud every time, and does not use abnormal drug but reports it.","Understands the relationship between storage temperature and drug efficacy, and can teach new staff the label-check and temperature-control procedure."],"name_vi":"Kiểm tra nhãn thuốc và quản lý nhiệt độ","kanten_vi":"Có lấy thuốc bảo quản lạnh 2〜8℃ ra, kiểm tra trên nhãn tên thuốc, liều lượng, hạn dùng, tình trạng bảo quản, biến màu cặn lắng, và để ấm lên chút về nhiệt độ phòng rồi mới dùng không.","levels_vi":["Không nhìn nhãn đã hút thuốc, thuốc hết hạn hay biến màu cũng dùng mà không nhận ra.","Nếu được chỉ thị thì kiểm tra, nhưng bỏ sót trong 5 mục cần kiểm tra, tiêm khi thuốc còn lạnh làm nái giãy giụa.","Nếu được chỉ thị thì kiểm tra được cơ bản các mục trên nhãn, để thuốc về nhiệt độ phòng rồi mới dùng.","Dù không có chỉ thị vẫn đọc to kiểm tra mỗi lần, thuốc bất thường thì không dùng mà báo cáo.","Hiểu quan hệ giữa nhiệt độ bảo quản và hiệu lực thuốc, và có thể hướng dẫn người mới trình tự kiểm tra nhãn và quản lý nhiệt độ."],"name_id":"Memeriksa label obat dan pengelolaan suhu","kanten_id":"Apakah mengeluarkan obat yang disimpan dingin 2〜8℃, memeriksa pada label nama, dosis, tanggal kedaluwarsa, kondisi penyimpanan, perubahan warna dan endapan, lalu membiarkannya sedikit menghangat ke suhu ruang sebelum dipakai?","levels_id":["Menyedot obat tanpa melihat label, dan memakai obat kedaluwarsa atau berubah warna tanpa sadar.","Jika diperintah bisa memeriksa, tetapi ada yang terlewat dari 5 hal pemeriksaan, dan menyuntik obat yang masih dingin sehingga induk meronta.","Jika diperintah, dapat memeriksa butir-butir pada label secara lengkap dan memakai obat setelah kembali ke suhu ruang.","Tanpa diperintah pun, setiap kali memeriksa dengan membacanya bersuara, dan obat yang tidak normal tidak dipakai melainkan dilaporkan.","Memahami hubungan suhu penyimpanan dengan khasiat obat, dan dapat mengajarkan urutan pemeriksaan label dan pengelolaan suhu kepada karyawan baru."]},{"id":"injection-safety","name":"確実な筋肉注射と針の安全管理","kanten":"首の正しい部位に90度で刺し、血の逆流を確認してからゆっくり注入し、針は1頭ごと交換して専用容器に捨てられるか。","levels":["部位を選ばず浅く刺し、逆流確認もせず、使った針にキャップをはめ直して自分を刺しかける。","指示があれば打てるが、消毒・逆流確認・針交換に抜けが多い。","指示があれば首の部位を消毒して90度で刺し、逆流確認と針の専用容器への廃棄までできる。","指示がなくても保定から廃棄まで一連を確実に行い、血が引けたら刺し直して全量を入れる。","首に打つ理由と針刺し事故の危険を理解し、注射手技と針の安全管理を新人に指導できる。"],"name_en":"Reliable Intramuscular Injection and Needle Safety","kanten_en":"Can they insert at 90 degrees into the correct site on the neck, check for blood backflow before injecting slowly, change the needle for every sow, and discard it into the dedicated container?","levels_en":["Sticks the needle in shallow anywhere, skips the backflow check, and recaps used needles, nearly sticking themselves.","With guidance can inject, but often misses disinfection, the backflow check, and needle changes.","With guidance, disinfects the neck site, inserts at 90 degrees, and can do the backflow check and discard needles into the dedicated container.","Independently carries out the whole sequence from restraint to disposal reliably, and re-inserts to deliver the full dose if blood is drawn.","Understands why the neck is used and the danger of needlestick accidents, and can teach new staff injection technique and needle safety."],"name_vi":"Tiêm bắp chắc chắn và quản lý an toàn kim tiêm","kanten_vi":"Có đâm kim góc 90 độ vào đúng vị trí ở cổ, kiểm tra máu trào ngược rồi mới bơm chậm, thay kim mỗi con và bỏ vào hộp chuyên dụng không.","levels_vi":["Đâm nông không chọn vị trí, không kiểm tra trào ngược, còn đậy lại nắp kim đã dùng suýt đâm vào tay mình.","Nếu được chỉ thị thì tiêm được, nhưng hay bỏ sót khử trùng, kiểm tra trào ngược và thay kim.","Nếu được chỉ thị thì khử trùng vị trí ở cổ, đâm góc 90 độ, làm được cả kiểm tra trào ngược và bỏ kim vào hộp chuyên dụng.","Dù không có chỉ thị vẫn làm chắc chắn cả chuỗi từ giữ cố định đến bỏ kim, nếu hút ra máu thì đâm lại chỗ khác và bơm đủ liều.","Hiểu lý do tiêm ở cổ và nguy cơ tai nạn kim đâm, và có thể hướng dẫn người mới kỹ thuật tiêm và quản lý an toàn kim."],"name_id":"Suntikan otot yang pasti dan pengelolaan keamanan jarum","kanten_id":"Apakah menusukkan jarum 90 derajat di tempat yang benar pada leher, memeriksa aliran balik darah sebelum menyuntik perlahan, mengganti jarum tiap ekor, dan membuangnya ke wadah khusus?","levels_id":["Menusuk dangkal tanpa memilih tempat, tidak memeriksa aliran balik, dan memasang kembali tutup jarum bekas sampai hampir menusuk diri sendiri.","Jika diperintah bisa menyuntik, tetapi sering lalai disinfeksi, memeriksa aliran balik, dan mengganti jarum.","Jika diperintah, dapat mendisinfeksi tempat di leher, menusuk 90 derajat, memeriksa aliran balik, dan membuang jarum ke wadah khusus.","Tanpa diperintah pun, melakukan seluruh rangkaian dari memegangi sampai pembuangan dengan pasti, dan jika darah tersedot menusuk ulang lalu memasukkan seluruh dosis.","Memahami alasan menyuntik di leher dan bahaya kecelakaan tertusuk jarum, dan dapat mengajarkan teknik menyuntik dan keamanan jarum kepada karyawan baru."]},{"id":"record-followup","name":"投与記録と発情観察の予定管理","kanten":"投与日・個体番号・量・実施者を記録し、投与後3〜5日の発情観察を続け、7日来なければ獣医師に相談できるか。","levels":["記録を残さず、「打ったから来るだろう」と観察もせず、効かなくても勝手にもう1回打つ。","指示されれば記録するが、観察予定のメモや毎日の雄豚当てに抜けが多い。","指示があれば投与記録と発情確認の予定日を書き、投与後の観察をひと通り続けられる。","指示がなくても毎日観察して発情のサインを捉え、7日過ぎても来ないときは自分で判断せず獣医師相談につなげる。","投与後の観察がチャンスを逃さない鍵であることを理解し、記録と予定管理の型を新人に指導できる。"],"name_en":"Administration Records and Heat-Observation Scheduling","kanten_en":"Can they record the date, ID number, dose, and person, keep observing for heat 3-5 days after administration, and consult the veterinarian if it has not come by day 7?","levels_en":["Leaves no records, assumes heat will come because the shot was given without observing, and gives another shot on their own when it does not work.","With guidance can record, but often misses noting the observation schedule and the daily boar exposure.","With guidance, records the administration and the planned heat-check dates, and can keep up the observation after dosing.","Independently observes daily and catches heat signs, and if it has not come after 7 days, does not decide alone but connects to a veterinary consultation.","Understands that post-administration observation is the key to not missing the chance, and can teach new staff the routine of records and scheduling."],"name_vi":"Ghi chép tiêm và quản lý lịch quan sát động dục","kanten_vi":"Có ghi ngày tiêm, số hiệu cá thể, liều lượng, người thực hiện, tiếp tục quan sát động dục 3〜5 ngày sau tiêm, nếu 7 ngày chưa động dục thì hỏi bác sĩ thú y không.","levels_vi":["Không ghi chép, nghĩ đã tiêm thì sẽ động dục mà không quan sát, không hiệu quả thì tự ý tiêm thêm 1 lần nữa.","Nếu được chỉ thị thì ghi, nhưng hay bỏ sót ghi chú lịch quan sát và việc cho tiếp xúc lợn đực hằng ngày.","Nếu được chỉ thị thì ghi việc tiêm và ngày dự định kiểm tra động dục, duy trì được cơ bản việc quan sát sau tiêm.","Dù không có chỉ thị vẫn quan sát hằng ngày để nhận ra dấu hiệu động dục, quá 7 ngày chưa động dục thì không tự quyết mà chuyển sang hỏi ý kiến bác sĩ thú y.","Hiểu quan sát sau tiêm là chìa khóa để không bỏ lỡ cơ hội, và có thể hướng dẫn người mới nề nếp ghi chép và quản lý lịch."],"name_id":"Catatan penyuntikan dan pengelolaan jadwal pengamatan birahi","kanten_id":"Apakah mencatat tanggal suntik, nomor individu, dosis, dan pelaksana, terus mengamati birahi 3〜5 hari setelah penyuntikan, dan berkonsultasi dengan dokter hewan jika sampai 7 hari belum birahi?","levels_id":["Tidak meninggalkan catatan, tidak mengamati karena berpikir sudah disuntik pasti birahi, dan jika tidak mempan menyuntik lagi atas keputusan sendiri.","Jika diperintah bisa mencatat, tetapi sering lalai menulis jadwal pengamatan dan kontak babi jantan setiap hari.","Jika diperintah, dapat menulis catatan penyuntikan dan tanggal rencana pemeriksaan birahi, serta melanjutkan pengamatan setelah penyuntikan secara lengkap.","Tanpa diperintah pun, mengamati setiap hari untuk menangkap tanda birahi, dan jika lewat 7 hari belum birahi tidak memutuskan sendiri melainkan menghubungkannya ke konsultasi dokter hewan.","Memahami bahwa pengamatan setelah penyuntikan adalah kunci agar tidak kehilangan kesempatan, dan dapat mengajarkan pola pencatatan dan pengelolaan jadwal kepada karyawan baru."]}],"name_en":"PMS Administration","purposeShort_en":"Induce estrus in sows with weak or absent heat and synchronize timing","name_vi":"Tiêm PMS (hormone kích thích động dục)","purposeShort_vi":"Gây động dục cho lợn nái động dục yếu hoặc không động dục, làm đồng đều thời điểm","name_id":"Penyuntikan PMS (hormon induksi birahi)","purposeShort_id":"Memicu birahi pada induk babi yang birahinya lemah atau tidak muncul, dan menyeragamkan waktunya"},{"id":"pg","category":"breeding","no":"No.36","name":"PG（プロスタグランジン）接種","purposeShort":"分娩のタイミングをそろえ、分娩管理・立会いをしやすくする","gyomu":"36","aspects":[{"id":"gestation-day","name":"妊娠日数の確認と適期投与","kanten":"妊娠日数を交配日の記録から正しく数え、114日未満への投与を避けて決められた日齢・対象に接種できるか。","levels":["妊娠日数を誤算して早すぎる時期に投与し、早産と未熟な子豚の死亡を招く。","指示があれば接種するが、日数確認や対象確認に漏れがある。","指示があれば決められた日齢・対象にひと通り接種できる。","指示がなくても妊娠日数を確認し、対象母豚を確かめて適期に接種する。","早期投与の禁忌と黄体の関係を理解し、適期投与の判断を新人に指導できる。"],"name_en":"Confirming Gestation Days and Timely Administration","kanten_en":"Can they count gestation days correctly from the mating-date records, avoid dosing before day 114, and inject the designated animals at the designated day?","levels_en":["Miscounts gestation days and injects too early, causing premature farrowing and deaths of immature piglets.","With guidance can inject, but misses the day count or the target-animal check.","With guidance can inject the designated animals at the designated day through the basic procedure.","Independently confirms gestation days, verifies the target sows, and injects at the right time.","Understands the contraindication of early administration and its relationship with the corpus luteum, and can teach new staff how to judge timely administration."],"name_vi":"Kiểm tra số ngày mang thai và tiêm đúng thời điểm","kanten_vi":"Có đếm đúng số ngày mang thai từ ghi chép ngày phối, tránh tiêm khi chưa đủ 114 ngày, tiêm đúng ngày tuổi thai và đúng đối tượng quy định không.","levels_vi":["Tính sai số ngày mang thai nên tiêm quá sớm, gây đẻ non và lợn con non yếu bị chết.","Nếu được chỉ thị thì tiêm, nhưng còn thiếu sót về kiểm tra số ngày và đối tượng.","Nếu được chỉ thị thì tiêm đúng ngày tuổi thai, đúng đối tượng quy định một cách cơ bản.","Dù không có chỉ thị vẫn kiểm tra số ngày mang thai, xác nhận lợn nái đối tượng và tiêm đúng thời điểm.","Hiểu chống chỉ định tiêm sớm và quan hệ với thể vàng, và có thể hướng dẫn người mới cách phán đoán thời điểm tiêm phù hợp."],"name_id":"Memeriksa umur kebuntingan dan menyuntik pada waktu yang tepat","kanten_id":"Apakah dapat menghitung umur kebuntingan dengan benar dari catatan tanggal kawin, menghindari penyuntikan sebelum hari ke-114, dan menyuntik pada umur dan sasaran yang ditentukan?","levels_id":["Salah menghitung umur kebuntingan sehingga menyuntik terlalu awal, dan menyebabkan lahir prematur serta kematian anak babi yang belum matang.","Menyuntik jika diperintah, tetapi sering lalai memeriksa jumlah hari dan sasaran.","Jika diperintah, dapat menyuntik pada umur dan sasaran yang ditentukan secara lengkap.","Tanpa diperintah pun, memeriksa umur kebuntingan, memastikan induk babi sasaran, dan menyuntik pada waktu yang tepat.","Memahami larangan penyuntikan terlalu awal dan hubungannya dengan korpus luteum, dan dapat mengajarkan penilaian waktu penyuntikan kepada karyawan baru."]},{"id":"id-doublecheck","name":"個体番号の照合とダブルチェック","kanten":"接種前に個体番号をプレートと照合して先輩とダブルチェックし、接種済みマーキングを付けられるか。","levels":["照合せずに打ち、間違った母豚への接種やマーキング忘れによる二重接種を招く。","指示があれば照合するが、ダブルチェックの依頼やマーキングに抜けが多い。","指示があればプレート照合とダブルチェックを行い、接種後のマーキングまでできる。","指示がなくても不安な個体はもう一度見てもらい、接種済みがひと目で分かる状態を保つ。","打ち間違いが流産につながる重大さを理解し、照合とマーキングの型を新人に指導できる。"],"name_en":"Verifying ID Numbers and Double-Checking","kanten_en":"Can they match the ID number against the plate before injecting, double-check with a senior, and apply the injected mark?","levels_en":["Injects without verifying, causing injections into the wrong sow and double injections from forgotten marking.","With guidance can verify, but often misses asking for the double check and the marking.","With guidance, verifies against the plate, double-checks, and can mark the sow after injection.","Independently has uncertain animals looked at again, and keeps injected sows recognizable at a glance.","Understands the seriousness of a wrong injection leading to abortion, and can teach new staff the routine of verification and marking."],"name_vi":"Đối chiếu số hiệu cá thể và kiểm tra chéo","kanten_vi":"Trước khi tiêm có đối chiếu số hiệu cá thể với bảng, kiểm tra chéo cùng người đi trước, và đánh dấu đã tiêm không.","levels_vi":["Không đối chiếu mà tiêm, gây tiêm nhầm nái và tiêm 2 lần do quên đánh dấu.","Nếu được chỉ thị thì đối chiếu, nhưng hay bỏ sót việc nhờ kiểm tra chéo và đánh dấu.","Nếu được chỉ thị thì đối chiếu với bảng, kiểm tra chéo, và đánh dấu được sau khi tiêm.","Dù không có chỉ thị vẫn nhờ xem lại con chưa chắc chắn, giữ trạng thái nhìn một cái là biết con đã tiêm.","Hiểu mức độ nghiêm trọng của tiêm nhầm dẫn đến sảy thai, và có thể hướng dẫn người mới nề nếp đối chiếu và đánh dấu."],"name_id":"Mencocokkan nomor individu dan pemeriksaan ganda","kanten_id":"Apakah sebelum menyuntik mencocokkan nomor individu dengan papan, memeriksa ganda bersama senior, dan memberi tanda sudah disuntik?","levels_id":["Menyuntik tanpa mencocokkan, sehingga terjadi suntikan pada induk yang salah dan suntikan dua kali karena lupa menandai.","Jika diperintah bisa mencocokkan, tetapi sering lalai meminta pemeriksaan ganda dan memberi tanda.","Jika diperintah, dapat mencocokkan dengan papan, memeriksa ganda, dan memberi tanda setelah penyuntikan.","Tanpa diperintah pun, meminta individu yang belum pasti dilihat sekali lagi, dan menjaga agar induk yang sudah disuntik terlihat sekali pandang.","Memahami betapa seriusnya salah suntik yang berujung keguguran, dan dapat mengajarkan pola pencocokan dan penandaan kepada karyawan baru."]},{"id":"injection-obs","name":"確実な注射と分娩受け入れ準備","kanten":"浅い注射で脂肪層に入るのを避けて確実に筋肉注射し、翌日の分娩に備えて立ち会い道具と子豚の保温を整えられるか。","levels":["針が浅く脂肪層に入って効果を弱め、分娩に備えた道具・保温の準備もしない。","指示があれば接種するが、注射の深さや分娩準備に漏れがある。","指示があれば十分な深さで筋肉注射し、立ち会いの道具をひと通りそろえられる。","指示がなくても確実に筋注し、保温灯でクリープエリアを32〜35℃に温めて分娩を受け入れる準備を整える。","浅い注射で効きが弱くなる理由を理解し、注射手技と分娩準備の段取りを新人に指導できる。"],"name_en":"Reliable Injection and Preparing to Receive the Farrowing","kanten_en":"Can they give a reliable intramuscular injection avoiding a shallow shot into the fat layer, and prepare the attendance tools and piglet warming for the next day's farrowing?","levels_en":["Injects shallow into the fat layer, weakening the effect, and makes no preparation of tools or warming for the farrowing.","With guidance can inject, but misses the injection depth and the farrowing preparation.","With guidance, injects deep enough into the muscle and can lay out the attendance tools.","Independently gives a reliable intramuscular injection, and warms the creep area to 32-35°C with heat lamps, ready to receive the farrowing.","Understands why a shallow injection weakens the effect, and can teach new staff injection technique and how to set up for farrowing."],"name_vi":"Tiêm chắc chắn và chuẩn bị đón đẻ","kanten_vi":"Có tiêm bắp chắc chắn tránh tiêm nông vào lớp mỡ, chuẩn bị dụng cụ túc trực và giữ ấm cho lợn con để đón đẻ ngày hôm sau không.","levels_vi":["Kim đâm nông vào lớp mỡ làm giảm hiệu quả, cũng không chuẩn bị dụng cụ và giữ ấm cho việc đẻ.","Nếu được chỉ thị thì tiêm, nhưng còn thiếu sót về độ sâu kim tiêm và chuẩn bị đón đẻ.","Nếu được chỉ thị thì tiêm bắp đủ sâu, xếp được cơ bản dụng cụ túc trực đỡ đẻ.","Dù không có chỉ thị vẫn tiêm bắp chắc chắn, dùng đèn sưởi làm ấm khu úm lợn con lên 32〜35℃, chuẩn bị sẵn sàng đón đẻ.","Hiểu lý do tiêm nông làm thuốc kém hiệu quả, và có thể hướng dẫn người mới kỹ thuật tiêm và cách sắp xếp chuẩn bị đón đẻ."],"name_id":"Menyuntik dengan pasti dan persiapan menyambut kelahiran","kanten_id":"Apakah menyuntik ke otot dengan pasti menghindari suntikan dangkal yang masuk lapisan lemak, dan menyiapkan peralatan pendampingan serta penghangatan anak babi untuk kelahiran keesokan harinya?","levels_id":["Jarum masuk dangkal ke lapisan lemak sehingga efeknya melemah, dan tidak menyiapkan peralatan maupun penghangatan untuk kelahiran.","Jika diperintah bisa menyuntik, tetapi sering lalai soal kedalaman suntikan dan persiapan kelahiran.","Jika diperintah, dapat menyuntik ke otot dengan kedalaman cukup, dan menyiapkan peralatan pendampingan secara lengkap.","Tanpa diperintah pun, menyuntik otot dengan pasti, dan menghangatkan area creep anak babi sampai 32〜35°C dengan lampu penghangat, siap menyambut kelahiran.","Memahami alasan suntikan dangkal melemahkan efek obat, dan dapat mengajarkan teknik menyuntik dan penyiapan kelahiran kepada karyawan baru."]},{"id":"human-safety","name":"人への安全と針・医療ゴミの処理","kanten":"PGが人にも効く薬と理解して必ず手袋を着け、皮膚に付いたらすぐ洗い流し、針はキャップをせず廃棄容器へ捨てられるか。","levels":["素手で薬を扱い、皮膚に付いても洗わず、使った針にキャップをはめ直して危険な捨て方をする。","指示があれば手袋を着けるが、廃棄の仕方や皮膚に付いたときの対応が不確実。","指示があれば手袋を着けて扱い、針・注射器を医療ゴミとしてひと通り処理できる。","指示がなくても手袋と廃棄ルールを徹底し、皮膚に付いたらすぐ洗い流して周囲にも注意を促す。","妊娠中の女性が扱ってはいけない理由を含めて危険性を理解し、安全な取り扱いを新人に指導できる。"],"name_en":"Human Safety and Disposal of Needles and Medical Waste","kanten_en":"Can they understand PG also acts on humans, always wear gloves, rinse immediately if it touches the skin, and discard needles into the disposal container without recapping?","levels_en":["Handles the drug bare-handed, does not wash it off the skin, and recaps used needles, disposing of them dangerously.","With guidance can wear gloves, but is unsure about disposal and what to do when the drug touches the skin.","With guidance, wears gloves to handle it and can dispose of needles and syringes as medical waste.","Independently keeps to the glove and disposal rules, rinses the skin immediately if touched, and alerts those around them.","Understands the hazards, including why pregnant women must not handle it, and can teach new staff safe handling."],"name_vi":"An toàn cho người và xử lý kim, rác y tế","kanten_vi":"Có hiểu PG là thuốc có tác dụng cả với người nên nhất định đeo găng tay, dính vào da thì rửa ngay, kim thì không đậy nắp mà bỏ vào thùng đựng rác không.","levels_vi":["Cầm thuốc bằng tay trần, dính vào da cũng không rửa, còn đậy lại nắp kim đã dùng và vứt bỏ nguy hiểm.","Nếu được chỉ thị thì đeo găng tay, nhưng cách vứt bỏ và cách xử lý khi dính vào da còn chưa chắc chắn.","Nếu được chỉ thị thì đeo găng tay khi thao tác, xử lý được kim và bơm tiêm như rác y tế.","Dù không có chỉ thị vẫn triệt để đeo găng và giữ quy tắc vứt bỏ, dính vào da thì rửa ngay và nhắc nhở cả người xung quanh.","Hiểu mức độ nguy hiểm bao gồm lý do phụ nữ mang thai không được cầm thuốc này, và có thể hướng dẫn người mới cách thao tác an toàn."],"name_id":"Keselamatan manusia dan pembuangan jarum serta sampah medis","kanten_id":"Apakah memahami PG adalah obat yang juga berefek pada manusia sehingga selalu memakai sarung tangan, segera membilas jika terkena kulit, dan membuang jarum ke wadah pembuangan tanpa memasang tutupnya?","levels_id":["Memegang obat dengan tangan kosong, tidak mencuci walau terkena kulit, dan memasang kembali tutup jarum bekas sehingga cara buangnya berbahaya.","Jika diperintah bisa memakai sarung tangan, tetapi cara membuang dan penanganan saat terkena kulit belum pasti.","Jika diperintah, dapat menanganinya dengan sarung tangan dan membuang jarum serta alat suntik sebagai sampah medis secara lengkap.","Tanpa diperintah pun, menjalankan aturan sarung tangan dan pembuangan dengan ketat, segera membilas jika terkena kulit, dan mengingatkan orang di sekitar.","Memahami bahayanya termasuk alasan wanita hamil tidak boleh menanganinya, dan dapat mengajarkan penanganan yang aman kepada karyawan baru."]},{"id":"record-timing","name":"接種記録と観察予定の管理","kanten":"個体番号・接種日時を必ず記録し、接種後12時間からの兆候確認と48時間の報告基準を守れるか。","levels":["だれに打ったかを記録せず、接種後の見回り予定も立てない。","指示されれば記録するが、日時の記載や観察予定に抜けが多い。","指示があれば個体番号・接種日時を記録し、翌日の見回り予定までひと通り立てられる。","指示がなくても記録を確実に残し、48時間たっても産まないときは油断せず必ず報告する。","分娩が接種後24〜36時間に集中する流れを理解し、記録と観察予定の組み方を新人に指導できる。"],"name_en":"Injection Records and Observation Scheduling","kanten_en":"Can they always record the ID number and injection date and time, and keep to checking for signs from 12 hours after injection and the 48-hour reporting rule?","levels_en":["Does not record who was injected, and makes no plan to check on them afterward.","With guidance can record, but often omits the date and time and the observation schedule.","With guidance, records the ID number and injection date and time, and can plan the next day's rounds.","Independently keeps reliable records, stays alert, and always reports when no farrowing has come after 48 hours.","Understands that farrowings concentrate 24-36 hours after injection, and can teach new staff how to organize records and observation schedules."],"name_vi":"Ghi chép tiêm và quản lý lịch theo dõi","kanten_vi":"Có nhất định ghi số hiệu cá thể, ngày giờ tiêm, giữ việc kiểm tra dấu hiệu từ 12 giờ sau tiêm và chuẩn báo cáo 48 giờ không.","levels_vi":["Không ghi đã tiêm con nào, cũng không lập lịch đi xem sau tiêm.","Nếu được chỉ thị thì ghi, nhưng hay bỏ sót ghi ngày giờ và lịch theo dõi.","Nếu được chỉ thị thì ghi số hiệu cá thể, ngày giờ tiêm, và lập được cơ bản lịch đi xem ngày hôm sau.","Dù không có chỉ thị vẫn ghi chép chắc chắn, không chủ quan và nhất định báo cáo khi quá 48 giờ vẫn chưa đẻ.","Hiểu việc đẻ tập trung vào 24〜36 giờ sau tiêm, và có thể hướng dẫn người mới cách tổ chức ghi chép và lịch theo dõi."],"name_id":"Catatan penyuntikan dan pengelolaan jadwal pengawasan","kanten_id":"Apakah selalu mencatat nomor individu dan tanggal-jam penyuntikan, serta menepati pemeriksaan tanda-tanda mulai 12 jam setelah suntik dan patokan lapor 48 jam?","levels_id":["Tidak mencatat siapa yang disuntik, dan tidak membuat rencana keliling memeriksa setelah penyuntikan.","Jika diperintah bisa mencatat, tetapi sering tidak menulis tanggal-jam dan jadwal pengawasan.","Jika diperintah, dapat mencatat nomor individu dan tanggal-jam penyuntikan, serta menyusun rencana keliling keesokan harinya secara lengkap.","Tanpa diperintah pun, meninggalkan catatan dengan pasti, tidak lengah, dan selalu melapor jika lewat 48 jam belum melahirkan.","Memahami bahwa kelahiran terkonsentrasi 24〜36 jam setelah penyuntikan, dan dapat mengajarkan cara menyusun catatan dan jadwal pengawasan kepada karyawan baru."]}],"name_en":"PG (Prostaglandin) Injection","purposeShort_en":"Synchronize farrowing timing to make farrowing management and attendance easier","name_vi":"Tiêm PG (prostaglandin)","purposeShort_vi":"Làm đồng đều thời điểm đẻ, giúp quản lý đẻ và trực đẻ dễ dàng hơn","name_id":"Penyuntikan PG (prostaglandin)","purposeShort_id":"Menyeragamkan waktu melahirkan agar pengelolaan dan pendampingan kelahiran lebih mudah"},{"id":"uterine-wash","category":"breeding","no":"No.42","name":"子宮内洗浄","purposeShort":"子宮内の汚染物を減らし、子宮炎・発熱を防ぎ産後回復を促す","gyomu":"42","aspects":[{"id":"target-select","name":"対象選定と獣医師指示の遵守","kanten":"全頭には行わず対象を選定し、薬剤の濃度・量を守って獣医師の指示に従えるか。","levels":["全頭にルーチンで行い、薬剤の濃度・量も守らず自然回復を妨げる。","指示があれば実施するが、対象選定や濃度管理に漏れがある。","指示があれば対象を選び、決められた濃度・量でひと通り実施できる。","指示がなくても手入れした母豚等に絞り、濃度・量を守って獣医師の指示に従う。","予防的ルーチン洗浄の弊害を理解し、対象選定と適正実施を新人に指導できる。"],"name_en":"Case Selection and Following Veterinary Instructions","kanten_en":"Can they select cases instead of treating every sow, keep the correct drug concentration and volume, and follow the veterinarian's instructions?","levels_en":["Performs it routinely on every sow, ignores drug concentration and volume, and hinders natural recovery.","With guidance can perform it, but misses case selection or concentration control.","With guidance can select cases and perform the basic procedure at the designated concentration and volume.","Independently limits treatment to sows that required manual intervention and the like, keeps concentration and volume, and follows the veterinarian's instructions.","Understands the harm of routine preventive flushing, and can teach new staff case selection and proper practice."],"name_vi":"Chọn đối tượng và tuân theo chỉ thị của bác sĩ thú y","kanten_vi":"Có chọn đối tượng thay vì làm cho tất cả, giữ đúng nồng độ và lượng thuốc, tuân theo chỉ thị của bác sĩ thú y không.","levels_vi":["Làm thường quy cho tất cả, không giữ đúng nồng độ và lượng thuốc, cản trở hồi phục tự nhiên.","Nếu được chỉ thị thì thực hiện, nhưng còn thiếu sót về chọn đối tượng và quản lý nồng độ.","Nếu được chỉ thị thì chọn đối tượng, thực hiện đúng nồng độ và lượng quy định một cách cơ bản.","Dù không có chỉ thị vẫn chỉ làm cho lợn nái đã can thiệp bằng tay v.v., giữ đúng nồng độ, lượng thuốc và tuân theo chỉ thị của bác sĩ thú y.","Hiểu tác hại của việc rửa thường quy để phòng bệnh, và có thể hướng dẫn người mới cách chọn đối tượng và thực hiện đúng."],"name_id":"Memilih sasaran dan mengikuti perintah dokter hewan","kanten_id":"Apakah tidak melakukan pada semua babi tetapi memilih sasaran, menjaga kepekatan dan jumlah obat, serta mengikuti perintah dokter hewan?","levels_id":["Melakukan secara rutin pada semua babi, tidak menjaga kepekatan dan jumlah obat, sehingga menghambat pemulihan alami.","Melakukan jika diperintah, tetapi sering lalai memilih sasaran dan mengatur kepekatan.","Jika diperintah, dapat memilih sasaran dan melakukannya secara lengkap dengan kepekatan dan jumlah yang ditentukan.","Tanpa diperintah pun, membatasi hanya pada induk babi yang dibantu saat melahirkan dan sejenisnya, menjaga kepekatan dan jumlah obat, serta mengikuti perintah dokter hewan.","Memahami kerugian pencucian rutin sebagai pencegahan, dan dapat mengajarkan pemilihan sasaran dan pelaksanaan yang tepat kepada karyawan baru."]},{"id":"solution-warm","name":"洗浄液の調製と加温","kanten":"洗浄液を処方どおりに用意し、体温程度（38〜39℃）に温め、濃度が分からないときは作業を止めて確認できるか。","levels":["冷たい液をそのまま使い、濃度が分からなくても適当に薄めて進めてしまう。","指示があれば用意するが、温度の確認や処方どおりの調製に抜けがある。","指示があれば処方どおりに調製し、体温程度に温めてから使える。","指示がなくても直前に液温を確かめ、不明点があれば作業を止めて確認してから進める。","冷たい液が子宮収縮・泌乳低下を招く仕組みを理解し、調製と加温の要点を新人に指導できる。"],"name_en":"Preparing and Warming the Flushing Solution","kanten_en":"Can they prepare the flushing solution as prescribed, warm it to about body temperature (38-39°C), and stop the work to check when the concentration is unclear?","levels_en":["Uses the solution cold as it is, and dilutes it by guesswork and proceeds even when the concentration is unknown.","With guidance can prepare it, but misses checking the temperature and preparing exactly as prescribed.","With guidance, prepares it as prescribed and can warm it to about body temperature before use.","Independently checks the solution temperature just before use, and stops the work to confirm anything unclear before proceeding.","Understands how cold solution causes uterine contraction and reduced milk production, and can teach new staff the key points of preparation and warming."],"name_vi":"Pha chế và làm ấm dung dịch rửa","kanten_vi":"Có chuẩn bị dung dịch rửa đúng theo đơn, làm ấm đến khoảng nhiệt độ cơ thể (38〜39℃), khi không rõ nồng độ thì dừng việc để hỏi lại không.","levels_vi":["Dùng ngay dung dịch còn lạnh, không rõ nồng độ cũng pha đại rồi làm tiếp.","Nếu được chỉ thị thì chuẩn bị, nhưng có bỏ sót việc kiểm tra nhiệt độ và pha đúng theo đơn.","Nếu được chỉ thị thì pha đúng theo đơn, làm ấm đến khoảng nhiệt độ cơ thể rồi mới dùng.","Dù không có chỉ thị vẫn kiểm tra nhiệt độ dung dịch ngay trước khi làm, có điểm chưa rõ thì dừng việc, hỏi lại rồi mới tiến hành.","Hiểu cơ chế dung dịch lạnh gây co tử cung, giảm tiết sữa, và có thể hướng dẫn người mới các điểm chính về pha chế và làm ấm."],"name_id":"Meracik dan menghangatkan cairan pencuci","kanten_id":"Apakah menyiapkan cairan pencuci sesuai resep, menghangatkannya sampai sekitar suhu tubuh (38〜39°C), dan menghentikan pekerjaan untuk bertanya jika kepekatannya tidak jelas?","levels_id":["Memakai cairan yang masih dingin begitu saja, dan walau kepekatannya tidak jelas mengencerkannya sembarangan lalu melanjutkan.","Jika diperintah bisa menyiapkan, tetapi sering lalai memeriksa suhu dan meracik tepat sesuai resep.","Jika diperintah, dapat meracik sesuai resep dan menghangatkannya sampai sekitar suhu tubuh sebelum dipakai.","Tanpa diperintah pun, memeriksa suhu cairan sesaat sebelum dipakai, dan jika ada yang belum jelas menghentikan pekerjaan untuk memastikan dulu.","Memahami mekanisme cairan dingin menyebabkan kontraksi rahim dan turunnya produksi susu, dan dapat mengajarkan pokok peracikan dan penghangatan kepada karyawan baru."]},{"id":"aseptic-gentle","name":"滅菌器具と外陰部消毒・穏やかな操作","kanten":"滅菌した器具・洗浄液を使い、外陰部を清拭・消毒してから、強くこすらず穏やかに操作できるか。","levels":["非滅菌の器具を使い、外陰部も汚れたまま挿入して新しいばい菌を子宮に入れてしまう。","指示があれば実施するが、滅菌や外陰部の消毒に漏れがある。","指示があれば滅菌器具を使い、外陰部を消毒してからひと通り実施できる。","指示がなくても外陰部の清拭消毒と滅菌器具の使用を徹底し、強くこすらず穏やかに操作する。","非滅菌器具による二次感染と強い操作で子宮を傷めるリスクを理解し、清潔な手順を新人に指導できる。"],"name_en":"Sterile Equipment, Vulva Disinfection, and Gentle Handling","kanten_en":"Can they use sterilized equipment and flushing solution, wipe and disinfect the vulva first, and handle gently without harsh scrubbing?","levels_en":["Uses unsterilized equipment and inserts with the vulva still dirty, bringing new germs into the uterus.","With guidance can perform it, but misses sterilization and vulva disinfection.","With guidance, uses sterile equipment and can perform the basic procedure after disinfecting the vulva.","Independently keeps to wiping and disinfecting the vulva and using sterile equipment, and handles gently without harsh scrubbing.","Understands the risks of secondary infection from unsterile equipment and of injuring the uterus by rough handling, and can teach new staff the clean procedure."],"name_vi":"Dụng cụ tiệt trùng, khử trùng âm hộ và thao tác nhẹ nhàng","kanten_vi":"Có dùng dụng cụ, dung dịch rửa đã tiệt trùng, lau sạch và khử trùng âm hộ trước, rồi thao tác nhẹ nhàng không chà xát mạnh không.","levels_vi":["Dùng dụng cụ không tiệt trùng, âm hộ còn bẩn đã đưa vào, mang vi khuẩn mới vào tử cung.","Nếu được chỉ thị thì thực hiện, nhưng còn thiếu sót về tiệt trùng và khử trùng âm hộ.","Nếu được chỉ thị thì dùng dụng cụ tiệt trùng, khử trùng âm hộ rồi thực hiện được cơ bản.","Dù không có chỉ thị vẫn triệt để lau khử trùng âm hộ và dùng dụng cụ tiệt trùng, thao tác nhẹ nhàng không chà xát mạnh.","Hiểu rủi ro nhiễm trùng thứ cấp do dụng cụ không tiệt trùng và làm tổn thương tử cung do thao tác mạnh, và có thể hướng dẫn người mới trình tự sạch sẽ."],"name_id":"Alat steril, disinfeksi vulva, dan penanganan lembut","kanten_id":"Apakah memakai alat dan cairan pencuci yang steril, mengelap dan mendisinfeksi vulva dulu, lalu menangani dengan lembut tanpa menggosok keras?","levels_id":["Memakai alat yang tidak steril dan memasukkan saat vulva masih kotor, sehingga membawa kuman baru ke dalam rahim.","Jika diperintah bisa melakukan, tetapi sering lalai soal sterilisasi dan disinfeksi vulva.","Jika diperintah, dapat memakai alat steril dan melakukannya secara lengkap setelah mendisinfeksi vulva.","Tanpa diperintah pun, menjalankan dengan ketat pengelapan-disinfeksi vulva dan pemakaian alat steril, serta menangani dengan lembut tanpa menggosok keras.","Memahami risiko infeksi sekunder karena alat tidak steril dan melukai rahim karena penanganan kasar, dan dapat mengajarkan prosedur yang bersih kepada karyawan baru."]},{"id":"stop-on-resistance","name":"抵抗・暴れ時の中断判断","kanten":"カテーテルに抵抗を感じたらすぐ止めて獣医師に相談し、母豚が暴れたら無理をせずいったん抜いて仕切り直せるか。","levels":["抵抗があっても力で押し込み、母豚が暴れても押さえつけて続ける。","指示があれば止まるが、無理をしがちで中断の判断が遅れる。","指示があれば抵抗を感じた時点で止め、報告してから次の対応に移れる。","指示がなくても抵抗や暴れの時点でそっと引き抜き、落ち着いてからやり直すか獣医師に相談する。","無理な操作が子宮穿孔・腹膜炎につながる危険を理解し、止める判断の基準を新人に指導できる。"],"name_en":"Deciding to Stop on Resistance or Struggling","kanten_en":"Can they stop immediately and consult the veterinarian when they feel resistance on the catheter, and, when the sow struggles, withdraw it without forcing and start over?","levels_en":["Pushes through resistance by force, and holds the sow down and continues even when she struggles.","With guidance can stop, but tends to force it and is slow to decide to stop.","With guidance, stops the moment resistance is felt and can report before moving to the next step.","Independently withdraws the catheter gently at the point of resistance or struggling, and retries once calm or consults the veterinarian.","Understands the danger that forced handling leads to uterine perforation and peritonitis, and can teach new staff the criteria for stopping."],"name_vi":"Phán đoán dừng lại khi vướng hoặc lợn giãy giụa","kanten_vi":"Khi thấy catheter bị vướng có dừng ngay và hỏi bác sĩ thú y, khi nái giãy giụa có không cố mà tạm rút ra làm lại không.","levels_vi":["Bị vướng vẫn dùng sức đẩy vào, nái giãy giụa vẫn đè xuống làm tiếp.","Nếu được chỉ thị thì dừng, nhưng hay cố làm và quyết định dừng còn chậm.","Nếu được chỉ thị thì dừng ngay lúc thấy vướng, báo cáo rồi mới chuyển sang bước tiếp theo.","Dù không có chỉ thị vẫn rút nhẹ ra ngay khi vướng hoặc lợn giãy, đợi bình tĩnh rồi làm lại hoặc hỏi bác sĩ thú y.","Hiểu nguy cơ thao tác cưỡng ép dẫn đến thủng tử cung, viêm phúc mạc, và có thể hướng dẫn người mới tiêu chí quyết định dừng."],"name_id":"Keputusan berhenti saat tertahan atau babi meronta","kanten_id":"Apakah saat kateter terasa tertahan segera berhenti dan berkonsultasi dengan dokter hewan, dan saat induk meronta tidak memaksa melainkan mencabutnya dulu lalu mengulang?","levels_id":["Walau tertahan tetap mendorong dengan tenaga, dan walau induk meronta tetap menekannya sambil melanjutkan.","Jika diperintah bisa berhenti, tetapi cenderung memaksa dan lambat memutuskan berhenti.","Jika diperintah, dapat berhenti begitu terasa tertahan, dan melapor sebelum lanjut ke penanganan berikutnya.","Tanpa diperintah pun, mencabut perlahan begitu tertahan atau babi meronta, lalu mengulang setelah tenang atau berkonsultasi dengan dokter hewan.","Memahami bahaya penanganan paksa yang berujung rahim berlubang dan radang selaput perut, dan dapat mengajarkan patokan kapan berhenti kepada karyawan baru."]},{"id":"effluent-record","name":"体温・排出液の記録と休薬管理","kanten":"処置前後の体温を測って比べ、排出液の色・におい・混入物を記録し、抗菌薬使用の記録と休薬の指示に従えるか。","levels":["体温も排出液も見ず、処置した母豚と日付の記録も残さない。","指示されれば記録するが、色・においなど獣医師の判断材料になる情報に抜けが多い。","指示があれば処置前の体温と排出液の状態を記録し、処置した母豚と日付を残せる。","指示がなくても翌日まで体温・食欲・悪露を毎日記録し、良くならないときは獣医師に伝える。","記録が次の処置判断と休薬管理の根拠になることを理解し、観察と記録の型を新人に指導できる。"],"name_en":"Recording Temperature and Effluent, and Withdrawal Management","kanten_en":"Can they measure and compare body temperature before and after the procedure, record the color, smell, and contents of the effluent, and follow the antimicrobial-use records and withdrawal instructions?","levels_en":["Looks at neither temperature nor effluent, and leaves no record of which sow was treated or when.","With guidance can record, but often omits information the veterinarian needs, such as color and smell.","With guidance, records the pre-treatment temperature and the state of the effluent, and can note the treated sow and date.","Independently records temperature, appetite, and lochia daily through the next day, and tells the veterinarian when there is no improvement.","Understands that the records are the basis for the next treatment decision and withdrawal management, and can teach new staff the routine of observation and recording."],"name_vi":"Ghi thân nhiệt, dịch thải và quản lý ngừng thuốc","kanten_vi":"Có đo và so sánh thân nhiệt trước sau xử lý, ghi màu, mùi, tạp chất của dịch thải ra, tuân theo ghi chép dùng kháng sinh và chỉ thị về thời gian ngừng thuốc không.","levels_vi":["Không xem thân nhiệt lẫn dịch thải, cũng không ghi lại đã xử lý nái nào, ngày nào.","Nếu được chỉ thị thì ghi, nhưng hay thiếu những thông tin làm căn cứ phán đoán cho bác sĩ thú y như màu, mùi.","Nếu được chỉ thị thì ghi thân nhiệt trước xử lý và trạng thái dịch thải, ghi lại được nái đã xử lý và ngày.","Dù không có chỉ thị vẫn ghi hằng ngày thân nhiệt, ăn uống, sản dịch đến hôm sau, không đỡ thì báo cho bác sĩ thú y.","Hiểu ghi chép là căn cứ cho phán đoán xử lý tiếp theo và quản lý thời gian ngừng thuốc, và có thể hướng dẫn người mới nề nếp quan sát và ghi chép."],"name_id":"Mencatat suhu tubuh dan cairan keluar, serta pengelolaan masa henti obat","kanten_id":"Apakah mengukur dan membandingkan suhu tubuh sebelum-sesudah tindakan, mencatat warna, bau, dan campuran cairan yang keluar, serta mengikuti catatan pemakaian antibiotik dan instruksi masa henti obat?","levels_id":["Tidak melihat suhu tubuh maupun cairan yang keluar, dan tidak mencatat induk mana yang ditangani dan tanggalnya.","Jika diperintah bisa mencatat, tetapi sering kurang informasi yang menjadi bahan penilaian dokter hewan seperti warna dan bau.","Jika diperintah, dapat mencatat suhu tubuh sebelum tindakan dan keadaan cairan yang keluar, serta meninggalkan catatan induk yang ditangani dan tanggalnya.","Tanpa diperintah pun, setiap hari sampai hari berikutnya mencatat suhu tubuh, nafsu makan, dan cairan nifas, serta memberi tahu dokter hewan jika tidak membaik.","Memahami bahwa catatan menjadi dasar keputusan penanganan berikutnya dan pengelolaan masa henti obat, dan dapat mengajarkan pola pengamatan dan pencatatan kepada karyawan baru."]}],"name_en":"Uterine Flushing","purposeShort_en":"Reduce uterine contamination, prevent metritis and fever, and promote postpartum recovery","name_vi":"Rửa tử cung (sau khi đẻ)","purposeShort_vi":"Giảm chất bẩn trong tử cung, phòng viêm tử cung, sốt và giúp hồi phục sau đẻ","name_id":"Pencucian rahim (setelah melahirkan)","purposeShort_id":"Mengurangi kotoran di dalam rahim, mencegah radang rahim dan demam, serta mempercepat pemulihan setelah melahirkan"},{"id":"gilt-intake","category":"breeding","no":"","name":"育成豚の受け入れ","purposeShort":"届いた候補豚（将来の母豚）を病気を持ち込まず安全に受け入れ、環境に慣らして健康な状態で群へ合流させる","gyomu":"","aspects":[{"id":"arrival-check","name":"到着時の個体確認と状態チェック","kanten":"到着した候補豚の頭数と個体番号を確かめ、肢蹄・乳頭数（14個以上）・背線・体重を見て受け入れの可否を確認できるか。","levels":["頭数や個体番号を確かめずに降ろし、肢蹄や乳頭を見ないまま、跛行や基準外の豚も他の豚と同じ豚房に入れる。","指示があれば頭数と個体番号を確認するが、肢蹄や乳頭数の見落としが多く、体重確認は他者まかせ。","指示があれば頭数と個体番号を確かめ、肢蹄・乳頭数（14個以上）・背線を確認し、体重を測って記録できる。","指示がなくても到着時に頭数と個体番号を確かめ、肢蹄・乳頭・背線の基準外の豚に気づけばその場で上長に伝える。","到着時の見落としが数か月後の母豚の成績や淘汰に響くことを理解し、確認の見方を新人に指導できる。"],"name_en":"Checking each pig and its condition on arrival","name_vi":"Kiểm tra từng con và tình trạng khi lợn về đến nơi","name_id":"Pemeriksaan tiap ekor dan kondisinya saat tiba","kanten_en":"Can they check the head count and individual numbers of arriving gilts, and look at legs and feet, teat count (14 or more), back line, and weight to confirm whether to accept them?","kanten_vi":"Có kiểm tra số lượng và số hiệu cá thể của lợn hậu bị vừa về, xem chân móng, số vú (từ 14 vú trở lên), đường lưng và cân nặng để xác nhận có nhận hay không không.","kanten_id":"Apakah memeriksa jumlah dan nomor individu babi calon induk yang tiba, serta melihat kaki dan kuku, jumlah puting (14 ke atas), garis punggung, dan berat badan untuk memastikan layak diterima.","levels_en":["Unloads without checking head count or individual numbers, does not look at legs or teats, and puts lame or off-standard pigs into the same pen as the others.","With guidance, checks head count and individual numbers, but often misses leg problems and teat counts, and leaves weight checks to others.","With guidance, checks the head count and individual ID numbers, checks legs and feet, teat count (14 or more), and back line, and can weigh and record.","Independently checks head count and individual numbers on arrival, and tells the supervisor on the spot when a pig falls outside the standard for legs and feet, teats, or back line.","Understands that what is missed at arrival affects the sow's performance and culling months later, and can teach new staff how to check."],"levels_vi":["Dỡ xuống mà không kiểm tra số lượng và số hiệu cá thể, không nhìn chân và vú, lợn đi khập khiễng hay không đạt tiêu chuẩn cũng cho vào chung ô với lợn khác.","Nếu có chỉ dẫn thì kiểm tra số lượng và số hiệu cá thể, nhưng hay bỏ sót vấn đề ở chân và số vú, việc kiểm tra cân nặng phó mặc cho người khác.","Nếu có chỉ dẫn thì kiểm tra số lượng và số hiệu cá thể, kiểm tra chân móng, số vú (từ 14 vú trở lên), đường lưng, và cân ghi lại được.","Không cần chỉ dẫn cũng kiểm tra số lượng và số hiệu cá thể ngay khi về, nếu thấy lợn không đạt tiêu chuẩn về chân móng, vú, đường lưng thì báo ngay cấp trên.","Hiểu việc bỏ sót khi lợn về đến nơi sẽ ảnh hưởng đến thành tích và việc loại thải lợn nái sau vài tháng, và có thể hướng dẫn người mới cách kiểm tra."],"levels_id":["Menurunkan tanpa memeriksa jumlah dan nomor individu, tidak melihat kaki dan puting, dan babi yang pincang atau tidak memenuhi standar pun dimasukkan ke kandang yang sama dengan yang lain.","Jika ada instruksi memeriksa jumlah dan nomor individu, tetapi sering terlewat masalah kaki dan jumlah puting, dan pemeriksaan berat badan diserahkan ke orang lain.","Jika ada instruksi, bisa memeriksa jumlah babi dan nomor individu, memeriksa kaki dan kuku, jumlah puting (14 ke atas), serta garis punggung, lalu menimbang dan mencatat.","Tanpa instruksi pun, memeriksa jumlah dan nomor individu saat tiba, dan jika melihat babi yang tidak memenuhi standar kaki dan kuku, puting, atau garis punggung langsung memberi tahu atasan di tempat.","Memahami bahwa yang terlewat saat tiba memengaruhi kinerja dan pengafkiran induk beberapa bulan kemudian, dan bisa mengajari karyawan baru cara memeriksa."]},{"id":"isolation-bio","name":"持ち込み防止と着替え・消毒","kanten":"外から来た豚と車・人から病原体を持ち込まないよう、農場の決まりに従って着替え・消毒をし、長靴・道具を他の群と分けて使えるか。","levels":["作業着や長靴を替えず、届いた豚を他の群の豚房に入れ、道具も共用して病原体を広げる。","指示があれば着替えや消毒をするが、長靴の履き替えや道具の分け方に抜けが多い。","指示があれば農場の決まりに従って着替え・消毒をし、長靴・道具を他の群と分けて使える。","指示がなくても受け入れ前後に着替え・消毒を行い、移動の順序を守って他の群に病原体を持ち込まない。","病気を入れない・広げない・持ち出さないの3原則を理解し、受け入れ時の分け方と消毒の理由を新人に指導できる。"],"name_en":"Preventing carry-in, changing clothes, and disinfecting","name_vi":"Ngăn mang mầm bệnh vào, thay đồ và khử trùng","name_id":"Pencegahan masuknya penyakit, ganti pakaian, dan disinfeksi","kanten_en":"Can they follow farm rules to keep pathogens out from incoming pigs, vehicles, and people, by changing clothes and disinfecting, and use boots and tools separately from other groups?","kanten_vi":"Có theo quy định của trại để không mang mầm bệnh vào từ lợn, xe và người bên ngoài, thay đồ, khử trùng và dùng ủng, dụng cụ riêng với các đàn khác không.","kanten_id":"Apakah mengikuti aturan peternakan agar tidak membawa patogen dari babi, kendaraan, dan orang dari luar, dengan berganti pakaian dan mendisinfeksi, serta memakai sepatu bot dan peralatan terpisah dari kelompok lain.","levels_en":["Does not change work clothes or boots, puts the arrived pigs into pens of other groups, and shares tools, spreading pathogens.","With guidance, changes clothes and disinfects, but often misses changing boots and keeping tools separate.","With guidance, changes clothes and disinfects according to farm rules, and can use boots and tools separately from other groups.","Independently changes clothes and disinfects before and after receiving, keeps to the movement order, and does not carry pathogens to other groups.","Understands the three principles of keeping disease out, not spreading it, and not carrying it away, and can teach new staff why pigs are separated and disinfection is done at intake."],"levels_vi":["Không thay quần áo, ủng, cho lợn vừa về vào ô của đàn khác, dùng chung dụng cụ làm lây mầm bệnh.","Nếu có chỉ dẫn thì thay đồ và khử trùng, nhưng hay bỏ sót việc thay ủng và việc tách dụng cụ.","Nếu có chỉ dẫn thì thay đồ, khử trùng theo quy định của trại, và dùng ủng, dụng cụ riêng với các đàn khác được.","Không cần chỉ dẫn cũng thay đồ, khử trùng trước và sau khi tiếp nhận, giữ đúng thứ tự di chuyển để không mang mầm bệnh sang đàn khác.","Hiểu 3 nguyên tắc không mang vào, không lây lan, không mang ra, và có thể hướng dẫn người mới lý do tách riêng và khử trùng khi tiếp nhận."],"levels_id":["Tidak mengganti pakaian kerja dan sepatu bot, memasukkan babi yang baru tiba ke kandang kelompok lain, dan memakai alat bersama sehingga menyebarkan patogen.","Jika ada instruksi bisa berganti pakaian dan mendisinfeksi, tetapi sering lalai mengganti sepatu bot dan memisahkan alat.","Jika ada instruksi, bisa berganti pakaian dan mendisinfeksi sesuai aturan peternakan, serta memakai sepatu bot dan alat terpisah dari kelompok lain.","Tanpa instruksi pun, berganti pakaian dan mendisinfeksi sebelum dan sesudah penerimaan, menaati urutan pergerakan, dan tidak membawa patogen ke kelompok lain.","Memahami tiga prinsip tidak memasukkan, tidak menyebarkan, dan tidak membawa keluar penyakit, dan bisa mengajari karyawan baru alasan pemisahan dan disinfeksi saat penerimaan."]},{"id":"acclimation","name":"馴致（環境と雄豚に慣らす）","kanten":"候補豚を急に驚かせずゆっくり近づけ、24〜26週齢から柵越しの雄豚当てを毎日10〜15分行って、環境と雄豚に慣らせるか。","levels":["急に近づいて追い回し、雄豚当ての時間も決めず、環境が急に変わってもそのままにする。","指示があれば雄豚当てをするが、時間や回数にムラがあり、豚を驚かせる近づき方が残る。","指示があれば柵越しで毎日10〜15分雄豚に触れさせ、ゆっくり近づいて落ち着かせられる。","指示がなくても決めた週齢から毎日雄豚当てを行い、環境の急な変化を避けて豚の様子を見ながら進める。","フェロモン刺激で性成熟が進むことと、若い豚はストレスに弱いことを理解し、馴致の進め方を新人に指導できる。"],"name_en":"Acclimation (getting pigs used to the environment and boars)","name_vi":"Làm quen (cho lợn quen môi trường và lợn đực)","name_id":"Adaptasi (membiasakan dengan lingkungan dan pejantan)","kanten_en":"Can they approach gilts slowly without startling them, and do daily 10-15 minute fence-line boar contact from 24-26 weeks of age so the pigs get used to the environment and the boar?","kanten_vi":"Có tiếp cận lợn hậu bị nhẹ nhàng không làm giật mình, và từ 24-26 tuần tuổi cho tiếp xúc lợn đực qua hàng rào mỗi ngày 10-15 phút để lợn quen môi trường và lợn đực không.","kanten_id":"Apakah mendekati babi calon induk dengan pelan tanpa mengagetkan, dan sejak umur 24-26 minggu melakukan kontak dengan pejantan lewat pagar setiap hari 10-15 menit agar terbiasa dengan lingkungan dan pejantan.","levels_en":["Approaches suddenly and chases the pigs, sets no time for boar contact, and leaves the pigs as they are even when the environment changes abruptly.","With guidance, does boar contact, but time and frequency are uneven, and the approach still startles the pigs.","With guidance, lets the pigs touch the boar across the fence for 10-15 minutes every day, and can approach slowly and calm them.","Independently does daily boar contact from the set age, avoids abrupt changes in the environment, and proceeds while watching the pigs.","Understands that pheromone stimulation advances sexual maturity and that young pigs are weak against stress, and can teach new staff how to carry out acclimation."],"levels_vi":["Đột ngột lại gần, đuổi lợn, không định giờ cho tiếp xúc lợn đực, môi trường thay đổi đột ngột cũng mặc kệ.","Nếu có chỉ dẫn thì cho tiếp xúc lợn đực, nhưng thời gian và số lần không đều, vẫn còn cách tiếp cận làm lợn giật mình.","Nếu có chỉ dẫn thì cho tiếp xúc lợn đực qua hàng rào mỗi ngày 10-15 phút, tiến lại gần từ từ và làm lợn bình tĩnh được.","Không cần chỉ dẫn cũng cho tiếp xúc lợn đực mỗi ngày từ độ tuổi đã định, tránh thay đổi môi trường đột ngột và vừa làm vừa quan sát lợn.","Hiểu kích thích pheromone thúc đẩy thành thục sinh dục và lợn non dễ bị căng thẳng, và có thể hướng dẫn người mới cách tiến hành làm quen."],"levels_id":["Tiba-tiba mendekat dan mengejar babi, tidak menentukan waktu kontak pejantan, dan membiarkan saja walau lingkungan berubah mendadak.","Jika ada instruksi melakukan kontak pejantan, tetapi waktu dan frekuensinya tidak tetap, dan cara mendekatnya masih mengagetkan babi.","Jika ada instruksi, bisa membuat babi menyentuh pejantan lewat pagar setiap hari 10-15 menit, serta mendekat pelan dan menenangkannya.","Tanpa instruksi pun, melakukan kontak pejantan setiap hari sejak umur yang ditetapkan, menghindari perubahan lingkungan mendadak, dan berjalan sambil mengamati babi.","Memahami bahwa rangsangan feromon mempercepat kematangan seksual dan babi muda lemah terhadap stres, dan bisa mengajari karyawan baru cara menjalankan adaptasi."]},{"id":"health-observe","name":"健康・脚・群内の様子の観察","kanten":"届いた候補豚の食欲・歩様・体型の変化と、群内でいじめられていないか、エサを食べられているかを毎日見て異常に気づけるか。","levels":["観察せず、食べていない豚やいじめられている豚、脚を引きずる豚がいても気づかない。","指示があれば見回るが、食欲や歩様の変化の見落としが多く、気づいても伝えない。","指示があれば食欲・歩様・体型を見て、群内でいじめられて食べられない豚を見つけて報告できる。","指示がなくても毎日の見回りで食欲・脚・太りすぎ痩せすぎを確認し、導入時に問題がなくても後から出る関節の異常に気づいて報告する。","若い豚は環境の変化に弱いことや脚の問題が長期の使用に響くことを理解し、観察の見どころを新人に指導できる。"],"name_en":"Observing health, legs, and behavior in the group","name_vi":"Quan sát sức khỏe, chân và tình hình trong đàn","name_id":"Pengamatan kesehatan, kaki, dan keadaan dalam kelompok","kanten_en":"Can they look every day at the arrived gilts' appetite, gait, and body shape, and whether they are being bullied or getting to the feed, and notice abnormalities?","kanten_vi":"Có hằng ngày quan sát sự thèm ăn, dáng đi, dáng người của lợn hậu bị vừa về, xem có bị ăn hiếp và có ăn được thức ăn không để nhận ra bất thường không.","kanten_id":"Apakah setiap hari mengamati nafsu makan, cara jalan, dan bentuk tubuh babi calon induk yang tiba, serta apakah ada yang diganggu atau bisa makan, dan menyadari kelainan.","levels_en":["Does not observe, and does not notice pigs that are not eating, being bullied, or dragging a leg.","With guidance, does rounds, but often misses changes in appetite and gait, and does not report even when noticed.","With guidance, looks at appetite, gait, and body shape, and can find and report pigs that are bullied in the group and cannot eat.","Independently checks appetite, legs, and over- or under-condition on daily rounds, and notices and reports joint problems that appear later even if there was no problem at arrival.","Understands that young pigs are weak against environmental change and that leg problems affect long-term use, and can teach new staff what to watch for."],"levels_vi":["Không quan sát, lợn không ăn, lợn bị ăn hiếp hay lợn đi khập khiễng cũng không nhận ra.","Nếu có chỉ dẫn thì đi tuần, nhưng hay bỏ sót thay đổi về thèm ăn và dáng đi, nhận ra cũng không báo.","Nếu có chỉ dẫn thì xem thèm ăn, dáng đi, dáng người, tìm ra và báo cáo lợn bị ăn hiếp trong đàn nên không ăn được.","Không cần chỉ dẫn cũng khi đi tuần hằng ngày kiểm tra thèm ăn, chân, quá béo hay quá gầy, và nhận ra, báo cáo vấn đề khớp xuất hiện về sau dù lúc nhập không có vấn đề.","Hiểu lợn non dễ bị ảnh hưởng khi môi trường thay đổi và vấn đề ở chân ảnh hưởng đến việc dùng lâu dài, và có thể hướng dẫn người mới điểm cần quan sát."],"levels_id":["Tidak mengamati, dan tidak sadar walau ada babi yang tidak makan, diganggu, atau menyeret kakinya.","Jika ada instruksi berkeliling, tetapi sering terlewat perubahan nafsu makan dan cara jalan, dan tidak melapor walau sadar.","Jika ada instruksi, bisa melihat nafsu makan, cara jalan, dan bentuk tubuh, serta menemukan dan melaporkan babi yang diganggu dalam kelompok sehingga tidak bisa makan.","Tanpa instruksi pun, memeriksa nafsu makan, kaki, dan terlalu gemuk atau kurus saat berkeliling setiap hari, dan menyadari serta melaporkan kelainan sendi yang muncul belakangan walau saat masuk tidak ada masalah.","Memahami bahwa babi muda lemah terhadap perubahan lingkungan dan masalah kaki memengaruhi pemakaian jangka panjang, dan bisa mengajari karyawan baru hal yang perlu diamati."]},{"id":"record-merge","name":"記録と群への合流前の最終確認","kanten":"個体番号・体重・乳頭数・発情日を記録用紙に残し、合流前に体重・BCS・肢蹄・健康を確認して、基準外の豚は上長に伝えられるか。","levels":["記録を残さず、確認もせずに群へ入れ、基準に満たない豚も黙って混ぜる。","指示があれば記録するが、個体番号や体重の記入漏れが多く、合流前の確認も抜けがち。","指示があれば個体番号・体重・乳頭数・発情日を記入し、体重・BCS・肢蹄・健康をひと通り確認して合流できる。","指示がなくても初回発情と2回目以降の発情を区別して記録し、合流前に最終確認して、基準外の豚は早めに上長へ伝えて判断をあおぐ。","記録と最終確認が将来の初産成績を左右することを理解し、記入と合流前確認の型を新人に指導できる。"],"name_en":"Records and final check before joining the herd","name_vi":"Ghi chép và kiểm tra lần cuối trước khi nhập đàn","name_id":"Pencatatan dan pemeriksaan akhir sebelum bergabung ke kelompok","kanten_en":"Can they keep each pig's ID number, weight, teat count, and heat dates on the record sheet, check weight, BCS, legs, and health before joining, and tell the supervisor about pigs that fall outside the standard?","kanten_vi":"Có ghi số hiệu, cân nặng, số vú, ngày động dục của từng con vào giấy ghi chép, kiểm tra cân nặng, BCS, chân móng, sức khỏe trước khi nhập đàn, và báo cấp trên về lợn không đạt tiêu chuẩn không.","kanten_id":"Apakah mencatat nomor identitas, berat badan, jumlah puting, dan tanggal birahi di lembar catatan, memeriksa berat badan, BCS, kaki, dan kesehatan sebelum bergabung, dan melapor ke atasan jika ada babi yang tidak memenuhi standar.","levels_en":["Keeps no records, puts pigs into the group without checking, and quietly mixes in pigs that do not meet the standard.","With guidance, records, but often leaves out ID numbers and weights, and the check before joining is often missed.","With guidance, writes ID number, weight, teat count, and heat dates, and can check weight, BCS, legs, and health adequately before joining.","Independently records first heat and second-or-later heat separately, does a final check before joining, and tells the supervisor early about pigs outside the standard to get a decision.","Understands that records and the final check affect first-litter performance later, and can teach new staff the routine of recording and pre-joining checks."],"levels_vi":["Không ghi chép, không kiểm tra mà cho vào đàn, lợn chưa đạt tiêu chuẩn cũng lặng lẽ trộn vào.","Nếu có chỉ dẫn thì ghi chép, nhưng hay sót số hiệu và cân nặng, việc kiểm tra trước khi nhập đàn cũng hay bị bỏ sót.","Nếu có chỉ dẫn thì ghi số hiệu, cân nặng, số vú, ngày động dục, kiểm tra cơ bản cân nặng, BCS, chân móng, sức khỏe rồi cho nhập đàn được.","Không cần chỉ dẫn cũng ghi phân biệt lần động dục đầu và từ lần thứ hai, kiểm tra lần cuối trước khi nhập đàn, lợn không đạt tiêu chuẩn thì báo sớm cho cấp trên để xin quyết định.","Hiểu ghi chép và kiểm tra lần cuối quyết định thành tích lứa đẻ đầu sau này, và có thể hướng dẫn người mới nề nếp ghi chép và kiểm tra trước khi nhập đàn."],"levels_id":["Tidak mencatat, memasukkan ke kelompok tanpa memeriksa, dan diam-diam mencampurkan babi yang tidak memenuhi standar.","Jika ada instruksi bisa mencatat, tetapi sering lupa nomor identitas dan berat badan, dan pemeriksaan sebelum bergabung juga sering terlewat.","Jika ada instruksi, bisa menulis nomor identitas, berat badan, jumlah puting, dan tanggal birahi, serta memeriksa berat badan, BCS, kaki, dan kesehatan secara garis besar sebelum bergabung.","Tanpa instruksi pun, mencatat birahi pertama dan birahi kedua dan seterusnya secara terpisah, melakukan pemeriksaan akhir sebelum bergabung, dan segera melapor ke atasan untuk meminta keputusan jika ada babi di luar standar.","Memahami bahwa pencatatan dan pemeriksaan akhir menentukan kinerja beranak pertama nanti, dan bisa mengajari karyawan baru pola pencatatan dan pemeriksaan sebelum bergabung."]}],"name_en":"Receiving Replacement Gilts","purposeShort_en":"Receive arriving gilts (future sows) safely without bringing in disease, get them used to the environment, and bring them into the herd in good health","name_vi":"Tiếp nhận lợn hậu bị","purposeShort_vi":"Tiếp nhận an toàn lợn hậu bị (nái tương lai) vừa về mà không mang mầm bệnh vào, cho quen môi trường rồi nhập đàn trong tình trạng khỏe mạnh","name_id":"Penerimaan babi calon induk","purposeShort_id":"Menerima babi calon induk (induk masa depan) yang tiba dengan aman tanpa membawa penyakit, membiasakannya dengan lingkungan, dan menggabungkannya ke kelompok dalam keadaan sehat"},{"id":"farrow-entry","category":"farrowing","no":"No.26","name":"入室（分娩舎）","purposeShort":"分娩が近い母豚だけを入れ、落ち着いた状態で分娩を迎えさせる","gyomu":"26","name_en":"Entry (Farrowing House)","name_vi":"Đưa nái vào chuồng đẻ","name_id":"Memasukkan induk ke kandang beranak","purposeShort_en":"Move in only sows close to farrowing so they can farrow in a calm state","purposeShort_vi":"Chỉ đưa lợn nái sắp đẻ vào, để nái đón cuộc đẻ trong trạng thái yên tĩnh","purposeShort_id":"Memasukkan hanya induk babi yang hampir melahirkan, agar melahirkan dalam keadaan tenang","aspects":[{"id":"prep-before","name":"入室前の舎内準備","kanten":"入室前に床・温度・水・エサと分娩クレートの洗浄・乾燥を整えられるか。","levels":["分娩舎の温度・保温灯を確認せず、クレート洗浄・乾燥も未完了のまま入室させ、子豚低体温死を招く。","指示があれば準備するが、温度設定やクレート乾燥の確認に漏れがある。","指示があれば床・温度・水・エサをひと通り整えられる。","指示がなくても入室前に温度・保温灯・水・エサとクレートの洗浄・乾燥を確認する。","入室前準備が子豚の生存に直結すると理解し、準備の要点を新人に指導できる。"],"name_en":"House Preparation Before Entry","kanten_en":"Can they prepare the floor, temperature, water, and feed, and wash and dry the farrowing crates before entry?","levels_en":["Moves sows in without checking the house temperature or heat lamps and with crates not yet washed and dried, causing piglet deaths from hypothermia.","With guidance can prepare, but misses the temperature settings or the crate-drying check.","With guidance can set up the floor, temperature, water, and feed through the basic procedure.","Independently checks temperature, heat lamps, water, feed, and crate washing and drying before entry.","Understands that pre-entry preparation directly affects piglet survival, and can teach new staff the key points of preparation."],"name_vi":"Chuẩn bị trong chuồng trước khi đưa lợn vào","kanten_vi":"Trước khi đưa lợn vào, có chuẩn bị sàn, nhiệt độ, nước, thức ăn và rửa, làm khô cũi đẻ không.","levels_vi":["Không kiểm tra nhiệt độ và đèn sưởi ấm của chuồng đẻ, đưa lợn vào khi cũi chưa rửa, chưa khô, khiến lợn con chết vì hạ thân nhiệt.","Nếu được chỉ thị thì chuẩn bị, nhưng còn thiếu sót về kiểm tra cài đặt nhiệt độ và độ khô của cũi.","Nếu được chỉ thị thì chuẩn bị sàn, nhiệt độ, nước, thức ăn được cơ bản.","Dù không có chỉ thị vẫn kiểm tra nhiệt độ, đèn sưởi ấm, nước, thức ăn và việc rửa, làm khô cũi trước khi đưa lợn vào.","Hiểu việc chuẩn bị trước khi vào chuồng liên quan trực tiếp đến sự sống của lợn con, và có thể hướng dẫn người mới các điểm chính của việc chuẩn bị."],"name_id":"Menyiapkan kandang sebelum babi masuk","kanten_id":"Apakah sebelum babi masuk dapat menyiapkan lantai, suhu, air, pakan, serta mencuci dan mengeringkan farrowing crate?","levels_id":["Tidak memeriksa suhu dan lampu pemanas kandang beranak, memasukkan babi sebelum farrowing crate selesai dicuci dan dikeringkan, sehingga anak babi mati kedinginan.","Menyiapkan jika diperintah, tetapi sering lalai memeriksa pengaturan suhu dan kekeringan crate.","Jika diperintah, dapat menyiapkan lantai, suhu, air, dan pakan secara lengkap.","Tanpa diperintah pun, sebelum babi masuk memeriksa suhu, lampu pemanas, air, pakan, serta pencucian dan pengeringan crate.","Memahami bahwa persiapan sebelum masuk langsung menentukan hidup mati anak babi, dan dapat mengajarkan pokok persiapan kepada karyawan baru."]},{"id":"batch-entry","name":"適期の一斉入室と入室後観察","kanten":"分娩が近い母豚をロットごとに一斉入室させ、途中追加を避け、入室後の体調・行動を観察できるか。","levels":["入室タイミングが遅れて妊娠舎で分娩させ、入室後の観察も怠る。","指示があれば入室させるが、タイミングや一斉入室の管理に漏れがある。","指示があればロットごとに一斉入室させ、ひと通り観察できる。","指示がなくても適期にロット単位で入室させ、途中追加を避けて入室後を観察する。","オールイン・オールアウトの意義を理解し、適期入室と観察を新人に指導できる。"],"name_en":"Timely Batch Entry and Observation After Entry","kanten_en":"Can they move sows close to farrowing in by lot all at once, avoid mid-batch additions, and observe condition and behavior after entry?","levels_en":["Moves sows in too late so they farrow in the gestation house, and neglects observation after entry.","With guidance can move sows in, but misses the timing or batch-entry management.","With guidance can move sows in by lot all at once and observe them through the basic routine.","Independently moves sows in by lot at the right time, avoids mid-batch additions, and observes them after entry.","Understands the value of all-in/all-out, and can teach new staff timely entry and observation."],"name_vi":"Đưa vào đồng loạt đúng thời điểm và theo dõi sau khi vào","kanten_vi":"Có đưa lợn nái sắp đẻ vào đồng loạt theo từng lô, tránh bổ sung giữa chừng, theo dõi thể trạng và hành vi sau khi vào không.","levels_vi":["Đưa vào muộn khiến nái đẻ ở chuồng mang thai, cũng lơ là theo dõi sau khi vào.","Nếu được chỉ thị thì đưa lợn vào, nhưng còn thiếu sót về thời điểm và quản lý đưa vào đồng loạt.","Nếu được chỉ thị thì đưa vào đồng loạt theo lô và theo dõi được cơ bản.","Dù không có chỉ thị vẫn đưa vào theo lô đúng thời điểm, tránh bổ sung giữa chừng và theo dõi sau khi vào.","Hiểu ý nghĩa của cùng vào - cùng ra (all-in all-out), và có thể hướng dẫn người mới việc đưa vào đúng thời điểm và theo dõi."],"name_id":"Memasukkan serentak pada waktu yang tepat dan mengawasi setelahnya","kanten_id":"Apakah dapat memasukkan induk babi yang hampir melahirkan serentak per kelompok (lot), menghindari penambahan di tengah jalan, dan mengawasi kondisi tubuh dan tingkah lakunya setelah masuk?","levels_id":["Terlambat memasukkan sehingga babi melahirkan di kandang bunting, dan lalai mengawasi setelah masuk.","Memasukkan jika diperintah, tetapi sering lalai soal waktu dan pengaturan masuk serentak.","Jika diperintah, dapat memasukkan serentak per kelompok (lot) dan mengawasinya secara lengkap.","Tanpa diperintah pun, memasukkan per kelompok (lot) pada waktu yang tepat, menghindari penambahan di tengah jalan, dan mengawasi setelah masuk.","Memahami arti sistem all-in all-out, dan dapat mengajarkan waktu masuk yang tepat dan pengawasan kepada karyawan baru."]},{"id":"calm-move","name":"静かな誘導と人の安全","kanten":"走らせない・たたかないで静かに誘導し、母豚の真後ろに立たず仕切り板を正しく使えるか。","levels":["母豚を走らせたり大声・たたく扱いをし、真後ろに立つなど危険な位置取りをしても気にしない。","指示があれば静かに誘導しようとするが、仕切り板の使い方や立ち位置にムラがあり、慌てると乱暴になる。","指示があれば通路の逃げ道をふさぎ、仕切り板で方向をつくって静かにゆっくり誘導できる。","指示がなくても事前に通路を整え、真後ろを避けた位置取りで安全に誘導し、興奮した母豚には無理をしない。","驚かせるストレスが流産や事故につながる原理を理解し、安全な誘導のやり方と立ち位置を新人に指導できる。"],"name_en":"Calm Moving and Human Safety","kanten_en":"Can they move sows calmly without making them run or hitting them, stay out of the spot directly behind the sow, and use the sorting board correctly?","levels_en":["Makes sows run, shouts at or hits them, and takes dangerous positions such as standing directly behind the sow without concern.","With guidance tries to move sows calmly, but is inconsistent with the sorting board and positioning, and becomes rough when flustered.","With guidance can block escape gaps in the aisle, use the sorting board to set the direction, and move sows calmly and slowly.","Independently prepares the aisle in advance, positions away from directly behind the sow to move her safely, and does not force an agitated sow.","Understands how the stress of startling sows leads to abortion and accidents, and can teach new staff safe moving methods and positioning."],"name_vi":"Lùa nhẹ nhàng và an toàn cho người","kanten_vi":"Có lùa nhẹ nhàng không bắt chạy, không đánh, không đứng ngay sau lợn nái và dùng tấm chắn đúng cách không.","levels_vi":["Bắt lợn nái chạy, quát to, đánh lợn, đứng ngay sau nái, không quan tâm dù đứng ở vị trí nguy hiểm.","Nếu được chỉ thị thì cố lùa nhẹ nhàng, nhưng cách dùng tấm chắn và vị trí đứng chưa đều, khi cuống lại thô bạo.","Nếu được chỉ thị thì bịt lối thoát trên lối đi, dùng tấm chắn tạo hướng đi và lùa nhẹ nhàng, từ từ được.","Dù không có chỉ thị vẫn chuẩn bị lối đi trước, đứng tránh vị trí ngay sau nái để lùa an toàn, không ép nái đang kích động.","Hiểu nguyên lý stress do làm nái hoảng sợ dẫn đến sảy thai và tai nạn, và có thể hướng dẫn người mới cách lùa an toàn và vị trí đứng."],"name_id":"Menggiring dengan tenang dan keselamatan orang","kanten_id":"Apakah dapat menggiring dengan tenang tanpa membuat lari atau memukul, tidak berdiri tepat di belakang induk babi, dan memakai papan sekat dengan benar?","levels_id":["Membuat induk babi lari, berteriak atau memukul, dan tidak peduli walau mengambil posisi berbahaya seperti berdiri tepat di belakang induk.","Jika diperintah berusaha menggiring dengan tenang, tetapi cara memakai papan sekat dan posisi berdiri tidak konsisten, dan menjadi kasar saat panik.","Jika diperintah, dapat menutup celah jalan kabur di lorong, membuat arah dengan papan sekat, dan menggiring dengan tenang dan perlahan.","Tanpa diperintah pun, menyiapkan lorong lebih dulu, mengambil posisi menghindari tepat di belakang induk agar menggiring dengan aman, dan tidak memaksa induk yang sedang gelisah.","Memahami prinsip bahwa stres karena dikagetkan menyebabkan keguguran dan kecelakaan, dan dapat mengajarkan cara menggiring yang aman dan posisi berdiri kepada karyawan baru."]},{"id":"id-check","name":"個体番号の照合と記入","kanten":"入室時に個体番号とストール番号をその場で照合し、プレート・記録に正しく残せるか。","levels":["番号を照合せずに母豚を入れ、プレートの記入漏れ・書きちがいがあっても放置する。","指示があれば記入するが、照合があいまいで確認は他者まかせ。","指示があれば個体番号とストール番号をその場で照合し、プレートに正しく記入できる。","指示がなくても全頭を照合・記入し、リストと合わない個体に気づけばその場で確かめて報告する。","番号ちがいが後の記録全部をくるわせることを理解し、照合と記入のやり方を新人に指導できる。"],"name_en":"Checking and Recording ID Numbers","kanten_en":"Can they check the sow's ID number against the stall number on the spot at entry, and record it correctly on the sow card and records?","levels_en":["Puts sows in without checking numbers, and leaves missing or wrong entries on the sow card unaddressed.","With guidance can record, but checks numbers vaguely and leaves confirmation to others.","With guidance can check the ID number against the stall number on the spot and record it correctly on the sow card.","Independently checks and records every sow, and on noticing a sow that does not match the list, confirms on the spot and reports it.","Understands that a wrong number throws off all later records, and can teach new staff how to check and record."],"name_vi":"Đối chiếu và ghi số tai","kanten_vi":"Khi đưa vào chuồng, có đối chiếu ngay tại chỗ số tai với số cũi, và ghi đúng vào bảng thẻ, sổ ghi chép không.","levels_vi":["Đưa lợn nái vào mà không đối chiếu số, bảng thẻ ghi thiếu hay ghi sai cũng bỏ mặc.","Nếu được chỉ thị thì ghi, nhưng đối chiếu mơ hồ và phó mặc người khác kiểm tra.","Nếu được chỉ thị thì đối chiếu ngay tại chỗ số tai với số cũi và ghi đúng vào bảng thẻ được.","Dù không có chỉ thị vẫn đối chiếu, ghi chép cho tất cả các con, nếu thấy con không khớp với danh sách thì kiểm tra ngay tại chỗ và báo cáo.","Hiểu rằng sai số sẽ làm sai toàn bộ ghi chép sau này, và có thể hướng dẫn người mới cách đối chiếu và ghi chép."],"name_id":"Mencocokkan dan mencatat nomor telinga","kanten_id":"Apakah saat masuk dapat mencocokkan nomor telinga dengan nomor kandang di tempat, dan mencatatnya dengan benar di papan plat dan catatan?","levels_id":["Memasukkan induk babi tanpa mencocokkan nomor, dan membiarkan walau ada catatan papan plat yang kosong atau salah tulis.","Mencatat jika diperintah, tetapi pencocokannya samar dan pemastian diserahkan ke orang lain.","Jika diperintah, dapat mencocokkan nomor telinga dengan nomor kandang di tempat dan mencatatnya dengan benar di papan plat.","Tanpa diperintah pun, mencocokkan dan mencatat semua induk, dan jika menemukan induk yang tidak cocok dengan daftar, memastikan di tempat lalu melaporkan.","Memahami bahwa nomor yang salah mengacaukan semua catatan selanjutnya, dan dapat mengajarkan cara mencocokkan dan mencatat kepada karyawan baru."]},{"id":"after-entry","name":"入室直後の飲水・初回給餌","kanten":"入室直後に全頭が水を飲めるか実際に確かめ、最初のエサを農場の指示どおり少量から与えられるか。","levels":["入室後の飲水確認をせず、最初から多量のエサを与えても気にしない。","指示があれば確認するが、実際に飲む様子まで見ず、給餌量にもムラがある。","指示があれば全頭が実際に水を飲む様子を確かめ、最初のエサを指示どおり少量から与えられる。","指示がなくても全頭の飲水と採食を確かめ、飲めない・食べない個体に気づけばニップルの詰まりなどを調べて報告する。","急な多給や飲水不足が母豚の体調をくずすことを理解し、入室直後の確認のやり方を新人に指導できる。"],"name_en":"Water Check and First Feeding Right After Entry","kanten_en":"Can they actually confirm every sow can drink water right after entry, and give the first feed starting from a small amount as the farm instructs?","levels_en":["Does not check drinking after entry, and gives a large amount of feed from the start without concern.","With guidance can check, but does not watch the sows actually drink, and feed amounts are inconsistent.","With guidance can confirm every sow actually drinks water, and give the first feed starting from a small amount as instructed.","Independently confirms every sow drinks and eats, and on noticing a sow that cannot drink or eat, checks for a clogged nipple and the like and reports it.","Understands that sudden overfeeding and lack of water upset the sow's condition, and can teach new staff how to check right after entry."],"name_vi":"Kiểm tra uống nước và cho ăn lần đầu ngay sau khi vào","kanten_vi":"Ngay sau khi vào chuồng, có kiểm tra thực tế tất cả các con uống được nước không, và cho cữ ăn đầu tiên từ lượng ít theo đúng chỉ thị của trại không.","levels_vi":["Không kiểm tra uống nước sau khi vào, cho ăn nhiều ngay từ đầu cũng không quan tâm.","Nếu được chỉ thị thì kiểm tra, nhưng không nhìn tận mắt cảnh nái uống nước, lượng cám cho ăn cũng không đều.","Nếu được chỉ thị thì kiểm tra tận mắt tất cả các con uống nước, cho cữ ăn đầu tiên từ lượng ít theo đúng chỉ thị được.","Dù không có chỉ thị vẫn kiểm tra tất cả các con uống nước và ăn cám, nếu thấy con không uống, không ăn thì kiểm tra núm uống nước có tắc không rồi báo cáo.","Hiểu rằng cho ăn nhiều đột ngột và thiếu nước uống làm lợn nái suy sụp thể trạng, và có thể hướng dẫn người mới cách kiểm tra ngay sau khi vào chuồng."],"name_id":"Memeriksa minum dan pemberian pakan pertama segera setelah masuk","kanten_id":"Apakah segera setelah masuk dapat benar-benar memastikan semua induk bisa minum air, dan memberi pakan pertama mulai dari jumlah sedikit sesuai perintah peternakan?","levels_id":["Tidak memeriksa minum setelah masuk, dan tidak peduli walau memberi pakan banyak sejak awal.","Memeriksa jika diperintah, tetapi tidak melihat langsung induk benar-benar minum, dan jumlah pakan tidak konsisten.","Jika diperintah, dapat memastikan semua induk benar-benar minum air, dan memberi pakan pertama mulai dari jumlah sedikit sesuai perintah.","Tanpa diperintah pun, memastikan semua induk minum dan makan, dan jika ada induk yang tidak bisa minum atau makan, memeriksa misalnya nipple yang tersumbat lalu melaporkan.","Memahami bahwa pemberian pakan banyak secara mendadak dan kekurangan air minum merusak kondisi induk babi, dan dapat mengajarkan cara pemeriksaan segera setelah masuk kepada karyawan baru."]}]},{"id":"farrow-assist","category":"farrowing","no":"No.35","name":"分娩介助","purposeShort":"母豚と子豚の命を守り、死産・直後の死亡を減らし初乳を飲ませる","gyomu":"35","name_en":"Farrowing Assistance","name_vi":"Hỗ trợ đỡ đẻ","name_id":"Membantu proses kelahiran","purposeShort_en":"Protect the lives of sows and piglets, reduce stillbirths and early deaths, and ensure colostrum intake","purposeShort_vi":"Bảo vệ tính mạng lợn nái và lợn con, giảm chết lưu, chết ngay sau đẻ và cho bú sữa đầu","purposeShort_id":"Melindungi nyawa induk dan anak babi, mengurangi lahir mati dan kematian setelah lahir, serta memberi kolostrum (susu pertama)","aspects":[{"id":"timing","name":"介助タイミングの見極めと難産の報告","kanten":"分娩間隔を計り、前の子豚から1時間以上出ない時だけ介助に入り、難産のサインをすぐ報告できるか。","levels":["分娩間隔を見ずに放置するか、逆にむやみに手を入れ、難産のサインがあっても報告しない。","指示があれば介助するが、分娩間隔の見極めが甘く、介助に入るかの判断は他者まかせ。","指示があれば見回りで分娩間隔を計り、前の子豚から1時間以上出ない時に手順どおり介助へ移れる。","指示がなくても最低30分おきの見回りで間隔を把握し、迷えば手を入れる前に報告し、難産のサインに気づけばすぐ先輩・獣医へ連絡する。","介助の遅れが低酸素・死産につながる原理を理解し、介助に入る見極めと難産サインの見分け方を新人に指導できる。"],"name_en":"Judging When to Assist and Reporting Dystocia","kanten_en":"Can they time the birth intervals, assist only when no piglet has come for over an hour since the last, and report signs of dystocia right away?","levels_en":["Leaves the sow unattended without watching birth intervals, or puts a hand in needlessly, and does not report even when there are signs of dystocia.","With guidance can assist, but judges birth intervals poorly and leaves the decision to assist to others.","With guidance can time birth intervals on rounds, and move to assist by the procedure when no piglet has come for over an hour since the last.","Independently tracks the intervals with rounds at least every 30 minutes, reports before putting a hand in when unsure, and on noticing signs of dystocia contacts a senior or the vet right away.","Understands how delayed assistance leads to hypoxia and stillbirth, and can teach new staff how to judge when to assist and how to spot signs of dystocia."],"name_vi":"Phán đoán thời điểm can thiệp và báo cáo đẻ khó","kanten_vi":"Có đo khoảng cách giữa các lần đẻ, chỉ can thiệp khi quá 1 tiếng kể từ con trước mà lợn con không ra, và báo ngay dấu hiệu đẻ khó không.","levels_vi":["Không theo dõi khoảng cách giữa các lần đẻ mà bỏ mặc, hoặc ngược lại tùy tiện đưa tay vào, có dấu hiệu đẻ khó cũng không báo.","Nếu được chỉ thị thì can thiệp, nhưng phán đoán khoảng cách đẻ còn kém, việc quyết định can thiệp phó mặc người khác.","Nếu được chỉ thị thì đo khoảng cách giữa các lần đẻ khi đi kiểm tra, và chuyển sang can thiệp theo đúng trình tự khi quá 1 tiếng kể từ con trước mà lợn con không ra.","Dù không có chỉ thị vẫn đi kiểm tra ít nhất 30 phút một lần để nắm khoảng cách đẻ, khi phân vân thì báo cáo trước khi đưa tay vào, thấy dấu hiệu đẻ khó thì liên lạc ngay với người hướng dẫn hoặc bác sĩ thú y.","Hiểu nguyên lý can thiệp chậm dẫn đến thiếu oxy, chết lưu, và có thể hướng dẫn người mới cách phán đoán khi nào can thiệp và cách nhận biết dấu hiệu đẻ khó."],"name_id":"Menilai waktu membantu dan melaporkan kesulitan melahirkan","kanten_id":"Apakah dapat mengukur jarak waktu antar kelahiran, masuk membantu hanya saat lebih dari 1 jam sejak anak sebelumnya tidak ada yang keluar, dan segera melaporkan tanda kesulitan melahirkan?","levels_id":["Membiarkan tanpa melihat jarak waktu antar kelahiran, atau sebaliknya sembarangan memasukkan tangan, dan tidak melaporkan walau ada tanda kesulitan melahirkan.","Membantu jika diperintah, tetapi penilaian jarak waktu antar kelahiran lemah dan keputusan untuk membantu diserahkan ke orang lain.","Jika diperintah, dapat mengukur jarak waktu antar kelahiran saat berkeliling, dan mulai membantu sesuai prosedur saat lebih dari 1 jam sejak anak sebelumnya tidak ada yang keluar.","Tanpa diperintah pun, memantau jarak kelahiran dengan berkeliling minimal setiap 30 menit, jika ragu melapor sebelum memasukkan tangan, dan jika melihat tanda kesulitan melahirkan segera menghubungi senior atau dokter hewan.","Memahami prinsip bahwa keterlambatan membantu menyebabkan kekurangan oksigen dan lahir mati, dan dapat mengajarkan penilaian kapan harus membantu serta cara mengenali tanda kesulitan melahirkan kepada karyawan baru."]},{"id":"clean-assist","name":"清潔と潤滑の徹底","kanten":"介助前に肘まで洗浄・消毒し、長手袋と潤滑剤を使って清潔に産道へ手を入れられるか。","levels":["手洗い・消毒をせず素手や汚れた手袋のまま介助し、潤滑剤も使わない。","指示があれば手袋を着けるが、肘までの洗浄・消毒や潤滑剤の塗り方に抜けがある。","指示があれば石けんで肘まで洗って消毒し、長手袋の上から潤滑剤を塗って手順どおり介助できる。","指示がなくても毎回清潔と潤滑を徹底し、母豚の力みに合わせて引き出し、産道に別の子豚が残っていないかも確かめる。","不潔な介助が子宮炎から無乳・子豚の飢餓につながる流れを理解し、清潔操作を新人に指導できる。"],"name_en":"Thorough Cleanliness and Lubrication","kanten_en":"Can they wash and disinfect up to the elbows before assisting, and enter the birth canal cleanly using long gloves and lubricant?","levels_en":["Assists bare-handed or with dirty gloves without washing or disinfecting, and uses no lubricant.","With guidance puts on gloves, but misses washing and disinfecting up to the elbows or how to apply the lubricant.","With guidance can wash up to the elbows with soap, disinfect, apply lubricant over the long gloves, and assist by the procedure.","Independently keeps thorough cleanliness and lubrication every time, pulls the piglet out in time with the sow's straining, and also checks that no other piglet remains in the birth canal.","Understands how unclean assistance leads from metritis to no milk and piglet starvation, and can teach new staff clean technique."],"name_vi":"Triệt để sạch sẽ và bôi trơn","kanten_vi":"Trước khi can thiệp, có rửa, khử trùng đến tận khuỷu tay, dùng găng tay dài và gel bôi trơn để đưa tay vào đường sinh một cách sạch sẽ không.","levels_vi":["Không rửa tay, khử trùng, can thiệp bằng tay trần hoặc găng tay bẩn, cũng không dùng gel bôi trơn.","Nếu được chỉ thị thì đeo găng tay, nhưng còn thiếu sót về rửa, khử trùng đến khuỷu tay và cách bôi gel bôi trơn.","Nếu được chỉ thị thì rửa bằng xà phòng đến khuỷu tay và khử trùng, bôi gel bôi trơn bên ngoài găng tay dài và can thiệp theo đúng trình tự được.","Dù không có chỉ thị vẫn triệt để sạch sẽ, bôi trơn mỗi lần, kéo lợn con ra đúng lúc nái rặn, kiểm tra cả trong đường sinh còn con khác không.","Hiểu chuỗi can thiệp không sạch dẫn đến viêm tử cung rồi mất sữa, lợn con chết đói, và có thể hướng dẫn người mới thao tác sạch sẽ."],"name_id":"Menjaga kebersihan dan pelumasan dengan ketat","kanten_id":"Apakah sebelum membantu dapat mencuci dan mendisinfeksi sampai siku, lalu memasukkan tangan ke jalan lahir dengan bersih memakai sarung tangan panjang dan gel pelumas?","levels_id":["Membantu dengan tangan telanjang atau sarung tangan kotor tanpa mencuci dan disinfeksi, dan tidak memakai pelumas.","Memakai sarung tangan jika diperintah, tetapi ada yang terlewat dalam mencuci dan disinfeksi sampai siku serta cara mengoleskan pelumas.","Jika diperintah, dapat mencuci dengan sabun sampai siku dan disinfeksi, mengoleskan gel pelumas di atas sarung tangan panjang, dan membantu sesuai prosedur.","Tanpa diperintah pun, setiap kali menjaga kebersihan dan pelumasan dengan ketat, menarik anak keluar mengikuti saat induk mengejan, dan memeriksa juga apakah masih ada anak lain di jalan lahir.","Memahami alur bahwa bantuan yang tidak bersih menyebabkan radang rahim lalu susu tidak keluar dan anak babi kelaparan, dan dapat mengajarkan penanganan bersih kepada karyawan baru."]},{"id":"newborn-care","name":"新生子豚の乾燥・保温・蘇生","kanten":"生まれた子豚をすぐ乾かし温め、呼吸を確認し、仮死子豚を蘇生できるか。","levels":["子豚を乾かさず温めず、仮死子豚を死産と誤判断して蘇生処置を省く。","指示があれば処置するが、呼吸確認や蘇生の判断に漏れがある。","指示があれば子豚を乾かし温め、呼吸をひと通り確認できる。","指示がなくてもすぐ乾かして温め、仮死子豚を見分けて蘇生処置を行う。","仮死と死産の見分けや蘇生の意義を理解し、新生子豚の初期処置を新人に指導できる。"],"name_en":"Drying, Warming, and Resuscitating Newborn Piglets","kanten_en":"Can they dry and warm newborn piglets immediately, check breathing, and resuscitate piglets born in apparent lifelessness?","levels_en":["Does not dry or warm piglets, mistakes asphyxiated piglets for stillbirths, and skips resuscitation.","With guidance can treat piglets, but misses breathing checks or the decision to resuscitate.","With guidance can dry and warm piglets and check breathing through the basic routine.","Independently dries and warms piglets immediately, recognizes asphyxiated piglets, and performs resuscitation.","Understands how to distinguish asphyxia from stillbirth and the value of resuscitation, and can teach new staff the initial care of newborn piglets."],"name_vi":"Lau khô, giữ ấm, hồi sức lợn con sơ sinh","kanten_vi":"Có lau khô, sưởi ấm lợn con ngay sau khi sinh, kiểm tra hô hấp và hồi sức cho lợn con bị ngạt không.","levels_vi":["Không lau khô, không sưởi ấm lợn con, nhầm lợn con bị ngạt là chết lưu và bỏ qua hồi sức.","Nếu được chỉ thị thì xử lý, nhưng còn thiếu sót trong kiểm tra hô hấp và phán đoán hồi sức.","Nếu được chỉ thị thì lau khô, sưởi ấm lợn con và kiểm tra hô hấp được cơ bản.","Dù không có chỉ thị vẫn lau khô, sưởi ấm ngay, phân biệt được lợn con bị ngạt và tiến hành hồi sức.","Hiểu cách phân biệt ngạt với chết lưu và ý nghĩa của hồi sức, và có thể hướng dẫn người mới cách xử lý ban đầu cho lợn con sơ sinh."],"name_id":"Mengeringkan, menghangatkan, dan menghidupkan kembali anak babi baru lahir","kanten_id":"Apakah dapat segera mengeringkan dan menghangatkan anak babi yang lahir, memeriksa napasnya, dan menolong anak babi yang lemas seperti mati (asfiksia)?","levels_id":["Tidak mengeringkan dan menghangatkan anak babi, salah mengira anak babi lemas sebagai lahir mati, dan melewatkan pertolongan napas.","Menangani jika diperintah, tetapi sering lalai memeriksa napas dan menilai perlunya pertolongan.","Jika diperintah, dapat mengeringkan dan menghangatkan anak babi serta memeriksa napasnya secara lengkap.","Tanpa diperintah pun, segera mengeringkan dan menghangatkan, membedakan anak babi lemas dan melakukan pertolongan napas.","Memahami cara membedakan lemas dan lahir mati serta arti pertolongan napas, dan dapat mengajarkan penanganan awal anak babi baru lahir kepada karyawan baru."]},{"id":"colostrum","name":"初乳の早期摂取","kanten":"生まれた子豚に遅くとも生後6時間以内に初乳を飲ませ、吸えない子豚にも手を打てるか。","levels":["初乳を飲めているか気にせず放置し、吸えない子豚がいても何もしない。","指示があれば乳頭にあてがうが、実際に飲めたかの確認までせずムラがある。","指示があれば乳頭に子豚の口をあてがい、吸わない子豚には乳を搾って口にたらして飲ませられる。","指示がなくても全頭の初乳摂取を6時間以内に確かめ、弱い子豚を優先して確実に飲ませる。","生後24時間を過ぎると腸が閉じて免疫を吸収できなくなる原理を理解し、初乳管理を新人に指導できる。"],"name_en":"Early Colostrum Intake","kanten_en":"Can they get newborn piglets to drink colostrum within 6 hours of birth at the latest, and take action for piglets that cannot suckle?","levels_en":["Pays no attention to whether piglets are getting colostrum, and does nothing even when a piglet cannot suckle.","With guidance puts piglets to the teat, but does not confirm they actually drank, so results are inconsistent.","With guidance can put the piglet's mouth to the teat, and for piglets that will not suckle, milk the teat and drip it into their mouths.","Independently confirms colostrum intake for every piglet within 6 hours, giving weak piglets priority so they drink without fail.","Understands that past 24 hours after birth the gut closes and can no longer absorb immunity, and can teach new staff colostrum management."],"name_vi":"Cho bú sữa đầu sớm","kanten_vi":"Có cho lợn con mới sinh bú sữa đầu chậm nhất trong vòng 6 tiếng sau khi sinh, và có cách xử lý cho cả lợn con không bú được không.","levels_vi":["Không quan tâm lợn con có bú được sữa đầu không mà bỏ mặc, có con không bú được cũng không làm gì.","Nếu được chỉ thị thì áp miệng lợn con vào đầu vú, nhưng không kiểm tra đến mức con đã bú được thật chưa nên không đều.","Nếu được chỉ thị thì áp miệng lợn con vào đầu vú, con nào không bú thì vắt sữa nhỏ vào miệng cho bú được.","Dù không có chỉ thị vẫn kiểm tra tất cả các con bú sữa đầu trong vòng 6 tiếng, ưu tiên con yếu để cho bú chắc chắn.","Hiểu nguyên lý quá 24 tiếng sau sinh ruột sẽ đóng lại và không hấp thu được miễn dịch, và có thể hướng dẫn người mới cách quản lý sữa đầu."],"name_id":"Pemberian kolostrum sejak dini","kanten_id":"Apakah dapat membuat anak babi yang lahir minum kolostrum paling lambat dalam 6 jam setelah lahir, dan mengambil tindakan untuk anak babi yang tidak bisa mengisap?","levels_id":["Tidak peduli apakah anak babi minum kolostrum dan membiarkannya, tidak berbuat apa-apa walau ada anak yang tidak bisa mengisap.","Jika diperintah menempelkan anak ke puting, tetapi tidak memastikan sampai benar-benar minum sehingga hasilnya tidak konsisten.","Jika diperintah, dapat menempelkan mulut anak babi ke puting, dan untuk anak yang tidak mau mengisap, memerah susu dan meneteskannya ke mulut agar minum.","Tanpa diperintah pun, memastikan semua anak minum kolostrum dalam 6 jam, dan memprioritaskan anak yang lemah agar pasti minum.","Memahami prinsip bahwa lewat 24 jam setelah lahir usus menutup dan tidak bisa menyerap kekebalan lagi, dan dapat mengajarkan pengelolaan kolostrum kepada karyawan baru."]},{"id":"post-record","name":"分娩後の確認・記録・片付け","kanten":"胎盤の排出を確認し、分娩時刻・産子数・死産数・処置を記録し、胎盤やタオルを決められた場所へ片付けられるか。","levels":["胎盤の確認や記録をせず、使ったタオル・胎盤も片付けずに放置する。","指示があれば記録・片付けをするが、記入項目や処理場所に抜け漏れが多い。","指示があれば分娩後4時間以内に胎盤の排出を確かめ、記録用紙に分娩時刻・産子数・死産数・処置を記入して片付けられる。","指示がなくても胎盤残留やMMAが疑われる発熱・乳房の異常に気づいてすぐ報告し、汚物を舎外に持ち出さず決められた場所で処理する。","胎盤残留が子宮炎につながることを理解し、分娩後の確認・記録・防疫を意識した片付けを新人に指導できる。"],"name_en":"Post-Farrowing Checks, Records, and Cleanup","kanten_en":"Can they confirm the placenta has passed, record the farrowing time, litter size, stillbirths, and treatments, and dispose of the placenta and towels in the designated place?","levels_en":["Does not check the placenta or keep records, and leaves used towels and the placenta lying around.","With guidance records and cleans up, but leaves many gaps in the entries and the disposal place.","With guidance can confirm placental passage within 4 hours after farrowing, fill in the farrowing time, litter size, stillbirths, and treatments on the record sheet, and clean up.","Independently notices fever or udder abnormalities suggesting retained placenta or MMA and reports them right away, and processes waste in the designated place without carrying it out of the house.","Understands that a retained placenta leads to metritis, and can teach new staff post-farrowing checks, records, and biosecurity-minded cleanup."],"name_vi":"Kiểm tra, ghi chép và dọn dẹp sau khi đẻ","kanten_vi":"Có xác nhận nhau thai đã ra, ghi giờ đẻ, số con sinh ra, số con chết lưu và nội dung xử lý, rồi dọn nhau thai và khăn vào nơi quy định không.","levels_vi":["Không kiểm tra nhau thai, không ghi chép, khăn đã dùng và nhau thai cũng bỏ mặc không dọn.","Nếu được chỉ thị thì ghi chép, dọn dẹp, nhưng còn nhiều thiếu sót về mục ghi và nơi xử lý.","Nếu được chỉ thị thì xác nhận nhau thai đã ra trong vòng 4 tiếng sau khi đẻ, ghi vào giấy ghi chép giờ đẻ, số con sinh ra, số con chết lưu, nội dung xử lý rồi dọn dẹp được.","Dù không có chỉ thị vẫn nhận ra sốt hay bất thường ở bầu vú nghi sót nhau, MMA và báo cáo ngay, xử lý chất bẩn ở nơi quy định, không mang ra ngoài chuồng.","Hiểu rằng sót nhau dẫn đến viêm tử cung, và có thể hướng dẫn người mới cách kiểm tra, ghi chép sau đẻ và dọn dẹp có ý thức phòng dịch."],"name_id":"Pemeriksaan, pencatatan, dan pembersihan setelah melahirkan","kanten_id":"Apakah dapat memastikan plasenta sudah keluar, mencatat jam melahirkan, jumlah anak lahir, jumlah lahir mati, dan penanganan, lalu membereskan plasenta dan handuk ke tempat yang ditentukan?","levels_id":["Tidak memeriksa plasenta atau mencatat, dan membiarkan handuk bekas dan plasenta tanpa dibereskan.","Mencatat dan membereskan jika diperintah, tetapi banyak yang terlewat pada butir catatan dan tempat pembuangan.","Jika diperintah, dapat memastikan plasenta keluar dalam 4 jam setelah melahirkan, mengisi jam melahirkan, jumlah anak lahir, jumlah lahir mati, dan penanganan di kertas catatan, lalu membereskan.","Tanpa diperintah pun, menyadari demam atau kelainan ambing yang mencurigakan sisa plasenta atau MMA dan segera melaporkan, serta memproses kotoran di tempat yang ditentukan tanpa membawanya keluar kandang.","Memahami bahwa plasenta yang tertinggal menyebabkan radang rahim, dan dapat mengajarkan pemeriksaan, pencatatan setelah melahirkan, serta pembersihan yang sadar biosekuriti kepada karyawan baru."]}]},{"id":"cross-foster","category":"farrowing","no":"No.39","name":"送り里子","purposeShort":"乳頭数と子豚数のバランスを整え、離乳頭数を増やし弱子を助ける","gyomu":"39","name_en":"Cross-Fostering","name_vi":"Ghép bầy (cho nái khác nuôi)","name_id":"Titip anak ke induk lain","purposeShort_en":"Balance teat numbers and litter sizes, increase weaned piglets, and help weak piglets","purposeShort_vi":"Cân bằng số vú và số lợn con, tăng số con cai sữa và cứu con yếu","purposeShort_id":"Menyeimbangkan jumlah puting dan jumlah anak babi, menambah jumlah anak sapih, dan menolong anak yang lemah","aspects":[{"id":"colostrum-first","name":"初乳摂取後の里子と対象選び","kanten":"初乳を飲ませてから、日齢・体重が近い健康な子豚を組み合わせ、乳頭数を超えないよう里子に出せるか。","levels":["初乳摂取が不十分なまま移動させ、体重差の大きい子豚を混ぜ、乳頭数を超える頭数でも気にしない。","指示があれば里子に出すが、初乳確認や対象選びに漏れが多い。","指示があれば初乳を飲ませてから日齢・体重の近い子豚をひと通り組める。","指示がなくても初乳摂取後の生後12〜24時間に里子を実施し、体重差を抑えて乳頭数内に収める。","初乳と免疫獲得の関係を理解し、里子の対象選びと頭数管理を新人に指導できる。"],"name_en":"Fostering After Colostrum Intake and Selecting Candidates","kanten_en":"Can they foster only after colostrum intake, match healthy piglets of similar age and weight, and stay within the teat count?","levels_en":["Moves piglets with insufficient colostrum intake, mixes piglets with large weight differences, and does not care even when the count exceeds the number of teats.","With guidance can foster, but often misses the colostrum check or candidate selection.","With guidance can ensure colostrum intake first and match piglets of similar age and weight through the basic procedure.","Independently fosters at 12-24 hours after birth once colostrum has been taken, limits weight differences, and stays within the teat count.","Understands the relationship between colostrum and immunity, and can teach new staff candidate selection and litter-size management."],"name_vi":"Ghép bầy sau khi bú sữa đầu và chọn đối tượng","kanten_vi":"Có cho bú sữa đầu trước, ghép các lợn con khỏe mạnh có ngày tuổi, cân nặng gần nhau, không vượt quá số vú không.","levels_vi":["Chuyển đi khi chưa bú đủ sữa đầu, ghép lợn con chênh lệch cân nặng lớn, số con vượt quá số vú cũng không quan tâm.","Nếu được chỉ thị thì ghép bầy, nhưng hay thiếu sót về kiểm tra sữa đầu và chọn đối tượng.","Nếu được chỉ thị thì cho bú sữa đầu rồi ghép các con có ngày tuổi, cân nặng gần nhau một cách cơ bản.","Dù không có chỉ thị vẫn ghép bầy trong 12-24 giờ sau sinh, sau khi đã bú sữa đầu, hạn chế chênh lệch cân nặng và giữ trong số vú.","Hiểu quan hệ giữa sữa đầu và miễn dịch, và có thể hướng dẫn người mới cách chọn con ghép bầy và quản lý số con."],"name_id":"Menitipkan setelah minum kolostrum dan memilih sasaran","kanten_id":"Apakah menitipkan setelah anak minum kolostrum (susu pertama), memasangkan anak babi sehat yang umur dan beratnya berdekatan, dan tidak melebihi jumlah puting?","levels_id":["Memindahkan sebelum cukup minum kolostrum, mencampur anak babi yang beda beratnya besar, dan tidak peduli walau jumlahnya melebihi jumlah puting.","Menitipkan jika diperintah, tetapi sering lalai memastikan kolostrum dan memilih sasaran.","Jika diperintah, dapat memasangkan anak babi yang umur dan beratnya berdekatan secara lengkap setelah minum kolostrum.","Tanpa diperintah pun, menitipkan pada 12-24 jam setelah lahir sesudah minum kolostrum, menekan beda berat, dan menjaga jumlah dalam batas jumlah puting.","Memahami hubungan kolostrum dengan kekebalan, dan dapat mengajarkan pemilihan anak titipan dan pengaturan jumlah kepada karyawan baru."]},{"id":"health-exclude","name":"病気の子豚の除外と手指衛生","kanten":"下痢・呼吸異常のある子豚を里子に出さず、疑わしい子豚に触れたあと手袋交換・手指消毒ができるか。","levels":["健康チェックをせず病気の子豚も移し、疑わしい子豚に触れた手のまま健康な子豚を扱う。","指示があればチェックするが見落としが多く、手袋交換や手指消毒も抜けがち。","指示があれば移す前に下痢・呼吸の異常を確かめ、疑わしい子豚に触れたあとは手袋を替えるか消毒できる。","指示がなくても健康チェックと手指衛生を徹底し、判断に迷う子豚は移さず報告して指示をあおぐ。","里子が感染を広げる経路になることを理解し、健康チェックと衛生手順を新人に指導できる。"],"name_en":"Excluding Sick Piglets and Hand Hygiene","kanten_en":"Can they keep piglets with diarrhea or breathing problems out of fostering, and change gloves or disinfect their hands after touching a suspect piglet?","levels_en":["Moves sick piglets too without health checks, and handles healthy piglets with the same hands that touched a suspect piglet.","With guidance checks but misses many cases, and often skips glove changes and hand disinfection.","With guidance can check for diarrhea and breathing problems before moving, and change gloves or disinfect after touching a suspect piglet.","Independently keeps thorough health checks and hand hygiene, and does not move piglets they are unsure about but reports and asks for instructions.","Understands that fostering can become a route that spreads infection, and can teach new staff health checks and hygiene procedures."],"name_vi":"Loại lợn con bệnh và vệ sinh tay","kanten_vi":"Có không ghép bầy lợn con bị tiêu chảy, thở bất thường, và sau khi chạm vào con nghi bệnh có thay găng tay, khử trùng tay không.","levels_vi":["Không kiểm tra sức khỏe, chuyển cả lợn con bệnh, tay vừa chạm con nghi bệnh vẫn dùng để chăm con khỏe.","Nếu được chỉ thị thì kiểm tra nhưng bỏ sót nhiều, cũng hay quên thay găng tay, khử trùng tay.","Nếu được chỉ thị thì kiểm tra tiêu chảy, thở bất thường trước khi chuyển, sau khi chạm con nghi bệnh thì thay găng tay hoặc khử trùng được.","Dù không có chỉ thị vẫn triệt để kiểm tra sức khỏe và vệ sinh tay, con nào phân vân thì không chuyển mà báo cáo và xin chỉ thị.","Hiểu rằng ghép bầy có thể thành đường lây lan bệnh, và có thể hướng dẫn người mới cách kiểm tra sức khỏe và trình tự vệ sinh."],"name_id":"Menyisihkan anak babi sakit dan kebersihan tangan","kanten_id":"Apakah tidak menitipkan anak babi yang diare atau napasnya tidak normal, dan setelah menyentuh anak babi yang dicurigai dapat mengganti sarung tangan atau mendisinfeksi tangan?","levels_id":["Memindahkan juga anak babi sakit tanpa pemeriksaan kesehatan, dan menangani anak babi sehat dengan tangan yang baru menyentuh anak yang dicurigai.","Memeriksa jika diperintah tetapi banyak yang terlewat, dan sering lupa mengganti sarung tangan dan mendisinfeksi tangan.","Jika diperintah, dapat memeriksa diare dan kelainan napas sebelum memindah, dan setelah menyentuh anak yang dicurigai mengganti sarung tangan atau mendisinfeksi.","Tanpa diperintah pun, menjaga ketat pemeriksaan kesehatan dan kebersihan tangan, dan anak babi yang meragukan tidak dipindah melainkan dilaporkan untuk meminta petunjuk.","Memahami bahwa titip anak bisa menjadi jalur penyebaran infeksi, dan dapat mengajarkan pemeriksaan kesehatan dan prosedur kebersihan kepada karyawan baru."]},{"id":"move-handle","name":"静かな移動と受け入れ確認","kanten":"子豚を静かに抱えて1回で移し、母豚が受け入れるか見守り、拒否された時は無理をせず相談できるか。","levels":["子豚を乱暴に扱って何度も動かし、母豚が噛む・踏むなど拒否しても放置する。","指示があれば移せるが扱いが雑で、受け入れの見守りは他者まかせ。","指示があれば子豚を静かに抱えて1回で移し、移した直後の母豚の様子を見守れる。","指示がなくても冬は移動先の保温を先に確かめて短時間で移し、拒否されたら無理に押し付けず先輩に相談して別の母豚を検討する。","移動のくり返しがストレスで発育を止めることと母豚の咬みつきの危険を理解し、安全な移し方を新人に指導できる。"],"name_en":"Calm Moving and Acceptance Checks","kanten_en":"Can they carry the piglet calmly and move it in one go, watch whether the sow accepts it, and consult without forcing it when rejected?","levels_en":["Handles piglets roughly and moves them repeatedly, and leaves them even when the sow rejects them by biting or trampling.","With guidance can move piglets but handles them roughly, and leaves watching for acceptance to others.","With guidance can carry the piglet calmly, move it in one go, and watch the sow right after the move.","Independently checks the warmth at the destination first in winter and moves quickly, and when rejected does not force the piglet on the sow but consults a senior and considers another sow.","Understands that repeated moves stall growth through stress and that sow bites are dangerous, and can teach new staff safe moving."],"name_vi":"Chuyển nhẹ nhàng và kiểm tra nái nhận con","kanten_vi":"Có bế lợn con nhẹ nhàng, chuyển 1 lần là xong, theo dõi nái có nhận con không, khi bị từ chối thì không ép mà trao đổi được không.","levels_vi":["Xử lý lợn con thô bạo, chuyển đi chuyển lại nhiều lần, nái cắn hay giẫm để từ chối cũng bỏ mặc.","Nếu được chỉ thị thì chuyển được nhưng thao tác còn thô, việc theo dõi nái nhận con phó mặc người khác.","Nếu được chỉ thị thì bế lợn con nhẹ nhàng, chuyển 1 lần là xong, theo dõi được tình trạng nái ngay sau khi chuyển.","Dù không có chỉ thị, mùa đông vẫn kiểm tra việc giữ ấm ở chuồng nhận trước rồi chuyển nhanh, khi bị từ chối thì không ép mà trao đổi với người hướng dẫn để xem xét nái khác.","Hiểu rằng chuyển đi chuyển lại gây stress làm ngừng lớn và nguy hiểm khi nái cắn, và có thể hướng dẫn người mới cách chuyển an toàn."],"name_id":"Memindahkan dengan tenang dan memastikan induk menerima","kanten_id":"Apakah dapat menggendong anak babi dengan tenang dan memindahkannya dalam 1 kali, mengawasi apakah induk menerimanya, dan saat ditolak tidak memaksa melainkan berkonsultasi?","levels_id":["Menangani anak babi dengan kasar dan memindahkannya berkali-kali, dan membiarkan walau induk menolak dengan menggigit atau menginjak.","Dapat memindah jika diperintah tetapi penanganannya kasar, dan pengawasan penerimaan diserahkan ke orang lain.","Jika diperintah, dapat menggendong anak babi dengan tenang, memindahkannya dalam 1 kali, dan mengawasi keadaan induk segera setelah pemindahan.","Tanpa diperintah pun, pada musim dingin memeriksa dulu penghangat di kandang tujuan lalu memindah dengan cepat, dan saat ditolak tidak memaksakan melainkan berkonsultasi dengan senior untuk mempertimbangkan induk lain.","Memahami bahwa pemindahan berulang menghentikan pertumbuhan karena stres dan bahaya gigitan induk babi, dan dapat mengajarkan cara memindah yang aman kepada karyawan baru."]},{"id":"follow-up","name":"里子後の飲乳確認と経過観察","kanten":"里子後24時間以内に乳頭への吸い付きとおなかのふくらみを確かめ、その後2〜3日観察を続けられるか。","levels":["移したあとの確認をせず、飲めていない子豚ややせ・下痢があっても気づかない。","指示があれば見るが確認が一度きりで、その後の観察は続かない。","指示があれば24時間以内に乳頭への吸い付きとおなかのふくらみを確かめられる。","指示がなくても2〜3日観察を続け、母豚の拒否・子豚のやせ・下痢に気づけばすぐ報告する。","飲めているかをおなかのふくらみで見分けるなど観察の要点を理解し、里子後のフォローを新人に指導できる。"],"name_en":"Suckling Checks and Follow-Up After Fostering","kanten_en":"Can they confirm within 24 hours of fostering that the piglet latches onto a teat and has a rounded belly, and keep observing for the next 2-3 days?","levels_en":["Does not check after the move, and fails to notice piglets that are not drinking, losing weight, or scouring.","With guidance looks, but checks only once and does not keep observing afterward.","With guidance can confirm within 24 hours that the piglet latches onto a teat and its belly is rounded.","Independently keeps observing for 2-3 days, and reports right away on noticing sow rejection, piglet thinness, or diarrhea.","Understands the key observation points, such as telling whether piglets are drinking by the rounded belly, and can teach new staff post-fostering follow-up."],"name_vi":"Kiểm tra bú sữa và theo dõi sau ghép bầy","kanten_vi":"Trong vòng 24 giờ sau khi ghép bầy, có kiểm tra con bám bú núm vú và bụng căng tròn không, sau đó tiếp tục theo dõi 2〜3 ngày không.","levels_vi":["Không kiểm tra sau khi chuyển, có con không bú được, gầy đi hay tiêu chảy cũng không nhận ra.","Nếu được chỉ thị thì xem, nhưng chỉ kiểm tra một lần, sau đó không tiếp tục theo dõi.","Nếu được chỉ thị thì kiểm tra được trong vòng 24 giờ con bám bú núm vú và bụng căng tròn.","Dù không có chỉ thị vẫn tiếp tục theo dõi 2〜3 ngày, thấy nái từ chối, lợn con gầy hay tiêu chảy thì báo cáo ngay.","Hiểu các điểm chính khi quan sát như nhìn bụng căng tròn để biết con bú được không, và có thể hướng dẫn người mới cách theo dõi sau ghép bầy."],"name_id":"Memastikan menyusu dan pengamatan lanjutan setelah titip anak","kanten_id":"Apakah dalam 24 jam setelah titip anak dapat memastikan anak menempel menyusu di puting dan perutnya membuncit, lalu melanjutkan pengamatan 2〜3 hari berikutnya?","levels_id":["Tidak memeriksa setelah memindah, dan tidak menyadari anak babi yang tidak bisa menyusu, kurus, atau diare.","Melihat jika diperintah, tetapi memeriksa hanya sekali dan pengamatan selanjutnya tidak berlanjut.","Jika diperintah, dapat memastikan dalam 24 jam anak menempel menyusu di puting dan perutnya membuncit.","Tanpa diperintah pun, melanjutkan pengamatan 2〜3 hari, dan segera melaporkan jika menyadari induk menolak, anak babi kurus, atau diare.","Memahami pokok pengamatan seperti membedakan anak bisa menyusu atau tidak dari perut yang membuncit, dan dapat mengajarkan tindak lanjut setelah titip anak kepada karyawan baru."]},{"id":"record-match","name":"マッチングシートと記録","kanten":"組み合わせをマッチングシートに書き、移した子豚に印をつけ、母豚番号・移した頭数を記録に残せるか。","levels":["シートも印も記録も残さず、どの子豚をどこへ移したか分からなくなる。","指示があれば書くが、記入漏れや印のつけ忘れが多い。","指示があればマッチングシートに組み合わせを書き、移した子豚に印をつけて母豚番号・頭数を記録できる。","指示がなくても移動のたびに記録し、移動後の頭数が乳頭数を超えていないかシートで確かめてズレがあれば報告する。","記録がその後の管理と個体追跡の土台になることを理解し、シートの書き方と印のつけ方を新人に指導できる。"],"name_en":"Matching Sheet and Records","kanten_en":"Can they write the pairings on the matching sheet, mark the moved piglets, and record the sow number and the number of piglets moved?","levels_en":["Leaves no sheet, marks, or records, and loses track of which piglet went where.","With guidance writes, but often misses entries and forgets to mark piglets.","With guidance can write the pairings on the matching sheet, mark the moved piglets, and record the sow number and the head count.","Independently records every move, checks on the sheet that the count after the move does not exceed the teat count, and reports any discrepancy.","Understands that records are the foundation for later management and individual tracing, and can teach new staff how to fill in the sheet and mark piglets."],"name_vi":"Bảng ghép bầy và ghi chép","kanten_vi":"Có ghi cách ghép vào bảng ghép bầy, đánh dấu lợn con đã chuyển, ghi lại số hiệu lợn nái và số con đã chuyển không.","levels_vi":["Không có bảng, không đánh dấu, không ghi chép, không còn biết đã chuyển con nào đi đâu.","Nếu được chỉ thị thì ghi, nhưng hay ghi thiếu và quên đánh dấu.","Nếu được chỉ thị thì ghi cách ghép vào bảng ghép bầy, đánh dấu lợn con đã chuyển và ghi được số hiệu lợn nái, số con.","Dù không có chỉ thị vẫn ghi chép mỗi lần chuyển, kiểm tra trên bảng số con sau khi chuyển có vượt số vú không, nếu lệch thì báo cáo.","Hiểu rằng ghi chép là nền tảng cho quản lý và truy xuất từng con sau này, và có thể hướng dẫn người mới cách ghi bảng và cách đánh dấu."],"name_id":"Lembar pencocokan dan pencatatan","kanten_id":"Apakah dapat menulis pasangan di lembar pencocokan, menandai anak babi yang dipindah, dan mencatat nomor induk babi serta jumlah anak yang dipindah?","levels_id":["Tidak meninggalkan lembar, tanda, maupun catatan, sehingga tidak tahu lagi anak babi mana dipindah ke mana.","Menulis jika diperintah, tetapi sering ada catatan yang kurang dan lupa memberi tanda.","Jika diperintah, dapat menulis pasangan di lembar pencocokan, menandai anak babi yang dipindah, dan mencatat nomor induk babi serta jumlahnya.","Tanpa diperintah pun, mencatat setiap pemindahan, memastikan di lembar bahwa jumlah setelah pemindahan tidak melebihi jumlah puting, dan melaporkan jika ada selisih.","Memahami bahwa catatan menjadi dasar pengelolaan dan penelusuran individu selanjutnya, dan dapat mengajarkan cara mengisi lembar dan memberi tanda kepada karyawan baru."]}]},{"id":"sow-lineup","category":"facility","no":"No.13","name":"母豚の並びの整理","purposeShort":"母豚をまとめて管理しやすくし、ケンカ・ストレスを減らす","gyomu":"13","aspects":[{"id":"schedule-order","name":"分娩予定日順の整列と台帳反映","kanten":"交配日・分娩予定日のズレを抑えて整列させ、並び情報を台帳に反映できるか。","levels":["分娩予定日順に整列させず、並び情報も台帳に反映せず認識齟齬を招く。","指示があれば整列させるが、予定日順の徹底や台帳反映に漏れがある。","指示があれば分娩予定日順にひと通り整列できる。","指示がなくても予定日のズレを抑えて整列させ、並び情報を台帳に反映する。","整列と移動指示の連動を理解し、並び管理と台帳反映を新人に指導できる。"],"name_en":"Lining Up by Due Date and Updating the Ledger","kanten_en":"Can they line up sows with minimal gaps in mating and due dates, and record the lineup in the ledger?","levels_en":["Does not line sows up by due date and does not record the lineup in the ledger, causing misunderstandings.","With guidance can line sows up, but misses strict due-date ordering or ledger updates.","With guidance can line sows up by due date through the basic procedure.","Independently lines sows up with minimal due-date gaps and records the lineup in the ledger.","Understands how the lineup links to movement orders, and can teach new staff lineup management and ledger updates."],"name_vi":"Xếp theo thứ tự ngày dự sinh và cập nhật sổ quản lý","kanten_vi":"Có xếp hàng sao cho ngày giao phối, ngày dự sinh ít chênh lệch, và ghi thông tin vị trí vào sổ quản lý không.","levels_vi":["Không xếp theo thứ tự ngày dự sinh, cũng không ghi thông tin vị trí vào sổ, gây hiểu nhầm lẫn nhau.","Nếu được chỉ thị thì xếp, nhưng còn thiếu sót về xếp đúng thứ tự ngày dự sinh và cập nhật sổ.","Nếu được chỉ thị thì xếp theo thứ tự ngày dự sinh được cơ bản.","Dù không có chỉ thị vẫn xếp cho ngày dự sinh ít chênh lệch và ghi thông tin vị trí vào sổ quản lý.","Hiểu sự liên kết giữa xếp hàng và chỉ thị di chuyển, và có thể hướng dẫn người mới cách quản lý vị trí và cập nhật sổ."],"name_id":"Menata urut tanggal perkiraan melahirkan dan mencatat ke buku","kanten_id":"Apakah dapat menata dengan menekan selisih tanggal kawin dan perkiraan melahirkan, serta mencatat susunan posisinya ke buku catatan?","levels_id":["Tidak menata urut tanggal perkiraan melahirkan, tidak mencatat susunan ke buku catatan, sehingga terjadi salah paham.","Menata jika diperintah, tetapi sering lalai menepati urutan tanggal dan mencatat ke buku.","Jika diperintah, dapat menata urut tanggal perkiraan melahirkan secara lengkap.","Tanpa diperintah pun, menata dengan menekan selisih tanggal perkiraan, dan mencatat susunan posisi ke buku catatan.","Memahami kaitan penataan dengan instruksi pemindahan, dan dapat mengajarkan pengaturan susunan dan pencatatan kepada karyawan baru."]},{"id":"early-preg-hold","name":"妊娠初期（35日以内）の移動除外","kanten":"交配日を確認して授精後35日以内の母豚をリストから外し、動かす場合は上司の許可を得られるか。","levels":["交配日を確認せず妊娠初期の母豚も動かし、胚死亡・流産のリスクを招く。","指示があれば外すが、交配日の確認漏れで妊娠初期の個体が混ざることがある。","指示があれば交配日を確認し、35日以内の母豚をひと通りリストから外せる。","指示がなくても交配日を必ず確認して外し、動かす必要があれば上司の許可を得る。","着床期の移動と流産の関係を理解し、リスト作成時の確認を新人に指導できる。"],"name_en":"Excluding Early-Gestation Sows (Within 35 Days) from Moves","kanten_en":"Can they check mating dates, exclude sows within 35 days after insemination from the list, and get a supervisor's permission when they must be moved?","levels_en":["Moves even early-gestation sows without checking mating dates, risking embryo death and abortion.","With guidance can exclude them, but missed mating-date checks sometimes let early-gestation sows slip in.","With guidance can check mating dates and exclude sows within 35 days from the list through the basic procedure.","Independently always checks mating dates to exclude them, and gets a supervisor's permission when a move is necessary.","Understands how moves during implantation relate to abortion, and can teach new staff the checks when making the list."],"name_vi":"Loại trừ khỏi di chuyển lợn nái đầu thai kỳ (trong vòng 35 ngày)","kanten_vi":"Có kiểm tra ngày giao phối, loại khỏi danh sách lợn nái trong vòng 35 ngày sau khi phối, và xin phép cấp trên khi cần di chuyển không.","levels_vi":["Không kiểm tra ngày giao phối, di chuyển cả lợn nái đầu thai kỳ, gây rủi ro chết phôi, sảy thai.","Nếu được chỉ thị thì loại ra, nhưng do sót kiểm tra ngày giao phối nên đôi khi vẫn lẫn con đầu thai kỳ.","Nếu được chỉ thị thì kiểm tra ngày giao phối và loại lợn nái trong vòng 35 ngày khỏi danh sách được cơ bản.","Dù không có chỉ thị vẫn luôn kiểm tra ngày giao phối để loại ra, và xin phép cấp trên nếu cần di chuyển.","Hiểu quan hệ giữa di chuyển trong giai đoạn phôi làm tổ và sảy thai, và có thể hướng dẫn người mới cách kiểm tra khi lập danh sách."],"name_id":"Mengecualikan induk babi awal kebuntingan (dalam 35 hari) dari pemindahan","kanten_id":"Apakah memeriksa tanggal kawin, mengeluarkan dari daftar induk babi yang masih dalam 35 hari setelah inseminasi, dan meminta izin atasan jika harus memindahkannya?","levels_id":["Memindahkan induk babi awal kebuntingan tanpa memeriksa tanggal kawin, sehingga menimbulkan risiko kematian embrio dan keguguran.","Mengeluarkan jika diperintah, tetapi karena lalai memeriksa tanggal kawin, kadang masih tercampur induk babi awal kebuntingan.","Jika diperintah, dapat memeriksa tanggal kawin dan mengeluarkan induk babi dalam 35 hari dari daftar secara lengkap.","Tanpa diperintah pun, selalu memeriksa tanggal kawin untuk mengeluarkannya, dan meminta izin atasan jika perlu memindahkan.","Memahami hubungan pemindahan pada masa penempelan embrio dengan keguguran, dan dapat mengajarkan pemeriksaan saat membuat daftar kepada karyawan baru."]},{"id":"compatibility","name":"体格差・攻撃性への配慮","kanten":"極端に弱い・大きい母豚や攻撃的な個体を同じ並びに入れず、負傷を防げるか。","levels":["体格差・攻撃性を考えず収容し、負傷が出ても気にしない。","指示があれば配慮するが、体格差や攻撃性の見極めに漏れがある。","指示があれば極端に弱い・大きい母豚を分けてひと通り配置できる。","指示がなくても体格差や初産・経産を見て収容し、血が出るひどいケンカは隔離して報告する。","収容と負傷・ストレスの関係を理解し、相性を考えた配置を新人に指導できる。"],"name_en":"Accounting for Size Differences and Aggression","kanten_en":"Can they keep extremely weak, oversized, or aggressive sows out of the same lineup and prevent injuries?","levels_en":["Houses sows without regard to size differences or aggression, and does not care even when injuries occur.","With guidance can take care, but misses judging size differences or aggression.","With guidance can separate extremely weak or oversized sows and complete the basic placement.","Independently houses sows with attention to size differences and parity, and isolates and reports severe fights that draw blood.","Understands how housing relates to injury and stress, and can teach new staff compatibility-based placement."],"name_vi":"Chú ý chênh lệch thể trạng và tính hung dữ","kanten_vi":"Có tránh xếp lợn nái quá yếu, quá to hoặc con hung dữ vào cùng hàng, phòng bị thương không.","levels_vi":["Xếp lợn không xét chênh lệch thể trạng, tính hung dữ, có con bị thương cũng không quan tâm.","Nếu được chỉ thị thì chú ý, nhưng còn thiếu sót trong nhận biết chênh lệch thể trạng và tính hung dữ.","Nếu được chỉ thị thì tách riêng lợn nái quá yếu, quá to và sắp xếp được cơ bản.","Dù không có chỉ thị vẫn xem chênh lệch thể trạng, lứa đầu hay đã đẻ nhiều lứa khi xếp, và cách ly, báo cáo khi có đánh nhau nặng chảy máu.","Hiểu quan hệ giữa cách xếp với bị thương, stress, và có thể hướng dẫn người mới cách bố trí có xét đến sự hợp nhau."],"name_id":"Memperhatikan beda ukuran badan dan sifat agresif","kanten_id":"Apakah tidak menempatkan induk babi yang sangat lemah, sangat besar, atau agresif dalam satu barisan, sehingga mencegah luka?","levels_id":["Menempatkan tanpa memikirkan beda ukuran badan dan sifat agresif, dan tidak peduli walaupun ada yang terluka.","Memperhatikan jika diperintah, tetapi sering lalai menilai beda ukuran badan dan sifat agresif.","Jika diperintah, dapat memisahkan induk babi yang sangat lemah atau sangat besar dan menempatkannya secara lengkap.","Tanpa diperintah pun, menempatkan dengan melihat beda ukuran badan dan induk beranak pertama atau sudah beranak, serta mengisolasi dan melaporkan perkelahian parah yang berdarah.","Memahami hubungan penempatan dengan luka dan stres, dan dapat mengajarkan penempatan yang memperhatikan kecocokan kepada karyawan baru."]},{"id":"calm-drive-safety","name":"追い板誘導と自分の安全確保","kanten":"追い板で1頭ずつ静かに誘導し、叩かず、壁との間に挟まれない位置と逃げ場を確保できるか。","levels":["複数頭を一度に追って叩き、壁との間に挟まれる危険な位置で作業する。","指示があれば追い板を使うが、急かしたり退避スペースの確保に漏れがある。","指示があれば追い板で1頭ずつひと通り静かに誘導できる。","指示がなくても叩かず豚のペースで誘導し、逃げ場を確保して挟まれを避ける。","豚の視界と動きの習性を理解し、安全な誘導と立ち位置を新人に指導できる。"],"name_en":"Driving-Board Guidance and Securing Your Own Safety","kanten_en":"Can they guide sows quietly one at a time with a driving board, without hitting, while keeping a position and escape route that avoid being pinned against the wall?","levels_en":["Drives several sows at once while hitting them, and works in a dangerous position where they can be pinned against the wall.","With guidance uses the driving board, but sometimes rushes the sows or misses securing an escape space.","With guidance can guide sows quietly one at a time with the driving board through the basic procedure.","Independently guides at the pigs' pace without hitting, and secures an escape route to avoid being pinned.","Understands pigs' field of vision and movement habits, and can teach new staff safe guidance and standing positions."],"name_vi":"Lùa bằng tấm chắn và bảo đảm an toàn cho bản thân","kanten_vi":"Có dùng tấm chắn lùa nhẹ nhàng từng con một, không đánh, giữ vị trí không bị kẹp giữa lợn và tường và bảo đảm đường thoát không.","levels_vi":["Dồn nhiều con cùng lúc và đánh lợn, làm việc ở vị trí nguy hiểm dễ bị kẹp giữa lợn và tường.","Nếu được chỉ thị thì dùng tấm chắn, nhưng có khi hối thúc lợn hoặc thiếu sót trong bảo đảm chỗ tránh.","Nếu được chỉ thị thì dùng tấm chắn lùa nhẹ nhàng từng con một được cơ bản.","Dù không có chỉ thị vẫn lùa theo nhịp của lợn, không đánh, bảo đảm đường thoát để tránh bị kẹp.","Hiểu tầm nhìn và tập tính di chuyển của lợn, và có thể hướng dẫn người mới cách lùa an toàn và vị trí đứng."],"name_id":"Menggiring dengan papan penggiring dan menjaga keselamatan diri","kanten_id":"Apakah dapat menggiring dengan tenang satu per satu memakai papan penggiring, tanpa memukul, sambil menjaga posisi agar tidak terjepit ke dinding dan menyediakan jalan menghindar?","levels_id":["Menggiring beberapa ekor sekaligus sambil memukul, dan bekerja di posisi berbahaya yang bisa terjepit ke dinding.","Memakai papan penggiring jika diperintah, tetapi kadang memburu-buru babi atau lalai menyiapkan ruang menghindar.","Jika diperintah, dapat menggiring dengan tenang satu per satu memakai papan penggiring secara lengkap.","Tanpa diperintah pun, menggiring mengikuti langkah babi tanpa memukul, dan menyediakan jalan menghindar agar tidak terjepit.","Memahami jangkauan pandang dan kebiasaan gerak babi, dan dapat mengajarkan cara menggiring yang aman dan posisi berdiri kepada karyawan baru."]},{"id":"after-care","name":"移動後の水・エサ・カード確認","kanten":"収容後に飲水・エサ箱への到達を見届け、母豚カードを同時に移し、当日と翌日に見回れるか。","levels":["入れたら終わりにし、水・エサもカード移動も確認せず取り違えを招く。","指示があれば確認するが、カードの移し忘れや翌日の見回りに漏れがある。","指示があれば飲水・エサの確認とカードの移動をひと通りできる。","指示がなくても水・エサを見届けてカードを同時に移し、当日・翌日もケンカや食欲を見回る。","カード忘れが給餌ミスにつながることを理解し、移動後の確認を新人に指導できる。"],"name_en":"Post-Move Checks of Water, Feed, and Cards","kanten_en":"Can they confirm each sow reaches water and the feed box after housing, move the sow card at the same time, and check on them that day and the next?","levels_en":["Considers the job done once sows are in, checking neither water and feed nor card moves, causing mix-ups.","With guidance can check, but sometimes forgets to move cards or misses the next day's rounds.","With guidance can check water and feed and move the cards through the basic procedure.","Independently confirms water and feed, moves the cards at the same time, and checks fighting and appetite that day and the next.","Understands that forgotten cards lead to feeding mistakes, and can teach new staff the post-move checks."],"name_vi":"Kiểm tra nước, thức ăn, thẻ nái sau khi di chuyển","kanten_vi":"Sau khi xếp vào chuồng có xem lợn uống được nước, với tới máng ăn không, chuyển thẻ nái cùng lúc, và đi kiểm tra trong ngày và ngày hôm sau không.","levels_vi":["Cho lợn vào là xong, không kiểm tra nước, thức ăn, không chuyển thẻ, gây nhầm con.","Nếu được chỉ thị thì kiểm tra, nhưng có khi quên chuyển thẻ hoặc thiếu sót đi kiểm tra ngày hôm sau.","Nếu được chỉ thị thì kiểm tra nước uống, thức ăn và chuyển thẻ được cơ bản.","Dù không có chỉ thị vẫn xem lợn uống nước, ăn được, chuyển thẻ cùng lúc, và trong ngày, ngày hôm sau vẫn đi xem đánh nhau và mức ăn.","Hiểu việc quên thẻ dẫn đến cho ăn sai, và có thể hướng dẫn người mới cách kiểm tra sau di chuyển."],"name_id":"Memeriksa air, pakan, dan kartu induk setelah pemindahan","kanten_id":"Apakah setelah dimasukkan memastikan babi mencapai air minum dan kotak pakan, memindahkan kartu induk pada saat yang sama, dan memeriksa keliling pada hari itu dan keesokan harinya?","levels_id":["Menganggap selesai begitu babi dimasukkan, tidak memeriksa air dan pakan maupun memindahkan kartu, sehingga terjadi tertukar.","Memeriksa jika diperintah, tetapi kadang lupa memindahkan kartu atau lalai memeriksa keliling keesokan harinya.","Jika diperintah, dapat memeriksa air minum dan pakan serta memindahkan kartu secara lengkap.","Tanpa diperintah pun, memastikan air dan pakan, memindahkan kartu pada saat yang sama, dan pada hari itu serta keesokan harinya memeriksa perkelahian dan nafsu makan.","Memahami bahwa lupa kartu menyebabkan kesalahan pemberian pakan, dan dapat mengajarkan pemeriksaan setelah pemindahan kepada karyawan baru."]}],"name_en":"Organizing the Sow Lineup","name_vi":"Sắp xếp lại vị trí lợn nái","name_id":"Menata ulang posisi induk babi","purposeShort_en":"Group sows for easier management and reduce fighting and stress","purposeShort_vi":"Gom lợn nái lại cho dễ quản lý, giảm đánh nhau và stress","purposeShort_id":"Mengelompokkan induk babi agar mudah dikelola, serta mengurangi perkelahian dan stres"},{"id":"move-order","category":"facility","no":"No.10","name":"移動指示","purposeShort":"ピッグフローを滞らせず、豚にストレスをかけず安全に移動させる","gyomu":"10","aspects":[{"id":"count-handover","name":"移動指示の復唱確認と頭数照合","kanten":"どのグループを・何頭・どこからどこへを復唱して確認し、移動元と移動先で頭数を数えて一致を確かめられるか。","levels":["指示を確認せず「たぶんこれ」で動かし、頭数も数えず誤移動を招く。","指示があれば確認するが、復唱やあいまいな点の確認、頭数照合に漏れが多い。","指示があれば移動頭数・グループを確認し、移動元でひと通り頭数を数えられる。","指示がなくても復唱して確認し、移動先でも数えて照合、合わなければ探して報告する。","数が合うまで終わりにしない意味を理解し、指示確認と頭数照合を新人に指導できる。"],"name_en":"Repeating Back Movement Orders and Verifying Head Counts","kanten_en":"Can they repeat back which group, how many head, and from where to where, and count the pigs at both origin and destination to confirm they match?","levels_en":["Moves pigs on a guess without confirming the order and without counting, causing wrong moves.","With guidance can confirm, but often misses repeating back, clarifying vague points, or verifying counts.","With guidance can confirm the head count and group and count the pigs at the origin through the basic procedure.","Independently repeats back to confirm, counts again at the destination to verify, and searches and reports when the numbers do not match.","Understands why the job is not done until the numbers match, and can teach new staff order confirmation and head-count verification."],"name_vi":"Nhắc lại chỉ thị di chuyển và đối chiếu số con","kanten_vi":"Có nhắc lại để xác nhận nhóm nào, bao nhiêu con, từ đâu đến đâu, và đếm số con ở cả nơi đi lẫn nơi đến để kiểm tra khớp nhau không.","levels_vi":["Không xác nhận chỉ thị, di chuyển theo kiểu「chắc là con này」, không đếm số con, gây di chuyển nhầm.","Nếu được chỉ thị thì xác nhận, nhưng hay thiếu sót về nhắc lại, hỏi rõ điểm chưa rõ và đối chiếu số con.","Nếu được chỉ thị thì xác nhận số con, nhóm di chuyển và đếm số con ở nơi đi được cơ bản.","Dù không có chỉ thị vẫn nhắc lại để xác nhận, đếm và đối chiếu cả ở nơi đến, nếu không khớp thì tìm và báo cáo.","Hiểu ý nghĩa của việc chưa khớp số thì chưa xong, và có thể hướng dẫn người mới cách xác nhận chỉ thị và đối chiếu số con."],"name_id":"Mengulang instruksi pemindahan dan mencocokkan jumlah ekor","kanten_id":"Apakah mengulang dengan suara untuk memastikan kelompok mana, berapa ekor, dari mana ke mana, serta menghitung jumlah ekor di tempat asal dan tujuan untuk memastikan cocok?","levels_id":["Memindahkan babi dengan menebak tanpa memastikan instruksi dan tanpa menghitung jumlah ekor, sehingga terjadi salah pindah.","Memastikan jika diperintah, tetapi sering lalai mengulang instruksi, menanyakan hal yang belum jelas, dan mencocokkan jumlah ekor.","Jika diperintah, dapat memastikan jumlah ekor dan kelompok yang dipindah serta menghitung jumlah ekor di tempat asal secara lengkap.","Tanpa diperintah pun, mengulang untuk memastikan, menghitung dan mencocokkan juga di tempat tujuan, dan jika tidak cocok mencari lalu melapor.","Memahami arti pekerjaan belum selesai sampai jumlahnya cocok, dan dapat mengajarkan konfirmasi instruksi dan pencocokan jumlah ekor kepada karyawan baru."]},{"id":"route-biosec","name":"通路確認と移動先の清浄性","kanten":"通路の段差・滑り・障害物を先に確認し、移動先の清掃・消毒完了を確かめて汚染搬入を防げるか。","levels":["通路を確認せず、清掃・消毒完了前の汚染豚舎に搬入する。","指示があれば通路を見るが、移動先の清浄性確認に漏れがある。","指示があれば通路の危険をひと通り確認できる。","指示がなくても通路を先に点検し、移動先の清掃・消毒完了を確かめてから移動する。","移動と防疫の関係を理解し、通路点検と清浄性確認を新人に指導できる。"],"name_en":"Checking Routes and Destination Cleanliness","kanten_en":"Can they check the route in advance for steps, slippery spots, and obstacles, and confirm the destination's cleaning and disinfection are complete to prevent bringing in contamination?","levels_en":["Does not check the route and moves pigs into a contaminated barn before cleaning and disinfection are complete.","With guidance checks the route, but misses confirming the destination's cleanliness.","With guidance can check the route hazards through the basic procedure.","Independently inspects the route first and confirms the destination's cleaning and disinfection are complete before moving.","Understands the link between movement and biosecurity, and can teach new staff route inspection and cleanliness checks."],"name_vi":"Kiểm tra lối đi và độ sạch của nơi chuyển đến","kanten_vi":"Có kiểm tra trước bậc, chỗ trơn, vật cản trên lối đi, xác nhận nơi chuyển đến đã vệ sinh, khử trùng xong để tránh mang ô nhiễm vào không.","levels_vi":["Không kiểm tra lối đi, đưa lợn vào chuồng ô nhiễm chưa vệ sinh, khử trùng xong.","Nếu được chỉ thị thì xem lối đi, nhưng còn thiếu sót trong kiểm tra độ sạch của nơi chuyển đến.","Nếu được chỉ thị thì kiểm tra chỗ nguy hiểm trên lối đi được cơ bản.","Dù không có chỉ thị vẫn kiểm tra lối đi trước, xác nhận nơi chuyển đến đã vệ sinh, khử trùng xong rồi mới di chuyển.","Hiểu quan hệ giữa di chuyển và phòng dịch, và có thể hướng dẫn người mới cách kiểm tra lối đi và độ sạch."],"name_id":"Memeriksa jalur dan kebersihan tempat tujuan","kanten_id":"Apakah dapat memeriksa lebih dulu jalur dari tangga, licin, dan penghalang, serta memastikan tempat tujuan sudah selesai dibersihkan dan didisinfeksi agar tidak membawa masuk pencemaran?","levels_id":["Tidak memeriksa jalur, dan memasukkan babi ke kandang kotor yang belum selesai dibersihkan dan didisinfeksi.","Melihat jalur jika diperintah, tetapi sering lalai memastikan kebersihan tempat tujuan.","Jika diperintah, dapat memeriksa bahaya di jalur secara lengkap.","Tanpa diperintah pun, memeriksa jalur lebih dulu, dan memastikan tempat tujuan selesai dibersihkan dan didisinfeksi sebelum memindahkan.","Memahami hubungan pemindahan dengan biosekuriti, dan dapat mengajarkan pemeriksaan jalur dan kebersihan tujuan kepada karyawan baru."]},{"id":"sick-hold","name":"病豚・起立不能豚の移動中止","kanten":"立てない豚・明らかに具合の悪い豚を無理に動かさず、その場で指導係に報告できるか。","levels":["立てない豚も無理に追って動かし、悪化させても報告しない。","指示があれば止めるが、具合の悪い豚の見極めに漏れがある。","指示があれば病豚を移動から外し、ひと通り報告できる。","指示がなくても移動前に豚を見て病豚を外し、その場で指導係に報告する。","無理な移動が悪化を招くことを理解し、移動可否の判断を新人に指導できる。"],"name_en":"Stopping Moves of Sick and Downed Pigs","kanten_en":"Can they avoid forcing pigs that cannot stand or are clearly unwell to move, and report to the trainer on the spot?","levels_en":["Forces even pigs that cannot stand to move, and does not report even when they get worse.","With guidance can hold them back, but misses spotting unwell pigs.","With guidance can exclude sick pigs from the move and report through the basic procedure.","Independently looks over the pigs before moving, excludes sick ones, and reports to the trainer on the spot.","Understands that forced moves worsen conditions, and can teach new staff how to judge whether a pig can be moved."],"name_vi":"Ngừng di chuyển lợn bệnh, lợn không đứng dậy được","kanten_vi":"Có tránh ép di chuyển lợn không đứng dậy được, lợn rõ ràng yếu, và báo cáo ngay tại chỗ cho người hướng dẫn không.","levels_vi":["Cố lùa cả lợn không đứng dậy được, làm bệnh nặng thêm cũng không báo cáo.","Nếu được chỉ thị thì dừng lại, nhưng còn thiếu sót trong nhận biết lợn yếu.","Nếu được chỉ thị thì loại lợn bệnh khỏi việc di chuyển và báo cáo được cơ bản.","Dù không có chỉ thị vẫn xem lợn trước khi di chuyển, loại lợn bệnh ra và báo cáo ngay tại chỗ cho người hướng dẫn.","Hiểu việc ép di chuyển làm bệnh nặng thêm, và có thể hướng dẫn người mới cách phán đoán có nên di chuyển hay không."],"name_id":"Menghentikan pemindahan babi sakit dan babi yang tidak bisa berdiri","kanten_id":"Apakah tidak memaksa memindahkan babi yang tidak bisa berdiri atau jelas tidak sehat, dan melaporkannya di tempat kepada pembimbing?","levels_id":["Memaksa menggiring bahkan babi yang tidak bisa berdiri, dan tidak melapor walaupun kondisinya memburuk.","Menghentikan jika diperintah, tetapi sering lalai mengenali babi yang tidak sehat.","Jika diperintah, dapat mengecualikan babi sakit dari pemindahan dan melapor secara lengkap.","Tanpa diperintah pun, memeriksa babi sebelum pemindahan, mengecualikan yang sakit, dan langsung melapor di tempat kepada pembimbing.","Memahami bahwa pemindahan paksa memperburuk kondisi, dan dapat mengajarkan penilaian boleh tidaknya memindahkan kepada karyawan baru."]},{"id":"calm-drive","name":"少頭数ずつの静かな誘導","kanten":"3〜5頭ずつ叩かず急かさず豚のペースで誘導し、止まったら離れて落ち着きを待てるか。","levels":["一度に大量に出して叩き・大声で追い、豚をパニックにさせる。","指示があれば少頭数で追うが、急かしたり無理に押すことがある。","指示があれば少頭数ずつ静かにひと通り誘導できる。","指示がなくても豚のペースで誘導し、止まったら少し離れて落ち着いてから再開する。","豚の視界と習性を理解し、パネルで一本道を作る静かな追い方を新人に指導できる。"],"name_en":"Quiet Driving in Small Groups","kanten_en":"Can they drive 3-5 pigs at a time at the pigs' pace without hitting or rushing, and step back and wait for them to settle when they stop?","levels_en":["Lets out a large number at once, hitting and shouting, and throws the pigs into a panic.","With guidance drives small groups, but sometimes rushes or pushes the pigs.","With guidance can drive pigs quietly in small groups through the basic procedure.","Independently drives at the pigs' pace and, when they stop, steps back a little and resumes after they settle.","Understands pigs' vision and habits, and can teach new staff quiet driving that makes a single path with panels."],"name_vi":"Lùa nhẹ nhàng theo từng nhóm nhỏ","kanten_vi":"Có lùa mỗi lần 3〜5 con theo nhịp của lợn, không đánh, không hối thúc, khi lợn dừng thì lùi ra chờ lợn bình tĩnh không.","levels_vi":["Thả ra một lúc quá nhiều con, vừa đánh vừa la lớn, làm lợn hoảng loạn.","Nếu được chỉ thị thì lùa theo nhóm nhỏ, nhưng có khi hối thúc hoặc đẩy ép lợn.","Nếu được chỉ thị thì lùa nhẹ nhàng theo từng nhóm nhỏ được cơ bản.","Dù không có chỉ thị vẫn lùa theo nhịp của lợn, khi lợn dừng thì lùi ra một chút, chờ bình tĩnh rồi mới tiếp tục.","Hiểu tầm nhìn và tập tính của lợn, và có thể hướng dẫn người mới cách lùa nhẹ nhàng dùng tấm chắn tạo một đường đi duy nhất."],"name_id":"Menggiring dengan tenang sedikit demi sedikit","kanten_id":"Apakah dapat menggiring 3〜5 ekor sekaligus mengikuti langkah babi tanpa memukul dan memburu-buru, dan saat babi berhenti menjauh dulu menunggu babi tenang?","levels_id":["Mengeluarkan banyak sekaligus sambil memukul dan berteriak, sehingga babi panik.","Menggiring dalam kelompok kecil jika diperintah, tetapi kadang memburu-buru atau mendorong paksa.","Jika diperintah, dapat menggiring dengan tenang sedikit demi sedikit secara lengkap.","Tanpa diperintah pun, menggiring mengikuti langkah babi, dan saat babi berhenti menjauh sedikit lalu melanjutkan setelah babi tenang.","Memahami pandangan dan kebiasaan babi, dan dapat mengajarkan cara menggiring tenang dengan membuat satu jalur memakai papan kepada karyawan baru."]},{"id":"mix-watch","name":"混群後のケンカ観察と後始末","kanten":"混群後しばらくケンカを観察して血の出る咬傷を報告し、道具の洗浄・消毒と踏込消毒を守れるか。","levels":["混ぜたまま立ち去り、ケンカも見ず道具の消毒もしない。","指示があれば観察するが、咬傷の報告や道具の消毒に漏れがある。","指示があれば混群後の観察と道具の洗浄・消毒をひと通りできる。","指示がなくてもしばらく観察して血の出る咬傷を報告し、区域をまたげば長靴を消毒する。","咬傷が病気の入口になることを理解し、混群後の観察と防疫を新人に指導できる。"],"name_en":"Watching Fights After Mixing and Cleanup Afterward","kanten_en":"Can they watch fights for a while after mixing, report bite wounds that draw blood, and keep to tool washing and disinfection and boot-dip disinfection?","levels_en":["Walks away right after mixing, neither watching fights nor disinfecting the tools.","With guidance can watch, but misses reporting bite wounds or disinfecting the tools.","With guidance can complete the basic post-mixing observation and tool washing and disinfection.","Independently watches for a while, reports bite wounds that draw blood, and disinfects boots when crossing between areas.","Understands that bite wounds are an entry point for disease, and can teach new staff post-mixing observation and biosecurity."],"name_vi":"Quan sát đánh nhau sau khi trộn nhóm và dọn dẹp sau việc","kanten_vi":"Sau khi trộn nhóm có quan sát đánh nhau một lúc, báo cáo vết cắn chảy máu, và tuân thủ rửa, khử trùng dụng cụ và nhúng ủng khử trùng không.","levels_vi":["Trộn xong bỏ đi ngay, không xem đánh nhau, cũng không khử trùng dụng cụ.","Nếu được chỉ thị thì quan sát, nhưng còn thiếu sót trong báo cáo vết cắn và khử trùng dụng cụ.","Nếu được chỉ thị thì quan sát sau trộn nhóm và rửa, khử trùng dụng cụ được cơ bản.","Dù không có chỉ thị vẫn quan sát một lúc, báo cáo vết cắn chảy máu, và khử trùng ủng khi đi qua khu vực khác.","Hiểu vết cắn là cửa vào của bệnh, và có thể hướng dẫn người mới cách quan sát sau trộn nhóm và phòng dịch."],"name_id":"Mengamati perkelahian setelah mencampur kelompok dan pembenahan sesudahnya","kanten_id":"Apakah setelah mencampur mengamati perkelahian beberapa saat, melaporkan luka gigitan yang berdarah, serta menaati pencucian dan disinfeksi alat dan disinfeksi celup sepatu bot?","levels_id":["Pergi begitu saja setelah mencampur, tidak mengamati perkelahian dan tidak mendisinfeksi alat.","Mengamati jika diperintah, tetapi sering lalai melaporkan luka gigitan dan mendisinfeksi alat.","Jika diperintah, dapat melakukan pengamatan setelah pencampuran serta pencucian dan disinfeksi alat secara lengkap.","Tanpa diperintah pun, mengamati beberapa saat, melaporkan luka gigitan yang berdarah, dan mendisinfeksi sepatu bot saat melintasi antar area.","Memahami bahwa luka gigitan menjadi pintu masuk penyakit, dan dapat mengajarkan pengamatan setelah pencampuran dan biosekuriti kepada karyawan baru."]}],"name_en":"Movement Orders","name_vi":"Chỉ thị di chuyển (di chuyển lợn)","name_id":"Instruksi pemindahan (memindahkan babi)","purposeShort_en":"Keep the pig flow moving and move pigs safely without stress","purposeShort_vi":"Không làm tắc luồng luân chuyển lợn (pig flow), di chuyển an toàn không gây stress cho lợn","purposeShort_id":"Menjaga alur pemindahan babi (pig flow) tetap lancar, dan memindahkan babi dengan aman tanpa membuat stres"},{"id":"move-preg","category":"facility","no":"No.25","name":"妊娠舎→交配舎・育成舎 移動","purposeShort":"ピッグフローを守って次の舎へつなぐ","gyomu":"25","aspects":[{"id":"list-check","name":"移動リスト照合と妊娠初期除外","kanten":"個体番号・頭数・行き先をリストで照合し、交配後35日以内の妊娠豚の混入を防げるか。","levels":["リストを見ずに動かし、妊娠初期の豚を混ぜて流産のリスクを招く。","指示があれば照合するが、35日以内の混入チェックに漏れがある。","指示があれば個体番号・頭数・行き先をひと通り照合できる。","指示がなくてもリストと照合し、35日以内の妊娠豚が混ざっていないか必ず確認する。","着床期の移動リスクを理解し、リスト照合とマーキングの要点を新人に指導できる。"],"name_en":"Verifying the Move List and Excluding Early Gestation","kanten_en":"Can they verify individual numbers, head counts, and destinations against the list, and keep out pregnant sows within 35 days after mating?","levels_en":["Moves pigs without looking at the list, mixing in early-gestation sows and risking abortion.","With guidance can verify, but misses checking for sows within 35 days slipping in.","With guidance can verify individual numbers, head counts, and destinations through the basic procedure.","Independently verifies against the list and always checks that no pregnant sows within 35 days are mixed in.","Understands the risks of moving during implantation, and can teach new staff the key points of list verification and marking."],"name_vi":"Đối chiếu danh sách di chuyển và loại trừ đầu thai kỳ","kanten_vi":"Có đối chiếu số tai, số con, nơi đến với danh sách, và ngăn lẫn lợn mang thai trong vòng 35 ngày sau khi phối không.","levels_vi":["Di chuyển mà không xem danh sách, để lẫn lợn đầu thai kỳ, gây rủi ro sảy thai.","Nếu được chỉ thị thì đối chiếu, nhưng còn thiếu sót trong kiểm tra lẫn con trong vòng 35 ngày.","Nếu được chỉ thị thì đối chiếu số tai, số con, nơi đến được cơ bản.","Dù không có chỉ thị vẫn đối chiếu với danh sách, luôn kiểm tra xem có lẫn lợn mang thai trong vòng 35 ngày không.","Hiểu rủi ro di chuyển trong giai đoạn phôi làm tổ, và có thể hướng dẫn người mới các điểm chính của đối chiếu danh sách và đánh dấu."],"name_id":"Mencocokkan daftar pemindahan dan mengecualikan awal kebuntingan","kanten_id":"Apakah mencocokkan nomor individu, jumlah ekor, dan tujuan dengan daftar, serta mencegah tercampurnya babi bunting dalam 35 hari setelah kawin?","levels_id":["Memindahkan tanpa melihat daftar, mencampurkan babi awal kebuntingan sehingga menimbulkan risiko keguguran.","Mencocokkan jika diperintah, tetapi sering lalai memeriksa tercampurnya induk dalam 35 hari.","Jika diperintah, dapat mencocokkan nomor individu, jumlah ekor, dan tujuan secara lengkap.","Tanpa diperintah pun, mencocokkan dengan daftar dan selalu memastikan tidak ada babi bunting dalam 35 hari yang tercampur.","Memahami risiko pemindahan pada masa penempelan embrio, dan dapat mengajarkan pokok pencocokan daftar dan penandaan kepada karyawan baru."]},{"id":"quiet-move","name":"斜め後ろからの静かな誘導","kanten":"母豚の斜め後ろに立ち追い板で視界をさえぎって少頭数ずつ誘導し、絶対に走らせず、止まったら待てるか。","levels":["一度に大量に追い出して走らせ、転倒・骨折の危険を招く。","指示があれば追うが、立ち位置や止まった時の対応に漏れがある。","指示があれば斜め後ろから追い板で視界をさえぎり、少頭数ずつひと通り誘導できる。","指示がなくても母豚のペースで歩かせ、止まったら小さく声をかけて待ち、横になったら無理に起こさない。","走らせると転倒・骨折につながることを理解し、静かな追い方を新人に指導できる。"],"name_en":"Quiet Driving from Diagonally Behind","kanten_en":"Can they stand diagonally behind the sow, block her view with the driving board to guide small groups, never make them run, and wait when they stop?","levels_en":["Drives out a large number at once and makes them run, risking falls and fractures.","With guidance can drive, but misses the standing position or the response when sows stop.","With guidance can block the view with the driving board from diagonally behind and guide small groups through the basic procedure.","Independently lets sows walk at their own pace, waits with a soft word when they stop, and does not force one up when she lies down.","Understands that making sows run leads to falls and fractures, and can teach new staff quiet driving."],"name_vi":"Lùa nhẹ nhàng từ chéo phía sau","kanten_vi":"Có đứng chéo phía sau lợn nái, dùng tấm chắn che tầm nhìn để lùa theo nhóm nhỏ, tuyệt đối không bắt chạy, và chờ khi lợn dừng không.","levels_vi":["Dồn ra một lúc quá nhiều con và bắt chạy, gây nguy cơ ngã, gãy xương.","Nếu được chỉ thị thì lùa, nhưng còn thiếu sót về vị trí đứng và cách xử lý khi lợn dừng.","Nếu được chỉ thị thì từ chéo phía sau dùng tấm chắn che tầm nhìn và lùa theo nhóm nhỏ được cơ bản.","Dù không có chỉ thị vẫn để lợn nái đi theo nhịp của nó, khi dừng thì nói nhỏ và chờ, khi lợn nằm xuống thì không ép đứng dậy.","Hiểu việc bắt chạy dẫn đến ngã, gãy xương, và có thể hướng dẫn người mới cách lùa nhẹ nhàng."],"name_id":"Menggiring dengan tenang dari serong belakang","kanten_id":"Apakah berdiri serong di belakang induk babi, menutup pandangannya dengan papan penggiring untuk menggiring sedikit demi sedikit, sama sekali tidak membuatnya berlari, dan menunggu saat babi berhenti?","levels_id":["Mengeluarkan banyak sekaligus dan membuat babi berlari, sehingga menimbulkan bahaya jatuh dan patah tulang.","Menggiring jika diperintah, tetapi sering lalai soal posisi berdiri dan penanganan saat babi berhenti.","Jika diperintah, dapat menutup pandangan dengan papan penggiring dari serong belakang dan menggiring sedikit demi sedikit secara lengkap.","Tanpa diperintah pun, membiarkan induk babi berjalan sesuai langkahnya, saat berhenti menunggu sambil bersuara pelan, dan saat babi berbaring tidak memaksanya bangun.","Memahami bahwa membuat babi berlari menyebabkan jatuh dan patah tulang, dan dapat mengajarkan cara menggiring yang tenang kepada karyawan baru."]},{"id":"dest-check","name":"移動先の受け入れ準備と水・エサ確認","kanten":"移動先の豚房が空いて清掃・消毒済みか、給水ニップルから水が出るか・給餌器の位置を事前に確認し、入れた直後にも飲めているか見届けられるか。","levels":["受け入れ準備を確認せず搬入し、水が出ない豚房に入れても気づかない。","指示があれば確認するが、ニップルを押しての水確認や入れた直後の見届けに漏れがある。","指示があれば豚房の空き・清掃消毒と水・エサの位置をひと通り確認できる。","指示がなくても準備が整うまで移動を始めず、入れた直後も水が飲めているか見届ける。","受け入れ準備不足のリスクを理解し、移動先確認の要点を新人に指導できる。"],"name_en":"Destination Readiness and Water and Feed Checks","kanten_en":"Can they check in advance that the destination pen is empty, cleaned, and disinfected, that water comes out of the drinking nipples, and where the feeder is, and confirm the sows can drink right after they are put in?","levels_en":["Moves pigs in without checking readiness, and does not notice even when the pen has no water.","With guidance can check, but misses pressing the nipples to test water or confirming right after the pigs are in.","With guidance can check pen availability, cleaning and disinfection, and the water and feed positions through the basic procedure.","Independently does not start the move until preparations are complete, and confirms the sows can drink right after they are in.","Understands the risks of inadequate destination preparation, and can teach new staff the key points of destination checks."],"name_vi":"Chuẩn bị tiếp nhận ở nơi đến và kiểm tra nước, thức ăn","kanten_vi":"Có kiểm tra trước ô chuồng nơi đến đã trống, vệ sinh, khử trùng chưa, núm uống nước có chảy không, vị trí máng ăn, và ngay sau khi cho vào có xem lợn uống được nước không.","levels_vi":["Đưa lợn vào mà không kiểm tra việc chuẩn bị tiếp nhận, cho vào ô chuồng không có nước chảy cũng không nhận ra.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về ấn núm uống thử nước và xem lợn ngay sau khi cho vào.","Nếu được chỉ thị thì kiểm tra ô chuồng trống, vệ sinh khử trùng và vị trí nước, thức ăn được cơ bản.","Dù không có chỉ thị vẫn không bắt đầu di chuyển cho đến khi chuẩn bị xong, và ngay sau khi cho vào vẫn xem lợn có uống được nước không.","Hiểu rủi ro của việc chuẩn bị tiếp nhận chưa đầy đủ, và có thể hướng dẫn người mới các điểm chính khi kiểm tra nơi chuyển đến."],"name_id":"Kesiapan penerimaan di tempat tujuan dan pemeriksaan air dan pakan","kanten_id":"Apakah memeriksa lebih dulu bahwa petak kandang tujuan kosong serta sudah dibersihkan dan didisinfeksi, air keluar dari nipple air minum, dan posisi tempat pakan, lalu segera setelah dimasukkan memastikan babi bisa minum?","levels_id":["Memasukkan babi tanpa memeriksa kesiapan penerimaan, dan tidak sadar walaupun memasukkan ke petak kandang yang airnya tidak keluar.","Memeriksa jika diperintah, tetapi sering lalai menekan nipple untuk menguji air dan memastikan segera setelah babi dimasukkan.","Jika diperintah, dapat memeriksa kekosongan petak kandang, pembersihan dan disinfeksi, serta posisi air dan pakan secara lengkap.","Tanpa diperintah pun, tidak memulai pemindahan sampai persiapan selesai, dan segera setelah dimasukkan memastikan babi bisa minum.","Memahami risiko persiapan penerimaan yang kurang, dan dapat mengajarkan pokok pemeriksaan tempat tujuan kepada karyawan baru."]},{"id":"biosec-mat","name":"舎間移動の防疫（消毒マット）","kanten":"舎間の消毒マットの液を確認・充填し、消毒済みの長靴で他群と接触しない動線を守れるか。","levels":["消毒マットが空でも素通りし、防疫を無視した動線で移動する。","指示があればマットを通るが、液の確認・充填や動線の意識に漏れがある。","指示があればマットの液を確認し、防疫手順をひと通り守れる。","指示がなくても液を確認・充填し、他群と接触しない動線で移動する。","舎間移動と病気の持ち込みの関係を理解し、防疫手順を新人に指導できる。"],"name_en":"Biosecurity for Between-House Moves (Disinfection Mats)","kanten_en":"Can they check and refill the disinfectant in the mats between houses, and keep to a route that avoids contact with other groups in disinfected boots?","levels_en":["Walks straight past empty disinfection mats and moves along routes that ignore biosecurity.","With guidance steps on the mats, but misses checking and refilling the liquid or minding the route.","With guidance can check the mat liquid and follow the biosecurity steps through the basic procedure.","Independently checks and refills the liquid and moves along routes that avoid contact with other groups.","Understands how between-house moves relate to bringing in disease, and can teach new staff the biosecurity steps."],"name_vi":"Phòng dịch khi di chuyển giữa các chuồng (thảm khử trùng)","kanten_vi":"Có kiểm tra, đổ thêm dung dịch cho thảm khử trùng giữa các chuồng, và đi ủng đã khử trùng theo đường đi không tiếp xúc với nhóm lợn khác không.","levels_vi":["Thảm khử trùng cạn cũng đi qua luôn, di chuyển theo đường đi bỏ qua phòng dịch.","Nếu được chỉ thị thì đi qua thảm, nhưng còn thiếu sót về kiểm tra, đổ thêm dung dịch và ý thức về đường đi.","Nếu được chỉ thị thì kiểm tra dung dịch của thảm và tuân thủ quy trình phòng dịch được cơ bản.","Dù không có chỉ thị vẫn kiểm tra, đổ thêm dung dịch và di chuyển theo đường đi không tiếp xúc với nhóm khác.","Hiểu quan hệ giữa di chuyển giữa các chuồng và việc mang bệnh vào, và có thể hướng dẫn người mới quy trình phòng dịch."],"name_id":"Biosekuriti pemindahan antar kandang (matras disinfektan)","kanten_id":"Apakah memeriksa dan mengisi cairan matras disinfektan antar kandang, serta menjaga jalur yang tidak bersinggungan dengan kelompok lain dengan sepatu bot yang sudah didisinfeksi?","levels_id":["Melewati begitu saja matras disinfektan yang kosong, dan berpindah lewat jalur yang mengabaikan biosekuriti.","Melewati matras jika diperintah, tetapi sering lalai memeriksa dan mengisi cairan serta memperhatikan jalur.","Jika diperintah, dapat memeriksa cairan matras dan menaati prosedur biosekuriti secara lengkap.","Tanpa diperintah pun, memeriksa dan mengisi cairan, serta berpindah lewat jalur yang tidak bersinggungan dengan kelompok lain.","Memahami hubungan pemindahan antar kandang dengan masuknya penyakit, dan dapat mengajarkan prosedur biosekuriti kepada karyawan baru."]},{"id":"record-plate","name":"頭数照合と記録・プレート更新","kanten":"頭数をリストと照合し、移動日時・個体番号・移動元先を記録して豚房プレートも同時に更新できるか。","levels":["頭数も数えず記録もせず、古いプレートを残して取り違えを招く。","指示があれば記録するが、頭数照合やプレート更新に漏れがある。","指示があれば頭数を照合し、記録とプレート更新をひと通りできる。","指示がなくても照合して記録し、プレートを同時に更新して古い情報を残さない。","古い表示が取り違え・給餌ミスを招くことを理解し、記録と更新の徹底を新人に指導できる。"],"name_en":"Head-Count Verification, Records, and Plate Updates","kanten_en":"Can they verify head counts against the list, record the date and time, individual numbers, and origin and destination, and update the pen plates at the same time?","levels_en":["Neither counts nor records, leaving old plates in place and causing mix-ups.","With guidance can record, but misses count verification or plate updates.","With guidance can verify head counts and complete the basic records and plate updates.","Independently verifies and records, updating the plates at the same time and leaving no old information behind.","Understands that old displays cause mix-ups and feeding mistakes, and can teach new staff thorough recording and updating."],"name_vi":"Đối chiếu số con, ghi chép và cập nhật bảng thông tin","kanten_vi":"Có đối chiếu số con với danh sách, ghi ngày giờ di chuyển, số tai, nơi đi nơi đến, và cập nhật luôn bảng thông tin ở ô chuồng không.","levels_vi":["Không đếm số con, không ghi chép, để lại bảng cũ gây nhầm con.","Nếu được chỉ thị thì ghi chép, nhưng còn thiếu sót về đối chiếu số con và cập nhật bảng.","Nếu được chỉ thị thì đối chiếu số con, ghi chép và cập nhật bảng được cơ bản.","Dù không có chỉ thị vẫn đối chiếu, ghi chép, cập nhật bảng cùng lúc, không để lại thông tin cũ.","Hiểu bảng hiển thị cũ gây nhầm con, cho ăn sai, và có thể hướng dẫn người mới việc ghi chép và cập nhật triệt để."],"name_id":"Pencocokan jumlah ekor, pencatatan, dan pembaruan papan informasi","kanten_id":"Apakah mencocokkan jumlah ekor dengan daftar, mencatat tanggal-jam pemindahan, nomor individu, asal dan tujuan, serta memperbarui papan petak kandang pada saat yang sama?","levels_id":["Tidak menghitung jumlah ekor dan tidak mencatat, meninggalkan papan lama sehingga terjadi tertukar.","Mencatat jika diperintah, tetapi sering lalai mencocokkan jumlah ekor dan memperbarui papan.","Jika diperintah, dapat mencocokkan jumlah ekor serta melakukan pencatatan dan pembaruan papan secara lengkap.","Tanpa diperintah pun, mencocokkan dan mencatat, memperbarui papan pada saat yang sama, dan tidak meninggalkan informasi lama.","Memahami bahwa tampilan lama menyebabkan tertukar dan salah pemberian pakan, dan dapat mengajarkan pencatatan dan pembaruan yang menyeluruh kepada karyawan baru."]}],"name_en":"Gestation House to Breeding/Grower House Movement","name_vi":"Di chuyển từ chuồng lợn nái mang thai → chuồng phối giống / chuồng hậu bị","name_id":"Pemindahan dari kandang bunting → kandang kawin / kandang babi pengganti","purposeShort_en":"Keep the pig flow and connect sows to the next house","purposeShort_vi":"Giữ đúng luồng luân chuyển lợn (pig flow), nối tiếp sang chuồng kế","purposeShort_id":"Menyambungkan ke kandang berikutnya dengan menjaga alur pemindahan babi (pig flow)"},{"id":"scraper","category":"facility","no":"No.19","name":"スクレーパー動作確認","purposeShort":"除糞機能を正常に保ち、機械トラブルを早期発見して大故障を防ぐ","gyomu":"19","aspects":[{"id":"safety-power","name":"電源遮断など安全手順","kanten":"確認・清掃の前に必ず電源を切り、回転部・可動部に安全に触れられるか。","levels":["電源を切らずに点検・清掃し、回転部に触れて事故の危険を招く。","指示があれば電源を切るが、徹底が甘く危険な操作が残る。","指示があれば確認・清掃前に電源をひと通り切れる。","指示がなくても必ず電源を切ってから安全に点検・清掃する。","回転部の危険を理解し、電源遮断など安全手順を新人に指導できる。"],"name_en":"Safety Procedures Including Power Shutoff","kanten_en":"Can they always cut the power before inspection and cleaning and touch rotating and moving parts safely?","levels_en":["Inspects and cleans without cutting the power, touching rotating parts and risking accidents.","With guidance cuts the power, but the habit is weak and unsafe actions remain.","With guidance can cut the power before inspection and cleaning as a basic routine.","Independently always cuts the power before inspecting and cleaning safely.","Understands the dangers of rotating parts, and can teach new staff safety procedures including power shutoff."],"name_vi":"Quy trình an toàn như ngắt điện","kanten_vi":"Trước khi kiểm tra, vệ sinh có luôn ngắt điện, chạm vào bộ phận quay, bộ phận chuyển động một cách an toàn không.","levels_vi":["Không ngắt điện mà kiểm tra, vệ sinh, chạm vào bộ phận quay gây nguy cơ tai nạn.","Nếu được chỉ thị thì ngắt điện, nhưng chưa triệt để, vẫn còn thao tác nguy hiểm.","Nếu được chỉ thị thì ngắt điện trước khi kiểm tra, vệ sinh được cơ bản.","Dù không có chỉ thị vẫn luôn ngắt điện rồi mới kiểm tra, vệ sinh an toàn.","Hiểu nguy hiểm của bộ phận quay, và có thể hướng dẫn người mới quy trình an toàn như ngắt điện."],"name_id":"Prosedur keselamatan seperti mematikan listrik","kanten_id":"Apakah selalu mematikan listrik sebelum pemeriksaan dan pembersihan, sehingga aman saat menyentuh bagian yang berputar atau bergerak?","levels_id":["Memeriksa dan membersihkan tanpa mematikan listrik, menyentuh bagian berputar, dan menimbulkan bahaya kecelakaan.","Mematikan listrik jika diperintah, tetapi tidak konsisten sehingga masih ada tindakan berbahaya.","Jika diperintah, dapat mematikan listrik sebelum pemeriksaan dan pembersihan secara lengkap.","Tanpa diperintah pun, selalu mematikan listrik lebih dulu, lalu memeriksa dan membersihkan dengan aman.","Memahami bahaya bagian yang berputar, dan dapat mengajarkan prosedur keselamatan seperti mematikan listrik kepada karyawan baru."]},{"id":"visual-clear","name":"刃・通り道の目視点検と異物除去","kanten":"刃の曲がり・欠けを端から端まで照らして確認し、通り道の糞のかたまり・異物を取り除けるか。","levels":["目視点検をせず、通り道の異物も放置して詰まり・故障を招く。","指示があれば見るが、刃の端までの確認や異物除去に漏れがある。","指示があれば懐中電灯で刃と通り道をひと通り点検し、異物を除去できる。","指示がなくても刃を端から端まで照らして確認し、異物を手袋をして取り除く。","異物が詰まり・故障につながることを理解し、目視点検の着眼点を新人に指導できる。"],"name_en":"Visual Inspection of the Blade and Path, and Removing Foreign Objects","kanten_en":"Can they shine a light along the blade from end to end to check for bends and chips, and remove manure clumps and foreign objects from the path?","levels_en":["Skips visual inspection and leaves foreign objects in the path, causing clogs and breakdowns.","With guidance can look, but misses checking to the ends of the blade or removing foreign objects.","With guidance can inspect the blade and path with a flashlight and remove foreign objects through the basic routine.","Independently shines a light along the blade from end to end and removes foreign objects wearing gloves.","Understands that foreign objects lead to clogs and breakdowns, and can teach new staff the key points of visual inspection."],"name_vi":"Kiểm tra bằng mắt lưỡi cào, đường chạy và loại bỏ dị vật","kanten_vi":"Có soi đèn kiểm tra lưỡi cào từ đầu đến cuối xem có cong, mẻ không, và loại bỏ cục phân, dị vật trên đường chạy không.","levels_vi":["Không kiểm tra bằng mắt, bỏ mặc dị vật trên đường chạy, gây tắc và hỏng máy.","Nếu được chỉ thị thì xem, nhưng còn thiếu sót về kiểm tra đến tận đầu lưỡi cào và loại bỏ dị vật.","Nếu được chỉ thị thì dùng đèn pin kiểm tra lưỡi cào, đường chạy và loại bỏ dị vật được cơ bản.","Dù không có chỉ thị vẫn soi đèn kiểm tra lưỡi cào từ đầu đến cuối và đeo găng tay loại bỏ dị vật.","Hiểu dị vật dẫn đến tắc, hỏng máy, và có thể hướng dẫn người mới các điểm cần xem khi kiểm tra bằng mắt."],"name_id":"Pemeriksaan visual bilah dan jalur serta pembuangan benda asing","kanten_id":"Apakah menyorot bilah dari ujung ke ujung untuk memeriksa bengkok dan gumpil, serta membuang gumpalan kotoran dan benda asing di jalurnya?","levels_id":["Tidak melakukan pemeriksaan visual dan membiarkan benda asing di jalur, sehingga terjadi penyumbatan dan kerusakan.","Melihat jika diperintah, tetapi sering lalai memeriksa sampai ujung bilah dan membuang benda asing.","Jika diperintah, dapat memeriksa bilah dan jalur dengan senter serta membuang benda asing secara lengkap.","Tanpa diperintah pun, menyorot bilah dari ujung ke ujung dan membuang benda asing dengan memakai sarung tangan.","Memahami bahwa benda asing menyebabkan penyumbatan dan kerusakan, dan dapat mengajarkan titik perhatian pemeriksaan visual kepada karyawan baru."]},{"id":"run-check","name":"試運転での動きとかき出し確認","kanten":"試運転で止まり・引っ掛かり・遅れがないかを見て、通り道に糞が残っていないか確認できるか。","levels":["動作確認をせず、途中停止や糞の残りがあっても気づかない。","指示があれば動かすが、動きの遅れやかき残しの確認に漏れがある。","指示があれば試運転してスムーズな動きとかき出しをひと通り確認できる。","指示がなくても動く部分から体を離して試運転し、いつもとの動きの違いに早く気づく。","正常時の動作音・速さを覚えて比べる意味を理解し、試運転確認のコツを新人に指導できる。"],"name_en":"Checking Movement and Scraping in a Test Run","kanten_en":"Can they watch a test run for stops, snags, and delays, and check that no manure is left in the path?","levels_en":["Does not check operation and does not notice mid-run stops or leftover manure.","With guidance can run it, but misses checking for slow movement or missed scraping.","With guidance can do a test run and check smooth movement and scraping through the basic routine.","Independently keeps clear of moving parts during test runs and quickly notices differences from the usual movement.","Understands why to memorize and compare the normal sound and speed, and can teach new staff the knack of test-run checks."],"name_vi":"Chạy thử để kiểm tra chuyển động và việc cào phân","kanten_vi":"Có chạy thử để xem máy có dừng, vướng, chạy chậm không, và kiểm tra trên đường chạy còn sót phân không.","levels_vi":["Không kiểm tra hoạt động, máy dừng giữa chừng hay còn sót phân cũng không nhận ra.","Nếu được chỉ thị thì cho chạy, nhưng còn thiếu sót về kiểm tra chạy chậm và phân cào sót.","Nếu được chỉ thị thì chạy thử và kiểm tra máy chạy trơn tru, cào sạch được cơ bản.","Dù không có chỉ thị vẫn đứng cách xa bộ phận chuyển động khi chạy thử, và sớm nhận ra khác biệt so với chuyển động thường ngày.","Hiểu ý nghĩa của việc nhớ tiếng máy, tốc độ khi bình thường để so sánh, và có thể hướng dẫn người mới mẹo kiểm tra khi chạy thử."],"name_id":"Uji jalan untuk memeriksa gerakan dan pengerukan kotoran","kanten_id":"Apakah saat uji jalan mengamati adanya berhenti, tersangkut, atau keterlambatan, dan memeriksa apakah masih ada kotoran tersisa di jalur?","levels_id":["Tidak memeriksa kerja mesin, dan tidak sadar walaupun mesin berhenti di tengah jalan atau kotoran tersisa.","Menjalankan jika diperintah, tetapi sering lalai memeriksa gerakan lambat dan kotoran yang belum terkeruk.","Jika diperintah, dapat melakukan uji jalan dan memeriksa gerakan lancar serta pengerukan secara lengkap.","Tanpa diperintah pun, menjauhkan badan dari bagian yang bergerak saat uji jalan, dan cepat menyadari perbedaan dari gerakan biasanya.","Memahami arti mengingat suara dan kecepatan normal untuk dibandingkan, dan dapat mengajarkan kiat pemeriksaan uji jalan kepada karyawan baru."]},{"id":"wear-report","name":"チェーン・ワイヤ点検と異常時の停止・報告","kanten":"チェーン・ワイヤの張り具合を手で押して確かめ、摩耗・錆を照らして点検し、異常があれば無理に動かさず自分で修理せず報告できるか。","levels":["張り・摩耗を見ずゆるみやすり減りを放置し、糞の滞留や大きな故障を招く。","指示があれば点検するが、たるみやすり減りの見極めに漏れがある。","指示があれば張り具合と摩耗・錆をひと通り点検し、メモを残せる。","指示がなくても毎回点検し、異常があれば無理に動かさず電源を切って報告する。","早期発見が大きな故障を防ぐことを理解し、点検の着眼点と異常時対応を新人に指導できる。"],"name_en":"Chain and Wire Inspection, and Stopping and Reporting on Abnormality","kanten_en":"Can they press the chain and wire by hand to check tension, shine a light to inspect for wear and rust, and on any abnormality report it without forcing operation or repairing it themselves?","levels_en":["Ignores tension and wear, leaving slack and thinning parts, causing manure buildup and major breakdowns.","With guidance can inspect, but misses judging slack and thinning.","With guidance can inspect tension, wear, and rust and leave a note through the basic routine.","Independently inspects every time and, on any abnormality, cuts the power and reports instead of forcing operation.","Understands that early detection prevents major breakdowns, and can teach new staff inspection points and abnormality response."],"name_vi":"Kiểm tra xích, dây cáp; dừng và báo cáo khi bất thường","kanten_vi":"Có ấn tay kiểm tra độ căng của xích, dây cáp, soi đèn kiểm tra mài mòn, gỉ sét, và khi có bất thường thì không cố cho chạy, không tự sửa mà báo cáo không.","levels_vi":["Không xem độ căng, mài mòn, bỏ mặc chỗ chùng, chỗ mòn, gây ứ đọng phân và hỏng lớn.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót trong nhận biết chỗ chùng và chỗ mòn.","Nếu được chỉ thị thì kiểm tra độ căng, mài mòn, gỉ sét và ghi chú lại được cơ bản.","Dù không có chỉ thị vẫn kiểm tra mỗi lần, khi có bất thường thì không cố cho chạy mà ngắt điện và báo cáo.","Hiểu phát hiện sớm giúp tránh hỏng lớn, và có thể hướng dẫn người mới các điểm cần xem khi kiểm tra và cách xử lý bất thường."],"name_id":"Pemeriksaan rantai dan kawat, berhenti dan melapor saat tidak normal","kanten_id":"Apakah menekan dengan tangan untuk memeriksa ketegangan rantai dan kawat, menyorot untuk memeriksa keausan dan karat, dan jika ada yang tidak normal melapor tanpa memaksakan jalan atau memperbaiki sendiri?","levels_id":["Tidak melihat ketegangan dan keausan, membiarkan bagian kendur dan menipis, sehingga kotoran menumpuk dan terjadi kerusakan besar.","Memeriksa jika diperintah, tetapi sering lalai menilai bagian kendur dan aus.","Jika diperintah, dapat memeriksa ketegangan, keausan, dan karat serta meninggalkan catatan secara lengkap.","Tanpa diperintah pun, memeriksa setiap kali, dan jika ada yang tidak normal mematikan listrik lalu melapor tanpa memaksakan jalan.","Memahami bahwa penemuan dini mencegah kerusakan besar, dan dapat mengajarkan titik pemeriksaan dan penanganan saat tidak normal kepada karyawan baru."]},{"id":"record-report","name":"点検結果の記録と具体的な報告","kanten":"「異常なし」でも点検記録用紙に記入し、異音の種類など異常の内容を具体的に伝えられるか。","levels":["点検しても記録を残さず、異常があっても内容を伝えない。","指示があれば記録するが、内容があいまいで抜け漏れが多い。","指示があれば異常なしを含めてひと通り記録できる。","指示がなくても毎回記録し、金属音・きしみ音など異音の種類を具体的に報告する。","具体的な報告が原因特定を早めることを理解し、記録と報告の書き方を新人に指導できる。"],"name_en":"Recording Inspection Results and Reporting Concretely","kanten_en":"Can they fill in the inspection record sheet even for \"no abnormality,\" and describe abnormalities concretely, such as the type of unusual noise?","levels_en":["Leaves no record after inspecting, and does not describe abnormalities even when they occur.","With guidance can record, but the content is vague with many gaps.","With guidance can record everything including \"no abnormality\" through the basic routine.","Independently records every time and reports the type of unusual noise concretely, such as metallic or squeaking sounds.","Understands that concrete reports speed up finding the cause, and can teach new staff how to write records and reports."],"name_vi":"Ghi chép kết quả kiểm tra và báo cáo cụ thể","kanten_vi":"Dù「không có bất thường」vẫn ghi vào phiếu ghi chép kiểm tra, và truyền đạt cụ thể nội dung bất thường như loại tiếng lạ không.","levels_vi":["Kiểm tra xong không ghi lại, có bất thường cũng không truyền đạt nội dung.","Nếu được chỉ thị thì ghi chép, nhưng nội dung mơ hồ, nhiều thiếu sót.","Nếu được chỉ thị thì ghi chép được cơ bản, kể cả khi không có bất thường.","Dù không có chỉ thị vẫn ghi chép mỗi lần, báo cáo cụ thể loại tiếng lạ như tiếng kim loại, tiếng cót két.","Hiểu báo cáo cụ thể giúp tìm nguyên nhân nhanh hơn, và có thể hướng dẫn người mới cách viết ghi chép và báo cáo."],"name_id":"Mencatat hasil pemeriksaan dan melapor secara konkret","kanten_id":"Apakah mengisi lembar catatan pemeriksaan walaupun「tidak ada kelainan」, dan menyampaikan isi kelainan secara konkret seperti jenis suara aneh?","levels_id":["Tidak meninggalkan catatan setelah memeriksa, dan tidak menyampaikan isinya walaupun ada kelainan.","Mencatat jika diperintah, tetapi isinya samar dan banyak yang terlewat.","Jika diperintah, dapat mencatat secara lengkap termasuk saat tidak ada kelainan.","Tanpa diperintah pun, mencatat setiap kali, dan melaporkan jenis suara aneh secara konkret seperti suara logam atau derit.","Memahami bahwa laporan konkret mempercepat penentuan penyebab, dan dapat mengajarkan cara menulis catatan dan laporan kepada karyawan baru."]}],"name_en":"Manure Scraper Operation Check","name_vi":"Kiểm tra hoạt động máy cào phân","name_id":"Pemeriksaan kerja alat pengeruk kotoran","purposeShort_en":"Keep manure removal working, detect mechanical trouble early, and prevent major breakdowns","purposeShort_vi":"Giữ chức năng dọn phân hoạt động bình thường, phát hiện sớm trục trặc máy để tránh hỏng lớn","purposeShort_id":"Menjaga fungsi pembersihan kotoran tetap normal, menemukan gangguan mesin sejak dini, dan mencegah kerusakan besar"},{"id":"fan-clean","category":"facility","no":"No.29","name":"ファン清掃","purposeShort":"換気能力を保ち、呼吸器トラブル・暑熱ストレスを防ぎ設備を長持ちさせる","gyomu":"29","aspects":[{"id":"power-off","name":"電源遮断と安全な清掃","kanten":"作業前に必ず電源を切り、モーター・配線に水をかけずに清掃できるか。","levels":["電源を切らずに清掃して回転部に接触し、モーターや配線に水をかける危険な作業をする。","指示があれば電源を切るが、水かけ回避などの徹底が甘い。","指示があれば電源を切り、羽根が完全に止まるのを待ってから作業できる。","指示がなくても電源を切り、モーターや配線を避けて安全に清掃する。","感電・巻き込みの危険を理解し、安全な清掃手順を新人に指導できる。"],"name_en":"Power Shutoff and Safe Cleaning","kanten_en":"Can they always cut the power before work and clean without splashing water on motors and wiring?","levels_en":["Cleans without cutting the power, contacting rotating parts, and works dangerously by splashing water on motors and wiring.","With guidance cuts the power, but is lax about avoiding water splashes and the like.","With guidance can cut the power and wait until the blades stop completely before working.","Independently cuts the power and cleans safely while avoiding motors and wiring.","Understands the dangers of electric shock and entanglement, and can teach new staff safe cleaning procedures."],"name_vi":"Ngắt điện và vệ sinh an toàn","kanten_vi":"Trước khi làm có luôn ngắt điện, vệ sinh mà không xịt nước vào mô-tơ, dây điện không.","levels_vi":["Không ngắt điện mà vệ sinh, chạm vào bộ phận quay, làm việc nguy hiểm như xịt nước vào mô-tơ, dây điện.","Nếu được chỉ thị thì ngắt điện, nhưng chưa triệt để trong việc tránh xịt nước v.v.","Nếu được chỉ thị thì ngắt điện và chờ cánh quạt dừng hẳn rồi mới làm.","Dù không có chỉ thị vẫn ngắt điện, tránh mô-tơ và dây điện, vệ sinh an toàn.","Hiểu nguy hiểm điện giật, bị cuốn kẹt, và có thể hướng dẫn người mới quy trình vệ sinh an toàn."],"name_id":"Mematikan listrik dan membersihkan dengan aman","kanten_id":"Apakah selalu mematikan listrik sebelum bekerja, dan membersihkan tanpa menyiram air ke motor dan kabel?","levels_id":["Membersihkan tanpa mematikan listrik hingga menyentuh bagian berputar, dan bekerja berbahaya dengan menyiram air ke motor dan kabel.","Mematikan listrik jika diperintah, tetapi tidak konsisten menghindari siraman air.","Jika diperintah, dapat mematikan listrik dan menunggu baling-baling berhenti sepenuhnya sebelum bekerja.","Tanpa diperintah pun, mematikan listrik dan membersihkan dengan aman sambil menghindari motor dan kabel.","Memahami bahaya tersengat listrik dan terlilit, dan dapat mengajarkan urutan pembersihan yang aman kepada karyawan baru."]},{"id":"dry-first","name":"乾いた埃払いと羽根裏の洗浄","kanten":"水をかける前にシャッター・防鳥ネットの埃を乾いたまま払い、羽根の裏側まで汚れを落とせるか。","levels":["いきなり水をかけて埃を泥にし、羽根の裏の汚れも残したままにする。","指示があれば清掃するが、乾いた埃払いの先行や羽根裏の洗浄に漏れがある。","指示があれば埃を先に払い、羽根・シャッター・ネットをひと通り洗える。","指示がなくても乾いた状態から順に清掃し、羽根裏やこびりついた汚れまで落とす。","汚れと風量低下の関係を理解し、効率のよい清掃の順序を新人に指導できる。"],"name_en":"Dry Dusting First and Washing Behind the Blades","kanten_en":"Can they dust the shutters and bird nets while still dry before applying water, and clean off the dirt down to the back of the blades?","levels_en":["Splashes water right away, turning dust into mud, and leaves the dirt on the back of the blades.","With guidance can clean, but misses dry dusting first or washing behind the blades.","With guidance can dust first and wash the blades, shutters, and nets through the basic routine.","Independently cleans in order starting from dry, removing even the dirt behind the blades and caked-on grime.","Understands how dirt relates to reduced airflow, and can teach new staff an efficient cleaning order."],"name_vi":"Phủi bụi khô trước và rửa mặt sau cánh quạt","kanten_vi":"Trước khi xịt nước có phủi bụi cửa chớp, lưới chắn chim khi còn khô, và làm sạch chất bẩn đến tận mặt sau cánh quạt không.","levels_vi":["Xịt nước ngay làm bụi thành bùn, và để nguyên chất bẩn ở mặt sau cánh quạt.","Nếu được chỉ thị thì vệ sinh, nhưng còn thiếu sót về phủi bụi khô trước và rửa mặt sau cánh quạt.","Nếu được chỉ thị thì phủi bụi trước, rửa cánh quạt, cửa chớp, lưới được cơ bản.","Dù không có chỉ thị vẫn vệ sinh theo thứ tự từ lúc còn khô, làm sạch cả mặt sau cánh quạt và chất bẩn bám cứng.","Hiểu quan hệ giữa chất bẩn và giảm lưu lượng gió, và có thể hướng dẫn người mới trình tự vệ sinh hiệu quả."],"name_id":"Membersihkan debu kering lebih dulu dan mencuci sisi belakang baling-baling","kanten_id":"Apakah sebelum menyiram air membersihkan debu penutup (shutter) dan jaring pencegah burung dalam keadaan kering, dan menghilangkan kotoran sampai sisi belakang baling-baling?","levels_id":["Langsung menyiram air sehingga debu menjadi lumpur, dan membiarkan kotoran di sisi belakang baling-baling.","Membersihkan jika diperintah, tetapi sering lalai mendahulukan pembersihan debu kering dan mencuci sisi belakang baling-baling.","Jika diperintah, dapat membersihkan debu lebih dulu dan mencuci baling-baling, penutup, dan jaring secara lengkap.","Tanpa diperintah pun, membersihkan berurutan mulai dari keadaan kering, sampai sisi belakang baling-baling dan kotoran yang menempel keras.","Memahami hubungan kotoran dengan turunnya aliran udara, dan dapat mengajarkan urutan pembersihan yang efisien kepada karyawan baru."]},{"id":"belt-check","name":"ファンベルトの張り・劣化点検","kanten":"指で押して1〜2cm沈む張りかを確かめ、ひび割れ・摩耗・ほつれを見つけて指導係に報告できるか。","levels":["ベルトを点検せず、劣化を放置して風量低下や故障を招く。","指示があれば見るが、張り具合やひび割れ・ほつれの見極めに漏れがある。","指示があれば指で押して張りを確かめ、傷みの有無をひと通り点検できる。","指示がなくても清掃のたびに点検し、ひび割れ・摩耗・ほつれがあれば交換が必要と報告する。","ベルトの寿命が1〜2年であることを踏まえ、劣化のサインと点検を新人に指導できる。"],"name_en":"Inspecting Fan-Belt Tension and Deterioration","kanten_en":"Can they check that the belt sinks 1-2 cm when pressed with a finger, and find cracks, wear, and fraying and report them to the trainer?","levels_en":["Does not inspect the belt, leaving deterioration unattended and causing reduced airflow and breakdowns.","With guidance can look, but misses judging tension, cracks, and fraying.","With guidance can press with a finger to check tension and inspect for damage through the basic routine.","Independently inspects at every cleaning and reports that replacement is needed when there are cracks, wear, or fraying.","Knowing that belts last one to two years, can teach new staff the signs of deterioration and the inspection."],"name_vi":"Kiểm tra độ căng và xuống cấp của dây curoa quạt","kanten_vi":"Có ấn ngón tay kiểm tra độ căng lún 1〜2cm không, phát hiện nứt, mòn, xơ và báo cáo cho người hướng dẫn không.","levels_vi":["Không kiểm tra dây curoa, bỏ mặc xuống cấp, gây giảm lưu lượng gió và hỏng máy.","Nếu được chỉ thị thì xem, nhưng còn thiếu sót trong nhận biết độ căng, nứt, xơ.","Nếu được chỉ thị thì ấn ngón tay kiểm tra độ căng và xem có hư hỏng không được cơ bản.","Dù không có chỉ thị vẫn kiểm tra mỗi lần vệ sinh, nếu có nứt, mòn, xơ thì báo cáo là cần thay.","Nắm được tuổi thọ dây curoa là 1〜2 năm, và có thể hướng dẫn người mới dấu hiệu xuống cấp và cách kiểm tra."],"name_id":"Memeriksa ketegangan dan kerusakan sabuk (belt) kipas","kanten_id":"Apakah menekan dengan jari untuk memastikan ketegangan melesak 1〜2cm, serta menemukan retak, aus, dan serabut lalu melaporkannya kepada pembimbing?","levels_id":["Tidak memeriksa sabuk dan membiarkan kondisinya memburuk, sehingga aliran udara turun dan mesin rusak.","Melihat jika diperintah, tetapi sering lalai menilai ketegangan, retak, dan serabut.","Jika diperintah, dapat menekan dengan jari untuk memeriksa ketegangan dan memeriksa ada tidaknya kerusakan secara lengkap.","Tanpa diperintah pun, memeriksa setiap kali membersihkan, dan jika ada retak, aus, atau serabut melaporkan bahwa perlu diganti.","Dengan memahami bahwa umur sabuk 1〜2 tahun, dapat mengajarkan tanda kerusakan dan pemeriksaannya kepada karyawan baru."]},{"id":"restart-verify","name":"シャッター開閉と試運転確認","kanten":"シャッターが軽く開閉するか手で確かめ、水気が切れてから試運転して回転・風・異音を確認できるか。","levels":["洗いっぱなしで確認せず、動きの重さや異音があっても放置する。","指示があれば確認するが、開閉の重さや異音の聞き分けに漏れがある。","指示があれば水気が切れてから電源を入れ、回転と風の出をひと通り確認できる。","指示がなくても開閉・回転・風・異音を確かめ、キュルキュル音などに気づけば報告する。","動きの重さや異音が風量低下・故障のサインと理解し、確認の仕方を新人に指導できる。"],"name_en":"Shutter Movement and Test-Run Checks","kanten_en":"Can they check by hand that the shutters open and close lightly, and test-run after the water has dried to check rotation, airflow, and unusual noise?","levels_en":["Leaves it as washed without checking, and ignores stiff movement and unusual noise.","With guidance can check, but misses noticing stiff movement or telling unusual noises apart.","With guidance can power on after the water has dried and check rotation and airflow through the basic routine.","Independently checks shutter movement, rotation, airflow, and noise, and reports squealing sounds and the like when noticed.","Understands that stiff movement and unusual noise are signs of reduced airflow and breakdowns, and can teach new staff how to check."],"name_vi":"Đóng mở cửa chớp và kiểm tra chạy thử","kanten_vi":"Có dùng tay kiểm tra cửa chớp đóng mở nhẹ nhàng không, chờ ráo nước rồi chạy thử để kiểm tra quay, gió, tiếng lạ không.","levels_vi":["Rửa xong bỏ đó không kiểm tra, cửa nặng hay có tiếng lạ cũng mặc kệ.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót trong nhận ra đóng mở nặng và phân biệt tiếng lạ.","Nếu được chỉ thị thì chờ ráo nước rồi bật điện, kiểm tra quay và gió thổi ra được cơ bản.","Dù không có chỉ thị vẫn kiểm tra đóng mở, quay, gió, tiếng lạ, nếu nghe tiếng rít v.v. thì báo cáo.","Hiểu chuyển động nặng, tiếng lạ là dấu hiệu giảm lưu lượng gió, hỏng máy, và có thể hướng dẫn người mới cách kiểm tra."],"name_id":"Buka-tutup penutup (shutter) dan pemeriksaan uji jalan","kanten_id":"Apakah memeriksa dengan tangan bahwa penutup membuka-menutup dengan ringan, dan setelah airnya kering melakukan uji jalan untuk memeriksa putaran, angin, dan suara aneh?","levels_id":["Meninggalkan begitu saja setelah dicuci tanpa memeriksa, dan membiarkan gerakan berat maupun suara aneh.","Memeriksa jika diperintah, tetapi sering lalai menyadari buka-tutup yang berat dan membedakan suara aneh.","Jika diperintah, dapat menyalakan listrik setelah airnya kering dan memeriksa putaran serta keluarnya angin secara lengkap.","Tanpa diperintah pun, memeriksa buka-tutup, putaran, angin, dan suara aneh, dan melapor jika menyadari bunyi mencicit dan sejenisnya.","Memahami bahwa gerakan berat dan suara aneh adalah tanda turunnya aliran udara dan kerusakan, dan dapat mengajarkan cara memeriksanya kepada karyawan baru."]},{"id":"notify-record","name":"作業の周知と清掃記録・報告","kanten":"清掃前に指導係へ一言伝えてから電源を切り、清掃日と異音・破損などの気づきを記録・報告できるか。","levels":["誰にも伝えず勝手に電源を切り、清掃日も気づきも残さない。","指示があれば伝えて記録するが、気づきの報告に抜けが多い。","指示があれば作業前に周知し、清掃日と気づきをひと通り記録できる。","指示がなくても周知してから作業し、換気設定は変えずに異音・破損を記録・報告する。","周知と記録が事故・故障防止につながることを理解し、報告の要点を新人に指導できる。"],"name_en":"Announcing the Work, and Cleaning Records and Reports","kanten_en":"Can they tell the trainer before cleaning and then cut the power, and record and report the cleaning date and findings such as unusual noise and damage?","levels_en":["Cuts the power on their own without telling anyone, leaving neither cleaning dates nor findings.","With guidance can inform and record, but often fails to report findings.","With guidance can announce before working and record the cleaning date and findings through the basic routine.","Independently announces before working, and records and reports unusual noise and damage without changing the ventilation settings.","Understands that announcements and records prevent accidents and breakdowns, and can teach new staff the key points of reporting."],"name_vi":"Thông báo trước khi làm và ghi chép, báo cáo vệ sinh","kanten_vi":"Trước khi vệ sinh có báo một tiếng với người hướng dẫn rồi mới ngắt điện, và ghi chép, báo cáo ngày vệ sinh cùng những điều nhận thấy như tiếng lạ, hư hỏng không.","levels_vi":["Không báo ai, tự ý ngắt điện, không ghi lại ngày vệ sinh lẫn điều nhận thấy.","Nếu được chỉ thị thì báo và ghi chép, nhưng hay bỏ sót báo cáo điều nhận thấy.","Nếu được chỉ thị thì thông báo trước khi làm, ghi ngày vệ sinh và điều nhận thấy được cơ bản.","Dù không có chỉ thị vẫn thông báo rồi mới làm, không đổi cài đặt thông gió, ghi chép và báo cáo tiếng lạ, hư hỏng.","Hiểu việc thông báo và ghi chép giúp phòng tai nạn, hỏng hóc, và có thể hướng dẫn người mới các điểm chính khi báo cáo."],"name_id":"Memberitahukan pekerjaan serta catatan dan laporan pembersihan","kanten_id":"Apakah sebelum membersihkan memberi tahu pembimbing lalu mematikan listrik, serta mencatat dan melaporkan tanggal pembersihan dan temuan seperti suara aneh dan kerusakan?","levels_id":["Mematikan listrik seenaknya tanpa memberi tahu siapa pun, dan tidak meninggalkan tanggal pembersihan maupun temuan.","Memberi tahu dan mencatat jika diperintah, tetapi sering terlewat melaporkan temuan.","Jika diperintah, dapat memberitahukan sebelum bekerja dan mencatat tanggal pembersihan serta temuan secara lengkap.","Tanpa diperintah pun, memberitahukan lebih dulu sebelum bekerja, dan mencatat serta melaporkan suara aneh dan kerusakan tanpa mengubah pengaturan ventilasi.","Memahami bahwa pemberitahuan dan pencatatan mencegah kecelakaan dan kerusakan, dan dapat mengajarkan pokok pelaporan kepada karyawan baru."]}],"name_en":"Fan Cleaning","name_vi":"Vệ sinh quạt","name_id":"Membersihkan kipas","purposeShort_en":"Maintain ventilation capacity, prevent respiratory trouble and heat stress, and extend equipment life","purposeShort_vi":"Duy trì năng lực thông gió, phòng bệnh hô hấp, stress do nóng và giúp thiết bị bền lâu","purposeShort_id":"Menjaga kemampuan ventilasi, mencegah gangguan pernapasan dan stres panas, serta membuat peralatan awet"},{"id":"pad-tank","category":"facility","no":"No.30","name":"パドタンク清掃（夏季）","purposeShort":"クーリング性能を保ち、藻・細菌・悪臭を防ぎ設備を長持ちさせる","gyomu":"30","aspects":[{"id":"regular-clean","name":"定期清掃と藻・ぬめりの早期発見","kanten":"夏は週1〜2回の目安で清掃し、緑色の水・ぬめりを清掃のサインとして見逃さないか。作業前に電源を切り水を抜けるか。","levels":["清掃を怠って藻・ぬめりを発生させ、電源も切らずに作業する。","指示があれば清掃するが、頻度や電源遮断・排水の手順に漏れがある。","指示があれば電源を切り水を抜いて、ひと通り清掃できる。","指示がなくても目安の頻度で清掃し、緑色の水・ぬめりを見たら回数に関係なく清掃する。","クーリング性能と衛生の関係を理解し、定期清掃の手順とサインを新人に指導できる。"],"name_en":"Regular Cleaning and Early Detection of Algae and Slime","kanten_en":"Can they clean about once or twice a week in summer and not overlook green water and slime as signs to clean? Can they cut the power and drain the water before work?","levels_en":["Neglects cleaning, letting algae and slime develop, and works without cutting the power.","With guidance can clean, but misses the frequency or the power-shutoff and draining steps.","With guidance can cut the power, drain the water, and clean through the basic routine.","Independently cleans at the standard frequency, and cleans regardless of the count whenever green water or slime appears.","Understands the link between cooling performance and hygiene, and can teach new staff the regular cleaning procedure and the signs."],"name_vi":"Vệ sinh định kỳ và phát hiện sớm rêu tảo, nhớt","kanten_vi":"Mùa hè có vệ sinh theo mức chuẩn 1〜2 lần/tuần, không bỏ qua nước xanh, nhớt là dấu hiệu cần vệ sinh không. Trước khi làm có ngắt điện, xả nước không.","levels_vi":["Lười vệ sinh làm phát sinh rêu tảo, nhớt, làm việc mà không ngắt điện.","Nếu được chỉ thị thì vệ sinh, nhưng còn thiếu sót về tần suất và quy trình ngắt điện, xả nước.","Nếu được chỉ thị thì ngắt điện, xả nước và vệ sinh được cơ bản.","Dù không có chỉ thị vẫn vệ sinh theo tần suất chuẩn, thấy nước xanh, nhớt thì vệ sinh ngay không kể số lần.","Hiểu quan hệ giữa hiệu quả làm mát và vệ sinh, và có thể hướng dẫn người mới quy trình vệ sinh định kỳ và các dấu hiệu."],"name_id":"Pembersihan berkala dan penemuan dini lumut dan lendir","kanten_id":"Apakah pada musim panas membersihkan dengan patokan 1〜2 kali seminggu, dan tidak melewatkan air hijau dan lendir sebagai tanda perlu dibersihkan? Apakah sebelum bekerja mematikan listrik dan membuang airnya?","levels_id":["Lalai membersihkan sehingga lumut dan lendir tumbuh, dan bekerja tanpa mematikan listrik.","Membersihkan jika diperintah, tetapi sering lalai soal frekuensi serta urutan mematikan listrik dan membuang air.","Jika diperintah, dapat mematikan listrik, membuang air, dan membersihkan secara lengkap.","Tanpa diperintah pun, membersihkan sesuai frekuensi patokan, dan begitu melihat air hijau atau lendir langsung membersihkan tanpa memandang jumlah kali.","Memahami hubungan kemampuan pendinginan dengan kebersihan, dan dapat mengajarkan urutan pembersihan berkala dan tanda-tandanya kepada karyawan baru."]},{"id":"soft-wash","name":"傷をつけないやさしい洗い方","kanten":"柔らかいブラシで底・角・水面の線をやさしくこすり、高圧洗浄機を使わずすすぎ水が透明になるまで洗えるか。","levels":["硬いブラシや高圧で強くこすり、タンクに傷をつけてかえって汚れやすくする。","指示があれば洗うが、力加減や底・角の洗い残しにムラがある。","指示があれば柔らかいブラシでやさしく、汚れやすい所をひと通り洗える。","指示がなくてもすすぎ水が透明になるまで洗い、高圧をかけずに仕上げる。","傷に汚れがたまる原理を理解し、タンクを傷めない洗い方を新人に指導できる。"],"name_en":"Gentle Washing That Avoids Scratches","kanten_en":"Can they gently scrub the bottom, corners, and waterline with a soft brush, and wash without a pressure washer until the rinse water runs clear?","levels_en":["Scrubs hard with stiff brushes or high pressure, scratching the tank and making it dirtier more easily.","With guidance can wash, but is inconsistent in pressure and leaves the bottom and corners unwashed in places.","With guidance can wash the dirt-prone spots gently with a soft brush through the basic routine.","Independently washes until the rinse water runs clear and finishes without applying high pressure.","Understands why dirt collects in scratches, and can teach new staff washing that does not damage the tank."],"name_vi":"Cách rửa nhẹ nhàng không làm xước","kanten_vi":"Có dùng bàn chải mềm chà nhẹ đáy, góc, vạch mực nước, không dùng máy rửa áp lực cao và rửa đến khi nước tráng trong suốt không.","levels_vi":["Chà mạnh bằng bàn chải cứng, áp lực cao, làm xước bể khiến bể càng dễ bẩn hơn.","Nếu được chỉ thị thì rửa, nhưng lực tay không đều, còn sót chỗ chưa rửa ở đáy, góc.","Nếu được chỉ thị thì dùng bàn chải mềm rửa nhẹ nhàng các chỗ dễ bẩn được cơ bản.","Dù không có chỉ thị vẫn rửa đến khi nước tráng trong suốt, hoàn thiện mà không dùng áp lực cao.","Hiểu nguyên lý chất bẩn tích trong vết xước, và có thể hướng dẫn người mới cách rửa không làm hỏng bể."],"name_id":"Cara mencuci lembut tanpa menggores","kanten_id":"Apakah menggosok lembut dasar, sudut, dan garis batas air dengan sikat lembut, serta mencuci tanpa mesin cuci bertekanan tinggi sampai air bilasan menjadi jernih?","levels_id":["Menggosok keras dengan sikat kaku atau tekanan tinggi, menggores tangki sehingga justru lebih mudah kotor.","Mencuci jika diperintah, tetapi tekanannya tidak merata dan masih ada bagian dasar dan sudut yang terlewat.","Jika diperintah, dapat mencuci bagian yang mudah kotor secara lembut dengan sikat lembut secara lengkap.","Tanpa diperintah pun, mencuci sampai air bilasan jernih dan menyelesaikannya tanpa tekanan tinggi.","Memahami prinsip kotoran menumpuk di goresan, dan dapat mengajarkan cara mencuci yang tidak merusak tangki kepada karyawan baru."]},{"id":"filter-pipe","name":"フィルター・ポンプ・配管の点検","kanten":"フィルターの詰まりを除いて網の目まで洗い、ポンプ・配管の水漏れ・ゆるみを点検し、破れや異常を報告できるか。","levels":["タンクだけ洗って満足し、フィルターの詰まりを放置してポンプに過負荷をかける。","指示があれば点検するが、網の目の詰まりや配管の確認に漏れがある。","指示があればフィルターを洗い、ポンプ・配管をひと通り目視点検できる。","指示がなくても毎回一緒に点検し、破れ・水漏れがあれば自分で直さず報告する。","詰まりとポンプ故障の関係を理解し、フィルター・配管点検を新人に指導できる。"],"name_en":"Inspecting the Filter, Pump, and Piping","kanten_en":"Can they clear filter clogs and wash until the mesh is visible, inspect the pump and piping for leaks and loose connections, and report tears and abnormalities?","levels_en":["Is satisfied with washing only the tank, leaving filter clogs and overloading the pump.","With guidance can inspect, but misses mesh clogs or the piping check.","With guidance can wash the filter and visually inspect the pump and piping through the basic routine.","Independently inspects them together every time, and reports tears and leaks instead of fixing them alone.","Understands how clogs relate to pump failure, and can teach new staff filter and piping inspection."],"name_vi":"Kiểm tra lưới lọc, máy bơm, đường ống","kanten_vi":"Có loại bỏ chỗ tắc của lưới lọc, rửa đến rõ mắt lưới, kiểm tra rò rỉ nước, chỗ nối lỏng của máy bơm, đường ống, và báo cáo khi rách hay bất thường không.","levels_vi":["Chỉ rửa bể là hài lòng, bỏ mặc lưới lọc bị tắc làm máy bơm quá tải.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về chỗ tắc ở mắt lưới và kiểm tra đường ống.","Nếu được chỉ thị thì rửa lưới lọc, kiểm tra bằng mắt máy bơm, đường ống được cơ bản.","Dù không có chỉ thị vẫn kiểm tra cùng lúc mỗi lần, nếu có rách, rò rỉ nước thì không tự sửa mà báo cáo.","Hiểu quan hệ giữa tắc nghẽn và hỏng máy bơm, và có thể hướng dẫn người mới cách kiểm tra lưới lọc, đường ống."],"name_id":"Memeriksa filter, pompa, dan pipa","kanten_id":"Apakah membuang sumbatan filter dan mencucinya sampai lubang saringan terlihat, memeriksa kebocoran air dan sambungan longgar pada pompa dan pipa, serta melaporkan sobek dan kelainan?","levels_id":["Puas hanya mencuci tangki, membiarkan filter tersumbat sehingga pompa bekerja berlebihan.","Memeriksa jika diperintah, tetapi sering lalai memeriksa sumbatan lubang saringan dan pipa.","Jika diperintah, dapat mencuci filter dan memeriksa pompa serta pipa secara visual dengan lengkap.","Tanpa diperintah pun, memeriksanya sekaligus setiap kali, dan jika ada sobek atau kebocoran melapor tanpa memperbaikinya sendiri.","Memahami hubungan penyumbatan dengan kerusakan pompa, dan dapat mengajarkan pemeriksaan filter dan pipa kepada karyawan baru."]},{"id":"refill-flow","name":"張り直しと均一な水回り確認","kanten":"決められた水位まできれいな水を張り直して再稼働し、パッド全体が均一に濡れるかを見届けられるか。","levels":["水を張って電源を入れたら立ち去り、パッドに乾いた部分があっても気づかない。","指示があれば確認するが、水位やパッドの濡れ具合の確認に漏れがある。","指示があれば水位まで張り直し、循環とパッドの濡れをひと通り確認できる。","指示がなくても循環開始まで見守り、一部だけ濡れない時は詰まりを疑って報告する。","均一な濡れと冷却効果の関係を理解し、再稼働確認の要点を新人に指導できる。"],"name_en":"Refilling and Checking Even Water Flow","kanten_en":"Can they refill with clean water to the set level, restart the system, and confirm the whole pad gets wet evenly?","levels_en":["Walks away after filling and powering on, and does not notice dry patches on the pad.","With guidance can check, but misses the water level or how wet the pad is.","With guidance can refill to the set level and check circulation and pad wetting through the basic routine.","Independently watches until circulation starts, and when only part stays dry, suspects a clog and reports it.","Understands how even wetting relates to cooling effect, and can teach new staff the key points of restart checks."],"name_vi":"Châm nước lại và kiểm tra nước chảy đều","kanten_vi":"Có châm nước sạch lại đến mực nước quy định, cho chạy lại, và xem toàn bộ tấm làm mát có ướt đều không.","levels_vi":["Châm nước, bật điện xong là bỏ đi, tấm làm mát có chỗ khô cũng không nhận ra.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về kiểm tra mực nước và độ ướt của tấm làm mát.","Nếu được chỉ thị thì châm lại đến mực nước, kiểm tra tuần hoàn và độ ướt của tấm làm mát được cơ bản.","Dù không có chỉ thị vẫn theo dõi đến khi bắt đầu tuần hoàn, khi chỉ một phần không ướt thì nghi bị tắc và báo cáo.","Hiểu quan hệ giữa ướt đều và hiệu quả làm mát, và có thể hướng dẫn người mới các điểm chính khi kiểm tra chạy lại."],"name_id":"Mengisi ulang air dan memeriksa aliran air yang merata","kanten_id":"Apakah mengisi ulang air bersih sampai ketinggian yang ditentukan, menjalankan kembali, dan memastikan seluruh panel pendingin basah merata?","levels_id":["Pergi begitu saja setelah mengisi air dan menyalakan listrik, dan tidak sadar walaupun ada bagian panel yang kering.","Memeriksa jika diperintah, tetapi sering lalai memeriksa ketinggian air dan tingkat basah panel.","Jika diperintah, dapat mengisi ulang sampai ketinggian air dan memeriksa sirkulasi serta basahnya panel secara lengkap.","Tanpa diperintah pun, mengawasi sampai sirkulasi dimulai, dan jika hanya sebagian yang tidak basah mencurigai penyumbatan lalu melapor.","Memahami hubungan basah merata dengan efek pendinginan, dan dapat mengajarkan pokok pemeriksaan saat menjalankan kembali kepada karyawan baru."]},{"id":"record-heat","name":"記録・報告と夏場の自己管理","kanten":"清掃日と気づいた異常を記録・報告し、暑い時期は自分の熱中症にも注意して作業できるか。","levels":["清掃しても記録せず、体調が悪くても無理を続けて報告しない。","指示があれば記録するが、異常の報告や水分補給に漏れがある。","指示があれば清掃日と気づきをひと通り記録・報告できる。","指示がなくても次回がわかる記録を残し、こまめに水分をとって体調の異変はすぐ伝える。","記録が清掃サイクルの維持につながることを理解し、記録と夏場の安全を新人に指導できる。"],"name_en":"Records, Reports, and Self-Care in Summer","kanten_en":"Can they record and report the cleaning date and any abnormalities noticed, and work while also watching out for their own heat stroke in hot weather?","levels_en":["Does not record after cleaning, and keeps pushing on without reporting even when feeling unwell.","With guidance can record, but misses reporting abnormalities or drinking enough water.","With guidance can record and report the cleaning date and findings through the basic routine.","Independently leaves records the next person can follow, drinks water frequently, and immediately reports any change in their own condition.","Understands that records keep the cleaning cycle going, and can teach new staff recording and summer safety."],"name_vi":"Ghi chép, báo cáo và tự chăm sóc bản thân mùa hè","kanten_vi":"Có ghi chép, báo cáo ngày vệ sinh và bất thường nhận thấy, mùa nóng có chú ý cả sốc nhiệt của bản thân khi làm việc không.","levels_vi":["Vệ sinh xong không ghi chép, người mệt vẫn cố làm tiếp mà không báo cáo.","Nếu được chỉ thị thì ghi chép, nhưng còn thiếu sót về báo cáo bất thường và bổ sung nước.","Nếu được chỉ thị thì ghi chép, báo cáo ngày vệ sinh và điều nhận thấy được cơ bản.","Dù không có chỉ thị vẫn để lại ghi chép giúp biết lần sau, uống nước thường xuyên và báo ngay khi cơ thể có dấu hiệu lạ.","Hiểu ghi chép giúp duy trì chu kỳ vệ sinh, và có thể hướng dẫn người mới việc ghi chép và an toàn mùa hè."],"name_id":"Catatan, laporan, dan menjaga diri pada musim panas","kanten_id":"Apakah mencatat dan melaporkan tanggal pembersihan dan kelainan yang disadari, serta pada musim panas bekerja sambil mewaspadai sengatan panas pada diri sendiri?","levels_id":["Tidak mencatat walaupun sudah membersihkan, dan terus memaksakan diri tanpa melapor walaupun badan tidak sehat.","Mencatat jika diperintah, tetapi sering lalai melaporkan kelainan dan minum air yang cukup.","Jika diperintah, dapat mencatat dan melaporkan tanggal pembersihan serta temuan secara lengkap.","Tanpa diperintah pun, meninggalkan catatan yang menjelaskan jadwal berikutnya, sering minum air, dan segera memberi tahu jika kondisi badan berubah.","Memahami bahwa catatan menjaga siklus pembersihan, dan dapat mengajarkan pencatatan dan keselamatan musim panas kepada karyawan baru."]}],"name_en":"Pad Tank Cleaning (Summer)","name_vi":"Vệ sinh bể nước của tấm làm mát (pad tank) — mùa hè","name_id":"Membersihkan tangki air panel pendingin (pad tank) — musim panas","purposeShort_en":"Maintain cooling performance, prevent algae, bacteria, and odor, and extend equipment life","purposeShort_vi":"Duy trì hiệu quả làm mát, phòng rêu tảo, vi khuẩn, mùi hôi và giúp thiết bị bền lâu","purposeShort_id":"Menjaga kemampuan pendinginan, mencegah lumut, bakteri, dan bau busuk, serta membuat peralatan awet"},{"id":"feed-switch","category":"facility","no":"No.20","name":"エサスイッチ","purposeShort":"給餌を安定させ、ムダな飼料を減らし機械トラブルを防ぐ","gyomu":"20","aspects":[{"id":"switch-position","name":"スイッチ位置と異常時の停止","kanten":"自動・手動・切の位置を確認し、ホッパー空・詰まり・異音時はすぐオフにできるか。","levels":["スイッチ位置を確認せず、ホッパー空や詰まり・異音があってもオフにしない。","指示があれば位置を確認するが、異常時の停止対応に漏れがある。","指示があれば自動・手動・切の位置をひと通り確認できる。","指示がなくても位置を確認し、ホッパー空・詰まり・異音時はすぐオフにする。","給餌設備のトラブルを理解し、スイッチ操作と異常時対応を新人に指導できる。"],"name_en":"Switch Position and Stopping on Abnormality","kanten_en":"Can they confirm the auto/manual/off position and switch off immediately when the hopper is empty, clogged, or making abnormal noise?","levels_en":["Does not confirm the switch position and does not switch off even when the hopper is empty, clogged, or making abnormal noise.","With guidance can confirm the position, but misses stopping the machine on abnormality.","With guidance can confirm the auto/manual/off position through the basic routine.","Independently confirms the position and switches off immediately on an empty hopper, clogging, or abnormal noise.","Understands feeding-equipment troubles, and can teach new staff switch operation and abnormality response."],"name_vi":"Vị trí công tắc và dừng khi bất thường","kanten_vi":"Có kiểm tra vị trí tự động / bằng tay / tắt, khi phễu chứa cám rỗng, bị tắc hoặc có tiếng lạ thì tắt ngay không.","levels_vi":["Không kiểm tra vị trí công tắc, phễu rỗng, bị tắc hay có tiếng lạ cũng không tắt.","Nếu được chỉ thị thì kiểm tra vị trí, nhưng còn thiếu sót trong xử lý dừng khi bất thường.","Nếu được chỉ thị thì kiểm tra vị trí tự động / bằng tay / tắt được cơ bản.","Dù không có chỉ thị vẫn kiểm tra vị trí, khi phễu rỗng, bị tắc, có tiếng lạ thì tắt ngay.","Hiểu các trục trặc của thiết bị cho ăn, và có thể hướng dẫn người mới cách thao tác công tắc và xử lý khi bất thường."],"name_id":"Posisi sakelar dan mematikan saat tidak normal","kanten_id":"Apakah memeriksa posisi otomatis / manual / mati, dan segera mematikan saat corong pakan (hopper) kosong, tersumbat, atau berbunyi aneh?","levels_id":["Tidak memeriksa posisi sakelar, dan tidak mematikan walaupun corong pakan kosong, tersumbat, atau berbunyi aneh.","Memeriksa posisi jika diperintah, tetapi sering lalai mematikan saat tidak normal.","Jika diperintah, dapat memeriksa posisi otomatis / manual / mati secara lengkap.","Tanpa diperintah pun, memeriksa posisi, dan segera mematikan saat corong pakan kosong, tersumbat, atau berbunyi aneh.","Memahami gangguan pada peralatan pemberian pakan, dan dapat mengajarkan pengoperasian sakelar dan penanganan saat tidak normal kepada karyawan baru."]},{"id":"label-stock","name":"飼料の種類・残量の事前確認","kanten":"ホッパーの飼料をラベルと照合し、のぞき窓や側面を叩いた音で残量を確かめてから運転できるか。","levels":["ラベルも残量も確認せず運転し、飼料の種類違いや空運転を招く。","指示があれば確認するが、声出し照合や残量の見極めに漏れがある。","指示があればラベル照合と残量確認をひと通りできる。","指示がなくても豚舎名と飼料名を声に出して照合し、残量を確かめてから動かす。","種類違いが消化不良を招くことを理解し、飼料確認の徹底を新人に指導できる。"],"name_en":"Checking Feed Type and Remaining Amount in Advance","kanten_en":"Can they match the feed in the hopper against the label, and check the remaining amount through the sight window or by tapping the side before running?","levels_en":["Runs without checking the label or the remaining amount, causing wrong feed types and dry running.","With guidance can check, but misses reading aloud to match or judging the remaining amount.","With guidance can match the label and check the remaining amount through the basic routine.","Independently reads the barn name and feed name aloud to match them, and checks the remaining amount before running.","Understands that wrong feed types cause digestive upsets, and can teach new staff thorough feed checks."],"name_vi":"Kiểm tra trước loại thức ăn và lượng còn lại","kanten_vi":"Có đối chiếu thức ăn trong phễu với nhãn, kiểm tra lượng còn lại qua cửa sổ quan sát hoặc tiếng gõ vào thành rồi mới cho chạy không.","levels_vi":["Không kiểm tra nhãn lẫn lượng còn lại mà cho chạy, gây nhầm loại thức ăn và chạy không tải.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về đọc to đối chiếu và ước lượng lượng còn lại.","Nếu được chỉ thị thì đối chiếu nhãn và kiểm tra lượng còn lại được cơ bản.","Dù không có chỉ thị vẫn đọc to tên chuồng và tên thức ăn để đối chiếu, kiểm tra lượng còn lại rồi mới cho chạy.","Hiểu nhầm loại thức ăn gây rối loạn tiêu hóa, và có thể hướng dẫn người mới việc kiểm tra thức ăn triệt để."],"name_id":"Memeriksa lebih dulu jenis pakan dan sisa jumlahnya","kanten_id":"Apakah mencocokkan pakan di corong dengan label, dan memastikan sisa jumlahnya lewat jendela pengintai atau bunyi ketukan pada dinding sebelum menjalankan?","levels_id":["Menjalankan tanpa memeriksa label maupun sisa jumlah, sehingga jenis pakan tertukar dan mesin berjalan kosong.","Memeriksa jika diperintah, tetapi sering lalai mencocokkan dengan suara keras dan memperkirakan sisa jumlah.","Jika diperintah, dapat mencocokkan label dan memeriksa sisa jumlah secara lengkap.","Tanpa diperintah pun, membaca keras nama kandang dan nama pakan untuk mencocokkan, dan memastikan sisa jumlah sebelum menjalankan.","Memahami bahwa jenis pakan yang tertukar menyebabkan gangguan pencernaan, dan dapat mengajarkan pemeriksaan pakan yang menyeluruh kepada karyawan baru."]},{"id":"bridging","name":"ブリッジング詰まりの安全対処","kanten":"満杯なのに飼料が落ちない時にブリッジングを疑い、必ずスイッチを切ってから叩く・突くで対処できるか。","levels":["動かしたまま詰まりに手を出し、直らなくても報告しない。","指示があれば対処するが、先に電源を切る手順や報告に漏れがある。","指示があればスイッチを切ってから外から叩く対処をひと通りできる。","指示がなくてもブリッジングを疑って安全に対処し、直らなければ無理せず報告する。","飼料がアーチ状に固まる仕組みを理解し、安全な対処手順を新人に指導できる。"],"name_en":"Safe Handling of Bridging Clogs","kanten_en":"Can they suspect bridging when feed does not drop despite a full hopper, and always switch off before tapping or poking to clear it?","levels_en":["Reaches into the clog with the machine still running, and does not report even when it cannot be fixed.","With guidance can handle it, but misses cutting the power first or reporting.","With guidance can switch off and then tap from the outside through the basic procedure.","Independently suspects bridging, handles it safely, and reports without forcing it when it cannot be fixed.","Understands how feed cakes into an arch, and can teach new staff the safe handling procedure."],"name_vi":"Xử lý an toàn tắc do bridging","kanten_vi":"Khi phễu đầy mà thức ăn không rơi xuống có nghi bridging, nhất định tắt công tắc trước rồi mới gõ, chọc để xử lý không.","levels_vi":["Máy đang chạy vẫn thò tay xử lý chỗ tắc, không sửa được cũng không báo cáo.","Nếu được chỉ thị thì xử lý, nhưng còn thiếu sót về bước ngắt điện trước và báo cáo.","Nếu được chỉ thị thì tắt công tắc rồi gõ từ bên ngoài để xử lý được cơ bản.","Dù không có chỉ thị vẫn nghi bridging và xử lý an toàn, không sửa được thì không cố mà báo cáo.","Hiểu cơ chế thức ăn vón thành vòm, và có thể hướng dẫn người mới quy trình xử lý an toàn."],"name_id":"Penanganan aman sumbatan bridging","kanten_id":"Apakah mencurigai bridging saat pakan tidak jatuh padahal penuh, dan selalu mematikan sakelar lebih dulu sebelum mengetuk atau menusuk untuk mengatasinya?","levels_id":["Menangani sumbatan saat mesin masih berjalan, dan tidak melapor walaupun tidak bisa diperbaiki.","Menangani jika diperintah, tetapi sering lalai mematikan listrik lebih dulu dan melapor.","Jika diperintah, dapat mematikan sakelar lalu mengetuk dari luar untuk mengatasinya secara lengkap.","Tanpa diperintah pun, mencurigai bridging dan menanganinya dengan aman, dan jika tidak berhasil melapor tanpa memaksakan.","Memahami mekanisme pakan menggumpal membentuk lengkungan, dan dapat mengajarkan prosedur penanganan yang aman kepada karyawan baru."]},{"id":"trough-watch","name":"トラフ量と食べ具合の見回り","kanten":"底がうっすら見える目安でトラフ量を確かめ、残餌や切り替え中の下痢に気づいて報告できるか。","levels":["給餌後の見回りをせず、山盛り・空のトラフや残餌を放置する。","指示があれば見回るが、量の目安や糞の状態の確認に漏れがある。","指示があれば1房ずつのぞき、トラフ量と残餌をひと通り確認できる。","指示がなくても給餌後に見回り、残餌や下痢の増加に気づいてすぐ報告する。","残餌が体調不良のサインと理解し、トラフ量の目安と観察を新人に指導できる。"],"name_en":"Checking Trough Amounts and How Well Pigs Eat","kanten_en":"Can they check trough amounts by the guide of the bottom being faintly visible, and notice and report leftover feed and diarrhea during feed changes?","levels_en":["Skips rounds after feeding, leaving heaped or empty troughs and leftover feed.","With guidance can make rounds, but misses the amount guide or checking manure condition.","With guidance can look into each pen and check trough amounts and leftover feed through the basic routine.","Independently makes rounds after feeding and immediately reports leftover feed and increases in diarrhea when noticed.","Understands that leftover feed is a sign of poor condition, and can teach new staff the trough-amount guide and observation."],"name_vi":"Đi kiểm tra lượng thức ăn trong máng và mức ăn","kanten_vi":"Có kiểm tra lượng trong máng theo mức chuẩn「nhìn thấy mờ mờ đáy máng」, nhận ra và báo cáo thức ăn thừa, tiêu chảy trong lúc đổi cám không.","levels_vi":["Không đi kiểm tra sau khi cho ăn, bỏ mặc máng đầy ụ, máng rỗng và thức ăn thừa.","Nếu được chỉ thị thì đi kiểm tra, nhưng còn thiếu sót về mức chuẩn lượng thức ăn và kiểm tra tình trạng phân.","Nếu được chỉ thị thì nhìn từng ô chuồng, kiểm tra lượng trong máng và thức ăn thừa được cơ bản.","Dù không có chỉ thị vẫn đi kiểm tra sau khi cho ăn, nhận ra thức ăn thừa, tiêu chảy tăng và báo cáo ngay.","Hiểu thức ăn thừa là dấu hiệu sức khỏe kém, và có thể hướng dẫn người mới mức chuẩn lượng trong máng và cách quan sát."],"name_id":"Memeriksa keliling jumlah pakan di tempat pakan dan nafsu makan","kanten_id":"Apakah memeriksa jumlah pakan di tempat pakan dengan patokan dasarnya terlihat samar, serta menyadari dan melaporkan pakan sisa dan diare selama pergantian pakan?","levels_id":["Tidak memeriksa keliling setelah pemberian pakan, membiarkan tempat pakan menggunung atau kosong serta pakan sisa.","Memeriksa keliling jika diperintah, tetapi sering lalai soal patokan jumlah dan memeriksa kondisi kotoran.","Jika diperintah, dapat melihat satu per satu petak kandang serta memeriksa jumlah di tempat pakan dan pakan sisa secara lengkap.","Tanpa diperintah pun, memeriksa keliling setelah pemberian pakan, dan segera melapor begitu menyadari pakan sisa atau diare yang bertambah.","Memahami bahwa pakan sisa adalah tanda kondisi kurang sehat, dan dapat mengajarkan patokan jumlah di tempat pakan dan pengamatan kepada karyawan baru."]},{"id":"timer-record","name":"タイマー変更後の動作確認と記録","kanten":"設定変更は決められた人が行い、タイマー変更後は動作確認し、切り替え日を記録できるか。","levels":["権限のない者が設定を変え、変更後の動作確認もせず切り替え日も記録しない。","指示があれば確認するが、動作確認や記録に漏れがある。","指示があればタイマー変更後の動作をひと通り確認できる。","指示がなくても変更後に実際に1回動かして確認し、切り替え開始日と内容を記録する。","設定変更と給餌事故の関係を理解し、動作確認と記録の徹底を新人に指導できる。"],"name_en":"Operation Check and Recording After Timer Changes","kanten_en":"Can they leave setting changes to designated staff, verify operation after timer changes, and record the changeover date?","levels_en":["Unauthorized staff change the settings, with no operation check afterward and no record of the changeover date.","With guidance can check, but misses the operation check or the record.","With guidance can verify operation after a timer change through the basic routine.","Independently runs the system once after changes to verify, and records the changeover start date and details.","Understands how setting changes relate to feeding accidents, and can teach new staff thorough operation checks and recording."],"name_vi":"Kiểm tra hoạt động sau khi đổi hẹn giờ và ghi chép","kanten_vi":"Việc đổi cài đặt có do người được quy định làm, sau khi đổi hẹn giờ có kiểm tra hoạt động và ghi lại ngày chuyển đổi không.","levels_vi":["Người không có quyền đổi cài đặt, sau khi đổi không kiểm tra hoạt động, cũng không ghi ngày chuyển đổi.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về kiểm tra hoạt động và ghi chép.","Nếu được chỉ thị thì kiểm tra hoạt động sau khi đổi hẹn giờ được cơ bản.","Dù không có chỉ thị vẫn cho chạy thử 1 lần sau khi đổi để kiểm tra, và ghi lại ngày bắt đầu chuyển đổi cùng nội dung.","Hiểu quan hệ giữa đổi cài đặt và sự cố cho ăn, và có thể hướng dẫn người mới việc kiểm tra hoạt động và ghi chép triệt để."],"name_id":"Memeriksa kerja setelah mengubah timer dan mencatatnya","kanten_id":"Apakah perubahan pengaturan hanya dilakukan orang yang ditunjuk, kerja mesin diperiksa setelah timer diubah, dan tanggal penggantian dicatat?","levels_id":["Orang tanpa wewenang mengubah pengaturan, tidak memeriksa kerja mesin setelah diubah, dan tidak mencatat tanggal penggantian.","Memeriksa jika diperintah, tetapi sering lalai memeriksa kerja mesin dan mencatat.","Jika diperintah, dapat memeriksa kerja mesin setelah timer diubah secara lengkap.","Tanpa diperintah pun, menjalankan mesin satu kali setelah perubahan untuk memastikan, dan mencatat tanggal mulai penggantian beserta isinya.","Memahami hubungan perubahan pengaturan dengan kecelakaan pemberian pakan, dan dapat mengajarkan pemeriksaan kerja mesin dan pencatatan kepada karyawan baru."]}],"name_en":"Feed Switch","name_vi":"Công tắc cấp cám (vận hành cho ăn tự động)","name_id":"Sakelar pakan (pengoperasian pemberian pakan otomatis)","purposeShort_en":"Keep feeding stable, reduce feed waste, and prevent mechanical trouble","purposeShort_vi":"Giữ việc cho ăn ổn định, giảm lãng phí thức ăn và phòng trục trặc máy","purposeShort_id":"Menstabilkan pemberian pakan, mengurangi pakan terbuang, dan mencegah gangguan mesin"},{"id":"water-check","category":"facility","no":"","name":"飲水器の点検","purposeShort":"肥育豚が毎日きちんと水を飲めるよう、飲水器の高さ・流量・詰まり・凍結を点検し、断水時は仮設給水で対応する","purposeShort_en":"Inspect drinker height, flow, clogs, and freezing so finishing pigs can always drink, and cover outages with temporary water","purposeShort_vi":"Kiểm tra chiều cao, lưu lượng, tắc và đóng băng của núm uống để lợn thịt uống nước đủ mỗi ngày, và cấp nước tạm khi mất nước","purposeShort_id":"Memeriksa tinggi, debit, sumbatan, dan beku pada tempat minum agar babi penggemukan bisa minum setiap hari, dan memberi air sementara saat air terhenti","gyomu":"","name_en":"Drinker Inspection","name_vi":"Kiểm tra núm uống nước","name_id":"Pemeriksaan Tempat Minum","aspects":[{"id":"flow-measure","name":"流量の確認（全ニップル）","kanten":"ニップル式の飲水器で、下にカップを置いて15秒など一定時間受けた量を1分に換算し、全ニップルの流量が肥育豚の目安に合うか確かめられるか。","levels":["流量を測らないまま、飲水器の点検を済ませたことにする。","指示があれば流量を測るが、一部のニップルだけで済ませたり、換算を間違えたりして、結果は他者まかせ。","指示があればカップで15秒など一定時間受けて1分に換算し、肥育豚の目安1.0〜1.5L/分に合うか全ニップルで確認できる。","指示がなくても豚房に複数あるニップルを全部測り、目安の1.0〜1.5L/分から外れるものや出っぱなしのものは上長に報告する。","流量が足りないニップルがあると水の取り合いになることを理解し、一定時間で受ける測り方と換算のしかたを新人に指導できる。"],"name_en":"Checking flow rate (every nipple)","name_vi":"Kiểm tra lưu lượng (tất cả núm uống)","name_id":"Pemeriksaan debit air (semua nipple)","kanten_en":"For nipple drinkers, can they place a cup underneath, catch water for a set time such as 15 seconds, convert it to 1 minute, and confirm that every nipple matches the guideline for finishing pigs?","kanten_vi":"Với núm uống kiểu nipple, có đặt cốc bên dưới, hứng nước trong thời gian cố định như 15 giây rồi quy ra 1 phút, và xác nhận tất cả núm uống đạt mức tham khảo cho lợn thịt không.","kanten_id":"Pada tempat minum tipe nipple, apakah menaruh cangkir di bawahnya, menampung air selama waktu tertentu seperti 15 detik, mengonversinya ke 1 menit, dan memastikan semua nipple sesuai acuan babi penggemukan.","levels_en":["Does not measure flow and treats the drinker check as done.","With guidance, measures flow, but covers only some nipples or miscalculates the conversion, and leaves the result to others.","With guidance, catches water in a cup for a set time such as 15 seconds, converts it to 1 minute, and can check all nipples against the finishing-pig guideline of 1.0-1.5 L/min.","Independently measures every nipple in a pen that has several, and reports to the supervisor any that fall outside the guideline of 1.0-1.5 L/min or run constantly.","Understands that a nipple with low flow leads to pigs competing for water, and can teach new staff how to catch water for a set time and convert it."],"levels_vi":["Không đo lưu lượng mà coi như đã kiểm tra xong núm uống.","Nếu có chỉ dẫn thì đo lưu lượng, nhưng chỉ đo một số núm uống hoặc quy đổi sai, kết quả phó mặc cho người khác.","Nếu có chỉ dẫn thì hứng nước bằng cốc trong thời gian cố định như 15 giây, quy ra 1 phút, và xác nhận tất cả núm uống đạt mức tham khảo cho lợn thịt là 1,0–1,5 L/phút được.","Không cần chỉ dẫn cũng đo hết các núm uống trong ô chuồng có nhiều núm, núm nào nằm ngoài mức tham khảo 1,0–1,5 L/phút hoặc chảy liên tục thì báo cấp trên.","Hiểu rằng núm uống có lưu lượng yếu sẽ khiến lợn tranh nhau nước, và có thể hướng dẫn người mới cách hứng nước trong thời gian cố định và cách quy đổi."],"levels_id":["Tidak mengukur debit, lalu menganggap pemeriksaan tempat minum sudah selesai.","Jika ada instruksi, mengukur debit, tetapi hanya sebagian nipple atau salah mengonversi, dan hasilnya diserahkan ke orang lain.","Jika ada instruksi, bisa menampung air dengan cangkir selama waktu tertentu seperti 15 detik, mengonversinya ke 1 menit, dan memastikan semua nipple sesuai acuan babi penggemukan 1,0–1,5 L/menit.","Tanpa instruksi pun, mengukur semua nipple di petak kandang yang punya beberapa nipple, dan melaporkan ke atasan yang berada di luar acuan 1,0–1,5 L/menit atau terus mengalir.","Memahami bahwa nipple dengan debit kecil membuat babi berebut air, dan bisa mengajari karyawan baru cara menampung air selama waktu tertentu dan mengonversinya."]},{"id":"height-fit","name":"取り付け高さの確認","kanten":"ニップルの高さが豚の大きさ（肥育前期か後期か）に合っているか見て、高すぎ・低すぎを直したり報告したりできるか。","levels":["ニップルの高さを見ず、豚が飲みにくそうでも、そのままにして気にしない。","指示があれば高さを見るが、前期と後期の違いを意識せず、ずれていても直すのは他者まかせ。","指示があれば床から肥育前期45〜55cm、後期60〜75cmの目安と照らし、高すぎ・低すぎのニップルを見つけられる。","指示がなくても豚の成長で合わなくなった高さに気づき、直すか上長に報告して、直した後も豚が飲めるか見る。","高すぎると小さい豚が飲めず、低すぎると水のロスが増えることを理解し、豚の肩より少し上という高さの見方を新人に指導できる。"],"name_en":"Checking mounting height","name_vi":"Kiểm tra chiều cao lắp đặt","name_id":"Pemeriksaan tinggi pemasangan","kanten_en":"Can they see whether the nipple height suits the pigs' size (early or late finishing), and fix or report heights that are too high or too low?","kanten_vi":"Có xem chiều cao núm uống có hợp với cỡ lợn (giai đoạn đầu hay cuối vỗ béo) không, và chỉnh hoặc báo cáo khi quá cao hay quá thấp không.","kanten_id":"Apakah memeriksa tinggi nipple sesuai ukuran babi (penggemukan awal atau akhir), serta memperbaiki atau melaporkan yang terlalu tinggi atau terlalu rendah.","levels_en":["Does not look at nipple height and ignores it even when pigs seem to have trouble drinking.","With guidance, looks at the height, but does not consider early versus late finishing and leaves fixing a mismatch to others.","With guidance, compares with the guideline of 45-55 cm from the floor for early finishing and 60-75 cm for late finishing, and can find nipples that are too high or too low.","Independently notices heights that no longer fit as pigs grow, fixes them or reports to the supervisor, and checks that pigs can drink afterward.","Understands that too high means small pigs cannot drink and too low means more water waste, and can teach new staff to look for a position a little above the pig's shoulder."],"levels_vi":["Không xem chiều cao núm uống, dù lợn có vẻ khó uống cũng bỏ mặc.","Nếu có chỉ dẫn thì xem chiều cao, nhưng không để ý khác biệt giữa giai đoạn đầu và cuối vỗ béo, lệch cũng phó mặc việc chỉnh cho người khác.","Nếu có chỉ dẫn thì đối chiếu mức tham khảo 45–55 cm tính từ sàn cho giai đoạn đầu vỗ béo và 60–75 cm cho giai đoạn cuối vỗ béo, tìm được núm uống quá cao hoặc quá thấp.","Không cần chỉ dẫn cũng nhận ra chiều cao không còn hợp khi lợn lớn lên, tự chỉnh hoặc báo cấp trên, và xem lợn có uống được sau khi chỉnh không.","Hiểu quá cao thì lợn nhỏ không uống được, quá thấp thì hao nước nhiều hơn, và có thể hướng dẫn người mới nhìn vị trí cao hơn vai lợn một chút."],"levels_id":["Tidak memeriksa tinggi nipple dan membiarkannya meskipun babi tampak sulit minum.","Jika ada instruksi, memeriksa tinggi, tetapi tidak membedakan penggemukan awal dan akhir, dan jika tingginya tidak sesuai, perbaikannya diserahkan ke orang lain.","Jika ada instruksi, bisa membandingkan dengan acuan 45–55 cm dari lantai untuk awal penggemukan dan 60–75 cm untuk akhir penggemukan, serta menemukan nipple yang terlalu tinggi atau rendah.","Tanpa instruksi pun, menyadari tinggi yang tidak cocok lagi karena babi tumbuh, memperbaikinya atau melapor ke atasan, dan memeriksa babi bisa minum setelahnya.","Memahami bahwa terlalu tinggi membuat babi kecil tidak bisa minum dan terlalu rendah menambah air terbuang, dan bisa mengajari karyawan baru melihat posisi sedikit di atas bahu babi."]},{"id":"clog-leak","name":"詰まり・出っぱなしの切り分け","kanten":"水が出ない・出が悪い・出っぱなし・水が汚いときに、原因を順に切り分け、元栓・ニップル・フィルター・配管に合った対処と、漏水時の元栓閉止と報告ができるか。","levels":["水が出ないニップルや出っぱなしの水を見ても、原因を調べず放置し、床の濡れも気にしない。","指示があれば不具合を見に行くが、原因を切り分けず、対処の判断は他者まかせ。","指示があれば元栓を確かめ、ニップルの分解清掃か交換、フィルター清掃、配管の洗い流しから原因に合う対処を選べる。","指示がなくても床の濡れすぎなどの原因を切り分けて対処し、配管の漏水は元栓を閉めたら直ちに上長へ報告し、断水する豚房の仮設給水を始める。","症状と原因と対処の対応を理解し、元栓から順に切り分ける手順を新人に指導できる。"],"name_en":"Isolating clogs and constantly running nipples","name_vi":"Phân biệt nguyên nhân tắc và chảy liên tục","name_id":"Menelusuri penyebab sumbatan dan air terus mengalir","kanten_en":"When water does not come out, flows poorly, runs constantly, or is dirty, can they work through the cause in order, respond appropriately to the main valve, nipple, filter, or piping, and close the main valve and report for a leak?","kanten_vi":"Khi nước không ra, ra yếu, chảy liên tục hoặc bẩn, có lần lượt tìm nguyên nhân, xử lý phù hợp với van tổng, núm uống, bộ lọc, đường ống, và đóng van tổng rồi báo cáo khi rò rỉ không.","kanten_id":"Apakah saat air tidak keluar, keluarnya buruk, terus mengalir, atau kotor, dapat menelusuri penyebab secara berurutan, menangani sesuai keran utama, nipple, filter, atau pipa, dan menutup keran utama lalu melapor saat bocor.","levels_en":["Sees nipples with no water or constant running water but leaves them without checking the cause, and ignores wet floors.","With guidance, goes to look at the fault, but does not isolate the cause and leaves the decision on action to others.","With guidance, checks the main valve and can choose the right action: disassemble and clean or replace the nipple, clean the filter, or flush the piping.","Independently isolates the cause of problems such as overly wet floors and deals with it; for a piping leak, reports to the supervisor at once after closing the main valve and starts temporary watering for pens that lose water.","Understands how symptoms, causes, and actions match, and can teach new staff the step-by-step check starting from the main valve."],"levels_vi":["Thấy núm uống không ra nước hoặc nước chảy liên tục cũng không tìm nguyên nhân mà bỏ mặc, sàn ướt cũng không để ý.","Nếu có chỉ dẫn thì đi xem chỗ hỏng, nhưng không tách nguyên nhân, việc quyết định xử lý phó mặc cho người khác.","Nếu có chỉ dẫn thì kiểm tra van tổng, chọn được cách xử lý đúng nguyên nhân: tháo vệ sinh hoặc thay núm uống, vệ sinh bộ lọc, xả rửa đường ống.","Không cần chỉ dẫn cũng tìm nguyên nhân khi sàn ướt quá mức và xử lý; khi đường ống rò rỉ thì đóng van tổng xong báo cấp trên ngay, và bắt đầu cấp nước tạm cho ô chuồng bị mất nước.","Hiểu mối liên hệ giữa triệu chứng, nguyên nhân và cách xử lý, và có thể hướng dẫn người mới trình tự kiểm tra từ van tổng."],"levels_id":["Melihat nipple tanpa air atau air yang terus mengalir tetapi dibiarkan tanpa mencari penyebab, dan tidak peduli lantai basah.","Jika ada instruksi, pergi melihat masalahnya, tetapi tidak menelusuri penyebab, dan keputusan penanganan diserahkan ke orang lain.","Jika ada instruksi, bisa memeriksa keran utama dan memilih penanganan yang sesuai: bongkar dan bersihkan atau ganti nipple, bersihkan filter, atau bilas pipa.","Tanpa instruksi pun, menelusuri penyebab seperti lantai yang terlalu basah lalu menanganinya; saat pipa bocor, setelah menutup keran utama segera melapor ke atasan dan mulai memberi air sementara ke petak yang airnya terhenti.","Memahami hubungan gejala, penyebab, dan penanganan, dan bisa mengajari karyawan baru urutan pemeriksaan mulai dari keran utama."]},{"id":"freeze-outage","name":"凍結・断水時の対応","kanten":"凍結に気づいたらぬるま湯で解凍し（熱湯は使わない）、凍結以外も含む断水ならバケツやホースで仮設給水して報告できるか（季節外は口頭で最初の行動を聞く）。","levels":["凍結や断水に気づかず、水が出ない豚房があっても確かめに行かない。","指示があれば水の出を見るが、解凍や仮設給水の手順が抜けたり後回しになったりして、報告も遅れる。","指示があれば凍結ならぬるま湯で解凍し、断水なら原因を問わずバケツやホースで仮設給水を始められる。","指示がなくても冬は毎朝、凍結していないか全箇所を確かめ、水が出ない豚房へすぐ仮設給水し、農場長に報告して再発防止を相談する。","脱水が命に関わることを理解し、熱湯を使わない理由と、修理までの仮設給水の手順を新人に指導できる。"],"name_en":"Response to freezing and water outage","name_vi":"Xử lý khi đóng băng và mất nước","name_id":"Penanganan saat beku dan air terhenti","kanten_en":"Can they thaw frozen parts with lukewarm water, never boiling water, give temporary water by bucket or hose when any outage stops the supply (frozen or not) until repair, and report (out of season, ask orally what they would do first)?","kanten_vi":"Có rã đông bằng nước ấm chứ không dùng nước sôi khi bị đóng băng, cấp nước tạm bằng xô hoặc vòi khi mất nước (dù có đóng băng hay không) cho đến khi sửa xong, rồi báo cáo không (ngoài mùa thì hỏi miệng hành động đầu tiên sẽ làm).","kanten_id":"Apakah mencairkan bagian beku dengan air hangat, bukan air mendidih, memberi air sementara dengan ember atau selang saat air terhenti (beku atau bukan) sampai diperbaiki, lalu melapor (di luar musim, tanyakan secara lisan tindakan pertama yang dilakukan).","levels_en":["Does not notice freezing or outage, and does not go to check even when a pen has no water.","With guidance, looks at water flow, but skips or delays the thawing and temporary watering steps, and reports late.","With guidance, thaws frozen parts with lukewarm water, and can start temporary watering with buckets or hoses in any outage, frozen or not.","Independently checks every point for freezing each winter morning, gives temporary water at once to pens with none, reports to the farm manager, and discusses preventing a recurrence.","Understands that dehydration can threaten life, and can teach new staff why not to use boiling water and how to give temporary water until repair."],"levels_vi":["Không nhận ra đóng băng hoặc mất nước, ô chuồng không có nước cũng không đi kiểm tra.","Nếu có chỉ dẫn thì xem nước ra, nhưng thiếu hoặc để chậm các bước rã đông và cấp nước tạm, và báo cáo cũng chậm.","Nếu có chỉ dẫn thì rã đông bằng nước ấm khi đóng băng, và bắt đầu cấp nước tạm bằng xô hoặc vòi khi mất nước do bất kỳ nguyên nhân nào được.","Không cần chỉ dẫn cũng kiểm tra đóng băng ở tất cả vị trí mỗi sáng mùa đông, cấp nước tạm ngay cho ô chuồng không có nước, báo trưởng trại và bàn cách ngăn tái diễn.","Hiểu mất nước có thể nguy hiểm đến tính mạng, và có thể hướng dẫn người mới lý do không dùng nước sôi và cách cấp nước tạm cho đến khi sửa xong."],"levels_id":["Tidak menyadari beku atau air terhenti, dan tidak memeriksa meskipun ada petak tanpa air.","Jika ada instruksi, melihat keluarnya air, tetapi melewatkan atau menunda langkah pencairan dan pemberian air sementara, dan terlambat melapor.","Jika ada instruksi, bisa mencairkan bagian beku dengan air hangat, dan memulai pemberian air sementara dengan ember atau selang pada setiap kasus air terhenti, beku atau bukan.","Tanpa instruksi pun, memeriksa beku di semua titik setiap pagi di musim dingin, segera memberi air sementara ke petak tanpa air, melapor ke kepala peternakan, dan membahas pencegahan terulang.","Memahami bahwa dehidrasi bisa membahayakan nyawa, dan bisa mengajari karyawan baru alasan tidak memakai air mendidih dan cara memberi air sementara sampai perbaikan."]},{"id":"season-record","name":"点検結果の記録と予備品","kanten":"今の季節に水まわりで何を見るかを答え、今日の点検結果を用紙にどう記録するかと、交換用の予備ニップルがあるかを説明できるか。","levels":["今の季節に水まわりで見る点を考えず、今日の点検結果も記録に残さず、予備のニップルがあるかも確かめない。","指示があれば今の季節に見る点を話して点検結果を記録するが、記録の項目が抜け、予備のニップルの確認は他者まかせ。","指示があれば今の季節に見る点（夏は水温・貯水タンク・配管の断熱、冬は保温材）を答え、今日の点検結果を用紙に記録して、予備のニップルの置き場所を言える。","指示がなくても今の季節に見る点で水まわりを点検し、結果を用紙に記録して、予備のニップルが足りなければ上長に報告する。","季節で水まわりに見る点が変わる理由を理解し、点検結果の記録のしかたと予備のニップルの置き場所を新人に指導できる。"],"name_en":"Recording check results and spare parts","name_vi":"Ghi chép kết quả kiểm tra và phụ tùng dự phòng","name_id":"Pencatatan hasil pemeriksaan dan suku cadang","kanten_en":"Can they say what to check around the water supply in the current season, how today's check results are recorded on a sheet, and whether spare nipples for replacement are on hand?","kanten_vi":"Có nói được mùa hiện tại cần xem gì ở hệ thống nước uống, kết quả kiểm tra hôm nay được ghi vào phiếu thế nào, và có sẵn núm uống dự phòng để thay không.","kanten_id":"Apakah dapat menyebutkan apa yang diperiksa pada sistem air minum di musim saat ini, bagaimana hasil pemeriksaan hari ini dicatat di lembar, dan apakah ada nipple cadangan untuk penggantian?","levels_en":["Does not think about what to check around the water supply in the current season, does not record today's check results, and does not confirm that spare nipples are on hand.","With guidance names what to check this season and records the results, but leaves out items, and leaves the check on spare nipples to others.","With guidance can say what to check this season (summer: water temperature, storage tank, pipe insulation; winter: insulation material), record today's results on a sheet, and say where the spare nipples are kept.","Independently checks the water supply for what matters this season, records the results on a sheet, and reports to the supervisor if spare nipples are short.","Understands why what to check around the water supply changes with the season, and can teach new staff how to record check results and where spare nipples are kept."],"levels_vi":["Không nghĩ đến việc mùa hiện tại cần xem gì ở hệ thống nước uống, không ghi lại kết quả kiểm tra hôm nay, và cũng không xác nhận có núm uống dự phòng hay không.","Nếu có chỉ dẫn thì nói được mùa này cần xem gì và ghi lại kết quả, nhưng còn thiếu mục, và phó mặc việc kiểm tra núm uống dự phòng cho người khác.","Nếu có chỉ dẫn thì trả lời được mùa này cần xem gì (mùa hè: nhiệt độ nước, bồn chứa, lớp cách nhiệt đường ống; mùa đông: vật liệu bảo ôn), ghi kết quả kiểm tra hôm nay vào phiếu, và nói được chỗ để núm uống dự phòng.","Không cần chỉ dẫn, vẫn kiểm tra hệ thống nước uống theo các điểm cần xem của mùa này, ghi kết quả vào phiếu, và báo cấp trên nếu núm uống dự phòng không đủ.","Hiểu vì sao điểm cần xem ở hệ thống nước uống thay đổi theo mùa, và có thể hướng dẫn người mới cách ghi kết quả kiểm tra và chỗ để núm uống dự phòng."],"levels_id":["Tidak memikirkan apa yang diperiksa pada sistem air minum di musim saat ini, tidak mencatat hasil pemeriksaan hari ini, dan tidak memastikan ada tidaknya nipple cadangan.","Jika ada instruksi, menyebutkan apa yang diperiksa musim ini dan mencatat hasilnya, tetapi ada item terlewat, dan pemeriksaan nipple cadangan diserahkan ke orang lain.","Jika ada instruksi, bisa menjawab apa yang diperiksa musim ini (musim panas: suhu air, tangki penampung, isolasi pipa; musim dingin: bahan isolasi), mencatat hasil pemeriksaan hari ini di lembar, dan menyebutkan tempat nipple cadangan.","Tanpa instruksi pun, memeriksa sistem air minum sesuai hal yang perlu dilihat musim ini, mencatat hasilnya di lembar, dan melapor ke atasan jika nipple cadangan kurang.","Memahami mengapa hal yang diperiksa pada sistem air minum berubah menurut musim, dan bisa mengajari karyawan baru cara mencatat hasil pemeriksaan dan tempat nipple cadangan."]}]},{"id":"vent-temp","category":"facility","no":"","name":"換気・温度管理（肥育）","purposeShort":"肥育豚が快適に過ごせる温度と換気を保ち、暑さ・寒さ・有害ガスから守る","purposeShort_en":"Keep temperature and ventilation comfortable for finishing pigs and protect them from heat, cold and harmful gas","purposeShort_vi":"Giữ nhiệt độ và thông gió thoải mái cho lợn thịt, bảo vệ lợn khỏi nóng, lạnh và khí độc","purposeShort_id":"Menjaga suhu dan ventilasi yang nyaman bagi babi penggemukan dan melindunginya dari panas, dingin, dan gas berbahaya","gyomu":"","name_en":"Ventilation and Temperature Control (Finishing)","name_vi":"Quản lý thông gió và nhiệt độ (lợn thịt)","name_id":"Pengelolaan ventilasi dan suhu (penggemukan)","aspects":[{"id":"read-temp","name":"温度の読み方","kanten":"温度計を豚の高さに置いて朝・午後・夕方に読み、最高最低の差や計器の故障にも気づけるか。","levels":["温度計の位置も確かめず、舎内の温度を読まないまま過ごし、壊れた計器の値も疑わずに使う。","指示があれば温度を読むが、天井近くなど豚の高さでない値を使ったり、読む時間帯が抜けたりして他者まかせ。","指示があれば豚の高さ（床上30〜50cm）の温度計を朝・午後・夕方に読み、最高最低温度計の差も確認できる。","指示がなくても豚の高さの温度計を朝・午後・夕方に読み、最高最低温度計で冷え込みや昼夜差の大きい日・計器の異常に気づけば上長に報告する。","豚の高さで測る理由と計器の故障が管理を誤らせることを理解し、温度の読み方を新人に指導できる。"],"name_en":"Reading the Temperature","name_vi":"Đọc nhiệt độ","name_id":"Membaca suhu","kanten_en":"Does the person place the thermometer at pig height, read it in the morning, afternoon and evening, and notice the high-low gap or a faulty gauge?","kanten_vi":"Có đặt nhiệt kế ở độ cao của lợn, đọc vào buổi sáng, chiều và tối, và nhận ra chênh lệch cao thấp hoặc nhiệt kế hỏng không.","kanten_id":"Apakah menaruh termometer setinggi babi, membacanya pagi, siang, dan sore, serta menyadari selisih termometer maksimum-minimum atau alat yang rusak?","levels_en":["Does not check where the thermometer is or read the house temperature, and uses the value of a broken gauge without doubt.","With guidance reads the temperature, but uses a value from near the ceiling instead of pig height or skips reading times, leaving it to others.","With guidance can read a thermometer at pig height (30-50 cm above the floor) in the morning, afternoon and evening, and check the high-low thermometer gap.","Independently reads the pig-height thermometer in the morning, afternoon and evening, and reports to the supervisor any cold snap, large day-night gap or gauge fault seen on the high-low thermometer.","Understands why temperature is measured at pig height and how a faulty gauge misleads management, and can teach new staff how to read temperature."],"levels_vi":["Không xem vị trí nhiệt kế, không đọc nhiệt độ trong chuồng, và dùng số của nhiệt kế hỏng mà không nghi ngờ.","Nếu có chỉ dẫn thì đọc nhiệt độ, nhưng dùng số đo gần trần chứ không phải ở độ cao của lợn, hoặc bỏ sót giờ đọc và phó mặc cho người khác.","Nếu có chỉ dẫn thì đọc nhiệt kế ở độ cao của lợn (cách sàn 30–50 cm) vào buổi sáng, chiều và tối, và kiểm tra chênh lệch trên nhiệt kế tối đa–tối thiểu.","Không cần chỉ dẫn vẫn đọc nhiệt kế ở độ cao của lợn vào buổi sáng, chiều và tối, nếu thấy qua nhiệt kế tối đa–tối thiểu ngày lạnh đột ngột, chênh lệch ngày đêm lớn hoặc nhiệt kế bất thường thì báo cấp trên.","Hiểu vì sao đo ở độ cao của lợn và nhiệt kế hỏng làm quản lý sai, và có thể hướng dẫn người mới cách đọc nhiệt độ."],"levels_id":["Tidak memeriksa posisi termometer dan tidak membaca suhu kandang, serta memakai angka alat yang rusak tanpa ragu.","Jika ada instruksi, membaca suhu, tetapi memakai angka dekat langit-langit, bukan setinggi babi, atau melewatkan jam baca dan menyerahkannya kepada orang lain.","Jika ada instruksi, dapat membaca termometer setinggi babi (30–50 cm dari lantai) pada pagi, siang, dan sore, serta memeriksa selisih termometer maksimum-minimum.","Tanpa instruksi pun membaca termometer setinggi babi pada pagi, siang, dan sore, dan jika termometer maksimum-minimum menunjukkan hari yang sangat dingin, selisih siang-malam besar, atau alat tidak normal, melapor kepada atasan.","Memahami alasan suhu diukur setinggi babi dan bahwa alat rusak menyesatkan pengelolaan, serta bisa mengajari karyawan baru cara membaca suhu."]},{"id":"pig-signs","name":"豚の行動で読む暑さ寒さ","kanten":"数字だけに頼らず、豚の呼吸・姿勢・集まり方や舎内の臭いと空気感から暑さ寒さの異常に気づけるか。","levels":["豚の様子も舎内の空気感も見ず、口を開けて呼吸する豚や一か所に固まる豚がいても気づかない。","指示があれば豚の様子を見るが、口呼吸や特定の場所への集中を見落とし、気づいても他者まかせにする。","指示があれば口を開けて呼吸する豚や横たわって動かない豚は暑さ、一か所に固まる豚は寒さや温度ムラの可能性と判断できる。","指示がなくても入った瞬間の臭いと空気感を確かめ、口呼吸や横たわって動かない豚は暑熱の緊急としてすぐ上長に報告し、一か所に固まる豚からは温度ムラや隙間風を疑って調整につなげる。","暑熱が命に関わること、固まりは温度ムラのサインであることを理解し、豚の見方を新人に指導できる。"],"name_en":"Reading Heat and Cold from Pig Behavior","name_vi":"Đọc nóng lạnh qua hành vi lợn","name_id":"Membaca panas dingin dari perilaku babi","kanten_en":"Beyond the numbers, can the person spot heat or cold problems from the pigs' breathing, posture, clustering, and the smell and feel of the air in the house?","kanten_vi":"Không chỉ dựa vào số đo, có nhận ra bất thường nóng lạnh qua nhịp thở, tư thế, cách tụ lại của lợn và mùi, cảm giác không khí trong chuồng không.","kanten_id":"Apakah tidak hanya bergantung pada angka, tetapi menyadari kelainan panas dan dingin dari napas, posisi, cara berkumpul babi, serta bau dan suasana udara kandang?","levels_en":["Does not look at the pigs or the feel of the air, and does not notice pigs breathing with open mouths or huddled in one spot.","With guidance looks at the pigs, but misses open-mouth breathing or crowding in one spot, and leaves it to others even when noticed.","With guidance can judge that pigs breathing with open mouths or lying and not moving suggest heat, and pigs huddled in one spot suggest cold or uneven temperature.","Independently checks the smell and feel of the air on entering, reports open-mouth breathing or pigs lying and not moving to the supervisor at once as a heat emergency, and suspects uneven temperature or drafts from huddled pigs and links it to adjustments.","Understands that heat stress can be life-threatening and that huddling signals uneven temperature, and can teach new staff how to read pigs."],"levels_vi":["Không nhìn lợn cũng không để ý không khí trong chuồng, lợn thở bằng miệng hoặc tụ lại một chỗ cũng không nhận ra.","Nếu có chỉ dẫn thì quan sát lợn, nhưng bỏ sót lợn thở bằng miệng hoặc tụ lại một chỗ, có nhận ra cũng phó mặc cho người khác.","Nếu có chỉ dẫn thì đánh giá được lợn thở bằng miệng hoặc nằm bất động có thể do nóng, còn lợn tụ lại một chỗ có thể do lạnh hoặc nhiệt độ không đều.","Không cần chỉ dẫn vẫn kiểm tra mùi và cảm giác không khí khi vào chuồng, báo cấp trên ngay lợn thở bằng miệng hoặc nằm bất động như tình huống khẩn cấp do nóng, và từ lợn tụ lại một chỗ mà nghi nhiệt độ không đều hoặc gió lùa rồi chỉnh cho phù hợp.","Hiểu sốc nhiệt có thể nguy hiểm đến tính mạng, lợn tụ lại là dấu hiệu nhiệt độ không đều, và có thể hướng dẫn người mới cách quan sát lợn."],"levels_id":["Tidak memperhatikan babi maupun suasana udara, dan tidak sadar walau ada babi bernapas lewat mulut atau menggerombol di satu tempat.","Jika ada instruksi, mengamati babi, tetapi melewatkan napas lewat mulut atau babi menggerombol di satu tempat, dan walau sadar menyerahkannya kepada orang lain.","Jika ada instruksi, dapat menilai bahwa babi yang bernapas lewat mulut atau berbaring tak bergerak kemungkinan kepanasan, dan babi yang menggerombol di satu tempat kemungkinan kedinginan atau suhu tidak merata.","Tanpa instruksi pun memeriksa bau dan suasana udara saat masuk, segera melapor kepada atasan jika ada babi bernapas lewat mulut atau berbaring tak bergerak sebagai darurat panas, dan mencurigai suhu tidak merata atau angin yang masuk lewat celah dari babi yang menggerombol, lalu menyesuaikannya.","Memahami bahwa stres panas bisa mengancam nyawa dan bahwa menggerombol tanda suhu tidak merata, serta bisa mengajari karyawan baru cara mengamati babi."]},{"id":"manual-adjust","name":"カーテン・インレットの調整","kanten":"カーテンやインレットを段階的に動かし、冷風が豚に直接当たらないよう隙間や破れも確認できるか。","levels":["カーテンやインレットを天気や時間帯に関係なく放置するか、一気に全開にして豚に冷風が当たる。","指示があれば開け閉めするが、一気に動かしたり隙間や破れの確認が抜けたりして、他者まかせになる。","指示があれば朝晩や天気に合わせてカーテンやインレットを段階的に動かし、隙間・破れ・裾の密着を確認できる。","指示がなくても朝晩や天気、豚への風当たりに応じて段階的に調整し、直せない破れや隙間があれば上長に報告する。","開度が小さいと風は速く遠くへ届き大きいと遅く近くに落ちることを理解し、調整を新人に指導できる。"],"name_en":"Adjusting Curtains and Inlets","name_vi":"Chỉnh rèm và cửa gió vào","name_id":"Mengatur tirai dan inlet","kanten_en":"Can the person move curtains or inlets in steps, check gaps and tears, and keep cold air from blowing directly on the pigs?","kanten_vi":"Có điều chỉnh rèm và cửa gió vào từng bước, kiểm tra khe hở, chỗ rách và tránh để gió lạnh thổi thẳng vào lợn không.","kanten_id":"Apakah menggerakkan tirai dan inlet secara bertahap, memeriksa celah dan sobekan, serta mencegah angin dingin langsung mengenai babi?","levels_en":["Leaves curtains and inlets alone regardless of weather or time, or opens them fully at once so cold air hits the pigs.","With guidance opens and closes them, but moves them all at once or skips checking for gaps and tears, leaving it to others.","With guidance can move curtains and inlets in steps to suit morning, evening and weather, and check gaps, tears and whether the curtain hem sits tight.","Independently adjusts in steps to suit morning, evening, weather and how the air hits the pigs, and reports to the supervisor any tear or gap that cannot be fixed.","Understands that a small opening sends air fast and far while a large one drops it slowly and near, and can teach new staff the adjustment."],"levels_vi":["Mặc kệ rèm và cửa gió vào bất kể thời tiết hay giờ giấc, hoặc mở hết một lúc khiến gió lạnh thổi vào lợn.","Nếu có chỉ dẫn thì mở đóng, nhưng mở hoặc đóng hết một lúc, hoặc bỏ sót kiểm tra khe hở, chỗ rách và phó mặc cho người khác.","Nếu có chỉ dẫn thì điều chỉnh rèm và cửa gió vào từng bước tùy sáng tối và thời tiết, kiểm tra khe hở, chỗ rách và phần chân rèm có sát chặt không.","Không cần chỉ dẫn vẫn điều chỉnh từng bước theo sáng tối, thời tiết và gió thổi vào lợn, gặp chỗ rách hoặc khe hở không tự sửa được thì báo cấp trên.","Hiểu độ mở nhỏ thì gió nhanh và đi xa, độ mở lớn thì gió chậm và rơi gần, và có thể hướng dẫn người mới cách điều chỉnh."],"levels_id":["Membiarkan tirai dan inlet tanpa memperhatikan cuaca atau waktu, atau membukanya penuh sekaligus sehingga angin dingin mengenai babi.","Jika ada instruksi, membuka dan menutup, tetapi menggerakkannya sekaligus atau melewatkan pemeriksaan celah dan sobekan, dan menyerahkannya kepada orang lain.","Jika ada instruksi, dapat menggerakkan tirai dan inlet bertahap sesuai pagi, sore, dan cuaca, serta memeriksa celah, sobekan, dan apakah ujung bawah tirai menempel rapat.","Tanpa instruksi pun menyesuaikan bertahap sesuai pagi, sore, cuaca, dan angin yang mengenai babi, dan melapor kepada atasan jika ada sobekan atau celah yang tidak bisa diperbaiki sendiri.","Memahami bahwa bukaan kecil membuat angin cepat dan jauh sedangkan bukaan besar membuat angin lambat dan jatuh dekat, serta bisa mengajari karyawan baru cara mengaturnya."]},{"id":"never-stop","name":"換気を止めない判断","kanten":"寒くても最低限の換気を止めず、目のチクチクなど臭いや体感から換気不足に気づき、換気と除糞でガス対策もできるか。","levels":["寒いからとカーテンを閉め切って換気を止め、臭いや目の刺激があっても何もしない。","指示があれば換気を保つが、寒さを気にして止めたくなり、臭いや目の刺激を見逃して他者まかせになる。","指示があれば寒い日も最低限の換気を残し、目がチクチクする時は換気を増やす必要があると判断できる。","指示がなくても換気を止めず、強い臭いや目の痛みがあれば換気を最大にして除糞を優先し、上長に報告する。","換気を止めるとアンモニアが溜まり呼吸器の病気が増えること、ピット作業は換気を最大にしてひとりでは入らないことを理解し、新人に指導できる。"],"name_en":"Never Stopping Ventilation","name_vi":"Không ngừng thông gió","name_id":"Keputusan tidak menghentikan ventilasi","kanten_en":"Even when cold, can the person keep minimum ventilation, notice poor ventilation from smell or stinging eyes, and take gas countermeasures with ventilation and manure removal?","kanten_vi":"Dù lạnh có giữ thông gió tối thiểu, nhận ra thiếu thông gió qua mùi hoặc cay mắt, và xử lý khí độc bằng thông gió và dọn phân không.","kanten_id":"Apakah tetap menjaga ventilasi minimum walau dingin, menyadari ventilasi kurang dari bau atau mata perih, dan menangani gas berbahaya dengan ventilasi dan pembersihan kotoran?","levels_en":["Closes the curtains fully because it is cold and stops ventilation, and does nothing even with a strong smell or stinging eyes.","With guidance keeps ventilation, but is tempted to stop it because of the cold, misses the smell or eye irritation, and leaves it to others.","With guidance keeps minimum ventilation even on cold days, and can judge that ventilation must be increased when the eyes sting.","Independently does not stop ventilation, and when there is a strong smell or painful eyes raises ventilation to maximum, gives priority to removing manure, and reports to the supervisor.","Understands that stopping ventilation lets ammonia build up and respiratory disease increase, and that pit work needs maximum ventilation and no one enters alone, and can teach new staff."],"levels_vi":["Vì lạnh mà đóng kín rèm, ngừng thông gió, có mùi nồng hoặc cay mắt cũng không làm gì.","Nếu có chỉ dẫn thì giữ thông gió, nhưng vì lo lạnh muốn ngừng, bỏ qua mùi hoặc cay mắt và phó mặc cho người khác.","Nếu có chỉ dẫn thì ngày lạnh vẫn giữ thông gió tối thiểu, và biết phải tăng thông gió khi thấy cay mắt.","Không cần chỉ dẫn vẫn không ngừng thông gió, khi mùi nồng hoặc đau mắt thì tăng thông gió tối đa, ưu tiên dọn phân và báo cấp trên.","Hiểu ngừng thông gió thì amoniac tích tụ và bệnh hô hấp tăng, khi làm việc ở hố phân phải thông gió tối đa và không vào một mình, và có thể hướng dẫn người mới."],"levels_id":["Menutup tirai penuh karena dingin sehingga ventilasi berhenti, dan tidak berbuat apa-apa walau bau menyengat atau mata perih.","Jika ada instruksi menjaga ventilasi, tetapi tergoda menghentikannya karena dingin, melewatkan bau atau iritasi mata, dan menyerahkannya kepada orang lain.","Jika ada instruksi, tetap menyisakan ventilasi minimum pada hari dingin, dan dapat menilai bahwa ventilasi perlu ditambah saat mata perih.","Tanpa instruksi pun tidak menghentikan ventilasi, dan saat bau menyengat atau mata sakit menaikkan ventilasi ke maksimum, mengutamakan pembersihan kotoran, dan melapor kepada atasan.","Memahami bahwa jika ventilasi dihentikan amonia menumpuk dan penyakit pernapasan meningkat, serta kerja di lubang kotoran (pit) perlu ventilasi maksimum dan tidak boleh masuk sendirian, serta bisa mengajari karyawan baru."]},{"id":"fan-failure-first","name":"ファン故障時の初動","kanten":"ファンの異常に気づき、ブレーカー・ベルト・羽根の異物を順に確認し、直せなければ報告して代替換気を確保できるか。","levels":["ファンが止まっても風や音の変化に気づかず、周辺の豚が口を開けて呼吸していても放置する。","指示があればファンを見るが、ブレーカーやベルトの確認が抜け、代替換気や報告を他者まかせにする。","指示があればブレーカーを確認し、ベルトと羽根の異物を順に見て、直せなければ上長に報告できる。","指示がなくても風や音、臭い、豚の呼吸で異常に気づき、ブレーカー・ベルト・異物を確認して上長に報告し、カーテンや扉を開けて代替換気を確保し、周辺の豚をこまめに見る。","ファンが一台でも止まれば周辺の豚に影響が出ることを理解し、故障時の初動を新人に指導できる。"],"name_en":"First Response to Fan Failure","name_vi":"Xử lý ban đầu khi quạt hỏng","name_id":"Tindakan awal saat kipas rusak","kanten_en":"Can the person notice a fan problem, check the breaker, belt and foreign objects on the blades in order, and report and secure substitute ventilation if it cannot be fixed?","kanten_vi":"Có nhận ra quạt bất thường, kiểm tra lần lượt cầu dao, dây curoa, dị vật trên cánh quạt, và nếu không sửa được thì báo cáo, bảo đảm thông gió thay thế không.","kanten_id":"Apakah menyadari kelainan kipas, memeriksa berurutan pemutus listrik, sabuk, dan benda asing pada bilah, lalu melapor dan menyediakan ventilasi pengganti jika tidak bisa diperbaiki?","levels_en":["Does not notice changes in airflow or sound when a fan stops, and leaves it even when nearby pigs breathe with open mouths.","With guidance looks at the fan, but skips checking the breaker or belt, and leaves substitute ventilation and reporting to others.","With guidance can check the breaker, then check the belt and foreign objects on the blades in order, and report to the supervisor if it cannot be fixed.","Independently notices a problem from airflow, sound, smell or pig breathing, checks the breaker, belt and foreign objects, reports to the supervisor, opens curtains and doors for substitute ventilation, and checks the pigs nearby often.","Understands that even one stopped fan affects nearby pigs, and can teach new staff the first response to a failure."],"levels_vi":["Quạt dừng mà không nhận ra thay đổi về gió hay tiếng động, lợn xung quanh há miệng thở cũng bỏ mặc.","Nếu có chỉ dẫn thì xem quạt, nhưng bỏ sót kiểm tra cầu dao và dây curoa, phó mặc việc thông gió thay thế và báo cáo cho người khác.","Nếu có chỉ dẫn thì kiểm tra cầu dao, rồi kiểm tra lần lượt dây curoa và dị vật trên cánh quạt, nếu không sửa được thì báo cấp trên.","Không cần chỉ dẫn vẫn nhận ra bất thường qua gió, tiếng động, mùi, nhịp thở của lợn, kiểm tra cầu dao, dây curoa, dị vật, báo cấp trên, mở rèm và cửa để bảo đảm thông gió thay thế, và thường xuyên xem lợn xung quanh.","Hiểu chỉ một quạt dừng cũng ảnh hưởng lợn xung quanh, và có thể hướng dẫn người mới cách xử lý ban đầu khi hỏng."],"levels_id":["Tidak sadar perubahan angin atau suara saat kipas berhenti, dan membiarkan walau babi di sekitarnya bernapas lewat mulut.","Jika ada instruksi, memeriksa kipas, tetapi melewatkan pemeriksaan pemutus listrik dan sabuk, dan menyerahkan ventilasi pengganti serta pelaporan kepada orang lain.","Jika ada instruksi, dapat memeriksa pemutus listrik, lalu memeriksa sabuk dan benda asing pada bilah secara berurutan, dan melapor kepada atasan jika tidak bisa diperbaiki.","Tanpa instruksi pun menyadari kelainan dari angin, suara, bau, atau napas babi, memeriksa pemutus listrik, sabuk, dan benda asing, melapor kepada atasan, membuka tirai dan pintu untuk ventilasi pengganti, serta sering memeriksa babi di sekitarnya.","Memahami bahwa satu kipas berhenti pun memengaruhi babi di sekitarnya, serta bisa mengajari karyawan baru tindakan awal saat rusak."]}]},{"id":"vent-controller","category":"facility","no":"","name":"換気設定確認（ウインドレス）","purposeShort":"自動換気の設定値を読み取って記録し、実際の動きと照合して、決められた人の変更と停電時の対応を守る","purposeShort_en":"Read and record automatic ventilation settings, compare them with actual operation, and follow the change rule and power-failure response","purposeShort_vi":"Đọc và ghi lại cài đặt thông gió tự động, đối chiếu với thực tế, tuân thủ quy định thay đổi và cách xử lý khi mất điện","purposeShort_id":"Membaca dan mencatat pengaturan ventilasi otomatis, mencocokkannya dengan kondisi nyata, menaati aturan hanya orang yang ditunjuk boleh mengubah, dan penanganan listrik padam","gyomu":"","name_en":"Ventilation Settings Check (Windowless)","name_vi":"Kiểm tra cài đặt thông gió (chuồng kín)","name_id":"Pemeriksaan pengaturan ventilasi (kandang tertutup)","aspects":[{"id":"read-record","name":"設定値の読み取りと記録","kanten":"コントローラーの設定温度・換気ステージ・最低換気量・タイマー・ヒーター設定を、変更ボタンを押さず画面で読み取り、用紙に正確に記録できるか（読み取りの正確さを見る）。","levels":["コントローラーの設定を見ず記録もしないため、今どんな設定になっているか分からない。","指示があれば画面を見るが、項目の読み落としや転記ミスが残り、記録は他者まかせ。","指示があれば設定温度・換気ステージ・最低換気量・タイマー・ヒーター設定を画面から読み取り、用紙に転記できる。","指示がなくても全項目を漏れなく読み、変更ボタンを押さずに画面の撮影か用紙で記録に残す。","設定が換気の出方を決めることを理解し、読み取りと記録の手順を新人に指導できる。"],"name_en":"Reading and Recording the Settings","name_vi":"Đọc và ghi lại các giá trị cài đặt","name_id":"Membaca dan mencatat nilai pengaturan","kanten_en":"Can they read the set temperature, ventilation stages, minimum ventilation, timers, and heater setting on the controller screen without pressing change buttons, and record them accurately on a sheet (judged on reading accuracy)?","kanten_vi":"Có đọc trên màn hình bộ điều khiển nhiệt độ cài đặt, các giai đoạn thông gió, lượng thông gió tối thiểu, bộ hẹn giờ, cài đặt máy sưởi mà không bấm nút thay đổi, và ghi chính xác vào phiếu không (xét độ chính xác khi đọc).","kanten_id":"Apakah bisa membaca di layar pengendali suhu pengaturan, tahap ventilasi, ventilasi minimum, timer, dan pengaturan pemanas tanpa menekan tombol ubah, lalu mencatatnya dengan akurat di lembar (dinilai dari ketepatan membaca)?","levels_en":["Does not look at the controller settings or record them, so does not know what the current settings are.","With guidance looks at the screen, but misses items or makes transcription errors, and leaves the recording to others.","With guidance can read the set temperature, ventilation stage, minimum ventilation, timers, and heater setting from the screen and copy them onto a sheet.","Independently reads all items without omission, and keeps a record by photographing the screen or on a sheet, without pressing any change button.","Understands that the settings decide how the ventilation works, and can teach new staff how to read and record them."],"levels_vi":["Không xem cài đặt của bộ điều khiển và cũng không ghi lại, nên không biết hiện đang cài đặt thế nào.","Nếu có chỉ dẫn thì xem màn hình, nhưng còn bỏ sót mục hoặc chép sai, và phó mặc việc ghi chép cho người khác.","Nếu có chỉ dẫn thì đọc được nhiệt độ cài đặt, giai đoạn thông gió, lượng thông gió tối thiểu, bộ hẹn giờ, cài đặt máy sưởi từ màn hình và chép vào phiếu.","Không cần chỉ dẫn, vẫn đọc đủ tất cả các mục, không bấm nút thay đổi, và lưu lại bằng cách chụp màn hình hoặc ghi vào phiếu.","Hiểu rằng cài đặt quyết định cách thông gió hoạt động, và có thể hướng dẫn người mới cách đọc và ghi lại."],"levels_id":["Tidak melihat pengaturan pengendali dan tidak mencatatnya, sehingga tidak tahu pengaturan saat ini.","Jika ada instruksi melihat layar, tetapi ada item terlewat atau salah salin, dan pencatatan diserahkan ke orang lain.","Jika ada instruksi, bisa membaca suhu pengaturan, tahap ventilasi, ventilasi minimum, timer, dan pengaturan pemanas dari layar lalu menyalinnya ke lembar.","Tanpa instruksi pun, membaca semua item tanpa terlewat, dan menyimpan catatan dengan memotret layar atau di lembar, tanpa menekan tombol ubah.","Memahami bahwa pengaturan menentukan cara kerja ventilasi, dan bisa mengajari karyawan baru cara membaca dan mencatatnya."]},{"id":"verify-actual","name":"設定と実際の照合","kanten":"画面の設定と、今のステージで動くはずのファン・シャッター・インレット・温度計の状態を見比べ、ずれを見つけられるか。","levels":["画面の表示どおりに動いていると思い込み、ファンやインレットの実際の動きを見に行かない。","指示があればファンを見に行くが、シャッターやインレットの開き具合の確認が抜け、ずれは他者まかせ。","指示があれば回転部に触れず、今のステージで回るはずのファンが回りシャッターが開き、止まるファンのシャッターは閉じているか、インレットの開きが設定と合うかを確認できる。","指示がなくても設定と実際を見比べ、センサーが豚の高さと豚のいる場所にあるかも確かめ、ずれを上長に報告する。","表示と実際がずれることがある理由を理解し、照合のポイントを新人に指導できる。"],"name_en":"Checking Settings against Actual Operation","name_vi":"Đối chiếu cài đặt với thực tế","name_id":"Pencocokan pengaturan dengan kondisi nyata","kanten_en":"Can they compare the settings on the screen with the state of the fans that should be running at the current stage, the shutters, inlets, and thermometer, and find any gaps?","kanten_vi":"Có so sánh cài đặt trên màn hình với tình trạng thực tế của quạt đáng lẽ chạy ở giai đoạn hiện tại, cửa chớp, cửa gió vào và nhiệt kế để phát hiện chỗ lệch không.","kanten_id":"Apakah bisa membandingkan pengaturan di layar dengan kondisi nyata kipas yang seharusnya berjalan pada tahap saat ini, shutter, inlet, dan termometer, serta menemukan selisihnya?","levels_en":["Assumes things run as displayed on the screen and does not go to see how the fans and inlets actually move.","With guidance goes to see the fans, but skips checking how far the shutters and inlets open, and leaves gaps to others.","With guidance, without touching rotating parts, can check that the fans that should run at the current stage are running with shutters open, that stopped fans' shutters are closed, and that the inlet opening matches the setting.","Independently compares settings with reality, also checks that the sensor is at pig height and where pigs are, and reports any gap to the supervisor.","Understands why the display and reality can differ, and can teach new staff the points to check."],"levels_vi":["Cứ tin là chạy đúng như màn hình hiển thị và không đi xem quạt, cửa gió vào thực tế hoạt động ra sao.","Nếu có chỉ dẫn thì đi xem quạt, nhưng bỏ sót việc kiểm tra độ mở của cửa chớp và cửa gió vào, và phó mặc chỗ lệch cho người khác.","Nếu có chỉ dẫn thì không chạm vào bộ phận đang quay, kiểm tra được quạt đáng lẽ chạy ở giai đoạn hiện tại có đang quay và cửa chớp mở không, cửa chớp của quạt đang dừng có đóng không, và độ mở cửa gió vào có khớp cài đặt không.","Không cần chỉ dẫn, vẫn so sánh cài đặt với thực tế, kiểm tra cả cảm biến có ở độ cao của lợn và nơi lợn ở không, và báo cấp trên chỗ lệch.","Hiểu vì sao hiển thị và thực tế có thể lệch nhau, và có thể hướng dẫn người mới các điểm cần kiểm tra."],"levels_id":["Mengira semuanya berjalan seperti tampilan layar dan tidak melihat gerakan nyata kipas dan inlet.","Jika ada instruksi pergi melihat kipas, tetapi pemeriksaan bukaan shutter dan inlet terlewat, dan selisih diserahkan ke orang lain.","Jika ada instruksi, tanpa menyentuh bagian yang berputar, bisa memeriksa apakah kipas yang seharusnya berjalan pada tahap saat ini berputar dengan shutter terbuka, shutter kipas yang berhenti tertutup, dan bukaan inlet sesuai pengaturan.","Tanpa instruksi pun, membandingkan pengaturan dengan kondisi nyata, juga memeriksa sensor ada di ketinggian babi dan tempat babi berada, dan melapor selisihnya ke atasan.","Memahami mengapa tampilan dan kondisi nyata bisa berbeda, dan bisa mengajari karyawan baru poin pemeriksaannya."]},{"id":"change-rule","name":"変更の権限と手順","kanten":"設定の変更は決められた人だけが行うと理解し、変更が必要なときの上長への相談と、変更後の記録・動作確認への立ち会いを守れるか。","levels":["寒い暑いと感じて自分の判断でコントローラーの設定を触り、記録も報告もしない。","設定を勝手には変えないが、指示があれば上長に相談する程度で、変更後の記録と動作確認が抜け、他者まかせ。","指示があれば、決められた人が変更した後に設定を記録し、動作の確認ができる。","指示がなくても変更が必要と気づいたら上長に相談し、決められた人が変更した後の記録と動作確認に立ち会う。最低換気量を含め、設定を自分では変えない。","換気不足で有害ガスや湿気がたまり、呼吸器の病気につながる理由を理解し、変更の手順を新人に指導できる。"],"name_en":"Authority and Procedure for Changes","name_vi":"Quyền và quy trình thay đổi cài đặt","name_id":"Wewenang dan prosedur perubahan","kanten_en":"Do they understand that only the designated person changes the settings, and follow consulting the supervisor when a change is needed and being present for the recording and operation check afterwards?","kanten_vi":"Có hiểu rằng chỉ người được chỉ định mới thay đổi cài đặt, và tuân thủ việc trao đổi với cấp trên khi cần đổi, cũng như có mặt khi ghi chép và kiểm tra hoạt động sau khi đổi không.","kanten_id":"Apakah memahami bahwa perubahan pengaturan hanya dilakukan orang yang ditunjuk, serta menaati konsultasi ke atasan saat perubahan diperlukan dan mendampingi pencatatan serta pemeriksaan kerja setelahnya?","levels_en":["Touches the controller settings on their own judgment because it feels cold or hot, and neither records nor reports it.","Does not change settings on their own, but only consults the supervisor when told to, and skips recording and checking operation after a change, leaving it to others.","With guidance can record the settings and check the operation after the designated person has made a change.","Independently consults the supervisor when noticing a change is needed, and is present for the recording and operation check after the designated person changes it. Does not change any setting, including the minimum ventilation, on their own.","Understands why poor ventilation lets harmful gas and humidity build up and leads to respiratory disease, and can teach new staff the change procedure."],"levels_vi":["Thấy lạnh hoặc nóng là tự ý chỉnh cài đặt bộ điều khiển, không ghi chép cũng không báo cáo.","Không tự ý đổi cài đặt, nhưng chỉ trao đổi với cấp trên khi được bảo, và bỏ sót ghi chép cùng kiểm tra hoạt động sau khi đổi, phó mặc cho người khác.","Nếu có chỉ dẫn thì ghi lại cài đặt và kiểm tra hoạt động sau khi người được chỉ định đã đổi.","Không cần chỉ dẫn, khi nhận ra cần đổi thì trao đổi với cấp trên, và có mặt ghi chép, kiểm tra hoạt động sau khi người được chỉ định đổi. Không tự thay đổi cài đặt nào, kể cả thông gió tối thiểu.","Hiểu vì sao thiếu thông gió làm khí độc và hơi ẩm tích tụ, dẫn đến bệnh hô hấp, và có thể hướng dẫn người mới quy trình thay đổi."],"levels_id":["Merasa dingin atau panas lalu mengubah pengaturan pengendali dengan penilaian sendiri, tanpa mencatat dan melapor.","Tidak mengubah pengaturan sendiri, tetapi hanya berkonsultasi ke atasan jika diminta, dan melewatkan pencatatan serta pemeriksaan kerja setelah perubahan, diserahkan ke orang lain.","Jika ada instruksi, bisa mencatat pengaturan dan memeriksa kerja setelah orang yang ditunjuk mengubahnya.","Tanpa instruksi pun, berkonsultasi ke atasan saat menyadari perlu perubahan, dan mendampingi pencatatan serta pemeriksaan kerja setelah orang yang ditunjuk mengubahnya. Tidak mengubah pengaturan apa pun sendiri, termasuk ventilasi minimum.","Memahami mengapa ventilasi kurang membuat gas berbahaya dan kelembapan menumpuk serta menyebabkan penyakit pernapasan, dan bisa mengajari karyawan baru prosedur perubahan."]},{"id":"weekly-review","name":"毎週の見直し依頼","kanten":"頭数・体重・季節の変化で設定が合わなくなると理解し、豚の様子から、合っているかを判断して毎週上長に見直しを依頼できるか。","levels":["一度決めた設定は変わらないと考え、見直しもせず気づいたことも報告しない。","指示があれば設定が合っているかを確かめるが、頭数や季節の変化を考えず、結果の判断は他者まかせ。","指示があれば毎週、豚の様子から、設定が頭数・体重・季節に合っているかを上長に伝えられる。","指示がなくても毎週、豚の様子を確かめ、頭数・体重・季節に合わない点があれば見直しを上長に依頼する。","自動換気でも設定の見直しが要る理由を理解し、見直しの視点を新人に指導できる。"],"name_en":"Weekly Review Request","name_vi":"Đề nghị xem xét lại hằng tuần","name_id":"Permintaan tinjauan mingguan","kanten_en":"Do they understand that settings stop fitting as headcount, weight, and season change, and judge from the pigs' condition whether they fit, asking the supervisor for a review every week?","kanten_vi":"Có hiểu rằng cài đặt sẽ không còn phù hợp khi số lượng lợn, cân nặng và mùa thay đổi, và hằng tuần dựa trên tình trạng lợn để đánh giá cài đặt có phù hợp không rồi đề nghị cấp trên xem lại không.","kanten_id":"Apakah memahami bahwa pengaturan menjadi tidak cocok karena perubahan jumlah babi, bobot, dan musim, serta setiap minggu menilai kecocokannya dari kondisi babi lalu meminta atasan meninjau?","levels_en":["Thinks settings, once decided, never change, so does not review them and does not report what they notice.","With guidance checks whether the settings fit, but does not consider changes in headcount or season, and leaves the judgment to others.","With guidance can tell the supervisor every week, from the pigs' condition, whether the settings fit the headcount, weight, and season.","Independently checks the pigs' condition every week, and asks the supervisor to review the settings if anything does not fit the headcount, weight, or season.","Understands why settings need review even with automatic ventilation, and can teach new staff what to look at."],"levels_vi":["Nghĩ rằng cài đặt đã định thì không đổi, nên không xem lại và cũng không báo điều mình nhận thấy.","Nếu có chỉ dẫn thì kiểm tra cài đặt có phù hợp không, nhưng không nghĩ đến thay đổi về số lượng lợn hay mùa, và phó mặc việc đánh giá cho người khác.","Nếu có chỉ dẫn thì hằng tuần dựa trên tình trạng lợn, báo cấp trên cài đặt có phù hợp với số lượng lợn, cân nặng, mùa không.","Không cần chỉ dẫn, hằng tuần vẫn kiểm tra tình trạng lợn, và nếu có điểm không phù hợp với số lượng lợn, cân nặng, mùa thì đề nghị cấp trên xem lại cài đặt.","Hiểu vì sao thông gió tự động vẫn cần xem lại cài đặt, và có thể hướng dẫn người mới các điểm cần xem."],"levels_id":["Mengira pengaturan yang sudah ditentukan tidak berubah, sehingga tidak meninjau dan tidak melaporkan hal yang disadari.","Jika ada instruksi, memeriksa kesesuaian pengaturan, tetapi tidak memikirkan perubahan jumlah babi atau musim, dan penilaian diserahkan ke orang lain.","Jika ada instruksi, setiap minggu bisa menyampaikan ke atasan, dari kondisi babi, apakah pengaturan sesuai jumlah babi, bobot, dan musim.","Tanpa instruksi pun, setiap minggu memeriksa kondisi babi, dan meminta atasan meninjau pengaturan jika ada yang tidak sesuai jumlah babi, bobot, atau musim.","Memahami mengapa pengaturan perlu ditinjau meski ventilasi otomatis, dan bisa mengajari karyawan baru hal yang perlu dilihat."]},{"id":"power-backup","name":"停電時の対応","kanten":"停電のとき、全体か一部かとブレーカーの確認・報告・発電機での換気ファンと給水ポンプ優先・発電機が使えないときの農場の手順に定めた代替換気ができるか。","levels":["停電が起きても対応せず、換気ファンが止まったままでも放置する。","指示があればブレーカーを見るが、報告や発電機の手順が抜け、換気の確保は他者まかせ。","指示があれば全体停電か一部か、ブレーカーが落ちているかを確認して農場長に報告し、発電機の起動手順と換気ファン・給水ポンプ優先を説明できる。","指示がなくても停電時にすぐ報告し、農場で起動訓練を受けた人は発電機を起動する。使えないときは農場の手順に定めた代替換気を行い、豚の呼吸を確かめる。","夏の停電は換気が最優先で、短い時間で豚が危険になる理由を理解し、発電機の毎月の試運転・燃料確認を含め新人に指導できる。"],"name_en":"Response to Power Failure","name_vi":"Xử lý khi mất điện","name_id":"Penanganan saat listrik padam","kanten_en":"At a power failure, can they check whether it is farm-wide or partial and whether the breaker has tripped, report, run the generator with ventilation fans and water pump first, and use the alternative ventilation set in the farm's procedure if the generator cannot be used?","kanten_vi":"Khi mất điện, có kiểm tra mất toàn trại hay một phần và cầu dao có bị ngắt không, báo cáo, chạy máy phát điện ưu tiên quạt thông gió và bơm nước, và dùng cách thông gió thay thế theo quy trình của trại khi không dùng được máy phát không.","kanten_id":"Saat listrik padam, apakah bisa memeriksa apakah padam seluruh peternakan atau sebagian dan apakah pemutus sirkuit turun, melapor, menyalakan generator dengan mendahulukan kipas ventilasi dan pompa air, serta memakai ventilasi pengganti sesuai prosedur peternakan bila generator tidak bisa dipakai?","levels_en":["Does not respond to a power failure and leaves it even when the ventilation fans stay stopped.","With guidance checks the breaker, but skips reporting and the generator steps, and leaves securing ventilation to others.","With guidance can check whether the outage is farm-wide or partial and whether the breaker has tripped, report to the farm manager, and explain the generator start procedure and putting ventilation fans and the water pump first.","Independently reports at once at a power failure, and those trained in starting the generator on the farm start it. If it cannot be used, uses the alternative ventilation set in the farm's procedure and checks the pigs' breathing.","Understands why ventilation comes first in a summer outage and pigs become endangered in a short time, and can teach new staff, including the monthly generator test run and fuel check."],"levels_vi":["Mất điện cũng không xử lý, quạt thông gió dừng vẫn bỏ mặc.","Nếu có chỉ dẫn thì xem cầu dao, nhưng bỏ sót báo cáo và các bước với máy phát điện, và phó mặc việc đảm bảo thông gió cho người khác.","Nếu có chỉ dẫn thì kiểm tra mất điện toàn trại hay một phần và cầu dao có bị ngắt không, báo cáo trưởng trại, và giải thích được quy trình khởi động máy phát điện cùng việc ưu tiên quạt thông gió và bơm nước.","Không cần chỉ dẫn, khi mất điện vẫn báo cáo ngay, và người đã được huấn luyện khởi động máy phát điện tại trại thì khởi động máy. Nếu không dùng được thì thông gió thay thế theo quy trình của trại và kiểm tra nhịp thở của lợn.","Hiểu vì sao khi mất điện mùa hè thì thông gió là ưu tiên hàng đầu và lợn nguy hiểm chỉ trong thời gian ngắn, và có thể hướng dẫn người mới, kể cả việc chạy thử máy phát điện hằng tháng và kiểm tra nhiên liệu."],"levels_id":["Tidak menanggapi listrik padam dan membiarkan meski kipas ventilasi tetap mati.","Jika ada instruksi memeriksa pemutus sirkuit, tetapi pelaporan dan langkah generator terlewat, dan penjaminan ventilasi diserahkan ke orang lain.","Jika ada instruksi, bisa memeriksa apakah padam seluruh peternakan atau sebagian dan apakah pemutus sirkuit turun, melapor ke kepala peternakan, serta menjelaskan prosedur menyalakan generator dan mendahulukan kipas ventilasi dan pompa air.","Tanpa instruksi pun, saat listrik padam langsung melapor, dan orang yang sudah dilatih menyalakan generator di peternakan menyalakannya. Jika tidak bisa dipakai, melakukan ventilasi pengganti sesuai prosedur peternakan dan memeriksa napas babi.","Memahami mengapa ventilasi diutamakan saat listrik padam di musim panas dan babi cepat berbahaya dalam waktu singkat, dan bisa mengajari karyawan baru, termasuk uji coba generator tiap bulan dan pemeriksaan bahan bakar."]}]},{"id":"density-grouping","category":"facility","no":"","name":"密度管理・群分け（肥育）","purposeShort":"面積と頭数を見て過密を防ぎ、必要なら群を分けて、尾かじりやけんかを減らす","gyomu":"","aspects":[{"id":"area-calc","name":"面積から上限頭数を出す","kanten":"豚の体重帯ごとの必要面積（0.5〜1.0 m2/頭）で豚房の面積を割り、入れてよい上限頭数を出せるか（例：15 m2・100 kgなら0.85で割って約17頭）。","levels":["豚房の面積も体重帯ごとの必要面積も確かめず、頭数が増えても入れられるだけ入れてしまう。","指示があれば豚房の面積を確かめて割るが、体重帯の選び方を誤ったり、結果の確認を他者まかせにしたりする。","指示があれば、自分の担当の豚房の面積を体重帯の必要面積で割り、入れてよい上限頭数を出せる。","指示がなくても体重測定や出荷選別の機会に体重帯を確かめ直して上限頭数を出し直し、移動後も移動元・移動先が収まるかを見て、超えそうなら上長に伝える。","体重が増えると必要面積も増えることを理解し、面積と頭数から上限を出す方法を新人に指導できる。"],"name_en":"Calculating the Head Limit from Area","name_vi":"Tính số đầu con tối đa theo diện tích","name_id":"Menghitung batas jumlah ekor dari luas","kanten_en":"Can they divide a pen's area by the required area per pig for the weight band (0.5-1.0 m2 per pig) to work out how many pigs it may hold (example: 15 m2 and 100 kg: divide by 0.85, about 17 pigs)?","kanten_vi":"Có chia diện tích ô chuồng cho diện tích cần thiết mỗi lợn theo nhóm cân nặng (0,5–1,0 m2/con) để tính số con tối đa được nuôi không (ví dụ: 15 m2, 100 kg thì chia cho 0,85, khoảng 17 con).","kanten_id":"Apakah dapat membagi luas petak kandang dengan luas yang dibutuhkan per ekor menurut kelompok bobot (0,5–1,0 m2/ekor) untuk menghitung jumlah ekor maksimum (contoh: 15 m2 dan 100 kg, dibagi 0,85, sekitar 17 ekor)?","levels_en":["Does not check pen area or the required area for the weight band, and keeps putting in as many pigs as will fit even as the count grows.","With guidance checks the pen area and divides, but picks the wrong weight band or leaves checking the result to others.","With guidance divides the area of a pen they are in charge of by the required area for the weight band, and can work out the maximum number of pigs it may hold.","Independently rechecks the weight band at weighing or shipping selection and recalculates the limit, also checks after a move that both the source and destination pens are within it, and tells the supervisor if a count is about to exceed it.","Understands that the required area per pig increases as weight increases, and can teach new staff how to work out the limit from area and head count."],"levels_vi":["Không kiểm tra diện tích ô chuồng hay diện tích cần thiết theo nhóm cân nặng, số con tăng lên vẫn cho vào hết mức có thể.","Nếu có chỉ dẫn thì xác nhận diện tích ô chuồng rồi chia, nhưng chọn sai nhóm cân nặng hoặc phó mặc việc kiểm tra kết quả cho người khác.","Nếu có chỉ dẫn thì chia diện tích ô chuồng mình phụ trách cho diện tích cần thiết của nhóm cân nặng, và tính được số con tối đa được nuôi.","Không cần chỉ dẫn vẫn xác nhận lại nhóm cân nặng khi cân hoặc chọn lợn xuất chuồng rồi tính lại số con tối đa, sau khi chuyển cũng xem ô chuồng đi và ô chuồng đến có nằm trong mức đó không, và nếu số con sắp vượt thì nói với cấp trên.","Hiểu rằng lợn càng nặng thì diện tích cần cho mỗi con càng tăng, và có thể hướng dẫn người mới cách tính mức tối đa từ diện tích và số đầu con."],"levels_id":["Tidak memeriksa luas petak kandang maupun luas yang dibutuhkan menurut kelompok bobot, dan terus memasukkan sebanyak mungkin walau jumlah ekor bertambah.","Jika ada instruksi, memastikan luas petak kandang lalu membaginya, tetapi salah memilih kelompok bobot atau menyerahkan pengecekan hasil kepada orang lain.","Jika ada instruksi, dapat membagi luas petak kandang yang menjadi tanggung jawabnya dengan luas yang dibutuhkan kelompok bobot, dan menghitung jumlah ekor maksimum.","Tanpa instruksi pun, memastikan ulang kelompok bobot saat penimbangan atau seleksi pengiriman lalu menghitung ulang batasnya, setelah pemindahan juga memeriksa apakah petak kandang asal dan tujuan masih dalam batas, dan memberi tahu atasan jika jumlah ekor hampir melebihinya.","Memahami bahwa luas yang dibutuhkan per ekor bertambah seiring bobot, dan bisa mengajari karyawan baru cara menghitung batas dari luas dan jumlah ekor."]},{"id":"crowd-signs","name":"過密の兆候を見抜く","kanten":"尾かじり・耳かじり、けんか、エサ箱や飲水器の渋滞、糞で汚れた豚、皮膚の傷など過密の兆候に気づき、全頭が同時に横になれるかを見られるか。","levels":["尾かじり・けんか・エサ箱の渋滞があっても、いつものことと見過ごし、豚房の混み具合を見ない。","指示があれば豚房を見るが、かじりやけんかなど目立つ兆候しか拾えず、見つけても伝えるのは他者まかせ。","指示があれば、かじり・けんか・エサ箱や飲水器の渋滞・糞汚れ・皮膚の傷を確かめ、全頭が同時に横になれるかも見られる。","指示がなくても豚房ごとに兆候の数の変化を記録して比べ、増えていれば豚房番号と様子を上長へ報告する。","過密も兆候の原因の一つだと理解し、横になれるかの簡易判断と主な兆候の見方を新人に指導できる。"],"name_en":"Spotting Signs of Overcrowding","name_vi":"Nhận ra dấu hiệu quá đông","name_id":"Mengenali tanda kepadatan berlebih","kanten_en":"Can they notice signs of overcrowding such as tail and ear biting, fighting, queues at feeders and drinkers, pigs soiled with manure, and skin wounds, and check whether all pigs can lie down at the same time?","kanten_vi":"Có nhận ra các dấu hiệu quá đông như cắn đuôi, cắn tai, đánh nhau, chen chúc ở máng ăn và vòi uống, lợn dính phân, vết thương ngoài da, và xem được toàn bộ lợn có nằm xuống cùng lúc được không.","kanten_id":"Apakah dapat menyadari tanda kepadatan berlebih seperti gigit ekor dan telinga, perkelahian, antrean di tempat pakan dan minum, babi kotor oleh kotoran, serta luka kulit, dan memeriksa apakah semua babi bisa berbaring bersamaan?","levels_en":["Overlooks tail biting, fighting, and crowding at the feeder as normal, and does not look at how crowded the pen is.","With guidance looks at the pen, but only picks up obvious signs such as biting and fighting, and leaves reporting what is found to others.","With guidance checks biting, fighting, queues at feeders and drinkers, soiling with manure, and skin wounds, and can also see whether all pigs can lie down at the same time.","Independently records and compares the number of signs for each pen, and if they are increasing, reports the pen number and the situation to the supervisor.","Understands that overcrowding is one cause of these signs, and can teach new staff the simple lying-down check and how to spot the main signs."],"levels_vi":["Bỏ qua cắn đuôi, đánh nhau, chen chúc ở máng ăn coi là chuyện thường, và không nhìn mức độ đông của ô chuồng.","Nếu có chỉ dẫn thì xem ô chuồng, nhưng chỉ nhặt ra các dấu hiệu dễ thấy như cắn và đánh nhau, và phó mặc việc báo những gì thấy cho người khác.","Nếu có chỉ dẫn thì kiểm tra cắn nhau, đánh nhau, chen chúc ở máng ăn và vòi uống, dính phân, vết thương ngoài da, và xem được toàn bộ lợn có nằm xuống cùng lúc được không.","Không cần chỉ dẫn vẫn ghi lại và so sánh số dấu hiệu của từng ô chuồng, và nếu tăng thì báo cấp trên số ô chuồng và tình trạng.","Hiểu rằng quá đông là một trong những nguyên nhân gây ra các dấu hiệu này, và có thể hướng dẫn người mới cách xem nhanh lợn có nằm được không cùng cách nhận ra các dấu hiệu chính."],"levels_id":["Mengabaikan gigit ekor, perkelahian, dan antrean di tempat pakan sebagai hal biasa, serta tidak melihat tingkat kepadatan petak kandang.","Jika ada instruksi, melihat petak kandang, tetapi hanya menangkap tanda yang mencolok seperti gigitan dan perkelahian, dan menyerahkan pelaporan temuan kepada orang lain.","Jika ada instruksi, memeriksa gigitan, perkelahian, antrean di tempat pakan dan minum, kotoran pada tubuh, dan luka kulit, serta dapat melihat apakah semua babi bisa berbaring bersamaan.","Tanpa instruksi pun, mencatat dan membandingkan jumlah tanda pada setiap petak kandang, dan jika bertambah, melapor kepada atasan dengan nomor petak dan kondisinya.","Memahami bahwa kepadatan berlebih adalah salah satu penyebab tanda-tanda itu, dan bisa mengajari karyawan baru pemeriksaan sederhana berbaring serta cara mengenali tanda utama."]},{"id":"split-judge","name":"分ける判断と上長報告","kanten":"過密や体格差を見たとき、空き豚房への移動、出荷が近い豚を先に出す案、小さい豚を別群にする、のどれが要るかを考え、放置せず上長に報告して相談できるか。","levels":["過密や小さい豚に気づいても「仕方ない」と放置し、誰にも報告しない。","指示があれば報告するが、どう分ければよいかは考えず、空き豚房の有無や出荷予定も確かめない。","指示があれば、空き豚房への移動・出荷が近い豚を先に出す案・小さい豚を別群にする、のどれが合うかを示して上長に相談できる。","指示がなくても過密や体格差に気づいた時点で、空き豚房と出荷予定を確かめ、案を添えて上長に報告する。","放置が尾かじりや成長遅延につながると理解し、3つの分け方の使い分けと報告のしかたを新人に指導できる。"],"name_en":"Deciding to Split and Reporting","name_vi":"Quyết định tách đàn và báo cấp trên","name_id":"Keputusan memisahkan kelompok dan lapor atasan","kanten_en":"When they see overcrowding or size differences, can they think through which is needed (moving some pigs to an empty pen, proposing to ship pigs nearing market weight first, or putting small pigs in a separate group), and report to and consult the supervisor instead of leaving it?","kanten_vi":"Khi thấy quá đông hoặc chênh lệch cỡ, có cân nhắc cần cách nào (chuyển bớt sang ô chuồng trống, đề xuất cho xuất chuồng trước những con sắp xuất chuồng, tách lợn nhỏ thành đàn riêng), và báo cấp trên để bàn thay vì bỏ mặc không.","kanten_id":"Ketika melihat kepadatan berlebih atau perbedaan ukuran, apakah dapat menimbang mana yang perlu (memindahkan sebagian ke petak kandang kosong, mengusulkan mengeluarkan lebih dulu babi yang dekat jadwal pengiriman, atau memisahkan babi kecil ke kelompok lain), dan melapor serta berkonsultasi dengan atasan tanpa membiarkannya?","levels_en":["Even on noticing overcrowding or small pigs, leaves it as unavoidable and reports to no one.","With guidance reports, but does not think about how to split, and does not check for empty pens or the shipping schedule.","With guidance can show which fits best (moving to an empty pen, proposing to ship pigs nearing market weight first, or putting small pigs in a separate group) and consult the supervisor.","Independently, as soon as overcrowding or size differences are noticed, checks empty pens and the shipping schedule and reports to the supervisor with a proposal.","Understands that leaving it leads to tail biting and slower growth, and can teach new staff how to choose among the 3 ways of splitting and how to report."],"levels_vi":["Dù nhận ra quá đông hoặc lợn nhỏ vẫn bỏ mặc vì cho rằng không còn cách nào, và không báo ai.","Nếu có chỉ dẫn thì báo, nhưng không nghĩ cách tách thế nào, cũng không kiểm tra ô chuồng trống hay lịch xuất chuồng.","Nếu có chỉ dẫn thì nêu được cách nào phù hợp (chuyển sang ô chuồng trống, đề xuất cho xuất chuồng trước những con sắp xuất chuồng, tách lợn nhỏ thành đàn riêng) và bàn với cấp trên.","Không cần chỉ dẫn, ngay khi nhận ra quá đông hoặc chênh lệch cỡ thì kiểm tra ô chuồng trống và lịch xuất chuồng rồi báo cấp trên kèm đề xuất.","Hiểu bỏ mặc sẽ dẫn đến cắn đuôi và chậm lớn, và có thể hướng dẫn người mới cách chọn trong 3 cách tách đàn và cách báo cáo."],"levels_id":["Walau menyadari kepadatan berlebih atau babi kecil, membiarkannya karena dianggap tidak bisa dihindari, dan tidak melapor kepada siapa pun.","Jika ada instruksi, melapor, tetapi tidak memikirkan cara memisahkan, dan tidak memeriksa petak kandang kosong maupun jadwal pengiriman.","Jika ada instruksi, dapat menunjukkan mana yang cocok (pindah ke petak kandang kosong, mengusulkan mengeluarkan lebih dulu babi yang dekat jadwal pengiriman, atau memisahkan babi kecil ke kelompok lain) dan berkonsultasi dengan atasan.","Tanpa instruksi pun, begitu menyadari kepadatan berlebih atau perbedaan ukuran, memeriksa petak kandang kosong dan jadwal pengiriman, lalu melapor kepada atasan beserta usulan.","Memahami bahwa pembiaran menyebabkan gigit ekor dan pertumbuhan lambat, dan bisa mengajari karyawan baru cara memilih dari 3 cara pemisahan serta cara melapor."]},{"id":"timing-fight","name":"移動の回数と時間帯","kanten":"新しい群を作る移動を最小限にし、暗めの時間帯（夕方から夜）に行うことを、前もって計画し口頭で説明できるか。","levels":["移動の回数も時間帯も考えず、群の組み替えを何度も繰り返す。","指示があれば移動の時間帯を選ぶが、組み替えの回数を減らす工夫が抜けて他者まかせになる。","指示があれば、新しい群を作る移動を最小限にし、暗めの時間帯（夕方から夜）に行う計画を立てられる。","指示がなくても移動の要否・回数・時間帯を前もって決めて上長に伝え、移動後に闘争が続いていれば上長に報告する。","新しい群を作ると闘争が起きやすいことと暗めの時間帯が有利な理由を理解し、移動の計画のしかたを新人に指導できる。"],"name_en":"Number and Timing of Moves","name_vi":"Số lần và thời điểm chuyển","name_id":"Jumlah dan waktu pemindahan","kanten_en":"Can they plan in advance, and explain aloud, how to keep moves that form a new group to a minimum and do them in a dimmer time of day (evening to night)?","kanten_vi":"Có lập kế hoạch trước và nói được bằng lời cách hạn chế tối thiểu việc chuyển lập đàn mới và thực hiện vào lúc trời tối hơn (chiều tối đến đêm) không.","kanten_id":"Apakah dapat merencanakan sebelumnya dan menjelaskan secara lisan cara membuat pemindahan yang membentuk kelompok baru seminimal mungkin dan dilakukan pada waktu yang lebih gelap (sore hingga malam)?","levels_en":["Does not think about the number or timing of moves, and regroups over and over.","With guidance chooses a time for the move, but does not think of ways to reduce the number of regroupings and leaves it to others.","With guidance can plan to keep moves that form a new group to a minimum and do them in a dimmer time of day (evening to night).","Independently decides in advance whether to move, how many times and when, and tells the supervisor; if fighting continues after the move, reports to the supervisor.","Understands that forming a new group easily causes fighting and why a dimmer time of day helps, and can teach new staff how to plan moves."],"levels_vi":["Không nghĩ đến số lần hay thời điểm chuyển, cứ xáo trộn đàn lặp đi lặp lại.","Nếu có chỉ dẫn thì chọn thời điểm chuyển, nhưng sót việc tìm cách giảm số lần xáo trộn đàn, phó mặc cho người khác.","Nếu có chỉ dẫn thì lập được kế hoạch hạn chế tối thiểu việc chuyển lập đàn mới và thực hiện lúc trời tối hơn (chiều tối đến đêm).","Không cần chỉ dẫn vẫn quyết định trước có cần chuyển không, bao nhiêu lần và lúc nào rồi báo cấp trên; nếu sau khi chuyển vẫn còn đánh nhau thì báo cấp trên.","Hiểu lập đàn mới dễ gây đánh nhau và vì sao lúc trời tối hơn có lợi, và có thể hướng dẫn người mới cách lập kế hoạch chuyển."],"levels_id":["Tidak memikirkan jumlah maupun waktu pemindahan, dan mengacak kelompok berulang kali.","Jika ada instruksi, memilih waktu pemindahan, tetapi tidak memikirkan cara mengurangi jumlah pengacakan kelompok dan menyerahkannya kepada orang lain.","Jika ada instruksi, dapat menyusun rencana agar pemindahan yang membentuk kelompok baru seminimal mungkin dan dilakukan pada waktu yang lebih gelap (sore hingga malam).","Tanpa instruksi pun, menentukan sebelumnya perlu tidaknya pindah, berapa kali, dan kapan lalu memberi tahu atasan; jika perkelahian berlanjut setelah pemindahan, melapor kepada atasan.","Memahami bahwa pembentukan kelompok baru mudah memicu perkelahian dan mengapa waktu yang lebih gelap membantu, dan bisa mengajari karyawan baru cara merencanakan pemindahan."]},{"id":"count-record","name":"移動した頭数の記録と日報反映","kanten":"豚房を移した頭数を、どの豚房から何頭をどこへと記録し、日報の式（前日頭数＋入舎−転出−死亡−出荷）に反映して合うか確かめられるか。","levels":["豚を移しても頭数を書き留めず、日報の頭数も前日のままか推測で書いてしまう。","指示があれば移した頭数を書くが、どの豚房から何頭かが抜け、日報の式への反映は他者まかせ。","指示があれば、どの豚房から何頭をどこへ移したかを記録し、日報の式（前日頭数＋入舎−転出−死亡−出荷）に入れて合うか確かめられる。","指示がなくても移動の直後に移動元・移動先の頭数を記録し、豚房の頭数の記録も直し、日報の頭数が合わなければその日のうちに原因を調べる。","頭数が合わないと原因の特定が難しくなることを理解し、移動の記録と日報への反映のしかたを新人に指導できる。"],"name_en":"Recording Moved Head Counts in the Daily Report","name_vi":"Ghi số đầu con đã chuyển vào báo cáo ngày","name_id":"Mencatat jumlah ekor yang dipindah ke laporan harian","kanten_en":"Can they record how many pigs went from which pen to which, enter it in the daily-report formula (previous-day count + pigs moved in − pigs moved out − deaths − shipments), and confirm it balances?","kanten_vi":"Có ghi lại đã chuyển bao nhiêu con từ ô chuồng nào sang đâu, đưa vào công thức của báo cáo ngày (số đầu con hôm trước + lợn nhập chuồng − lợn chuyển đi − chết − xuất chuồng) và xác nhận khớp không.","kanten_id":"Apakah dapat mencatat berapa ekor yang dipindah dari petak kandang mana ke mana, memasukkannya ke rumus laporan harian (jumlah ekor hari sebelumnya + babi masuk − babi pindah keluar − mati − pengiriman), dan memastikan cocok?","levels_en":["Does not write down the number of pigs after moving them, and leaves the daily head count as the previous day's or guesses it.","With guidance writes the number moved, but omits how many from which pen, and leaves entering it in the daily-report formula to others.","With guidance records how many pigs were moved from which pen to which, enters it in the daily-report formula (previous-day count + pigs moved in − pigs moved out − deaths − shipments), and can confirm it balances.","Independently records the head counts of the source and destination pens right after a move, corrects the pen head-count record, and if the daily count does not balance, investigates the cause the same day.","Understands that a head count that does not balance makes the cause hard to identify, and can teach new staff how to record moves and enter them in the daily report."],"levels_vi":["Chuyển lợn xong không ghi lại số con, số đầu con trong báo cáo ngày để nguyên như hôm trước hoặc ghi đại theo phỏng đoán.","Nếu có chỉ dẫn thì ghi số con đã chuyển, nhưng sót việc từ ô chuồng nào bao nhiêu con, và phó mặc việc đưa vào công thức báo cáo ngày cho người khác.","Nếu có chỉ dẫn thì ghi lại đã chuyển bao nhiêu con từ ô chuồng nào sang đâu, đưa vào công thức báo cáo ngày (số đầu con hôm trước + lợn nhập chuồng − lợn chuyển đi − chết − xuất chuồng) và xác nhận được có khớp không.","Không cần chỉ dẫn vẫn ghi số đầu con của ô chuồng đi và ô chuồng đến ngay sau khi chuyển, sửa lại ghi chép số đầu con của ô chuồng, và nếu số đầu con trong ngày không khớp thì tìm nguyên nhân ngay trong ngày.","Hiểu rằng số đầu con không khớp làm khó xác định nguyên nhân, và có thể hướng dẫn người mới cách ghi lại việc chuyển và đưa vào báo cáo ngày."],"levels_id":["Setelah memindahkan babi, tidak mencatat jumlah ekornya, dan jumlah ekor di laporan harian dibiarkan sama dengan hari sebelumnya atau ditebak.","Jika ada instruksi, menulis jumlah ekor yang dipindah, tetapi melewatkan berapa ekor dari petak kandang mana, dan menyerahkan pemasukan ke rumus laporan harian kepada orang lain.","Jika ada instruksi, dapat mencatat berapa ekor yang dipindah dari petak kandang mana ke mana, memasukkannya ke rumus laporan harian (jumlah ekor hari sebelumnya + babi masuk − babi pindah keluar − mati − pengiriman), dan memastikan cocok.","Tanpa instruksi pun, mencatat jumlah ekor petak kandang asal dan tujuan segera setelah pemindahan, memperbaiki catatan jumlah ekor petak kandang, dan jika jumlah ekor harian tidak cocok, mencari penyebabnya pada hari itu juga.","Memahami bahwa jumlah ekor yang tidak cocok membuat penyebab sulit ditemukan, dan bisa mengajari karyawan baru cara mencatat pemindahan serta memasukkannya ke laporan harian."]}],"name_en":"Density Management and Grouping (Finishing)","name_vi":"Quản lý mật độ và chia đàn (lợn thịt)","name_id":"Manajemen kepadatan dan pengelompokan (penggemukan)","purposeShort_en":"Prevent overcrowding by checking area and head count, and split groups when needed to reduce tail biting and fighting","purposeShort_vi":"Xem diện tích và số đầu con để tránh quá đông, và khi cần thì chia đàn để giảm cắn đuôi và đánh nhau","purposeShort_id":"Mencegah kepadatan berlebih dengan memeriksa luas dan jumlah ekor, dan memisahkan kelompok bila perlu untuk mengurangi gigit ekor dan perkelahian"},{"id":"daily-report","category":"record","no":"No.05","name":"日報記入","purposeShort":"豚の状態を記録して病気を早期発見し、成績を数字で残し改善に役立てる","gyomu":"05","aspects":[{"id":"accurate-timely","name":"その場での正確な記録","kanten":"記憶頼りのまとめ書きを避け、その場で事実と数字を正確に記録できるか。","levels":["記憶頼りで後からまとめ書きし、数値の単位ズレなど不正確な記録をする。","指示があれば記録するが、まとめ書きや単位ズレが多い。","指示があればその場で事実と数字をひと通り正確に記録できる。","指示がなくてもその場で正確に記録し、単位や数値を確かめる。","記録の正確さが早期発見・改善に不可欠と理解し、正確な記入を新人に指導できる。"],"name_en":"Accurate On-the-Spot Recording","kanten_en":"Can they avoid batch-writing from memory and record facts and figures accurately on the spot?","levels_en":["Batch-writes later from memory and makes inaccurate records such as unit mismatches in figures.","With guidance can record, but often batch-writes and mismatches units.","With guidance can record facts and figures accurately on the spot through the basic routine.","Independently records accurately on the spot and double-checks units and figures.","Understands that accurate records are essential to early detection and improvement, and can teach new staff accurate entry."],"name_vi":"Ghi chính xác ngay tại chỗ","kanten_vi":"Có tránh ghi gộp sau bằng trí nhớ, ghi sự việc và con số chính xác ngay tại chỗ không.","levels_vi":["Dựa vào trí nhớ, ghi gộp sau, ghi không chính xác như lệch đơn vị của số liệu.","Nếu được chỉ thị thì ghi, nhưng hay ghi gộp và lệch đơn vị.","Nếu được chỉ thị thì ghi sự việc, con số chính xác ngay tại chỗ được cơ bản.","Dù không có chỉ thị vẫn ghi chính xác ngay tại chỗ, kiểm tra lại đơn vị và con số.","Hiểu tính chính xác của ghi chép là không thể thiếu cho phát hiện sớm và cải thiện, và có thể hướng dẫn người mới cách ghi chính xác."],"name_id":"Mencatat dengan tepat di tempat","kanten_id":"Apakah menghindari menulis rangkuman dari ingatan, dan dapat mencatat fakta dan angka dengan tepat di tempat kerja?","levels_id":["Menulis rangkuman belakangan dari ingatan, dan membuat catatan tidak tepat seperti satuan angka yang keliru.","Mencatat jika diperintah, tetapi sering menulis rangkuman belakangan dan salah satuan.","Jika diperintah, dapat mencatat fakta dan angka dengan tepat di tempat secara lengkap.","Tanpa diperintah pun, mencatat dengan tepat di tempat, dan memastikan satuan dan angkanya.","Memahami bahwa ketepatan catatan penting untuk penemuan dini dan perbaikan, dan dapat mengajarkan pengisian yang tepat kepada karyawan baru."]},{"id":"shared-rule-use","name":"共通ルールでの記入と活用","kanten":"全員が同じルールで書き、書くだけで終わらせず見返して活用できるか。治療豚情報を漏らさないか。","levels":["自己流で書き、治療豚の薬剤名・投与量・開始日を記入せず休薬管理を抜けさせる。","指示があれば共通ルールで書くが、活用や治療豚情報の記入に漏れがある。","指示があれば共通ルールに沿ってひと通り記入できる。","指示がなくても共通ルールで書き、治療豚情報を漏らさず、記録を見返して活用する。","記録の共有と活用の意義を理解し、共通ルールと活用方法を新人に指導できる。"],"name_en":"Writing by Shared Rules and Putting Records to Use","kanten_en":"Can everyone write by the same rules, review and use the records rather than just writing them, and never omit treated-pig information?","levels_en":["Writes in a personal style and omits drug names, doses, and start dates for treated pigs, breaking withdrawal management.","With guidance writes by shared rules, but misses using the records or entering treated-pig information.","With guidance can complete entries following the shared rules.","Independently writes by shared rules, never omits treated-pig information, and reviews and uses the records.","Understands the value of sharing and using records, and can teach new staff the shared rules and how to use records."],"name_vi":"Ghi theo quy tắc chung và sử dụng ghi chép","kanten_vi":"Mọi người có ghi theo cùng một quy tắc, không chỉ ghi mà còn xem lại để sử dụng không. Có bỏ sót thông tin lợn đang điều trị không.","levels_vi":["Ghi theo kiểu riêng, không ghi tên thuốc, liều lượng, ngày bắt đầu của lợn điều trị, làm hổng quản lý thời gian ngừng thuốc.","Nếu được chỉ thị thì ghi theo quy tắc chung, nhưng còn thiếu sót về sử dụng và ghi thông tin lợn điều trị.","Nếu được chỉ thị thì ghi theo quy tắc chung được cơ bản.","Dù không có chỉ thị vẫn ghi theo quy tắc chung, không bỏ sót thông tin lợn điều trị, xem lại và sử dụng ghi chép.","Hiểu ý nghĩa của việc chia sẻ và sử dụng ghi chép, và có thể hướng dẫn người mới quy tắc chung và cách sử dụng."],"name_id":"Mengisi dengan aturan bersama dan memanfaatkannya","kanten_id":"Apakah semua orang menulis dengan aturan yang sama, tidak berhenti pada sekadar menulis tetapi membacanya kembali dan memanfaatkannya? Apakah data babi yang diobati tidak terlewat?","levels_id":["Menulis dengan gaya sendiri, tidak mengisi nama obat, dosis, dan tanggal mulai untuk babi yang diobati, sehingga pengelolaan masa henti obat bolong.","Menulis dengan aturan bersama jika diperintah, tetapi sering lalai memanfaatkan dan mengisi data babi yang diobati.","Jika diperintah, dapat mengisi sesuai aturan bersama secara lengkap.","Tanpa diperintah pun, menulis dengan aturan bersama, tidak melewatkan data babi yang diobati, dan membaca kembali catatan untuk dimanfaatkan.","Memahami arti berbagi dan memanfaatkan catatan, dan dapat mengajarkan aturan bersama dan cara memanfaatkannya kepada karyawan baru."]},{"id":"headcount-balance","name":"頭数変動の検算","kanten":"前日頭数＋入舎−転出−死亡−出荷（淘汰を含む）＝当日頭数の式で検算し、合わないとき当日中に原因を調べられるか。","levels":["頭数変動を書かず、計算が合わなくても気にせず放置する。","指示があれば頭数を書くが、検算をせず、不一致も他者に指摘されるまで気づかない。","指示があれば式で検算し、合わないことに自分で気づける。","指示がなくても毎日検算し、合わないときは当日中に記入漏れ・数え間違いなどの原因を調べる。","先延ばしが原因特定を難しくすると理解し、検算と当日中の原因調査を新人に指導できる。"],"name_en":"Verifying Head-Count Changes","kanten_en":"Can they verify using the formula previous-day count + pigs moved in − pigs moved out − deaths − shipments (including culls) = today's count, and investigate the cause the same day when it does not balance?","levels_en":["Does not record head-count changes and leaves mismatched calculations without concern.","With guidance records head counts, but skips verification and misses mismatches until others point them out.","With guidance can verify with the formula and notice by themselves when it does not balance.","Independently verifies every day and, when it does not balance, investigates causes such as missed entries or miscounts the same day.","Understands that postponing makes cause identification difficult, and can teach new staff verification and same-day cause investigation."],"name_vi":"Kiểm lại biến động số đầu con","kanten_vi":"Có kiểm lại bằng công thức: số đầu con hôm trước + lợn nhập chuồng − lợn chuyển đi − chết − xuất chuồng (kể cả loại thải) = số đầu con hôm nay, và khi không khớp có tìm nguyên nhân ngay trong ngày không.","levels_vi":["Không ghi biến động số đầu con, tính không khớp cũng không quan tâm và bỏ mặc.","Nếu được chỉ thị thì ghi số đầu con, nhưng không kiểm lại, sai lệch cũng không nhận ra cho đến khi người khác chỉ ra.","Nếu được chỉ thị thì kiểm lại bằng công thức, tự nhận ra khi không khớp.","Dù không có chỉ thị vẫn kiểm lại hằng ngày, khi không khớp thì tìm nguyên nhân như sót ghi, đếm nhầm ngay trong ngày.","Hiểu việc trì hoãn làm khó xác định nguyên nhân, và có thể hướng dẫn người mới việc kiểm lại và tìm nguyên nhân trong ngày."],"name_id":"Menghitung ulang perubahan jumlah ekor","kanten_id":"Apakah dapat menghitung ulang dengan rumus: jumlah ekor hari sebelumnya + babi masuk − babi pindah keluar − mati − pengiriman (termasuk afkir) = jumlah ekor hari ini, dan mencari penyebabnya pada hari itu juga jika tidak cocok?","levels_id":["Tidak mencatat perubahan jumlah ekor, dan tidak peduli walau perhitungannya tidak cocok.","Mencatat jumlah ekor jika diperintah, tetapi tidak menghitung ulang, dan tidak menyadari ketidakcocokan sampai ditunjukkan orang lain.","Jika diperintah, dapat menghitung ulang dengan rumus dan menyadari sendiri bila tidak cocok.","Tanpa diperintah pun, menghitung ulang setiap hari, dan bila tidak cocok mencari penyebabnya seperti catatan terlewat atau salah hitung pada hari itu juga.","Memahami bahwa menunda membuat penyebab sulit ditemukan, dan dapat mengajarkan penghitungan ulang serta pencarian penyebab pada hari yang sama kepada karyawan baru."]},{"id":"detail-findings","name":"死亡・異常の具体的な記述","kanten":"死亡・異常を「死亡1頭」で済ませず、場所・番号・時間・症状まで具体的に書けるか。","levels":["死亡や異常があっても書かない、または「特に問題なし」で済ませて放置する。","指示があれば書くが、「なんか具合が悪そう」式のあいまいな表現が多く項目に抜けがある。","指示があれば場所・個体番号・時間・症状をひと通り具体的に書ける。","指示がなくても推定体重や外見の様子まで書き、残餌増加などの小さな気づきも記録する。","記述が後の原因究明の手がかりになると理解し、具体的な書き方を新人に指導できる。"],"name_en":"Specific Description of Deaths and Abnormalities","kanten_en":"Can they describe deaths and abnormalities specifically down to place, number, time, and symptoms, instead of settling for \"1 death\"?","levels_en":["Does not write up deaths or abnormalities, or dismisses them as \"no particular problem\".","With guidance writes, but uses many vague expressions like \"seems somehow unwell\" and leaves items missing.","With guidance can write place, individual number, time, and symptoms specifically through the basic routine.","Independently writes down to estimated weight and outward appearance, and records small findings such as increased leftover feed.","Understands that descriptions become clues for later cause investigation, and can teach new staff specific writing."],"name_vi":"Mô tả cụ thể về chết và bất thường","kanten_vi":"Có viết cụ thể đến nơi, số hiệu, thời gian, triệu chứng, thay vì chỉ ghi \"chết 1 con\" không.","levels_vi":["Có chết hay bất thường cũng không ghi, hoặc chỉ ghi \"không có vấn đề gì\" rồi bỏ mặc.","Nếu được chỉ thị thì ghi, nhưng nhiều cách viết mơ hồ kiểu \"hình như hơi yếu\" và còn sót mục.","Nếu được chỉ thị thì ghi cụ thể được cơ bản nơi, số hiệu cá thể, thời gian, triệu chứng.","Dù không có chỉ thị vẫn ghi đến cả trọng lượng ước tính, dáng vẻ bên ngoài, và ghi lại cả những phát hiện nhỏ như thức ăn thừa tăng.","Hiểu mô tả sẽ là manh mối để tìm nguyên nhân sau này, và có thể hướng dẫn người mới cách viết cụ thể."],"name_id":"Uraian yang rinci tentang kematian dan kelainan","kanten_id":"Apakah dapat menulis secara rinci sampai tempat, nomor, waktu, dan gejala, bukan hanya \"mati 1 ekor\"?","levels_id":["Walau ada kematian atau kelainan tidak menulisnya, atau hanya menulis \"tidak ada masalah\" lalu membiarkannya.","Menulis jika diperintah, tetapi banyak ungkapan samar seperti \"sepertinya kurang sehat\" dan ada bagian yang terlewat.","Jika diperintah, dapat menulis tempat, nomor individu, waktu, dan gejala secara rinci dan lengkap.","Tanpa diperintah pun, menulis sampai perkiraan bobot dan penampilan luar, serta mencatat temuan kecil seperti sisa pakan yang bertambah.","Memahami bahwa uraian menjadi petunjuk untuk mencari penyebab di kemudian hari, dan dapat mengajarkan cara menulis yang rinci kepada karyawan baru."]},{"id":"trend-report","name":"前日比較と急変の報告","kanten":"前日までの日報と数字を比べ、死亡や治療頭数の急変・設備不具合を上長へ報告できるか。","levels":["過去の日報と比べず、死亡数が急に増えても気づかず報告もしない。","指示があれば比べるが、急変の見落としが多く、報告するかは他者まかせ。","指示があれば前日までの数字と比べ、急に変わった項目を報告できる。","指示がなくても毎日比較し、急変や設備不具合を報告した相手まで日報に残す。","週ごとの推移を見て対策につなげる意義を理解し、比較と報告の要点を新人に指導できる。"],"name_en":"Comparing with Previous Days and Reporting Sudden Changes","kanten_en":"Can they compare figures with daily reports up to the previous day, and report sudden changes in deaths or treated-pig counts and equipment trouble to a supervisor?","levels_en":["Does not compare with past daily reports, and neither notices nor reports sudden rises in deaths.","With guidance compares, but often overlooks sudden changes and leaves reporting to others.","With guidance can compare with figures up to the previous day and report items that changed suddenly.","Independently compares every day, and records in the daily report even whom they reported sudden changes and equipment trouble to.","Understands the value of watching weekly trends to build countermeasures, and can teach new staff the key points of comparison and reporting."],"name_vi":"So sánh với hôm trước và báo cáo thay đổi đột ngột","kanten_vi":"Có so sánh con số với nhật ký công việc đến hôm trước, và báo cáo cấp trên khi số chết, số con điều trị thay đổi đột ngột hoặc thiết bị trục trặc không.","levels_vi":["Không so sánh với nhật ký trước đây, số chết tăng đột ngột cũng không nhận ra và không báo cáo.","Nếu được chỉ thị thì so sánh, nhưng hay bỏ sót thay đổi đột ngột, việc báo cáo thì phó mặc người khác.","Nếu được chỉ thị thì so sánh với con số đến hôm trước, báo cáo được mục thay đổi đột ngột.","Dù không có chỉ thị vẫn so sánh hằng ngày, ghi vào nhật ký cả người mình đã báo cáo về thay đổi đột ngột, trục trặc thiết bị.","Hiểu ý nghĩa của việc xem diễn biến theo tuần để đưa ra đối sách, và có thể hướng dẫn người mới điểm chính của so sánh và báo cáo."],"name_id":"Membandingkan dengan hari sebelumnya dan melaporkan perubahan mendadak","kanten_id":"Apakah dapat membandingkan angka dengan laporan harian sampai hari sebelumnya, dan melaporkan kepada atasan perubahan mendadak jumlah kematian atau jumlah yang diobati serta gangguan peralatan?","levels_id":["Tidak membandingkan dengan laporan harian sebelumnya, tidak menyadari dan tidak melaporkan walau jumlah kematian naik mendadak.","Membandingkan jika diperintah, tetapi sering melewatkan perubahan mendadak, dan urusan melapor diserahkan kepada orang lain.","Jika diperintah, dapat membandingkan dengan angka sampai hari sebelumnya dan melaporkan hal yang berubah mendadak.","Tanpa diperintah pun, membandingkan setiap hari, dan mencatat di laporan harian sampai kepada siapa perubahan mendadak atau gangguan peralatan dilaporkan.","Memahami arti melihat perkembangan mingguan untuk menyusun penanggulangan, dan dapat mengajarkan pokok perbandingan dan pelaporan kepada karyawan baru."]}],"name_en":"Daily Report Entry","name_vi":"Ghi nhật ký công việc","name_id":"Mengisi laporan harian","purposeShort_en":"Record pig conditions for early disease detection and keep performance in numbers for improvement","purposeShort_vi":"Ghi lại tình trạng lợn để phát hiện bệnh sớm, lưu thành tích bằng con số để phục vụ cải thiện","purposeShort_id":"Mencatat keadaan babi untuk menemukan penyakit sejak dini, dan menyimpan hasil kerja dalam angka untuk perbaikan"},{"id":"plate","category":"record","no":"No.07","name":"プレート作成","purposeShort":"個体・群をすぐ見分けられるようにし、ワクチン・治療・休薬中を示す","gyomu":"07","aspects":[{"id":"update","name":"最新状態への更新と旧プレート処理","kanten":"情報を最新に保ち、分娩後の作成忘れや、差し替え時の古いプレートの残存を防げるか。","levels":["分娩後に作成し忘れ、差し替え時も古いプレートを廃棄せず誤情報を残す。","指示があれば更新するが、作成忘れや旧プレート処理に漏れがある。","指示があれば情報をひと通り最新に更新できる。","指示がなくても分娩後すぐ作成し、差し替え時は古いプレートを確実に廃棄する。","情報の鮮度が個体管理に直結すると理解し、更新と旧プレート処理を新人に指導できる。"],"name_en":"Keeping Plates Current and Disposing of Old Ones","kanten_en":"Can they keep information current, avoiding missed plate creation after farrowing and old plates left behind after replacement?","levels_en":["Forgets to create plates after farrowing and leaves old plates undiscarded at replacement, keeping wrong information posted.","With guidance can update, but misses plate creation or old-plate disposal.","With guidance can update information to the current state through the basic routine.","Independently creates plates right after farrowing and reliably discards old plates at replacement.","Understands that information freshness directly affects individual management, and can teach new staff updating and old-plate disposal."],"name_vi":"Cập nhật trạng thái mới nhất và xử lý thẻ cũ","kanten_vi":"Có giữ thông tin luôn mới nhất, tránh quên làm thẻ sau khi đẻ, tránh để sót thẻ cũ khi thay thẻ không.","levels_vi":["Quên làm thẻ sau khi đẻ, khi thay cũng không bỏ thẻ cũ, để lại thông tin sai.","Nếu được chỉ thị thì cập nhật, nhưng còn thiếu sót về quên làm thẻ và xử lý thẻ cũ.","Nếu được chỉ thị thì cập nhật thông tin lên mới nhất được cơ bản.","Dù không có chỉ thị vẫn làm thẻ ngay sau khi đẻ, khi thay thì bỏ chắc chắn thẻ cũ.","Hiểu độ mới của thông tin liên quan trực tiếp đến quản lý cá thể, và có thể hướng dẫn người mới việc cập nhật và xử lý thẻ cũ."],"name_id":"Memperbarui ke keadaan terkini dan membuang kartu lama","kanten_id":"Apakah dapat menjaga informasi tetap terkini, tidak lupa membuat kartu setelah melahirkan, dan tidak membiarkan kartu lama tertinggal saat penggantian?","levels_id":["Lupa membuat kartu setelah melahirkan, dan saat penggantian tidak membuang kartu lama sehingga informasi salah tertinggal.","Memperbarui jika diperintah, tetapi sering lupa membuat dan lalai menangani kartu lama.","Jika diperintah, dapat memperbarui informasi ke keadaan terkini secara lengkap.","Tanpa diperintah pun, segera membuat setelah melahirkan, dan saat penggantian pasti membuang kartu lama.","Memahami bahwa kesegaran informasi langsung memengaruhi pengelolaan individu, dan dapat mengajarkan pembaruan dan penanganan kartu lama kepada karyawan baru."]},{"id":"readable","name":"誰にでも分かる表記・色分けルールの遵守","kanten":"誰が見ても分かる表記にし、農場の色分け・略語ルールに従い、自分の判断で色や略語を作らないか。","levels":["担当者ごとに書式が異なり、自分の判断で色や略語を作って後任者が判読できない。","指示があれば書くが、表記の統一や色分けルールの適用に漏れがある。","指示があれば決められた書式と色分けルールに沿ってひと通り作成できる。","指示がなくても誰でも分かる統一表記で書き、迷う略語は勝手に作らず指導係に確認する。","表記統一の意義を理解し、分かりやすいプレート作成を新人に指導できる。"],"name_en":"Notation Anyone Can Read and Following Color-Coding Rules","kanten_en":"Can they use notation anyone can understand, follow the farm's color-coding and abbreviation rules, and avoid inventing colors or abbreviations on their own judgment?","levels_en":["Uses formats that differ by person and invents colors and abbreviations on their own, so successors cannot read the plates.","With guidance writes, but misses unifying notation and applying the color-coding rules.","With guidance can create plates following the set format and color-coding rules through the basic routine.","Independently writes in unified notation anyone can read, and checks uncertain abbreviations with the trainer instead of inventing them.","Understands the value of unified notation, and can teach new staff how to make clear plates."],"name_vi":"Cách ghi ai cũng hiểu và tuân thủ quy tắc phân màu","kanten_vi":"Có ghi sao cho ai nhìn cũng hiểu, theo quy tắc phân màu, viết tắt của trại, không tự ý tạo màu hay chữ viết tắt không.","levels_vi":["Mỗi người ghi một kiểu, tự ý tạo màu và chữ viết tắt khiến người kế nhiệm không đọc được.","Nếu được chỉ thị thì ghi, nhưng còn thiếu sót về thống nhất cách ghi và áp dụng quy tắc phân màu.","Nếu được chỉ thị thì làm được cơ bản theo mẫu và quy tắc phân màu đã định.","Dù không có chỉ thị vẫn ghi thống nhất ai cũng hiểu, chữ viết tắt còn phân vân thì không tự tạo mà hỏi người hướng dẫn.","Hiểu ý nghĩa của việc thống nhất cách ghi, và có thể hướng dẫn người mới cách làm thẻ dễ hiểu."],"name_id":"Penulisan yang dimengerti siapa pun dan menaati aturan pewarnaan","kanten_id":"Apakah menulis dengan cara yang dimengerti siapa pun, mengikuti aturan pewarnaan dan singkatan peternakan, dan tidak membuat warna atau singkatan atas pertimbangan sendiri?","levels_id":["Format tulisan berbeda tiap petugas, membuat warna dan singkatan sendiri sehingga pengganti tidak dapat membacanya.","Menulis jika diperintah, tetapi sering lalai menyeragamkan penulisan dan menerapkan aturan pewarnaan.","Jika diperintah, dapat membuat sesuai format dan aturan pewarnaan yang ditetapkan secara lengkap.","Tanpa diperintah pun, menulis dengan format seragam yang dimengerti siapa pun, dan singkatan yang meragukan tidak dibuat sendiri melainkan ditanyakan kepada pembimbing.","Memahami arti keseragaman penulisan, dan dapat mengajarkan pembuatan kartu yang mudah dimengerti kepada karyawan baru."]},{"id":"source-copy","name":"記録を見ながらの転記と読み合わせ","kanten":"記憶で書かず日報・治療記録・母豚カードを見て写し、書いた後に数字を指差しで照合できるか。","levels":["記憶だけで書いて番号や日付を間違え、照合もせず放置する。","指示があれば記録を見て写すが、読み合わせを省きがちで間違いに気づかない。","指示があれば記録を見ながら写し、書いた後に数字を1つずつ照合できる。","指示がなくても必ず記録を見て転記し、食い違いはその場で直すか上司に報告する。","転記ミスが作業ミスにつながると理解し、記録を見て写す習慣と照合を新人に指導できる。"],"name_en":"Copying from Records and Read-Back Verification","kanten_en":"Can they copy from the daily report, treatment records, and sow cards instead of writing from memory, and point-check the figures after writing?","levels_en":["Writes from memory alone, gets numbers and dates wrong, and leaves them unverified.","With guidance copies from the records, but tends to skip the read-back and misses errors.","With guidance can copy while viewing the records and check the figures one by one after writing.","Independently always copies from the records, and fixes discrepancies on the spot or reports them to a supervisor.","Understands that copying errors lead to work errors, and can teach new staff the habit of copying from records and verifying."],"name_vi":"Chép theo ghi chép và đối chiếu lại","kanten_vi":"Có chép theo nhật ký công việc, hồ sơ điều trị, thẻ lợn nái thay vì viết bằng trí nhớ, và sau khi viết có chỉ tay đối chiếu con số không.","levels_vi":["Chỉ viết bằng trí nhớ, sai số hiệu và ngày tháng, cũng không đối chiếu mà bỏ mặc.","Nếu được chỉ thị thì xem ghi chép để chép, nhưng hay bỏ qua việc đối chiếu lại nên không nhận ra sai sót.","Nếu được chỉ thị thì chép theo ghi chép, sau khi viết đối chiếu được từng con số một.","Dù không có chỉ thị vẫn luôn xem ghi chép để chép, chỗ sai lệch thì sửa ngay tại chỗ hoặc báo cáo cấp trên.","Hiểu chép nhầm sẽ dẫn đến làm nhầm, và có thể hướng dẫn người mới thói quen xem ghi chép để chép và đối chiếu."],"name_id":"Menyalin sambil melihat catatan dan mencocokkannya kembali","kanten_id":"Apakah menyalin sambil melihat laporan harian, catatan pengobatan, dan kartu induk babi, bukan menulis dari ingatan, dan setelah menulis mencocokkan angkanya sambil menunjuk?","levels_id":["Menulis hanya dari ingatan, salah nomor dan tanggal, serta membiarkannya tanpa dicocokkan.","Menyalin sambil melihat catatan jika diperintah, tetapi cenderung melewatkan pencocokan sehingga tidak menyadari kesalahan.","Jika diperintah, dapat menyalin sambil melihat catatan dan mencocokkan angka satu per satu setelah menulis.","Tanpa diperintah pun, selalu menyalin sambil melihat catatan, dan ketidaksesuaian langsung diperbaiki di tempat atau dilaporkan kepada atasan.","Memahami bahwa salah salin berujung pada salah kerja, dan dapat mengajarkan kebiasaan menyalin sambil melihat catatan serta mencocokkannya kepada karyawan baru."]},{"id":"withdrawal-card","name":"治療カードの休薬情報記入","kanten":"治療カードに薬剤名・休薬期間・出荷可能日まで書き切り、治療中と目立たせられるか。","levels":["治療カードを作らない、または休薬情報を書かず、休薬中の豚を見分けられなくする。","指示があれば書くが、出荷可能日の記入漏れや目立たせ方の不足が多い。","指示があれば症状・薬剤名・休薬期間・出荷可能日までひと通り書ける。","指示がなくても休薬が明ける日付まで必ず書き切り、治療中と一目で分かるよう目立たせる。","休薬情報が食の安全に直結すると理解し、治療カードの書き方を新人に指導できる。"],"name_en":"Entering Withdrawal Information on Treatment Cards","kanten_en":"Can they write treatment cards completely with drug name, withdrawal period, and earliest shipping date, and make under-treatment status stand out?","levels_en":["Does not make treatment cards, or omits withdrawal information, making withdrawal pigs impossible to distinguish.","With guidance writes, but often misses the earliest shipping date and fails to make cards stand out.","With guidance can write symptoms, drug name, withdrawal period, and earliest shipping date through the basic routine.","Independently always writes through to the date the withdrawal ends, and makes cards stand out so treatment status is clear at a glance.","Understands that withdrawal information directly affects food safety, and can teach new staff how to write treatment cards."],"name_vi":"Ghi thông tin ngừng thuốc trên thẻ điều trị","kanten_vi":"Có ghi đầy đủ trên thẻ điều trị tên thuốc, thời gian ngừng thuốc, ngày có thể xuất chuồng, và làm nổi bật là đang điều trị không.","levels_vi":["Không làm thẻ điều trị, hoặc không ghi thông tin ngừng thuốc, khiến không phân biệt được lợn đang ngừng thuốc.","Nếu được chỉ thị thì ghi, nhưng hay sót ngày có thể xuất chuồng và chưa làm đủ nổi bật.","Nếu được chỉ thị thì ghi được cơ bản triệu chứng, tên thuốc, thời gian ngừng thuốc, ngày có thể xuất chuồng.","Dù không có chỉ thị vẫn ghi đủ đến ngày hết ngừng thuốc, làm nổi bật để nhìn một cái là biết đang điều trị.","Hiểu thông tin ngừng thuốc liên quan trực tiếp đến an toàn thực phẩm, và có thể hướng dẫn người mới cách ghi thẻ điều trị."],"name_id":"Mengisi informasi masa henti obat pada kartu pengobatan","kanten_id":"Apakah dapat mengisi kartu pengobatan sampai nama obat, masa henti obat, dan tanggal boleh dikirim, serta membuat status sedang diobati mencolok?","levels_id":["Tidak membuat kartu pengobatan, atau tidak mengisi informasi masa henti obat, sehingga babi dalam masa henti obat tidak dapat dibedakan.","Mengisi jika diperintah, tetapi sering melewatkan tanggal boleh dikirim dan kurang membuatnya mencolok.","Jika diperintah, dapat mengisi gejala, nama obat, masa henti obat, sampai tanggal boleh dikirim secara lengkap.","Tanpa diperintah pun, selalu mengisi sampai tanggal berakhirnya masa henti obat, dan membuatnya mencolok agar sekali lihat tahu sedang diobati.","Memahami bahwa informasi masa henti obat berhubungan langsung dengan keamanan pangan, dan dapat mengajarkan cara mengisi kartu pengobatan kepada karyawan baru."]},{"id":"attach-safety","name":"取り付け位置と誤飲防止","kanten":"通路側から読め汚れにくい高さに付け、タイの切れ端やペンのキャップを豚房に落とさないか。","levels":["豚がかじれる位置に付けたり、切れ端を豚房に落としたりしても気にしない。","指示があれば付けるが、高さや向きにムラがあり、切れ端の回収も他者まかせ。","指示があれば通路側から読める高さに付け、切れ端やキャップを回収できる。","指示がなくても読みやすく汚れにくい位置を選び、豚が飲み込む物を残さないか確かめる。","誤飲の危険と読みやすさの両立を理解し、安全な取り付け方を新人に指導できる。"],"name_en":"Attachment Position and Preventing Accidental Ingestion","kanten_en":"Can they attach plates at a height readable from the aisle and unlikely to get dirty, without dropping tie scraps or pen caps into the pen?","levels_en":["Attaches plates where pigs can chew them and does not care about scraps dropped into the pen.","With guidance attaches, but height and orientation vary and leaves scrap collection to others.","With guidance can attach at a height readable from the aisle and collect scraps and caps.","Independently chooses positions that are readable and unlikely to get dirty, and checks that nothing swallowable is left for the pigs.","Understands both the danger of accidental ingestion and readability, and can teach new staff safe attachment."],"name_vi":"Vị trí gắn và phòng nuốt nhầm","kanten_vi":"Có gắn ở độ cao đọc được từ lối đi, khó bị bẩn, không làm rơi mẩu dây buộc hay nắp bút vào ô chuồng không.","levels_vi":["Gắn ở chỗ lợn gặm được, làm rơi mẩu vụn vào ô chuồng cũng không quan tâm.","Nếu được chỉ thị thì gắn, nhưng độ cao và hướng không đều, việc thu nhặt mẩu vụn thì phó mặc người khác.","Nếu được chỉ thị thì gắn được ở độ cao đọc được từ lối đi, thu nhặt mẩu vụn và nắp bút.","Dù không có chỉ thị vẫn chọn vị trí dễ đọc, khó bẩn, kiểm tra không để lại vật lợn có thể nuốt.","Hiểu phải vừa phòng nguy cơ nuốt nhầm vừa bảo đảm dễ đọc, và có thể hướng dẫn người mới cách gắn an toàn."],"name_id":"Posisi pemasangan dan pencegahan tertelannya benda","kanten_id":"Apakah memasang pada ketinggian yang terbaca dari lorong dan tidak mudah kotor, tanpa menjatuhkan potongan pengikat atau tutup pena ke dalam kandang?","levels_id":["Memasang di posisi yang bisa digigit babi, dan tidak peduli walau menjatuhkan potongan ke dalam kandang.","Memasang jika diperintah, tetapi ketinggian dan arahnya tidak seragam, dan pengumpulan potongan diserahkan kepada orang lain.","Jika diperintah, dapat memasang pada ketinggian yang terbaca dari lorong dan mengumpulkan potongan serta tutup pena.","Tanpa diperintah pun, memilih posisi yang mudah dibaca dan tidak mudah kotor, serta memastikan tidak ada benda yang dapat tertelan babi yang tertinggal.","Memahami perlunya menyeimbangkan bahaya tertelannya benda dan kemudahan membaca, dan dapat mengajarkan cara pemasangan yang aman kepada karyawan baru."]}],"name_en":"Plate Preparation","name_vi":"Làm thẻ thông tin (plate)","name_id":"Membuat kartu data (plate)","purposeShort_en":"Make individuals and groups instantly identifiable and show vaccination, treatment, and withdrawal status","purposeShort_vi":"Giúp nhận biết ngay từng con, từng nhóm; hiển thị vắc-xin, điều trị, đang ngừng thuốc","purposeShort_id":"Membuat individu dan kelompok mudah dikenali dengan cepat, serta menandai babi yang divaksin, diobati, atau dalam masa henti obat"},{"id":"tagging","category":"record","no":"No.21","name":"タグ付け","purposeShort":"1頭ずつ確実に見分け、健康・繁殖・治療・出荷を一貫管理し追跡可能にする","gyomu":"21","aspects":[{"id":"position-asepsis","name":"正しい位置と装着前消毒","kanten":"決められた位置・向きに正しく付け、装着前に器具と耳を消毒できるか。","levels":["装着位置・向きが不統一で読み取りにくく、器具・耳の消毒もしない。","指示があれば付けるが、位置の統一や消毒に漏れがある。","指示があれば決められた位置に、消毒してひと通り装着できる。","指示がなくても位置・向きを統一し、装着前に器具と耳を消毒する。","読み取りやすさと感染防止を理解し、正しい装着と消毒を新人に指導できる。"],"name_en":"Correct Position and Pre-Attachment Disinfection","kanten_en":"Can they attach tags correctly in the designated position and orientation, and disinfect the applicator and the ear before attachment?","levels_en":["Attaches tags in inconsistent positions and orientations that are hard to read, and skips disinfecting the applicator and the ear.","With guidance can attach tags, but misses position consistency or disinfection.","With guidance can disinfect and attach tags in the designated position through the basic routine.","Independently keeps position and orientation consistent and disinfects the applicator and the ear before attachment.","Understands readability and infection prevention, and can teach new staff correct attachment and disinfection."],"name_vi":"Vị trí đúng và khử trùng trước khi gắn","kanten_vi":"Có gắn đúng vị trí, đúng chiều quy định, khử trùng dụng cụ và tai trước khi gắn không.","levels_vi":["Vị trí, chiều gắn không thống nhất, khó đọc, cũng không khử trùng dụng cụ và tai.","Nếu được chỉ thị thì gắn, nhưng còn thiếu sót về thống nhất vị trí và khử trùng.","Nếu được chỉ thị thì khử trùng và gắn vào đúng vị trí quy định được cơ bản.","Dù không có chỉ thị vẫn thống nhất vị trí, chiều gắn, khử trùng dụng cụ và tai trước khi gắn.","Hiểu tính dễ đọc và việc phòng nhiễm trùng, và có thể hướng dẫn người mới cách gắn đúng và khử trùng."],"name_id":"Posisi yang benar dan disinfeksi sebelum pemasangan","kanten_id":"Apakah dapat memasang dengan benar pada posisi dan arah yang ditentukan, serta mendisinfeksi alat dan telinga sebelum pemasangan?","levels_id":["Posisi dan arah pemasangan tidak seragam sehingga sulit dibaca, dan tidak mendisinfeksi alat dan telinga.","Memasang jika diperintah, tetapi sering lalai menyeragamkan posisi dan mendisinfeksi.","Jika diperintah, dapat memasang pada posisi yang ditentukan dengan disinfeksi secara lengkap.","Tanpa diperintah pun, menyeragamkan posisi dan arah, serta mendisinfeksi alat dan telinga sebelum pemasangan.","Memahami kemudahan pembacaan dan pencegahan infeksi, dan dapat mengajarkan pemasangan yang benar dan disinfeksi kepada karyawan baru."]},{"id":"reattach","name":"脱落・破損時の再装着","kanten":"脱落・破損を見つけ次第付け直し、個体不明のまま管理を続けないか。","levels":["タグ付け忘れや脱落後の再装着をせず、個体不明のまま出荷しトレーサビリティを断つ。","指示があれば付け直すが、脱落の発見や再装着に漏れがある。","指示があれば脱落・破損をひと通り付け直せる。","指示がなくても脱落・破損を見つけ次第付け直し、個体不明を作らない。","トレーサビリティの重要性を理解し、脱落時の再装着徹底を新人に指導できる。"],"name_en":"Reattachment After Loss or Damage","kanten_en":"Can they reattach tags as soon as loss or damage is found, and never continue managing unidentified pigs?","levels_en":["Skips tagging or reattachment after loss, ships unidentified pigs, and breaks traceability.","With guidance can reattach, but misses spotting losses or reattaching.","With guidance can reattach lost or damaged tags through the basic routine.","Independently reattaches tags as soon as loss or damage is found and never leaves pigs unidentified.","Understands the importance of traceability, and can teach new staff thorough reattachment after tag loss."],"name_vi":"Gắn lại khi thẻ rơi, hỏng","kanten_vi":"Phát hiện thẻ rơi, hỏng có gắn lại ngay, không tiếp tục quản lý khi không rõ cá thể không.","levels_vi":["Quên gắn thẻ, thẻ rơi cũng không gắn lại, xuất chuồng khi không rõ cá thể, làm đứt truy xuất nguồn gốc.","Nếu được chỉ thị thì gắn lại, nhưng còn thiếu sót trong phát hiện thẻ rơi và gắn lại.","Nếu được chỉ thị thì gắn lại thẻ rơi, hỏng được cơ bản.","Dù không có chỉ thị vẫn phát hiện thẻ rơi, hỏng là gắn lại ngay, không để xảy ra con không rõ cá thể.","Hiểu tầm quan trọng của truy xuất nguồn gốc, và có thể hướng dẫn người mới việc gắn lại triệt để khi thẻ rơi."],"name_id":"Memasang ulang saat lepas atau rusak","kanten_id":"Apakah memasang ulang begitu menemukan tanda telinga yang lepas atau rusak, dan tidak melanjutkan pengelolaan dengan individu yang tidak dikenal?","levels_id":["Lupa memasang tanda telinga dan tidak memasang ulang setelah lepas, mengirim babi tanpa identitas, sehingga memutus ketertelusuran (traceability).","Memasang ulang jika diperintah, tetapi sering lalai menemukan yang lepas dan memasang ulang.","Jika diperintah, dapat memasang ulang yang lepas atau rusak secara lengkap.","Tanpa diperintah pun, memasang ulang begitu menemukan yang lepas atau rusak, dan tidak membiarkan ada individu tanpa identitas.","Memahami pentingnya ketertelusuran (traceability), dan dapat mengajarkan kedisiplinan memasang ulang saat lepas kepada karyawan baru."]},{"id":"number-prep","name":"番号順の準備と頭数照合","kanten":"タグを番号順にそろえ、腹の子豚の頭数と番号を数えて飛び・重複に装着前に気づけるか。","levels":["タグを数えず用意し、番号の飛びや重複に気づかないまま装着する。","指示があれば並べるが、頭数との照合を省きがちで間違いを他者に指摘される。","指示があれば番号順に並べ、頭数と番号が合っているか装着前に確認できる。","指示がなくても予備を含めて準備し、飛び・重複を装着前に見つけて対処する。","番号の乱れが記録の混乱を招くと理解し、準備と照合の手順を新人に指導できる。"],"name_en":"Preparing Tags in Number Order and Matching Head Counts","kanten_en":"Can they arrange tags in number order, count the litter's piglets and numbers, and notice gaps or duplicates before attachment?","levels_en":["Prepares tags without counting and attaches them without noticing gaps or duplicated numbers.","With guidance arranges tags, but tends to skip matching against head counts and has errors pointed out by others.","With guidance can arrange tags in number order and confirm before attachment that counts and numbers match.","Independently prepares including spares, and finds and handles gaps or duplicates before attachment.","Understands that disordered numbers cause record confusion, and can teach new staff the preparation and matching procedure."],"name_vi":"Chuẩn bị theo thứ tự số và đối chiếu số đầu con","kanten_vi":"Có xếp thẻ theo thứ tự số, đếm số lợn con trong ổ và số thẻ, nhận ra số nhảy cóc, trùng lặp trước khi gắn không.","levels_vi":["Chuẩn bị thẻ mà không đếm, gắn mà không nhận ra số nhảy cóc, trùng lặp.","Nếu được chỉ thị thì xếp, nhưng hay bỏ qua đối chiếu với số đầu con nên bị người khác chỉ ra sai sót.","Nếu được chỉ thị thì xếp theo thứ tự số, xác nhận được trước khi gắn số đầu con và số thẻ có khớp không.","Dù không có chỉ thị vẫn chuẩn bị cả thẻ dự phòng, phát hiện và xử lý số nhảy cóc, trùng lặp trước khi gắn.","Hiểu số bị rối sẽ gây hỗn loạn ghi chép, và có thể hướng dẫn người mới trình tự chuẩn bị và đối chiếu."],"name_id":"Menyiapkan sesuai urutan nomor dan mencocokkan jumlah ekor","kanten_id":"Apakah menyusun tag sesuai urutan nomor, menghitung jumlah anak babi dalam satu kelahiran dan nomornya, dan menyadari nomor yang loncat atau ganda sebelum pemasangan?","levels_id":["Menyiapkan tag tanpa menghitung, dan memasang tanpa menyadari nomor yang loncat atau ganda.","Menyusun jika diperintah, tetapi cenderung melewatkan pencocokan dengan jumlah ekor sehingga kesalahannya ditunjukkan orang lain.","Jika diperintah, dapat menyusun sesuai urutan nomor dan memastikan sebelum pemasangan bahwa jumlah ekor dan nomor cocok.","Tanpa diperintah pun, menyiapkan termasuk cadangan, dan menemukan serta menangani nomor loncat atau ganda sebelum pemasangan.","Memahami bahwa nomor yang kacau menimbulkan kekacauan catatan, dan dapat mengajarkan urutan persiapan dan pencocokan kepada karyawan baru."]},{"id":"restraint-attach","name":"保定と一回での確実な装着","kanten":"子豚をしっかり保定し、プライヤーを一気に握り込んで番号が読める状態に装着できるか。","levels":["保定が不十分なまま装着し、途中で止まったタグや読めないタグを放置する。","指示があれば装着するが、握りが中途半端で留まりのムラが多く、確認は他者まかせ。","指示があれば保定して一気に装着し、確実に留まって番号が読めるか確認できる。","指示がなくても確実に装着し、保定が難しいときは自分から先輩と2人で行う。","暴れによる位置ズレやけがの防止を理解し、保定と装着のコツを新人に指導できる。"],"name_en":"Restraint and Secure One-Motion Attachment","kanten_en":"Can they restrain the piglet firmly and squeeze the applicator in one motion to attach the tag so the number is readable?","levels_en":["Attaches with insufficient restraint and leaves half-closed or unreadable tags as they are.","With guidance attaches, but grips halfway with uneven fastening and leaves checking to others.","With guidance can restrain, attach in one motion, and confirm the tag is fastened securely and the number readable.","Independently attaches securely and, when restraint is difficult, works in a pair with a senior on their own initiative.","Understands preventing position shift and injury from struggling, and can teach new staff the knack of restraint and attachment."],"name_vi":"Giữ chặt và gắn chắc chắn trong một lần","kanten_vi":"Có giữ chặt lợn con, bóp kìm dứt khoát một lần để gắn thẻ ở trạng thái đọc được số không.","levels_vi":["Gắn khi giữ chưa chặt, thẻ kẹp dở dang hay không đọc được số cũng bỏ mặc.","Nếu được chỉ thị thì gắn, nhưng bóp nửa vời, độ bám không đều, việc kiểm tra thì phó mặc người khác.","Nếu được chỉ thị thì giữ chặt, gắn dứt khoát một lần, xác nhận được thẻ bám chắc và đọc được số.","Dù không có chỉ thị vẫn gắn chắc chắn, khi khó giữ thì tự đề nghị làm cùng người đi trước theo cặp 2 người.","Hiểu việc phòng lệch vị trí và bị thương do lợn giãy, và có thể hướng dẫn người mới mẹo giữ chặt và gắn thẻ."],"name_id":"Memegangi dan memasang dengan pasti dalam sekali gerakan","kanten_id":"Apakah dapat memegangi anak babi dengan kuat, menekan tang sekali gerakan dengan mantap, dan memasang tag dalam keadaan nomornya terbaca?","levels_id":["Memasang saat pegangan belum kuat, dan membiarkan tag yang berhenti setengah jalan atau tidak terbaca.","Memasang jika diperintah, tetapi tekanannya setengah-setengah sehingga hasilnya tidak rata, dan pemeriksaan diserahkan kepada orang lain.","Jika diperintah, dapat memegangi lalu memasang sekali gerakan, dan memastikan tag terpasang kuat serta nomornya terbaca.","Tanpa diperintah pun, memasang dengan pasti, dan bila sulit memegangi berinisiatif bekerja berdua dengan senior.","Memahami pencegahan pergeseran posisi dan cedera akibat meronta, dan dapat mengajarkan kiat memegangi dan memasang kepada karyawan baru."]},{"id":"record-observe","name":"その場記録と装着後の観察","kanten":"装着直後に個体番号・装着日・母豚番号をメモし、24〜48時間は耳の腫れと哺乳を確認できるか。","levels":["記録を残さず、装着後の耳の腫れや哺乳の様子も見ない。","指示があれば記録するが、後からまとめて記憶で書き、装着後の確認も抜けが多い。","指示があればその場でメモし、日報に正確に書き写し、装着後の見回りで耳を確認できる。","指示がなくてもその場で記録して見直し、腫れ・化膿や哺乳不良に気づけば報告する。","番号間違いが休薬管理をずらす危険を理解し、その場記録と観察を新人に指導できる。"],"name_en":"On-the-Spot Recording and Post-Attachment Observation","kanten_en":"Can they note the individual number, attachment date, and sow number right after attachment, and check ear swelling and suckling for 24-48 hours?","levels_en":["Leaves no record and does not watch for ear swelling or suckling after attachment.","With guidance records, but batch-writes later from memory and often misses post-attachment checks.","With guidance can note on the spot, copy accurately into the daily report, and check the ears on post-attachment rounds.","Independently records on the spot and reviews it, and reports swelling, festering, or poor suckling when noticed.","Understands the danger that number errors shift withdrawal management, and can teach new staff on-the-spot recording and observation."],"name_vi":"Ghi ngay tại chỗ và quan sát sau khi gắn","kanten_vi":"Có ghi ngay sau khi gắn số cá thể, ngày gắn, số lợn nái, và trong 24-48 giờ kiểm tra tai sưng và bú mẹ không.","levels_vi":["Không ghi lại, sau khi gắn cũng không xem tai sưng hay tình hình bú mẹ.","Nếu được chỉ thị thì ghi, nhưng để sau mới viết gộp bằng trí nhớ, kiểm tra sau khi gắn cũng nhiều thiếu sót.","Nếu được chỉ thị thì ghi chú ngay tại chỗ, chép chính xác vào nhật ký công việc, kiểm tra được tai khi đi tua sau khi gắn.","Dù không có chỉ thị vẫn ghi ngay tại chỗ và xem lại, nhận ra sưng, mưng mủ hay bú kém thì báo cáo.","Hiểu nguy cơ nhầm số làm lệch quản lý ngừng thuốc, và có thể hướng dẫn người mới việc ghi tại chỗ và quan sát."],"name_id":"Mencatat di tempat dan mengamati setelah pemasangan","kanten_id":"Apakah segera setelah pemasangan mencatat nomor individu, tanggal pemasangan, dan nomor induk babi, serta selama 24-48 jam memeriksa pembengkakan telinga dan menyusunya?","levels_id":["Tidak meninggalkan catatan, dan setelah pemasangan tidak melihat pembengkakan telinga maupun keadaan menyusu.","Mencatat jika diperintah, tetapi menulisnya belakangan dari ingatan, dan pemeriksaan setelah pemasangan sering terlewat.","Jika diperintah, dapat mencatat di tempat, menyalinnya dengan tepat ke laporan harian, dan memeriksa telinga saat keliling setelah pemasangan.","Tanpa diperintah pun, mencatat di tempat dan memeriksanya kembali, serta melaporkan bila menyadari bengkak, bernanah, atau kurang menyusu.","Memahami bahaya salah nomor menggeser pengelolaan masa henti obat, dan dapat mengajarkan pencatatan di tempat dan pengamatan kepada karyawan baru."]}],"name_en":"Tagging","name_vi":"Gắn thẻ tai (bấm thẻ số)","name_id":"Pemasangan tanda telinga (tag nomor)","purposeShort_en":"Identify each pig reliably for consistent health, breeding, treatment, and shipping management and traceability","purposeShort_vi":"Nhận biết chắc chắn từng con, quản lý nhất quán sức khỏe, sinh sản, điều trị, xuất chuồng và truy xuất được nguồn gốc","purposeShort_id":"Mengenali setiap ekor dengan pasti, mengelola kesehatan, reproduksi, pengobatan, dan pengiriman secara terpadu, serta membuatnya dapat ditelusuri"},{"id":"farrow-schedule","category":"record","no":"No.32","name":"分娩予定記入","purposeShort":"分娩時期を把握して舎・人手を計画的に準備し、不受胎を早期発見する","gyomu":"32","aspects":[{"id":"calc","name":"妊娠日齢の統一計算","kanten":"妊娠日齢の数え方を統一し、交配日から114〜115日後を正確に計算できるか。","levels":["交配日の記録が抜け、日齢の数え方も不統一で分娩予定を計算できない。","指示があれば計算するが、数え方の統一や幅の考慮に漏れがある。","指示があれば交配日から予定日をひと通り計算できる。","指示がなくても統一した数え方で114〜115日後を正確に計算する。","計算のズレが準備に与える影響を理解し、統一した数え方を新人に指導できる。"],"name_en":"Standardized Gestation-Day Calculation","kanten_en":"Can they use a standardized way of counting gestation days and accurately calculate 114-115 days from the mating date?","levels_en":["Mating dates go unrecorded and day counting is inconsistent, so due dates cannot be calculated.","With guidance can calculate, but misses the standardized counting or the allowance for the range.","With guidance can calculate the due date from the mating date through the basic procedure.","Independently calculates 114-115 days accurately using the standardized counting.","Understands how calculation errors affect preparation, and can teach new staff the standardized counting."],"name_vi":"Tính ngày tuổi thai theo cách thống nhất","kanten_vi":"Có thống nhất cách đếm ngày tuổi thai, tính đúng 114-115 ngày sau ngày giao phối không.","levels_vi":["Thiếu ghi chép ngày giao phối, cách đếm cũng không thống nhất nên không tính được ngày dự sinh.","Nếu được chỉ thị thì tính, nhưng còn thiếu sót về thống nhất cách đếm và xét khoảng dao động.","Nếu được chỉ thị thì tính được ngày dự sinh từ ngày giao phối một cách cơ bản.","Dù không có chỉ thị vẫn tính đúng 114-115 ngày sau bằng cách đếm thống nhất.","Hiểu ảnh hưởng của việc tính lệch đến khâu chuẩn bị, và có thể hướng dẫn người mới cách đếm thống nhất."],"name_id":"Menghitung umur kebuntingan dengan cara yang seragam","kanten_id":"Apakah cara menghitung umur kebuntingan diseragamkan, dan dapat menghitung dengan tepat 114-115 hari setelah tanggal kawin?","levels_id":["Catatan tanggal kawin bolong dan cara menghitung tidak seragam, sehingga perkiraan melahirkan tidak dapat dihitung.","Menghitung jika diperintah, tetapi sering lalai menyeragamkan cara hitung dan mempertimbangkan rentangnya.","Jika diperintah, dapat menghitung tanggal perkiraan dari tanggal kawin secara lengkap.","Tanpa diperintah pun, menghitung 114-115 hari setelah kawin dengan tepat memakai cara hitung yang seragam.","Memahami pengaruh selisih hitungan terhadap persiapan, dan dapat mengajarkan cara hitung yang seragam kepada karyawan baru."]},{"id":"rewrite","name":"再交配時の書き直しと母豚観察","kanten":"交配・再交配のたびに書き直し、予定日だけで判断せず母豚の様子も確認できるか。","levels":["再交配時に修正記入を忘れ、予定日だけで判断して母豚の様子を見ない。","指示があれば書き直すが、修正漏れや観察不足がある。","指示があれば交配・再交配のたびにひと通り書き直せる。","指示がなくても再交配時に必ず書き直し、母豚の様子も合わせて確認する。","書き直し漏れがスケジュール混乱を招くと理解し、記入と観察の徹底を新人に指導できる。"],"name_en":"Rewriting on Rebreeding and Observing the Sow","kanten_en":"Can they rewrite the entry at every mating and rebreeding, and check the sow's condition instead of judging by the due date alone?","levels_en":["Forgets to correct entries on rebreeding and judges by the due date alone without watching the sow.","With guidance can rewrite, but has missed corrections and insufficient observation.","With guidance can rewrite the entry at every mating and rebreeding through the basic routine.","Independently rewrites without fail on rebreeding and checks the sow's condition as well.","Understands that missed rewrites disrupt the schedule, and can teach new staff thorough entry and observation."],"name_vi":"Ghi lại khi phối lại và quan sát lợn nái","kanten_vi":"Mỗi lần phối, phối lại có ghi lại không, không chỉ dựa vào ngày dự sinh mà còn xem tình trạng lợn nái không.","levels_vi":["Quên sửa khi phối lại, chỉ dựa vào ngày dự sinh mà không xem tình trạng lợn nái.","Nếu được chỉ thị thì ghi lại, nhưng còn sót chỗ sửa và thiếu quan sát.","Nếu được chỉ thị thì ghi lại được mỗi lần phối, phối lại một cách cơ bản.","Dù không có chỉ thị vẫn luôn ghi lại khi phối lại, đồng thời xem tình trạng lợn nái.","Hiểu sót ghi lại sẽ gây rối loạn lịch, và có thể hướng dẫn người mới việc ghi chép và quan sát triệt để."],"name_id":"Menulis ulang saat kawin ulang dan mengamati induk babi","kanten_id":"Apakah menulis ulang setiap kali kawin atau kawin ulang, dan tidak menilai hanya dari tanggal perkiraan tetapi juga memeriksa keadaan induk babi?","levels_id":["Lupa memperbaiki catatan saat kawin ulang, menilai hanya dari tanggal perkiraan, dan tidak melihat keadaan induk babi.","Menulis ulang jika diperintah, tetapi masih ada lupa memperbaiki dan kurang mengamati.","Jika diperintah, dapat menulis ulang setiap kali kawin atau kawin ulang secara lengkap.","Tanpa diperintah pun, pasti menulis ulang saat kawin ulang, dan memeriksa keadaan induk babi sekaligus.","Memahami bahwa lupa menulis ulang mengacaukan jadwal, dan dapat mengajarkan kedisiplinan mencatat dan mengamati kepada karyawan baru."]},{"id":"date-verify","name":"カレンダーでの日付再確認","kanten":"計算した日付をカレンダーで指さし確認し、月またぎなどの1日ズレを防げるか。","levels":["計算しっぱなしで確認せず、月またぎの1日ズレに気づかず放置する。","指示があれば確認するが、指さし確認を省きがちでズレの見落としがある。","指示があればカレンダーで指さしして再確認し、早見表があれば優先して使える。","指示がなくても月またぎや31日がない月を意識して再確認し、ズレはその場で直す。","1日のズレが分娩準備を狂わせると理解し、再確認のやり方を新人に指導できる。"],"name_en":"Rechecking Dates on the Calendar","kanten_en":"Can they point-check the calculated date on a calendar and prevent one-day slips such as month boundaries?","levels_en":["Leaves the calculation unchecked and lets one-day slips at month boundaries go unnoticed.","With guidance checks, but tends to skip point-checking and overlooks slips.","With guidance can recheck by pointing on the calendar, using a quick-reference table first when available.","Independently rechecks mindful of month boundaries and months without a 31st, and fixes slips on the spot.","Understands that a one-day slip disrupts farrowing preparation, and can teach new staff how to recheck."],"name_vi":"Kiểm tra lại ngày trên lịch","kanten_vi":"Có chỉ tay kiểm tra lại ngày đã tính trên lịch, phòng lệch 1 ngày như khi sang tháng không.","levels_vi":["Tính xong không kiểm tra, lệch 1 ngày khi sang tháng cũng không nhận ra mà bỏ mặc.","Nếu được chỉ thị thì kiểm tra, nhưng hay bỏ qua việc chỉ tay xác nhận nên còn bỏ sót chỗ lệch.","Nếu được chỉ thị thì chỉ tay kiểm tra lại trên lịch, nếu có bảng tra nhanh thì ưu tiên dùng.","Dù không có chỉ thị vẫn chú ý khi sang tháng, tháng không có ngày 31 để kiểm tra lại, chỗ lệch thì sửa ngay tại chỗ.","Hiểu lệch 1 ngày sẽ làm rối việc chuẩn bị đẻ, và có thể hướng dẫn người mới cách kiểm tra lại."],"name_id":"Memeriksa ulang tanggal pada kalender","kanten_id":"Apakah memeriksa ulang tanggal hasil hitungan pada kalender sambil menunjuk, dan mencegah selisih satu hari seperti saat pergantian bulan?","levels_id":["Selesai menghitung tanpa memeriksa, dan tidak menyadari selisih satu hari saat pergantian bulan.","Memeriksa jika diperintah, tetapi cenderung melewatkan pemeriksaan sambil menunjuk sehingga selisih terlewat.","Jika diperintah, dapat memeriksa ulang pada kalender sambil menunjuk, dan mengutamakan tabel rujukan cepat bila ada.","Tanpa diperintah pun, memeriksa ulang dengan memperhatikan pergantian bulan dan bulan tanpa tanggal 31, serta memperbaiki selisih di tempat.","Memahami bahwa selisih satu hari mengacaukan persiapan melahirkan, dan dapat mengajarkan cara memeriksa ulang kepada karyawan baru."]},{"id":"board-plan","name":"予定表への記入と週単位の見える化","kanten":"予定表に母豚番号と予定日を書き、週ごとの分娩頭数と分娩舎への移動日まで見えるようにできるか。","levels":["母豚カードにしか書かず、予定表への記入も移動日の逆算もしない。","指示があれば予定表に書くが、記入漏れが多く週ごとの頭数が読み取れない。","指示があれば予定表に母豚番号と予定日を書き、移動日を逆算して記入できる。","指示がなくても週ごとの頭数が見える形に整え、移動日が休日や大きな作業と重ならないか確かめる。","週の頭数が舎と人手の計画の土台と理解し、予定表の作り方を新人に指導できる。"],"name_en":"Entering the Schedule Board and Weekly Visualization","kanten_en":"Can they write sow numbers and due dates on the schedule board, making weekly farrowing counts and the move date to the farrowing house visible?","levels_en":["Writes only on the sow card, with no schedule-board entry or back-calculated move date.","With guidance writes on the board, but misses many entries so weekly counts cannot be read.","With guidance can write sow numbers and due dates on the board and back-calculate and enter the move date.","Independently keeps weekly counts visible, and checks that move dates do not clash with holidays or major work.","Understands that weekly counts underpin housing and staffing plans, and can teach new staff how to build the schedule board."],"name_vi":"Ghi vào bảng kế hoạch và nhìn thấy theo tuần","kanten_vi":"Có ghi số lợn nái và ngày dự sinh vào bảng kế hoạch, làm cho thấy được số con đẻ theo tuần và cả ngày chuyển sang chuồng đẻ không.","levels_vi":["Chỉ ghi trên thẻ lợn nái, không ghi vào bảng kế hoạch, cũng không tính ngược ngày chuyển chuồng.","Nếu được chỉ thị thì ghi vào bảng, nhưng sót nhiều nên không đọc được số con theo tuần.","Nếu được chỉ thị thì ghi số lợn nái, ngày dự sinh vào bảng, tính ngược và ghi được ngày chuyển chuồng.","Dù không có chỉ thị vẫn sắp xếp để thấy được số con theo tuần, kiểm tra ngày chuyển có trùng ngày nghỉ hay việc lớn không.","Hiểu số con theo tuần là nền tảng kế hoạch chuồng và nhân lực, và có thể hướng dẫn người mới cách làm bảng kế hoạch."],"name_id":"Mengisi papan jadwal dan visualisasi per minggu","kanten_id":"Apakah dapat menulis nomor induk babi dan tanggal perkiraan pada papan jadwal, sehingga jumlah yang melahirkan per minggu dan tanggal pindah ke kandang melahirkan terlihat?","levels_id":["Hanya menulis di kartu induk babi, tidak mengisi papan jadwal dan tidak menghitung mundur tanggal pindah.","Menulis di papan jika diperintah, tetapi banyak yang terlewat sehingga jumlah per minggu tidak terbaca.","Jika diperintah, dapat menulis nomor induk babi dan tanggal perkiraan di papan, serta menghitung mundur dan mengisi tanggal pindah.","Tanpa diperintah pun, menata agar jumlah per minggu terlihat, dan memastikan tanggal pindah tidak bertabrakan dengan hari libur atau pekerjaan besar.","Memahami bahwa jumlah per minggu menjadi dasar rencana kandang dan tenaga kerja, dan dapat mengajarkan cara membuat papan jadwal kepada karyawan baru."]},{"id":"check-count","name":"鑑定日の記入と頭数突き合わせ","kanten":"再発情チェック・妊娠鑑定の日も予定表に書き、母豚カードと予定表の頭数を数えて突き合わせられるか。","levels":["鑑定日を書かず、頭数の突き合わせもせず、書きもれ・消しもれを放置する。","指示があれば書くが、鑑定日の記入や頭数照合に抜けが多く、不一致も他者まかせ。","指示があれば再発情チェック・妊娠鑑定の日を記入し、頭数を数えて突き合わせできる。","指示がなくても両方の頭数を合うまで確認し、不一致の原因（書きもれ・消しもれ）を自分で見つけて直す。","不受胎の早期発見につながる仕組みと理解し、鑑定日記入と突き合わせを新人に指導できる。"],"name_en":"Entering Check Dates and Matching Head Counts","kanten_en":"Can they also write return-to-estrus check and pregnancy check dates on the board, and count and match head counts between sow cards and the board?","levels_en":["Does not write check dates or match head counts, and leaves missed entries and missed erasures as they are.","With guidance writes, but often misses check-date entries and count matching, leaving mismatches to others.","With guidance can enter return-to-estrus check and pregnancy check dates and count and match the head counts.","Independently checks both counts until they match, and finds and fixes the causes of mismatches (missed entries or erasures) by themselves.","Understands this as a mechanism for early detection of failed conception, and can teach new staff check-date entry and matching."],"name_vi":"Ghi ngày kiểm tra và đối chiếu số đầu con","kanten_vi":"Có ghi cả ngày kiểm tra động dục lại, ngày khám thai vào bảng kế hoạch, đếm và đối chiếu số đầu con giữa thẻ lợn nái và bảng kế hoạch không.","levels_vi":["Không ghi ngày kiểm tra, không đối chiếu số đầu con, bỏ mặc chỗ sót ghi, sót xóa.","Nếu được chỉ thị thì ghi, nhưng còn nhiều sót về ghi ngày kiểm tra và đối chiếu số, chỗ không khớp thì phó mặc người khác.","Nếu được chỉ thị thì ghi được ngày kiểm tra động dục lại, ngày khám thai, đếm và đối chiếu số đầu con.","Dù không có chỉ thị vẫn xác nhận đến khi số hai bên khớp nhau, tự tìm ra và sửa nguyên nhân không khớp (sót ghi, sót xóa).","Hiểu đây là cơ chế giúp phát hiện sớm không thụ thai, và có thể hướng dẫn người mới việc ghi ngày kiểm tra và đối chiếu."],"name_id":"Mengisi tanggal pemeriksaan dan mencocokkan jumlah ekor","kanten_id":"Apakah juga menulis tanggal pemeriksaan birahi kembali dan pemeriksaan kebuntingan pada papan jadwal, serta menghitung dan mencocokkan jumlah ekor antara kartu induk babi dan papan jadwal?","levels_id":["Tidak menulis tanggal pemeriksaan, tidak mencocokkan jumlah ekor, dan membiarkan catatan yang terlewat atau lupa dihapus.","Menulis jika diperintah, tetapi banyak yang terlewat dalam mengisi tanggal pemeriksaan dan mencocokkan jumlah, dan ketidakcocokan diserahkan kepada orang lain.","Jika diperintah, dapat mengisi tanggal pemeriksaan birahi kembali dan pemeriksaan kebuntingan, serta menghitung dan mencocokkan jumlah ekor.","Tanpa diperintah pun, memastikan sampai jumlah keduanya cocok, dan menemukan serta memperbaiki sendiri penyebab ketidakcocokan (catatan terlewat atau lupa dihapus).","Memahami bahwa ini mekanisme untuk menemukan kegagalan bunting sejak dini, dan dapat mengajarkan pengisian tanggal pemeriksaan dan pencocokan kepada karyawan baru."]}],"name_en":"Farrowing Due-Date Entry","name_vi":"Ghi ngày dự sinh","name_id":"Mencatat perkiraan tanggal melahirkan","purposeShort_en":"Grasp farrowing timing to prepare housing and staff systematically and detect failed conception early","purposeShort_vi":"Nắm thời kỳ đẻ để chuẩn bị chuồng và nhân lực có kế hoạch, phát hiện sớm không thụ thai","purposeShort_id":"Mengetahui waktu melahirkan untuk menyiapkan kandang dan tenaga kerja secara terencana, serta menemukan kegagalan bunting sejak dini"},{"id":"cull-ship","category":"shipping","no":"No.22","name":"廃豚出荷（母豚出し）","purposeShort":"繁殖群を計画的に更新し、母豚に無理をさせず安全に出荷する","gyomu":"22","aspects":[{"id":"cull-select","name":"リスト照合とマーキング","kanten":"廃豚リストと耳標番号を上長と照合し、対象豚に見分けやすくマーキングして取り違えを防げるか。","levels":["リストと耳標を照合せずマーキングも曖昧で、対象外の豚と取り違えても気づかない。","指示があれば照合・マーキングするが、耳標の読み違いや印の不明瞭さが残り、確認は他者まかせ。","指示があればリストと耳標を1頭ずつ突き合わせ、背中に大きくはっきりマーキングできる。","指示がなくても上長とリストを確認してから照合・マーキングし、番号の不一致に気づけばその場で確かめる。","取り違え・誤出荷が起きやすい場面を理解し、照合とマーキングの手順を新人に指導できる。"],"name_en":"List Verification and Marking","name_vi":"Đối chiếu danh sách và đánh dấu","name_id":"Pencocokan daftar dan penandaan","kanten_en":"Can they verify the cull list against ear tag numbers with their supervisor, mark the target pigs clearly, and prevent mix-ups?","kanten_vi":"Có đối chiếu danh sách lợn loại thải và số thẻ tai với cấp trên, đánh dấu dễ nhận biết lên lợn cần xuất để phòng nhầm lẫn không.","kanten_id":"Apakah mencocokkan daftar babi afkir dan nomor tanda telinga bersama atasan, menandai babi sasaran agar mudah dibedakan, dan mencegah tertukar?","levels_en":["Does not verify the list against ear tags, marks vaguely, and does not notice even when a non-target pig is mixed up.","With guidance can verify and mark, but misreads ear tags or leaves unclear marks, and leaves checking to others.","With guidance can match the list and ear tags one pig at a time and mark the back large and clearly.","Independently confirms the list with the supervisor before verifying and marking, and checks any number mismatch on the spot.","Understands the situations where mix-ups and wrong shipments tend to occur, and can teach new staff the verification and marking procedure."],"levels_vi":["Không đối chiếu danh sách với thẻ tai, đánh dấu cũng mập mờ, lợn ngoài danh sách bị nhầm cũng không nhận ra.","Nếu được chỉ thị thì đối chiếu, đánh dấu, nhưng còn đọc nhầm thẻ tai, dấu không rõ, và phó mặc việc kiểm tra cho người khác.","Nếu được chỉ thị thì đối chiếu danh sách với thẻ tai từng con một, đánh dấu to và rõ lên lưng được.","Dù không có chỉ thị vẫn xác nhận danh sách với cấp trên rồi mới đối chiếu, đánh dấu; nhận thấy số không khớp thì kiểm tra ngay tại chỗ.","Hiểu những tình huống dễ xảy ra nhầm lẫn, xuất nhầm, và có thể hướng dẫn người mới trình tự đối chiếu và đánh dấu."],"levels_id":["Tidak mencocokkan daftar dengan tanda telinga, penandaan pun kabur, dan tidak sadar walau tertukar dengan babi di luar sasaran.","Mencocokkan dan menandai jika diperintah, tetapi masih salah baca tanda telinga atau tandanya tidak jelas, dan menyerahkan pengecekan kepada orang lain.","Jika diperintah, dapat mencocokkan daftar dan tanda telinga satu per satu ekor, lalu menandai punggung dengan besar dan jelas.","Tanpa diperintah pun, memastikan daftar bersama atasan sebelum mencocokkan dan menandai, dan jika menyadari nomor tidak cocok langsung memeriksanya di tempat.","Memahami situasi yang mudah menimbulkan tertukar atau salah kirim, dan dapat mengajarkan prosedur pencocokan dan penandaan kepada karyawan baru."]},{"id":"welfare-law","name":"歩様確認と法令遵守","kanten":"歩けない・立てない豚は出荷せず、出荷前に体調・歩様を確認し、絶食時も水を止めないか。","levels":["歩けない豚を出荷し、体調・歩様の確認も絶食時の給水も怠る。","指示があれば確認するが、歩様の見極めや給水管理に漏れがある。","指示があれば体調・歩様をひと通り確認して出荷できる。","指示がなくても歩けない豚を除外し、絶食時も水を止めずに安全に出荷する。","と畜場法・輸送指針を理解し、アニマルウェルフェアに配慮した出荷を新人に指導できる。"],"name_en":"Gait Checks and Legal Compliance","name_vi":"Kiểm tra dáng đi và tuân thủ pháp luật","name_id":"Memeriksa cara berjalan dan menaati peraturan","kanten_en":"Can they refuse to ship pigs that cannot walk or stand, check condition and gait before shipping, and keep water available during fasting?","kanten_vi":"Có không xuất lợn không đi được, không đứng được; trước khi xuất kiểm tra thể trạng, dáng đi; khi nhịn ăn không cắt nước không.","kanten_id":"Apakah tidak mengirim babi yang tidak bisa berjalan atau berdiri, memeriksa kondisi tubuh dan cara berjalan sebelum pengiriman, dan tidak menghentikan air minum saat puasa?","levels_en":["Ships pigs that cannot walk, and neglects condition and gait checks and water supply during fasting.","With guidance can check, but misses judging gait or managing water supply.","With guidance can check condition and gait and ship through the basic procedure.","Independently excludes pigs that cannot walk and ships safely with water kept available during fasting.","Understands the Slaughterhouse Act and transport guidelines, and can teach new staff welfare-conscious shipping."],"levels_vi":["Xuất cả lợn không đi được, lơ là kiểm tra thể trạng, dáng đi và cấp nước khi nhịn ăn.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về nhận biết dáng đi và quản lý cấp nước.","Nếu được chỉ thị thì kiểm tra thể trạng, dáng đi và xuất chuồng được cơ bản.","Dù không có chỉ thị vẫn loại trừ lợn không đi được, không cắt nước khi nhịn ăn, xuất chuồng an toàn.","Hiểu luật về lò mổ và hướng dẫn vận chuyển của Nhật Bản, và có thể hướng dẫn người mới cách xuất chuồng có quan tâm đến phúc lợi động vật (welfare)."],"levels_id":["Mengirim babi yang tidak bisa berjalan, dan lalai memeriksa kondisi tubuh dan cara berjalan serta memberi air minum saat puasa.","Memeriksa jika diperintah, tetapi sering lalai menilai cara berjalan dan mengelola air minum.","Jika diperintah, dapat memeriksa kondisi tubuh dan cara berjalan secara lengkap lalu mengirim.","Tanpa diperintah pun, menyisihkan babi yang tidak bisa berjalan, dan mengirim dengan aman tanpa menghentikan air minum saat puasa.","Memahami undang-undang rumah potong hewan dan pedoman pengangkutan, dan dapat mengajarkan pengiriman yang memperhatikan kesejahteraan hewan kepada karyawan baru."]},{"id":"withdrawal-double","name":"休薬期間のダブルチェック","kanten":"投薬記録を正本に、全対象豚の休薬期間経過を2人でダブルチェックし、「たぶん大丈夫」で出さないか。","levels":["投薬記録を見ずに「たぶん大丈夫」で出荷しようとし、休薬期間中の豚が混ざっても気づかない。","指示があれば記録を見るが、確認が1人だけになったり対象豚の一部を見落としたりする。","指示があれば投薬記録に基づき、全対象豚の休薬期間経過を2人で確認できる。","指示がなくてもダブルチェックを徹底し、記憶で決めず、疑わしい豚はその場で上長に確認して出荷から外す。","休薬期間中の出荷が法律違反であることを理解し、記録に基づくダブルチェックの方法を新人に指導できる。"],"name_en":"Double-Checking Withdrawal Periods","name_vi":"Hai người cùng kiểm tra thời gian ngừng thuốc","name_id":"Pengecekan ganda masa henti obat","kanten_en":"Can they use the medication records as the authoritative source, double-check with two people that all target pigs have passed their withdrawal periods, and never ship on a \"probably fine\"?","kanten_vi":"Có lấy sổ ghi chép dùng thuốc làm căn cứ chính, 2 người cùng kiểm tra kỹ rằng mọi con lợn cần xuất đã qua hết thời gian ngừng thuốc, không xuất theo kiểu \"chắc là ổn\" không.","kanten_id":"Apakah menjadikan catatan pemberian obat sebagai acuan resmi, melakukan pengecekan ganda oleh 2 orang bahwa semua babi sasaran sudah melewati masa henti obat, dan tidak mengirim dengan \"mungkin aman\"?","levels_en":["Tries to ship on a \"probably fine\" without looking at the medication records, and does not notice pigs still in withdrawal mixed in.","With guidance can look at the records, but the check ends up with one person only or misses some of the target pigs.","With guidance can confirm with two people, based on the medication records, that all target pigs have passed their withdrawal periods.","Independently enforces the double check, never decides from memory, and on the spot confirms doubtful pigs with the supervisor and excludes them from shipping.","Understands that shipping during the withdrawal period is against the law, and can teach new staff the record-based double-check method."],"levels_vi":["Định xuất chuồng theo kiểu \"chắc là ổn\" mà không xem sổ ghi chép dùng thuốc, lợn còn trong thời gian ngừng thuốc lẫn vào cũng không nhận ra.","Nếu được chỉ thị thì xem sổ ghi chép, nhưng có khi chỉ 1 người kiểm tra hoặc bỏ sót một phần lợn cần xuất.","Nếu được chỉ thị thì dựa vào sổ ghi chép dùng thuốc, 2 người cùng xác nhận được rằng mọi con lợn cần xuất đã qua hết thời gian ngừng thuốc.","Dù không có chỉ thị vẫn kiểm tra kỹ bằng 2 người, không quyết định theo trí nhớ; con đáng ngờ thì hỏi cấp trên ngay tại chỗ và loại khỏi danh sách xuất.","Hiểu rằng xuất chuồng lợn còn trong thời gian ngừng thuốc là vi phạm pháp luật, và có thể hướng dẫn người mới cách 2 người cùng kiểm tra dựa trên sổ ghi chép."],"levels_id":["Mencoba mengirim dengan \"mungkin aman\" tanpa melihat catatan pemberian obat, dan tidak sadar ada babi yang masih dalam masa henti obat ikut tercampur.","Melihat catatan jika diperintah, tetapi pengecekan kadang hanya oleh 1 orang atau melewatkan sebagian babi sasaran.","Jika diperintah, dapat memastikan oleh 2 orang berdasarkan catatan pemberian obat bahwa semua babi sasaran sudah melewati masa henti obat.","Tanpa diperintah pun, menjalankan pengecekan ganda dengan ketat, tidak memutuskan dari ingatan; babi yang meragukan langsung dikonfirmasi ke atasan di tempat dan dikeluarkan dari pengiriman.","Memahami bahwa mengirim babi dalam masa henti obat melanggar hukum, dan dapat mengajarkan cara pengecekan ganda berdasarkan catatan kepada karyawan baru."]},{"id":"fast-notify","name":"絶食開始と通路・積み込み場所の準備","kanten":"前日夕方の給餌停止で絶食を始め（目安は出荷12〜18時間前）、通路と積み込み場所の清掃・障害物や滑る場所の確認まで準備できるか。","levels":["絶食を始めず満腹のまま出荷させようとし、通路の準備もせずに豚を通す。","指示があれば準備するが、絶食開始の時期がずれたり、通路の障害物や滑る場所を見落としたりする。","指示があれば前日夕方に給餌を止め、通路と積み込み場所を清掃して仕切り板・追い込み板を用意できる。","指示がなくても出荷12〜18時間前を目安に絶食を管理し、通路を自分で歩いて滑りやすい所がないか確かめてから作業に入る。","絶食が輸送中の糞尿を減らし処理をスムーズにする理由を理解し、出荷前日の準備を新人に指導できる。"],"name_en":"Starting Fasting and Preparing the Aisle and Loading Area","name_vi":"Bắt đầu nhịn ăn và chuẩn bị lối đi, chỗ chất lợn lên xe","name_id":"Memulai puasa dan menyiapkan lorong serta tempat pemuatan","kanten_en":"Can they start fasting by stopping the evening feed the day before (guideline: 12-18 hours before shipping), and prepare through cleaning the aisle and loading area and checking for obstacles and slippery spots?","kanten_vi":"Có bắt đầu nhịn ăn bằng cách ngừng cho ăn bữa chiều hôm trước (khoảng 12〜18 tiếng trước khi xuất), và chuẩn bị đến cả việc dọn sạch lối đi, chỗ chất lợn lên xe, kiểm tra vật cản và chỗ trơn trượt không.","kanten_id":"Apakah memulai puasa dengan menghentikan pakan sore hari sebelumnya (patokan 12〜18 jam sebelum pengiriman), dan menyiapkan sampai membersihkan lorong dan tempat pemuatan serta memeriksa penghalang dan tempat licin?","levels_en":["Tries to ship pigs on a full stomach without starting fasting, and moves them through an unprepared aisle.","With guidance can prepare, but mistimes the start of fasting or overlooks obstacles and slippery spots in the aisle.","With guidance can stop feeding on the previous evening, clean the aisle and loading area, and set out partition boards and pig boards.","Independently manages fasting to the 12-18 hours-before-shipping guideline, and walks the aisle personally to check for slippery spots before starting work.","Understands why fasting reduces manure and urine during transport and smooths processing, and can teach new staff the day-before-shipping preparation."],"levels_vi":["Không cho nhịn ăn, định xuất lợn khi còn no, cho lợn đi qua lối đi chưa chuẩn bị gì.","Nếu được chỉ thị thì chuẩn bị, nhưng có khi lệch thời điểm bắt đầu nhịn ăn, hoặc bỏ sót vật cản và chỗ trơn trên lối đi.","Nếu được chỉ thị thì ngừng cho ăn chiều hôm trước, dọn sạch lối đi và chỗ chất lợn lên xe, chuẩn bị được tấm ngăn và tấm lùa.","Dù không có chỉ thị vẫn quản lý nhịn ăn theo mốc 12〜18 tiếng trước khi xuất, tự đi thử lối đi để kiểm tra chỗ trơn trượt rồi mới bắt đầu làm.","Hiểu lý do nhịn ăn giúp giảm phân và nước tiểu khi vận chuyển, giúp xử lý thuận lợi, và có thể hướng dẫn người mới việc chuẩn bị ngày trước khi xuất."],"levels_id":["Tidak memulai puasa dan mencoba mengirim babi dalam keadaan kenyang, serta melewatkan babi di lorong tanpa persiapan.","Menyiapkan jika diperintah, tetapi waktu mulai puasa meleset, atau melewatkan penghalang dan tempat licin di lorong.","Jika diperintah, dapat menghentikan pakan sore hari sebelumnya, membersihkan lorong dan tempat pemuatan, serta menyiapkan papan penyekat dan papan penggiring.","Tanpa diperintah pun, mengelola puasa dengan patokan 12〜18 jam sebelum pengiriman, dan berjalan sendiri menyusuri lorong untuk memeriksa tempat licin sebelum mulai bekerja.","Memahami alasan puasa mengurangi kotoran dan air seni saat pengangkutan serta memperlancar proses, dan dapat mengajarkan persiapan sehari sebelum pengiriman kepada karyawan baru."]},{"id":"load-verify-disinfect","name":"積み込み・頭数照合と出荷後消毒","kanten":"追い込み板で静かに積み込み、頭数・耳標を出荷伝票と照合して記録し、車両が触れた場所を消毒できるか。","levels":["豚を追い回して積み込み、頭数照合も出荷後の消毒もせず放置する。","指示があれば積み込むが、伝票との照合や車両が触れた場所の消毒に抜けが多い。","指示があれば静かに積み込み、頭数・耳標を伝票と照合し、通路と積み込み場所を消毒できる。","指示がなくても照合の不一致をその場で解消してから出発させ、記録と車両接触部の消毒まで自分で完結する。","出荷トラックが病気を持ち込むリスクを理解し、積み込みから消毒までの流れを新人に指導できる。"],"name_en":"Loading, Head-Count Verification, and Post-Shipping Disinfection","name_vi":"Chất lợn lên xe, đối chiếu số con và khử trùng sau xuất chuồng","name_id":"Pemuatan, pencocokan jumlah ekor, dan disinfeksi setelah pengiriman","kanten_en":"Can they load quietly with a pig board, verify head count and ear tags against the shipping slip and record them, and disinfect the places the vehicle touched?","kanten_vi":"Có dùng tấm lùa chất lợn lên xe nhẹ nhàng, đối chiếu số con và thẻ tai với phiếu xuất chuồng rồi ghi lại, khử trùng chỗ xe chạm vào không.","kanten_id":"Apakah memuat dengan tenang memakai papan penggiring, mencocokkan jumlah ekor dan tanda telinga dengan surat pengiriman lalu mencatatnya, dan mendisinfeksi tempat yang tersentuh kendaraan?","levels_en":["Chases pigs around while loading, and leaves the job without head-count verification or post-shipping disinfection.","With guidance can load, but often misses the check against the slip or the disinfection of places the vehicle touched.","With guidance can load quietly, verify head count and ear tags against the slip, and disinfect the aisle and loading area.","Independently resolves any verification mismatch on the spot before letting the truck leave, and completes the recording and the disinfection of vehicle-contact spots by themselves.","Understands the risk of the shipping truck bringing in disease, and can teach new staff the flow from loading to disinfection."],"levels_vi":["Rượt đuổi lợn khi chất lên xe, bỏ mặc không đối chiếu số con, không khử trùng sau khi xuất.","Nếu được chỉ thị thì chất lợn lên xe, nhưng còn nhiều thiếu sót về đối chiếu với phiếu và khử trùng chỗ xe chạm vào.","Nếu được chỉ thị thì chất lợn nhẹ nhàng, đối chiếu số con và thẻ tai với phiếu, khử trùng được lối đi và chỗ chất lợn lên xe.","Dù không có chỉ thị vẫn giải quyết chỗ không khớp ngay tại chỗ rồi mới cho xe đi, tự hoàn tất cả việc ghi chép và khử trùng chỗ xe chạm vào.","Hiểu rủi ro xe xuất chuồng mang mầm bệnh vào trại, và có thể hướng dẫn người mới quy trình từ chất lợn lên xe đến khử trùng."],"levels_id":["Mengejar-ngejar babi saat memuat, dan meninggalkan pekerjaan tanpa mencocokkan jumlah ekor maupun disinfeksi setelah pengiriman.","Memuat jika diperintah, tetapi sering lalai mencocokkan dengan surat pengiriman dan mendisinfeksi tempat yang tersentuh kendaraan.","Jika diperintah, dapat memuat dengan tenang, mencocokkan jumlah ekor dan tanda telinga dengan surat pengiriman, serta mendisinfeksi lorong dan tempat pemuatan.","Tanpa diperintah pun, menyelesaikan ketidakcocokan hasil pencocokan di tempat sebelum truk berangkat, dan menuntaskan sendiri pencatatan serta disinfeksi bagian yang tersentuh kendaraan.","Memahami risiko truk pengiriman membawa masuk penyakit, dan dapat mengajarkan alur dari pemuatan sampai disinfeksi kepada karyawan baru."]}],"name_en":"Cull Sow Shipping","name_vi":"Xuất chuồng lợn loại thải (đưa lợn nái đi)","name_id":"Pengiriman babi afkir (mengeluarkan induk babi)","purposeShort_en":"Renew the breeding herd systematically and ship sows safely without overstraining them","purposeShort_vi":"Đổi mới đàn sinh sản có kế hoạch, xuất chuồng an toàn không ép lợn nái quá sức","purposeShort_id":"Memperbarui kelompok induk secara terencana, dan mengirim dengan aman tanpa memaksa induk babi"},{"id":"cull-move","category":"shipping","no":"No.23","name":"育成舎へ廃豚移動","purposeShort":"出荷前管理を円滑にする","gyomu":"23","aspects":[{"id":"move-pre-check","name":"移動前の照合と歩様確認","kanten":"耳標をリストと照合し、1頭ずつ立たせて歩様を見て、歩けない・呼吸が荒い豚を移動から外し報告できるか。","levels":["照合も歩様確認もせずに追い始め、歩けない豚を無理に動かして放置する。","指示があれば確認するが、耳標の照合や歩様の見極めに漏れがあり、報告は他者まかせ。","指示があればリストと1頭ずつ照合し、歩様を確認して異常な豚を移動から外し報告できる。","指示がなくても移動前の確認を徹底し、治療中・休薬期間中の豚が混ざっていないかも指導係と確認する。","歩けない豚を動かす危険と出荷できない理由を理解し、移動前確認のやり方を新人に指導できる。"],"name_en":"Pre-Move Verification and Gait Checks","name_vi":"Đối chiếu và kiểm tra dáng đi trước khi chuyển","name_id":"Pencocokan dan pemeriksaan cara berjalan sebelum pemindahan","kanten_en":"Can they verify ear tags against the list, stand each pig up to check its gait, and exclude pigs that cannot walk or are breathing hard from the move and report them?","kanten_vi":"Có đối chiếu thẻ tai với danh sách, cho từng con đứng dậy để xem dáng đi, loại con không đi được hoặc thở gấp khỏi việc di chuyển và báo cáo không.","kanten_id":"Apakah mencocokkan tanda telinga dengan daftar, membuat setiap babi berdiri untuk melihat cara jalannya, mengeluarkan babi yang tidak bisa berjalan atau napasnya cepat dari pemindahan, dan melaporkannya?","levels_en":["Starts driving pigs without verification or gait checks, forces pigs that cannot walk to move, and leaves them.","With guidance can check, but misses ear-tag verification or judging gait, and leaves reporting to others.","With guidance can verify against the list one pig at a time, check gait, and exclude and report abnormal pigs.","Independently enforces pre-move checks, and also confirms with the trainer that no pigs under treatment or in withdrawal are mixed in.","Understands the danger of moving pigs that cannot walk and why they cannot be shipped, and can teach new staff the pre-move check."],"levels_vi":["Bắt đầu lùa mà không đối chiếu, không kiểm tra dáng đi, ép con lợn không đi được phải di chuyển rồi bỏ mặc.","Nếu được chỉ thị thì kiểm tra, nhưng còn thiếu sót về đối chiếu thẻ tai và nhận biết dáng đi, phó mặc việc báo cáo cho người khác.","Nếu được chỉ thị thì đối chiếu với danh sách từng con một, kiểm tra dáng đi, loại con bất thường khỏi việc di chuyển và báo cáo được.","Dù không có chỉ thị vẫn kiểm tra kỹ trước khi chuyển, và xác nhận với người hướng dẫn xem có lẫn lợn đang điều trị hoặc đang trong thời gian ngừng thuốc không.","Hiểu nguy hiểm khi bắt lợn không đi được phải di chuyển và lý do không thể xuất chuồng, và có thể hướng dẫn người mới cách kiểm tra trước khi chuyển."],"levels_id":["Mulai menggiring tanpa pencocokan maupun pemeriksaan cara berjalan, memaksa babi yang tidak bisa berjalan untuk pindah, lalu membiarkannya.","Memeriksa jika diperintah, tetapi masih lalai mencocokkan tanda telinga dan menilai cara berjalan, serta menyerahkan pelaporan kepada orang lain.","Jika diperintah, dapat mencocokkan dengan daftar satu per satu ekor, memeriksa cara berjalan, lalu mengeluarkan babi yang abnormal dari pemindahan dan melaporkannya.","Tanpa diperintah pun, menjalankan pemeriksaan sebelum pemindahan dengan ketat, dan juga memastikan bersama pembimbing bahwa tidak ada babi yang sedang diobati atau dalam masa henti obat ikut tercampur.","Memahami bahaya memindahkan babi yang tidak bisa berjalan dan alasan babi itu tidak boleh dikirim, dan dapat mengajarkan cara pemeriksaan sebelum pemindahan kepada karyawan baru."]},{"id":"route-setup","name":"移動ルートと受け入れ豚房の準備","kanten":"受け入れ豚房の空きと給水を確かめ、扉・ゲートで一本道を作り、通路の障害物・滑る場所を先に片付けられるか。","levels":["準備をせずに追い始め、豚が抜け出したり滑って転んだりしても気にしない。","指示があれば準備するが、扉の閉め忘れや滑る場所の見落としが多い。","指示があれば扉・ゲートを先に全部セットし、障害物と滑る場所を片付けてから豚を通せる。","指示がなくても受け入れ豚房の空きと給水まで確かめ、ルートを自分で歩いて危険箇所を先に直す。","転倒・脱走が起きやすい箇所を理解し、ルート準備の段取りを新人に指導できる。"],"name_en":"Preparing the Route and the Receiving Pen","name_vi":"Chuẩn bị đường di chuyển và ô chuồng tiếp nhận","name_id":"Menyiapkan rute pemindahan dan petak kandang penerima","kanten_en":"Can they confirm the receiving pen is empty with water flowing, make a single path with doors and gates, and clear obstacles and slippery spots in the aisle beforehand?","kanten_vi":"Có kiểm tra ô chuồng tiếp nhận còn trống và nước uống chảy tốt, dùng cửa và cổng tạo thành đường một chiều, dọn trước vật cản và chỗ trơn trên lối đi không.","kanten_id":"Apakah memastikan petak kandang penerima kosong dan air minum mengalir, membuat jalur satu arah dengan pintu dan gerbang, serta membereskan lebih dulu penghalang dan tempat licin di lorong?","levels_en":["Starts driving pigs without preparation, and does not care when pigs escape or slip and fall.","With guidance can prepare, but often forgets to close doors or overlooks slippery spots.","With guidance can set all doors and gates first and clear obstacles and slippery spots before moving pigs through.","Independently confirms the receiving pen's vacancy and water supply, and walks the route personally to fix hazard spots beforehand.","Understands the spots where falls and escapes tend to occur, and can teach new staff how to set up the route."],"levels_vi":["Bắt đầu lùa mà không chuẩn bị, lợn xổng ra hay trượt ngã cũng không quan tâm.","Nếu được chỉ thị thì chuẩn bị, nhưng hay quên đóng cửa và bỏ sót chỗ trơn.","Nếu được chỉ thị thì cài đặt trước tất cả cửa và cổng, dọn vật cản và chỗ trơn rồi mới cho lợn đi qua được.","Dù không có chỉ thị vẫn kiểm tra đến cả ô chuồng tiếp nhận còn trống và nước uống, tự đi thử đường di chuyển để sửa trước chỗ nguy hiểm.","Hiểu những chỗ dễ xảy ra ngã và xổng chuồng, và có thể hướng dẫn người mới cách sắp xếp chuẩn bị đường di chuyển."],"levels_id":["Mulai menggiring tanpa persiapan, dan tidak peduli walau babi lolos atau terpeleset dan jatuh.","Menyiapkan jika diperintah, tetapi sering lupa menutup pintu dan melewatkan tempat licin.","Jika diperintah, dapat mengatur dulu semua pintu dan gerbang, membereskan penghalang dan tempat licin, baru melewatkan babi.","Tanpa diperintah pun, memastikan sampai kekosongan petak kandang penerima dan air minumnya, serta berjalan sendiri menyusuri rute untuk memperbaiki titik berbahaya lebih dulu.","Memahami titik-titik yang mudah menimbulkan babi jatuh atau lolos, dan dapat mengajarkan urutan penyiapan rute kepada karyawan baru."]},{"id":"drive-safety","name":"追い板の使い方と自身の安全確保","kanten":"追い板で後ろ斜めから3〜5頭ずつ静かに追い、興奮したら待ち、自分の逃げ道を常に確保できるか。","levels":["叩く・大声・追い回しで豚を暴れさせ、壁際に立って挟まれそうになっても気づかない。","指示があれば追い板を使うが、一度に動かす頭数が多すぎたり、立ち位置が危なかったりする。","指示があれば3〜5頭ずつ静かに追い、逃げ道を確保した立ち位置で移動できる。","指示がなくても豚が興奮したら無理せず10〜15分待って再開し、突進には追い板を盾にして安全によける。","豚の視界をさえぎって方向をつくる原理を理解し、安全な追い方を新人に指導できる。"],"name_en":"Using the Pig Board and Keeping Yourself Safe","name_vi":"Cách dùng tấm chắn lùa lợn và bảo đảm an toàn cho bản thân","name_id":"Cara memakai papan penggiring dan menjaga keselamatan diri","kanten_en":"Can they drive pigs quietly with the pig board from diagonally behind, 3-5 at a time, wait when pigs get agitated, and always keep an escape route for themselves?","kanten_vi":"Có dùng tấm chắn lùa nhẹ nhàng từng 3〜5 con từ phía sau chếch bên hông, lợn kích động thì chờ, và luôn giữ đường thoát cho bản thân không.","kanten_id":"Apakah menggiring dengan tenang 3〜5 ekor sekali jalan memakai papan penggiring dari belakang agak menyamping, menunggu jika babi panik, dan selalu menjaga jalur keluar untuk diri sendiri?","levels_en":["Makes pigs panic by hitting, shouting, and chasing, and stands against the wall without noticing they are about to be pinned.","With guidance can use the pig board, but moves too many pigs at once or stands in dangerous positions.","With guidance can drive pigs quietly 3-5 at a time, standing where an escape route is secured.","Independently waits 10-15 minutes without forcing when pigs get agitated before resuming, and safely dodges charges using the pig board as a shield.","Understands the principle of blocking the pig's view to create direction, and can teach new staff safe driving."],"levels_vi":["Đánh, la lớn, rượt đuổi làm lợn hoảng loạn, đứng sát tường sắp bị kẹp cũng không nhận ra.","Nếu được chỉ thị thì dùng tấm chắn, nhưng có khi lùa một lần quá nhiều con, hoặc đứng ở vị trí nguy hiểm.","Nếu được chỉ thị thì lùa nhẹ nhàng từng 3〜5 con, di chuyển ở vị trí đứng có giữ đường thoát.","Dù không có chỉ thị vẫn không ép khi lợn kích động, chờ 10〜15 phút rồi mới tiếp tục; lợn lao tới thì dùng tấm chắn làm khiên né an toàn.","Hiểu nguyên lý che tầm nhìn của lợn để tạo hướng đi, và có thể hướng dẫn người mới cách lùa an toàn."],"levels_id":["Membuat babi mengamuk dengan memukul, berteriak, dan mengejar-ngejar, serta berdiri rapat ke dinding tanpa sadar hampir terjepit.","Memakai papan penggiring jika diperintah, tetapi kadang memindahkan terlalu banyak ekor sekaligus atau posisi berdirinya berbahaya.","Jika diperintah, dapat menggiring dengan tenang 3〜5 ekor sekali jalan, pada posisi berdiri yang menjaga jalur keluar.","Tanpa diperintah pun, saat babi panik tidak memaksa, menunggu 10〜15 menit lalu melanjutkan; jika diseruduk, menghindar dengan aman memakai papan penggiring sebagai perisai.","Memahami prinsip menutupi pandangan babi untuk mengarahkan jalannya, dan dapat mengajarkan cara menggiring yang aman kepada karyawan baru."]},{"id":"isolation-move","name":"他群との接触回避（隔離）","kanten":"廃豚を他群と接触させず、柵ごしに鼻が触れ合わない空き豚房を選び、感染を広げない移動ができるか。","levels":["他群と鼻が触れ合う豚房に平気で入れ、廃豚を他の群のそばに置いても気にしない。","指示があれば他群から離すが、柵ごしの鼻の接触までは意識が回らない。","指示があれば他の豚と柵ごしに鼻が触れ合わない空き豚房を選び、他群と接触させずに移動できる。","指示がなくても移動の時間帯（夕方〜夜はけんかが減る）など農場の決まりを確かめて動き、接触の恐れがあれば先に指導係に相談する。","柵ごしの接触や共用通路の糞が感染拡大のもとになることを理解し、廃豚の隔離の考え方を新人に指導できる。"],"name_en":"Avoiding Contact with Other Groups (Isolation)","name_vi":"Tránh tiếp xúc với nhóm khác (cách ly)","name_id":"Menghindari kontak dengan kelompok lain (isolasi)","kanten_en":"Can they keep cull sows from contacting other groups, choose an empty pen where noses cannot touch through the fence, and move without spreading infection?","kanten_vi":"Có không để lợn loại thải tiếp xúc với nhóm khác, chọn ô chuồng trống nơi mũi không chạm nhau qua hàng rào, di chuyển mà không làm lây lan bệnh không.","kanten_id":"Apakah tidak membiarkan babi afkir kontak dengan kelompok lain, memilih petak kandang kosong yang hidungnya tidak bisa saling bersentuhan lewat pagar, dan memindahkan tanpa menyebarkan penyakit?","levels_en":["Casually puts pigs into pens where noses touch other groups, and does not care about leaving cull sows near other groups.","With guidance can keep them away from other groups, but does not think as far as nose contact through the fence.","With guidance can choose an empty pen where noses cannot touch other pigs through the fence and move without contact with other groups.","Independently checks farm rules such as the moving time slot (fights decrease from evening to night) before acting, and consults the trainer first when contact seems possible.","Understands that contact through fences and manure in shared aisles can spread infection, and can teach new staff the thinking behind cull-sow isolation."],"levels_vi":["Thản nhiên cho lợn vào ô chuồng nơi mũi chạm với nhóm khác, đặt lợn loại thải cạnh đàn khác cũng không quan tâm.","Nếu được chỉ thị thì tách khỏi nhóm khác, nhưng chưa để ý đến việc chạm mũi qua hàng rào.","Nếu được chỉ thị thì chọn ô chuồng trống nơi mũi không chạm với lợn khác qua hàng rào, di chuyển được mà không cho tiếp xúc với nhóm khác.","Dù không có chỉ thị vẫn kiểm tra quy định của trại như khung giờ di chuyển (chiều tối〜ban đêm ít đánh nhau) rồi mới làm; nếu e ngại có tiếp xúc thì hỏi ý kiến người hướng dẫn trước.","Hiểu rằng chạm nhau qua hàng rào và phân trên lối đi chung là nguồn lây lan bệnh, và có thể hướng dẫn người mới cách suy nghĩ về cách ly lợn loại thải."],"levels_id":["Dengan santai memasukkan babi ke petak yang hidungnya bisa bersentuhan dengan kelompok lain, dan tidak peduli menempatkan babi afkir di dekat kelompok lain.","Menjauhkan dari kelompok lain jika diperintah, tetapi belum memikirkan sampai sentuhan hidung lewat pagar.","Jika diperintah, dapat memilih petak kandang kosong yang hidungnya tidak bersentuhan dengan babi lain lewat pagar, dan memindahkan tanpa kontak dengan kelompok lain.","Tanpa diperintah pun, memastikan aturan peternakan seperti waktu pemindahan (sore〜malam perkelahian berkurang) sebelum bertindak, dan jika ada risiko kontak, berkonsultasi dulu dengan pembimbing.","Memahami bahwa sentuhan lewat pagar dan kotoran di lorong bersama menjadi sumber penyebaran penyakit, dan dapat mengajarkan cara berpikir isolasi babi afkir kepada karyawan baru."]},{"id":"finish-record-disinfect","name":"収容後の確認・記録と消毒","kanten":"扉を確実に閉めて給水を確かめ、耳標・頭数をその場で記録し、通路清掃と追い板・長靴の消毒までできるか。","levels":["扉や給水を確かめず、記録も残さず、通路の糞や使った追い板もそのまま放置する。","指示があれば行うが、ニップル給水の確認や消毒に抜けが多く、記録も後回しにする。","指示があれば扉・給水を確認し、耳標・頭数をその場で記録し、追い板と長靴を消毒できる。","指示がなくても記録をリストと照合して数を合わせ、通路の清掃・消毒までを移動作業の一部として完結する。","廃豚から他群へ病気が広がる経路を理解し、収容後の確認から消毒までの流れを新人に指導できる。"],"name_en":"Post-Housing Checks, Recording, and Disinfection","name_vi":"Kiểm tra, ghi chép và khử trùng sau khi đưa lợn vào chuồng","name_id":"Pemeriksaan, pencatatan, dan disinfeksi setelah babi masuk kandang","kanten_en":"Can they close the door securely, check the water supply, record ear tags and head count on the spot, and follow through with aisle cleaning and disinfecting the pig board and boots?","kanten_vi":"Có đóng chặt cửa, kiểm tra nước uống, ghi ngay tại chỗ số thẻ tai và số con, làm đến cả việc quét dọn lối đi và khử trùng tấm chắn, ủng không.","kanten_id":"Apakah menutup pintu dengan rapat, memeriksa air minum, mencatat tanda telinga dan jumlah ekor di tempat, serta menuntaskan pembersihan lorong dan disinfeksi papan penggiring serta sepatu bot?","levels_en":["Does not check the door or water supply, leaves no records, and abandons the manure in the aisle and the used pig board as they are.","With guidance can do the work, but often misses checking the nipple drinker or disinfecting, and puts off recording.","With guidance can check the door and water supply, record ear tags and head count on the spot, and disinfect the pig board and boots.","Independently verifies records against the list to match the numbers, and completes aisle cleaning and disinfection as part of the moving job.","Understands the routes by which disease spreads from cull sows to other groups, and can teach new staff the flow from post-housing checks to disinfection."],"levels_vi":["Không kiểm tra cửa và nước uống, không ghi chép, bỏ mặc phân trên lối đi và tấm chắn đã dùng.","Nếu được chỉ thị thì làm, nhưng còn nhiều thiếu sót về kiểm tra núm uống và khử trùng, việc ghi chép cũng để sau.","Nếu được chỉ thị thì kiểm tra cửa và nước uống, ghi ngay tại chỗ số thẻ tai và số con, khử trùng được tấm chắn và ủng.","Dù không có chỉ thị vẫn đối chiếu ghi chép với danh sách để khớp số, hoàn tất cả việc quét dọn và khử trùng lối đi như một phần của công việc di chuyển.","Hiểu đường lây bệnh từ lợn loại thải sang các đàn khác, và có thể hướng dẫn người mới quy trình từ kiểm tra sau khi vào chuồng đến khử trùng."],"levels_id":["Tidak memeriksa pintu dan air minum, tidak meninggalkan catatan, dan membiarkan begitu saja kotoran di lorong serta papan penggiring yang dipakai.","Melakukannya jika diperintah, tetapi sering lalai memeriksa nipel air minum dan mendisinfeksi, serta menunda pencatatan.","Jika diperintah, dapat memeriksa pintu dan air minum, mencatat tanda telinga dan jumlah ekor di tempat, serta mendisinfeksi papan penggiring dan sepatu bot.","Tanpa diperintah pun, mencocokkan catatan dengan daftar agar jumlahnya sesuai, dan menuntaskan pembersihan serta disinfeksi lorong sebagai bagian dari pekerjaan pemindahan.","Memahami jalur penyebaran penyakit dari babi afkir ke kelompok lain, dan dapat mengajarkan alur dari pemeriksaan setelah masuk kandang sampai disinfeksi kepada karyawan baru."]}],"name_en":"Moving Cull Sows to the Grower House","name_vi":"Chuyển lợn loại thải sang chuồng lợn choai","name_id":"Memindahkan babi afkir ke kandang grower","purposeShort_en":"Keep pre-shipping management running smoothly","purposeShort_vi":"Giúp việc quản lý trước xuất chuồng thuận lợi","purposeShort_id":"Melancarkan pengelolaan sebelum pengiriman"},{"id":"body-measure","category":"shipping","no":"","name":"体測","purposeShort":"肥育豚の体重を正しく測り、出荷の適期と群の発育のばらつきを把握する","gyomu":"","aspects":[{"id":"scale-prep","name":"体重計の設置とゼロ点・道具の準備","kanten":"体重計（台秤）を平らな場所に置いてゼロ点を確かめ、追い板・記録用紙・マーキングスプレーをそろえてから測り始められるか。","levels":["体重計を傾いた場所に置き、ゼロ点も見ず道具も不足したまま測り始める。","指示があれば設置するが、ゼロ点の確認や道具のそろえ忘れが多く、校正は他者まかせ。","指示があれば平らな場所に設置してゼロ点を確認し、追い板・記録用紙・スプレーをそろえて測り始められる。","指示がなくても測る前に設置場所とゼロ点を確かめ、道具を整え、校正が必要そうなら上長に伝える。","体重計がずれると出荷判断や増体の計算まで狂うことを理解し、設置とゼロ点確認の手順を新人に指導できる。"],"name_en":"Setting up the scale, zeroing, and preparing tools","name_vi":"Đặt cân, chỉnh về 0 và chuẩn bị dụng cụ","name_id":"Pemasangan timbangan, titik nol, dan persiapan alat","kanten_en":"Can they place the scale (platform scale) on a flat spot, check the zero point, and gather the pig board, record sheet, and marking spray before starting to weigh?","kanten_vi":"Có đặt cân (cân bàn) ở chỗ bằng phẳng, kiểm tra điểm 0, chuẩn bị đủ tấm chắn, giấy ghi chép, bình xịt đánh dấu rồi mới bắt đầu cân không.","kanten_id":"Apakah menaruh timbangan (timbangan lantai) di tempat datar, memeriksa titik nol, dan menyiapkan papan penggiring, lembar catatan, serta semprotan penanda sebelum mulai menimbang.","levels_en":["Places the scale on a sloping spot and starts weighing without checking zero and with tools missing.","With guidance, sets it up, but often forgets the zero check and tools, and leaves calibration to others.","With guidance, sets the scale on a flat place, checks zero, and can start weighing with the pig board, record sheet, and spray ready.","Independently checks the location and zero before weighing, gets the tools ready, and tells the supervisor if calibration seems necessary.","Understands that a shifted scale throws off shipping decisions and gain calculations, and can teach new staff the setup and zero-check procedure."],"levels_vi":["Đặt cân ở chỗ nghiêng, không xem điểm 0, dụng cụ còn thiếu vẫn bắt đầu cân.","Nếu có chỉ dẫn thì đặt cân, nhưng hay quên kiểm tra điểm 0 và chuẩn bị dụng cụ, việc hiệu chuẩn phó mặc cho người khác.","Nếu có chỉ dẫn thì đặt cân ở chỗ bằng phẳng, kiểm tra điểm 0, chuẩn bị đủ tấm chắn, giấy ghi chép, bình xịt rồi bắt đầu cân được.","Không cần chỉ dẫn cũng kiểm tra chỗ đặt và điểm 0 trước khi cân, chuẩn bị dụng cụ, nếu thấy có vẻ cần hiệu chuẩn thì báo cấp trên.","Hiểu cân bị lệch sẽ làm sai cả quyết định xuất chuồng và tính tăng trọng, và có thể hướng dẫn người mới trình tự đặt cân và kiểm tra điểm 0."],"levels_id":["Menaruh timbangan di tempat miring, tidak melihat titik nol, dan mulai menimbang dengan alat yang kurang.","Jika ada instruksi bisa memasang, tetapi sering lupa memeriksa titik nol dan melengkapi alat, dan kalibrasi diserahkan ke orang lain.","Jika ada instruksi, bisa memasang di tempat datar, memeriksa titik nol, dan mulai menimbang dengan papan penggiring, lembar catatan, dan semprotan sudah siap.","Tanpa instruksi pun, memeriksa tempat dan titik nol sebelum menimbang, menyiapkan alat, dan memberi tahu atasan jika tampaknya perlu dikalibrasi.","Memahami bahwa timbangan yang bergeser mengacaukan keputusan pengiriman dan perhitungan pertambahan berat, dan bisa mengajari karyawan baru urutan pemasangan dan pemeriksaan titik nol."]},{"id":"calm-handling","name":"豚の誘導と扱い（ストレス・けが防止）","kanten":"追い板で静かに誘導し、追い回さず無理に押し込まずに体重計へ乗せ、豚にも自分にもけがをさせず測れるか。","levels":["大声で追い回し、無理に押し込んで豚を興奮させ、豚や自分にけがをさせかねない扱いをする。","指示があれば静かに誘導するが、焦ると追い回したり押し込んだりして、通路や追い板の使い方にムラがある。","指示があれば追い板で誘導し、体重計に静かに乗せて、落ち着いてから測り、静かに出せる。","指示がなくても豚が興奮したら一度待ち、通路の障害物を除いて、豚にも自分にもけがが出ない位置で誘導する。","体重測定が豚にとってストレスであることを理解し、静かに扱うコツと安全な立ち位置を新人に指導できる。"],"name_en":"Guiding and handling the pigs (preventing stress and injury)","name_vi":"Lùa và xử lý lợn (phòng căng thẳng và chấn thương)","name_id":"Penggiringan dan penanganan babi (mencegah stres dan cedera)","kanten_en":"Can they guide pigs quietly with the pig board, put them on the scale without chasing or forcing, and weigh without injuring the pigs or themselves?","kanten_vi":"Có lùa lợn nhẹ nhàng bằng tấm chắn, đưa lên cân mà không đuổi hay ép mạnh, cân mà không làm lợn và bản thân bị thương không.","kanten_id":"Apakah menggiring babi dengan tenang memakai papan penggiring, menaikkannya ke timbangan tanpa mengejar atau memaksa, dan menimbang tanpa melukai babi maupun diri sendiri.","levels_en":["Chases with shouting, forces pigs in and excites them, and handles them in ways that could injure the pigs or themselves.","With guidance, guides quietly, but when rushed chases or pushes them in, and use of passages and the pig board is uneven.","With guidance, guides with the pig board, puts the pig quietly on the scale, weighs once it settles, and lets it out quietly.","Independently waits when a pig gets excited, clears obstacles from the passage, and guides from a position where neither the pig nor they get hurt.","Understands that weighing is stressful for pigs, and can teach new staff how to handle them quietly and safe positioning."],"levels_vi":["La to đuổi lợn, ép mạnh làm lợn bị kích động, xử lý theo cách có thể làm lợn và bản thân bị thương.","Nếu có chỉ dẫn thì lùa nhẹ nhàng, nhưng khi vội thì đuổi hay ép lợn vào, cách dùng lối đi và tấm chắn không đều.","Nếu có chỉ dẫn thì lùa bằng tấm chắn, đưa lợn lên cân nhẹ nhàng, chờ lợn yên rồi mới cân và cho ra nhẹ nhàng được.","Không cần chỉ dẫn cũng chờ một lúc khi lợn bị kích động, dọn vật cản ở lối đi, và lùa ở vị trí để cả lợn và mình không bị thương.","Hiểu việc cân là căng thẳng với lợn, và có thể hướng dẫn người mới mẹo xử lý nhẹ nhàng và vị trí đứng an toàn."],"levels_id":["Mengejar sambil berteriak, memaksa babi masuk sehingga gelisah, dan menangani dengan cara yang bisa melukai babi atau diri sendiri.","Jika ada instruksi bisa menggiring dengan tenang, tetapi saat terburu-buru mengejar atau mendorong paksa, dan cara memakai lorong dan papan penggiring tidak merata.","Jika ada instruksi, bisa menggiring dengan papan penggiring, menaikkan babi ke timbangan dengan tenang, menimbang setelah tenang, dan mengeluarkannya dengan tenang.","Tanpa instruksi pun, menunggu dulu saat babi gelisah, menyingkirkan penghalang di lorong, dan menggiring dari posisi yang tidak melukai babi maupun diri sendiri.","Memahami bahwa penimbangan membuat babi stres, dan bisa mengajari karyawan baru trik menangani dengan tenang dan posisi berdiri yang aman."]},{"id":"weigh-estimate","name":"計測と推定メジャー・目視推定の使い分け","kanten":"動かなくなってから体重計の数値を読み、体重計がない時は胸囲と体長のメジャーによる推定を目安として使い分けられるか。","levels":["豚が動いている最中に数値を読み、体重計があっても目視だけで決めて、推定値を正確な体重のように扱う。","指示があれば測るが、読むタイミングがばらつき、推定メジャーの当て方も不確か。","指示があれば豚が動かなくなったところで数値を読み、体重計がなければ胸囲と体長を測って目安の体重を出せる。","指示がなくても測る前に目視で体重を予想して実測と比べ、メジャー推定はあくまで目安として出荷の最終判断には体重計の値を使う。","目視・メジャー推定・実測の精度の違いを理解し、使い分けと目視推定の上達のコツを新人に指導できる。"],"name_en":"Weighing, and choosing between the tape estimate and visual estimate","name_vi":"Cân và phân biệt dùng thước đo ước lượng và ước lượng bằng mắt","name_id":"Penimbangan, serta memilih antara taksiran pita ukur dan taksiran visual","kanten_en":"Can they read the scale once the pig stops moving, and when there is no scale use a girth-and-length tape estimate as a rough guide, choosing between methods appropriately?","kanten_vi":"Có đọc số trên cân khi lợn đã đứng yên, và khi không có cân thì dùng thước đo vòng ngực và chiều dài thân để ước lượng làm mức tham khảo, biết dùng phù hợp từng cách không.","kanten_id":"Apakah membaca angka timbangan setelah babi diam, dan bila tidak ada timbangan memakai taksiran pita ukur lingkar dada dan panjang badan sebagai acuan, serta menggunakannya dengan tepat.","levels_en":["Reads the number while the pig is still moving, decides by eye alone even when a scale is available, and treats an estimate as an exact weight.","With guidance, weighs, but the timing of reading varies and how to place the estimating tape is uncertain.","With guidance, reads the number when the pig stops moving, and without a scale can measure girth and length to get a rough weight.","Independently guesses the weight by eye before weighing and compares with the measured value, treats the tape estimate only as a guide, and uses the scale value for final shipping decisions.","Understands the differences in accuracy of visual estimate, tape estimate, and actual weighing, and can teach new staff how to choose among them and tips for improving visual estimation."],"levels_vi":["Đọc số khi lợn còn đang cử động, có cân mà vẫn chỉ quyết định bằng mắt, coi số ước lượng như cân nặng chính xác.","Nếu có chỉ dẫn thì cân, nhưng lúc đọc số không đều, cách đặt thước đo ước lượng cũng không chắc.","Nếu có chỉ dẫn thì đọc số khi lợn đứng yên, không có cân thì đo vòng ngực và chiều dài thân để ra cân nặng tham khảo được.","Không cần chỉ dẫn cũng đoán cân nặng bằng mắt trước khi cân rồi so với số thực, coi ước lượng bằng thước chỉ là mức tham khảo, quyết định cuối cùng về xuất chuồng thì dùng số trên cân.","Hiểu độ chính xác khác nhau giữa ước lượng bằng mắt, bằng thước đo và cân thực tế, và có thể hướng dẫn người mới cách dùng phù hợp và mẹo ước lượng bằng mắt."],"levels_id":["Membaca angka saat babi masih bergerak, memutuskan hanya dengan mata walau ada timbangan, dan memperlakukan taksiran seperti berat badan yang pasti.","Jika ada instruksi bisa menimbang, tetapi waktu membaca angka tidak tetap dan cara menempatkan pita ukur taksiran tidak pasti.","Jika ada instruksi, bisa membaca angka saat babi diam, dan bila tidak ada timbangan mengukur lingkar dada dan panjang badan untuk mendapat berat acuan.","Tanpa instruksi pun, menebak berat dengan mata sebelum menimbang lalu membandingkan dengan hasil timbang, menganggap taksiran pita ukur hanya acuan, dan memakai angka timbangan untuk keputusan akhir pengiriman.","Memahami perbedaan ketelitian taksiran visual, taksiran pita ukur, dan penimbangan nyata, dan bisa mengajari karyawan baru cara memilihnya serta trik meningkatkan taksiran visual."]},{"id":"ship-judge","name":"出荷適期の判定（休薬確認と選別）","kanten":"出荷候補の豚について投薬記録で休薬期間が完了しているかを確かめ、測った体重を出荷適体重110〜120kgなどの基準に当てはめて、出荷候補・軽量豚・重量豚に分けて上長に報告できるか。","levels":["投薬記録も体重の基準も確かめず、休薬期間中の豚や足りない豚も区別せず、自分だけで決めて出荷に回す。","指示があれば投薬記録を見て基準と比べるが、休薬期間の確認や軽量豚・重量豚の見落としが多く、報告も他者まかせ。","指示があれば投薬記録で休薬期間の完了を確かめて、完了していない豚を出荷候補から外し、110〜120kgを出荷候補、90kg未満（同日齢比較）を軽量豚、120kg超を重量豚に分け、結果を報告できる。","指示がなくても出荷候補の休薬期間を投薬記録でダブルチェックし、休薬期間が確認できない豚は出荷しない。契約や出荷先の基準も確認して選別し、軽量豚は別管理と原因確認、重量豚は優先出荷を上長へ提案し、足りない豚の出荷は相談する。","休薬期間中の豚を出荷すると法律違反になり農場全体の出荷停止につながること、軽すぎても重すぎても減額や脂肪過多になることを理解し、休薬確認と選別の考え方を新人に指導できる。"],"name_en":"Judging shipping readiness (withdrawal check and sorting)","name_vi":"Đánh giá thời điểm xuất chuồng (kiểm tra thời gian ngừng thuốc và phân loại)","name_id":"Penilaian waktu kirim (pemeriksaan masa henti obat dan pemilahan)","kanten_en":"Can they check the medication records to confirm that the withdrawal period has ended for pigs that are shipping candidates, apply the measured weight to criteria such as the shipping weight of 110-120 kg, sort pigs into shipping candidates, light pigs, and heavy pigs, and report to the supervisor?","kanten_vi":"Có kiểm tra ghi chép dùng thuốc để xác nhận thời gian ngừng thuốc đã kết thúc đối với lợn dự kiến xuất chuồng, áp cân nặng đã cân vào tiêu chuẩn như cân nặng xuất chuồng 110-120 kg, phân thành lợn dự kiến xuất, lợn nhẹ cân, lợn nặng cân và báo cáo cấp trên không.","kanten_id":"Apakah bisa memeriksa catatan pemberian obat untuk memastikan masa henti obat sudah selesai pada babi calon kirim, menerapkan berat yang diukur pada standar seperti berat kirim 110-120 kg, memilah menjadi calon kirim, babi ringan, dan babi berat, lalu melapor ke atasan.","levels_en":["Checks neither the medication records nor the weight criteria, does not distinguish pigs in their withdrawal period or under-weight pigs, and decides alone to send pigs to shipping.","With guidance, looks at the medication records and compares with the criteria, but often misses the withdrawal check and light or heavy pigs, and leaves reporting to others.","With guidance, confirms in the medication records that the withdrawal period has ended, removes pigs whose withdrawal period has not ended from the shipping candidates, sorts 110-120 kg as shipping candidates, under 90 kg (compared at the same age) as light pigs, and over 120 kg as heavy pigs, and can report the result.","Independently double-checks the withdrawal period of shipping candidates in the medication records, and does not ship any pig whose withdrawal period cannot be confirmed. Also confirms the contract or buyer's standard before sorting, proposes separate management and cause checks for light pigs and priority shipping for heavy pigs to the supervisor, and consults about shipping pigs that fall short.","Understands that shipping a pig in its withdrawal period is against the law and can lead to a shipping ban for the whole farm, and that pigs too light or too heavy lead to price penalties or excess fat, and can teach new staff how to think about the withdrawal check and sorting."],"levels_vi":["Không kiểm tra ghi chép dùng thuốc lẫn tiêu chuẩn cân nặng, không phân biệt lợn đang trong thời gian ngừng thuốc hay lợn thiếu cân, tự mình quyết định đưa đi xuất chuồng.","Nếu có chỉ dẫn thì xem ghi chép dùng thuốc và so với tiêu chuẩn, nhưng hay bỏ sót việc kiểm tra thời gian ngừng thuốc và lợn nhẹ cân, lợn nặng cân, việc báo cáo thì để người khác làm.","Nếu có chỉ dẫn thì xác nhận trong ghi chép dùng thuốc rằng thời gian ngừng thuốc đã kết thúc, loại lợn chưa hết thời gian ngừng thuốc ra khỏi danh sách dự kiến xuất, phân 110-120 kg là lợn dự kiến xuất, dưới 90 kg (so cùng ngày tuổi) là lợn nhẹ cân, trên 120 kg là lợn nặng cân, và báo cáo được kết quả.","Không cần chỉ dẫn cũng kiểm tra hai lần thời gian ngừng thuốc của lợn dự kiến xuất trong ghi chép dùng thuốc, lợn nào chưa xác nhận được thời gian ngừng thuốc thì không xuất. Cũng xác nhận tiêu chuẩn theo hợp đồng hoặc nơi nhận rồi mới phân loại, đề xuất với cấp trên quản lý riêng và tìm nguyên nhân với lợn nhẹ cân, ưu tiên xuất với lợn nặng cân, và trao đổi khi lợn thiếu cân mà muốn xuất.","Hiểu rằng xuất lợn đang trong thời gian ngừng thuốc là vi phạm pháp luật và có thể khiến cả trại bị đình chỉ xuất chuồng, lợn quá nhẹ hay quá nặng đều bị giảm giá hoặc nhiều mỡ, và có thể hướng dẫn người mới cách nghĩ về kiểm tra thời gian ngừng thuốc và phân loại."],"levels_id":["Tidak memeriksa catatan pemberian obat maupun standar berat, tidak membedakan babi yang masih dalam masa henti obat atau babi yang kurang berat, dan memutuskan sendiri untuk mengirim.","Jika ada instruksi, melihat catatan pemberian obat dan membandingkan dengan standar, tetapi sering terlewat memeriksa masa henti obat serta babi ringan atau berat, dan menyerahkan laporan ke orang lain.","Jika ada instruksi, memastikan di catatan pemberian obat bahwa masa henti obat sudah selesai, mengeluarkan babi yang masa henti obatnya belum selesai dari calon kirim, memilah 110-120 kg sebagai calon kirim, di bawah 90 kg (dibandingkan pada umur yang sama) sebagai babi ringan, dan di atas 120 kg sebagai babi berat, lalu bisa melaporkan hasilnya.","Tanpa instruksi pun memeriksa dua kali masa henti obat calon kirim di catatan pemberian obat, dan babi yang masa henti obatnya tidak bisa dipastikan tidak dikirim. Juga memastikan standar kontrak atau pembeli sebelum memilah, mengusulkan ke atasan pengelolaan terpisah dan pemeriksaan penyebab untuk babi ringan dan pengiriman prioritas untuk babi berat, dan berkonsultasi tentang pengiriman babi yang kurang berat.","Memahami bahwa mengirim babi dalam masa henti obat melanggar hukum dan bisa menyebabkan penghentian pengiriman seluruh peternakan, serta babi terlalu ringan atau terlalu berat menyebabkan potongan harga atau lemak berlebih, dan bisa mengajari karyawan baru cara berpikir tentang pemeriksaan masa henti obat dan pemilahan."]},{"id":"record-variance","name":"記録と群のばらつき・遅れ豚の確認","kanten":"体重を記録し、群内のばらつきを見て、小さい豚の原因（病気・寄生虫・いじめ・採食）を確かめられるか。","levels":["記録を残さず、群に小さい豚がいても気にせず、体重のばらつきも見ない。","指示があれば記録するが、記入漏れが多く、小さい豚がいても原因まで見ない。","指示があれば体重を記録し、群内のばらつきを確認して、極端に小さい豚を報告できる。","指示がなくても測定後すぐ記録し、小さい豚は病気・寄生虫・いじめ・エサに届いていないかを確かめ、跛行などの異常があれば報告する。","記録が増体の計算と出荷計画の土台であることを理解し、記入とばらつき確認の見方を新人に指導できる。"],"name_en":"Records, and checking group variation and slow-growing pigs","name_vi":"Ghi chép, kiểm tra độ chênh lệch trong đàn và lợn chậm lớn","name_id":"Pencatatan, serta pemeriksaan variasi kelompok dan babi yang lambat tumbuh","kanten_en":"Can they record weights, look at variation within the group, and check the cause of small pigs (disease, parasites, bullying, feed access)?","kanten_vi":"Có ghi cân nặng, xem độ chênh lệch trong đàn, và tìm nguyên nhân lợn nhỏ (bệnh, ký sinh trùng, bị ăn hiếp, ăn uống) không.","kanten_id":"Apakah mencatat berat badan, melihat variasi dalam kelompok, dan memeriksa penyebab babi yang kecil (penyakit, parasit, diganggu, akses pakan).","levels_en":["Keeps no records, ignores small pigs in the group, and does not look at weight variation.","With guidance, records, but often leaves entries incomplete, and does not look into the cause even when there are small pigs.","With guidance, records weights, checks variation within the group, and can report extremely small pigs.","Independently records right after weighing, checks whether small pigs are affected by disease, parasites, bullying, or not reaching feed, and reports abnormalities such as lameness.","Understands that records underpin gain calculations and shipping plans, and can teach new staff how to record and check variation."],"levels_vi":["Không ghi chép, trong đàn có lợn nhỏ cũng mặc kệ, không xem độ chênh lệch cân nặng.","Nếu có chỉ dẫn thì ghi chép, nhưng hay sót, có lợn nhỏ cũng không tìm đến nguyên nhân.","Nếu có chỉ dẫn thì ghi cân nặng, kiểm tra độ chênh lệch trong đàn, và báo cáo lợn nhỏ bất thường được.","Không cần chỉ dẫn cũng ghi chép ngay sau khi cân, kiểm tra lợn nhỏ có bị bệnh, ký sinh trùng, ăn hiếp hay không tới được thức ăn, nếu thấy bất thường như đi khập khiễng thì báo cáo.","Hiểu ghi chép là nền tảng của việc tính tăng trọng và kế hoạch xuất chuồng, và có thể hướng dẫn người mới cách ghi và xem độ chênh lệch."],"levels_id":["Tidak mencatat, tidak peduli walau ada babi kecil dalam kelompok, dan tidak melihat variasi berat badan.","Jika ada instruksi bisa mencatat, tetapi sering ada yang kurang, dan walau ada babi kecil tidak menelusuri penyebabnya.","Jika ada instruksi, bisa mencatat berat badan, memeriksa variasi dalam kelompok, dan melaporkan babi yang sangat kecil.","Tanpa instruksi pun, langsung mencatat setelah menimbang, memeriksa apakah babi kecil terkena penyakit, parasit, diganggu, atau tidak sampai ke pakan, dan melaporkan kelainan seperti pincang.","Memahami bahwa pencatatan adalah dasar perhitungan pertambahan berat dan rencana pengiriman, dan bisa mengajari karyawan baru cara mencatat dan memeriksa variasi."]}],"name_en":"Body Weight Measurement","purposeShort_en":"Weigh finishing pigs correctly to grasp the right time to ship and the variation in growth within the group","name_vi":"Cân đo thể trọng","purposeShort_vi":"Cân đúng cân nặng lợn thịt để nắm thời điểm xuất chuồng phù hợp và độ chênh lệch phát triển trong đàn","name_id":"Pengukuran berat badan","purposeShort_id":"Menimbang berat babi penggemukan dengan benar untuk mengetahui waktu kirim yang tepat dan variasi pertumbuhan dalam kelompok"},{"id":"ship-fin","category":"shipping","no":"","name":"出荷","purposeShort":"選別された肥育豚を、休薬を確かめたうえでストレスと事故なく積み込み、頭数と記録を残して出荷する","gyomu":"","name_en":"Shipping","purposeShort_en":"Load the selected finishing pigs after confirming the withdrawal period, without stress or accidents, and ship them with the head count and records kept","name_vi":"Xuất chuồng","purposeShort_vi":"Sau khi xác nhận thời gian ngừng thuốc, đưa lợn thịt đã chọn lên xe không căng thẳng, không tai nạn, rồi xuất chuồng và lưu số lượng cùng ghi chép","name_id":"Pengiriman","purposeShort_id":"Memuat babi penggemukan yang sudah dipilih setelah memastikan masa henti obat, tanpa stres dan kecelakaan, lalu mengirimnya dengan jumlah ekor dan catatan tersimpan","aspects":[{"id":"ship-criteria-plan","name":"出荷基準の確認と1週間前からの準備","kanten":"体重110〜120kg（契約による）・170〜180日齢（目安）・休薬確認の開始（7日前）・歩行可能で重い外傷がないという出荷基準を確かめ、7日前の候補選定から前日の最終選別までの段取りに沿って動けるか。","levels":["基準を確かめず見た目だけで出荷候補を決め、段取りも知らないまま前日や当日になって慌てる。","指示があれば基準を見て候補を挙げるが、日齢や外傷の確認が抜け、7日前・3日前などの段取りは他者まかせ。","指示があれば体重・日齢・健康状態・外傷を基準と照らして候補を選び、7日前の選定、3日前の最終確認、前日の最終選別の流れに沿って動ける。","指示がなくても基準を満たすか自分で確かめて候補を選び、段取りの各日に何をするか把握して、頭数の確定や業者連絡が必要な時期を上長に伝える。","基準が契約や出荷先で変わること、準備が遅れると出荷が乱れることを理解し、1週間前からの段取りを新人に指導できる。"],"name_en":"Checking the shipping criteria and preparing from one week before","name_vi":"Xác nhận tiêu chuẩn xuất chuồng và chuẩn bị từ một tuần trước","name_id":"Memeriksa standar kirim dan persiapan dari satu minggu sebelumnya","kanten_en":"Can they check the shipping criteria (110-120 kg depending on contract, about 170-180 days of age as a guide, withdrawal check started 7 days before, able to walk, no serious injury) and work along the schedule from selecting candidates 7 days before to the final sorting the day before?","kanten_vi":"Có xác nhận tiêu chuẩn xuất chuồng (110-120 kg tùy hợp đồng, khoảng 170-180 ngày tuổi (mang tính tham khảo), bắt đầu kiểm tra thời gian ngừng thuốc từ 7 ngày trước, đi lại được, không có vết thương nặng) và làm theo trình tự từ chọn lợn dự kiến 7 ngày trước đến phân loại lần cuối vào hôm trước không.","kanten_id":"Apakah memeriksa standar kirim (110-120 kg tergantung kontrak, umur sekitar 170-180 hari sebagai acuan, mulai memeriksa masa henti obat 7 hari sebelumnya, bisa berjalan, tanpa luka berat) dan bekerja sesuai urutan dari pemilihan calon 7 hari sebelumnya sampai pemilahan akhir sehari sebelumnya.","levels_en":["Picks shipping candidates by appearance without checking the criteria, does not know the schedule, and scrambles the day before or on the day.","With guidance, lists candidates by the criteria, but misses age and injury checks, and leaves the schedule (7 days, 3 days before, etc.) to others.","With guidance, selects candidates by comparing weight, age, health, and injuries with the criteria, and can follow the flow of selection 7 days before, final check 3 days before, and final sorting the day before.","Independently checks whether pigs meet the criteria and selects candidates, knows what to do on each day of the schedule, and tells the supervisor when the head count must be fixed and the shipping/transport company contacted.","Understands that the criteria change with the contract and destination and that late preparation disrupts shipping, and can teach new staff the schedule from one week before."],"levels_vi":["Không xác nhận tiêu chuẩn mà chỉ nhìn bề ngoài để chọn lợn dự kiến xuất, không biết trình tự nên đến hôm trước hoặc hôm xuất mới cuống lên.","Nếu có chỉ dẫn thì xem tiêu chuẩn và nêu lợn dự kiến, nhưng sót việc kiểm tra ngày tuổi và vết thương, trình tự như 7 ngày trước, 3 ngày trước thì phó mặc cho người khác.","Nếu có chỉ dẫn thì so cân nặng, ngày tuổi, sức khỏe, vết thương với tiêu chuẩn để chọn lợn dự kiến, và làm theo trình tự chọn 7 ngày trước, kiểm tra lần cuối 3 ngày trước, phân loại lần cuối hôm trước được.","Không cần chỉ dẫn cũng tự xác nhận lợn có đạt tiêu chuẩn để chọn, nắm rõ mỗi ngày trong trình tự phải làm gì, và báo cấp trên khi đến lúc cần chốt số lượng và liên hệ bên vận chuyển.","Hiểu tiêu chuẩn thay đổi theo hợp đồng và nơi nhận, chuẩn bị chậm thì xuất chuồng sẽ rối, và có thể hướng dẫn người mới trình tự từ một tuần trước."],"levels_id":["Memilih calon kirim hanya dari penampilan tanpa memeriksa standar, tidak tahu urutan kerja, dan panik pada hari sebelumnya atau hari H.","Jika ada instruksi, mencantumkan calon sesuai standar, tetapi terlewat memeriksa umur dan luka, dan urutan kerja (7 hari, 3 hari sebelumnya, dll.) diserahkan ke orang lain.","Jika ada instruksi, memilih calon dengan membandingkan berat, umur, kesehatan, dan luka dengan standar, dan bisa mengikuti alur pemilihan 7 hari sebelumnya, pemeriksaan akhir 3 hari sebelumnya, dan pemilahan akhir sehari sebelumnya.","Tanpa instruksi pun, memeriksa sendiri apakah babi memenuhi standar untuk memilih calon, tahu apa yang dikerjakan pada tiap hari, dan memberi tahu atasan saat jumlah ekor perlu ditetapkan dan pengangkut perlu dihubungi.","Memahami bahwa standar berubah menurut kontrak dan tujuan, serta persiapan yang terlambat mengacaukan pengiriman, dan bisa mengajari karyawan baru urutan kerja dari satu minggu sebelumnya."]},{"id":"ship-withdrawal-confirm","name":"投薬記録での休薬完了の確認と逆算","kanten":"出荷予定日から逆算し、注射・飼料添加・飲水投与を含む投薬記録（獣医師の指示書がある場合はその休薬期間）で全対象豚の休薬期間の完了を確かめ、出荷当日朝に2人でダブルチェックし、確認できない豚は出荷せず上長に確認できるか。","levels":["投薬記録を見ずに出荷する豚を決め、休薬期間中の豚が混ざっていても気づかない。","指示があれば投薬記録を見るが、一部の豚や薬剤の確認が抜け、確認は1人だけで済ませる。","指示があれば出荷7日前から確認を始めて出荷予定日から休薬期間を逆算し、投薬記録で全対象豚の休薬完了を確かめ、当日朝にもう一度確認できる。","指示がなくても出荷予定の豚に投薬が必要になったらその場で休薬終了日を出して出荷予定日と比べ、かかる場合は出荷日の変更を上長に相談し、出荷予定日と休薬終了日を豚房に表示し、当日朝は2人でダブルチェックして、記録を正本に、休薬の完了が確認できない豚は出荷せず、その場で上長に確認して出荷から外す。","休薬期間中の出荷が法律違反で農場全体の出荷停止につながることを理解し、逆算カレンダーの使い方とダブルチェックの方法を新人に指導できる。"],"name_en":"Confirming completed withdrawal periods in medication records, and counting back","name_vi":"Xác nhận đã hết thời gian ngừng thuốc trong ghi chép dùng thuốc và tính ngược","name_id":"Memastikan masa henti obat selesai di catatan pemberian obat, dan menghitung mundur","kanten_en":"Can they count back from the planned shipping date, confirm that the withdrawal period has ended for every target pig using medication records that include injections, feed additives and drinking-water medication (and the withdrawal period on the vet's instruction sheet, if there is one), double-check with two people on the morning of shipping, and not ship any pig that cannot be confirmed but ask the supervisor?","kanten_vi":"Có tính ngược từ ngày dự kiến xuất, xác nhận mọi con lợn dự kiến xuất đã hết thời gian ngừng thuốc dựa trên ghi chép dùng thuốc gồm cả tiêm, thuốc trộn thức ăn và thuốc trong nước uống (nếu có chỉ định của bác sĩ thú y thì theo thời gian ngừng thuốc đó), hai người cùng kiểm tra vào sáng hôm xuất, con nào không xác nhận được thì không xuất mà hỏi cấp trên không.","kanten_id":"Apakah menghitung mundur dari tanggal kirim yang direncanakan, memastikan masa henti obat semua babi sasaran sudah selesai berdasarkan catatan pemberian obat termasuk suntikan, aditif pakan, dan obat lewat air minum (jika ada surat instruksi dokter hewan, sesuai masa henti obat di dalamnya), memeriksa ganda oleh dua orang pada pagi hari kirim, dan tidak mengirim babi yang tidak bisa dipastikan melainkan bertanya ke atasan.","levels_en":["Decides which pigs to ship without looking at the medication records, and does not notice even if a pig in its withdrawal period is mixed in.","With guidance, looks at the medication records, but misses some pigs or drugs, and finishes the check with only one person.","With guidance, starts checking 7 days before shipping and counts back the withdrawal period from the planned shipping date, confirms in the medication records that it has ended for all target pigs, and checks again on the morning of shipping.","Independently, when a pig scheduled for shipping needs medication, works out the withdrawal end date on the spot, compares it with the planned shipping date, asks the supervisor to change the shipping date if it overlaps, displays the shipping date and withdrawal end date at the pen, double-checks with two people on the morning of shipping using the records as the source of truth, does not ship any pig whose completed withdrawal cannot be confirmed, and asks the supervisor on the spot and removes it from shipping.","Understands that shipping a pig in its withdrawal period is against the law and can lead to a shipping ban for the whole farm, and can teach new staff how to use the count-back calendar and how to double-check."],"levels_vi":["Quyết định lợn xuất mà không xem ghi chép dùng thuốc, lợn đang trong thời gian ngừng thuốc lẫn vào cũng không nhận ra.","Nếu có chỉ dẫn thì xem ghi chép dùng thuốc, nhưng sót một số con hoặc loại thuốc, và chỉ một người kiểm tra là xong.","Nếu có chỉ dẫn thì bắt đầu kiểm tra từ 7 ngày trước ngày xuất và tính ngược thời gian ngừng thuốc từ ngày dự kiến xuất, xác nhận trong ghi chép dùng thuốc rằng mọi con dự kiến xuất đã hết thời gian ngừng thuốc, và kiểm tra lại vào sáng hôm xuất được.","Không cần chỉ dẫn cũng, khi con dự kiến xuất cần dùng thuốc thì tính ngay ngày hết ngừng thuốc, so với ngày dự kiến xuất, nếu trùng thì xin cấp trên đổi ngày xuất, ghi ngày xuất và ngày hết ngừng thuốc ở ô chuồng, sáng hôm xuất hai người cùng kiểm tra lại, lấy ghi chép làm căn cứ chính, con nào không xác nhận được đã hết thời gian ngừng thuốc thì không xuất, hỏi cấp trên ngay tại chỗ và loại khỏi danh sách xuất.","Hiểu xuất lợn đang trong thời gian ngừng thuốc là vi phạm pháp luật và có thể khiến cả trại bị đình chỉ xuất chuồng, và có thể hướng dẫn người mới cách dùng lịch tính ngược và cách kiểm tra hai lần."],"levels_id":["Menentukan babi yang dikirim tanpa melihat catatan pemberian obat, dan tidak sadar walau ada babi dalam masa henti obat yang tercampur.","Jika ada instruksi, melihat catatan pemberian obat, tetapi sebagian babi atau obat terlewat, dan pemeriksaan selesai hanya dengan satu orang.","Jika ada instruksi, mulai memeriksa 7 hari sebelum kirim dan menghitung mundur masa henti obat dari tanggal kirim yang direncanakan, memastikan di catatan pemberian obat bahwa masa henti obat semua babi sasaran sudah selesai, dan memeriksa lagi pada pagi hari kirim.","Tanpa instruksi pun, saat babi yang akan dikirim perlu diobati, langsung menghitung tanggal berakhirnya masa henti obat, membandingkannya dengan tanggal kirim, meminta atasan mengubah tanggal kirim jika bertabrakan, menampilkan tanggal kirim dan tanggal berakhirnya masa henti obat di petak kandang, memeriksa ganda oleh dua orang pada pagi hari kirim dengan catatan sebagai dasar, tidak mengirim babi yang selesainya masa henti obat tidak bisa dipastikan, bertanya ke atasan di tempat, dan mengeluarkannya dari pengiriman.","Memahami bahwa mengirim babi dalam masa henti obat melanggar hukum dan bisa menyebabkan penghentian pengiriman seluruh peternakan, dan bisa mengajari karyawan baru cara memakai kalender hitung mundur dan cara memeriksa dua kali."]},{"id":"ship-eve-prep","name":"前日の準備（絶食・マーキング・通路）と当日朝の歩様確認","kanten":"前日に最終選別した豚へ見分けやすくマーキングし、前日夕方から給餌を止め（当日朝も与えず）、水は止めず、出荷通路を清掃して障害物を除き、当日朝に歩けない豚や具合の悪い豚を外せるか。","levels":["マーキングも通路の準備もせず、水まで止めてしまい、歩けない豚も出荷に回す。","指示があれば準備するが、マーキングが不明瞭だったり通路の障害物を見落としたりし、歩様の確認は他者まかせ。","指示があれば前日に対象豚へはっきりマーキングし、前日夕方から給餌を止め（当日朝も与えず）水は出し続け、通路を清掃し、当日朝に歩様・呼吸・外観を確認できる。","指示がなくても水を止めないことを確かめ、通路を自分で見て回って障害物を除き、当日朝に歩けない豚や明らかに具合が悪い豚を出荷から外して上長に伝える。","絶食の目的と、脱水が肉質低下と動物福祉の問題になることを理解し、前日の準備と当日朝の確認を新人に指導できる。"],"name_en":"Preparation the day before (fasting, marking, passage) and gait check on the morning","name_vi":"Chuẩn bị hôm trước (nhịn ăn, đánh dấu, lối đi) và kiểm tra dáng đi sáng hôm xuất","name_id":"Persiapan hari sebelumnya (puasa, penandaan, lorong) dan pemeriksaan cara jalan pada pagi hari","kanten_en":"Can they mark the pigs finally selected the day before so they are easy to tell apart, withhold feed from the evening before (including the morning of shipping) while keeping water available, clean the shipping passage and remove obstacles, and on the morning remove pigs that cannot walk or are unwell?","kanten_vi":"Có đánh dấu dễ nhận biết lên lợn đã phân loại lần cuối hôm trước, ngừng cho ăn từ chiều hôm trước (sáng hôm xuất cũng không cho ăn) mà không ngừng nước, dọn lối đi xuất chuồng và bỏ vật cản, sáng hôm xuất loại được lợn không đi được hoặc không khỏe không.","kanten_id":"Apakah menandai babi hasil pemilahan akhir sehari sebelumnya agar mudah dibedakan, menghentikan pakan mulai sore hari sebelumnya (pagi hari kirim juga tidak diberi) tanpa menghentikan air, membersihkan lorong pengiriman dan menyingkirkan penghalang, serta pada pagi hari mengeluarkan babi yang tidak bisa berjalan atau tidak sehat.","levels_en":["Does no marking or passage preparation, even stops the water, and sends pigs that cannot walk to shipping.","With guidance, prepares, but marks unclearly or overlooks obstacles in the passage, and leaves the gait check to others.","With guidance, marks the target pigs clearly the day before, withholds feed from the evening before (none on the morning either) while keeping water running, cleans the passage, and can check gait, breathing, and appearance on the morning.","Independently makes sure the water is not stopped, walks the passage to remove obstacles, and on the morning removes pigs that cannot walk or are clearly unwell from shipping and tells the supervisor.","Understands the purpose of fasting and that dehydration causes lower meat quality and an animal welfare problem, and can teach new staff the preparation the day before and the check on the morning."],"levels_vi":["Không đánh dấu, không chuẩn bị lối đi, còn cắt cả nước, lợn không đi được vẫn đưa đi xuất.","Nếu có chỉ dẫn thì chuẩn bị, nhưng đánh dấu không rõ hoặc sót vật cản ở lối đi, việc kiểm tra dáng đi thì phó mặc cho người khác.","Nếu có chỉ dẫn thì hôm trước đánh dấu rõ lên lợn xuất, ngừng cho ăn từ chiều hôm trước (sáng hôm xuất cũng không cho ăn) nhưng vẫn cho uống nước, dọn lối đi, và sáng hôm xuất kiểm tra được dáng đi, hơi thở, bề ngoài.","Không cần chỉ dẫn cũng đảm bảo không cắt nước, tự đi xem lối đi để dọn vật cản, và sáng hôm xuất loại khỏi danh sách xuất lợn không đi được hoặc rõ ràng không khỏe rồi báo cấp trên.","Hiểu mục đích của việc nhịn ăn, và mất nước làm giảm chất lượng thịt và là vấn đề phúc lợi động vật, và có thể hướng dẫn người mới việc chuẩn bị hôm trước và kiểm tra sáng hôm xuất."],"levels_id":["Tidak menandai dan tidak menyiapkan lorong, bahkan menghentikan air, dan mengirim babi yang tidak bisa berjalan.","Jika ada instruksi, menyiapkan, tetapi penandaan tidak jelas atau penghalang di lorong terlewat, dan pemeriksaan cara jalan diserahkan ke orang lain.","Jika ada instruksi, menandai babi sasaran dengan jelas sehari sebelumnya, menghentikan pakan mulai sore hari sebelumnya (pagi hari kirim juga tidak diberi) tetapi air tetap ada, membersihkan lorong, dan memeriksa cara jalan, napas, dan penampilan pada pagi hari.","Tanpa instruksi pun, memastikan air tidak dihentikan, berjalan memeriksa lorong untuk menyingkirkan penghalang, dan pada pagi hari mengeluarkan babi yang tidak bisa berjalan atau jelas tidak sehat dari pengiriman lalu memberi tahu atasan.","Memahami tujuan puasa serta bahwa dehidrasi menurunkan kualitas daging dan menjadi masalah kesejahteraan hewan, dan bisa mengajari karyawan baru persiapan hari sebelumnya dan pemeriksaan pada pagi hari."]},{"id":"ship-calm-loading","name":"静かな誘導と積み込み（肉質と事故の防止）","kanten":"追い板で豚の視界を限りながら静かにゆっくり誘導し、1回に3〜5頭ずつ、滑り止めを確かめたスロープで転倒や挟まれを防いで積み込め、夏は早朝、冬は凍結に気を配れるか。","levels":["追い回し、叩き、多頭数を一度に押し込んで、転倒や挟まれが起きても気にしない。","指示があれば追い板で誘導するが、焦ると追い回したり多頭数を一度に動かしたりし、スロープの滑りやすさを見落とす。","指示があれば追い板で静かに誘導し、1回に3〜5頭ずつ、滑り止めを確かめたスロープから転倒や挟まれに注意して積み込める。","指示がなくても豚のペースに合わせ、興奮した豚がいれば待ち、電気ショッカーは最小限にとどめる。夏は早朝・車内の換気、冬は凍結箇所の滑り止めまで気を配る。","追い回しや暑熱のストレスがPSE肉、長いストレスがDFD肉につながることを理解し、静かな積み込みのコツを新人に指導できる。"],"name_en":"Calm guiding and loading (protecting meat quality and preventing accidents)","name_vi":"Lùa nhẹ nhàng và lên xe (giữ chất lượng thịt, phòng tai nạn)","name_id":"Penggiringan dan pemuatan yang tenang (menjaga kualitas daging dan mencegah kecelakaan)","kanten_en":"Can they guide quietly and slowly with a pig board while limiting the pigs' view, load 3-5 pigs at a time on a ramp whose non-slip surface they have checked, prevent falls and crushing, and attend to early-morning shipping in summer and freezing in winter?","kanten_vi":"Có lùa nhẹ nhàng, chậm rãi bằng tấm chắn để hạn chế tầm nhìn của lợn, mỗi lần 3-5 con, lên xe qua dốc đã kiểm tra chống trượt, phòng ngã và bị kẹp, và chú ý xuất sáng sớm vào mùa hè, chú ý đóng băng vào mùa đông không.","kanten_id":"Apakah menggiring dengan tenang dan pelan memakai papan penggiring sambil membatasi pandangan babi, memuat 3-5 ekor sekali jalan dari ramp yang anti-selip sudah diperiksa, mencegah jatuh dan terjepit, serta memperhatikan pengiriman pagi hari di musim panas dan es di musim dingin.","levels_en":["Chases, hits, and pushes many pigs at once, and does not care even when pigs fall or get caught.","With guidance, guides with the pig board, but when rushed chases or moves many pigs at once and overlooks slippery ramps.","With guidance, guides quietly with the pig board and can load 3-5 pigs at a time from a ramp whose non-slip surface is checked, watching for falls and crushing.","Independently matches the pigs' pace, waits if a pig is excited, and keeps the use of an electric prod to a minimum. Also attends to early-morning shipping and ventilation of the truck in summer and non-slip treatment of icy spots in winter.","Understands that chasing and heat stress lead to PSE meat and prolonged stress to DFD meat, and can teach new staff tips for quiet loading."],"levels_vi":["Đuổi, đánh, dồn nhiều con cùng lúc, lợn ngã hay bị kẹp cũng mặc kệ.","Nếu có chỉ dẫn thì lùa bằng tấm chắn, nhưng khi vội thì đuổi hoặc cho nhiều con đi cùng lúc, bỏ sót dốc trơn trượt.","Nếu có chỉ dẫn thì lùa nhẹ nhàng bằng tấm chắn, mỗi lần 3-5 con, lên xe qua dốc đã kiểm tra chống trượt, chú ý lợn ngã và bị kẹp được.","Không cần chỉ dẫn cũng theo nhịp của lợn, con nào bị kích động thì chờ, hạn chế dùng gậy chích điện ở mức tối thiểu. Mùa hè chú ý xuất sáng sớm và thông gió trên xe, mùa đông chú ý rải chống trượt chỗ đóng băng.","Hiểu việc đuổi và nắng nóng gây căng thẳng dẫn đến thịt PSE, căng thẳng kéo dài dẫn đến thịt DFD, và có thể hướng dẫn người mới mẹo lên xe nhẹ nhàng."],"levels_id":["Mengejar, memukul, dan mendorong banyak babi sekaligus, tidak peduli walau babi jatuh atau terjepit.","Jika ada instruksi, menggiring dengan papan penggiring, tetapi saat terburu-buru mengejar atau menggerakkan banyak ekor sekaligus dan melewatkan ramp yang licin.","Jika ada instruksi, menggiring dengan tenang memakai papan penggiring dan bisa memuat 3-5 ekor sekali jalan dari ramp yang anti-selipnya sudah diperiksa, sambil mengawasi babi jatuh dan terjepit.","Tanpa instruksi pun, menyesuaikan dengan kecepatan babi, menunggu jika ada babi yang gelisah, dan memakai alat kejut listrik seminimal mungkin. Juga memperhatikan pengiriman pagi hari dan ventilasi truk di musim panas serta penahan selip di bagian beku di musim dingin.","Memahami bahwa dikejar dan stres panas menyebabkan daging PSE, serta stres yang berkepanjangan menyebabkan daging DFD, dan bisa mengajari karyawan baru trik pemuatan yang tenang."]},{"id":"ship-count-record","name":"頭数の照合・出荷伝票と出荷記録・残留個体の確認","kanten":"積み込んだ頭数を数えて出荷伝票と照合し、頭数・農場名・日付を記入し、出荷先・オス・メスの内訳・体重・運搬車の情報・体調に不安のある個体を出荷記録に残し、出荷後の豚房に残った豚がいないか確かめられる、出荷後に積み込み場所と通路を清掃・消毒できるか。","levels":["頭数を数えず伝票も記録も残さず、出荷後の豚房も見ないまま作業を終える。","指示があれば数えて記入するが、伝票との不一致や記録項目の抜けが多く、出荷後の豚房の確認を忘れる。","指示があれば積み込んだ頭数を伝票と照合し、頭数・農場名・日付を記入して出荷記録に必要な項目（日付・出荷先・頭数・体重・運搬業者と車両番号）を残し、出荷後に豚房に残った豚がいないか確かめ、積み込み場所と通路を清掃・消毒できる。","指示がなくても不一致はその場で原因を確かめてから出発させ、オス・メスの内訳や体調に不安のある個体の特記事項まで記録し、日報にも記入して積み込み場所の外縁部にトラックを留め農場の奥まで入れないよう気を配り、残留個体なしを自分で確認する。","投薬記録と出荷記録の両方がそろって休薬の証拠になり、残留個体がいると頭数が合わなくなることを理解し、照合と記録の書き方を新人に指導できる。"],"name_en":"Matching head counts, shipping slip and shipping record, and checking for pigs left behind","name_vi":"Đối chiếu số lượng, phiếu xuất và hồ sơ xuất chuồng, kiểm tra lợn còn sót","name_id":"Pencocokan jumlah ekor, surat pengiriman dan catatan pengiriman, serta pemeriksaan babi yang tertinggal","kanten_en":"Can they count the pigs loaded and match them with the shipping slip, fill in the head count, farm name, and date, record the destination, male/female breakdown, weights, transport company and vehicle number, and any pig with a health concern in the shipping record, and check that no pig is left in the pen after shipping, and clean and disinfect the loading area and passage after shipping?","kanten_vi":"Có đếm số lợn đã lên xe và đối chiếu với phiếu xuất, ghi số lượng, tên trại, ngày, ghi vào hồ sơ xuất chuồng nơi nhận, số đực cái, cân nặng, thông tin xe vận chuyển và con nào có điều lo ngại về sức khỏe, và kiểm tra sau khi xuất không còn lợn sót trong ô không, và vệ sinh khử trùng nơi lên xe và lối đi sau khi xuất không.","kanten_id":"Apakah menghitung babi yang dimuat dan mencocokkannya dengan surat pengiriman, mengisi jumlah ekor, nama peternakan, dan tanggal, mencatat tujuan, rincian jantan dan betina, berat, perusahaan dan nomor kendaraan pengangkut, serta babi yang dikhawatirkan kesehatannya di catatan pengiriman, dan memeriksa tidak ada babi yang tertinggal di kandang setelah pengiriman, serta membersihkan dan mendisinfeksi tempat pemuatan dan lorong setelah pengiriman.","levels_en":["Does not count, leaves no slip or record, and finishes the work without looking at the pens after shipping.","With guidance, counts and fills in, but often has mismatches with the slip or missing record items, and forgets to check the pens after shipping.","With guidance, matches the loaded head count with the slip, fills in head count, farm name, and date, leaves the required items (date, destination, head count, weight, transport company and vehicle number) in the shipping record, and can check that no pig is left in the pens after shipping, and clean and disinfect the loading area and passage.","Independently checks the cause of a mismatch on the spot before letting the truck leave, records the male/female breakdown and notes on pigs with health concerns, enters it in the daily report, and keeps the truck at the outer loading area and out of the farm interior, and confirms by themselves that no pig is left behind.","Understands that the medication record and the shipping record together are the evidence for withdrawal, and and that a pig left behind throws the head count off, and can teach new staff how to match and record."],"levels_vi":["Không đếm, không để lại phiếu hay ghi chép, và kết thúc công việc mà không xem lại các ô sau khi xuất.","Nếu có chỉ dẫn thì đếm và ghi, nhưng hay lệch với phiếu hoặc thiếu mục ghi chép, và quên kiểm tra ô sau khi xuất.","Nếu có chỉ dẫn thì đối chiếu số lợn lên xe với phiếu xuất, ghi số lượng, tên trại, ngày, để lại các mục cần thiết (ngày, nơi nhận, số lượng, cân nặng, bên vận chuyển và biển số xe) trong hồ sơ xuất chuồng, và kiểm tra sau khi xuất không còn lợn sót trong ô, và vệ sinh khử trùng nơi lên xe và lối đi được.","Không cần chỉ dẫn cũng tìm nguyên nhân ngay tại chỗ khi số liệu lệch rồi mới cho xe đi, ghi cả số đực cái và ghi chú về con có điều lo ngại sức khỏe, ghi cả vào nhật ký, và giữ xe ở khu vực lên xe ngoài rìa trại, không cho vào sâu trong trại, và tự xác nhận không còn lợn sót.","Hiểu ghi chép dùng thuốc cùng hồ sơ xuất chuồng là bằng chứng về thời gian ngừng thuốc, và lợn sót thì số lượng sẽ không khớp, và có thể hướng dẫn người mới cách đối chiếu và ghi chép."],"levels_id":["Tidak menghitung, tidak meninggalkan surat maupun catatan, dan mengakhiri pekerjaan tanpa melihat kandang setelah pengiriman.","Jika ada instruksi, menghitung dan mengisi, tetapi sering tidak cocok dengan surat atau ada item catatan yang kurang, dan lupa memeriksa kandang setelah pengiriman.","Jika ada instruksi, mencocokkan jumlah ekor yang dimuat dengan surat pengiriman, mengisi jumlah ekor, nama peternakan, dan tanggal, meninggalkan item yang diperlukan (tanggal, tujuan, jumlah ekor, berat, perusahaan dan nomor kendaraan pengangkut) di catatan pengiriman, dan bisa memeriksa tidak ada babi yang tertinggal di kandang setelah pengiriman, serta membersihkan dan mendisinfeksi tempat pemuatan dan lorong.","Tanpa instruksi pun, memeriksa penyebab ketidakcocokan di tempat sebelum truk berangkat, mencatat rincian jantan dan betina serta catatan khusus babi yang dikhawatirkan kesehatannya, mengisi laporan harian, dan menjaga truk tetap di tempat pemuatan bagian luar dan tidak masuk ke dalam peternakan, serta memastikan sendiri tidak ada babi yang tertinggal.","Memahami bahwa catatan pemberian obat dan catatan pengiriman bersama-sama menjadi bukti masa henti obat, dan babi yang tertinggal membuat jumlah tidak cocok, dan bisa mengajari karyawan baru cara mencocokkan dan mencatat."]}]}],"presets":[{"id":"farrowing-house","name":"分娩舎","name_en":"Farrowing barn","name_vi":"Chuồng đẻ","name_id":"Kandang beranak","works":["feeding-daily","nursing-feed","castration","sow-vaccine","farrow-assist","cross-foster","disinfect"]},{"id":"stall-house","name":"ストール舎","name_en":"Stall barn","name_vi":"Chuồng cá thể","name_id":"Kandang stall","works":["feeding-daily","additive","gilt-intake","preg-check","pms","ai-insem"]},{"id":"nursery-house","name":"子豚舎","name_en":"Nursery barn","name_vi":"Chuồng cai sữa","name_id":"Kandang sapihan","works":["fan-clean","five-s","treatment","carcass","washing","lime"]},{"id":"finishing-house","name":"肥育舎","name_en":"Finishing barn","name_vi":"Chuồng vỗ béo","name_id":"Kandang penggemukan","works":["feeding-daily","feed-adjust-fin","additive","disinfect","daily-report","dung-removal","lime","body-measure"]}]};
